def calcola_costo_turni(prezzi, mw_f1, mw_f2, mw_f3):
    """Costo di fornitura scomposto per turno di produzione industriale.

    Molti clienti industriali lavorano su 3 turni da 8 ore: Notte 22-06,
    Mattina 06-14, Pomeriggio 14-22. Il prezzo spot (e quindi il costo di
    fornitura a prezzo variabile) cambia molto tra notte e giorno: questo
    tab dice all'energy manager quanto costa far girare ciascun turno e
    quale turno e' il piu' caro in EUR/MWh — informazione operativa per
    spostare produzione, manutenzione o fermi sui turni piu' economici.

    Il profilo di carico dell'app e' piatto per fascia (MW costanti in
    F1/F2/F3): il carico orario e' il MW della fascia di ciascuna ora (via
    fascia_oraria). Il costo orario e' prezzo x carico; ogni ora cade in
    esattamente un turno.

    Metodo (tutto deterministico a parita' di input):
    - turno(h): 22,23,0-5 -> "Notte (22-06)"; 6-13 -> "Mattina (06-14)";
      14-21 -> "Pomeriggio (14-22)";
    - per turno: ore, MWh = somma carico, costo = somma(prezzo x carico),
      prezzo medio = costo / MWh (None se MWh = 0), % costo = costo /
      costo totale x 100 (0.0 se costo totale = 0);
    - KPI: turno piu' costoso (max costo), turno piu' caro in EUR/MWh
      (max prezzo medio tra i turni con MWh > 0), quota % del turno di
      punta sul totale;
    - df_mesi: per mese di calendario, costo EUR per turno (somme
      esatte: la somma su turni e mesi = costo totale).

    NaN-safe: serie vuota, MW tutti a zero o non validi -> statistiche
    neutrali con DataFrame dalle colonne giuste.

    Ritorna dict con 'ore', 'mwh_totale', 'costo_totale', 'turno_piu_costoso',
    'turno_piu_caro_mwh', 'pct_turno_punta' (None se costo_totale = 0),
    'df_turni' ('Turno', 'Ore', 'MWh', 'Costo (€)', 'Prezzo medio (€/MWh)',
    '% costo'), 'df_mesi' ('Mese', 'Notte (€)', 'Mattina (€)',
    'Pomeriggio (€)').
    """
    turni = ["Notte (22-06)", "Mattina (06-14)", "Pomeriggio (14-22)"]
    cols_t = ["Turno", "Ore", "MWh", "Costo (€)", "Prezzo medio (€/MWh)", "% costo"]
    cols_m = ["Mese", "Notte (€)", "Mattina (€)", "Pomeriggio (€)"]

    def turno_di(h):
        if h >= 22 or h < 6:
            return "Notte (22-06)"
        if h < 14:
            return "Mattina (06-14)"
        return "Pomeriggio (14-22)"

    vuoto = {"ore": 0, "mwh_totale": 0.0, "costo_totale": 0.0,
             "turno_piu_costoso": None, "turno_piu_caro_mwh": None,
             "pct_turno_punta": None,
             "df_turni": pd.DataFrame([{"Turno": t, "Ore": 0, "MWh": 0.0,
                                        "Costo (€)": 0.0,
                                        "Prezzo medio (€/MWh)": None,
                                        "% costo": 0.0} for t in turni]),
             "df_mesi": pd.DataFrame(columns=cols_m)}
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0:
        return dict(vuoto)
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
    except (TypeError, ValueError):
        mws = [0.0, 0.0, 0.0]
    out = dict(vuoto)
    out["ore"] = len(p)
    try:
        ore_turno = pd.Series([turno_di(ts.hour) for ts in p.index],
                              index=p.index, dtype="string")
        carico = p.index.map(fascia_oraria).map(
            {"F1": mws[0], "F2": mws[1], "F3": mws[2]}).astype(float)
    except Exception:
        return out
    costo_orario = (p.values * carico.values)
    df_h = pd.DataFrame({"turno": ore_turno.values, "mwh": carico.values,
                         "costo": costo_orario})
    g = df_h.groupby("turno", observed=True)
    righe = []
    costi = {}
    for t in turni:
        if t in g.groups:
            gg = g.get_group(t)
            ore_t = int(len(gg))
            mwh_t = float(gg["mwh"].sum())
            costo_t = float(gg["costo"].sum())
        else:
            ore_t, mwh_t, costo_t = 0, 0.0, 0.0
        pm = (costo_t / mwh_t) if mwh_t > 0 else None
        costi[t] = costo_t
        righe.append({"Turno": t, "Ore": ore_t, "MWh": round(mwh_t, 3),
                      "Costo (€)": round(costo_t, 2),
                      "Prezzo medio (€/MWh)": (round(pm, 2) if pm is not None else None),
                      "% costo": 0.0})
    costo_tot = float(df_h["costo"].sum())
    mwh_tot = float(df_h["mwh"].sum())
    for rg in righe:
        rg["% costo"] = round(rg["Costo (€)"] / costo_tot * 100.0, 1) if costo_tot > 0 else 0.0
    # Chiudi l'arrotondamento a 1 decimale: la somma deve fare 100.0
    if costo_tot > 0:
        residuo = round(100.0 - sum(rg["% costo"] for rg in righe), 1)
        if abs(residuo) > 0.0:
            tmax_r = max(turni, key=lambda t: costi[t])
            for rg in righe:
                if rg["Turno"] == tmax_r:
                    rg["% costo"] = round(rg["% costo"] + residuo, 1)
                    break
    out["df_turni"] = pd.DataFrame(righe, columns=cols_t)
    out["mwh_totale"] = round(mwh_tot, 3)
    out["costo_totale"] = round(costo_tot, 2)
    if costo_tot > 0:
        tmax = max(turni, key=lambda t: costi[t])
        out["turno_piu_costoso"] = tmax
        out["pct_turno_punta"] = round(costi[tmax] / costo_tot * 100.0, 1)
        pm_vals = {r["Turno"]: r["Prezzo medio (€/MWh)"] for r in righe
                   if r["Prezzo medio (€/MWh)"] is not None}
        out["turno_piu_caro_mwh"] = max(pm_vals, key=pm_vals.get) if pm_vals else None
    # Dettaglio mensile: costo per turno, mese di calendario
    try:
        df_h["mese"] = pd.PeriodIndex(p.index, freq="M").astype(str)
        dm = (df_h.groupby(["mese", "turno"], observed=True)["costo"]
              .sum().unstack(fill_value=0.0))
        for t in turni:
            if t not in dm.columns:
                dm[t] = 0.0
        dm = dm[turni].reset_index()
        dm.columns = ["Mese", "Notte (€)", "Mattina (€)", "Pomeriggio (€)"]
        for c in ["Notte (€)", "Mattina (€)", "Pomeriggio (€)"]:
            dm[c] = dm[c].round(2)
        out["df_mesi"] = dm.sort_values("Mese").reset_index(drop=True)
    except Exception:
        pass
    return out

def calcola_backtest_ordini_limite(prezzi, mw_f1, mw_f2, mw_f3, soglie):
    """Backtest deterministico di ordini limite di acquisto sul mercato spot.

    Domanda operativa dell'energy analyst: "se automatizzassi l'acquisto con
    un ordine limite a X euro/MWh (algo 'buy-the-dip' per carichi flessibili,
    ricariche, pompaggi, batch), quante ore si riempirebbero, a che prezzo
    medio comprerei davvero e quanto risparmierei rispetto a comprare tutto
    al prezzo medio di periodo?" — l'ordine si riempie in OGNI ora con
    prezzo <= soglia (fill deterministico sullo storico; nessuno slippage
    modellato, i volumi orari del profilo sono piccoli rispetto al mercato).

    Diverso dal tab Finestre di acquisto (tab23: cerca la finestra CONTIGUA
    di N ore piu' economica di ogni giorno — timing, non prezzo) e dal tab
    Top ore di costo (tab39: le ore piu' care GIA' accadute, non una
    strategia eseguibile in avanti).

    Per ogni soglia S:
    - ore riempite = ore con prezzo <= S; quota ore = riempite / ore totali;
    - MWh acquistabili = somma dei MW di fascia nelle ore riempite;
    - prezzo medio di riempimento = media dei prezzi nelle ore riempite
      (il prezzo a cui compreresti davvero con quel limite: sempre < S);
    - risparmio vs media = (prezzo medio periodo - prezzo medio
      riempimento) x MWh riempiti (positivo = risparmi, negativo = paghi
      di piu' — puo' succedere solo se il profilo pesa sulle ore care).

    Sanitizzazione: ore con prezzo NaN scartate, timestamp duplicati ->
    primo tenuto, serie ordinata per tempo; ore in Europe/Zurich per la
    fascia corretta; soglie non numeriche/non finite scartate, duplicate
    rimosse, ordinate in modo crescente. Serie con meno di 24 ore, profilo
    nullo o nessuna soglia valida -> 'ok' False.

    Ritorna dict con 'ok', 'prezzo_medio_periodo', 'mwh_totale',
    'tot_ore', 'df_soglie' ('Soglia (euro/MWh)' / 'Ore riempite' /
    'Quota ore %' / 'MWh acquistabili' / 'Quota MWh %' / 'Prezzo medio
    riempimento (euro/MWh)' / 'Risparmio vs media (euro)'), 'df_mesi'
    ('Mese' + una colonna 'MWh @ <soglia>' per soglia testata), 'df_ore'
    ('Data' / 'Ora' / 'Prezzo (euro/MWh)' / 'Fascia' / 'MW' / 'MWh') con
    tutte le ore del periodo: la UI filtra per la soglia selezionata."""
    COLS_S = ["Soglia (euro/MWh)", "Ore riempite", "Quota ore %",
              "MWh acquistabili", "Quota MWh %",
              "Prezzo medio riempimento (euro/MWh)",
              "Risparmio vs media (euro)"]
    COLS_O = ["Data", "Ora", "Prezzo (euro/MWh)", "Fascia", "MW", "MWh"]

    def _vuoto():
        return {"ok": False, "prezzo_medio_periodo": None, "mwh_totale": 0.0,
                "tot_ore": 0,
                "df_soglie": pd.DataFrame(columns=COLS_S),
                "df_mesi": pd.DataFrame(columns=["Mese"]),
                "df_ore": pd.DataFrame(columns=COLS_O)}

    try:
        p = prezzi.astype(float)
        if hasattr(p.index, "duplicated"):
            p = p[~p.index.duplicated(keep="first")]
        p = p.dropna().sort_index()
    except Exception:
        return _vuoto()
    if len(p) < 24:
        return _vuoto()
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
    except (TypeError, ValueError):
        return _vuoto()
    if sum(mws) <= 0:
        return _vuoto()
    soglie_pulite = []
    try:
        soglie_iter = list(soglie)
    except TypeError:
        return _vuoto()
    for s in soglie_iter:
        try:
            v = float(s)
        except (TypeError, ValueError):
            continue
        if np.isfinite(v) and v not in soglie_pulite:
            soglie_pulite.append(v)
    soglie_pulite = sorted(soglie_pulite)
    if not soglie_pulite:
        return _vuoto()

    idx = p.index.tz_convert("Europe/Zurich") if p.index.tz is not None else p.index
    valori = p.to_numpy(dtype=float)
    fasce = np.array([fascia_oraria(ts) for ts in idx])
    mw_map = {"F1": mws[0], "F2": mws[1], "F3": mws[2]}
    mw_ore = np.array([mw_map.get(fx, 0.0) for fx in fasce], dtype=float)
    medio = float(np.mean(valori))
    mwh_tot = float(mw_ore.sum())

    righe = []
    maschere = []
    for s in soglie_pulite:
        mask = valori <= s
        maschere.append(mask)
        n_fill = int(mask.sum())
        mwh_fill = float(mw_ore[mask].sum())
        if n_fill > 0:
            medio_fill = float(np.mean(valori[mask]))
            risp = (medio - medio_fill) * mwh_fill
        else:
            medio_fill, risp = None, 0.0
        righe.append({
            "Soglia (euro/MWh)": s,
            "Ore riempite": n_fill,
            "Quota ore %": round(n_fill / len(valori) * 100.0, 2),
            "MWh acquistabili": round(mwh_fill, 1),
            "Quota MWh %": round(mwh_fill / mwh_tot * 100.0, 2) if mwh_tot > 0 else 0.0,
            "Prezzo medio riempimento (euro/MWh)": (round(medio_fill, 2)
                                                   if medio_fill is not None else None),
            "Risparmio vs media (euro)": round(risp, 2),
        })
    df_soglie = pd.DataFrame(righe, columns=COLS_S)

    # MWh riempiti per mese di calendario e per soglia.
    try:
        mesi = pd.PeriodIndex(idx, freq="M").astype(str).to_numpy()
        dfm = pd.DataFrame({"mese": mesi})
        for s, mask in zip(soglie_pulite, maschere):
            dfm[f"@ {s:g}"] = np.where(mask, mw_ore, 0.0)
        g = dfm.groupby("mese", observed=True).sum(numeric_only=True)
        df_mesi = g.reset_index().rename(columns={"mese": "Mese"})
        df_mesi = df_mesi.sort_values("Mese").reset_index(drop=True)
        for c in df_mesi.columns[1:]:
            df_mesi[c] = df_mesi[c].round(1)
    except Exception:
        df_mesi = pd.DataFrame(columns=["Mese"])

    # Dettaglio orario completo: la UI filtra per la soglia selezionata.
    try:
        df_ore = pd.DataFrame({
            "Data": idx.strftime("%d/%m/%Y"),
            "Ora": idx.hour,
            "Prezzo (euro/MWh)": np.round(valori, 2),
            "Fascia": fasce,
            "MW": np.round(mw_ore, 3),
            "MWh": np.round(mw_ore, 3),
        })
    except Exception:
        df_ore = pd.DataFrame(columns=COLS_O)

    return {"ok": True, "prezzo_medio_periodo": round(medio, 2),
            "mwh_totale": round(mwh_tot, 1), "tot_ore": int(len(p)),
            "df_soglie": df_soglie, "df_mesi": df_mesi, "df_ore": df_ore}


def calcola_take_or_pay(prezzi, mw_f1, mw_f2, mw_f3, prezzo_fisso,
                        volume_mode="profilo", tolleranza_pct=10.0,
                        pen_sopra_pct=0.0, pen_sotto_pct=0.0,
                        sweep_prezzi=None):
    """Take-or-pay: contratto di fornitura a prezzo fisso con banda di
    tolleranza sui volumi orari.

    Domanda operativa dell'energy analyst: "se firmo un fisso a P euro/MWh
    con volume orario contrattato V e tolleranza +/-X%, quanto pago DAVVERO
    col mio profilo?" — il contratto copre al prezzo P solo il volume
    dentro la banda [V*(1-X), V*(1+X)]: il consumo OLTRE il cap si regola
    a spot maggiorato di una penale, il volume SOTTO il floor resta comunque
    pagato a P (take-or-pay) con eventuale rivendita a spot scontato.

    Diverso dal tab Fisso vs indicizzato (tab46: fisso PURO senza banda
    volumi, tutto il consumo a P) e dal tab Sbilanciamento (tab55: errore
    di PREVISIONE del carico regolato dal TSO, non un contratto
    commerciale). Qui il driver di costo e' la RIGIDITA' del volume
    contrattato rispetto al profilo reale.

    volume_mode: "profilo" = il volume contrattato segue il profilo
    dichiarato F1/F2/F3 (V_h = consumo di fascia); "piatto" = baseload
    (V_h = consumo medio orario). Con "profilo" e tolleranza 0 il contratto
    copre esattamente il profilo dichiarato a P.

    Per ogni ora h, con C = consumo, V = volume contrattato,
    floor = V*(1-tol), cap = V*(1+tol), S = spot:
    - quota in banda: min(max(C, floor), cap) pagata a P;
    - eccedenza sopra cap: (C - cap) a S * (1 + pen_sopra);
    - take-or-pay sotto floor: floor pagato a P, meno credito di rivendita
      (floor - C) * S * (1 - pen_sotto).

    Sanitizzazione: ore con prezzo NaN scartate, timestamp duplicati ->
    primo tenuto, serie ordinata per tempo; ore in Europe/Zurich per la
    fascia corretta; tolleranza clamp 0-100, penali clamp 0-100, prezzo
    fisso >= 0 e finito. Serie con meno di 24 ore, profilo nullo o prezzo
    fisso non valido -> 'ok' False.

    Ritorna dict con 'ok', 'prezzo_fisso', 'tot_ore', 'mwh_consumati',
    'mwh_contrattati', 'costo_totale', 'prezzo_medio_effettivo',
    'costo_spot', 'delta_vs_spot' (positivo = il contratto costa DI PIU'
    dello spot), 'pct_ore_in_banda' / 'pct_ore_sotto_floor' /
    'pct_ore_sopra_cap', 'mwh_take_or_pay' (pagati a P ma non consumati),
    'mwh_eccedenza', 'df_ore' ('Data' / 'Ora' / 'Fascia' /
    'Prezzo (euro/MWh)' / 'MW consumati' / 'MW contrattati' / 'Floor (MW)' /
    'Cap (MW)' / 'Stato' / 'Costo orario (euro)'), 'df_mesi' ('Mese' /
    'Costo contratto (euro)' / 'Costo spot (euro)' / 'MWh' /
    'Prezzo medio effettivo (euro/MWh)'), 'df_sweep' ('Prezzo fisso
    (euro/MWh)' / 'Prezzo medio effettivo (euro/MWh)' / 'Delta vs spot
    (euro)') per i prezzi in sweep_prezzi (sanitizzati, finiti, >= 0,
    deduplicati, ordinati)."""
    COLS_O = ["Data", "Ora", "Fascia", "Prezzo (euro/MWh)", "MW consumati",
              "MW contrattati", "Floor (MW)", "Cap (MW)", "Stato",
              "Costo orario (euro)"]
    COLS_S = ["Prezzo fisso (euro/MWh)", "Prezzo medio effettivo (euro/MWh)",
              "Delta vs spot (euro)"]

    def _vuoto():
        return {"ok": False, "prezzo_fisso": None, "tot_ore": 0,
                "mwh_consumati": 0.0, "mwh_contrattati": 0.0,
                "costo_totale": 0.0, "prezzo_medio_effettivo": None,
                "costo_spot": 0.0, "delta_vs_spot": 0.0,
                "pct_ore_in_banda": 0.0, "pct_ore_sotto_floor": 0.0,
                "pct_ore_sopra_cap": 0.0, "mwh_take_or_pay": 0.0,
                "mwh_eccedenza": 0.0,
                "df_ore": pd.DataFrame(columns=COLS_O),
                "df_mesi": pd.DataFrame(columns=["Mese"]),
                "df_sweep": pd.DataFrame(columns=COLS_S)}

    try:
        p = prezzi.astype(float)
        if hasattr(p.index, "duplicated"):
            p = p[~p.index.duplicated(keep="first")]
        p = p.dropna().sort_index()
    except Exception:
        return _vuoto()
    if len(p) < 24:
        return _vuoto()
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
    except (TypeError, ValueError):
        return _vuoto()
    if sum(mws) <= 0:
        return _vuoto()
    try:
        P = float(prezzo_fisso)
    except (TypeError, ValueError):
        return _vuoto()
    if not np.isfinite(P) or P < 0:
        return _vuoto()
    try:
        tol = max(0.0, min(100.0, float(tolleranza_pct))) / 100.0
        pen_up = 1.0 + max(0.0, min(100.0, float(pen_sopra_pct))) / 100.0
        pen_down = 1.0 - max(0.0, min(100.0, float(pen_sotto_pct))) / 100.0
    except (TypeError, ValueError):
        return _vuoto()

    idx = p.index.tz_convert("Europe/Zurich") if p.index.tz is not None else p.index
    valori = p.to_numpy(dtype=float)
    fasce = np.array([fascia_oraria(ts) for ts in idx])
    mw_map = {"F1": mws[0], "F2": mws[1], "F3": mws[2]}
    consumo = np.array([mw_map.get(fx, 0.0) for fx in fasce], dtype=float)
    if volume_mode == "piatto":
        vol = np.full_like(consumo, consumo.mean())
    else:
        vol = consumo.copy()
    floor = vol * (1.0 - tol)
    cap = vol * (1.0 + tol)

    in_banda = np.minimum(np.maximum(consumo, floor), cap)
    eccesso = np.maximum(0.0, consumo - cap)
    mancante = np.maximum(0.0, floor - consumo)
    costo_eccesso = eccesso * valori * pen_up
    credito = mancante * valori * pen_down

    def _costo_totale(pf):
        return float(np.sum(in_banda * pf + costo_eccesso - credito))

    costo_tot = _costo_totale(P)
    mwh = float(consumo.sum())
    pme = costo_tot / mwh if mwh > 0 else None
    costo_spot = float(np.sum(consumo * valori))
    delta = costo_tot - costo_spot

    n = len(valori)
    sopra = consumo > cap
    sotto = consumo < floor
    pct_sopra = round(float(sopra.sum()) / n * 100.0, 2)
    pct_sotto = round(float(sotto.sum()) / n * 100.0, 2)
    pct_banda = round(100.0 - pct_sopra - pct_sotto, 2)

    try:
        sweep = []
        if sweep_prezzi is not None:
            for s in list(sweep_prezzi):
                try:
                    v = float(s)
                except (TypeError, ValueError):
                    continue
                if np.isfinite(v) and v >= 0 and v not in sweep:
                    sweep.append(v)
        sweep = sorted(sweep)
    except TypeError:
        sweep = []
    righe_s = [{"Prezzo fisso (euro/MWh)": s,
                "Prezzo medio effettivo (euro/MWh)": round(_costo_totale(s) / mwh, 2) if mwh > 0 else None,
                "Delta vs spot (euro)": round(_costo_totale(s) - costo_spot, 2)}
               for s in sweep]
    df_sweep = pd.DataFrame(righe_s, columns=COLS_S)

    stati = np.where(sopra, "sopra cap", np.where(sotto, "sotto floor (take-or-pay)", "in banda"))
    costo_ora = in_banda * P + costo_eccesso - credito
    try:
        df_ore = pd.DataFrame({
            "Data": idx.strftime("%d/%m/%Y"),
            "Ora": idx.hour,
            "Fascia": fasce,
            "Prezzo (euro/MWh)": np.round(valori, 2),
            "MW consumati": np.round(consumo, 3),
            "MW contrattati": np.round(vol, 3),
            "Floor (MW)": np.round(floor, 3),
            "Cap (MW)": np.round(cap, 3),
            "Stato": stati,
            "Costo orario (euro)": np.round(costo_ora, 2),
        })
    except Exception:
        df_ore = pd.DataFrame(columns=COLS_O)

    try:
        dfm = pd.DataFrame({
            "mese": pd.PeriodIndex(idx, freq="M").astype(str),
            "costo_c": costo_ora,
            "costo_s": consumo * valori,
            "mwh": consumo,
        })
        g = dfm.groupby("mese", observed=True).sum(numeric_only=True)
        df_mesi = g.reset_index().rename(columns={
            "mese": "Mese", "costo_c": "Costo contratto (euro)",
            "costo_s": "Costo spot (euro)", "mwh": "MWh"})
        df_mesi = df_mesi.sort_values("Mese").reset_index(drop=True)
        df_mesi["Costo contratto (euro)"] = df_mesi["Costo contratto (euro)"].round(0)
        df_mesi["Costo spot (euro)"] = df_mesi["Costo spot (euro)"].round(0)
        df_mesi["MWh"] = df_mesi["MWh"].round(1)
        df_mesi["Prezzo medio effettivo (euro/MWh)"] = (
            df_mesi["Costo contratto (euro)"] / df_mesi["MWh"].replace(0, np.nan)).round(2)
    except Exception:
        df_mesi = pd.DataFrame(columns=["Mese"])

    return {"ok": True, "prezzo_fisso": P, "tot_ore": n,
            "mwh_consumati": round(mwh, 1),
            "mwh_contrattati": round(float(vol.sum()), 1),
            "costo_totale": round(costo_tot, 2),
            "prezzo_medio_effettivo": round(pme, 2) if pme is not None else None,
            "costo_spot": round(costo_spot, 2),
            "delta_vs_spot": round(delta, 2),
            "pct_ore_in_banda": pct_banda,
            "pct_ore_sotto_floor": pct_sotto,
            "pct_ore_sopra_cap": pct_sopra,
            "mwh_take_or_pay": round(float(mancante.sum()), 1),
            "mwh_eccedenza": round(float(eccesso.sum()), 1),
            "df_ore": df_ore, "df_mesi": df_mesi, "df_sweep": df_sweep}


def _irr_sizing(netto_annuo, capex, anni, degrado, tol=1e-6):
    """Tasso interno di rendimento: risolve NPV(r) = 0 con ricavi netti in degrado
    geometrico annuo. Ritorna la percentuale arrotondata, None se non converge."""
    if netto_annuo is None or capex is None or netto_annuo <= 0 or capex <= 0 or anni <= 0:
        return None

    def npv_r(r):
        if r <= -1.0:
            return float("inf")
        q = (1.0 - degrado) / (1.0 + r)
        f = float(anni) if abs(1.0 - q) < 1e-12 else q * (1.0 - q ** anni) / (1.0 - q)
        return netto_annuo * f - capex

    lo, hi = -0.999, 10.0
    if npv_r(lo) < 0 or npv_r(hi) > 0:
        return None
    for _ in range(100):
        mid = 0.5 * (lo + hi)
        if npv_r(mid) > 0:
            lo = mid
        else:
            hi = mid
        if hi - lo < tol:
            break
    return round(0.5 * (lo + hi) * 100.0, 1)


def calcola_sizing_batteria(prezzi, eff=0.85, cap_max=20.0, pot_max=10.0,
                            step=2.0, ore_finestra=2.0, cicli_giorno=1,
                            capex_kwh=250.0, capex_kw=150.0, opex_pct=0.02,
                            anni=15, tasso=0.06, degrado_annuo=0.02,
                            budget_max=1_500_000.0, payback_target=8.0):
    """Sizing batteria per arbitraggio: sweep su griglia capacita' (MWh) x potenza (MW).

    Strategia: cicli_giorno cicli/giorno, carica all'ora piu' economica e scarica a quella
    piu' cara di ogni giorno; spread netto = max(0, p_max - p_min / eff), energia per
    ciclo = min(cap, pot * ore_finestra) (la potenza limita quanto riesci a muovere
    nella finestra di prezzo). Spread annualizzato sul periodo disponibile.
    Economia: CAPEX = cap*capex_kwh + pot*capex_kw, OPEX annuo = CAPEX*opex_pct,
    ricavi netti in degrado geometrico, NPV con tasso di sconto, PI = NPV/CAPEX.
    Ottimo = max NPV entro budget_max; target = min CAPEX con payback <= payback_target.
    Ritorna dict con ok, df_grid, matrici per heatmap, ottimo, target_payback."""
    try:
        p = pd.Series(prezzi).astype(float).dropna()
    except Exception:
        return {"ok": False, "errore": "prezzi non validi"}
    if not isinstance(p.index, pd.DatetimeIndex):
        return {"ok": False, "errore": "indice temporale non valido"}
    if len(p) < 24 or not (0 < eff <= 1) or step <= 0 or cap_max <= 0 or pot_max <= 0:
        return {"ok": False, "errore": "parametri non validi o dati insufficienti"}
    if anni <= 0 or not (0 <= degrado_annuo < 1):
        return {"ok": False, "errore": "parametri non validi o dati insufficienti"}
    try:
        giorni = p.index.normalize()
    except Exception:
        return {"ok": False, "errore": "indice temporale non valido"}
    dmin = p.groupby(giorni).min()
    dmax = p.groupby(giorni).max()
    spread = (dmax - dmin / eff).clip(lower=0.0)
    n_giorni = int(len(spread))
    if n_giorni == 0:
        return {"ok": False, "errore": "nessun giorno completo"}
    spread_annuo = float(spread.sum()) * (365.25 / n_giorni)

    caps = np.arange(step, cap_max + step * 0.5, step)
    pots = np.arange(step, pot_max + step * 0.5, step)
    if len(caps) == 0 or len(pots) == 0:
        return {"ok": False, "errore": "parametri non validi o dati insufficienti"}
    energia = np.minimum(caps[:, None], pots[None, :] * ore_finestra) * max(1, int(cicli_giorno))
    ricavo = spread_annuo * energia
    capex = caps[:, None] * 1000.0 * capex_kwh + pots[None, :] * 1000.0 * capex_kw
    opex = capex * opex_pct
    netto = ricavo - opex
    with np.errstate(divide="ignore", invalid="ignore"):
        payback = np.where(netto > 0, capex / netto, np.inf)
    q = (1.0 - degrado_annuo) / (1.0 + tasso)
    fattore = float(anni) if abs(1.0 - q) < 1e-12 else q * (1.0 - q ** anni) / (1.0 - q)
    npv = netto * fattore - capex
    with np.errstate(divide="ignore", invalid="ignore"):
        pi = np.where(capex > 0, npv / capex, 0.0)

    righe = []
    for i, c in enumerate(caps):
        for j, pw in enumerate(pots):
            righe.append({
                "Capacità (MWh)": round(float(c), 2),
                "Potenza (MW)": round(float(pw), 2),
                "Energia ciclo (MWh)": round(float(energia[i, j]), 2),
                "Ricavo annuo (€)": round(float(ricavo[i, j]), 0),
                "CAPEX (€)": round(float(capex[i, j]), 0),
                "OPEX annuo (€)": round(float(opex[i, j]), 0),
                "Payback (anni)": round(float(payback[i, j]), 1) if np.isfinite(payback[i, j]) else None,
                "NPV (€)": round(float(npv[i, j]), 0),
                "PI": round(float(pi[i, j]), 2),
            })
    df = pd.DataFrame(righe)

    def _riga(i, j):
        netto_ij = float(netto[i, j])
        return {"cap_mwh": float(caps[i]), "pot_mw": float(pots[j]),
                "energia_ciclo": float(energia[i, j]),
                "ricavo_annuo": float(ricavo[i, j]), "capex": float(capex[i, j]),
                "opex_annuo": float(opex[i, j]), "netto_annuo": netto_ij,
                "payback": float(payback[i, j]),
                "npv": float(npv[i, j]), "pi": float(pi[i, j]),
                "irr": _irr_sizing(netto_ij, float(capex[i, j]), anni, degrado_annuo)}

    cand = np.ones_like(capex, dtype=bool)
    if budget_max is not None and budget_max > 0:
        cand = capex <= budget_max
    ottimo = None
    if cand.any():
        ii, jj = np.unravel_index(np.argmax(np.where(cand, npv, -np.inf)), npv.shape)
        ottimo = _riga(ii, jj)
        ottimo["budget_vincolante"] = bool(budget_max is not None and budget_max > 0
                                           and ottimo["capex"] >= 0.999 * budget_max)
    target = None
    okp = np.isfinite(payback) & (payback <= payback_target)
    if okp.any():
        ii, jj = np.unravel_index(np.argmin(np.where(okp, capex, np.inf)), capex.shape)
        target = _riga(ii, jj)

    return {"ok": True, "n_giorni": n_giorni, "spread_annuo": round(spread_annuo, 2),
            "fattore_att": round(fattore, 4),
            "df_grid": df, "mat_payback": payback, "mat_npv": npv, "mat_pi": pi,
            "caps": caps.tolist(), "pots": pots.tolist(),
            "ottimo": ottimo, "target_payback": target}


# Metriche giornaliere disponibili per gli alert personalizzati (tab77)
METRICHE_ALERT = {
    "max_orario": "Max orario del giorno (€/MWh)",
    "min_orario": "Min orario del giorno (€/MWh)",
    "media_giorno": "Media giornaliera (€/MWh)",
    "spread_giorno": "Spread giornaliero max-min (€/MWh)",
    "ore_sopra_livello": "Ore sopra il livello critico (n. ore)",
    "ore_sotto_livello": "Ore sotto il livello basso (n. ore)",
    "var_media_7gg": "Variazione % media vs 7 giorni prima (%)",
}
_LABEL2KEY_ALERT = {v: k for k, v in METRICHE_ALERT.items()}
_OPERATORI_ALERT = {
    ">": np.greater,
    ">=": np.greater_equal,
    "<": np.less,
    "<=": np.less_equal,
}


def calcola_alert_personalizzati(prezzi, regole, livello_critico=150.0, livello_basso=20.0, k_critico=2):
    """Motore di alert personalizzati: valuta regole di monitoraggio sui prezzi orari.

    Ogni regola e' un dict {nome, metrica, operatore, soglia} dove metrica e' una
    delle chiavi di METRICHE_ALERT (o la sua label), operatore in > >= < <= e
    soglia un numero finito. Le metriche sono calcolate per giorno di calendario:
    max/min/media/spread orari, n. ore sopra il livello critico o sotto il livello
    basso, variazione % della media vs la media dei 7 giorni precedenti.
    Un giorno e' 'critico' se almeno k_critico regole scattano insieme.
    I NaN (es. var_media_7gg nei primi 7 giorni) non fanno mai scattare una regola.
    Ritorna dict con ok, df_giorni (bool per regola + conteggi), df_regole
    (statistiche per regola), serie metriche giornaliere e conteggi aggregati.
    """
    try:
        p = pd.Series(prezzi).astype(float).dropna()
    except Exception:
        return {"ok": False, "errore": "prezzi non validi"}
    if not isinstance(p.index, pd.DatetimeIndex):
        return {"ok": False, "errore": "indice temporale non valido"}
    if len(p) < 24:
        return {"ok": False, "errore": "servono almeno 24 ore di prezzi"}
    try:
        giorni = p.index.normalize()
    except Exception:
        return {"ok": False, "errore": "indice temporale non valido"}
    g = p.groupby(giorni)
    dmax = g.max()
    dmin = g.min()
    dmean = g.mean()
    spread = dmax - dmin
    ore_sopra = g.apply(lambda s: int((s > float(livello_critico)).sum()))
    ore_sotto = g.apply(lambda s: int((s < float(livello_basso)).sum()))
    media_7gg = dmean.shift(7)
    with np.errstate(divide="ignore", invalid="ignore"):
        var_7gg = np.where(media_7gg.abs() > 1e-9,
                           (dmean - media_7gg) / media_7gg.abs() * 100.0, np.nan)
    var_7gg = pd.Series(var_7gg, index=dmean.index)
    metriche = {
        "max_orario": dmax,
        "min_orario": dmin,
        "media_giorno": dmean,
        "spread_giorno": spread,
        "ore_sopra_livello": ore_sopra,
        "ore_sotto_livello": ore_sotto,
        "var_media_7gg": var_7gg,
    }

    valide, scartate, visti = [], 0, set()
    for r in (regole or []):
        try:
            nome = str(r.get("nome", "")).strip()
            met = str(r.get("metrica", "")).strip()
            op = str(r.get("operatore", "")).strip()
            soglia = float(r.get("soglia"))
        except (TypeError, ValueError, AttributeError):
            scartate += 1
            continue
        if met in _LABEL2KEY_ALERT:
            met = _LABEL2KEY_ALERT[met]
        if (not nome or met not in metriche or op not in _OPERATORI_ALERT
                or not np.isfinite(soglia) or nome in visti):
            scartate += 1
            continue
        visti.add(nome)
        valide.append({"nome": nome, "metrica": met, "operatore": op, "soglia": soglia})
    if not valide:
        return {"ok": False, "errore": "nessuna regola valida"}

    date_idx = dmean.index
    nomi = [rv["nome"] for rv in valide]
    df = pd.DataFrame(index=date_idx)
    serie_metriche = {}
    for rv in valide:
        s = metriche[rv["metrica"]].reindex(date_idx)
        serie_metriche[rv["nome"]] = s
        fill = -np.inf if rv["operatore"] in (">", ">=") else np.inf
        trig = _OPERATORI_ALERT[rv["operatore"]](s.fillna(fill).to_numpy(), rv["soglia"])
        df[rv["nome"]] = pd.Series(np.asarray(trig, dtype=bool), index=date_idx)
    df["n_regole_attive"] = df[nomi].sum(axis=1).astype(int)
    k = max(1, int(k_critico))
    df["giorno_critico"] = df["n_regole_attive"] >= k

    righe = []
    for rv in valide:
        t = df[rv["nome"]]
        n_trig = int(t.sum())
        ultimo = df.index[t].max() if n_trig else None
        estremo = None
        if n_trig:
            sv = serie_metriche[rv["nome"]][t].dropna()
            if len(sv):
                estremo = float(sv.max()) if rv["operatore"] in (">", ">=") else float(sv.min())
        righe.append({
            "Regola": rv["nome"],
            "Metrica": METRICHE_ALERT[rv["metrica"]],
            "Operatore": rv["operatore"],
            "Soglia": rv["soglia"],
            "N. trigger": n_trig,
            "% giorni": round(100.0 * n_trig / len(date_idx), 1),
            "Ultimo trigger": ultimo,
            "Valore estremo": round(estremo, 2) if estremo is not None else None,
        })
    df_regole = pd.DataFrame(righe)

    attive = df[nomi].apply(lambda row: ", ".join([c for c in nomi if row[c]]), axis=1)
    df_out = pd.DataFrame({
        "Data": date_idx,
        "N. regole attive": df["n_regole_attive"].to_numpy(),
        "Giorno critico": np.where(df["giorno_critico"].to_numpy(), "sì", "no"),
        "Regole attive": attive.to_numpy(),
    })
    return {"ok": True, "n_giorni": len(date_idx),
            "n_con_alert": int((df["n_regole_attive"] > 0).sum()),
            "n_critici": int(df["giorno_critico"].sum()),
            "n_scartate": scartate, "k_critico": k,
            "livello_critico": float(livello_critico), "livello_basso": float(livello_basso),
            "df_giorni": df_out, "df_bool": df[nomi], "df_regole": df_regole,
            "serie_metriche": serie_metriche,
            "serie_media": dmean, "serie_max": dmax,
            "regole_valide": valide}


def calcola_autoconsumo_fv(prezzi, mw_f1, mw_f2, mw_f3, potenza_mwp,
                           perdite_pct=14.0, feedin_eur_mwh=60.0,
                           capex_eur_kwp=1100.0):
    """Autoconsumo fotovoltaico behind-the-meter (tab 'Autoconsumo FV').

    Simula un impianto FV sul sito del cliente: la generazione oraria
    (profilo_solare deterministico x potenza x (1 - perdite)) copre per prima
    cosa il carico orario del profilo (MW per fascia, come nel resto dell'app);
    l'eccedenza viene immessa in rete e valorizzata al prezzo di ritiro
    dedicato (feed-in).

    A differenza del tab Price capture (tutta la generazione venduta a spot),
    qui la domanda e': quanto risparmio in bolletta con il FV sul tetto.

    Metodo (tutto deterministico a parita' di input):
    - carico orario = MW della fascia di ciascuna ora (via fascia_oraria);
    - gen oraria = profilo_solare(prezzi, potenza_mwp) x (1 - perdite_pct/100);
    - autoconsumo_h = min(gen_h, carico_h); eccedenza_h = gen_h - autoconsumo_h;
    - costo evitato = somma(autoconsumo_h x prezzo_h): bolletta che non paghi;
    - ricavo eccedenze = somma(eccedenza_h) x feedin;
    - risparmio periodo = costo evitato + ricavo eccedenze;
    - quota autoconsumo = autoconsumo / generazione (None se gen = 0);
    - quota autosufficienza = autoconsumo / carico (None se carico = 0);
    - annualizzazione x 8760/ore: produzione annua, risparmio annuo;
    - payback = CAPEX / risparmio annuo (None se risparmio annuo <= 0);
    - produzione specifica = kWh/kWp/anno;
    - df_mesi: per mese Generazione/Autoconsumo/Eccedenza (MWh), Costo evitato
      (EUR), Ricavo eccedenze (EUR), quote %;
    - sweep dimensionamento: 21 potenze da 0 a pmax = max(2 x picco carico,
      potenza x 1.5, 0.05 MWp); per ciascuna risparmio annuo, payback e quote
      (vettorizzato sul profilo normalizzato a 1 MWp).

    prezzi: Series oraria in EUR/MWh (indice datetime).
    potenza_mwp: taglia impianto in MWp (>= 0). perdite_pct: perdite di sistema
    % (0-90). feedin_eur_mwh: prezzo di ritiro delle eccedenze. capex_eur_kwp:
    costo chiavi in mano per kWp (solo per il payback).

    NaN-safe: serie vuota, MW tutti a zero, parametri non validi ->
    statistiche neutrali con DataFrame dalle colonne giuste.

    Ritorna dict con 'ore', 'picco_carico_mw', 'potenza_mwp', 'capex_eur',
    'gen_mwh', 'autoconsumo_mwh', 'eccedenza_mwh', 'carico_mwh',
    'quota_autoconsumo', 'quota_autosufficienza', 'costo_base_eur',
    'costo_evitato_eur', 'ricavo_eccedenze_eur', 'risparmio_periodo_eur',
    'risparmio_annuo_eur', 'payback_anni', 'produzione_specifica_kwh_kwp',
    'df_mesi', 'df_sweep' ('Potenza (MWp)', 'Risparmio annuo (EUR)',
    'Payback (anni)', 'Quota autoconsumo (%)', 'Quota autosufficienza (%)').
    """
    cols_m = ["Mese", "Generazione (MWh)", "Autoconsumo (MWh)", "Eccedenza (MWh)",
              "Costo evitato (EUR)", "Ricavo eccedenze (EUR)",
              "Quota autoconsumo (%)", "Quota autosufficienza (%)"]
    cols_s = ["Potenza (MWp)", "Risparmio annuo (EUR)", "Payback (anni)",
              "Quota autoconsumo (%)", "Quota autosufficienza (%)"]
    vuoto = {"ore": 0, "picco_carico_mw": 0.0, "potenza_mwp": 0.0, "capex_eur": 0.0,
             "gen_mwh": 0.0, "autoconsumo_mwh": 0.0, "eccedenza_mwh": 0.0,
             "carico_mwh": 0.0, "quota_autoconsumo": None,
             "quota_autosufficienza": None, "costo_base_eur": 0.0,
             "costo_evitato_eur": 0.0, "ricavo_eccedenze_eur": 0.0,
             "risparmio_periodo_eur": 0.0, "risparmio_annuo_eur": 0.0,
             "payback_anni": None, "produzione_specifica_kwh_kwp": None,
             "df_mesi": pd.DataFrame(columns=cols_m),
             "df_sweep": pd.DataFrame(columns=cols_s)}
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0:
        return dict(vuoto)
    try:
        pot = max(0.0, float(potenza_mwp))
    except (TypeError, ValueError):
        pot = 0.0
    try:
        perd = float(perdite_pct)
    except (TypeError, ValueError):
        perd = 14.0
    perd = min(90.0, max(0.0, perd))
    try:
        feedin = max(0.0, float(feedin_eur_mwh))
    except (TypeError, ValueError):
        feedin = 0.0
    try:
        capex_kwp = max(0.0, float(capex_eur_kwp))
    except (TypeError, ValueError):
        capex_kwp = 0.0
    out = dict(vuoto)
    out["ore"] = len(p)
    out["potenza_mwp"] = round(pot, 4)
    try:
        fasce = p.index.map(fascia_oraria)
    except Exception:
        return out
    try:
        mw_map = {"F1": max(0.0, float(mw_f1)), "F2": max(0.0, float(mw_f2)),
                  "F3": max(0.0, float(mw_f3))}
    except (TypeError, ValueError):
        mw_map = {"F1": 0.0, "F2": 0.0, "F3": 0.0}
    carico = fasce.map(mw_map).to_numpy(dtype=float)
    picco = float(carico.max()) if len(carico) else 0.0
    out["picco_carico_mw"] = round(picco, 3)
    try:
        gen1 = profilo_solare(p, 1.0).to_numpy(dtype=float) * (1.0 - perd / 100.0)
    except Exception:
        return out
    pr = p.to_numpy(dtype=float)
    fattore_annuo = 8760.0 / len(p)
    capex = pot * 1000.0 * capex_kwp
    out["capex_eur"] = round(capex, 2)
    carico_mwh = float(carico.sum())
    out["carico_mwh"] = round(carico_mwh, 2)
    out["costo_base_eur"] = round(float((carico * pr).sum()), 2)
    # --- sweep dimensionamento (vettorizzato su profilo normalizzato) ---
    pmax = max(2.0 * picco, pot * 1.5, 0.05)
    ps = np.linspace(0.0, pmax, 21)
    G = gen1[:, None] * ps[None, :]
    AUTO = np.minimum(G, carico[:, None])
    ECC = G - AUTO
    evitato_v = (AUTO * pr[:, None]).sum(axis=0)
    ricavo_v = ECC.sum(axis=0) * feedin
    risp_annuo_v = (evitato_v + ricavo_v) * fattore_annuo
    gen_v = G.sum(axis=0)
    with np.errstate(divide="ignore", invalid="ignore"):
        q_auto_v = np.where(gen_v > 0, AUTO.sum(axis=0) / gen_v * 100.0, np.nan)
        q_self_v = np.where(carico_mwh > 0, AUTO.sum(axis=0) / carico_mwh * 100.0, np.nan)
        capex_v = ps * 1000.0 * capex_kwp
        pb_v = np.where(risp_annuo_v > 0, capex_v / risp_annuo_v, np.nan)
    righe_s = []
    for i, pv in enumerate(ps):
        righe_s.append({"Potenza (MWp)": round(float(pv), 4),
                        "Risparmio annuo (EUR)": round(float(risp_annuo_v[i]), 2),
                        "Payback (anni)": (round(float(pb_v[i]), 2)
                                            if np.isfinite(pb_v[i]) else None),
                        "Quota autoconsumo (%)": (round(float(q_auto_v[i]), 1)
                                                  if np.isfinite(q_auto_v[i]) else None),
                        "Quota autosufficienza (%)": (round(float(q_self_v[i]), 1)
                                                      if np.isfinite(q_self_v[i]) else None)})
    out["df_sweep"] = pd.DataFrame(righe_s, columns=cols_s)
    # --- punto di lavoro (potenza scelta) ---
    g = gen1 * pot
    auto = np.minimum(g, carico)
    ecc = g - auto
    gen_mwh = float(g.sum())
    auto_mwh = float(auto.sum())
    ecc_mwh = float(ecc.sum())
    out["gen_mwh"] = round(gen_mwh, 2)
    out["autoconsumo_mwh"] = round(auto_mwh, 2)
    out["eccedenza_mwh"] = round(ecc_mwh, 2)
    out["quota_autoconsumo"] = round(100.0 * auto_mwh / gen_mwh, 1) if gen_mwh > 0 else None
    out["quota_autosufficienza"] = (round(100.0 * auto_mwh / carico_mwh, 1)
                                    if carico_mwh > 0 else None)
    evitato = float((auto * pr).sum())
    ricavo = float(ecc_mwh * feedin)
    out["costo_evitato_eur"] = round(evitato, 2)
    out["ricavo_eccedenze_eur"] = round(ricavo, 2)
    risp = evitato + ricavo
    out["risparmio_periodo_eur"] = round(risp, 2)
    risp_annuo = risp * fattore_annuo
    out["risparmio_annuo_eur"] = round(risp_annuo, 2)
    out["payback_anni"] = round(capex / risp_annuo, 2) if risp_annuo > 0 else None
    out["produzione_specifica_kwh_kwp"] = (
        round(gen_mwh * fattore_annuo * 1000.0 / (pot * 1000.0), 0)
        if pot > 0 else None)
    # --- dettaglio mensile ---
    mesi = p.index.to_period("M").astype(str)
    righe = []
    for m in sorted(set(mesi)):
        idx = mesi == m
        gm = float(g[idx].sum())
        am = float(auto[idx].sum())
        em = float(ecc[idx].sum())
        cm = float(carico[idx].sum())
        righe.append({"Mese": m,
                      "Generazione (MWh)": round(gm, 2),
                      "Autoconsumo (MWh)": round(am, 2),
                      "Eccedenza (MWh)": round(em, 2),
                      "Costo evitato (EUR)": round(float((auto[idx] * pr[idx]).sum()), 2),
                      "Ricavo eccedenze (EUR)": round(em * feedin, 2),
                      "Quota autoconsumo (%)": round(100.0 * am / gm, 1) if gm > 0 else None,
                      "Quota autosufficienza (%)": round(100.0 * am / cm, 1) if cm > 0 else None})
    out["df_mesi"] = pd.DataFrame(righe, columns=cols_m)
    return out


def calcola_nuovo_carico(prezzi, profilo_24, potenza_mw, mw_f1, mw_f2, mw_f3,
                         tariffa_picco_eur_kw_anno=0.0, mod_mensile=None):
    """Costo marginale di un nuovo carico (tab 'Nuovo carico').

    Valuta quanto costa aggiungere un nuovo consumo (es. flotta EV, pompe di
    calore, datacenter) con un profilo giornaliero dato, valorizzato ai prezzi
    spot orari del periodo selezionato.

    Metodo (tutto deterministico a parita' di input):
    - profilo_24: 24 fattori 0..1 (frazione della potenza nominale per ora);
      valori fuori range vengono clampati; lunghezza diversa da 24 -> neutrali.
    - mod_mensile: 12 moltiplicatori mensili (default 1.0) per carichi
      stagionali (es. pompe di calore); valori negativi -> 0; lunghezza
      diversa da 12 -> neutrali.
    - carico_nuovo_h = potenza_mw x profilo_24[ora] x mod_mensile[mese];
    - costo_h = carico_nuovo_h x prezzo_h;
    - prezzo medio = somma(costo) / somma(energia) (None se energia = 0);
    - confronto con carico esistente: stesso calcolo sul profilo per fascia
      (come nel resto dell'app) -> delta €/MWh e % (shape del nuovo carico
      migliore o peggiore della media del carico esistente);
    - picco: picco esistente dal carico per fascia; picco totale coincidente
      = max(carico_esistente_h + carico_nuovo_h); incremento = totale -
      esistente (>= 0); un carico notturno puo' alzare il picco meno della sua
      potenza nominale se il picco esistente e' diurno;
    - costo potenza = incremento_picco_MW x 1000 x tariffa €/kW/anno;
    - annualizzazione x 8760/ore: energia e costi annui stimati;
    - df_mesi: per mese Energia (MWh), Costo (EUR), Prezzo medio (€/MWh),
      Picco nuovo (MW);
    - df_ore: 24 righe con Ora, Frazione profilo, Energia (MWh), Prezzo medio
      ora (€/MWh) ponderato sull'energia del nuovo carico in quell'ora.

    NaN-safe: serie vuota, potenza 0, profilo tutto a zero, parametri non
    validi -> statistiche neutrali con DataFrame dalle colonne giuste.

    Ritorna dict con 'ore', 'potenza_mw', 'energia_mwh', 'energia_annua_mwh',
    'costo_periodo_eur', 'costo_annuo_eur', 'prezzo_medio_eur_mwh',
    'prezzo_medio_base_eur_mwh', 'delta_eur_mwh', 'delta_pct',
    'picco_nuovo_mw', 'picco_esistente_mw', 'picco_totale_mw',
    'incremento_picco_mw', 'costo_potenza_annuo_eur',
    'costo_totale_annuo_eur', 'quota_costo_f1_pct', 'df_mesi', 'df_ore'.
    """
    cols_m = ["Mese", "Energia (MWh)", "Costo (EUR)", "Prezzo medio (€/MWh)",
              "Picco nuovo (MW)"]
    cols_h = ["Ora", "Frazione profilo", "Energia (MWh)",
              "Prezzo medio ora (€/MWh)"]
    vuoto = {"ore": 0, "potenza_mw": 0.0, "energia_mwh": 0.0,
             "energia_annua_mwh": 0.0, "costo_periodo_eur": 0.0,
             "costo_annuo_eur": 0.0, "prezzo_medio_eur_mwh": None,
             "prezzo_medio_base_eur_mwh": None, "delta_eur_mwh": None,
             "delta_pct": None, "picco_nuovo_mw": 0.0,
             "picco_esistente_mw": 0.0, "picco_totale_mw": 0.0,
             "incremento_picco_mw": 0.0, "costo_potenza_annuo_eur": 0.0,
             "costo_totale_annuo_eur": 0.0, "quota_costo_f1_pct": None,
             "df_mesi": pd.DataFrame(columns=cols_m),
             "df_ore": pd.DataFrame(columns=cols_h)}
    try:
        prof = np.asarray(profilo_24, dtype=float).ravel()
    except (TypeError, ValueError):
        return dict(vuoto)
    if prof.shape[0] != 24 or np.isnan(prof).any():
        return dict(vuoto)
    prof = np.clip(prof, 0.0, 1.0)
    if mod_mensile is None:
        mod = np.ones(12)
    else:
        try:
            mod = np.asarray(mod_mensile, dtype=float).ravel()
        except (TypeError, ValueError):
            return dict(vuoto)
        if mod.shape[0] != 12 or np.isnan(mod).any():
            return dict(vuoto)
        mod = np.clip(mod, 0.0, None)
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0:
        return dict(vuoto)
    try:
        pot = max(0.0, float(potenza_mw))
    except (TypeError, ValueError):
        pot = 0.0
    try:
        tar = max(0.0, float(tariffa_picco_eur_kw_anno))
    except (TypeError, ValueError):
        tar = 0.0
    out = dict(vuoto)
    out["ore"] = len(p)
    out["potenza_mw"] = round(pot, 4)
    try:
        fasce = p.index.map(fascia_oraria)
    except Exception:
        return out
    try:
        mw_map = {"F1": max(0.0, float(mw_f1)), "F2": max(0.0, float(mw_f2)),
                  "F3": max(0.0, float(mw_f3))}
    except (TypeError, ValueError):
        mw_map = {"F1": 0.0, "F2": 0.0, "F3": 0.0}
    carico_e = fasce.map(mw_map).to_numpy(dtype=float)
    pr = p.to_numpy(dtype=float)
    ore_idx = p.index.hour.to_numpy()
    mesi_idx = p.index.month.to_numpy()
    nuovo = pot * prof[ore_idx] * mod[mesi_idx - 1]
    costo = nuovo * pr
    fattore_annuo = 8760.0 / len(p)
    energia = float(nuovo.sum())
    costo_tot = float(costo.sum())
    out["energia_mwh"] = round(energia, 2)
    out["energia_annua_mwh"] = round(energia * fattore_annuo, 2)
    out["costo_periodo_eur"] = round(costo_tot, 2)
    costo_annuo = costo_tot * fattore_annuo
    out["costo_annuo_eur"] = round(costo_annuo, 2)
    out["prezzo_medio_eur_mwh"] = (round(costo_tot / energia, 2)
                                   if energia > 0 else None)
    energia_e = float(carico_e.sum())
    costo_e = float((carico_e * pr).sum())
    pm_base = costo_e / energia_e if energia_e > 0 else None
    out["prezzo_medio_base_eur_mwh"] = round(pm_base, 2) if pm_base is not None else None
    if out["prezzo_medio_eur_mwh"] is not None and pm_base is not None and pm_base != 0:
        out["delta_eur_mwh"] = round(out["prezzo_medio_eur_mwh"] - pm_base, 2)
        out["delta_pct"] = round(100.0 * (out["prezzo_medio_eur_mwh"] - pm_base) / pm_base, 1)
    picco_e = float(carico_e.max()) if len(carico_e) else 0.0
    picco_n = float(nuovo.max()) if len(nuovo) else 0.0
    picco_t = float((carico_e + nuovo).max()) if len(nuovo) else 0.0
    incr = max(0.0, picco_t - picco_e)
    out["picco_esistente_mw"] = round(picco_e, 3)
    out["picco_nuovo_mw"] = round(picco_n, 3)
    out["picco_totale_mw"] = round(picco_t, 3)
    out["incremento_picco_mw"] = round(incr, 3)
    costo_pot = incr * 1000.0 * tar
    out["costo_potenza_annuo_eur"] = round(costo_pot, 2)
    out["costo_totale_annuo_eur"] = round(costo_annuo + costo_pot, 2)
    costo_f1 = float(costo[fasce == "F1"].sum())
    out["quota_costo_f1_pct"] = (round(100.0 * costo_f1 / costo_tot, 1)
                                 if costo_tot > 0 else None)
    # --- dettaglio mensile ---
    mesi = p.index.to_period("M").astype(str)
    righe = []
    for m in sorted(set(mesi)):
        idx = mesi == m
        em = float(nuovo[idx].sum())
        cm = float(costo[idx].sum())
        righe.append({"Mese": m,
                      "Energia (MWh)": round(em, 2),
                      "Costo (EUR)": round(cm, 2),
                      "Prezzo medio (€/MWh)": round(cm / em, 2) if em > 0 else None,
                      "Picco nuovo (MW)": round(float(nuovo[idx].max()), 3)})
    out["df_mesi"] = pd.DataFrame(righe, columns=cols_m)
    # --- dettaglio orario (profilo 24h) ---
    righe_h = []
    for h in range(24):
        idx = ore_idx == h
        eh = float(nuovo[idx].sum())
        ch = float(costo[idx].sum())
        righe_h.append({"Ora": h,
                        "Frazione profilo": round(float(prof[h]), 3),
                        "Energia (MWh)": round(eh, 2),
                        "Prezzo medio ora (€/MWh)": round(ch / eh, 2) if eh > 0 else None})
    out["df_ore"] = pd.DataFrame(righe_h, columns=cols_h)
    return out


def calcola_opzione_asiatica(forward, strike, anni, vol_pct, tasso_pct, tipo="call",
                            n_fixing=12, n_sim=20000, seed=7):
    """Prezzatura di un'opzione ASIATICA (payoff sulla MEDIA dei prezzi) sul forward dell'energia.

    Le opzioni energy si regolano quasi sempre sulla media (settlement mensile
    = media dei giornalieri): un'opzione asiatica replica questo payoff e costa
    meno di una vanilla europea sullo stesso sottostante.

    Metodo: geometrica asiatica con formula chiusa di Kemna-Vorst (esatta);
    aritmetica asiatica via Monte Carlo con VARIABILE DI CONTROLLO sulla
    geometrica (stesso browniano, prezzo esatto noto -> errore std ridotto).
    Il forward e' trattato come martingala (drift zero, modello Black-76).
    n_fixing=1 -> la media coincide con il fixing unico: il prezzo asiatico
    e' identico alla vanilla europea (errore MC = 0, sconto = 0).
    NaN-safe: input non validi (F/K<=0, T<0, vol<0, tasso<0, NaN, stringhe)
    -> dict neutro con nan e senza eccezioni. n_fixing<1 -> 1; n_sim<100 -> 100.
    Ritorna dict con: call_arith/put_arith (MC, €/MWh), call_geom/put_geom
    (Kemna-Vorst), err_std_call/err_std_put, vanilla_call/vanilla_put
    (da calcola_black76), sconto_call_pct/sconto_put_pct (vs vanilla),
    n_fixing, n_sim. Ipotesi: prezzo lognormale, vol/tassi costanti, fixing
    equispaziati da T/n a T.
    """
    neutro = {"call_arith": float("nan"), "put_arith": float("nan"),
              "call_geom": float("nan"), "put_geom": float("nan"),
              "err_std_call": float("nan"), "err_std_put": float("nan"),
              "vanilla_call": float("nan"), "vanilla_put": float("nan"),
              "sconto_call_pct": float("nan"), "sconto_put_pct": float("nan"),
              "n_fixing": None, "n_sim": None}
    try:
        F = float(forward); K = float(strike); T = float(anni)
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r)):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    try:
        n = max(1, int(n_fixing))
    except (TypeError, ValueError):
        return neutro
    try:
        nsim = int(n_sim)
    except (TypeError, ValueError):
        nsim = 20000
    nsim = max(100, nsim)
    df = float(np.exp(-r * T))
    vanilla = calcola_black76(F, K, T, sig * 100.0, r * 100.0)
    vc = float(vanilla["call"]); vp = float(vanilla["put"])
    if n == 1:
        # Un solo fixing: la media coincide col prezzo finale -> vanilla esatta.
        return {"call_arith": vc, "put_arith": vp,
                "call_geom": vc, "put_geom": vp,
                "err_std_call": 0.0, "err_std_put": 0.0,
                "vanilla_call": vc, "vanilla_put": vp,
                "sconto_call_pct": 0.0, "sconto_put_pct": 0.0,
                "n_fixing": 1, "n_sim": nsim}
    if T == 0.0 or sig == 0.0:
        ic, ip = max(F - K, 0.0), max(K - F, 0.0)
        return {"call_arith": float(ic * df), "put_arith": float(ip * df),
                "call_geom": float(ic * df), "put_geom": float(ip * df),
                "err_std_call": 0.0, "err_std_put": 0.0,
                "vanilla_call": float(vanilla["call"]),
                "vanilla_put": float(vanilla["put"]),
                "sconto_call_pct": 0.0, "sconto_put_pct": 0.0,
                "n_fixing": n, "n_sim": nsim}
    # --- Kemna-Vorst: media GEOMETRICA (formula chiusa) ---
    t_i = T * np.arange(1, n + 1) / n
    tbar = float(t_i.mean())
    var_g = float(sig ** 2 * ((n + 1) * (2 * n + 1)) / (6.0 * n ** 2) * T)
    sig_a = float(np.sqrt(var_g / T))
    f_a = F * float(np.exp(-0.5 * sig ** 2 * tbar + 0.5 * var_g))
    sqt_a = sig_a * float(np.sqrt(T))
    d1g = (float(np.log(f_a / K)) + 0.5 * var_g) / sqt_a
    d2g = d1g - sqt_a
    cg = df * (f_a * float(norm.cdf(d1g)) - K * float(norm.cdf(d2g)))
    pg = df * (K * float(norm.cdf(-d2g)) - f_a * float(norm.cdf(-d1g)))
    # --- Monte Carlo: media ARITMETICA con controllo sulla geometrica ---
    rng = np.random.default_rng(int(seed))
    dt = T / n
    incr = rng.normal(0.0, 1.0, size=(nsim, n)) * float(np.sqrt(dt))
    w_t = np.cumsum(incr, axis=1)
    drift = -0.5 * sig ** 2 * t_i
    spot_t = F * np.exp(drift + sig * w_t)
    media_a = spot_t.mean(axis=1)
    media_g = np.exp(np.log(spot_t).mean(axis=1))
    pay_a_c = np.maximum(media_a - K, 0.0)
    pay_a_p = np.maximum(K - media_a, 0.0)
    pay_g_c = np.maximum(media_g - K, 0.0)
    pay_g_p = np.maximum(K - media_g, 0.0)
    adj_c = pay_a_c - pay_g_c
    adj_p = pay_a_p - pay_g_p
    ca = float(cg + df * adj_c.mean())
    pa = float(pg + df * adj_p.mean())
    err_c = float(df * adj_c.std(ddof=1) / np.sqrt(nsim))
    err_p = float(df * adj_p.std(ddof=1) / np.sqrt(nsim))
    vc = float(vanilla["call"]); vp = float(vanilla["put"])
    sc = float(100.0 * (vc - ca) / vc) if vc and np.isfinite(vc) and vc > 0 else 0.0
    sp = float(100.0 * (vp - pa) / vp) if vp and np.isfinite(vp) and vp > 0 else 0.0
    return {"call_arith": ca, "put_arith": pa,
            "call_geom": float(cg), "put_geom": float(pg),
            "err_std_call": err_c, "err_std_put": err_p,
            "vanilla_call": vc, "vanilla_put": vp,
            "sconto_call_pct": sc, "sconto_put_pct": sp,
            "n_fixing": n, "n_sim": nsim}


def calcola_strategia_opzionaria(tipo, forward, anni, vol_pct, tasso_pct,
                                 k_call_pct=10.0, k_put_pct=10.0, n_punti=400):
    """Payoff a scadenza di strategie opzionarie COMBINATE sul forward dell'energia.

    Cinque strutture standard, tutte europee con premi Black-76 (vedi
    calcola_black76) e strike espressi come offset % dal forward F:
      straddle           : long call ATM + long put ATM  (scommessa sulla volatilita')
      strangle           : long call Kc=F*(1+c%) + long put Kp=F*(1-p%) (volatilita', piu' economica)
      butterfly          : long call Kp + short 2x call F + long call Kc (scommessa su prezzo stabile)
      collar_consumatore : long call Kc + short put Kp (protezione dal rialzo per chi compra energia)
      collar_produttore  : long put Kp + short call Kc (protezione dal ribasso per chi vende energia)
    Il collar e' la copertura classica del procurement energy: la vendita
    dell'opzione opposta finanzia (in tutto o in parte) l'acquisto della
    protezione -> premio netto spesso vicino a zero ("zero-cost collar").

    P&L a scadenza per MWh: somma dei payoff delle gambe (segno + per long,
    - per short, moltiplicatore per la butterfly) MENO il premio netto pagato
    (negativo = credito incassato). Payoff valutato su una griglia di prezzi
    a scadenza che include sempre F e tutti gli strike; i breakeven sono i
    punti dove il P&L totale cambia segno (interpolazione lineare).
    NaN-safe: tipo sconosciuto o input non validi (F<=0, T<0, vol<0, tasso<0,
    offset<0, Kp<=0, NaN, stringhe) -> dict con valido=False e nan, nessuna
    eccezione. Ipotesi: opzioni europee, vol/tassi costanti, payoff valutato
    solo a scadenza (niente mark-to-market intermedio, niente early exercise).
    Ritorna dict con: valido, tipo, legs (lista dict con tipo/lato/strike/
    moltiplicatore/premio/premio_segno/delta/delta_segno), premio_netto_mwh
    (+ = costo, - = credito), delta_netto (per MWh), spot_x, payoff_tot,
    payoff_legs (coppie etichetta/lista), breakeven (lista), max_profit,
    max_loss (sulla griglia), forward."""
    neutro = {"valido": False, "tipo": None, "legs": [],
              "premio_netto_mwh": float("nan"), "delta_netto": float("nan"),
              "spot_x": None, "payoff_tot": None, "payoff_legs": [],
              "breakeven": [], "max_profit": float("nan"),
              "max_loss": float("nan"), "forward": float("nan")}
    TIPI = ("straddle", "strangle", "butterfly", "collar_consumatore",
            "collar_produttore")
    try:
        F = float(forward); T = float(anni)
        sig = float(vol_pct); r = float(tasso_pct)
        kc_off = float(k_call_pct); kp_off = float(k_put_pct)
        n = int(n_punti)
    except (TypeError, ValueError):
        return neutro
    if tipo not in TIPI:
        return neutro
    if not all(np.isfinite(v) for v in (F, T, sig, r, kc_off, kp_off)):
        return neutro
    if F <= 0 or T < 0 or sig < 0 or r < 0 or kc_off < 0 or kp_off < 0:
        return neutro
    n = max(50, min(2000, n))

    Kc = float(F * (1.0 + kc_off / 100.0))
    Kp = float(F * (1.0 - kp_off / 100.0))
    if not np.isfinite(Kc) or not np.isfinite(Kp) or Kp <= 0:
        return neutro

    if tipo == "straddle":
        spec = [("call", "long", F, 1), ("put", "long", F, 1)]
    elif tipo == "strangle":
        spec = [("call", "long", Kc, 1), ("put", "long", Kp, 1)]
    elif tipo == "butterfly":
        spec = [("call", "long", Kp, 1), ("call", "short", F, 2), ("call", "long", Kc, 1)]
    elif tipo == "collar_consumatore":
        spec = [("call", "long", Kc, 1), ("put", "short", Kp, 1)]
    else:  # collar_produttore
        spec = [("put", "long", Kp, 1), ("call", "short", Kc, 1)]

    legs = []
    for tleg, lato, K, mult in spec:
        pr = calcola_black76(F, K, anni, vol_pct, tasso_pct)
        prem = float(pr[tleg])
        delta = float(pr["delta_call"] if tleg == "call" else pr["delta_put"])
        if not (np.isfinite(prem) and np.isfinite(delta)):
            return neutro
        segno = 1.0 if lato == "long" else -1.0
        legs.append({"tipo": tleg, "lato": lato, "strike": float(K),
                     "moltiplicatore": int(mult), "premio": prem,
                     "premio_segno": float(segno * prem * mult),
                     "delta": delta,
                     "delta_segno": float(segno * delta * mult)})

    premio_netto = float(sum(l["premio_segno"] for l in legs))
    delta_netto = float(sum(l["delta_segno"] for l in legs))
    strikes = sorted({l["strike"] for l in legs})
    lo = max(0.01, min(strikes) * 0.3)
    hi = max(strikes) * 1.8
    x = np.linspace(lo, hi, n)
    x = np.array(sorted(set(np.concatenate([x, np.array(strikes + [F])]))))

    payoff_legs = []
    for l in legs:
        segno = 1.0 if l["lato"] == "long" else -1.0
        if l["tipo"] == "call":
            pay = np.maximum(x - l["strike"], 0.0)
        else:
            pay = np.maximum(l["strike"] - x, 0.0)
        payoff_legs.append((f"{l['lato']} {l['tipo']} K={l['strike']:.1f}",
                            segno * float(l["moltiplicatore"]) * pay))
    y = sum(p[1] for p in payoff_legs) - premio_netto

    be = []
    for i in range(len(x) - 1):
        if y[i] == 0.0:
            be.append(float(x[i]))
        elif y[i] * y[i + 1] < 0:
            frac = float(y[i] / (y[i] - y[i + 1]))
            be.append(float(x[i] + frac * (x[i + 1] - x[i])))
    be_u = []
    for b in be:
        if not be_u or abs(b - be_u[-1]) > 1e-6:
            be_u.append(b)
    if len(be_u) > 6:
        be_u = []  # payoff degenere (piatto a zero ovunque): nessun BE significativo

    return {"valido": True, "tipo": tipo, "legs": legs,
            "premio_netto_mwh": premio_netto, "delta_netto": delta_netto,
            "spot_x": [float(v) for v in x],
            "payoff_tot": [float(v) for v in y],
            "payoff_legs": [(lab, [float(v) for v in arr]) for lab, arr in payoff_legs],
            "breakeven": be_u, "max_profit": float(np.max(y)),
            "max_loss": float(np.min(y)), "forward": float(F)}


def _prezzo_berm_tree(F, K, T, sig, r, tipo, n_esercizi, n_steps):
    """Motore binomiale CRR sul FORWARD (martingala risk-neutral: p=(1-d)/(u-d)).

    Ritorna (premio_bermudiana, premio_europeo): l'europea usa lo stesso albero
    senza esercizio anticipato (solo a scadenza). Date di esercizio: k*T/n_esercizi
    (k=1..n_esercizi), mappate sullo step piu' vicino.
    Convenzione di liquidazione: CASH all'esercizio — esercitando alla data t si
    incassa subito l'intrinseco max(F_t-K,0) / max(K-F_t,0) (non scontato), come
    nei contratti fisici energy (paghi K, ritiri la commodity). Con questa
    convenzione la put ha in genere un early exercise premium > 0; la call ha
    premio extra solo se deep ITM con tassi alti (valore temporale del cash).
    Assume input gia' validati: F>0, K>0, T>0, sig>0, r>=0, n_esercizi>=1, n_steps>=10."""
    dt = T / n_steps
    u = float(np.exp(sig * np.sqrt(dt)))
    d = 1.0 / u
    p = (1.0 - d) / (u - d)
    df_step = float(np.exp(-r * dt))
    ex_steps = sorted({min(n_steps, max(0, int(round(k * n_steps / n_esercizi))))
                       for k in range(1, n_esercizi + 1)})
    ex_steps[-1] = n_steps  # l'ultima data coincide sempre con la scadenza
    ex_set = set(ex_steps)
    is_call = (tipo == "call")
    # payoff a scadenza
    Vb = np.empty(n_steps + 1)
    Ve = np.empty(n_steps + 1)
    for j in range(n_steps + 1):
        s = F * (u ** j) * (d ** (n_steps - j))
        pay = max(s - K, 0.0) if is_call else max(K - s, 0.0)
        Vb[j] = pay
        Ve[j] = pay
    # induzione all'indietro
    for i in range(n_steps - 1, -1, -1):
        for j in range(i + 1):
            cont_b = df_step * (p * Vb[j + 1] + (1.0 - p) * Vb[j])
            cont_e = df_step * (p * Ve[j + 1] + (1.0 - p) * Ve[j])
            Ve[j] = cont_e
            if i in ex_set:
                s = F * (u ** j) * (d ** (i - j))
                intr = max(s - K, 0.0) if is_call else max(K - s, 0.0)
                Vb[j] = cont_b if cont_b >= intr else intr
            else:
                Vb[j] = cont_b
    return float(Vb[0]), float(Ve[0])


def calcola_bermudiana(tipo, forward, strike, anni, vol_pct, tasso_pct,
                       n_esercizi=4, n_steps=400):
    """Premio di un'opzione BERMUDIANA sul forward dell'energia (albero binomiale CRR).

    La Bermudiana si puo' esercitare solo in date discrete (es. mensili o
    trimestrali): e' il modello naturale per opzioni su periodi di consegna
    energetici e per contratti storage/swing semplificati. Pricing con albero
    binomiale CRR sul forward (martingala risk-neutral, p=(1-d)/(u-d)),
    esercizio anticipato solo agli step corrispondenti alle date k*T/n_esercizi.
    Ritorna anche il premio EUROPEO sullo stesso albero: la differenza e'
    il valore dell'esercizio anticipato (early exercise premium).
    Note: l'esercizio e' cash-settled (intrinseco incassato subito alla data di
    esercizio). La put ha in genere un early exercise premium > 0; la call ha
    premio extra solo se deep ITM con tassi alti. Casi limite: T=0 -> intrinseco;
    vol=0 -> bermudiana = intrinseco (esercizio immediato), europea scontata.
    NaN-safe: input non validi -> dict neutro con nan e senza eccezioni.
    Ritorna dict con: premio, premio_europeo, premio_early (€/MWh),
    premio_early_pct (%), delta (bump centrale), intrinseco, valido,
    n_esercizi, n_steps, date_esercizio (anni)."""
    neutro = {"premio": float("nan"), "premio_europeo": float("nan"),
              "premio_early": float("nan"), "premio_early_pct": float("nan"),
              "delta": float("nan"), "intrinseco": float("nan"),
              "valido": False, "n_esercizi": 0, "n_steps": 0,
              "date_esercizio": []}
    try:
        F = float(forward); K = float(strike); T = float(anni)
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
        ne = int(round(float(n_esercizi))); ns = int(round(float(n_steps)))
        tp = str(tipo).strip().lower()
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r)):
        return neutro
    if tp not in ("call", "put"):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0 or ne < 1:
        return neutro
    ns = min(max(ns, 10), 2000)
    out = dict(neutro)
    out.update({"valido": True, "n_esercizi": ne, "n_steps": ns,
                "date_esercizio": [round(k * T / ne, 6) for k in range(1, ne + 1)]})
    is_call = (tp == "call")
    intr = max(F - K, 0.0) if is_call else max(K - F, 0.0)
    out["intrinseco"] = float(intr)
    df = float(np.exp(-r * T))
    if T == 0.0:
        out.update({"premio": float(intr), "premio_europeo": float(intr),
                    "premio_early": 0.0, "premio_early_pct": 0.0,
                    "delta": float(1.0 if (is_call and F > K) else (-1.0 if (not is_call and F < K) else 0.0))})
        return out
    if sig == 0.0:
        # senza vol: esercizio immediato se in-the-money (cash settlement)
        out.update({"premio": float(intr), "premio_europeo": float(intr * df),
                    "premio_early": float(intr * (1.0 - df)),
                    "delta": float(1.0 if (is_call and F > K) else (-1.0 if (not is_call and F < K) else 0.0))})
        out["premio_early_pct"] = float(100.0 * out["premio_early"] / out["premio"]) \
            if out["premio"] > 0 else 0.0
        return out
    pb, pe = _prezzo_berm_tree(F, K, T, sig, r, tp, ne, ns)
    early = max(pb - pe, 0.0)  # tolleranza numerica: mai negativo
    h = 0.01
    pb_up, _ = _prezzo_berm_tree(F * (1.0 + h), K, T, sig, r, tp, ne, ns)
    pb_dn, _ = _prezzo_berm_tree(F * (1.0 - h), K, T, sig, r, tp, ne, ns)
    delta = (pb_up - pb_dn) / (2.0 * F * h)
    out.update({"premio": float(pb), "premio_europeo": float(pe),
                "premio_early": float(early), "delta": float(delta)})
    out["premio_early_pct"] = float(100.0 * early / pb) if pb > 0 else 0.0
    return out


def _ko_rr_barriera(tipo, direzione, F, K, H, T, sig, r):
    """Termine knock-out di Reiner-Rubinstein (1991) in forma Black-76.

    Sostituzione S=F (forward), b=0 (costo di carry nullo): il forward e'
    una martingala risk-neutral, quindi le formule RR diventano il pricing
    Black-76 con barriera a monitoraggio continuo. Componenti A/B/C/D
    standard con rebate=0; la tabella dei casi segue Reiner-Rubinstein/Haug.
    Casi degeneri: put down con H>K e call up con H<K valgono esattamente 0
    (la barriera scatterebbe prima che l'opzione possa mai andare ITM)."""
    phi = 1.0 if tipo == "call" else -1.0
    eta = 1.0 if direzione == "down" else -1.0
    b = 0.0
    mu = (b - 0.5 * sig * sig) / (sig * sig)
    sT = sig * np.sqrt(T)
    df = np.exp(-r * T)
    x1 = np.log(F / K) / sT + (1 + mu) * sT
    x2 = np.log(F / H) / sT + (1 + mu) * sT
    y1 = np.log(H * H / (F * K)) / sT + (1 + mu) * sT
    y2 = np.log(H / F) / sT + (1 + mu) * sT
    sterm = F * np.exp((b - r) * T)
    n = norm.cdf
    A = phi * sterm * n(phi * x1) - phi * K * df * n(phi * x1 - phi * sT)
    B = phi * sterm * n(phi * x2) - phi * K * df * n(phi * x2 - phi * sT)
    C = (phi * sterm * (H / F) ** (2 * (mu + 1)) * n(eta * y1)
         - phi * K * df * (H / F) ** (2 * mu) * n(eta * y1 - eta * sT))
    D = (phi * sterm * (H / F) ** (2 * (mu + 1)) * n(eta * y2)
         - phi * K * df * (H / F) ** (2 * mu) * n(eta * y2 - eta * sT))
    if direzione == "down":  # H < F
        if tipo == "call":
            return A - C if K >= H else B - D
        return A - B + C - D if K >= H else 0.0
    # up: H > F
    if tipo == "call":
        return A - B + C - D if K <= H else 0.0
    return A - C if K <= H else B - D


def _prob_knock_barriera(direzione, F, H, T, sig):
    """Probabilita' risk-neutral di first-passage alla barriera (formula chiusa).

    Il log-forward ha drift risk-neutral nu=-sig^2/2 (martingala). Formula di
    riflessione: P(hit)=N((-|d|+/-nu*T)/(sig*sqrt(T)))+exp(2*nu*d/sig^2)*
    N((-|d|-/+nu*T)/(sig*sqrt(T))) con d=ln(H/F) con segno."""
    if sig <= 0 or T <= 0:
        if direzione == "down":
            return 1.0 if F <= H else 0.0
        return 1.0 if F >= H else 0.0
    sT = sig * np.sqrt(T)
    nu = -0.5 * sig * sig
    d = float(np.log(H / F))
    n = norm.cdf
    if direzione == "down":  # d < 0
        return float(n((d - nu * T) / sT)
                     + np.exp(2 * nu * d / (sig * sig)) * n((d + nu * T) / sT))
    return float(n((-d + nu * T) / sT)
                 + np.exp(2 * nu * d / (sig * sig)) * n((-d - nu * T) / sT))


def calcola_barriera(tipo, struttura, direzione, barriera, forward, strike,
                     anni, vol_pct, tasso_pct):
    """Premio di un'opzione con BARRIERA sul forward dell'energia (Reiner-Rubinstein).

    Knock-out: l'opzione si spegne se il forward tocca la barriera H prima di
    T; knock-in: si accende solo al tocco. Pricing analitico a monitoraggio
    continuo in forma Black-76 (forward come martingala risk-neutral, b=0);
    knock-in = vanilla - knock-out per parita' in/out. Ritorna anche la
    probabilita' risk-neutral di knock (first-passage) e il delta via bump.
    Casi limite: T=0 o vol=0 -> knock deterministico (intrinseco scontato se
    non knockato); barriera dal lato sbagliato del forward -> knock immediato
    (KO=0, KI=vanilla). Casi degeneri: put down con H>K e call up con H<K
    valgono 0. NaN-safe: input non validi -> dict neutro con nan.
    Ritorna dict con: premio_ko, premio_ki, premio_vanilla, sconto_ko_pct,
    prob_knock, delta (della struttura scelta), intrinseco, valido, regime
    ('regolare'/'reverse'), lato_barriera_ok."""
    neutro = {"premio_ko": float("nan"), "premio_ki": float("nan"),
              "premio_vanilla": float("nan"), "sconto_ko_pct": float("nan"),
              "prob_knock": float("nan"), "delta": float("nan"),
              "intrinseco": float("nan"), "valido": False,
              "regime": "", "lato_barriera_ok": False}
    try:
        tp = str(tipo).strip().lower()
        st_ = str(struttura).strip().lower()
        dr = str(direzione).strip().lower()
        H = float(barriera); F = float(forward); K = float(strike)
        T = float(anni); sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (H, F, K, T, sig, r)):
        return neutro
    if tp not in ("call", "put") or st_ not in ("knock-out", "knock-in") \
            or dr not in ("down", "up"):
        return neutro
    if H <= 0 or F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    is_call = (tp == "call")
    if is_call:
        regolare = (dr == "down" and H <= K) or (dr == "up" and H >= K)
    else:
        regolare = (dr == "down" and H >= K) or (dr == "up" and H <= K)
    out = dict(neutro)
    out.update({"valido": True, "regime": "regolare" if regolare else "reverse"})
    intr = max(F - K, 0.0) if is_call else max(K - F, 0.0)
    out["intrinseco"] = float(intr)
    van = calcola_black76(F, K, T, sig * 100.0, r * 100.0)
    vanilla = float(van["call"] if is_call else van["put"])
    out["premio_vanilla"] = vanilla
    lato_ok = (dr == "down" and H < F) or (dr == "up" and H > F)
    out["lato_barriera_ok"] = bool(lato_ok)
    if not lato_ok:
        # barriera dal lato sbagliato: knock immediato
        out.update({"premio_ko": 0.0, "premio_ki": vanilla, "prob_knock": 1.0,
                    "sconto_ko_pct": 100.0 if vanilla > 0 else 0.0, "delta": 0.0})
        return out
    if T == 0.0 or sig == 0.0:
        knocked = (F <= H) if dr == "down" else (F >= H)
        df = float(np.exp(-r * T))
        ko = 0.0 if knocked else intr * df
        ki = intr * df if knocked else 0.0
        out.update({"premio_ko": float(ko), "premio_ki": float(ki),
                    "prob_knock": 1.0 if knocked else 0.0, "delta": 0.0})
        out["sconto_ko_pct"] = float(100.0 * (1.0 - ko / vanilla)) if vanilla > 0 else 0.0
        return out
    ko = _ko_rr_barriera(tp, dr, F, K, H, T, sig, r)
    ko = float(min(max(ko, 0.0), vanilla))  # tolleranza numerica
    ki = float(max(vanilla - ko, 0.0))
    out["premio_ko"] = ko
    out["premio_ki"] = ki
    out["sconto_ko_pct"] = float(100.0 * (1.0 - ko / vanilla)) if vanilla > 0 else 0.0
    out["prob_knock"] = float(min(max(_prob_knock_barriera(dr, F, H, T, sig), 0.0), 1.0))

    def _premio_f(fx):
        if not ((dr == "down" and H < fx) or (dr == "up" and H > fx)):
            kk = 0.0
        else:
            vv0 = calcola_black76(fx, K, T, sig * 100.0, r * 100.0)
            vv0 = float(vv0["call"] if is_call else vv0["put"])
            kk = min(max(_ko_rr_barriera(tp, dr, fx, K, H, T, sig, r), 0.0), vv0)
        vv = calcola_black76(fx, K, T, sig * 100.0, r * 100.0)
        vv = float(vv["call"] if is_call else vv["put"])
        return kk if st_ == "knock-out" else max(vv - kk, 0.0)

    h = 0.01
    out["delta"] = float((_premio_f(F * (1 + h)) - _premio_f(F * (1 - h))) / (2 * F * h))
    return out


def calcola_lookback(tipo, strike_type, forward, strike, anni, vol_pct, tasso_pct,
                     n_fixing=30, n_paths=20000, seed=42):
    """Premio di un'opzione LOOKBACK sul forward dell'energia (Monte Carlo Black-76).

    Strike FISSO: la call paga max(max_fix - K, 0), la put paga max(K - min_fix, 0).
    Strike FLOTTANTE: la call paga max(S_T - min_fix, 0), la put paga
    max(max_fix - S_T, 0) — lo strike e' il minimo/massimo realizzato.
    Pricing Monte Carlo con seed fisso (deterministico, coerente con i grafici
    seedati della dashboard) e variabili antitetiche; dinamica risk-neutral
    driftless sul forward, sconto al tasso risk-free. Le date di fixing sono
    t = T*i/n per i = 1..n (esclude t = 0): con n_fixing = 1 lo strike fisso
    coincide ESATTAMENTE con la vanilla Black-76 e lo strike flottante vale 0
    (ancora di coerenza usata nei test).
    Casi limite: T = 0 o vol = 0 -> deterministico (intrinseco scontato per lo
    strike fisso, 0 per lo strike flottante). NaN-safe: input non validi ->
    dict neutro con valido = False, nessuna eccezione.
    Ritorna dict con: premio, premio_vanilla (strike fisso; nan se flottante),
    extra_vs_vanilla, prob_esercizio, delta (via bump sul forward, stesso seed),
    intrinseco, valido."""


    neutro = {"premio": float("nan"), "premio_vanilla": float("nan"),
              "extra_vs_vanilla": float("nan"), "prob_esercizio": float("nan"),
              "delta": float("nan"), "intrinseco": float("nan"),
              "valido": False}
    try:
        tp = str(tipo).strip().lower()
        st_ = str(strike_type).strip().lower()
        F = float(forward); K = float(strike); T = float(anni)
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
        nfx = int(n_fixing); npt = int(n_paths); sd = int(seed)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r)):
        return neutro
    if tp not in ("call", "put") or st_ not in ("fisso", "flottante"):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    if nfx < 1 or npt < 100:
        return neutro
    is_call = (tp == "call")
    fisso = (st_ == "fisso")
    df = float(np.exp(-r * T))
    van = calcola_black76(F, K, T, sig * 100.0, r * 100.0)
    vanilla = float(van["call"] if is_call else van["put"])
    out = dict(neutro)
    out.update({"valido": True, "premio_vanilla": vanilla})
    if fisso:
        intr = max(F - K, 0.0) if is_call else max(K - F, 0.0)
    else:
        intr = 0.0
    out["intrinseco"] = float(intr)

    def _prezzo(ff):
        if T == 0.0 or sig == 0.0:
            if fisso:
                pay = max(ff - K, 0.0) if is_call else max(K - ff, 0.0)
            else:
                pay = 0.0
            return float(pay * df), (1.0 if pay > 0 else 0.0)
        rng = np.random.default_rng(sd)
        nh = npt // 2
        zh = rng.standard_normal((nh, nfx))
        z = np.vstack([zh, -zh])  # antitetiche: (2*nh, nfx)
        dt = T / nfx
        drift = -0.5 * sig * sig * dt
        vola = sig * float(np.sqrt(dt))
        s = np.exp(np.log(ff) + np.cumsum(drift + vola * z, axis=1))
        s_min = s.min(axis=1)
        s_max = s.max(axis=1)
        s_t = s[:, -1]
        if fisso:
            pay = np.maximum(s_max - K, 0.0) if is_call else np.maximum(K - s_min, 0.0)
        else:
            pay = np.maximum(s_t - s_min, 0.0) if is_call else np.maximum(s_max - s_t, 0.0)
        return float(df * pay.mean()), float((pay > 0).mean())

    p0, pr0 = _prezzo(F)
    out["premio"] = p0
    out["prob_esercizio"] = pr0
    out["extra_vs_vanilla"] = float(p0 - vanilla) if fisso else float("nan")
    h = 0.01
    p_up, _ = _prezzo(F * (1 + h))
    p_dn, _ = _prezzo(F * (1 - h))
    out["delta"] = float((p_up - p_dn) / (2 * F * h))
    return out


def calcola_composta(comp_tipo, sott_tipo, forward, k_composto, k_sottostante,
                     mesi_composto, mesi_sottostante, vol_pct, tasso_pct,
                     n_paths=20000, seed=42):
    """Premio di un'opzione COMPOSTA (opzione su opzione) sul forward energetico.

    La composta scade a t1 e paga max(+- (V(F(t1), K2, T2-t1) - K1), 0), dove
    V e' il valore Black-76 dell'opzione SOTTOSTANTE (call o put) di strike K2
    e scadenza T2 >= t1. Nell'energia serve a comprare oggi il DIRITTO di
    decidere in futuro se attivare una copertura: es. call su call = a t1
    decidi se pagare K1 per ottenere una call con scadenza T2 (estensione
    dell'hedge condizionata al prezzo di mercato a t1).
    Pricing Monte Carlo con seed fisso e antitetiche: simulato F(t1) con
    dinamica driftless Black-76, l'opzione sottostante e' prezzata in forma
    chiusa vettoriale su ogni path, payoff scontato al tasso risk-free.
    Ancore esatte: K1 = 0 -> la call composta coincide con la vanilla
    sottostante; t1 = 0 -> max(+-(C0 - K1), 0); vol = 0 -> deterministico;
    parita' composta put-call: put su call = K1*df - call su call.
    F_star = prezzo forward critico a t1 (esercizio ottimale sopra/sotto),
    cercato con brentq; nan se inesistente. NaN-safe: input non validi ->
    dict neutro con valido = False.
    Ritorna dict con: premio, premio_sottostante (vanilla a T2), prob_esercizio,
    delta (via bump sul forward, stesso seed), f_star, intrinseco, valido."""
    from scipy.stats import norm as _norm
    from scipy.optimize import brentq as _brentq

    neutro = {"premio": float("nan"), "premio_sottostante": float("nan"),
              "prob_esercizio": float("nan"), "delta": float("nan"),
              "f_star": float("nan"), "intrinseco": float("nan"),
              "valido": False}
    try:
        ct = str(comp_tipo).strip().lower()
        st_ = str(sott_tipo).strip().lower()
        F = float(forward); K1 = float(k_composto); K2 = float(k_sottostante)
        t1 = float(mesi_composto) / 12.0; T2 = float(mesi_sottostante) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
        npt = int(n_paths); sd = int(seed)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K1, K2, t1, T2, sig, r)):
        return neutro
    if ct not in ("call", "put") or st_ not in ("call", "put"):
        return neutro
    if F <= 0 or K1 < 0 or K2 <= 0 or t1 < 0 or T2 <= 0 or t1 > T2:
        return neutro
    if sig < 0 or r < 0 or npt < 100:
        return neutro
    is_call = (ct == "call")
    sott_call = (st_ == "call")
    df1 = float(np.exp(-r * t1))
    Trem = T2 - t1

    def _b76(Fv, Kv, Tv, cp):
        # Black-76 vettoriale su forward Fv; cp True=call, False=put
        Fv = np.asarray(Fv, dtype=float)
        if Tv <= 0.0 or sig <= 0.0:
            intr = np.maximum(Fv - Kv, 0.0) if cp else np.maximum(Kv - Fv, 0.0)
            return np.exp(-r * Tv) * intr
        sqt = sig * np.sqrt(Tv)
        d1 = (np.log(Fv / Kv) + 0.5 * sig * sig * Tv) / sqt
        d2 = d1 - sqt
        dff = np.exp(-r * Tv)
        if cp:
            return dff * (Fv * _norm.cdf(d1) - Kv * _norm.cdf(d2))
        return dff * (Kv * _norm.cdf(-d2) - Fv * _norm.cdf(-d1))

    def _prezzo(ff, seed_loc):
        V0 = float(_b76(ff, K2, T2, sott_call))
        if t1 == 0.0 or sig == 0.0:
            # deterministico: F(t1) = F
            V1 = float(_b76(ff, K2, Trem, sott_call))
            pay = max(V1 - K1, 0.0) if is_call else max(K1 - V1, 0.0)
            return float(pay * df1), (1.0 if pay > 0 else 0.0), V0
        rng = np.random.default_rng(seed_loc)
        nh = npt // 2
        zh = rng.standard_normal(nh)
        z = np.concatenate([zh, -zh])  # antitetiche
        F1 = ff * np.exp(-0.5 * sig * sig * t1 + sig * np.sqrt(t1) * z)
        V1 = _b76(F1, K2, Trem, sott_call)
        pay = np.maximum(V1 - K1, 0.0) if is_call else np.maximum(K1 - V1, 0.0)
        return float(df1 * pay.mean()), float((pay > 0).mean()), V0

    p0, pr0, V0 = _prezzo(F, sd)
    out = dict(neutro)
    out.update({"valido": True, "premio": p0, "prob_esercizio": pr0,
                "premio_sottostante": V0,
                "intrinseco": float(max(V0 - K1, 0.0) if is_call else max(K1 - V0, 0.0))})
    h = 0.01
    p_up, _, _ = _prezzo(F * (1 + h), sd)
    p_dn, _, _ = _prezzo(F * (1 - h), sd)
    out["delta"] = float((p_up - p_dn) / (2 * F * h))

    # F_star: prezzo forward critico a t1 (esercizio ottimale)
    if t1 > 0.0 and Trem >= 0.0:
        def _V1(x):
            return float(_b76(x, K2, Trem, sott_call)) - K1
        try:
            if is_call and sott_call and K1 == 0.0:
                out["f_star"] = 0.0
            else:
                hi = F * np.exp(10 * sig * np.sqrt(max(t1, 1e-9)) + 5)
                out["f_star"] = float(_brentq(_V1, 1e-8, hi, maxiter=200))
        except Exception:
            out["f_star"] = float("nan")
    return out


def calcola_digitale(payoff, tipo, forward, strike, mesi, vol_pct, tasso_pct):
    """Premio di un'opzione DIGITALE (binaria) sul forward energetico, Black-76 forma chiusa.

    La digitale paga un importo FISSO se a scadenza la condizione e' vera,
    zero altrimenti — niente gamma progressiva: o tutto o niente.
    - cash-or-nothing call: 1 EUR/MWh se F_T > K, 0 altrimenti (put: se F_T < K)
    - asset-or-nothing call: F_T se F_T > K, 0 altrimenti (put: F_T se F_T < K)
    Nell'energia servono nei contratti di fornitura con trigger di prezzo
    (es. bonus/malus forfettario se il prezzo supera una soglia), nelle
    clausole cap con payout secco e per coprire eventi prezzo discreti.
    Formule Black-76 (driftless sul forward):
      cash call = df * N(d2) · cash put = df * N(-d2)
      asset call = df * F * N(d1) · asset put = df * F * N(-d1)
      d1 = (ln(F/K) + 0.5*sig^2*T) / (sig*sqrt(T)); d2 = d1 - sig*sqrt(T)
    Ancore esatte: parita' call+put cash = df, call+put asset = df*F;
    vol = 0 o T = 0 -> valore attualizzato del payout deterministico;
    K -> 0: cash call -> df, asset call -> df*F. NaN-safe: input non validi
    (tipo/payoff sconosciuti, F <= 0, K <= 0, mesi < 0, sig < 0, r < 0)
    -> dict neutro con valido = False.
    Ritorna dict con: premio, premio_vanilla (stessa call/put Black-76),
    prob_itm (probabilita' risk-neutral di finire in the money = N(+-d2)),
    delta (bump sul forward), intrinseco (valore del payout a F=K? no:
    valore digitale a scadenza se esercitata OGGI: cash 1/0, asset F/0),
    limite_sup (df per cash, df*F per asset), valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio": float("nan"), "premio_vanilla": float("nan"),
              "prob_itm": float("nan"), "delta": float("nan"),
              "intrinseco": float("nan"), "limite_sup": float("nan"),
              "valido": False}
    try:
        pf = str(payoff).strip().lower()
        tp = str(tipo).strip().lower()
        F = float(forward); K = float(strike); T = float(mesi) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r)):
        return neutro
    if pf not in ("cash", "asset") or tp not in ("call", "put"):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    is_call = (tp == "call")
    df = float(np.exp(-r * T))
    limite = df if pf == "cash" else df * F

    def _premio(ff):
        # premio digitale valutato al forward ff
        if T <= 0.0 or sig <= 0.0:
            itm = (ff > K) if is_call else (ff < K)
            at = (ff == K)
            unit = 0.5 if at else (1.0 if itm else 0.0)
            return df * unit if pf == "cash" else df * ff * unit
        sqt = sig * np.sqrt(T)
        d1 = (np.log(ff / K) + 0.5 * sig * sig * T) / sqt
        d2 = d1 - sqt
        if pf == "cash":
            return df * (_norm.cdf(d2) if is_call else _norm.cdf(-d2))
        return df * ff * (_norm.cdf(d1) if is_call else _norm.cdf(-d1))

    def _vanilla(ff):
        # premio call/put vanilla Black-76 di confronto
        if T <= 0.0 or sig <= 0.0:
            intr = max(ff - K, 0.0) if is_call else max(K - ff, 0.0)
            return df * intr
        sqt = sig * np.sqrt(T)
        d1 = (np.log(ff / K) + 0.5 * sig * sig * T) / sqt
        d2 = d1 - sqt
        if is_call:
            return df * (ff * _norm.cdf(d1) - K * _norm.cdf(d2))
        return df * (K * _norm.cdf(-d2) - ff * _norm.cdf(-d1))

    def _prob(ff):
        # prob. risk-neutral di finire ITM
        if T <= 0.0 or sig <= 0.0:
            return 0.5 if ff == K else (1.0 if (ff > K) == is_call else 0.0)
        sqt = sig * np.sqrt(T)
        d2 = (np.log(ff / K) + 0.5 * sig * sig * T) / sqt - sqt
        return float(_norm.cdf(d2) if is_call else _norm.cdf(-d2))

    out = dict(neutro)
    out.update({"valido": True, "premio": float(_premio(F)),
                "premio_vanilla": float(_vanilla(F)),
                "prob_itm": _prob(F),
                "limite_sup": float(limite)})
    if pf == "cash":
        out["intrinseco"] = 1.0 if (F > K) == is_call else 0.0
    else:
        out["intrinseco"] = float(F) if (F > K) == is_call else 0.0
    h = 0.01
    out["delta"] = float((_premio(F * (1 + h)) - _premio(F * (1 - h))) / (2 * F * h))
    return out

def calcola_chooser(forward, strike, mesi_scelta, mesi_scadenza, vol_pct, tasso_pct):
    """Premio di un'opzione CHOOSER semplice sul forward energetico (forma chiusa di Rubinstein).

    La chooser scade a T2 ma a una data di SCELTA t1 <= T2 il detentore decide
    se tenerla come call o come put (stesso strike K, stessa scadenza T2):
    valore a t1 = max(C(t1), P(t1)), dove C/P sono i valori Black-76 con vita
    residua T2-t1. Nell'energia serve a comprare oggi l'optionalita' sulla
    DIREZIONE del prezzo prima di un evento noto a data certa (asta di
    capacita', decisione regolatoria, stagione meteo): a t1, se il forward
    supera K si prende la call, altrimenti la put. Costa meno di uno straddle
    perche' a t1 se ne esercita una sola gamba invece di pagarle due oggi.
    Formule (Rubinstein 1991, forward driftless, r = risk-free):
      chooser = C(F, K, T2) + exp(-r*(T2-t1)) * P(F, K, t1)
    con C/P = call/put Black-76 (vedi calcola_black76). Intuizione: il primo
    termine e' il valore atteso della call a T2; il secondo e' l'extra dato
    dalla possibilita' di ripiegare sulla put (per parita' C-P = df*(F-K), a
    t1 si sceglie la call sse F(t1) > K, quindi la prob. risk-neutral di
    scegliere la call e' N(d2(F, K, t1))).
    Ancore esatte: t1 = 0 -> max(call, put) a T2 (scelta immediata); t1 = T2 ->
    call + put = straddle (a scadenza una gamba vale zero e l'altra |F-K|);
    vol = 0 -> df(T2)*|F-K| (deterministico); il premio e' sempre compreso tra
    max(call, put) e straddle, e cresce con la data di scelta t1.
    NaN-safe: input non validi (F <= 0, K <= 0, mesi < 0, t1 > T2, vol/tasso
    < 0, NaN, stringhe) -> dict neutro con valido = False.
    Ritorna dict con: premio, call, put (vanilla Black-76 a T2), straddle,
    risparmio_vs_straddle, prob_scelta_call, delta (bump sul forward),
    intrinseco (df*|F-K|), valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio": float("nan"), "call": float("nan"), "put": float("nan"),
              "straddle": float("nan"), "risparmio_vs_straddle": float("nan"),
              "prob_scelta_call": float("nan"), "delta": float("nan"),
              "intrinseco": float("nan"), "valido": False}
    try:
        F = float(forward); K = float(strike)
        t1 = float(mesi_scelta) / 12.0; T2 = float(mesi_scadenza) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, t1, T2, sig, r)):
        return neutro
    if F <= 0 or K <= 0 or t1 < 0 or T2 <= 0 or t1 > T2:
        return neutro
    if sig < 0 or r < 0:
        return neutro

    def _b76(ff, kk, tt, cp):
        # Black-76 scalare; cp True = call, False = put
        dff = float(np.exp(-r * tt))
        if tt <= 0.0 or sig <= 0.0:
            intr = max(ff - kk, 0.0) if cp else max(kk - ff, 0.0)
            return dff * intr
        sqt = sig * np.sqrt(tt)
        d1 = (np.log(ff / kk) + 0.5 * sig * sig * tt) / sqt
        d2 = d1 - sqt
        if cp:
            return dff * (ff * _norm.cdf(d1) - kk * _norm.cdf(d2))
        return dff * (kk * _norm.cdf(-d2) - ff * _norm.cdf(-d1))

    def _premio(ff):
        cc = _b76(ff, K, T2, True)
        pp = _b76(ff, K, t1, False)
        return cc + float(np.exp(-r * (T2 - t1))) * pp

    C = _b76(F, K, T2, True)
    P = _b76(F, K, T2, False)
    straddle = C + P
    premio = _premio(F)
    if t1 > 0.0 and sig > 0.0:
        sqt1 = sig * np.sqrt(t1)
        d2t1 = (np.log(F / K) + 0.5 * sig * sig * t1) / sqt1 - sqt1
        prob_c = float(_norm.cdf(d2t1))
    else:
        prob_c = 0.5 if F == K else (1.0 if F > K else 0.0)
    out = dict(neutro)
    out.update({"valido": True, "premio": float(premio), "call": float(C),
                "put": float(P), "straddle": float(straddle),
                "risparmio_vs_straddle": float(straddle - premio),
                "prob_scelta_call": prob_c,
                "intrinseco": float(np.exp(-r * T2) * abs(F - K))})
    h = 0.01
    out["delta"] = float((_premio(F * (1 + h)) - _premio(F * (1 - h))) / (2 * F * h))
    return out


def calcola_forward_start(forward, alfa_pct, mesi_inizio, mesi_scadenza, vol_pct, tasso_pct):
    """Premio di un'opzione FORWARD START europea sul forward energetico (forma chiusa).

    La forward start scade a T2 ma la sua vita inizia a una data futura t1
    (0 <= t1 <= T2): a t1 lo strike viene fissato in modo proporzionale al
    prezzo di mercato, K = alfa * F(t1) (alfa = moneyness, tipicamente 100% =
    ATM). Da t1 a T2 e' una vanilla europea Black-76 con strike fisso alfa *
    F(t1). Nell'energia serve a comprare oggi un'assicurazione sul prezzo
    FUTURO senza fissare lo strike a livelli correnti: es. un consumatore
    che a gennaio vuole proteggere il Q4 ma non vuole ancorare lo strike
    al forward di oggi, o un produttore che vuole una floor che parta
    at-the-money solo dopo l'estate. Costa meno della vanilla con strike
    fisso alfa * F(0) perche' rinuncia all'optionalita' sul periodo [0, t1]
    (il premio decresce con t1).
    Formula (forward driftless, vol costante, r = risk-free, tau = T2 - t1):
      d1* = (-ln(alfa) + 0.5*sig^2*tau) / (sig*sqrt(tau)); d2* = d1* - sig*sqrt(tau)
      call_fs = df(T2) * F * (N(d1*) - alfa*N(d2*))
      put_fs  = df(T2) * F * (alfa*N(-d2*) - N(-d1*))
    Derivazione: condizionando a F(t1), il payoff atteso e' il prezzo
    Black-76 di una vanilla con forward F(t1) e strike alfa*F(t1), cioe'
    F(t1)*(N(d1*) - alfa*N(d2*)); prendendo l'attesa su F(t1) (martingala,
    E[F(t1)] = F, indipendenza degli incrementi) si ottiene la forma chiusa.
    Ancore esatte: t1 = 0 -> vanilla Black-76 con strike alfa*F(0);
    t1 = T2 -> premio 0 (nessuna vita residua); vol = 0 -> deterministico
    df(T2)*F*max(1-alfa,0) per la call, df(T2)*F*max(alfa-1,0) per la put;
    parita' call-put esatta: call_fs - put_fs = df(T2)*F*(1-alfa);
    call_fs <= vanilla call con strike alfa*F (concavita' in F);
    prob. risk-neutral di finire ITM: call -> N(d2*), put -> N(-d2*);
    delta analitica: call -> df(T2)*(N(d1*) - alfa*N(d2*)) (coincide con
    premio/F), put -> df(T2)*(alfa*N(-d2*) - N(-d1*)) (positiva: lo strike
    scala con F, quindi la put forward start cresce con il forward).
    NaN-safe: input non validi (F <= 0, alfa <= 0, t1 < 0, T2 <= 0,
    t1 > T2, vol/tasso < 0, NaN, stringhe) -> dict neutro con valido = False.
    Ritorna dict con: premio_call, premio_put, vanilla_call, vanilla_put
    (vanilla Black-76 a T2 con strike alfa*F di confronto), diff_vs_vanilla
    (vanilla - fs) per call e put, parita_diff (scostamento dalla parita'
    esatta, ~0), prob_itm_call/put, delta_call/put, intrinseco_vol0_call/put,
    strike_atteso (alfa*F), valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio_call": float("nan"), "premio_put": float("nan"),
              "vanilla_call": float("nan"), "vanilla_put": float("nan"),
              "diff_vs_vanilla_call": float("nan"),
              "diff_vs_vanilla_put": float("nan"),
              "parita_diff": float("nan"),
              "prob_itm_call": float("nan"), "prob_itm_put": float("nan"),
              "delta_call": float("nan"), "delta_put": float("nan"),
              "intrinseco_vol0_call": float("nan"),
              "intrinseco_vol0_put": float("nan"),
              "strike_atteso": float("nan"), "valido": False}
    try:
        F = float(forward); alfa = float(alfa_pct) / 100.0
        t1 = float(mesi_inizio) / 12.0; T2 = float(mesi_scadenza) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, alfa, t1, T2, sig, r)):
        return neutro
    if F <= 0 or alfa <= 0 or t1 < 0 or T2 <= 0 or t1 > T2:
        return neutro
    if sig < 0 or r < 0:
        return neutro

    df2 = float(np.exp(-r * T2))
    tau = T2 - t1

    def _b76(ff, kk, tt, cp):
        # Black-76 scalare; cp True = call, False = put
        dff = float(np.exp(-r * tt))
        if tt <= 0.0 or sig <= 0.0:
            intr = max(ff - kk, 0.0) if cp else max(kk - ff, 0.0)
            return dff * intr
        sqt = sig * np.sqrt(tt)
        d1 = (np.log(ff / kk) + 0.5 * sig * sig * tt) / sqt
        d2 = d1 - sqt
        if cp:
            return dff * (ff * _norm.cdf(d1) - kk * _norm.cdf(d2))
        return dff * (kk * _norm.cdf(-d2) - ff * _norm.cdf(-d1))

    K = alfa * F
    van_c = _b76(F, K, T2, True)
    van_p = _b76(F, K, T2, False)

    if sig <= 0.0:
        # deterministico: F(t1) = F, strike = alfa*F
        pc = df2 * F * max(1.0 - alfa, 0.0)
        pp = df2 * F * max(alfa - 1.0, 0.0)
        prob_c = 1.0 if alfa < 1.0 else (0.5 if alfa == 1.0 else 0.0)
        dc = df2 if alfa < 1.0 else 0.0
        dp = df2 if alfa > 1.0 else 0.0
    elif tau <= 0.0:
        # t1 = T2 con vol > 0: opzione morta, nessun valore temporale
        pc = pp = 0.0
        prob_c = 1.0 if alfa < 1.0 else (0.5 if alfa == 1.0 else 0.0)
        dc = df2 * (1.0 - alfa) if alfa < 1.0 else 0.0
        dp = df2 * (alfa - 1.0) if alfa > 1.0 else 0.0
    else:
        sqtau = sig * np.sqrt(tau)
        d1s = (-np.log(alfa) + 0.5 * sig * sig * tau) / sqtau
        d2s = d1s - sqtau
        nd1 = float(_norm.cdf(d1s)); nd2 = float(_norm.cdf(d2s))
        nmd1 = 1.0 - nd1; nmd2 = 1.0 - nd2
        pc = df2 * F * (nd1 - alfa * nd2)
        pp = df2 * F * (alfa * nmd2 - nmd1)
        prob_c = float(_norm.cdf(d2s))
        dc = df2 * (nd1 - alfa * nd2)
        dp = df2 * (alfa * nmd2 - nmd1)
    prob_p = 1.0 - prob_c

    out = dict(neutro)
    out.update({"valido": True, "premio_call": float(pc), "premio_put": float(pp),
                "vanilla_call": float(van_c), "vanilla_put": float(van_p),
                "diff_vs_vanilla_call": float(van_c - pc),
                "diff_vs_vanilla_put": float(van_p - pp),
                "parita_diff": float((pc - pp) - df2 * F * (1.0 - alfa)),
                "prob_itm_call": float(prob_c), "prob_itm_put": float(prob_p),
                "delta_call": float(dc), "delta_put": float(dp),
                "intrinseco_vol0_call": float(df2 * F * max(1.0 - alfa, 0.0)),
                "intrinseco_vol0_put": float(df2 * F * max(alfa - 1.0, 0.0)),
                "strike_atteso": float(K)})
    return out


def calcola_quanto(forward, strike, mesi, vol_sott_pct, vol_cambio_pct, corr, tasso_pct, cambio=1.0):
    """Premio di un'opzione QUANTO europea sul forward energetico (forma chiusa).

    La QUANTO e' un'opzione su un sottostante denominato in VALUTA ESTERA il
    cui payoff viene convertito in valuta domestica a un TASSO DI CAMBIO
    FISSO X (niente rischio cambio sul payout). Nell'energia e' lo strumento
    standard dei prodotti cross-border e dei quanto "temperatura x prezzo":
    es. un'opzione sul forward power tedesco (EUR) regolata in CHF a cambio
    fisso, oppure un'opzione sul prezzo con sottostante indice climatico.
    Il pricing corregge il forward con il fattore quanto
      Fq = F * exp(-rho * sigS * sigX * T)
    (rho = correlazione sottostante/cambio, sigS = vol sottostante,
    sigX = vol cambio): se sottostante e cambio si muovono insieme
    (rho > 0), il forward quanto scende e la call vale meno della vanilla.
    Formule Black-76 sul forward corretto:
      d1 = (ln(Fq/K) + 0.5*sigS^2*T) / (sigS*sqrt(T)); d2 = d1 - sigS*sqrt(T)
      call = X * df * (Fq*N(d1) - K*N(d2))
      put  = X * df * (K*N(-d2) - Fq*N(-d1))
    Derivazione: sotto la misura risk-neutral domestica il forward estero
    ha drift -rho*sigS*sigX (aggiustamento di cambio numeraire), quindi il
    suo valore atteso e' Fq; condizionando, il prezzo e' Black-76 sul
    forward corretto con cambio fisso X.
    Ancore esatte: rho = 0 o sigX = 0 -> vanilla Black-76 su F (x X);
    sigS = 0 o T = 0 -> X*df*max(+- (Fq-K), 0) con Fq = F;
    parita' call-put esatta: call - put = X*df*(Fq - K);
    prob. risk-neutral di finire ITM: call -> N(d2), put -> N(-d2);
    delta sul forward estero: call -> X*df*exp(-rho*sigS*sigX*T)*N(d1),
    put -> X*df*exp(-rho*sigS*sigX*T)*(N(d1) - 1).
    NaN-safe: input non validi (F <= 0, K <= 0, T < 0, vol < 0, |rho| > 1,
    X <= 0, r < 0, NaN, stringhe) -> dict neutro con valido = False.
    Ritorna dict con: premio_call, premio_put, vanilla_call, vanilla_put
    (Black-76 con rho = 0 di confronto), diff_vs_vanilla_call/put,
    parita_diff (~0), fattore_quanto (exp(-rho*sigS*sigX*T)),
    forward_quanto (Fq), prob_itm_call/put, delta_call/put (sul forward
    estero, in valuta domestica per unita' di F), intrinseco_vol0_call/put,
    valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio_call": float("nan"), "premio_put": float("nan"),
              "vanilla_call": float("nan"), "vanilla_put": float("nan"),
              "diff_vs_vanilla_call": float("nan"),
              "diff_vs_vanilla_put": float("nan"),
              "parita_diff": float("nan"),
              "fattore_quanto": float("nan"), "forward_quanto": float("nan"),
              "prob_itm_call": float("nan"), "prob_itm_put": float("nan"),
              "delta_call": float("nan"), "delta_put": float("nan"),
              "intrinseco_vol0_call": float("nan"),
              "intrinseco_vol0_put": float("nan"), "valido": False}
    try:
        F = float(forward); K = float(strike); T = float(mesi) / 12.0
        sigS = float(vol_sott_pct) / 100.0; sigX = float(vol_cambio_pct) / 100.0
        rho = float(corr); r = float(tasso_pct) / 100.0; X = float(cambio)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sigS, sigX, rho, r, X)):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or X <= 0:
        return neutro
    if sigS < 0 or sigX < 0 or r < 0 or abs(rho) > 1:
        return neutro

    df = float(np.exp(-r * T))
    adj = float(np.exp(-rho * sigS * sigX * T))
    Fq = F * adj

    def _van(ff):
        # vanilla Black-76 sul forward ff (confronto: rho = 0 -> ff = F)
        if T <= 0.0 or sigS <= 0.0:
            intr_c = max(ff - K, 0.0); intr_p = max(K - ff, 0.0)
            return X * df * intr_c, X * df * intr_p
        sqt = sigS * np.sqrt(T)
        d1v = (np.log(ff / K) + 0.5 * sigS * sigS * T) / sqt
        d2v = d1v - sqt
        vc = X * df * (ff * _norm.cdf(d1v) - K * _norm.cdf(d2v))
        vp = X * df * (K * _norm.cdf(-d2v) - ff * _norm.cdf(-d1v))
        return vc, vp

    van_c, van_p = _van(F)

    if T <= 0.0 or sigS <= 0.0:
        # deterministico: Fq = F (adj = 1 se sigS = 0)
        pc = X * df * max(Fq - K, 0.0)
        pp = X * df * max(K - Fq, 0.0)
        prob_c = 0.5 if Fq == K else (1.0 if Fq > K else 0.0)
        dc = X * df * adj if Fq > K else 0.0
        dp = -X * df * adj if Fq < K else 0.0
    else:
        sqt = sigS * np.sqrt(T)
        d1 = (np.log(Fq / K) + 0.5 * sigS * sigS * T) / sqt
        d2 = d1 - sqt
        nd1 = float(_norm.cdf(d1)); nd2 = float(_norm.cdf(d2))
        nmd1 = 1.0 - nd1; nmd2 = 1.0 - nd2
        pc = X * df * (Fq * nd1 - K * nd2)
        pp = X * df * (K * nmd2 - Fq * nmd1)
        prob_c = float(_norm.cdf(d2))
        dc = X * df * adj * nd1
        dp = X * df * adj * (nd1 - 1.0)
    prob_p = 1.0 - prob_c

    out = dict(neutro)
    out.update({"valido": True, "premio_call": float(pc), "premio_put": float(pp),
                "vanilla_call": float(van_c), "vanilla_put": float(van_p),
                "diff_vs_vanilla_call": float(van_c - pc),
                "diff_vs_vanilla_put": float(van_p - pp),
                "parita_diff": float((pc - pp) - X * df * (Fq - K)),
                "fattore_quanto": float(adj), "forward_quanto": float(Fq),
                "prob_itm_call": float(prob_c), "prob_itm_put": float(prob_p),
                "delta_call": float(dc), "delta_put": float(dp),
                "intrinseco_vol0_call": float(X * df * max(F - K, 0.0)),
                "intrinseco_vol0_put": float(X * df * max(K - F, 0.0))})
    return out


def calcola_rainbow(s1, s2, strike, mesi, vol1_pct, vol2_pct, corr, tasso_pct, tipo="call_max"):
    """Premio di un'opzione RAINBOW europea su due forward energetici (formula chiusa di Stulz 1982).

    La RAINBOW e' un'opzione sul MIGLIORE (best-of, max) o sul PEGGIORE
    (worst-of, min) tra due sottostanti: call sul max = max(max(S1,S2)-K,0),
    put sul max, call sul min, put sul min. Nell'energia e' lo strumento
    naturale di due problemi ricorrenti: (1) la capacita' di
    interconnessione/transito, che vale il diritto di vendere sul mercato
    col prezzo piu' alto (best-of tra due hub); (2) il fuel switching, dove
    il costo e' il combustibile piu' economico (worst-of tra due fuel).
    Il driver chiave, oltre alle vol, e' la CORRELAZIONE: se i due prezzi si
    muovono insieme il best-of vale poco piu' della vanilla migliore, se si
    muovono per conto loro il premio esplode.
    Formule (convenzione forward: S1, S2 sono prezzi forward, quindi
    martingale; df = exp(-r*T)):
      sig^2 = v1^2+v2^2-2*rho*v1*v2
      y1 = (ln(S1/K)-v1^2*T/2)/(v1*sqrt(T))          [stile d2]
      y2 = (ln(S2/K)-v2^2*T/2)/(v2*sqrt(T))
      d   = (ln(S1/S2)+sig^2*T/2)/(sig*sqrt(T))      (soglia sotto Q1)
      d2s = (ln(S2/S1)+sig^2*T/2)/(sig*sqrt(T))
      e1  = (ln(S1/S2)-(v1^2-v2^2)*T/2)/(sig*sqrt(T)) (soglia sotto Q)
      e2  = -e1
      r1 = (v1-rho*v2)/sig;  r2 = (v2-rho*v1)/sig
      M(a,b;r) = CDF normale bivariata standard
      E[max] = S1*N(d)+S2*N(d2s)
      call_max = df*(S1*M(y1+v1*sqrt(T),d;r1)+S2*M(y2+v2*sqrt(T),d2s;r2)
                     -K*(M(y1,e1;r1)+M(y2,e2;r2)))
      put_max  = call_max - df*(E[max]-K)            (parita' esatta)
      call_min = BS_call(S1)+BS_call(S2)-call_max    (max+min = S1+S2)
      put_min  = BS_put(S1)+BS_put(S2)-put_max
      E[min]   = S1+S2-E[max]
    Delta analitici con derivate complete dei termini bivariati (la
    scomposizione asset-or-nothing/cash-or-nothing NON si semplifica perche'
    i due pezzi vivono sotto misure diverse, Q1/Q2 vs Q):
      dE[max]/dS1 = N(d)+phi(d)/(sig*sqrt(T))-S2*phi(d2s)/(S1*sig*sqrt(T))
      dput_max = dcall_max - df*dE[max]/dS   (dalla parita')
      dcall_min = dBS - dcall_max;  dput_min = dcall_min - df*(1-dE[max]/dS)
    Casi degeneri esatti: T=0 -> intrinseco; v1=v2=0 -> df*intrinseco;
    sig~0 (rho=+-1 e v1=v2) -> vanilla Black-76 sul max/min; v1=0 o v2=0 ->
    formule chiuse col sottostante deterministico.
    NaN-safe: input non validi -> dict neutro con valido=False.
    Ritorna dict con: premio, delta_s1, delta_s2, fwd_maxmin (E[max]/E[min]),
    intrinseco, vanilla_s1, vanilla_s2 (Black-76 di confronto),
    extra_vs_vanilla (premio - max delle vanille), parita_diff (~0), valido.
    Verifiche: cross-check Monte Carlo con antitetiche su 5 set di parametri,
    ancore esatte T=0/vol=0/S2->0->vanilla, parita', identita' min, delta vs
    bump, bound di arbitraggio call_max <= somma vanille
    (vedi hidden_files/test_rainbow_2026-09-30_1940.py)."""
    from scipy.stats import multivariate_normal as _mvn
    from scipy.stats import norm as _norm

    def _bvn(a, b, r):
        rr = min(max(float(r), -1.0 + 1e-9), 1.0 - 1e-9)
        return float(_mvn.cdf([float(a), float(b)], mean=[0.0, 0.0],
                              cov=[[1.0, rr], [rr, 1.0]]))

    def _bs(F, K, T, v, r):
        """Black-76 sul forward: (call, put, delta_call, delta_put, d1, d2)."""
        df_ = float(np.exp(-r * T))
        ic = max(F - K, 0.0)
        ip = max(K - F, 0.0)
        if T <= 0.0 or v <= 0.0:
            dc = df_ if F > K else 0.0
            dp = -df_ if F < K else 0.0
            return df_ * ic, df_ * ip, dc, dp, float("nan"), float("nan")
        sqt = v * np.sqrt(T)
        d1 = (np.log(F / K) + 0.5 * v * v * T) / sqt
        d2 = d1 - sqt
        c = df_ * (F * float(_norm.cdf(d1)) - K * float(_norm.cdf(d2)))
        p = df_ * (K * float(_norm.cdf(-d2)) - F * float(_norm.cdf(-d1)))
        return (c, p, df_ * float(_norm.cdf(d1)),
                -df_ * float(_norm.cdf(-d1)), d1, d2)

    neutro = {"premio": float("nan"), "delta_s1": float("nan"),
              "delta_s2": float("nan"), "fwd_maxmin": float("nan"),
              "intrinseco": float("nan"), "vanilla_s1": float("nan"),
              "vanilla_s2": float("nan"), "extra_vs_vanilla": float("nan"),
              "parita_diff": float("nan"), "valido": False}
    try:
        S1 = float(s1)
        S2 = float(s2)
        K = float(strike)
        T = float(mesi) / 12.0
        v1 = float(vol1_pct) / 100.0
        v2 = float(vol2_pct) / 100.0
        rho = float(corr)
        r = float(tasso_pct) / 100.0
        tipo = str(tipo)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (S1, S2, K, T, v1, v2, rho, r)):
        return neutro
    if (S1 <= 0 or S2 <= 0 or K <= 0 or T < 0 or v1 < 0 or v2 < 0
            or abs(rho) > 1 or r < 0
            or tipo not in ("call_max", "put_max", "call_min", "put_min")):
        return neutro

    df = float(np.exp(-r * T))
    M0 = max(S1, S2)
    m0 = min(S1, S2)
    is_max = tipo.endswith("max")
    is_call = tipo.startswith("call")
    base = M0 if is_max else m0
    intr = max(base - K, 0.0) if is_call else max(K - base, 0.0)

    c1, p1, dc1, dp1, _, _ = _bs(S1, K, T, v1, r)
    c2, p2, dc2, dp2, _, _ = _bs(S2, K, T, v2, r)

    cmax = pmax = cmin = pmin = float("nan")
    Emax = Emin = float("nan")
    d1_cmax = d2_cmax = d1_pmax = d2_pmax = float("nan")
    d1_cmin = d2_cmin = d1_pmin = d2_pmin = float("nan")

    if T == 0.0:
        cmax = max(M0 - K, 0.0)
        pmax = max(K - M0, 0.0)
        cmin = max(m0 - K, 0.0)
        pmin = max(K - m0, 0.0)
        Emax, Emin = M0, m0
        b1 = 1.0 if S1 >= S2 else 0.0
        b2 = 1.0 - b1
        w1 = 1.0 if S1 <= S2 else 0.0
        w2 = 1.0 - w1
        d1_cmax = b1 if S1 > K else 0.0
        d2_cmax = b2 if S2 > K else 0.0
        d1_pmax = -b1 if S1 < K else 0.0
        d2_pmax = -b2 if S2 < K else 0.0
        d1_cmin = w1 if S1 > K else 0.0
        d2_cmin = w2 if S2 > K else 0.0
        d1_pmin = -w1 if S1 < K else 0.0
        d2_pmin = -w2 if S2 < K else 0.0
    elif v1 == 0.0 and v2 == 0.0:
        cmax = df * max(M0 - K, 0.0)
        pmax = df * max(K - M0, 0.0)
        cmin = df * max(m0 - K, 0.0)
        pmin = df * max(K - m0, 0.0)
        Emax, Emin = M0, m0
        b1 = 1.0 if S1 >= S2 else 0.0
        b2 = 1.0 - b1
        w1 = 1.0 if S1 <= S2 else 0.0
        w2 = 1.0 - w1
        d1_cmax = df * b1 if S1 > K else 0.0
        d2_cmax = df * b2 if S2 > K else 0.0
        d1_pmax = -df * b1 if S1 < K else 0.0
        d2_pmax = -df * b2 if S2 < K else 0.0
        d1_cmin = df * w1 if S1 > K else 0.0
        d2_cmin = df * w2 if S2 > K else 0.0
        d1_pmin = -df * w1 if S1 < K else 0.0
        d2_pmin = -df * w2 if S2 < K else 0.0
    else:
        sig2 = v1 * v1 + v2 * v2 - 2.0 * rho * v1 * v2
        sig = float(np.sqrt(max(sig2, 0.0)))
        if sig < 1e-12:
            # rho = +-1 e v1 = v2: i due forward si muovono identici ->
            # max/min e' un singolo lognormale sul max/min iniziale.
            v = 0.5 * (v1 + v2)
            cc, pp, dcc, dpp, _, _ = _bs(M0, K, T, v, r)
            cmax, pmax = cc, pp
            Emax = M0
            i1 = 1.0 if S1 >= S2 else 0.0
            i2 = 1.0 - i1
            d1_cmax, d2_cmax = dcc * i1, dcc * i2
            d1_pmax, d2_pmax = dcc * i1 - df * i1, dcc * i2 - df * i2
            cmin = c1 + c2 - cmax
            pmin = p1 + p2 - pmax
            Emin = S1 + S2 - Emax
            d1_cmin = dc1 - d1_cmax
            d2_cmin = dc2 - d2_cmax
            d1_pmin = d1_cmin - df * (1.0 - i1)
            d2_pmin = d2_cmin - df * (1.0 - i2)
        elif v1 == 0.0 or v2 == 0.0:
            # Un sottostante deterministico (Sd), l'altro lognormale (Ss).
            if v1 == 0.0:
                Sd, Ss, vs, swap = S1, S2, v2, False
            else:
                Sd, Ss, vs, swap = S2, S1, v1, True
            ks = max(Sd, K)
            bs_ks = _bs(Ss, ks, T, vs, r)
            bs_sd = _bs(Ss, Sd, T, vs, r)
            cmax = df * max(Sd - K, 0.0) + bs_ks[0]
            Emax = Sd + bs_sd[0] / df
            pmax = cmax - df * (Emax - K)
            cmin = c1 + c2 - cmax
            pmin = p1 + p2 - pmax
            Emin = S1 + S2 - Emax
            nd2_sd = float(_norm.cdf(bs_sd[5]))
            nd1_sd = float(_norm.cdf(bs_sd[4]))
            dd_cmax = df * (1.0 - nd2_sd) if Sd >= K else 0.0
            ds_cmax = bs_ks[2]
            ed_d = 1.0 - nd2_sd
            ed_s = nd1_sd
            dd_pmax = dd_cmax - df * ed_d
            ds_pmax = ds_cmax - df * ed_s
            if not swap:
                d1_cmax, d2_cmax = dd_cmax, ds_cmax
                d1_pmax, d2_pmax = dd_pmax, ds_pmax
                d1_cmin = dc1 - d1_cmax
                d2_cmin = dc2 - d2_cmax
                d1_pmin = d1_cmin - df * (1.0 - ed_d)
                d2_pmin = d2_cmin - df * (1.0 - ed_s)
            else:
                d2_cmax, d1_cmax = dd_cmax, ds_cmax
                d2_pmax, d1_pmax = dd_pmax, ds_pmax
                d1_cmin = dc1 - d1_cmax
                d2_cmin = dc2 - d2_cmax
                d1_pmin = d1_cmin - df * (1.0 - ed_s)
                d2_pmin = d2_cmin - df * (1.0 - ed_d)
        else:
            sqT = float(np.sqrt(T))
            sqt1 = v1 * sqT
            sqt2 = v2 * sqT
            sqtS = sig * sqT
            y1 = (float(np.log(S1 / K)) - 0.5 * v1 * v1 * T) / sqt1
            y2 = (float(np.log(S2 / K)) - 0.5 * v2 * v2 * T) / sqt2
            d_ = (float(np.log(S1 / S2)) + 0.5 * sig * sig * T) / sqtS
            d2s = (float(np.log(S2 / S1)) + 0.5 * sig * sig * T) / sqtS
            e1 = (float(np.log(S1 / S2)) - 0.5 * (v1 * v1 - v2 * v2) * T) / sqtS
            e2 = -e1
            r1 = (v1 - rho * v2) / sig
            r2 = (v2 - rho * v1) / sig
            Ma = _bvn(y1 + sqt1, d_, r1)
            Mb = _bvn(y2 + sqt2, d2s, r2)
            Mq1 = _bvn(y1, e1, r1)
            Mq2 = _bvn(y2, e2, r2)
            nd = float(_norm.cdf(d_))
            nd2s = float(_norm.cdf(d2s))
            Emax = S1 * nd + S2 * nd2s
            cmax = df * (S1 * Ma + S2 * Mb - K * (Mq1 + Mq2))
            pmax = cmax - df * (Emax - K)
            cmin = c1 + c2 - cmax
            pmin = p1 + p2 - pmax
            Emin = S1 + S2 - Emax
            s1q = float(np.sqrt(max(1.0 - r1 * r1, 1e-24)))
            s2q = float(np.sqrt(max(1.0 - r2 * r2, 1e-24)))
            ph = _norm.pdf
            N = _norm.cdf
            if s1q > 1e-4 and s2q > 1e-4:
                dMa_dS1 = (ph(y1 + sqt1) * N((d_ - r1 * (y1 + sqt1)) / s1q) / (S1 * sqt1)
                           + ph(d_) * N((y1 + sqt1 - r1 * d_) / s1q) / (S1 * sqtS))
                dMq1_dS1 = (ph(y1) * N((e1 - r1 * y1) / s1q) / (S1 * sqt1)
                            + ph(e1) * N((y1 - r1 * e1) / s1q) / (S1 * sqtS))
                dT1dS1 = df * (Ma + S1 * dMa_dS1 - K * dMq1_dS1)
                dMa_dS2 = ph(d_) * N((y1 + sqt1 - r1 * d_) / s1q) * (-1.0 / (S2 * sqtS))
                dMq1_dS2 = ph(e1) * N((y1 - r1 * e1) / s1q) * (-1.0 / (S2 * sqtS))
                dT1dS2 = df * (S1 * dMa_dS2 - K * dMq1_dS2)
                dMb_dS2 = (ph(y2 + sqt2) * N((d2s - r2 * (y2 + sqt2)) / s2q) / (S2 * sqt2)
                           + ph(d2s) * N((y2 + sqt2 - r2 * d2s) / s2q) / (S2 * sqtS))
                dMq2_dS2 = (ph(y2) * N((e2 - r2 * y2) / s2q) / (S2 * sqt2)
                            + ph(e2) * N((y2 - r2 * e2) / s2q) / (S2 * sqtS))
                dT2dS2 = df * (Mb + S2 * dMb_dS2 - K * dMq2_dS2)
                dMb_dS1 = ph(d2s) * N((y2 + sqt2 - r2 * d2s) / s2q) * (-1.0 / (S1 * sqtS))
                dMq2_dS1 = ph(e2) * N((y2 - r2 * e2) / s2q) * (-1.0 / (S1 * sqtS))
                dT2dS1 = df * (S2 * dMb_dS1 - K * dMq2_dS1)
                dE_dS1 = nd + ph(d_) / sqtS - S2 * ph(d2s) / (S1 * sqtS)
                dE_dS2 = nd2s + ph(d2s) / sqtS - S1 * ph(d_) / (S2 * sqtS)
                d1_cmax = dT1dS1 + dT2dS1
                d2_cmax = dT1dS2 + dT2dS2
                d1_pmax = d1_cmax - df * dE_dS1
                d2_pmax = d2_cmax - df * dE_dS2
                d1_cmin = dc1 - d1_cmax
                d2_cmin = dc2 - d2_cmax
                d1_pmin = d1_cmin - df * (1.0 - dE_dS1)
                d2_pmin = d2_cmin - df * (1.0 - dE_dS2)
            if not (np.isfinite(d1_cmax) and np.isfinite(d2_cmax)):
                # |rho| -> 1: i delta analitici sono instabili -> bump
                # sui prezzi (esatti) del ramo generale.
                def _px_max(Sa, Sb):
                    sqt1_ = v1 * sqT
                    sqt2_ = v2 * sqT
                    sqtS_ = sig * sqT
                    y1_ = (float(np.log(Sa / K)) - 0.5 * v1 * v1 * T) / sqt1_
                    y2_ = (float(np.log(Sb / K)) - 0.5 * v2 * v2 * T) / sqt2_
                    d__ = (float(np.log(Sa / Sb)) + 0.5 * sig * sig * T) / sqtS_
                    d2s_ = (float(np.log(Sb / Sa)) + 0.5 * sig * sig * T) / sqtS_
                    e1_ = (float(np.log(Sa / Sb)) - 0.5 * (v1 * v1 - v2 * v2) * T) / sqtS_
                    Ma_ = _bvn(y1_ + sqt1_, d__, r1)
                    Mb_ = _bvn(y2_ + sqt2_, d2s_, r2)
                    Mq1_ = _bvn(y1_, e1_, r1)
                    Mq2_ = _bvn(y2_, -e1_, r2)
                    Emax_ = Sa * float(_norm.cdf(d__)) + Sb * float(_norm.cdf(d2s_))
                    cmax_ = df * (Sa * Ma_ + Sb * Mb_ - K * (Mq1_ + Mq2_))
                    return cmax_, cmax_ - df * (Emax_ - K), Emax_
                h1 = 1e-4 * S1
                h2 = 1e-4 * S2
                c_up, p_up, _ = _px_max(S1 + h1, S2)
                c_dn, p_dn, _ = _px_max(S1 - h1, S2)
                d1_cmax = (c_up - c_dn) / (2.0 * h1)
                d1_pmax = (p_up - p_dn) / (2.0 * h1)
                c_up, p_up, _ = _px_max(S1, S2 + h2)
                c_dn, p_dn, _ = _px_max(S1, S2 - h2)
                d2_cmax = (c_up - c_dn) / (2.0 * h2)
                d2_pmax = (p_up - p_dn) / (2.0 * h2)
                dE_dS1 = (d1_cmax - d1_pmax) / df
                dE_dS2 = (d2_cmax - d2_pmax) / df
                d1_cmin = dc1 - d1_cmax
                d2_cmin = dc2 - d2_cmax
                d1_pmin = d1_cmin - df * (1.0 - dE_dS1)
                d2_pmin = d2_cmin - df * (1.0 - dE_dS2)

    out = dict(neutro)
    premia = {"call_max": cmax, "put_max": pmax,
              "call_min": cmin, "put_min": pmin}
    deltas = {"call_max": (d1_cmax, d2_cmax), "put_max": (d1_pmax, d2_pmax),
              "call_min": (d1_cmin, d2_cmin), "put_min": (d1_pmin, d2_pmin)}
    d1r, d2r = deltas[tipo]
    premio = premia[tipo]
    vs1 = c1 if is_call else p1
    vs2 = c2 if is_call else p2
    if is_max:
        par = (cmax - pmax) - df * (Emax - K)
        fwd = Emax
    else:
        par = (cmin - pmin) - df * (Emin - K)
        fwd = Emin
    out.update({"valido": True, "premio": float(premio),
                "delta_s1": float(d1r), "delta_s2": float(d2r),
                "fwd_maxmin": float(fwd), "intrinseco": float(intr),
                "vanilla_s1": float(vs1), "vanilla_s2": float(vs2),
                "extra_vs_vanilla": float(premio - max(vs1, vs2)),
                "parita_diff": float(par)})
    return out


# Zone supportate dal tab Spread transfrontaliero: codice ENTSO-E (live)
# e parametri del mock deterministico (demo). Offset/profili riflettono
# differenze tipiche reali: DE-LU piu' volatile con duck curve solare,
# FR piu' piatta (nucleare baseload), IT-NORD con picco serale e premio
# di congestione strutturale vs CH.
ZONE_XB = {
    "🇩🇪 Germania/Lussemburgo (DE-LU)": {"codice": "DE_LU", "seed": 21,
                                         "base": -4.0, "vol": 1.35,
                                         "duck": -14.0, "picco_serale": 0.0},
    "🇫🇷 Francia (FR)": {"codice": "FR", "seed": 33,
                         "base": -2.0, "vol": 0.80,
                         "duck": 0.0, "picco_serale": 4.0},
    "🇮🇹 Italia Nord (IT-NORD)": {"codice": "IT_North", "seed": 55,
                                 "base": 8.0, "vol": 1.10,
                                 "duck": 0.0, "picco_serale": 22.0},
}


def generate_mock_zona(start_date, end_date, zona):
    """Mock deterministico di una seconda zona di prezzo per lo spread transfrontaliero.

    Stesso profilo giornaliero/stagionalita' di generate_mock_hourly ma con
    seed, base, volatilita' e forma diversi per zona (vedi ZONE_XB): la
    correlazione imperfetta tra le due serie genera spread realistici con
    episodi di congestione. Deterministico: stesso input -> stessa serie.
    Zona sconosciuta -> serie vuota (valido=False a valle)."""
    cfg = ZONE_XB.get(zona)
    if cfg is None:
        return pd.Series(dtype=float, name="Prezzo Spot (€/MWh)")
    rng = np.random.default_rng(cfg["seed"])
    idx = pd.date_range(
        start=pd.Timestamp(start_date),
        end=pd.Timestamp(end_date) + pd.Timedelta(days=1) - pd.Timedelta(hours=1),
        freq="h", tz="Europe/Zurich",
    )
    ore = idx.hour.to_numpy()
    wd = idx.weekday.to_numpy()
    profilo_giornaliero = 25 * np.sin(2 * np.pi * (ore - 6) / 24) + 18 * np.sin(4 * np.pi * (ore - 9) / 24)
    # Duck curve tedesca: crollo dei prezzi a meta' giornata per il solare
    duck = np.where((ore >= 10) & (ore <= 15), cfg["duck"] * np.sin(np.pi * (ore - 10) / 5.0), 0.0)
    # Picco serale accentuato (es. domanda italiana 19-21)
    picco = np.where((ore >= 18) & (ore <= 21), cfg["picco_serale"], 0.0)
    sconto_weekend = np.where(wd < 5, 12.0, -18.0)
    trend = np.linspace(0, 15, len(idx))
    rumore = rng.normal(0, 9 * cfg["vol"], len(idx))
    spike = np.where(rng.random(len(idx)) < 0.008, rng.uniform(60, 160, len(idx)), 0.0)
    prezzi = np.clip(95 + cfg["base"] + profilo_giornaliero + duck + picco
                     + sconto_weekend + trend + rumore + spike, 5, None)
    s = pd.Series(prezzi, index=idx, name="Prezzo Spot (€/MWh)")
    s.index.name = "Data e Ora"
    return s


def calcola_spread_xb(pa, pb, capacita_mw=1.0):
    """Statistiche dello spread transfrontaliero tra due serie orarie.

    spread = pb - pa: con capacita' di interconnessione A->B, ogni ora con
    spread > 0 rende spread * capacita' € (arbitraggio perfetto, senza
    costi di transito/allocazione e senza vincoli di nomina). Il valore
    totale e' la somma dei max(spread, 0) — stima "intrinsic" della
    capacita', cioe' il floor sotto cui un'opzione best-of (tab rainbow)
    non puo' mai scendere.

    Le due serie vengono allineate per timestamp (inner join); le coppie
    con NaN vengono scartate. Se restano meno di 2 ore valide -> valido=False.
    Ritorna dict con KPI, serie dello spread allineata e profilo orario medio."""
    out = {"valido": False}
    try:
        cap = float(capacita_mw)
        if not np.isfinite(cap) or cap <= 0:
            return out
        a = pd.to_numeric(pa, errors="coerce")
        b = pd.to_numeric(pb, errors="coerce")
        df = pd.concat({"a": a, "b": b}, axis=1).dropna()
        if len(df) < 2:
            return out
        spread = (df["b"] - df["a"]).to_numpy(dtype=float)
        if not np.all(np.isfinite(spread)):
            return out
        pos = np.maximum(spread, 0.0)
        valore_tot = float(pos.sum()) * cap  # €: spread €/MWh * cap MW * 1h
        giorni = max(1, int((df.index.max() - df.index.min()).total_seconds() // 86400) + 1)
        ore_idx = df.index.hour.to_numpy()
        prof = np.array([spread[ore_idx == h].mean() if (ore_idx == h).any() else np.nan
                         for h in range(24)])
        out.update({
            "valido": True,
            "n_ore": int(len(spread)),
            "spread_medio": float(spread.mean()),
            "spread_max": float(spread.max()),
            "spread_min": float(spread.min()),
            "pct_ore_positive": float(100.0 * (spread > 0).mean()),
            "valore_totale_eur": valore_tot,
            "valore_giorno_eur": valore_tot / giorni,
            "valore_mw_giorno": valore_tot / cap / giorni,
            "correlazione": float(np.corrcoef(df["a"].to_numpy(), df["b"].to_numpy())[0, 1]),
            "serie_spread": pd.Series(spread, index=df.index, name="Spread (€/MWh)"),
            "profilo_orario": prof,
        })
    except Exception:
        return {"valido": False}
    return out


def generate_mock_gas(start_date, end_date):
    """Serie GIORNALIERA sintetica del prezzo gas TTF (€/MWh termico).

    Base ~38 €/MWh con premio invernale (+14 a gennaio) e sconto estivo
    (-14 a luglio), trend e spike casuali (seed fisso). Deterministica:
    stesso input -> stessa serie. ENTSO-E non pubblica prezzi gas, quindi
    la tab 'Stoccaggio gas' usa sempre questo mock (dichiarato nel banner).
    Se start > end -> serie vuota."""
    rng = np.random.default_rng(1234)
    idx = pd.date_range(start=pd.Timestamp(start_date), end=pd.Timestamp(end_date),
                        freq="D", tz="Europe/Zurich")
    if len(idx) == 0:
        return pd.Series(dtype=float, name="Prezzo Gas TTF (€/MWh)")
    doy = idx.dayofyear.to_numpy()
    stag = 14.0 * np.cos(2 * np.pi * (doy - 15) / 365.25)
    trend = np.linspace(0, 6, len(idx))
    rumore = rng.normal(0, 2.5, len(idx))
    spike = np.where(rng.random(len(idx)) < 0.02, rng.uniform(8, 25, len(idx)), 0.0)
    prezzi = np.clip(38 + stag + trend + rumore + spike, 12, None)
    s = pd.Series(prezzi, index=idx, name="Prezzo Gas TTF (€/MWh)")
    s.index.name = "Giorno"
    return s


def calcola_stoccaggio_gas(prezzi_gas, capacita_gwh, inj_rate_gwh_g, wd_rate_gwh_g,
                           costo_inj_eur_mwh=0.4, costo_wd_eur_mwh=0.4,
                           inv_iniziale_pct=50.0, inv_finale_pct=50.0,
                           solo_valore=False):
    """Valore INTRINSECO di uno stoccaggio gas (ottimizzazione LP esatta).

    Massimizza, su prezzi giornalieri noti (perfect foresight),
      sum_d [ wd_d * (P_d - c_wd) - inj_d * (P_d + c_inj) ]
    con vincoli: 0 <= inj_d <= tasso_iniezione, 0 <= wd_d <= tasso_erogazione,
    giacenza S_d = S0 + cumsum(inj - wd) in [0, capacita'], S_N = giacenza finale
    target. Risolto con programmazione lineare (scipy HiGHS): l'ottimo e'
    esatto, non euristico.

    Il valore intrinseco e' il FLOOR del valore dello stoccaggio: la
    flessibilita' di ribilanciare le nomine in corso d'opera (valore
    ESTRINSECO) vale >= 0 e si prezza con modelli stocastici.

    Parametri prezzi_gas: Series (qualsiasi frequenza: viene ricampionata a
    media giornaliera). capacita_gwh: working gas. Tassi in GWh/giorno.
    Costi variabili in €/MWh. Giacenze in % della capacita'.

    Se giacenza finale != iniziale, il valore include il costo/ricavo forzato
    del riempimento/svuotamento netto (es. obbligo di riempimento).

    Ritorna dict: valido, valore_intrinseco_eur, valore_per_gwh_eur,
    cicli_equivalenti, energia_iniettata_gwh, energia_prelevata_gwh,
    prezzo_medio_acquisto, prezzo_medio_vendita, spread_medio_catturato,
    pnl_mensile (DataFrame), serie inventario/iniezioni/prelievi.
    Meno di 2 giorni validi, capacita' o tassi non positivi -> valido=False.
    solo_valore=True: percorso veloce (solo valido/n_giorni/
    valore_intrinseco_eur, niente DataFrame) per il Monte Carlo.
    """
    out = {"valido": False}
    try:
        from scipy.optimize import linprog as _linprog
        from scipy import sparse as _sparse
        p = pd.to_numeric(prezzi_gas, errors="coerce")
        if not isinstance(p, pd.Series):
            p = pd.Series(p)
        p = p.resample("D").mean().dropna()
        n = len(p)
        if n < 2:
            return out
        cap = float(capacita_gwh)
        ri = float(inj_rate_gwh_g)
        rw = float(wd_rate_gwh_g)
        ci = float(costo_inj_eur_mwh)
        cw = float(costo_wd_eur_mwh)
        if not all(np.isfinite([cap, ri, rw, ci, cw])) or cap <= 0 or ri <= 0 or rw <= 0:
            return out
        if ci < 0 or cw < 0:
            return out
        s0 = cap * float(np.clip(inv_iniziale_pct, 0.0, 100.0)) / 100.0
        st_ = cap * float(np.clip(inv_finale_pct, 0.0, 100.0)) / 100.0
        P = p.to_numpy(dtype=float)
        if not np.all(np.isfinite(P)):
            return out
        # x = [inj_0..inj_{n-1}, wd_0..wd_{n-1}]; minimizza c^T x
        # Matrici sparse: ~5x piu' veloci di quelle dense su questo LP
        # (critico per il Monte Carlo dello stoccaggio estrinseco).
        c = np.concatenate([P + ci, -(P - cw)])
        L = _sparse.tril(_sparse.csr_matrix(np.ones((n, n))))
        A_ub = _sparse.vstack([_sparse.hstack([L, -L]),
                               _sparse.hstack([-L, L])]).tocsr()
        b_ub = np.concatenate([np.full(n, cap - s0), np.full(n, s0)])
        A_eq = _sparse.csr_matrix(np.concatenate([np.ones(n), -np.ones(n)]).reshape(1, -1))
        b_eq = np.array([st_ - s0])
        bounds = [(0.0, ri)] * n + [(0.0, rw)] * n
        res = _linprog(c, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                       bounds=bounds, method="highs")
        if not res.success:
            return out
        inj = np.clip(res.x[:n], 0.0, None)
        wd = np.clip(res.x[n:], 0.0, None)
        inv = s0 + np.cumsum(inj - wd)
        valore = float(-res.fun)
        if valore < 0 and valore > -1e-6:
            valore = 0.0
        if solo_valore:
            # Percorso veloce per il Monte Carlo: solo l'ottimo, niente DataFrame
            out.update({"valido": True, "n_giorni": int(n),
                        "valore_intrinseco_eur": valore})
            return out
        e_inj = float(inj.sum())
        e_wd = float(wd.sum())
        pa = float((inj * P).sum() / e_inj) if e_inj > 0 else float("nan")
        pv = float((wd * P).sum() / e_wd) if e_wd > 0 else float("nan")
        pnl_g = wd * (P - cw) - inj * (P + ci)
        df_g = pd.DataFrame({"iniezione_gwh": np.round(inj, 3),
                             "prelievo_gwh": np.round(wd, 3),
                             "giacenza_gwh": np.round(inv, 3),
                             "prezzo_eur_mwh": np.round(P, 2),
                             "pnl_eur": np.round(pnl_g, 2)},
                            index=p.index)
        mese = df_g.index.strftime("%Y-%m")
        pnl_m = (df_g.assign(_m=mese).groupby("_m")
                 .agg(iniezione_gwh=("iniezione_gwh", "sum"),
                      prelievo_gwh=("prelievo_gwh", "sum"),
                      pnl_eur=("pnl_eur", "sum")).reset_index()
                 .rename(columns={"_m": "mese"}))
        out.update({
            "valido": True,
            "n_giorni": int(n),
            "valore_intrinseco_eur": valore,
            "valore_per_gwh_eur": valore / cap,
            "cicli_equivalenti": e_wd / cap,
            "energia_iniettata_gwh": e_inj,
            "energia_prelevata_gwh": e_wd,
            "prezzo_medio_acquisto": pa,
            "prezzo_medio_vendita": pv,
            "spread_medio_catturato": (pv - pa) if np.isfinite(pa) and np.isfinite(pv) else float("nan"),
            "giacenza_iniziale_gwh": float(s0),
            "giacenza_finale_gwh": float(st_),
            "pnl_mensile": pnl_m,
            "serie_giornaliera": df_g,
        })
    except Exception:
        return {"valido": False}
    return out


@st.cache_data(show_spinner=False)
def calcola_stoccaggio_estrinseco(prezzi_gas, capacita_gwh, inj_rate_gwh_g, wd_rate_gwh_g,
                                  costo_inj_eur_mwh=0.4, costo_wd_eur_mwh=0.4,
                                  inv_iniziale_pct=50.0, inv_finale_pct=50.0,
                                  n_scenari=100, vol_annua_pct=35.0,
                                  mean_reversion_giorni=30.0, seed=1234):
    """Valore ESTRINSECO di uno stoccaggio gas (Monte Carlo su prezzi stocastici).

    Il tab 'Stoccaggio gas' calcola il valore INTRINSECO: floor deterministico
    sotto perfect foresight. Nella realta' i prezzi futuri sono incerti e lo
    stoccaggio puo' ribilanciare le nomine in corso d'opera: questa
    opzionalita' operativa vale >= 0 e qui viene prezzata con Monte Carlo.

    Per ogni scenario si simula un percorso giornaliero del prezzo gas:
    GBM lognormale con mean reversion alla curva base deterministica
    (deviazioni AR(1): X_t = phi*X_{t-1} + sigma_d*z_t, phi = exp(-1/mr)),
    seed fisso -> completamente riproducibile. Su ciascun percorso si
    ricalcola il valore intrinseco ottimale con la stessa LP esatta; il valore
    estrinseco e' la MEDIA dei valori ottimali per scenario.

    Per convessita' del valore LP nei prezzi, E[V(P)] >= V(E[P]): a meno del
    rumore di simulazione l'estrinseco e' sempre >= dell'intrinseco.
    La differenza e' il premio di flessibilita' operativa (numero da portare
    alle aste di capacita' e alle due diligence).

    Parametri prezzi_*/capacita'/tassi/costi/giacenze come in
    calcola_stoccaggio_gas. n_scenari: percorsi simulati (20-300 consigliati).
    vol_annua_pct: volatilita' logaritmica annua dei prezzi gas.
    mean_reversion_giorni: scala temporale di rientro delle deviazioni.
    Ritorna dict: valido, n_giorni, n_scenari, vol_annua_pct,
    valore_intrinseco_eur, valore_estrinseco_eur, p10_eur, p90_eur, std_eur,
    premio_estrinseco_eur, premio_pct, valori_eur (lista). Input non validi
    (meno di 2 giorni, capacita'/tassi non positivi, vol negativa) ->
    {"valido": False}.
    """
    out = {"valido": False}
    try:
        base = calcola_stoccaggio_gas(prezzi_gas, capacita_gwh, inj_rate_gwh_g,
                                      wd_rate_gwh_g, costo_inj_eur_mwh,
                                      costo_wd_eur_mwh, inv_iniziale_pct,
                                      inv_finale_pct)
        if not base.get("valido"):
            return out
        p = pd.to_numeric(prezzi_gas, errors="coerce")
        if not isinstance(p, pd.Series):
            p = pd.Series(p)
        p = p.resample("D").mean().dropna().clip(lower=0.5)
        n = len(p)
        if n < 2:
            return out
        nsc = max(1, int(n_scenari))
        vol = float(vol_annua_pct) / 100.0
        mr = max(1.0, float(mean_reversion_giorni))
        if not np.isfinite(vol) or vol < 0 or not np.isfinite(mr):
            return out
        phi = float(np.exp(-1.0 / mr))
        sig_d = vol / np.sqrt(365.0)
        rng = np.random.default_rng(int(seed))
        logb = np.log(p.to_numpy())
        intr = float(base["valore_intrinseco_eur"])
        # Deviazioni log-prezzo AR(1) stazionarie a media zero
        z = rng.standard_normal((nsc, n))
        xs = np.empty((nsc, n))
        x = np.zeros(nsc)
        for t in range(n):
            x = phi * x + sig_d * z[:, t]
            xs[:, t] = x
        valori = np.empty(nsc)
        for i in range(nsc):
            ps = pd.Series(np.exp(logb + xs[i]), index=p.index)
            r = calcola_stoccaggio_gas(ps, capacita_gwh, inj_rate_gwh_g,
                                       wd_rate_gwh_g, costo_inj_eur_mwh,
                                       costo_wd_eur_mwh, inv_iniziale_pct,
                                       inv_finale_pct, solo_valore=True)
            valori[i] = float(r["valore_intrinseco_eur"]) if r.get("valido") else float("nan")
        ok = valori[np.isfinite(valori)]
        if len(ok) == 0:
            return out
        estr = float(ok.mean())
        premio = estr - intr
        out.update({
            "valido": True,
            "n_giorni": int(n),
            "n_scenari": int(nsc),
            "vol_annua_pct": float(vol_annua_pct),
            "valore_intrinseco_eur": intr,
            "valore_estrinseco_eur": estr,
            "p10_eur": float(np.percentile(ok, 10)),
            "p90_eur": float(np.percentile(ok, 90)),
            "std_eur": float(ok.std()),
            "premio_estrinseco_eur": float(premio),
            "premio_pct": float(100.0 * premio / intr) if intr > 0 else float("nan"),
            "valori_eur": [float(v) for v in ok],
        })
    except Exception:
        return {"valido": False}
    return out


def ottimizza_ricarica_ev(prezzi_24, energia_kwh, potenza_kw, ora_arrivo=17,
                          ora_partenza=7, efficienza_pct=92.0, capacita_kwh=None,
                          soc_iniziale_pct=20.0):
    """Piano di ricarica ottimale di un veicolo elettrico sui prezzi orari.

    Dato il profilo di 24 prezzi orari (€/MWh) e una finestra di sosta
    [ora_arrivo, ora_partenza) — che puo' attraversare la mezzanotte —
    trova il piano di ricarica a costo minimo: alloca la potenza sulle ore
    piu' economiche della finestra. Con costi lineari e vincoli di sola
    potenza/energia (nessuna dinamica di stato oltre il SoC finale) il
    greedy sulle ore ordinate per prezzo e' l'ottimo esatto, non
    un'approssimazione.
    Confronta con la baseline "ricarica immediata" (attacca la spina
    all'arrivo e carica a potenza massima finche' non e' pieno): il
    risparmio e' il valore economico dello smart charging, la metrica che
    un energy analyst usa per dimensionare tariffe ToU o wallbox
    intelligenti per flotte aziendali.
    Parametri: prezzi_24 sequenza di 24 prezzi orari €/MWh; energia_kwh
    energia da immettere in batteria; potenza_kw potenza max del
    caricatore; ora_arrivo/ora_partenza interi 0-23 (se uguali = 24h);
    efficienza_pct rendimento di ricarica (l'energia prelevata dalla rete
    e' energia_kwh/efficienza); capacita_kwh e soc_iniziale_pct opzionali
    per il vincolo di capienza della batteria.
    Ritorna dict con: schedario (lista di 24 potenze kW), costo_ottimale,
    costo_immediata, risparmio_eur, risparmio_pct, prezzo_medio_ott
    (€/MWh), prezzo_medio_finestra (€/MWh), ore_ricarica, energia_rete_kwh,
    valido, motivo. NaN-safe: input non validi -> dict neutro con
    valido=False."""
    neutro = {"schedario": [0.0] * 24, "costo_ottimale": float("nan"),
              "costo_immediata": float("nan"), "risparmio_eur": float("nan"),
              "risparmio_pct": float("nan"), "prezzo_medio_ott": float("nan"),
              "prezzo_medio_finestra": float("nan"), "ore_ricarica": 0,
              "energia_rete_kwh": float("nan"), "valido": False,
              "motivo": "input non validi"}
    try:
        pr = [float(x) for x in list(prezzi_24)[:24]]
        en = float(energia_kwh)
        pw = float(potenza_kw)
        ha = int(ora_arrivo) % 24
        hp = int(ora_partenza) % 24
        eff = float(efficienza_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if len(pr) != 24 or not all(np.isfinite(p) for p in pr):
        return neutro
    if not all(np.isfinite(v) for v in (en, pw, eff)):
        return neutro
    if en <= 0 or pw <= 0 or not 0.0 < eff <= 1.0:
        return dict(neutro, motivo="energia e potenza devono essere > 0, efficienza in (0,100]")
    if capacita_kwh is not None:
        try:
            cap = float(capacita_kwh)
            soc0 = float(soc_iniziale_pct)
        except (TypeError, ValueError):
            return dict(neutro, motivo="capacita'/SoC non numerici")
        if not (np.isfinite(cap) and np.isfinite(soc0)) or cap <= 0:
            return dict(neutro, motivo="capacita' batteria non valida")
        spazio = cap * max(0.0, 1.0 - soc0 / 100.0)
        if en > spazio + 1e-9:
            return dict(neutro, motivo=f"l'energia richiesta ({en:.1f} kWh) supera lo spazio in batteria ({spazio:.1f} kWh)")
    ore_finestra = []
    h = ha
    while True:
        ore_finestra.append(h)
        h = (h + 1) % 24
        if h == hp:
            break
    energia_rete = en / eff
    if len(ore_finestra) * pw < energia_rete - 1e-9:
        return dict(neutro, motivo="finestra troppo corta: servono piu' ore o piu' potenza")
    # Ottimo: ore della finestra ordinate per prezzo crescente (stabile per ora)
    ordine_ott = sorted(ore_finestra, key=lambda hh: (pr[hh], hh))
    sched = [0.0] * 24
    residuo = energia_rete
    for hh in ordine_ott:
        q = min(pw, residuo)
        sched[hh] = q
        residuo -= q
        if residuo <= 1e-9:
            break
    # Baseline: ricarica immediata dall'arrivo a potenza massima
    sched_naive = [0.0] * 24
    residuo = energia_rete
    for hh in ore_finestra:
        q = min(pw, residuo)
        sched_naive[hh] = q
        residuo -= q
        if residuo <= 1e-9:
            break
    costo_ott = sum(sched[hh] * pr[hh] for hh in ore_finestra) / 1000.0
    costo_nav = sum(sched_naive[hh] * pr[hh] for hh in ore_finestra) / 1000.0
    risparmio = costo_nav - costo_ott
    out = dict(neutro)
    out.update({"schedario": sched, "costo_ottimale": float(costo_ott),
                "costo_immediata": float(costo_nav),
                "risparmio_eur": float(risparmio),
                "risparmio_pct": float(100.0 * risparmio / costo_nav) if costo_nav > 0 else 0.0,
                "prezzo_medio_ott": float(costo_ott / en * 1000.0),
                "prezzo_medio_finestra": float(sum(pr[hh] for hh in ore_finestra) / len(ore_finestra)),
                "ore_ricarica": int(sum(1 for hh in ore_finestra if sched[hh] > 1e-9)),
                "energia_rete_kwh": float(energia_rete),
                "valido": True, "motivo": ""})
    return out


def calcola_americana(forward, strike, mesi, vol_pct, tasso_pct, n_step=200):
    """Premio di un'opzione AMERICANA su forward energetico (albero binomiale CRR).

    L'opzione AMERICANA puo' essere esercitata in QUALSIASI momento prima della
    scadenza (non solo a scadenza come l'europea): il suo prezzo incorpora la
    flessibilita' di "uscire" quando conviene. E' il modello naturale delle
    opzionalita' FISICHE dell'energy (una centrale che si accende/spegne ogni
    giorno, uno stoccaggio, un tolling con esercizio giornaliero): la
    differenza americana - europea e' l'EARLY-EXERCISE PREMIUM, cioe' quanto
    vale poter decidere prima della scadenza.
    Albero CRR sul forward (misura T-forward: il forward ha drift nullo):
      dt = T/N; u = exp(sig*sqrt(dt)); d = 1/u
      p = (1-d)/(u-d) (prob. risk-neutral); df_step = exp(-r*dt)
    Backward induction con esercizio anticipato a ogni nodo:
      V = max(intrinseco, df_step*(p*V_up + (1-p)*V_down))
    Convenzione di esercizio STILE FUTURES (come le opzioni su futures
    power/gas di EEX/ICE): l'esercizio consegna CASH pari all'intrinseco
    (F_t - K per la call). Per questo, con tasso r > 0, l'esercizio
    anticipato puo' essere ottimale ANCHE per la call deep ITM (si incassa
    subito l'intrinseco e lo si mette a frutto); con r = 0 l'americana
    coincide con l'europea. E' diverso dalle opzioni su forward OTC, dove
    l'esercizio consegna un contratto forward (e l'americana = europea).
    Sullo stesso albero si calcola anche l'europea (senza max) e il
    riferimento Black-76 in forma chiusa.
    Ancore esatte: (1) con r = 0, americana = europea sullo stesso albero
    (nessun interesse da incassare anticipando: check a tolleranza
    stretta); (2) parita' call-put europea ESATTA sull'albero:
    C - P = df*(F - K); (3) T = 0 o vol = 0 -> americana = intrinseco NON
    scontato (se ITM conviene esercitare subito), europea = df*intrinseco;
    (4) put americana deep ITM ~= intrinseco (esercizio immediato
    ottimale); (5) europea su albero -> Black-76 per N -> infinito
    (convergenza CRR, verifica nel tab).
    NaN-safe: input non validi (F <= 0, K <= 0, T < 0, vol < 0, r < 0,
    n_step < 1 o > 2000, NaN, stringhe) -> dict neutro con valido = False.
    Ritorna dict con: premio_am_call/put, premio_eu_call/put (stesso albero),
    bs_call/bs_put (Black-76 di riferimento), early_premium_call/put,
    parita_diff (~0), delta_am_call/put (dall'albero, al nodo radice),
    esercizio_immediato_call/put (bool: alla radice conviene esercitare ora),
    intrinseco_call/put, valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio_am_call": float("nan"), "premio_am_put": float("nan"),
              "premio_eu_call": float("nan"), "premio_eu_put": float("nan"),
              "bs_call": float("nan"), "bs_put": float("nan"),
              "early_premium_call": float("nan"),
              "early_premium_put": float("nan"),
              "parita_diff": float("nan"),
              "delta_am_call": float("nan"), "delta_am_put": float("nan"),
              "esercizio_immediato_call": False,
              "esercizio_immediato_put": False,
              "intrinseco_call": float("nan"),
              "intrinseco_put": float("nan"), "valido": False}
    try:
        F = float(forward); K = float(strike); T = float(mesi) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
        Ns = float(n_step)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r, Ns)):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    if not Ns.is_integer() or not 1 <= Ns <= 2000:
        return neutro
    N = int(Ns)

    df = float(np.exp(-r * T))
    intr_c = max(F - K, 0.0)
    intr_p = max(K - F, 0.0)

    def _bs():
        # Black-76 di riferimento (forma chiusa)
        if T <= 0.0 or sig <= 0.0:
            return df * intr_c, df * intr_p
        sqt = sig * np.sqrt(T)
        d1 = (np.log(F / K) + 0.5 * sig * sig * T) / sqt
        d2 = d1 - sqt
        c = df * (F * _norm.cdf(d1) - K * _norm.cdf(d2))
        p_ = df * (K * _norm.cdf(-d2) - F * _norm.cdf(-d1))
        return float(c), float(p_)

    bs_c, bs_p = _bs()

    if T <= 0.0 or sig <= 0.0:
        # deterministico: l'americana ITM si esercita subito (non scontata)
        out = dict(neutro)
        out.update({"valido": True, "premio_am_call": float(intr_c),
                    "premio_am_put": float(intr_p),
                    "premio_eu_call": float(bs_c), "premio_eu_put": float(bs_p),
                    "bs_call": float(bs_c), "bs_put": float(bs_p),
                    "early_premium_call": float(intr_c - bs_c),
                    "early_premium_put": float(intr_p - bs_p),
                    "parita_diff": float((bs_c - bs_p) - df * (F - K)),
                    "delta_am_call": 1.0 if F > K else 0.0,
                    "delta_am_put": -1.0 if F < K else 0.0,
                    "esercizio_immediato_call": bool(intr_c > 0),
                    "esercizio_immediato_put": bool(intr_p > 0),
                    "intrinseco_call": float(intr_c),
                    "intrinseco_put": float(intr_p)})
        return out

    dt = T / N
    u = float(np.exp(sig * np.sqrt(dt)))
    d = 1.0 / u
    disc = float(np.exp(-r * dt))
    p = (1.0 - d) / (u - d)

    j = np.arange(N + 1, dtype=float)
    ST = F * np.power(u, j) * np.power(d, N - j)
    Vc = np.maximum(ST - K, 0.0)   # americana call ai nodi terminali
    Vp = np.maximum(K - ST, 0.0)   # americana put ai nodi terminali
    Ec = Vc.copy()                 # europea call (stesso albero)
    Ep = Vp.copy()                 # europea put (stesso albero)
    STn = ST.copy()
    cont_c0 = cont_p0 = None
    Vc1 = Vp1 = ST1 = None
    for i in range(N, 0, -1):
        if i == 1:
            # valori americani (con esercizio) e sottostante al passo 1:
            # servono per delta ed esercizio-immediato alla radice
            Vc1 = Vc.copy(); Vp1 = Vp.copy(); ST1 = STn.copy()
        STn = STn[:-1] * u          # S(i,j) = S(i+1,j)/d = S(i+1,j)*u
        intr_c_i = np.maximum(STn - K, 0.0)
        intr_p_i = np.maximum(K - STn, 0.0)
        cont_c = disc * (p * Vc[1:] + (1.0 - p) * Vc[:-1])
        cont_p = disc * (p * Vp[1:] + (1.0 - p) * Vp[:-1])
        if i == 1:
            cont_c0 = float(cont_c[0]); cont_p0 = float(cont_p[0])
        Vc = np.maximum(intr_c_i, cont_c)
        Vp = np.maximum(intr_p_i, cont_p)
        Ec = disc * (p * Ec[1:] + (1.0 - p) * Ec[:-1])
        Ep = disc * (p * Ep[1:] + (1.0 - p) * Ep[:-1])

    am_c = float(Vc[0]); am_p = float(Vp[0])
    eu_c = float(Ec[0]); eu_p = float(Ep[0])
    dST = float(ST1[1] - ST1[0])
    delta_c = float((Vc1[1] - Vc1[0]) / dST) if dST > 0 else 0.0
    delta_p = float((Vp1[1] - Vp1[0]) / dST) if dST > 0 else 0.0

    out = dict(neutro)
    out.update({"valido": True, "premio_am_call": am_c, "premio_am_put": am_p,
                "premio_eu_call": eu_c, "premio_eu_put": eu_p,
                "bs_call": bs_c, "bs_put": bs_p,
                "early_premium_call": float(am_c - eu_c),
                "early_premium_put": float(am_p - eu_p),
                "parita_diff": float((eu_c - eu_p) - df * (F - K)),
                "delta_am_call": delta_c, "delta_am_put": delta_p,
                "esercizio_immediato_call": bool(intr_c > 0 and intr_c >= cont_c0),
                "esercizio_immediato_put": bool(intr_p > 0 and intr_p >= cont_p0),
                "intrinseco_call": float(intr_c),
                "intrinseco_put": float(intr_p)})
    return out


def render_kpi(title, value, col):
    col.markdown(f"<div class='metric-container'><div class='metric-label'>{title}</div><div class='metric-val'>{value}</div></div>", unsafe_allow_html=True)

def calcola_qualita_dati(prezzi, soglia_z=4.0, run_piatta_ore=6):
    """Audit di qualita' dei dati della serie oraria dei prezzi.

    Domanda operativa: "posso fidarmi dei numeri che vedo negli altri
    tab?" — controlla l'integrita' della serie oraria prima di qualsiasi
    analisi: ore mancanti rispetto alla griglia oraria attesa, timestamp
    duplicati (es. ora ambigua del cambio DST), valori NaN, sequenze di
    valori identici ("dato congelato"), outlier statistici e prezzi
    negativi.

    - soglia_z: soglia di z-score robusto (mediana/MAD) oltre la quale un
      valore e' outlier;
    - run_piatta_ore: lunghezza minima (ore) di una sequenza di valori
      identici per segnalarla come episodio "congelato" sospetto;
    - score 0-100: 100 meno penalita' pesate per gravita' (ore mancanti
      fino a -30, duplicati -10, NaN fino a -15, episodi congelati fino
      a -15, outlier fino a -10); verdetto 🟢 >= 90, 🟡 70-89, 🔴 < 70.

    NaN-safe: serie vuota, indice non-datetime o valori non numerici ->
    errore pulito; indice tz-aware reso naive (convenzione degli altri
    tab); indice non ordinato -> ordinato e segnalato. I prezzi negativi
    sono solo informativi (legittimi sullo spot europeo).

    Ritorna dict con 'errore', 'valido', 'score', 'verdetto', 'n_attese',
    'n_effettive', 'copertura_pct', 'n_mancanti', 'n_duplicati', 'n_nan',
    'non_ordinato', 'n_episodi_piatti', 'n_outlier', 'n_negativi',
    'df_problemi' (Tipo, Inizio, Fine, Ore, Dettaglio), 'df_mensile'
    (Mese, Attese, Effettive, Copertura %), 'df_outlier' (Timestamp,
    Prezzo, z-score).
    """
    colonne_prob = ["Tipo", "Inizio", "Fine", "Ore", "Dettaglio"]
    col_mese = ["Mese", "Attese", "Effettive", "Copertura %"]
    col_out = ["Timestamp", "Prezzo (\u20ac/MWh)", "z-score"]
    vuoto = {"errore": None, "valido": False, "score": None,
             "verdetto": None, "n_attese": 0, "n_effettive": 0,
             "copertura_pct": None, "n_mancanti": 0, "n_duplicati": 0,
             "n_nan": 0, "non_ordinato": False, "n_episodi_piatti": 0,
             "n_outlier": 0, "n_negativi": 0,
             "df_problemi": pd.DataFrame(columns=colonne_prob),
             "df_mensile": pd.DataFrame(columns=col_mese),
             "df_outlier": pd.DataFrame(columns=col_out)}

    def _err(msg):
        out = dict(vuoto)
        out["df_problemi"] = pd.DataFrame(columns=colonne_prob)
        out["df_mensile"] = pd.DataFrame(columns=col_mese)
        out["df_outlier"] = pd.DataFrame(columns=col_out)
        out["errore"] = msg
        return out

    try:
        soglia_z = float(soglia_z)
        run_piatta_ore = int(run_piatta_ore)
    except (TypeError, ValueError):
        return _err("Parametri non validi: soglia_z e run_piatta_ore "
                    "devono essere numerici.")
    if soglia_z <= 0 or run_piatta_ore < 2:
        return _err("Parametri non validi: soglia_z > 0 e "
                    "run_piatta_ore >= 2.")

    if prezzi is None or len(prezzi) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")
    try:
        p = pd.Series(prezzi)
    except Exception:
        return _err("Input non interpretabile come serie di prezzi.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("L'indice della serie deve essere di tipo data/ora.")
    vals = pd.to_numeric(p.values, errors="coerce")
    if np.isnan(vals).all():
        return _err("Nessun valore numerico nella serie prezzi.")
    idx = p.index.tz_localize(None) if p.index.tz is not None else p.index
    s = pd.Series(vals, index=idx)

    non_ordinato = not s.index.is_monotonic_increasing
    if non_ordinato:
        s = s.sort_index()

    n_nan = int(s.isna().sum())
    ts_dup = sorted(set(s.index[s.index.duplicated(keep=False)]))
    n_duplicati = len(ts_dup)

    atteso = pd.date_range(s.index.min(), s.index.max(), freq="h")
    presenti = set(s.index)
    mancanti = [t for t in atteso if t not in presenti]
    n_mancanti = len(mancanti)

    problemi = []
    if mancanti:
        ini = prec = mancanti[0]
        coda = mancanti[1:] + [None]
        for t in coda:
            if t is None or t != prec + pd.Timedelta(hours=1):
                n_ore = int((prec - ini).total_seconds() // 3600) + 1
                problemi.append(("Ore mancanti", ini, prec, n_ore,
                                 f"{n_ore} ore consecutive senza dato"))
                if t is None:
                    break
                ini = t
            prec = t
    for t in ts_dup:
        problemi.append(("Timestamp duplicato", t, t, 1,
                         "stesso timestamp piu' volte (es. ora ambigua "
                         "del cambio DST)"))

    sv = s.dropna()
    n_episodi_piatti = 0
    if len(sv) >= run_piatta_ore:
        grp = (sv != sv.shift()).cumsum()
        for _, g in sv.groupby(grp):
            if len(g) >= run_piatta_ore:
                n_episodi_piatti += 1
                problemi.append(("Valore congelato", g.index[0],
                                 g.index[-1], len(g),
                                 f"{g.iloc[0]:,.2f} \u20ac/MWh invariato "
                                 f"per {len(g)} ore"))

    n_outlier = 0
    df_out = pd.DataFrame(columns=col_out)
    svu = sv[~sv.index.duplicated(keep="first")]
    if len(svu) >= 4:
        med = float(svu.median())
        mad = float((svu - med).abs().median())
        if mad > 0:
            z = (svu - med).abs() / (1.4826 * mad)
            zo = z[z > soglia_z].sort_values(ascending=False)
            n_outlier = len(zo)
            if n_outlier:
                df_out = pd.DataFrame({
                    "Timestamp": list(zo.index),
                    "Prezzo (\u20ac/MWh)": [float(svu.loc[t])
                                            for t in zo.index],
                    "z-score": [round(float(v), 2) for v in zo.values],
                }).head(50)

    n_negativi = int((sv < 0).sum())

    validi = set(sv.index) & set(atteso)
    n_attese = len(atteso)
    n_effettive = len(validi)
    copertura_pct = round(100.0 * n_effettive / n_attese, 2) \
        if n_attese else None

    righe_mese = []
    if n_attese:
        att_m = pd.Series(1, index=atteso).resample("MS").sum()
        eff_m = pd.Series(1,
                          index=pd.DatetimeIndex(sorted(validi))).resample(
                              "MS").sum() if validi else pd.Series(
                                  dtype=float)
        for mese in att_m.index:
            a = int(att_m.loc[mese])
            e = int(eff_m.loc[mese]) if mese in eff_m.index else 0
            righe_mese.append({"Mese": mese.strftime("%Y-%m"),
                               "Attese": a, "Effettive": e,
                               "Copertura %": round(100.0 * e / a, 2)
                               if a else None})
    df_mensile = pd.DataFrame(righe_mese, columns=col_mese)

    pct_manc = 100.0 * n_mancanti / n_attese if n_attese else 0.0
    pct_nan = 100.0 * n_nan / len(s) if len(s) else 0.0
    penalita = (min(30.0, 2.0 * pct_manc)
                + (10.0 if n_duplicati else 0.0)
                + min(15.0, pct_nan)
                + min(15.0, 3.0 * n_episodi_piatti)
                + min(10.0, float(n_outlier)))
    score = round(max(0.0, 100.0 - penalita), 1)
    if score >= 90:
        verdetto = "\U0001f7e2 ottima"
    elif score >= 70:
        verdetto = "\U0001f7e1 accettabile"
    else:
        verdetto = "\U0001f534 critica"

    df_problemi = pd.DataFrame(problemi, columns=colonne_prob)
    if not df_problemi.empty:
        df_problemi = df_problemi.sort_values("Inizio").reset_index(
            drop=True)

    out = dict(vuoto)
    out.update({"valido": True, "score": score, "verdetto": verdetto,
                "n_attese": n_attese, "n_effettive": n_effettive,
                "copertura_pct": copertura_pct, "n_mancanti": n_mancanti,
                "n_duplicati": n_duplicati, "n_nan": n_nan,
                "non_ordinato": bool(non_ordinato),
                "n_episodi_piatti": n_episodi_piatti,
                "n_outlier": n_outlier, "n_negativi": n_negativi,
                "df_problemi": df_problemi, "df_mensile": df_mensile,
                "df_outlier": df_out})
    return out


def calcola_beta_gas_power(prezzi_orari, prezzi_gas, profilo="base", finestra=90, min_giorni=30):
    """Beta cross-commodity dello spot elettrico sul gas TTF (OLS giornaliera).

    Domanda operativa: "quando il TTF si muove di 1 €/MWh, di quanto si muove
    mediamente lo spot elettrico?" — la beta e' l'hedge ratio gas-to-power per
    coprire l'esposizione elettrica con future sul gas.

    - prezzi_orari: Series oraria dei prezzi elettrici (€/MWh, indice datetime;
      tz-aware reso naive come negli altri tab);
    - prezzi_gas: Series GIORNALIERA del prezzo gas (€/MWh termico, indice
      datetime);
    - profilo: "base" (media 0-23 di tutti i giorni) o "peak" (media ore 8-20
      dei soli giorni lun-ven);
    - finestra: ampiezza (giorni) della beta rolling; min_giorni: osservazioni
      minime per stimare la regressione.

    Regressione OLS in forma chiusa: power_giorno = alpha + beta * gas_giorno
    (nessuna dipendenza esterna). Ritorna dict con 'errore', 'valido', 'beta',
    'alpha', 'r2', 'correlazione', 'n_giorni', 'std_residui', 'gas_medio',
    'power_medio', 'df_rolling' (Fine finestra, Beta, R²), 'df_scatter'
    (Giorno, Gas (€/MWh), Power (€/MWh)), 'df_scenari' (Variazione gas,
    Gas (€/MWh), Δ prezzo (€/MWh), Prezzo atteso (€/MWh)).

    NaN-safe: serie vuote, indici non-datetime, gas costante (varianza nulla),
    giorni comuni < min_giorni -> errore pulito, mai eccezioni.
    """
    col_roll = ["Fine finestra", "Beta", "R²"]
    col_sc = ["Giorno", "Gas (€/MWh)", "Power (€/MWh)"]
    col_scen = ["Variazione gas", "Gas (€/MWh)", "Δ prezzo (€/MWh)",
                "Prezzo atteso (€/MWh)"]
    vuoto = {"errore": None, "valido": False, "beta": None, "alpha": None,
             "r2": None, "correlazione": None, "n_giorni": 0,
             "std_residui": None, "gas_medio": None, "power_medio": None,
             "df_rolling": pd.DataFrame(columns=col_roll),
             "df_scatter": pd.DataFrame(columns=col_sc),
             "df_scenari": pd.DataFrame(columns=col_scen)}

    def _err(msg):
        out = dict(vuoto)
        out["df_rolling"] = pd.DataFrame(columns=col_roll)
        out["df_scatter"] = pd.DataFrame(columns=col_sc)
        out["df_scenari"] = pd.DataFrame(columns=col_scen)
        out["errore"] = msg
        return out

    try:
        finestra = int(finestra)
        min_giorni = int(min_giorni)
    except (TypeError, ValueError):
        return _err("Parametri non validi: finestra e min_giorni devono essere interi.")
    if min_giorni < 10 or finestra < min_giorni:
        return _err("Parametri non validi: servono min_giorni >= 10 e finestra >= min_giorni.")
    if profilo not in ("base", "peak"):
        return _err("Profilo non valido: 'base' o 'peak'.")

    if prezzi_orari is None or len(prezzi_orari) == 0:
        return _err("Serie prezzi elettrici vuota.")
    if prezzi_gas is None or len(prezzi_gas) == 0:
        return _err("Serie prezzi gas vuota.")
    try:
        p = pd.Series(prezzi_orari)
        g = pd.Series(prezzi_gas)
    except Exception:
        return _err("Input non interpretabili come serie.")
    if not isinstance(p.index, pd.DatetimeIndex) or not isinstance(g.index, pd.DatetimeIndex):
        return _err("Gli indici di entrambe le serie devono essere di tipo data/ora.")
    pv = pd.to_numeric(p.values, errors="coerce")
    gv = pd.to_numeric(g.values, errors="coerce")
    if np.isnan(pv).all():
        return _err("Nessun valore numerico nella serie elettrica.")
    if np.isnan(gv).all():
        return _err("Nessun valore numerico nella serie gas.")
    idx_p = p.index.tz_localize(None) if p.index.tz is not None else p.index
    idx_g = g.index.tz_localize(None) if g.index.tz is not None else g.index
    s_p = pd.Series(pv, index=idx_p).dropna()
    s_g = pd.Series(gv, index=idx_g).dropna()
    if s_p.empty or s_g.empty:
        return _err("Serie vuote dopo la pulizia dei NaN.")

    ore = s_p.index.hour
    giorni = s_p.index.normalize()
    if profilo == "base":
        power_d = s_p.groupby(giorni).mean()
    else:
        dow = s_p.index.dayofweek
        mask_peak = (ore >= 8) & (ore < 20) & (dow < 5)
        if not bool(mask_peak.any()):
            return _err("Nessuna ora peak (lun-ven 8-20) nella serie elettrica.")
        power_d = s_p[mask_peak].groupby(giorni[mask_peak]).mean()
    gas_d = s_g.groupby(s_g.index.normalize()).mean()
    df = pd.DataFrame({"gas": gas_d, "power": power_d}).dropna()
    if len(df) < min_giorni:
        return _err(f"Dati insufficienti: {len(df)} giorni comuni, servono almeno {min_giorni}.")
    if float(df["gas"].var()) <= 0:
        return _err("Prezzo gas costante sul periodo: regressione impossibile.")

    x = df["gas"].to_numpy()
    y = df["power"].to_numpy()

    def _ols(xx, yy):
        if len(xx) < 2 or float(np.var(xx)) <= 0:
            return None
        b = float(np.cov(xx, yy, ddof=0)[0, 1] / np.var(xx))
        a = float(np.mean(yy) - b * np.mean(xx))
        corr = float(np.corrcoef(xx, yy)[0, 1])
        return b, a, corr, corr * corr

    full = _ols(x, y)
    if full is None:
        return _err("Regressione impossibile sui dati disponibili.")
    beta, alpha, corr, r2 = full
    std_res = float(np.std(y - (alpha + beta * x)))
    gas_ref = float(x.mean())
    power_ref = float(y.mean())

    righe = []
    for i in range(min_giorni, len(df) + 1):
        sub = df.iloc[max(0, i - finestra):i]
        r = _ols(sub["gas"].to_numpy(), sub["power"].to_numpy())
        righe.append({"Fine finestra": df.index[i - 1].date(),
                      "Beta": round(r[0], 3) if r else None,
                      "R²": round(r[3], 3) if r else None})
    df_roll = pd.DataFrame(righe, columns=col_roll)

    df_sc = pd.DataFrame({"Giorno": df.index.date,
                          "Gas (€/MWh)": np.round(x, 2),
                          "Power (€/MWh)": np.round(y, 2)})

    scen = []
    for pct in (-30, -20, -10, 10, 20, 30):
        gas_sc = gas_ref * (1 + pct / 100.0)
        d_prezzo = beta * (gas_sc - gas_ref)
        scen.append({"Variazione gas": f"{pct:+d} %",
                     "Gas (€/MWh)": round(gas_sc, 2),
                     "Δ prezzo (€/MWh)": round(d_prezzo, 2),
                     "Prezzo atteso (€/MWh)": round(power_ref + d_prezzo, 2)})
    df_scen = pd.DataFrame(scen, columns=col_scen)

    return {"errore": None, "valido": True, "beta": beta, "alpha": alpha,
            "r2": r2, "correlazione": corr, "n_giorni": len(df),
            "std_residui": std_res, "gas_medio": gas_ref,
            "power_medio": power_ref, "df_rolling": df_roll,
            "df_scatter": df_sc, "df_scenari": df_scen}


def calcola_volatilita_termine(prezzi_orari, bucket="mese", min_giorni=10, min_bucket=2):
    """Struttura a termine della volatilita' realizzata dello spot (€/MWh).

    prezzi_orari: Series oraria in €/MWh. Gli spot possono essere 0 o negativi,
    quindi si lavora sulle VARIAZIONI GIORNALIERE del prezzo medio (€/MWh),
    non sui log-return (stessa convenzione del tab Volatilita').
    Metodo: media per giorno solare -> variazioni giornaliere -> per ogni bucket
    di consegna (mese di calendario o trimestre) vol annua = std(ddof=1) delle
    variazioni x sqrt(252). Slope = regressione OLS in forma chiusa della vol
    sui bucket in ordine cronologico (€/MWh per bucket): slope < 0 =
    backwardation della vol (stress concentrato a breve termine), slope > 0 =
    contango (incertezza che cresce a termine).
    A cosa serve: input n.1 per prezzare le opzioni (tab structuring) e per
    scegliere le scadenze delle coperture — mesi ad alta vol storica hanno
    premi attesi piu' alti.
    NaN-safe: serie vuota / indice non-datetime / variazioni insufficienti ->
    errore pulito; bucket con < min_giorni giorni saltato (n_esclusi);
    prezzi costanti -> vol 0, valido.
    Ritorna dict con errore/valido/bucket/tabella/front/media/slope/
    slope_rel/bucket_max/bucket_min/rapporto/verdetto/serie_variazioni.
    """
    cols = ["Bucket", "Giorni", "Prezzo medio (€/MWh)", "Vol annua (€/MWh)",
            "Vol annua (% prezzo)"]
    vuoto = pd.DataFrame({c: [] for c in cols})

    def _err(msg):
        return {"errore": msg, "valido": False, "bucket": str(bucket),
                "tabella": vuoto, "n_bucket": 0, "n_esclusi": 0,
                "giorni_totali": 0, "front": None, "media": None,
                "slope": None, "slope_rel": None, "bucket_max": None,
                "bucket_min": None, "rapporto": None, "verdetto": msg,
                "serie_variazioni": pd.Series(dtype=float)}

    if not isinstance(prezzi_orari, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    if not isinstance(prezzi_orari.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    try:
        min_giorni = int(min_giorni)
        min_bucket = int(min_bucket)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: controlla gli input.")
    if min_giorni < 2:
        return _err("min_giorni deve essere almeno 2.")
    if min_bucket < 2:
        return _err("min_bucket deve essere almeno 2.")
    freq = {"mese": "M", "month": "M", "trimestre": "Q",
            "quarter": "Q"}.get(str(bucket).strip().lower())
    if freq is None:
        return _err("bucket non valido: usa 'mese' o 'trimestre'.")

    p = pd.to_numeric(prezzi_orari, errors="coerce").dropna()
    if len(p) < 48:
        return _err("Serie troppo corta: servono almeno 48 ore di prezzi.")
    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    giornaliera = p.groupby(idxn.date).mean()
    if len(giornaliera) < 3:
        return _err("Servono almeno 3 giorni di prezzi per le variazioni.")
    var = giornaliera.diff().dropna()
    per_g = pd.DatetimeIndex(pd.to_datetime(giornaliera.index)).to_period(freq)
    per_v = pd.DatetimeIndex(pd.to_datetime(var.index)).to_period(freq)

    righe, esclusi = [], 0
    for per in sorted(set(per_v)):
        mg = per_g == per
        mv = per_v == per
        gg = int(mg.sum())
        chg = var.iloc[mv].dropna()
        if gg < min_giorni or len(chg) < 2:
            esclusi += 1
            continue
        v = float(chg.std(ddof=1)) * (252.0 ** 0.5)
        pm = float(giornaliera.iloc[mg].mean())
        vpct = (v / abs(pm) * 100.0) if pm != 0 else float("nan")
        righe.append({"Bucket": str(per), "Giorni": gg,
                      "Prezzo medio (€/MWh)": round(pm, 2),
                      "Vol annua (€/MWh)": round(v, 2),
                      "Vol annua (% prezzo)": (round(vpct, 1) if vpct == vpct else None),
                      "_vol": v})

    if not righe:
        return _err(f"Nessun bucket con almeno {min_giorni} giorni: "
                    "serie troppo corta o parametro troppo alto.")

    vols = np.array([r["_vol"] for r in righe])
    media = float(vols.mean())
    slope = None
    if len(vols) >= min_bucket:
        x = np.arange(len(vols), dtype=float)
        vx = float(np.var(x))
        slope = float(np.cov(x, vols, ddof=0)[0, 1] / vx) if vx > 0 else 0.0
    slope_rel = (slope / media) if (slope is not None and media > 0) else None
    imax, imin = int(vols.argmax()), int(vols.argmin())
    rapporto = float(vols[imax] / vols[imin]) if vols[imin] > 0 else None

    if len(righe) < min_bucket:
        valido = False
        verdetto = (f"⚪ Struttura non stimabile: {len(righe)} bucket validi, "
                    f"ne servono almeno {min_bucket} per la pendenza.")
    else:
        valido = True
        thr = 0.05 * media
        if slope < -thr:
            verdetto = ("🔴 Backwardation della vol: lo stress e' concentrato a "
                        "breve termine — opzioni e coperture corte piu' care.")
        elif slope > thr:
            verdetto = ("🟢 Contango della vol: l'incertezza cresce a termine — "
                        "occhio alle scadenze lunghe.")
        else:
            verdetto = "🟡 Struttura piatta: la vol e' simile su tutti i bucket."

    tabella = pd.DataFrame([{k: r[k] for k in cols} for r in righe], columns=cols)
    return {"errore": None, "valido": valido, "bucket": str(bucket),
            "tabella": tabella, "n_bucket": len(righe), "n_esclusi": esclusi,
            "giorni_totali": int(len(giornaliera)), "front": float(vols[0]),
            "media": media, "slope": slope, "slope_rel": slope_rel,
            "bucket_max": righe[imax]["Bucket"], "bucket_min": righe[imin]["Bucket"],
            "rapporto": rapporto, "verdetto": verdetto,
            "serie_variazioni": var}


def calcola_indice_stress(prezzi_orari, soglia=70.0, pesi=None):
    """Indice di stress di mercato giornaliero (0-100): un numero unico che
    dice quanto il mercato e' sotto stress ogni giorno.

    4 componenti, normalizzate min-max sul periodo analizzato (0 = minimo
    osservato, 1 = massimo osservato), poi media pesata x 100:
      1. Livello prezzo    — media giornaliera (prezzi alti = stress), w 0.35
      2. Range intraday    — (max-min)/|media|, con pavimento a 5 €/MWh per
         non far esplodere il rapporto quando la media e' ~0, w 0.25
      3. Shock giornaliero — |variazione della media vs giorno prima|, w 0.25
      4. Ore negative      — quota di ore con prezzo < 0 (stress da eccesso
         di rinnovabili / domanda debole), w 0.15
    Classi: SSI < 30 calmo, < 50 tensionato, < 70 stressato, >= 70 crisi.
    A cosa serve: termometro unico per il TEMPO delle coperture (SSI alto =
    si fissa prima, si paga volentieri il premio delle opzioni), storicizza le
    crisi per confrontare "quanto e' grave oggi" col passato; le componenti
    spiegano sempre il perche' del punteggio, niente black box.
    NaN-safe: serie vuota / indice non-datetime / < 72 ore -> errore pulito;
    prezzi costanti -> tutte le componenti a 0 -> SSI 0 (calmo); tz-aware reso
    naive; soglia fuori 0-100 o pesi non validi -> errore.
    Ritorna dict con errore/valido/serie/tabella/ultimo/medio/massimo/
    sopra_soglia/pct_crisi/n_giorni/mensile/pesi/verdetto.
    """
    PESI_DEF = (0.35, 0.25, 0.25, 0.15)
    COLS_PT = ["Livello prezzo (pt)", "Range intraday (pt)",
               "Shock giornaliero (pt)", "Ore negative (pt)"]

    def _vuoto():
        return pd.DataFrame({"Data": [], "SSI": [], "Classe": [],
                             **{c: [] for c in COLS_PT}})

    def _err(msg):
        return {"errore": msg, "valido": False, "serie": _vuoto(),
                "tabella": _vuoto(), "ultimo": None, "medio": None,
                "massimo": None, "sopra_soglia": 0, "pct_crisi": 0.0,
                "n_giorni": 0,
                "mensile": pd.DataFrame({"Mese": [], "SSI medio": []}),
                "pesi": PESI_DEF, "verdetto": msg}

    if not isinstance(prezzi_orari, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    if not isinstance(prezzi_orari.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    try:
        soglia = float(soglia)
    except (TypeError, ValueError):
        return _err("soglia non numerica: usa un valore 0-100.")
    if not (0.0 <= soglia <= 100.0):
        return _err("soglia fuori range: usa un valore 0-100.")
    if pesi is None:
        w = PESI_DEF
    else:
        try:
            w = tuple(float(x) for x in pesi)
        except (TypeError, ValueError):
            return _err("pesi non numerici: servono 4 valori >= 0.")
        if len(w) != 4 or any(x < 0 for x in w) or sum(w) <= 0:
            return _err("pesi non validi: servono 4 valori >= 0 con somma > 0.")
        tot = sum(w)
        w = tuple(x / tot for x in w)

    p = pd.to_numeric(prezzi_orari, errors="coerce").dropna()
    if len(p) < 72:
        return _err("Serie troppo corta: servono almeno 72 ore di prezzi.")
    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    giorni = idxn.date
    g = p.groupby(giorni)
    media = g.mean()
    rng = (g.max() - g.min()) / media.abs().clip(lower=5.0)
    shock = media.diff().abs().fillna(0.0)
    neg = (p < 0).groupby(giorni).mean()

    def _mm(s):
        lo, hi = float(s.min()), float(s.max())
        if hi > lo:
            return (s - lo) / (hi - lo)
        return pd.Series(0.0, index=s.index)

    comp = pd.DataFrame({"Livello prezzo": _mm(media),
                         "Range intraday": _mm(rng),
                         "Shock giornaliero": _mm(shock),
                         "Ore negative": _mm(neg)})
    pts = comp.mul(w, axis=1) * 100.0
    ssi = pts.sum(axis=1).round(1)

    def _classe(v):
        if v < 30.0:
            return "🟢 Calmo"
        if v < 50.0:
            return "🟡 Tensionato"
        if v < 70.0:
            return "🟠 Stressato"
        return "🔴 Crisi"

    classi = [_classe(v) for v in ssi.to_numpy()]
    serie = pd.DataFrame({"Data": pd.to_datetime(ssi.index),
                          "SSI": ssi.to_numpy(), "Classe": classi})
    for i, c in enumerate(COLS_PT):
        serie[c] = pts.iloc[:, i].to_numpy().round(1)

    tabella = serie.sort_values("SSI", ascending=False).head(20).reset_index(drop=True)
    mens = serie.groupby(serie["Data"].dt.to_period("M"))["SSI"].mean().round(1)
    mensile = pd.DataFrame({"Mese": [str(m) for m in mens.index],
                            "SSI medio": mens.to_numpy()})

    ultimo_ssi = float(ssi.iloc[-1])
    ultimo_data = str(ssi.index[-1])
    massimo_idx = int(ssi.to_numpy().argmax())
    sopra = int((ssi.to_numpy() >= soglia).sum())
    crisi = float(np.mean([c == "🔴 Crisi" for c in classi])) * 100.0

    if ultimo_ssi >= soglia:
        verdetto = (f"🚨 Mercato in tensione l'ultimo giorno ({ultimo_data}): "
                    f"SSI {ultimo_ssi:.1f} sopra la soglia {soglia:.0f}.")
    else:
        verdetto = (f"Mercato sotto controllo l'ultimo giorno ({ultimo_data}): "
                    f"SSI {ultimo_ssi:.1f} sotto la soglia {soglia:.0f}.")

    return {"errore": None, "valido": True, "serie": serie, "tabella": tabella,
            "ultimo": {"data": ultimo_data, "ssi": ultimo_ssi,
                       "classe": _classe(ultimo_ssi)},
            "medio": float(ssi.mean()),
            "massimo": {"data": str(ssi.index[massimo_idx]),
                        "valore": float(ssi.iloc[massimo_idx])},
            "sopra_soglia": sopra, "pct_crisi": round(crisi, 1),
            "n_giorni": int(len(ssi)), "mensile": mensile, "pesi": w,
            "verdetto": verdetto}


def _fascia_aeegsi(h, wd):
    """Fascia AEEGSI F1/F2/F3 da ora (0-23) e weekday (0=lun..6=dom)."""
    if wd == 6:
        return "F3"
    if wd == 5:
        return "F2" if 7 <= h < 23 else "F3"
    if 8 <= h < 19:
        return "F1"
    if (7 <= h < 8) or (19 <= h < 23):
        return "F2"
    return "F3"


def _stat_circolari(ore, pesi):
    """Media e dispersione circolari su 24h. Ritorna (baricentro_ore, dispersione_ore, quota_centro_pct)."""
    theta = 2.0 * np.pi * np.asarray(ore, dtype=float) / 24.0
    w = np.asarray(pesi, dtype=float)
    sw = float(w.sum())
    if sw <= 0.0:
        return None, None, None
    s = float((w * np.sin(theta)).sum())
    c = float((w * np.cos(theta)).sum())
    ang = np.arctan2(s, c)
    bary = float((ang / (2.0 * np.pi) * 24.0) % 24.0)
    rl = float(np.hypot(s, c) / sw)  # lunghezza risultante 0..1
    disp = float(np.sqrt(max(0.0, -2.0 * np.log(min(rl, 1.0)))) * 24.0 / (2.0 * np.pi)) if rl > 0 else None
    d = np.minimum(np.abs(np.asarray(ore, dtype=float) - bary), 24.0 - np.abs(np.asarray(ore, dtype=float) - bary))
    quota = float(w[d <= 2.0].sum() / sw * 100.0)
    return bary, disp, quota


def calcola_baricentro_costo(prezzi, mw_f1, mw_f2, mw_f3):
    """Baricentro del costo: l'ora del giorno in cui si concentra la spesa.

    Il costo orario e' prezzo spot x MW della fascia F1/F2/F3 (stessa logica
    della tab Top ore di costo). Il baricentro e' la media ponderata
    CIRCOLARE delle ore 0-23 (pesi = costi orari non negativi): con una media
    aritmetica banale le ore 0 e 23 falserebbero il risultato, con quella
    circolare no. La dispersione e' la deviazione standard circolare in ore;
    la quota entro ±2h dice quanta spesa sta davvero vicino al baricentro.

    Differenza dagli altri tab: Top ore di costo classifica le ore piu' care
    GIA' accadute (le prime 10 possono cadere tutte nello stesso giorno);
    Ora di punta prende l'ora piu' costosa di OGNI giorno; qui la domanda e'
    'attorno a che ora ruota mediamente la mia bolletta?' — un unico numero
    (es. 17:36) + dispersione, utile per la demand response ricorrente e per
    verificare se il profilo si e' spostato (baricentro mensile).

    Le ore con costo negativo (prezzi negativi) sono escluse dai pesi e
    conteggiate a parte; se il costo totale non positivo non si calcola nulla.

    NaN-safe: serie vuota / indice non datetime / tutti i MW a zero / nessun
    costo positivo -> errore pulito, DataFrame con le colonne giuste vuoti.

    Ritorna dict con 'errore', 'valido', 'n_ore', 'mwh_tot', 'costo_tot',
    'baricentro_ore', 'baricentro_txt' ('HH:MM'), 'dispersione_ore',
    'quota_centro_pct' (quota di costo entro ±2h dal baricentro),
    'ore_negative' / 'quota_neg_pct' (ore a costo negativo escluse dai pesi),
    'per_ora' (DataFrame 24 righe: Ora, Ore osservate, Costo (€), Quota %) e
    'mensile' (DataFrame: Mese, Baricentro, Dispersione (±h), Quota ±2h (%), Costo (€))."""
    cols_o = ["Ora", "Ore osservate", "Costo (€)", "Quota %"]
    cols_m = ["Mese", "Baricentro", "Dispersione (±h)", "Quota ±2h (%)", "Costo (€)"]
    vuoto = {"errore": "Dati insufficienti: nessuna ora valida nel periodo.",
             "valido": False, "n_ore": 0, "mwh_tot": 0.0, "costo_tot": None,
             "baricentro_ore": None, "baricentro_txt": None,
             "dispersione_ore": None, "quota_centro_pct": None,
             "ore_negative": 0, "quota_neg_pct": 0.0,
             "per_ora": pd.DataFrame(columns=cols_o),
             "mensile": pd.DataFrame(columns=cols_m)}
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0 or not isinstance(p.index, pd.DatetimeIndex):
        return dict(vuoto)
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)), "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        out = dict(vuoto)
        out["errore"] = "Imposta una potenza maggiore di zero in almeno una fascia."
        return out
    ore = p.index.hour.to_numpy()
    wd = p.index.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    mw = np.array([mw_map[f] for f in fasce])
    costo = p.to_numpy(dtype=float) * mw
    w = np.maximum(costo, 0.0)
    if w.sum() <= 0.0:
        out = dict(vuoto)
        out["errore"] = "Costo totale non positivo: baricentro non calcolabile."
        return out
    bary, disp, quota_c = _stat_circolari(ore, w)
    n_ore = len(p)
    costo_tot = float(costo.sum())
    mwh_tot = float(mw.sum())
    neg = int((costo < 0.0).sum())
    ore_24, costo_24, n_24 = np.arange(24), np.zeros(24), np.zeros(24, dtype=int)
    for h in range(24):
        m = ore == h
        n_24[h] = int(m.sum())
        costo_24[h] = float(costo[m].sum())
    q24 = np.where(costo_tot > 0, np.maximum(costo_24, 0.0) / max(w.sum(), 1e-12) * 100.0, 0.0)
    per_ora = pd.DataFrame({"Ora": [f"{h:02d}:00" for h in ore_24],
                            "Ore osservate": n_24,
                            "Costo (€)": np.round(costo_24, 2),
                            "Quota %": np.round(q24, 2)})
    righe = []
    mesi = (p.index.tz_localize(None) if p.index.tz is not None else p.index).to_period("M")
    for mese, grp in pd.DataFrame({"c": costo, "o": ore}).groupby(mesi):
        cm, om = grp["c"].to_numpy(), grp["o"].to_numpy()
        wm = np.maximum(cm, 0.0)
        if wm.sum() <= 0.0:
            continue
        bm, dm, qm = _stat_circolari(om, wm)
        righe.append({"Mese": str(mese), "Baricentro": f"{int(bm):02d}:{int(round((bm % 1) * 60)):02d}",
                      "Dispersione (±h)": round(dm, 1) if dm is not None else None,
                      "Quota ±2h (%)": round(qm, 1), "Costo (€)": round(float(cm.sum()), 0)})
    bh = int(bary)
    bt = f"{bh:02d}:{int(round((bary - bh) * 60)):02d}"
    return {"errore": None, "valido": True, "n_ore": n_ore, "mwh_tot": mwh_tot,
            "costo_tot": costo_tot, "baricentro_ore": bary, "baricentro_txt": bt,
            "dispersione_ore": disp, "quota_centro_pct": quota_c,
            "ore_negative": neg, "quota_neg_pct": round(neg / n_ore * 100.0, 1),
            "per_ora": per_ora, "mensile": pd.DataFrame(righe, columns=cols_m)}


def calcola_penalita_reattiva(prezzi, mw_f1, mw_f2, mw_f3, cos_phi,
                            tariffa_t1=0.008, tariffa_t2=0.012,
                            soglia_t1=0.33, soglia_t2=0.75, cos_phi_obiettivo=0.95):
    """Penale per energia reattiva: quanto ti costa il basso fattore di potenza.

    Domanda operativa: 'quanto pago di penali per l'energia reattiva
    (kvarh) e quanto risparmierei rifasando a 0.95?'

    Logica: dalla potenza attiva oraria (MW della fascia F1/F2/F3, stessa
    logica della tab Baricentro del costo) e dal cos(phi) dichiarato si
    ricava l'energia reattiva oraria: Er = Ea * tan(acos(cos_phi)).
    Aggregazione mensile e penali a due scaglioni stile ARERA (soglie e
    tariffe configurabili perche' cambiano per livello di tensione e anno):
      - scaglione 1: reattiva oltre soglia_t1 (default 33%) e fino a
        soglia_t2 (default 75%) dell'attiva -> tariffa_t1 €/kvarh;
      - scaglione 2: reattiva oltre soglia_t2 dell'attiva -> tariffa_t2 €/kvarh.
    In piu' il 'risparmio rifasamento': penale ricalcolata con
    cos_phi_obiettivo (default 0.95) sullo stesso profilo.

    Differenza dagli altri tab: stima bolletta e riconciliazione fattura
    valorizzano la componente ENERGIA a spot; qui si misura una voce di
    costo INDIPENDENTE dal prezzo (dipende solo dal profilo e dal cos phi),
    che per un'utenza industriale mal rifasata puo' valere migliaia di euro
    l'anno e si elimina con un rifasatore da qualche centinaio di euro.

    NaN-safe: serie vuota / indice non datetime / tutti i MW a zero /
    cos_phi fuori (0, 1) -> errore pulito, DataFrame con le colonne giuste vuoti.

    Ritorna dict con 'errore', 'valido', 'n_ore', 'mwh_tot', 'kvarh_tot',
    'rapporto_medio_pct' (reattiva/attiva pesata sul periodo),
    'penale_tot' (€), 'penale_rifasata' (€ con cos_phi_obiettivo),
    'risparmio_rifasamento' (€), 'mesi_con_penale' (int), 'peggior_mese'
    (str 'YYYY-MM'), 'penale_peggiore' (€), 'tan_phi', 'tan_phi_obiettivo' e
    'mensile' (DataFrame: Mese, Attiva (kWh), Reattiva (kvarh),
    Rapporto %, Eccedenza t1 (kvarh), Eccedenza t2 (kvarh), Penale (€))."""
    cols_m = ["Mese", "Attiva (kWh)", "Reattiva (kvarh)", "Rapporto %",
              "Eccedenza t1 (kvarh)", "Eccedenza t2 (kvarh)", "Penale (€)"]
    vuoto = {"errore": "Dati insufficienti: nessuna ora valida nel periodo.",
             "valido": False, "n_ore": 0, "mwh_tot": 0.0, "kvarh_tot": 0.0,
             "rapporto_medio_pct": None, "penale_tot": 0.0,
             "penale_rifasata": 0.0, "risparmio_rifasamento": 0.0,
             "mesi_con_penale": 0, "peggior_mese": None, "penale_peggiore": 0.0,
             "tan_phi": None, "tan_phi_obiettivo": None,
             "mensile": pd.DataFrame(columns=cols_m)}
    try:
        cp = float(cos_phi)
    except Exception:
        cp = float("nan")
    if not (0.0 < cp < 1.0):
        out = dict(vuoto)
        out["errore"] = "Il cos(phi) deve essere compreso tra 0 e 1 (esclusi)."
        return out
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0 or not isinstance(p.index, pd.DatetimeIndex):
        return dict(vuoto)
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)), "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        out = dict(vuoto)
        out["errore"] = "Imposta una potenza maggiore di zero in almeno una fascia."
        return out
    t1 = max(0.0, float(tariffa_t1 or 0.0))
    t2 = max(0.0, float(tariffa_t2 or 0.0))
    s1 = min(max(0.0, float(soglia_t1 or 0.0)), 5.0)
    s2 = min(max(0.0, float(soglia_t2 or 0.0)), 5.0)
    if s2 < s1:
        s1, s2 = s2, s1
    try:
        co = float(cos_phi_obiettivo)
    except Exception:
        co = 0.95
    co = min(max(co, 0.01), 0.9999)
    tan_phi = float(np.tan(np.arccos(cp)))
    tan_ob = float(np.tan(np.arccos(co)))
    ore = p.index.hour.to_numpy()
    wd = p.index.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    mw = np.array([mw_map[f] for f in fasce])
    ea_oraria = mw * 1000.0          # kWh per ora
    er_oraria = ea_oraria * tan_phi  # kvarh per ora
    mesi = (p.index.tz_localize(None) if p.index.tz is not None else p.index).to_period("M")

    def _penale_mese(ea, er):
        if ea <= 0.0 or er <= 0.0:
            return 0.0, 0.0, 0.0
        ecc2 = max(0.0, er - s2 * ea)
        ecc1 = max(0.0, min(er, s2 * ea) - s1 * ea)
        return ecc1, ecc2, ecc1 * t1 + ecc2 * t2

    righe = []
    for mese, idx in pd.DataFrame({"ea": ea_oraria, "er": er_oraria}).groupby(mesi).groups.items():
        g = pd.DataFrame({"ea": ea_oraria, "er": er_oraria}).iloc[idx]
        ea_m, er_m = float(g["ea"].sum()), float(g["er"].sum())
        ecc1, ecc2, pen = _penale_mese(ea_m, er_m)
        righe.append({"Mese": str(mese), "Attiva (kWh)": round(ea_m, 0),
                      "Reattiva (kvarh)": round(er_m, 0),
                      "Rapporto %": round(er_m / ea_m * 100.0, 1) if ea_m > 0 else 0.0,
                      "Eccedenza t1 (kvarh)": round(ecc1, 0),
                      "Eccedenza t2 (kvarh)": round(ecc2, 0),
                      "Penale (€)": round(pen, 2)})
    mensile = pd.DataFrame(righe, columns=cols_m)
    ea_tot, er_tot = float(ea_oraria.sum()), float(er_oraria.sum())
    penale_tot = float(mensile["Penale (€)"].sum()) if len(mensile) else 0.0
    # scenario rifasamento: stessa attiva, reattiva ridotta a tan(phi_obiettivo)
    er_ob = ea_oraria * tan_ob
    pen_ob = 0.0
    for mese, idx in pd.DataFrame({"ea": ea_oraria, "er": er_ob}).groupby(mesi).groups.items():
        g = pd.DataFrame({"ea": ea_oraria, "er": er_ob}).iloc[idx]
        pen_ob += _penale_mese(float(g["ea"].sum()), float(g["er"].sum()))[2]
    mesi_pen = mensile[mensile["Penale (€)"] > 0.0]
    peg_m, peg_v = (None, 0.0)
    if len(mesi_pen):
        riga = mesi_pen.loc[mesi_pen["Penale (€)"].idxmax()]
        peg_m, peg_v = str(riga["Mese"]), float(riga["Penale (€)"])
    return {"errore": None, "valido": True, "n_ore": len(p),
            "mwh_tot": ea_tot / 1000.0, "kvarh_tot": er_tot,
            "rapporto_medio_pct": round(er_tot / ea_tot * 100.0, 1) if ea_tot > 0 else 0.0,
            "penale_tot": round(penale_tot, 2),
            "penale_rifasata": round(pen_ob, 2),
            "risparmio_rifasamento": round(penale_tot - pen_ob, 2),
            "mesi_con_penale": int(len(mesi_pen)),
            "peggior_mese": peg_m, "penale_peggiore": round(peg_v, 2),
            "tan_phi": round(tan_phi, 4), "tan_phi_obiettivo": round(tan_ob, 4),
            "mensile": mensile}


def calcola_efficienza_fixing(prezzi_orari, prezzo_fissato):
    """Efficienza del fixing: quanto e' stato buono il tuo prezzo fissato (€/MWh)
    contro il mercato del periodo.

    Confronta il prezzo medio che hai fissato con la distribuzione dei prezzi
    orari del periodo:
      - % ore battute = quota di ore in cui il mercato e' stato uguale o piu'
        caro del tuo fixing (100% = l'hai sempre battuto);
      - sovracosto vs media di periodo, in €/MWh e in %;
      - distanza dal minimo di periodo (costo opportunita' del timing perfetto)
        e dal massimo di periodo.
    Verdetto per % ore battute: >=90 Eccellente, >=70 Buono, >=50 Nella norma,
    >=30 Caro, <30 Molto caro.
    A cosa serve: valuta ex-post le decisioni di fissazione — un fixing sotto
    la mediana batte il mercato piu' della meta' del tempo; la tabella mensile
    mostra in quali mesi il fixing ha reso di piu' o di meno, utile per il
    debriefing col fornitore.
    NaN-safe: serie vuota / indice non-datetime / < 24 ore / prezzo fissato
    non numerico o <= 0 -> errore pulito; tz-aware reso naive.
    Ritorna dict con errore/valido/prezzo_fissato/media/mediana/p10/p25/p50/
    p75/p90/min/max/n_ore/pct_battuto/sovracosto_eur/sovracosto_pct/dist_min/
    dist_max/verdetto/mensile.
    """
    def _vuoto_mens():
        return pd.DataFrame({"Mese": [], "Media €/MWh": [],
                             "Scarto vs fixing €/MWh": [],
                             "Ore battute %": []})

    def _err(msg):
        return {"errore": msg, "valido": False, "prezzo_fissato": None,
                "media": None, "mediana": None, "p10": None, "p25": None,
                "p50": None, "p75": None, "p90": None, "min": None,
                "max": None, "n_ore": 0, "pct_battuto": None,
                "sovracosto_eur": None, "sovracosto_pct": None,
                "dist_min": None, "dist_max": None, "verdetto": msg,
                "mensile": _vuoto_mens()}

    if not isinstance(prezzi_orari, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    if not isinstance(prezzi_orari.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    try:
        pf = float(prezzo_fissato)
    except (TypeError, ValueError):
        return _err("Prezzo fissato non numerico: inserisci un valore > 0.")
    if not pf > 0:
        return _err("Prezzo fissato non valido: inserisci un valore > 0.")

    p = pd.to_numeric(prezzi_orari, errors="coerce").dropna()
    if len(p) < 24:
        return _err("Serie troppo corta: servono almeno 24 ore di prezzi.")
    vals = p.to_numpy(dtype=float)
    q = np.percentile(vals, [10, 25, 50, 75, 90])

    media = float(vals.mean())
    pct_batt = float((vals >= pf).mean() * 100.0)
    sovr_eur = pf - media
    sovr_pct = (sovr_eur / media * 100.0) if abs(media) > 1e-9 else 0.0

    if pct_batt >= 90.0:
        verdetto = (f"🏆 Eccellente: hai battuto il mercato nel {pct_batt:.1f}% "
                    "delle ore — fixing quasi perfetto.")
    elif pct_batt >= 70.0:
        verdetto = (f"✅ Buono: hai battuto il mercato nel {pct_batt:.1f}% "
                    "delle ore.")
    elif pct_batt >= 50.0:
        verdetto = (f"➖ Nella norma: hai battuto il mercato nel "
                    f"{pct_batt:.1f}% delle ore.")
    elif pct_batt >= 30.0:
        verdetto = (f"⚠️ Caro: hai battuto il mercato solo nel "
                    f"{pct_batt:.1f}% delle ore.")
    else:
        verdetto = (f"🚨 Molto caro: hai battuto il mercato solo nel "
                    f"{pct_batt:.1f}% delle ore.")

    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    mesi = idxn.to_period("M")
    gm = p.groupby(mesi)
    mm = gm.mean()
    pbb = gm.apply(lambda s: float((s.to_numpy() >= pf).mean() * 100.0))
    mensile = pd.DataFrame(
        {"Mese": [str(m) for m in mm.index],
         "Media €/MWh": mm.to_numpy().round(2),
         "Scarto vs fixing €/MWh": (mm - pf).to_numpy().round(2),
         "Ore battute %": pbb.to_numpy().round(1)})

    return {"errore": None, "valido": True, "prezzo_fissato": pf,
            "media": round(media, 2), "mediana": round(float(np.median(vals)), 2),
            "p10": round(float(q[0]), 2), "p25": round(float(q[1]), 2),
            "p50": round(float(q[2]), 2), "p75": round(float(q[3]), 2),
            "p90": round(float(q[4]), 2),
            "min": round(float(vals.min()), 2),
            "max": round(float(vals.max()), 2),
            "n_ore": int(len(vals)), "pct_battuto": round(pct_batt, 1),
            "sovracosto_eur": round(sovr_eur, 2),
            "sovracosto_pct": round(sovr_pct, 1),
            "dist_min": round(pf - float(vals.min()), 2),
            "dist_max": round(float(vals.max()) - pf, 2),
            "verdetto": verdetto, "mensile": mensile}


def calcola_ottimizza_potenza(prezzi, mw_f1, mw_f2, mw_f3, p_contr_kw,
                              quota_kw_mese, penale_kw, fattore_picco=1.05):
    """Ottimizzazione della potenza impegnata (potenza contrattuale).

    Il distributore fattura la potenza in due voci: una QUOTA FISSA mensile
    proporzionale alla potenza impegnata (kW contrattuali x quota €/kW/mese)
    e una PENALE quando il picco reale supera la potenza impegnata
    (kW di superamento x penale €/kW, per mese). Troppa potenza impegnata =
    quota fissa sprecata; troppo poca = penali ricorrenti. Questa tab trova
    il punto di equilibrio.

    Il picco mensile e' stimato dal profilo orario MW F1/F2/F3 (stessa
    logica degli altri tab): picco_mese = max(MW orari del mese) x 1000 x
    fattore_picco. Il fattore_picco (default 1.05) approssima il picco
    quarto-orario, che la misura reale usa al posto del picco orario:
    alzalo se il tuo carico ha punte brevi e ripide.

    La scansione prova potenze candidate da 0.5 x picco_max a 1.3 x
    picco_max: per ogni candidata il costo totale = quota fissa + penali
    su tutti i mesi. I candidati includono anche i picchi mensili osservati
    (il costo e' lineare a tratti con spigoli proprio li': l'ottimo cade
    sempre su uno spigolo o su un estremo). Il risparmio annuo e' il
    risparmio sul periodo annualizzato (x 12 / n_mesi).

    NaN-safe: serie vuota / indice non-datetime / < 24 ore / MW tutti a
    zero / potenza contrattuale <= 0 / quota o penale negative /
    fattore_picco <= 0 -> errore pulito; tz-aware reso naive.

    Ritorna dict con errore/valido/n_ore/n_mesi/mwh_tot/picco_max_kw/
    p_contr_kw/potenza_ottima_kw/costo_attuale/costo_ottimo/
    risparmio_periodo/risparmio_annuo/mesi_superamento/categoria/
    verdetto/mensile/scansione.
    """
    cols_m = ["Mese", "Picco (kW)", "Quota fissa (€)", "Penale (€)", "Totale (€)"]
    cols_s = ["Potenza (kW)", "Quota fissa (€)", "Penali (€)", "Totale (€)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_ore": 0, "n_mesi": 0,
                "mwh_tot": 0.0, "picco_max_kw": None, "p_contr_kw": None,
                "potenza_ottima_kw": None, "costo_attuale": None,
                "costo_ottimo": None, "risparmio_periodo": None,
                "risparmio_annuo": None, "mesi_superamento": 0,
                "categoria": None, "verdetto": msg,
                "mensile": pd.DataFrame(columns=cols_m),
                "scansione": pd.DataFrame(columns=cols_s)}

    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    try:
        p_contr = float(p_contr_kw)
        quota = float(quota_kw_mese)
        penale = float(penale_kw)
        fp = float(fattore_picco)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: potenza, quota, penale e fattore devono essere numeri.")
    if not p_contr > 0:
        return _err("Potenza contrattuale non valida: inserisci un valore > 0 kW.")
    if quota < 0:
        return _err("Quota potenza non valida: non puo' essere negativa.")
    if penale < 0:
        return _err("Penale di superamento non valida: non puo' essere negativa.")
    if not fp > 0:
        return _err("Fattore di picco non valido: inserisci un valore > 0.")
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Input non valido: serie prezzi non leggibile.")
    if len(p) < 24:
        return _err("Serie troppo corta: servono almeno 24 ore di prezzi.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)), "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        return _err("Imposta una potenza maggiore di zero in almeno una fascia.")

    ore = p.index.hour.to_numpy()
    wd = p.index.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    mw = np.array([mw_map[f] for f in fasce])  # MW orari del profilo

    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    mesi = idxn.to_period("M")
    dfm = pd.DataFrame({"mw": mw}, index=idxn)
    picchi = []
    righe = []
    for mese, grp in dfm.groupby(mesi):
        pk = float(grp["mw"].max()) * 1000.0 * fp  # kW
        picchi.append(pk)
        qf = p_contr * quota
        pen = max(0.0, pk - p_contr) * penale
        righe.append({"Mese": str(mese), "Picco (kW)": round(pk, 0),
                      "Quota fissa (€)": round(qf, 2), "Penale (€)": round(pen, 2),
                      "Totale (€)": round(qf + pen, 2)})
    picchi = np.array(picchi)
    n_mesi = len(picchi)
    picco_max = float(picchi.max())

    def _costo_tot(pot):
        qf = pot * quota * n_mesi
        pen = float(np.maximum(0.0, picchi - pot).sum()) * penale
        return qf, pen, qf + pen

    lo, hi = 0.5 * picco_max, 1.3 * picco_max
    candidati = sorted(set([lo, hi, p_contr, picco_max] +
                           list(np.linspace(lo, hi, 41)) + list(picchi)))
    righe_s = []
    for cand in candidati:
        qf, pen, tot = _costo_tot(cand)
        righe_s.append({"Potenza (kW)": round(cand, 0), "Quota fissa (€)": round(qf, 2),
                        "Penali (€)": round(pen, 2), "Totale (€)": round(tot, 2)})
    scansione = pd.DataFrame(righe_s, columns=cols_s)
    i_best = int(np.argmin([r["Totale (€)"] for r in righe_s]))
    pot_ott = float(righe_s[i_best]["Potenza (kW)"])
    costo_ott = float(righe_s[i_best]["Totale (€)"])
    qf_a, pen_a, costo_att = _costo_tot(p_contr)
    mesi_sup = int((picchi > p_contr).sum())
    risp = costo_att - costo_ott
    risp_annuo = risp * 12.0 / n_mesi

    if pot_ott < 0.9 * p_contr:
        categoria = "sovradimensionata"
        verdetto = (f"📉 Potenza sovradimensionata: l'ottimo e' {pot_ott:,.0f} kW "
                    f"contro {p_contr:,.0f} kW impegnati — ridurla taglia la quota "
                    f"fissa di {risp_annuo:,.0f} €/anno senza penali.")
    elif pot_ott > 1.1 * p_contr:
        categoria = "sottodimensionata"
        verdetto = (f"📈 Potenza sottodimensionata: l'ottimo e' {pot_ott:,.0f} kW "
                    f"contro {p_contr:,.0f} kW impegnati — con {mesi_sup} mesi di "
                    f"superamento, alzare l'impegnata risparmia {risp_annuo:,.0f} €/anno.")
    else:
        categoria = "adeguata"
        verdetto = (f"✅ Potenza adeguata: {p_contr:,.0f} kW impegnati contro un ottimo "
                    f"di {pot_ott:,.0f} kW — margine di miglioramento solo {risp_annuo:,.0f} €/anno.")

    return {"errore": None, "valido": True, "n_ore": int(len(p)),
            "n_mesi": n_mesi, "mwh_tot": float(mw.sum()),
            "picco_max_kw": round(picco_max, 0), "p_contr_kw": round(p_contr, 0),
            "potenza_ottima_kw": round(pot_ott, 0),
            "costo_attuale": round(costo_att, 2), "costo_ottimo": round(costo_ott, 2),
            "risparmio_periodo": round(risp, 2), "risparmio_annuo": round(risp_annuo, 2),
            "mesi_superamento": mesi_sup, "categoria": categoria,
            "verdetto": verdetto,
            "mensile": pd.DataFrame(righe, columns=cols_m), "scansione": scansione}


def calcola_rollover_coperture(prezzi, mw=1.0, quota_copertura_pct=50.0,
                               mesi_anticipo=1, soglia_regime_pct=1.5):
    """Backtest del costo di rolling di una copertura forward mensile continua.

    Il desk compra ogni mese la consegna del mese successivo con una
    copertura a termine "rolling": a fine mese chiude la copertura in
    scadenza e apre quella nuova. Il ROLL di ogni mese e' la differenza tra
    il prezzo pagato per la nuova copertura e quello pagato per la vecchia:
      roll_i = strip_{i-k} - strip_{i-k-1}   (EUR/MWh, firmato: + = costo)
    Roll positivo = curva in CONTANGO (il rolling costa soldi); roll
    negativo = BACKWARDATION (il rolling guadagna).
    roll_yield_i = -roll_i / strip_{i-k-1} * 100  (+ = guadagno in backwardation)
    Regime: "contango" se roll_yield < -soglia, "backwardation" se
    roll_yield > soglia, altrimenti "piatto" (soglia in %).
    costo_eur_i = roll_i * MWh coperti del mese i (mw * ore_mese * quota/100).

    Con i soli spot storici il prezzo "pagato" e' approssimato con lo strip
    base implicito del mese di acquisto (media delle ore del mese): e' un
    proxy di backtest, NON la vera curva forward quotata. mesi_anticipo
    (1-3) sposta indietro la finestra di acquisto: con k=1 il prezzo per la
    consegna del mese i e' lo strip del mese i-1, con k=2 lo strip del
    mese i-2, ecc. Nota: con k>1 il roll cambia solo per la finestra
    storica usata (i differenziali strip_j - strip_{j-1} sono gli stessi).

    NaN-safe: serie vuota / indice non datetime / < 3 mesi / mw <= 0 /
    quota fuori [0,100] / anticipo fuori [1,3] / soglia negativa ->
    errore pulito; tz-aware reso naive; mesi con ore zero saltati.

    Ritorna dict con errore/valido/n_ore/n_mesi_totali/n_roll/mw/
    quota_copertura_pct/mesi_anticipo/totale_eur/roll_medio_eur_mwh/
    yield_medio_pct/mesi_contango/mesi_backwardation/mesi_piatti/
    costo_annuo_stimato/costo_fornitura/incidenza_pct/categoria/
    verdetto/mensile/sensibilita.
    """
    cols_m = ["Mese", "Strip (\u20ac/MWh)", "Roll (\u20ac/MWh)", "Roll yield (%)",
              "Regime", "MWh coperti", "Costo roll (\u20ac)"]
    cols_s = ["Quota copertura (%)", "Costo annuo stimato (\u20ac)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_ore": 0, "n_mesi_totali": 0,
                "n_roll": 0, "mw": None, "quota_copertura_pct": None,
                "mesi_anticipo": None, "totale_eur": None,
                "roll_medio_eur_mwh": None, "yield_medio_pct": None,
                "mesi_contango": 0, "mesi_backwardation": 0, "mesi_piatti": 0,
                "costo_annuo_stimato": None, "costo_fornitura": None,
                "incidenza_pct": None, "categoria": None, "verdetto": msg,
                "mensile": pd.DataFrame(columns=cols_m),
                "sensibilita": pd.DataFrame(columns=cols_s)}

    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    try:
        mw_f = float(mw)
        quota = float(quota_copertura_pct)
        soglia = float(soglia_regime_pct)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: MW, quota e soglia devono essere numeri.")
    if not mw_f > 0:
        return _err("Potenza non valida: inserisci MW > 0.")
    if not 0.0 <= quota <= 100.0:
        return _err("Quota di copertura non valida: inserisci un valore tra 0 e 100.")
    try:
        k = int(mesi_anticipo)
    except (TypeError, ValueError):
        return _err("Anticipo non valido: mesi_anticipo deve essere intero tra 1 e 3.")
    if k not in (1, 2, 3):
        return _err("Anticipo non valido: mesi_anticipo deve essere 1, 2 o 3.")
    if not soglia >= 0:
        return _err("Soglia di regime non valida: non puo' essere negativa.")
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Input non valido: serie prezzi non leggibile.")
    if len(p) == 0:
        return _err("Serie vuota: nessun dato disponibile.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index

    mesi = idxn.to_period("M")
    strip = {}
    ore_m = {}
    for m, grp in pd.Series(p.values, index=idxn).groupby(mesi):
        if len(grp) == 0:
            continue
        v = float(np.nanmean(grp.values))
        if np.isnan(v):
            continue
        strip[str(m)] = v
        ore_m[str(m)] = int(len(grp))
    mesi_ord = sorted(strip.keys())
    n_mesi = len(mesi_ord)
    if n_mesi < 3:
        return _err("Servono almeno 3 mesi di dati per simulare il rolling.")
    if n_mesi - k - 1 < 1:
        return _err(f"Con anticipo di {k} mesi servono almeno {k + 2} mesi di dati.")

    righe = []
    roll_vals, yield_vals, costi = [], [], []
    n_cont = n_back = n_flat = 0
    costo_fornitura = 0.0
    for pos in range(k + 1, n_mesi):
        m_del = mesi_ord[pos]          # mese di consegna coperto
        s_new = strip[mesi_ord[pos - k]]
        s_old = strip[mesi_ord[pos - k - 1]]
        roll = s_new - s_old
        yld = -roll / s_old * 100.0 if s_old != 0 else float("nan")
        if not np.isnan(yld) and yld < -soglia:
            regime = "contango"
            n_cont += 1
        elif not np.isnan(yld) and yld > soglia:
            regime = "backwardation"
            n_back += 1
        else:
            regime = "piatto"
            n_flat += 1
        mwh = mw_f * ore_m[m_del] * quota / 100.0
        costo = roll * mwh
        roll_vals.append(roll)
        yield_vals.append(yld)
        costi.append(costo)
        costo_fornitura += strip[m_del] * ore_m[m_del] * mw_f
        righe.append({"Mese": m_del, "Strip (\u20ac/MWh)": round(s_new, 2),
                      "Roll (\u20ac/MWh)": round(roll, 2),
                      "Roll yield (%)": round(yld, 2) if not np.isnan(yld) else None,
                      "Regime": regime, "MWh coperti": round(mwh, 1),
                      "Costo roll (\u20ac)": round(costo, 2)})

    roll_vals = np.array(roll_vals)
    n_roll = len(righe)
    totale = float(np.sum(costi))
    roll_medio = float(np.mean(roll_vals))
    yv = np.array([y for y in yield_vals if not np.isnan(y)])
    yield_medio = float(np.mean(yv)) if len(yv) else 0.0
    costo_annuo = totale / n_roll * 12.0
    incidenza = (abs(totale) / costo_fornitura * 100.0) if costo_fornitura > 0 else 0.0
    if totale > 0.005:
        categoria = "costo"
        verdetto = (f"Il rolling ti e' costato {totale:,.0f} \u20ac sul periodo "
                    f"({n_cont} mesi in contango, {n_back} in backwardation): la curva "
                    "prezza i mesi lontani piu' dei vicini. Valuta coperture piu' lunghe "
                    "o acquisti a pronti nei mesi di contango estremo.")
    elif totale < -0.005:
        categoria = "guadagno"
        verdetto = (f"Il rolling ti ha fatto guadagnare {abs(totale):,.0f} \u20ac sul periodo "
                    f"({n_back} mesi in backwardation, {n_cont} in contango): la curva "
                    "prezza i mesi lontani meno dei vicini. Mantieni il rolling mensile, "
                    "il mercato ti paga per farlo.")
    else:
        categoria = "neutro"
        verdetto = (f"Rolling quasi neutro ({totale:,.2f} \u20ac sul periodo, {n_flat} mesi "
                    "piatti): il costo del rolling non e' un driver in questo periodo.")

    sens_righe = []
    for q in range(0, 101, 10):
        c_ann = costo_annuo * q / quota if quota > 0 else 0.0
        sens_righe.append({"Quota copertura (%)": q,
                           "Costo annuo stimato (\u20ac)": round(c_ann, 0)})

    return {"errore": None, "valido": True, "n_ore": int(len(p)),
            "n_mesi_totali": n_mesi, "n_roll": n_roll, "mw": mw_f,
            "quota_copertura_pct": quota, "mesi_anticipo": k,
            "totale_eur": round(totale, 2),
            "roll_medio_eur_mwh": round(roll_medio, 2),
            "yield_medio_pct": round(yield_medio, 2),
            "mesi_contango": n_cont, "mesi_backwardation": n_back,
            "mesi_piatti": n_flat,
            "costo_annuo_stimato": round(costo_annuo, 0),
            "costo_fornitura": round(costo_fornitura, 0),
            "incidenza_pct": round(incidenza, 2),
            "categoria": categoria, "verdetto": verdetto,
            "mensile": pd.DataFrame(righe, columns=cols_m),
            "sensibilita": pd.DataFrame(sens_righe, columns=cols_s)}


def calcola_peak_shaving(prezzi, mw_f1, mw_f2, mw_f3, cap_mwh, pot_mw,
                         eff_pct=85.0, quota_eur_kw_mese=2.5,
                         potenza_attuale_kw=1000.0, degrado_eur_mwh=0.0,
                         capex_batteria_eur=0.0, n_soglie=21):
    """Peak shaving con batteria: taglia i picchi per abbassare la potenza impegnata.

    Domanda operativa: 'conviene una batteria per ridurre la quota fissa di
    potenza (EUR/kW/mese)?' Complemento operativo del tab 'Potenza impegnata'
    (tab146), che ottimizza la potenza contrattuale sul profilo esistente:
    qui si simula l'INTERVENTO fisico che abbassa i picchi mensili.

    Metodo (tutto deterministico a parita' di input, euristica giornaliera):
    - carico orario (kW) dal profilo MW per fascia F1/F2/F3 (via _fascia_aeegsi);
    - per ogni giorno e per ogni soglia T la batteria SCARICA nelle ore di
      carico piu' alto per portare il prelievo netto verso T (priorita' ai
      picchi, limiti di potenza e di energia, rendimento sqrt(eff) per lato),
      poi RICARICA nelle ore piu' economiche senza mai superare T (la
      ricarica non deve creare un nuovo picco: T e' il tetto contrattuale);
    - il SOC si propaga da un giorno all'altro (parte da batteria piena):
      se T e' troppo bassa rispetto al carico notturno la batteria non
      riesce a ricaricarsi, si esaurisce nei primi giorni e i picchi
      tornano al lordo: lo sweep penalizza onestamente queste soglie.
    Sweep di n_soglie soglie tra il 55% e il 100% del picco lordo massimo.
    Per ogni soglia:
      picchi netti mensili -> nuova potenza impegnata ottimale;
      risparmio quota = max(0, min(attuale, picco_lordo) - ottimale)
                        x quota x n_mesi  (alla batteria e' accreditata solo
                        la riduzione SOTTO il livello gia' ottenibile senza
                        batteria: senza batteria contratteresti il picco lordo);
      delta_energia = somma((netto - lordo)/1000 x prezzo_orario)
                      (negativo = risparmio: scarichi nelle ore care);
      degrado = MWh scaricati x degrado_eur_mwh;
      beneficio netto = risparmio quota - delta_energia - degrado,
      annualizzato x 12/n_mesi. Ottimo = soglia col massimo beneficio.

    NaN-safe: serie vuota / indice non datetime / MW tutti a zero /
    cap_mwh o pot_mw <= 0 / eff fuori (0, 100] / potenza attuale <= 0 ->
    errore pulito, DataFrame con le colonne giuste vuoti.

    Ritorna dict con 'errore', 'valido', 'n_ore', 'n_mesi', 'picco_lordo_kw',
    'soglia_ottima_kw', 'potenza_ottimale_kw', 'risparmio_annuo_netto',
    'quota_annua', 'delta_energia_annuo', 'degrado_annuo',
    'mwh_scaricati_annui', 'payback_anni' (None se capex <= 0 o
    beneficio <= 0), 'riduzione_picco_pct', 'categoria'
    ('conviene'/'non-conviene'/'inutile'), 'verdetto', 'sweep' (DataFrame)
    e 'mensile' (DataFrame alla soglia ottima).
    """
    cols_s = ["Soglia (kW)", "Risparmio annuo netto (\u20ac)",
              "Potenza ottimale (kW)", "Quota domanda (\u20ac/anno)",
              "Delta costo energia (\u20ac/anno)", "Degrado (\u20ac/anno)"]
    cols_m = ["Mese", "Picco lordo (kW)", "Picco netto (kW)", "Risparmio quota (\u20ac)"]
    vuoto = {"errore": "Dati insufficienti: nessuna ora valida nel periodo.",
             "valido": False, "n_ore": 0, "n_mesi": 0, "picco_lordo_kw": 0.0,
             "soglia_ottima_kw": None, "potenza_ottimale_kw": None,
             "risparmio_annuo_netto": 0.0, "quota_annua": 0.0,
             "delta_energia_annuo": 0.0, "degrado_annuo": 0.0,
             "mwh_scaricati_annui": 0.0, "payback_anni": None,
             "riduzione_picco_pct": 0.0, "categoria": "non-conviene",
             "verdetto": "",
             "sweep": pd.DataFrame(columns=cols_s),
             "mensile": pd.DataFrame(columns=cols_m)}

    def _err(msg):
        out = dict(vuoto)
        out["errore"] = msg
        return out

    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Dati insufficienti: nessuna ora valida nel periodo.")
    if len(p) == 0 or not isinstance(p.index, pd.DatetimeIndex):
        return _err("Dati insufficienti: nessuna ora valida nel periodo.")
    idx = p.index.tz_localize(None) if p.index.tz is not None else p.index
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)),
              "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        return _err("Imposta una potenza maggiore di zero in almeno una fascia.")
    try:
        cap_kwh = float(cap_mwh) * 1000.0
        pot_kw = float(pot_mw) * 1000.0
    except Exception:
        return _err("Capacita' e potenza della batteria devono essere numeri positivi.")
    if not (cap_kwh > 0.0 and pot_kw > 0.0):
        return _err("Capacita' e potenza della batteria devono essere maggiori di zero.")
    try:
        eff = float(eff_pct) / 100.0
    except Exception:
        eff = float("nan")
    if not (0.0 < eff <= 1.0):
        return _err("Il rendimento deve essere compreso tra 0 e 100% (escluso lo 0).")
    eff_side = float(np.sqrt(eff))
    quota = max(0.0, float(quota_eur_kw_mese or 0.0))
    try:
        p_att = float(potenza_attuale_kw)
    except Exception:
        p_att = float("nan")
    if not (p_att > 0.0):
        return _err("La potenza impegnata attuale deve essere maggiore di zero.")
    degr = max(0.0, float(degrado_eur_mwh or 0.0))
    try:
        capex = max(0.0, float(capex_batteria_eur or 0.0))
    except Exception:
        capex = 0.0
    try:
        n_thr = int(n_soglie)
    except Exception:
        n_thr = 21
    n_thr = max(5, min(61, n_thr))

    ore = idx.hour.to_numpy()
    wd = idx.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    load_kw = np.array([mw_map[f] * 1000.0 for f in fasce])
    price = p.to_numpy(dtype=float)
    picco_lordo = float(load_kw.max())
    if picco_lordo <= 0.0:
        return _err("Imposta una potenza maggiore di zero in almeno una fascia.")

    giorni = idx.to_period("D").to_numpy()
    _, inv = np.unique(giorni, return_inverse=True)
    pos_giorni = [np.flatnonzero(inv == i) for i in range(int(inv.max()) + 1)]
    mesi = idx.to_period("M")
    n_mesi = int(mesi.nunique())
    ann = 12.0 / n_mesi if n_mesi > 0 else 1.0
    # picchi lordi mensili (una sola volta: non dipendono dalla soglia)
    s_load = pd.Series(load_kw, index=idx)
    picchi_lordi_m = s_load.groupby(mesi).max()

    def _simula(T):
        """Simula un anno di gestione giornaliera con soglia T (kW).

        Ritorna (net_kw, mwh_scaricati): serie del prelievo netto e MWh
        scaricati (energia erogata alla rete)."""
        soc = cap_kwh  # parte da batteria piena
        net = load_kw.copy()
        scar_kwh = 0.0
        car_kwh = 0.0
        for pos in pos_giorni:
            ld = load_kw[pos]
            pr = price[pos]
            # --- scarica: prima le ore di carico piu' alto ---
            need = np.minimum(np.maximum(ld - T, 0.0), pot_kw)
            if need.sum() > 0.0 and soc > 0.0:
                order = np.argsort(-ld, kind="stable")
                e_need = need[order] / eff_side  # energia da prelevare dalla batteria
                cum = np.cumsum(e_need)
                mask_full = cum <= soc + 1e-9
                take = np.zeros_like(e_need)
                take[mask_full] = need[order][mask_full]
                usato = float(cum[mask_full][-1]) if mask_full.any() else 0.0
                resto = soc - usato
                idx_p = np.flatnonzero(~mask_full)
                if idx_p.size and resto > 1e-9:
                    j = int(idx_p[0])
                    take[j] = min(float(need[order][j]), resto * eff_side)
                d = np.zeros_like(need)
                d[order] = take
                net[pos] = ld - d
                soc = max(0.0, min(cap_kwh, soc - float((d / eff_side).sum())))
                scar_kwh += float(d.sum())
            # --- ricarica: ore piu' economiche senza superare T ---
            room = cap_kwh - soc
            if room > 1e-9:
                nd = net[pos]
                cand = np.minimum(np.maximum(T - nd, 0.0), pot_kw)
                if cand.sum() > 0.0:
                    order_c = np.argsort(pr, kind="stable")
                    e_in = cand[order_c] * eff_side  # energia che entrerebbe in batteria
                    cum_c = np.cumsum(e_in)
                    mask_f = cum_c <= room + 1e-9
                    take_c = np.zeros_like(e_in)
                    take_c[mask_f] = cand[order_c][mask_f]
                    usato_c = float(cum_c[mask_f][-1]) if mask_f.any() else 0.0
                    resto_c = room - usato_c
                    idx_pc = np.flatnonzero(~mask_f)
                    if idx_pc.size and resto_c > 1e-9:
                        j = int(idx_pc[0])
                        take_c[j] = min(float(cand[order_c][j]), resto_c / eff_side)
                    c = np.zeros_like(cand)
                    c[order_c] = take_c
                    net[pos] = nd + c
                    soc = max(0.0, min(cap_kwh, soc + float((c * eff_side).sum())))
                    car_kwh += float(c.sum())
        return net, scar_kwh / 1000.0, car_kwh / 1000.0

    baseline_kw = min(p_att, picco_lordo)  # livello gia' ottenibile senza batteria
    righe = []
    dettaglio = {}
    for T in np.linspace(0.55 * picco_lordo, picco_lordo, n_thr):
        T = float(T)
        net, mwh_scar, _ = _simula(T)
        delta_eur = float((((net - load_kw) / 1000.0) * price).sum())
        degr_eur = mwh_scar * degr
        s_net = pd.Series(net, index=idx)
        picchi_net = s_net.groupby(mesi).max()
        pot_ott = float(picchi_net.max())
        risparmio_quota = max(0.0, baseline_kw - pot_ott) * quota * n_mesi
        beneficio = risparmio_quota - delta_eur - degr_eur
        righe.append({"Soglia (kW)": round(T, 1),
                      "Risparmio annuo netto (\u20ac)": round(beneficio * ann, 0),
                      "Potenza ottimale (kW)": round(pot_ott, 1),
                      "Quota domanda (\u20ac/anno)": round(risparmio_quota * ann, 0),
                      "Delta costo energia (\u20ac/anno)": round(delta_eur * ann, 0),
                      "Degrado (\u20ac/anno)": round(degr_eur * ann, 0)})
        dettaglio[T] = (net, mwh_scar, delta_eur, degr_eur, risparmio_quota,
                        pot_ott, picchi_net, beneficio)

    sweep = pd.DataFrame(righe, columns=cols_s)
    i_best = int(sweep["Risparmio annuo netto (\u20ac)"].idxmax())
    T_best = float(sweep.loc[i_best, "Soglia (kW)"])
    # ritrova la chiave esatta del dettaglio (arrotondamento a 1 decimale)
    T_key = min(dettaglio.keys(), key=lambda k: abs(k - T_best))
    net_b, mwh_scar_b, delta_b, degr_b, quota_b, pot_ott_b, picchi_net_b, ben_b = dettaglio[T_key]

    righe_m = []
    for per, pl in picchi_lordi_m.items():
        pn = float(picchi_net_b[per])
        rq = max(0.0, baseline_kw - pn) * quota
        righe_m.append({"Mese": per.strftime("%Y-%m"),
                        "Picco lordo (kW)": round(float(pl), 1),
                        "Picco netto (kW)": round(pn, 1),
                        "Risparmio quota (\u20ac)": round(rq, 0)})
    mensile = pd.DataFrame(righe_m, columns=cols_m)

    risparmio_annuo = float(sweep.loc[i_best, "Risparmio annuo netto (\u20ac)"])
    quota_annua = float(sweep.loc[i_best, "Quota domanda (\u20ac/anno)"])
    delta_annuo = float(sweep.loc[i_best, "Delta costo energia (\u20ac/anno)"])
    degr_annuo = float(sweep.loc[i_best, "Degrado (\u20ac/anno)"])
    payback = round(capex / risparmio_annuo, 1) if (capex > 0.0 and risparmio_annuo > 0.0) else None
    rid_picco = (1.0 - pot_ott_b / picco_lordo) * 100.0 if picco_lordo > 0 else 0.0

    if risparmio_annuo <= 0.0:
        categoria = "non-conviene"
        verdetto = (f"Con questi parametri il peak shaving non si ripaga "
                    f"({risparmio_annuo:,.0f} \u20ac/anno): la batteria costa piu' "
                    f"di quanto fa risparmiare su quota di potenza ed energia.")
    elif quota_annua <= 0.0:
        categoria = "inutile"
        verdetto = (f"La batteria porta un beneficio energetico ({risparmio_annuo:,.0f} "
                    f"\u20ac/anno) ma non riduce la potenza impegnata sotto il livello "
                    f"gia' ottenibile senza batteria ({baseline_kw:,.0f} kW): per la "
                    f"quota di potenza e' inutile, valuta il solo arbitraggio.")
    else:
        categoria = "conviene"
        verdetto = (f"Conviene: soglia ottima {T_best:,.0f} kW, potenza impegnata "
                    f"riducibile a {pot_ott_b:,.0f} kW con un beneficio netto di "
                    f"{risparmio_annuo:,.0f} \u20ac/anno.")

    return {"errore": None, "valido": True, "n_ore": int(len(p)), "n_mesi": n_mesi,
            "picco_lordo_kw": round(picco_lordo, 1),
            "soglia_ottima_kw": round(T_best, 1),
            "potenza_ottimale_kw": round(pot_ott_b, 1),
            "risparmio_annuo_netto": risparmio_annuo,
            "quota_annua": quota_annua,
            "delta_energia_annuo": delta_annuo,
            "degrado_annuo": degr_annuo,
            "mwh_scaricati_annui": round(mwh_scar_b * ann, 1),
            "payback_anni": payback,
            "riduzione_picco_pct": round(rid_picco, 1),
            "categoria": categoria, "verdetto": verdetto,
            "sweep": sweep, "mensile": mensile}


def _phi_std(z):
    """CDF della normale standard (approssimazione Abramowitz-Stegun 7.1.26).

    Solo numpy: serve ai test standalone che estraggono le funzioni via AST
    senza gli import di modulo (scipy non disponibile nel namespace isolato).
    """
    x = float(z)
    t = 1.0 / (1.0 + 0.2316419 * abs(x))
    d = 0.3989422804014327 * np.exp(-x * x / 2.0)
    p = d * t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 +
         t * (-1.821255978 + t * 1.330274429))))
    return 1.0 - p if x >= 0 else p


def _gammaln(x):
    """Logaritmo della funzione Gamma (Lanczos g=7), solo numpy.

    Serve alla correzione di Anis-Lloyd dell'R/S atteso per rumore bianco:
    la stima R/S grezza su finestre piccole e' distorta verso l'alto
    (su rumore bianco puro darebbe H ~ 0.65 invece di 0.5), quindi H si
    stima come 0.5 + pendenza di log(R/S / E[R/S_bianco]) su log(n).
    Implementata qui (e non via scipy) perche' i test standalone estraggono
    le funzioni via AST senza gli import di modulo.
    """
    xa = np.atleast_1d(np.asarray(x, dtype=float))
    if np.any(xa <= 0.0):
        raise ValueError("gammaln: x deve essere > 0")
    _c = np.array([0.99999999999980993, 676.5203681218851, -1259.1392167224028,
                   771.32342877765313, -176.61502916214059, 12.507343278686905,
                   -0.13857109526572012, 9.9843695780195716e-6,
                   1.5056327351493116e-7])
    refl = xa < 0.5
    y = np.where(refl, 1.0 - xa, xa) - 1.0
    a = _c[0] + sum(_c[k] / (y + k) for k in range(1, 9))
    t = y + 7.5
    out = 0.5 * np.log(2.0 * np.pi) + (y + 0.5) * np.log(t) - t + np.log(a)
    if np.any(refl):
        xr = xa[refl]
        out[refl] = np.log(np.pi) - np.log(np.sin(np.pi * xr)) - out[refl]
    return out[0] if np.ndim(x) == 0 else out


def _rs_atteso_bianco(n):
    """E[R/S_n] per rumore bianco gaussiano (Anis-Lloyd 1976).

    E[R/S_n] = Gamma((n-1)/2) / (sqrt(pi) * Gamma(n/2))
               * sum_{i=1}^{n-1} sqrt((n-i)/i)
    Usato per correggere la distorsione da campione finito dell'analisi R/S.
    """
    n = int(n)
    if n < 2:
        return float("nan")
    i = np.arange(1, n)
    return float(np.exp(_gammaln((n - 1) / 2.0) - _gammaln(n / 2.0))
                 / np.sqrt(np.pi) * np.sqrt((n - i) / i).sum())


def calcola_hurst(prezzi, scala_min_giorni=4, n_scale=12, min_giorni=60):
    """Esponente di Hurst (analisi R/S) sulle medie giornaliere + runs test di efficienza debole.

    Domanda operativa: 'il prezzo dello spot ha memoria?' H misura la memoria
    di LUNGO periodo della serie:
      H < 0.45  -> MEAN-REVERTING (antipersistente): i movimenti tendono a
                   rientrare; conviene comprare sui cali e vendere sui picchi,
                   e dopo uno shock aspettare il rientro prima di fissare;
      0.45-0.55 -> RANDOM WALK: nessuna memoria sfruttabile; il timing non
                   paga, meglio medie di periodo e strategie sistematiche;
      H > 0.55  -> PERSISTENTE (trending): i movimenti tendono a proseguire;
                   conviene seguire il trend, non scommettere sul rientro.

    Metodo: variazioni giornaliere delle medie giornaliere dei prezzi orari
    (la serie stazionaria su cui l'analisi R/S e' valida: sui livelli grezzi
    sia R che S crescerebbero con la scala, falsando H); analisi R/S
    (rescaled range, S con ddof=0 come nella definizione classica) su finestre
    non sovrapposte di n giorni, con n log-spaziato tra scala_min_giorni e
    N/4 giorni (servono >= 4 scale valide). La stima R/S grezza e' distorta
    verso l'alto sulle finestre piccole (su rumore bianco darebbe H ~ 0.65):
    si applica la correzione di Anis-Lloyd e H = 0.5 + pendenza della retta
    OLS in forma chiusa di log10(R/S / E[R/S_bianco]) su log10(n).
    Completato dal RUNS TEST di Wald-Wolfowitz sui segni delle variazioni
    giornaliere (forma debole dell'efficienza di mercato: con p < 5% i segni
    delle variazioni non sono casuali).

    Differenza rispetto agli altri tab: 'Mean reversion' stima AR(1) sulle ore
    (memoria di BREVE periodo, half-life in ore); 'Autocorrelazione' mostra la
    memoria per singolo lag; qui si misura la memoria di LUNGO periodo su piu'
    scale (settimane/mesi), la scala rilevante per le decisioni di fixing,
    di budgeting e di timing degli acquisti.

    NaN-safe: ore NaN ignorate; giorni senza ore valide esclusi; serie vuota /
    indice non datetime / meno di min_giorni giorni validi / serie giornaliera
    costante o variazioni nulle (S = 0 ovunque) / meno di 4 scale valide ->
    errore pulito.
    Deterministico a parita' di input (nessun seed: solo aritmetica).

    Ritorna dict con 'errore', 'valido', 'n_giorni', 'hurst', 'r2_fit',
    'classe' ('mean-reverting'/'random-walk'/'persistente'), 'verdetto',
    'segnale' (implicazione operativa), 'runs_n', 'runs_osservati',
    'runs_attesi', 'runs_z', 'runs_p', 'runs_verdetto', 'n_scale' e 'scale'
    (DataFrame: 'Finestra (giorni)', 'R/S medio', 'Fit R/S').
    """
    cols = ["Finestra (giorni)", "R/S medio", "Fit R/S"]
    vuoto = {"errore": "Dati insufficienti: servono almeno 60 giorni di prezzi orari validi.",
             "valido": False, "n_giorni": 0, "hurst": None, "r2_fit": None,
             "classe": None, "verdetto": "", "segnale": "", "runs_n": 0,
             "runs_osservati": None, "runs_attesi": None, "runs_z": None,
             "runs_p": None, "runs_verdetto": "", "n_scale": 0,
             "scale": pd.DataFrame(columns=cols)}

    def _err(msg):
        out = dict(vuoto)
        out["errore"] = msg
        return out

    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Dati insufficienti: nessuna ora valida nel periodo.")
    if len(p) == 0 or not isinstance(p.index, pd.DatetimeIndex):
        return _err("Dati insufficienti: nessuna ora valida nel periodo.")
    idx = p.index.tz_localize(None) if p.index.tz is not None else p.index
    p = pd.Series(p.to_numpy(dtype=float), index=idx)
    giorni = p.resample("D").mean().dropna()
    n_g = len(giorni)
    try:
        mg = int(min_giorni)
    except Exception:
        mg = 60
    if n_g < max(30, mg):
        return _err(f"Dati insufficienti: servono almeno {max(30, mg)} giorni "
                    f"validi, trovati {n_g}.")
    x = giorni.to_numpy(dtype=float)
    if not np.all(np.isfinite(x)) or np.all(x == x[0]):
        return _err("Serie giornaliera costante o non finita: R/S non calcolabile.")
    # R/S va calcolato sulle variazioni (serie stazionaria), non sui livelli:
    # sui livelli sia R che S crescono con la scala e H risulta spurio (~1).
    dx = np.diff(x)
    dx = dx[np.isfinite(dx)]
    if len(dx) < 30 or np.all(dx == 0.0):
        return _err("Variazioni giornaliere insufficienti o nulle: R/S non calcolabile.")

    try:
        n_min = max(2, int(scala_min_giorni))
    except Exception:
        n_min = 4
    try:
        ns = max(4, min(24, int(n_scale)))
    except Exception:
        ns = 12
    n_max = len(dx) // 4
    if n_max <= n_min:
        return _err("Serie troppo corta per le scale richieste.")
    raw = np.unique(np.round(np.logspace(np.log10(n_min), np.log10(n_max), ns)).astype(int))
    scale_n = [int(v) for v in raw if int(v) >= n_min]
    if len(scale_n) < 4:
        return _err("Meno di 4 scale valide per la stima di Hurst.")

    def _rs_medio(v, n):
        k = len(v) // n
        if k < 2:
            return np.nan
        vals = []
        for i in range(k):
            ch = v[i * n:(i + 1) * n]
            s = ch.std(ddof=0)  # ddof=0: definizione classica dell'R/S
            if s > 0.0 and np.isfinite(s):
                cum = np.cumsum(ch - ch.mean())
                vals.append((cum.max() - cum.min()) / s)
        return float(np.mean(vals)) if vals else np.nan

    rs = np.array([_rs_medio(dx, n) for n in scale_n])
    ok = np.isfinite(rs) & (rs > 0.0)
    nn = np.array(scale_n, dtype=float)[ok]
    rs = rs[ok]
    if len(nn) < 4:
        return _err("R/S non calcolabile su abbastanza scale (serie quasi costante?).")
    e_bn = np.array([_rs_atteso_bianco(int(n)) for n in nn])
    ok2 = np.isfinite(e_bn) & (e_bn > 0.0)
    nn, rs, e_bn = nn[ok2], rs[ok2], e_bn[ok2]
    if len(nn) < 4:
        return _err("Correzione di Anis-Lloyd non valutabile sulle scale disponibili.")
    lx = np.log10(nn)
    ly = np.log10(rs / e_bn)  # scostamento dal rumore bianco
    mx, my = lx.mean(), ly.mean()
    den = ((lx - mx) ** 2).sum()
    if den <= 0.0:
        return _err("Scale degeneri: stima di Hurst impossibile.")
    pendenza = float(((lx - mx) * (ly - my)).sum() / den)
    hurst = 0.5 + pendenza  # correzione di Anis-Lloyd: il bianco ha pendenza 0
    interc = float(my - pendenza * mx)
    ss_tot = ((ly - my) ** 2).sum()
    ss_res = ((ly - (interc + pendenza * lx)) ** 2).sum()
    r2 = float(1.0 - ss_res / ss_tot) if ss_tot > 0.0 else 0.0
    r2 = max(0.0, min(1.0, r2))

    if hurst < 0.45:
        classe = "mean-reverting"
        segnale = ("Serie ANTIPERSISTENTE: i movimenti tendono a rientrare. "
                   "Strategia: comprare sui cali, vendere sui picchi; dopo uno "
                   "shock, aspettare il rientro prima di fissare il prezzo.")
    elif hurst > 0.55:
        classe = "persistente"
        segnale = ("Serie PERSISTENTE: i movimenti tendono a proseguire. "
                   "Strategia: seguire il trend in corso, non scommettere sul "
                   "rientro; fissare presto se il trend e' al rialzo.")
    else:
        classe = "random-walk"
        segnale = ("RANDOM WALK: nessuna memoria sfruttabile su queste scale. "
                   "Il timing discrezionale non paga: meglio medie di periodo, "
                   "acquisti programmati e strategie sistematiche.")

    segni = np.sign(dx[dx != 0.0])
    runs_n = int(len(segni))
    r_osservati = r_attesi = r_z = r_p = None
    r_verdetto = "Runs test non valutabile (variazioni insufficienti)."
    if runs_n >= 20:
        n_pos = int((segni > 0).sum())
        n_neg = int((segni < 0).sum())
        if n_pos > 0 and n_neg > 0:
            r_osservati = int(1 + (np.diff(segni) != 0).sum())
            n = float(runs_n)
            mu = 2.0 * n_pos * n_neg / n + 1.0
            var = (2.0 * n_pos * n_neg * (2.0 * n_pos * n_neg - n_pos - n_neg)
                   / (n * n * (n - 1.0)))
            r_attesi = float(mu)
            if var > 0.0:
                r_z = float((r_osservati - mu) / np.sqrt(var))
                r_p = float(2.0 * (1.0 - _phi_std(abs(r_z))))
                r_verdetto = ("Efficienza debole RIFIUTATA (p < 5%): i segni delle "
                              "variazioni giornaliere non sono casuali."
                              if r_p < 0.05 else
                              "Efficienza debole NON rifiutata (p >= 5%): i segni "
                              "delle variazioni sono compatibili col caso.")

    verdetto = (f"H = {hurst:.3f} ({classe.replace('-', ' ')}, R2 del fit {r2:.3f} "
                f"su {len(nn)} scale, {n_g} giorni). {segnale}")
    df_scale = pd.DataFrame({
        "Finestra (giorni)": nn.astype(int),
        "R/S medio": np.round(rs, 4),
        "Fit R/S": np.round(e_bn * 10.0 ** (interc + pendenza * lx), 4),
    })
    return {"errore": None, "valido": True, "n_giorni": int(n_g),
            "hurst": round(hurst, 4), "r2_fit": round(r2, 4),
            "classe": classe, "verdetto": verdetto, "segnale": segnale,
            "runs_n": runs_n, "runs_osservati": r_osservati,
            "runs_attesi": round(r_attesi, 2) if r_attesi is not None else None,
            "runs_z": round(r_z, 3) if r_z is not None else None,
            "runs_p": r_p, "runs_verdetto": r_verdetto,
            "n_scale": int(len(nn)), "scale": df_scale}


def calcola_tornado_sensibilita(prezzi, mw_f1, mw_f2, mw_f3, p_contr_kw,
                                quota_kw_mese, oneri_eur_mwh, delta_pct=10.0):
    """Tornado di sensibilita' del costo annuo di fornitura.

    Il costo annuo e' la somma di tre voci (stesso modello delle altre tab
    di costo): ENERGIA = somma(prezzo_orario x MW_orari), QUOTA POTENZA =
    kW impegnati x quota EUR/kW/mese x mesi, ONERI = oneri EUR/MWh x MWh
    totali. I MW orari sono costruiti dal profilo F1/F2/F3 come nelle
    altre tab.

    Il tornado varia UN driver alla volta di +/-delta_pct e misura di
    quanto si muove il costo annuo: il driver con l'ampiezza maggiore e'
    quello su cui il budget e' piu' esposto. Serve a decidere dove
    concentrare fixing, hedging e demand response.

    Driver: 'Prezzo energia', 'Volumi (MWh)', 'Quota potenza (EUR/kW)',
    'Potenza impegnata (kW)', 'Oneri (EUR/MWh)'. I costi del periodo sono
    annualizzati (x 12 / n_mesi).

    NaN-safe: serie vuota / indice non-datetime / < 24 ore / MW tutti a
    zero / costo base non positivo / potenza <= 0 / quota o oneri negativi /
    delta fuori (0, 100] -> errore pulito; tz-aware reso naive.

    Ritorna dict con errore/valido/n_ore/n_mesi/mwh_tot/costo_base_annuo/
    driver_dominante/impatto_max_pos/impatto_max_neg/quota_max_pct/
    verdetto/tornado (DataFrame ordinato per ampiezza decrescente).
    """
    cols = ["Driver", "Impatto + (EUR/a)", "Impatto - (EUR/a)",
            "Ampiezza (EUR/a)", "Quota sul costo (%)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_ore": 0, "n_mesi": 0,
                "mwh_tot": 0.0, "costo_base_annuo": 0.0,
                "driver_dominante": None, "impatto_max_pos": 0.0,
                "impatto_max_neg": 0.0, "quota_max_pct": 0.0,
                "verdetto": msg, "tornado": pd.DataFrame(columns=cols)}

    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    try:
        p_contr = float(p_contr_kw)
        quota = float(quota_kw_mese)
        oneri = float(oneri_eur_mwh)
        d = float(delta_pct)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: potenza, quota, oneri e delta devono essere numeri.")
    if not p_contr > 0:
        return _err("Potenza contrattuale non valida: inserisci un valore > 0 kW.")
    if quota < 0:
        return _err("Quota potenza non valida: non puo' essere negativa.")
    if oneri < 0:
        return _err("Oneri non validi: non possono essere negativi.")
    if not 0.0 < d <= 100.0:
        return _err("Delta non valido: inserisci una percentuale tra 0 (escluso) e 100.")
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Input non valido: serie prezzi non leggibile.")
    if len(p) < 24:
        return _err("Serie troppo corta: servono almeno 24 ore di prezzi.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)),
              "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        return _err("Imposta una potenza maggiore di zero in almeno una fascia.")

    ore = p.index.hour.to_numpy()
    wd = p.index.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, dd) for h, dd in zip(ore, wd)])
    mw = np.array([mw_map[f] for f in fasce])  # MW orari del profilo
    pv = p.to_numpy(dtype=float)

    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    n_mesi = int(idxn.to_period("M").nunique())
    ann = 12.0 / n_mesi
    mwh = float(mw.sum())
    ce = float((pv * mw).sum())        # costo energia del periodo
    cq = p_contr * quota * n_mesi      # quota potenza del periodo
    co = oneri * mwh                   # oneri del periodo
    base = ce + cq + co
    if not base > 0:
        return _err("Costo base non positivo: verifica prezzi e profilo di carico.")

    dd = d / 100.0
    drivers = [
        ("Prezzo energia",
         lambda s: float((pv * (1.0 + s) * mw).sum()) + cq + co),
        ("Volumi (MWh)",
         lambda s: float((pv * mw * (1.0 + s)).sum()) + cq + oneri * mwh * (1.0 + s)),
        ("Quota potenza (EUR/kW)",
         lambda s: ce + p_contr * quota * (1.0 + s) * n_mesi + co),
        ("Potenza impegnata (kW)",
         lambda s: ce + p_contr * (1.0 + s) * quota * n_mesi + co),
        ("Oneri (EUR/MWh)",
         lambda s: ce + cq + oneri * (1.0 + s) * mwh),
    ]
    base_a = base * ann
    righe = []
    for nome, fn in drivers:
        up = (fn(dd) - base) * ann
        dn = (fn(-dd) - base) * ann
        amp = max(abs(up), abs(dn))
        righe.append({"Driver": nome,
                      "Impatto + (EUR/a)": round(up, 0),
                      "Impatto - (EUR/a)": round(dn, 0),
                      "Ampiezza (EUR/a)": round(amp, 0),
                      "Quota sul costo (%)": round(100.0 * amp / base_a, 2)})
    tornado = (pd.DataFrame(righe, columns=cols)
               .sort_values("Ampiezza (EUR/a)", ascending=False, kind="mergesort")
               .reset_index(drop=True))
    dom = str(tornado.iloc[0]["Driver"])
    amp_max = float(tornado.iloc[0]["Ampiezza (EUR/a)"])
    q_max = float(tornado.iloc[0]["Quota sul costo (%)"])
    ipos = float(tornado["Impatto + (EUR/a)"].max())
    ineg = float(tornado["Impatto - (EUR/a)"].min())

    nota = {
        "Prezzo energia": "Il mercato pesa piu' del contratto: priorita' a fixing e coperture.",
        "Volumi (MWh)": "Il profilo di consumo pesa piu' del prezzo: priorita' a demand response ed efficienza.",
        "Quota potenza (EUR/kW)": "La voce di rete domina: rinegozia quota e potenza col distributore.",
        "Potenza impegnata (kW)": "Il tetto di potenza domina il conto: vedi la tab 'Potenza impegnata' per l'ottimo.",
        "Oneri (EUR/MWh)": "Gli oneri di sistema dominano: verifica esenzioni e voci in bolletta.",
    }.get(dom, "")
    verdetto = (f"Tornado: driver dominante {dom} — uno shock di ±{d:.0f}% muove il costo "
                f"annuo di {amp_max:,.0f} EUR/anno ({q_max:.1f}% del totale di {base_a:,.0f} EUR/anno). {nota}")

    return {"errore": None, "valido": True, "n_ore": int(len(p)),
            "n_mesi": n_mesi, "mwh_tot": round(mwh, 1),
            "costo_base_annuo": round(base_a, 0),
            "driver_dominante": dom, "impatto_max_pos": round(ipos, 0),
            "impatto_max_neg": round(ineg, 0), "quota_max_pct": round(q_max, 2),
            "verdetto": verdetto, "tornado": tornado}
def calcola_segnali_tecnici(prezzi, rsi_period=14, macd_fast=12, macd_slow=26,
                           macd_signal=9, sma_breve=20, sma_lunga=50,
                           bb_period=20, bb_mult=2.0, orizzonte_gg=5):
    """Segnali tecnici sul prezzo: RSI, MACD, incroci di medie mobili, Bande di Bollinger.

    Lavora sulle medie GIORNALIERE dei prezzi orari (gli indicatori tecnici
    sullo spot orario sono rumore). Per ogni indicatore genera segnali
    BUY/SELL sugli eventi classici:
      - Medie mobili: golden cross (media breve sopra la lunga) = BUY,
        death cross = SELL;
      - MACD: istogramma che attraversa lo zero verso l'alto = BUY, verso il
        basso = SELL;
      - RSI (Wilder): scende sotto 30 = BUY (ipervenduto), sale sopra 70 =
        SELL (ipercomprato);
      - Bollinger: chiusura che rompe la banda inferiore = BUY (mean
        reversion), che rompe la superiore = SELL.
    Ogni segnale e' backtestato sull'orizzonte scelto: esito = variazione
    del prezzo nei giorni successivi (segno invertito per i SELL, cosi' un
    esito positivo = "il segnale aveva ragione"). Hit rate = quota di
    segnali con esito positivo.

    NaN-safe: serie vuota / indice non-datetime / troppo corta / parametri
    non validi -> errore pulito; tz-aware reso naive; prezzi <= 0 saltati
    nel backtest (rendimenti non definiti); deterministico.

    Ritorna dict con errore/valido/n_giorni/giorni_richiesti/ultimo
    (prezzo/rsi/macd/macd_signal/hist/sma_breve/sma_lunga/bb_pos_pct)/
    stance (sma/rsi/macd/bb)/punteggio/verdetto/n_segnali/hit_rate_tot/
    esito_medio_tot/segnali (DataFrame)/riepilogo (DataFrame)/serie
    (DataFrame giornaliero con gli indicatori).
    """
    col_s = ["Data", "Indicatore", "Segnale", "Prezzo (EUR/MWh)",
             "Esito orizzonte (%)", "Esito valido"]
    col_r = ["Indicatore", "N. segnali", "Hit rate (%)", "Esito medio (%)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_giorni": 0,
                "giorni_richiesti": 0, "ultimo": {}, "stance": {},
                "punteggio": 0, "verdetto": msg, "n_segnali": 0,
                "hit_rate_tot": float("nan"), "esito_medio_tot": float("nan"),
                "segnali": pd.DataFrame(columns=col_s),
                "riepilogo": pd.DataFrame(columns=col_r),
                "serie": pd.DataFrame()}

    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    try:
        rp = int(rsi_period); mf = int(macd_fast); ms = int(macd_slow)
        mgs = int(macd_signal); sb = int(sma_breve); sl = int(sma_lunga)
        bp = int(bb_period); bm = float(bb_mult); hz = int(orizzonte_gg)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: periodi e orizzonte devono essere numeri.")
    if not 2 <= rp <= 100:
        return _err("Periodo RSI non valido: inserisci un intero tra 2 e 100.")
    if not (2 <= mf < ms <= 200):
        return _err("Parametri MACD non validi: serve 2 <= fast < slow <= 200.")
    if not 2 <= mgs <= 100:
        return _err("Periodo segnale MACD non valido: inserisci un intero tra 2 e 100.")
    if not (2 <= sb < sl <= 300):
        return _err("Medie mobili non valide: serve 2 <= breve < lunga <= 300.")
    if not 2 <= bp <= 200:
        return _err("Periodo Bollinger non valido: inserisci un intero tra 2 e 200.")
    if not 0.5 <= bm <= 5.0:
        return _err("Moltiplicatore Bollinger non valido: inserisci un valore tra 0,5 e 5.")
    if not 1 <= hz <= 60:
        return _err("Orizzonte non valido: inserisci un intero tra 1 e 60 giorni.")
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Input non valido: serie prezzi non leggibile.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    if p.index.tz is not None:
        p.index = p.index.tz_localize(None)
    if len(p) == 0:
        return _err("Serie vuota: nessun prezzo valido.")

    richiesti = max(sl, ms + mgs, bp, rp + 1, hz + 2)
    s = p.resample("D").mean().dropna()
    n = len(s)
    if n < richiesti:
        return _err("Serie troppo corta: servono almeno %d giorni di prezzi (ne hai %d)."
                    % (richiesti, n))

    idx = s.index
    px = s.to_numpy(dtype=float)

    # --- RSI di Wilder ---
    delta = s.diff()
    gain = delta.clip(lower=0.0)
    loss = -delta.clip(upper=0.0)
    ag = gain.ewm(alpha=1.0 / rp, min_periods=rp, adjust=False).mean()
    al = loss.ewm(alpha=1.0 / rp, min_periods=rp, adjust=False).mean()
    rsi = 100.0 - 100.0 / (1.0 + ag / al)
    rsi = rsi.mask((ag == 0) & (al == 0), 50.0)  # serie piatta -> RSI neutro

    # --- MACD ---
    ema_f = s.ewm(span=mf, adjust=False).mean()
    ema_s = s.ewm(span=ms, adjust=False).mean()
    macd = ema_f - ema_s
    macd_sig = macd.ewm(span=mgs, adjust=False).mean()
    hist = macd - macd_sig

    # --- Medie mobili ---
    sma_b = s.rolling(sb, min_periods=sb).mean()
    sma_l = s.rolling(sl, min_periods=sl).mean()

    # --- Bande di Bollinger ---
    mid = s.rolling(bp, min_periods=bp).mean()
    sd = s.rolling(bp, min_periods=bp).std(ddof=1)
    up = mid + bm * sd
    lo = mid - bm * sd
    up_v = up.to_numpy(dtype=float)
    lo_v = lo.to_numpy(dtype=float)
    rng = up_v - lo_v
    pos = np.where(rng > 0, (px - lo_v) / rng * 100.0, 50.0)

    rsi_v = rsi.to_numpy(dtype=float)
    hist_v = hist.to_numpy(dtype=float)
    sb_v = sma_b.to_numpy(dtype=float)
    sl_v = sma_l.to_numpy(dtype=float)

    def _ok(*vals):
        return all(v is not None and not (isinstance(v, float) and np.isnan(v))
                   for v in vals)

    segnali = []
    for i in range(1, n):
        d = idx[i]
        pr = px[i]
        if _ok(sb_v[i - 1], sl_v[i - 1], sb_v[i], sl_v[i]):
            if sb_v[i - 1] <= sl_v[i - 1] and sb_v[i] > sl_v[i]:
                segnali.append((d, "Medie mobili", "BUY", pr,
                                "Golden cross: media breve sopra la lunga"))
            elif sb_v[i - 1] >= sl_v[i - 1] and sb_v[i] < sl_v[i]:
                segnali.append((d, "Medie mobili", "SELL", pr,
                                "Death cross: media breve sotto la lunga"))
        if _ok(hist_v[i - 1], hist_v[i]):
            if hist_v[i - 1] <= 0 < hist_v[i]:
                segnali.append((d, "MACD", "BUY", pr, "Istogramma sopra lo zero"))
            elif hist_v[i - 1] >= 0 > hist_v[i]:
                segnali.append((d, "MACD", "SELL", pr, "Istogramma sotto lo zero"))
        if _ok(rsi_v[i - 1], rsi_v[i]):
            if rsi_v[i - 1] >= 30.0 and rsi_v[i] < 30.0:
                segnali.append((d, "RSI", "BUY", pr, "RSI sotto 30: ipervenduto"))
            elif rsi_v[i - 1] <= 70.0 and rsi_v[i] > 70.0:
                segnali.append((d, "RSI", "SELL", pr, "RSI sopra 70: ipercomprato"))
        if _ok(lo_v[i - 1], lo_v[i], up_v[i - 1], up_v[i]):
            if px[i - 1] >= lo_v[i - 1] and pr < lo_v[i]:
                segnali.append((d, "Bollinger", "BUY", pr,
                                "Chiusura sotto la banda inferiore"))
            elif px[i - 1] <= up_v[i - 1] and pr > up_v[i]:
                segnali.append((d, "Bollinger", "SELL", pr,
                                "Chiusura sopra la banda superiore"))

    # --- Backtest dei segnali sull'orizzonte ---
    righe = []
    for (d, ind, tipo, pr, motivo) in segnali:
        i = int(idx.get_loc(d))
        esito = float("nan")
        valido_e = False
        j = i + hz
        if j < n and pr > 0 and px[j] > 0:
            ret = (px[j] - pr) / pr * 100.0
            esito = ret if tipo == "BUY" else -ret
            valido_e = True
        righe.append({"Data": d.date(), "Indicatore": ind, "Segnale": tipo,
                      "Prezzo (EUR/MWh)": round(float(pr), 2),
                      "Esito orizzonte (%)": round(float(esito), 2) if valido_e else float("nan"),
                      "Esito valido": valido_e, "_motivo": motivo})
    df_seg = pd.DataFrame(righe, columns=col_s + ["_motivo"])

    riepilogo = []
    for ind in ["Medie mobili", "MACD", "RSI", "Bollinger"]:
        sub = df_seg[(df_seg["Indicatore"] == ind) & (df_seg["Esito valido"])]
        nn = len(sub)
        if nn:
            hit = float((sub["Esito orizzonte (%)"] > 0).mean() * 100.0)
            avg = float(sub["Esito orizzonte (%)"].mean())
        else:
            hit, avg = float("nan"), float("nan")
        riepilogo.append({"Indicatore": ind, "N. segnali": nn,
                          "Hit rate (%)": round(hit, 1) if nn else float("nan"),
                          "Esito medio (%)": round(avg, 2) if nn else float("nan")})
    df_riep = pd.DataFrame(riepilogo, columns=col_r)
    sub_all = df_seg[df_seg["Esito valido"]]
    if len(sub_all):
        hit_tot = round(float((sub_all["Esito orizzonte (%)"] > 0).mean() * 100.0), 1)
        avg_tot = round(float(sub_all["Esito orizzonte (%)"].mean()), 2)
    else:
        hit_tot, avg_tot = float("nan"), float("nan")

    # --- Lettura dell'ultimo giorno ---
    macd_v = macd.to_numpy(dtype=float)
    msg_v = macd_sig.to_numpy(dtype=float)
    ultimo = {"prezzo": round(float(px[-1]), 2),
              "rsi": round(float(rsi_v[-1]), 1) if _ok(rsi_v[-1]) else float("nan"),
              "macd": round(float(macd_v[-1]), 2),
              "macd_signal": round(float(msg_v[-1]), 2),
              "hist": round(float(hist_v[-1]), 2),
              "sma_breve": round(float(sb_v[-1]), 2),
              "sma_lunga": round(float(sl_v[-1]), 2),
              "bb_pos_pct": round(float(pos[-1]), 1)}
    st_sma = (1 if _ok(sb_v[-1], sl_v[-1]) and sb_v[-1] > sl_v[-1]
              else (-1 if _ok(sb_v[-1], sl_v[-1]) and sb_v[-1] < sl_v[-1] else 0))
    st_rsi = (1 if _ok(rsi_v[-1]) and rsi_v[-1] < 30
              else (-1 if _ok(rsi_v[-1]) and rsi_v[-1] > 70 else 0))
    st_macd = (1 if _ok(hist_v[-1]) and hist_v[-1] > 0
               else (-1 if _ok(hist_v[-1]) and hist_v[-1] < 0 else 0))
    st_bb = 1 if pos[-1] < 20 else (-1 if pos[-1] > 80 else 0)
    stance = {"sma": st_sma, "rsi": st_rsi, "macd": st_macd, "bb": st_bb}
    punteggio = st_sma + st_rsi + st_macd + st_bb
    if punteggio >= 2:
        verdetto = ("Segnale composito RIALZISTA (+%d): la maggioranza degli indicatori "
                    "punta verso l'alto — il mercato spot e' in fase di forza." % punteggio)
    elif punteggio <= -2:
        verdetto = ("Segnale composito RIBASSISTA (%d): la maggioranza degli indicatori "
                    "punta verso il basso — il mercato spot e' in fase di debolezza." % punteggio)
    else:
        verdetto = ("Segnale composito NEUTRO (%+d): gli indicatori sono discordi — "
                    "nessuna direzione prevalente, meglio attendere conferme." % punteggio)
    verdetto += (" Gli indicatori tecnici sullo spot elettrico sono un ausilio di timing, "
                 "non una previsione: usali insieme a fondamentali e coperture.")

    serie = pd.DataFrame({"prezzo": s, "sma_breve": sma_b, "sma_lunga": sma_l,
                          "bb_mid": mid, "bb_up": up, "bb_lo": lo,
                          "rsi": rsi, "macd": macd, "macd_signal": macd_sig,
                          "hist": hist})

    return {"errore": None, "valido": True, "n_giorni": n,
            "giorni_richiesti": richiesti, "ultimo": ultimo, "stance": stance,
            "punteggio": punteggio, "verdetto": verdetto,
            "n_segnali": len(df_seg), "hit_rate_tot": hit_tot,
            "esito_medio_tot": avg_tot,
            "segnali": df_seg.drop(columns=["_motivo"]),
            "riepilogo": df_riep, "serie": serie}











def _pesi_profilo_tipo(nome, ore, dow, mese):
    """Pesi orari (relativi) di un profilo tipo di cliente.

    ore/dow/mese: array numpy (ora 0-23, weekday 0=lun..6=dom, mese 1-12).
    Ritorna array float >= 0 della stessa lunghezza. Profili deterministici,
    senza dati esterni:
      - 'residenziale': picco serale 19-22, notte bassa, weekend piu' carico di giorno;
      - 'uffici': 8-18 feriali, quasi zero notte/weekend;
      - 'industriale_2t': due turni 6-22 feriali, minimo il resto;
      - 'industriale_3t': continuo 24/7 (piatto);
      - 'pompa_calore': base residenziale + zoccolo, pesata per stagione
        (inverno x1.6, spalla x1.0, estate x0.3 solo ACS).
    """
    ore = np.asarray(ore, dtype=int)
    dow = np.asarray(dow, dtype=int)
    mese = np.asarray(mese, dtype=int)
    feriale = dow < 5

    res_fer = np.array([0.15, 0.12, 0.12, 0.12, 0.12, 0.15,
                        0.45, 0.70, 0.45, 0.40, 0.38, 0.38,
                        0.45, 0.38, 0.38, 0.38, 0.45, 0.60,
                        0.85, 1.00, 1.00, 0.85, 0.55, 0.30])
    res_we = np.array([0.15, 0.12, 0.12, 0.12, 0.12, 0.15,
                       0.35, 0.55, 0.65, 0.65, 0.65, 0.65,
                       0.70, 0.65, 0.65, 0.65, 0.65, 0.70,
                       0.85, 1.00, 1.00, 0.85, 0.55, 0.30])
    uff_fer = np.array([0.05, 0.05, 0.05, 0.05, 0.05, 0.05,
                        0.05, 0.35, 1.00, 1.00, 1.00, 1.00,
                        1.00, 1.00, 1.00, 1.00, 1.00, 1.00,
                        0.50, 0.25, 0.05, 0.05, 0.05, 0.05])
    ind2_fer = np.array([0.12, 0.12, 0.12, 0.12, 0.12, 0.12,
                         1.00, 1.00, 1.00, 1.00, 1.00, 1.00,
                         1.00, 1.00, 1.00, 1.00, 1.00, 1.00,
                         1.00, 1.00, 1.00, 1.00, 0.12, 0.12])

    if nome == "residenziale":
        w = np.where(feriale, res_fer[ore], res_we[ore])
    elif nome == "uffici":
        w = np.where(feriale, uff_fer[ore], 0.05)
    elif nome == "industriale_2t":
        w = np.where(feriale, ind2_fer[ore], 0.12)
    elif nome == "industriale_3t":
        w = np.ones_like(ore, dtype=float)
    elif nome == "pompa_calore":
        base = np.where(feriale, res_fer[ore], res_we[ore])
        base = np.maximum(base, 0.35)
        stag = np.where(np.isin(mese, [11, 12, 1, 2, 3]), 1.6,
               np.where(np.isin(mese, [4, 10]), 1.0, 0.3))
        w = base * stag
    else:
        raise ValueError(f"profilo tipo sconosciuto: {nome}")
    return w.astype(float)


PROFILI_TIPO = [
    ("residenziale", "🏠 Residenziale", "Picco serale, consumi concentrati 17-22."),
    ("uffici", "🏢 Uffici", "Prelievo 8-18 nei feriali, quasi zero notte e weekend."),
    ("industriale_2t", "🏭 Industriale 2 turni", "Prelievo pieno 6-22 feriali, minimo il resto."),
    ("industriale_3t", "🏗️ Industriale continuo", "Prelievo costante 24/7, fattore di carico 100%."),
    ("pompa_calore", "🔥 Pompa di calore", "Profilo residenziale con zoccolo, pesato sulla stagione (inverno x1.6)."),
]


def calcola_profili_tipo(prezzi, energia_annua_mwh=1000.0, profili=None, min_ore=168):
    """Confronto del costo di fornitura per profili tipo di cliente.

    Domanda operativa: "quanto costa servire un residenziale rispetto a un
    industriale continuo, a parita' di energia annua?" — applica i profili
    orari standard (_pesi_profilo_tipo) ai prezzi spot del periodo e calcola
    per ciascuno: energia, costo, prezzo catturato (€/MWh), premio/sconto
    rispetto al prezzo medio aritmetico, picco, fattore di carico e quota
    di energia per fascia F1/F2/F3. L'energia annua viene riscalata sul
    periodo (ore_periodo / 8760), cosi' i profili restano confrontabili su
    periodi di qualsiasi lunghezza.

    NaN-safe: serie vuota / indice non-datetime / non numerica / troppo
    corta / energia non positiva -> errore pulito; tz-aware reso naive;
    deterministico.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        en = float(energia_annua_mwh)
    except (TypeError, ValueError):
        return _err("energia_annua_mwh non valida")
    if not np.isfinite(en) or en <= 0:
        return _err("energia_annua_mwh deve essere positiva")

    if profili is None:
        nomi = [p[0] for p in PROFILI_TIPO]
    else:
        nomi = [p for p in profili if p in dict((x[0], x[1]) for x in PROFILI_TIPO)]
        if not nomi:
            return _err("nessun profilo valido selezionato")

    try:
        s = pd.Series(prezzi).dropna()
    except (TypeError, ValueError):
        return _err("serie prezzi non valida")
    if len(s) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(s.index, pd.DatetimeIndex):
        return _err("l'indice dei prezzi deve essere datetime")
    try:
        s = s.astype(float)
    except (TypeError, ValueError):
        return _err("prezzi non numerici")
    if len(s) < int(min_ore):
        return _err(f"servono almeno {int(min_ore)} ore di prezzi")

    idx = s.index
    if idx.tz is not None:
        idx = idx.tz_localize(None)
    ore = idx.hour.to_numpy()
    dow = idx.dayofweek.to_numpy()
    mese = idx.month.to_numpy()
    pv = s.to_numpy(dtype=float)
    n_ore = len(s)
    energia_periodo = en * n_ore / 8760.0
    prezzo_medio = float(np.mean(pv))
    fasce = np.array([_fascia_aeegsi(h, w) for h, w in zip(ore.tolist(), dow.tolist())])

    etichette = {p[0]: (p[1], p[2]) for p in PROFILI_TIPO}
    righe, mensili = [], []
    for nome in nomi:
        w = _pesi_profilo_tipo(nome, ore, dow, mese)
        sw = float(w.sum())
        if sw <= 0:
            return _err(f"profilo '{nome}' con pesi nulli sul periodo")
        mwh_h = w / sw * energia_periodo
        costo_h = mwh_h * pv
        costo = float(costo_h.sum())
        catturato = costo / energia_periodo
        picco = float(mwh_h.max())
        fc = energia_periodo / (picco * n_ore) * 100.0 if picco > 0 else 0.0
        q_f1 = float(mwh_h[fasce == "F1"].sum() / energia_periodo * 100.0)
        q_f2 = float(mwh_h[fasce == "F2"].sum() / energia_periodo * 100.0)
        q_f3 = float(mwh_h[fasce == "F3"].sum() / energia_periodo * 100.0)
        etichetta = etichette[nome][0]
        righe.append({
            "Profilo": etichetta,
            "Energia (MWh)": round(energia_periodo, 1),
            "Costo (€)": round(costo, 0),
            "Prezzo catturato (€/MWh)": round(catturato, 2),
            "Premio vs medio (€/MWh)": round(catturato - prezzo_medio, 2),
            "Picco (MW)": round(picco, 3),
            "Fattore di carico (%)": round(fc, 1),
            "Quota F1 (%)": round(q_f1, 1),
            "Quota F2 (%)": round(q_f2, 1),
            "Quota F3 (%)": round(q_f3, 1),
        })
        mese_lbl = idx.strftime("%Y-%m")
        for m in sorted(set(mese_lbl.tolist())):
            mk = mese_lbl == m
            mensili.append({
                "Mese": m, "Profilo": etichetta,
                "MWh": round(float(mwh_h[mk].sum()), 1),
                "Costo (€)": round(float(costo_h[mk].sum()), 0),
            })

    tabella = pd.DataFrame(righe)
    df_mens = pd.DataFrame(mensili).sort_values(["Mese", "Profilo"]).reset_index(drop=True)
    idx_min = tabella["Prezzo catturato (€/MWh)"].idxmin()
    idx_max = tabella["Prezzo catturato (€/MWh)"].idxmax()
    verdetto = (f"A parita' di energia ({energia_periodo:,.0f} MWh nel periodo), "
                f"{tabella.loc[idx_min, 'Profilo']} cattura il prezzo piu' basso "
                f"({tabella.loc[idx_min, 'Prezzo catturato (€/MWh)']:.2f} €/MWh), "
                f"{tabella.loc[idx_max, 'Profilo']} il piu' alto "
                f"({tabella.loc[idx_max, 'Prezzo catturato (€/MWh)']:.2f} €/MWh): "
                f"differenza {tabella.loc[idx_max, 'Prezzo catturato (€/MWh)'] - tabella.loc[idx_min, 'Prezzo catturato (€/MWh)']:.2f} €/MWh "
                f"({(tabella.loc[idx_max, 'Prezzo catturato (€/MWh)'] - tabella.loc[idx_min, 'Prezzo catturato (€/MWh)']) * energia_periodo:,.0f} € sul periodo).")
    return {
        "errore": None, "valido": True,
        "tabella": tabella, "mensile": df_mens,
        "prezzo_medio": round(prezzo_medio, 2),
        "energia_periodo": round(energia_periodo, 1),
        "n_ore": n_ore,
        "profilo_min": tabella.loc[idx_min, "Profilo"],
        "profilo_max": tabella.loc[idx_max, "Profilo"],
        "catturato_min": float(tabella.loc[idx_min, "Prezzo catturato (€/MWh)"]),
        "catturato_max": float(tabella.loc[idx_max, "Prezzo catturato (€/MWh)"]),
        "verdetto": verdetto,
    }


def genera_forecast_naive(reali, metodo="lag24"):
    """Genera una serie forecast naive dalla serie reale (benchmark di riferimento).

    Domanda operativa: "il mio forecast vale qualcosa?" — se un modello vero non
    batte questi benchmark banali, non serve a niente. Metodi:
      "lag24"  = valore di 24h fa (ieri, stessa ora);
      "lag168" = valore di 168h fa (stessa ora della settimana scorsa);
      "mm24"   = media mobile delle 24 ore precedenti.
    Restituisce la serie forecast sullo stesso indice della reale (con NaN in
    testa dove il lag non ha storia). NaN-safe, tz-aware reso naive, deterministico.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        s = pd.Series(reali).dropna()
    except (TypeError, ValueError):
        return _err("serie reale non valida")
    if len(s) == 0:
        return _err("serie reale vuota")
    if not isinstance(s.index, pd.DatetimeIndex):
        return _err("l'indice della serie reale deve essere datetime")
    try:
        s = s.astype(float)
    except (TypeError, ValueError):
        return _err("valori della serie reale non numerici")
    if s.index.tz is not None:
        s = s.tz_convert(None)
    s = s.sort_index()
    if metodo == "lag24":
        fc = s.shift(24)
        descr = "Naive 24h (ieri, stessa ora)"
    elif metodo == "lag168":
        fc = s.shift(168)
        descr = "Naive 168h (settimana scorsa, stessa ora)"
    elif metodo == "mm24":
        fc = s.shift(1).rolling(24, min_periods=1).mean()
        descr = "Media mobile 24h precedenti"
    else:
        return _err(f"metodo '{metodo}' non riconosciuto")
    return {"errore": None, "valido": True, "forecast": fc, "metodo": descr,
            "n_ore": int(len(s))}


def calcola_accuratezza_forecast(reali, forecast, min_ore=24, top_n=10):
    """Valutazione di un forecast contro i valori reali.

    Domanda operativa: "il mio forecast di prezzo/carico e' affidabile?" —
    allinea reali e forecast sull'indice datetime comune e calcola MAE, RMSE,
    MAPE, bias (errore medio firmato), deviazione std dell'errore e correlazione;
    lo SKILL SCORE confronta il MAE col benchmark naive (persistenza 24h):
    positivo = il forecast batte il naive, negativo = peggio del banale.
    Profilo orario dell'errore (per ora del giorno) + peggiori ore per |errore|.

    NaN-safe: serie vuota / indice non-datetime / non numerica / troppo poche
    ore in comune / parametri non validi -> errore pulito; tz-aware reso naive;
    deterministico.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        mo = int(min_ore)
    except (TypeError, ValueError):
        return _err("min_ore non valido")
    if mo < 1:
        return _err("min_ore deve essere >= 1")
    try:
        tn = int(top_n)
    except (TypeError, ValueError):
        return _err("top_n non valido")
    if tn < 1:
        return _err("top_n deve essere >= 1")

    def _clean(s, nome):
        try:
            c = pd.Series(s).dropna()
        except (TypeError, ValueError):
            return None, f"{nome}: serie non valida"
        if len(c) == 0:
            return None, f"{nome}: serie vuota"
        if not isinstance(c.index, pd.DatetimeIndex):
            return None, f"{nome}: l'indice deve essere datetime"
        try:
            c = c.astype(float)
        except (TypeError, ValueError):
            return None, f"{nome}: valori non numerici"
        if c.index.tz is not None:
            c.index = c.index.tz_localize(None)
        return c.sort_index(), None

    r, em = _clean(reali, "reali")
    if em:
        return _err(em)
    f, em = _clean(forecast, "forecast")
    if em:
        return _err(em)

    df = pd.DataFrame({"reale": r, "forecast": f}).dropna()
    if len(df) < mo:
        return _err(f"servono almeno {mo} ore in comune tra reali e forecast (trovate {len(df)})")
    e = (df["forecast"] - df["reale"]).to_numpy(dtype=float)
    rv = df["reale"].to_numpy(dtype=float)
    n = len(df)
    mae = float(np.mean(np.abs(e)))
    rmse = float(np.sqrt(np.mean(e ** 2)))
    bias = float(np.mean(e))
    std_e = float(np.std(e))
    nz = rv != 0
    mape = float(np.mean(np.abs(e[nz] / rv[nz])) * 100.0) if nz.any() else None
    corr = None
    if np.std(rv) > 0 and np.std(df["forecast"].to_numpy(dtype=float)) > 0:
        corr = float(np.corrcoef(rv, df["forecast"].to_numpy(dtype=float))[0, 1])

    # Skill score vs benchmark naive (persistenza 24h sulla serie reale)
    skill = None
    mae_naive = None
    if n > 24:
        nv = df["reale"].shift(24).dropna()
        en = (nv - df["reale"].loc[nv.index]).to_numpy(dtype=float)
        if len(en) > 0:
            mae_naive = float(np.mean(np.abs(en)))
            if mae_naive > 0:
                skill = float(1.0 - mae / mae_naive)

    ore = df.index.hour.to_numpy()
    prof = pd.DataFrame({"ora": ore, "err": e, "ae": np.abs(e)}).groupby("ora").agg(
        ore_n=("err", "size"),
        err_medio=("err", "mean"),
        mae=("ae", "mean"),
    ).reset_index().sort_values("ora")

    peg = df.assign(errore=e, aerr=np.abs(e)).nlargest(tn, "aerr")
    peggiori = pd.DataFrame({
        "Timestamp": peg.index.strftime("%Y-%m-%d %H:%M"),
        "Reale": peg["reale"].round(2).to_numpy(),
        "Forecast": peg["forecast"].round(2).to_numpy(),
        "Errore": peg["errore"].round(2).to_numpy(),
    })

    righe = [
        ("Ore valutate", f"{n}"),
        ("MAE (errore medio assoluto)", f"{mae:.2f}"),
        ("RMSE", f"{rmse:.2f}"),
        ("Bias (errore medio firmato)", f"{bias:+.2f}"),
        ("Deviazione std errore", f"{std_e:.2f}"),
        ("MAPE", f"{mape:.2f} %" if mape is not None else "n/d (reali a zero)"),
        ("Correlazione", f"{corr:.3f}" if corr is not None else "n/d (serie costante)"),
        ("MAE benchmark naive 24h", f"{mae_naive:.2f}" if mae_naive is not None else "n/d (< 48h)"),
        ("Skill score vs naive", f"{skill:+.1%}" if skill is not None else "n/d"),
    ]
    tabella = pd.DataFrame(righe, columns=["Metrica", "Valore"])

    if abs(bias) < 0.1 * mae:
        nota_bias = "senza distorsione sistematica"
    elif bias > 0:
        nota_bias = "sovrastima sistematica (forecast sopra il reale)"
    else:
        nota_bias = "sottostima sistematica (forecast sotto il reale)"
    if skill is None:
        nota_skill = "skill non calcolabile (serie troppo corta per il benchmark)"
    elif skill >= 0.2:
        nota_skill = f"batte il benchmark naive del {skill:.0%} — il modello aggiunge valore"
    elif skill >= 0:
        nota_skill = "in linea col benchmark naive — valore aggiunto marginale"
    else:
        nota_skill = f"peggio del naive ({skill:.0%}) — meglio usare ieri stessa ora"
    verdetto = (f"Su {n} ore: MAE {mae:.2f}, RMSE {rmse:.2f}, {nota_bias}; {nota_skill}.")

    return {
        "errore": None, "valido": True,
        "n_ore": n, "mae": mae, "rmse": rmse, "bias": bias,
        "std_errore": std_e, "mape": mape, "correlazione": corr,
        "mae_naive": mae_naive, "skill": skill,
        "profilo_orario": prof, "peggiori": peggiori,
        "tabella": tabella, "verdetto": verdetto,
        "reali": df["reale"], "forecast_all": df["forecast"],
    }


def calcola_normalizzazione_climatica(prezzi, mw_f1=1.0, mw_f2=1.0, mw_f3=1.0,
                                            temperatura=None, t_base_risc=15.5,
                                            t_base_raffr=22.0, min_giorni=30):
    """Normalizzazione climatica del carico con gradi-giorno (HDD/CDD).

    Domanda operativa: "quanto del mio carico e' clima e quanto e' struttura?" —
    per confrontare due periodi (o budget vs consuntivo) bisogna togliere
    l'effetto temperatura. Si aggrega a livello GIORNALIERO e si stima con OLS:
        carico_medio_g(kW) = a + b * HDD_g + c * CDD_g
    dove HDD = somma oraria di max(0, t_base_risc - T), CDD = somma oraria di
    max(0, T - t_base_raffr). Il carico NORMALIZZATO toglie lo scostamento dal
    clima medio del periodo:
        y_norm = y - b*(HDD - HDD_medio) - c*(CDD - CDD_medio)
    cosi' la media del normalizzato coincide con la media del reale e il
    confronto tra periodi e' a parita' di clima.

    Ritorna: R^2 del fit, b/c in kW per grado-giorno, quote % di carico da
    riscaldamento / raffrescamento / base, energia reale vs normalizzata (MWh),
    tabella giornaliera, verdetto con driver dominante e nota operativa.

    NaN-safe: serie vuota / indice non-datetime / non numerica / temperatura
    mancante o senza variabilita' utile / basi invertite / parametri non validi
    -> errore pulito; tz-aware reso naive; deterministico.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        mg = int(min_giorni)
    except (TypeError, ValueError):
        return _err("min_giorni non valido")
    if mg < 10:
        return _err("min_giorni non valido (minimo 10)")
    min_giorni = mg

    for nome, mw in (("mw_f1", mw_f1), ("mw_f2", mw_f2), ("mw_f3", mw_f3)):
        try:
            v = float(mw)
        except (TypeError, ValueError):
            return _err("%s non valido" % nome)
        if not np.isfinite(v) or v < 0:
            return _err("%s non valido (deve essere >= 0)" % nome)
    mw_f1, mw_f2, mw_f3 = float(mw_f1), float(mw_f2), float(mw_f3)
    if mw_f1 + mw_f2 + mw_f3 <= 0:
        return _err("potenza nulla in tutte le fasce: carico sempre zero")

    try:
        tbr = float(t_base_risc)
        tbc = float(t_base_raffr)
    except (TypeError, ValueError):
        return _err("temperature di base non valide")
    if not (np.isfinite(tbr) and np.isfinite(tbc)):
        return _err("temperature di base non valide")
    if tbr >= tbc:
        return _err("la base riscaldamento deve essere < base raffrescamento")

    def _clean(s, nome):
        try:
            c = pd.Series(s).dropna()
        except (TypeError, ValueError):
            return None, "%s: serie non valida" % nome
        if len(c) == 0:
            return None, "%s: serie vuota" % nome
        if not isinstance(c.index, pd.DatetimeIndex):
            return None, "%s: l'indice deve essere datetime" % nome
        try:
            c = c.astype(float)
        except (TypeError, ValueError):
            return None, "%s: valori non numerici" % nome
        if c.index.tz is not None:
            c.index = c.index.tz_localize(None)
        return c.sort_index(), None

    p, em = _clean(prezzi, "prezzi")
    if em:
        return _err(em)
    if temperatura is None:
        return _err("serie temperatura mancante: carica il CSV con le temperature orarie")
    t, em = _clean(temperatura, "temperatura")
    if em:
        return _err(em)

    # carico orario kW dal profilo MW per fascia AEEGSI
    idxc = p.index
    ore = idxc.hour.to_numpy()
    wd = idxc.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    mw_ora = np.where(fasce == "F1", mw_f1, np.where(fasce == "F2", mw_f2, mw_f3))
    carico = pd.Series(mw_ora * 1000.0, index=idxc, name="carico_kw")

    df = pd.DataFrame({"carico_kw": carico, "temp": t}).dropna()
    if len(df) == 0:
        return _err("nessuna ora in comune tra prezzi e temperatura")

    df["hdd_h"] = np.maximum(0.0, tbr - df["temp"].to_numpy(dtype=float))
    df["cdd_h"] = np.maximum(0.0, df["temp"].to_numpy(dtype=float) - tbc)
    df["giorno"] = df.index.floor("D")
    gg = df.groupby("giorno").agg(
        carico_medio=("carico_kw", "mean"),
        hdd=("hdd_h", "sum"),
        cdd=("cdd_h", "sum"),
        n_ore=("carico_kw", "size"),
    )
    gg = gg[gg["n_ore"] >= 20]  # giorni con almeno 20 ore valide
    n_giorni = int(len(gg))
    if n_giorni < min_giorni:
        return _err("serie troppo corta: %d giorni completi, richiesti %d" % (n_giorni, min_giorni))

    y = gg["carico_medio"].to_numpy(dtype=float)
    hdd = gg["hdd"].to_numpy(dtype=float)
    cdd = gg["cdd"].to_numpy(dtype=float)
    y_medio = float(np.mean(y))
    if not np.isfinite(y_medio) or y_medio <= 0:
        return _err("carico medio giornaliero non positivo")

    X = np.column_stack([np.ones(n_giorni), hdd, cdd])
    if int(np.linalg.matrix_rank(X)) < 3:
        return _err("temperatura senza variabilita' utile: regressione non identificabile "
                    "(servono giorni con HDD>0 e giorni con CDD>0)")
    beta, residuals, rank, sv = np.linalg.lstsq(X, y, rcond=None)
    a, b, c = float(beta[0]), float(beta[1]), float(beta[2])
    y_hat = X @ beta
    ss_res = float(np.sum((y - y_hat) ** 2))
    ss_tot = float(np.sum((y - y_medio) ** 2))
    if ss_tot <= 0:
        r2 = 1.0 if ss_res <= 1e-12 else 0.0
    else:
        r2 = float(max(0.0, min(1.0, 1.0 - ss_res / ss_tot)))

    hdd_medio = float(np.mean(hdd))
    cdd_medio = float(np.mean(cdd))
    y_norm = y - b * (hdd - hdd_medio) - c * (cdd - cdd_medio)

    q_risc = b * hdd_medio / y_medio * 100.0
    q_raffr = c * cdd_medio / y_medio * 100.0
    q_base = 100.0 - q_risc - q_raffr
    energia_mwh = float(y_medio * 24.0 * n_giorni / 1000.0)
    energia_norm_mwh = float(np.mean(y_norm) * 24.0 * n_giorni / 1000.0)

    tabella = pd.DataFrame({
        "Data": gg.index.strftime("%Y-%m-%d"),
        "Carico medio (kW)": np.round(y, 2),
        "HDD": np.round(hdd, 1),
        "CDD": np.round(cdd, 1),
        "Carico normalizzato (kW)": np.round(y_norm, 2),
    })

    if r2 >= 0.70:
        giudizio = "forte: il clima spiega bene il carico"
    elif r2 >= 0.40:
        giudizio = "moderato: il clima spiega una parte del carico"
    else:
        giudizio = "debole: il carico dipende poco dalla temperatura"
    quote = {"riscaldamento": q_risc, "raffrescamento": q_raffr, "base": q_base}
    driver = max(quote, key=lambda k: quote[k])
    note = {
        "riscaldamento": "il carico invernale e' il driver: confronta gli inverni a parita' di HDD.",
        "raffrescamento": "il carico estivo e' il driver: confronta le estati a parita' di CDD.",
        "base": "il carico e' quasi tutto strutturale: il clima conta poco, guarda al profilo.",
    }
    verdetto = ("Legame clima-carico %s (R² = %.2f). Driver dominante: %s (%.1f %%). %s"
                % (giudizio, r2, driver, quote[driver], note[driver]))

    return {"errore": None, "valido": True, "n_giorni": n_giorni,
            "r2": r2, "base_kw": a,
            "kw_per_gg_risc": b, "kw_per_gg_raffr": c,
            "quota_risc_pct": float(q_risc), "quota_raffr_pct": float(q_raffr),
            "quota_base_pct": float(q_base),
            "carico_medio_kw": y_medio,
            "energia_mwh": energia_mwh, "energia_norm_mwh": energia_norm_mwh,
            "hdd_medio": hdd_medio, "cdd_medio": cdd_medio,
            "tabella": tabella, "verdetto": verdetto,
            "giorni": gg.index, "y": y, "y_norm": y_norm,
            "hdd": hdd, "cdd": cdd}


def calcola_enpi(prezzi, mw_f1=1.0, mw_f2=1.0, mw_f3=1.0, produzione=None,
                 baseline_mesi=3):
    """EnPI - consumo specifico di energia per unita' prodotta (stile ISO 50001).

    Domanda operativa: "quanta energia mi costa ogni pezzo che produco, e sto
    migliorando?" L'EnPI (Energy Performance Indicator) e' il KPI cardine di
    ISO 50001 e delle diagnosi energetiche: consumo specifico =
    kWh / unita' prodotta nel mese. Qui si calcola da:
      - energia mensile (MWh) e costo mensile (EUR) dal profilo orario
        MW F1/F2/F3 (via fascia_oraria, come gli altri tab di costo);
      - produzione mensile fornita dall'utente (CSV o tabella: mese, volume).

    Oltre al consumo specifico, il tab stima il MODELLO DI BASELINE con OLS:
        energia_mese = a + b * produzione_mese
    da cui: baseload fisso a (MWh/mese indipendenti dalla produzione),
    consumo marginale b (kWh per unita' aggiuntiva) e R² (quanto la
    produzione spiega davvero i consumi). La BASELINE EnPI e' la media del
    consumo specifico dei primi `baseline_mesi` mesi: il miglioramento % dei
    mesi successivi si misura contro quella.

    Differenza dagli altri tab: 'Costo per turno' e 'Margine per impianto'
    guardano al costo assoluto; qui costo e consumo sono rapportati
    all'OUTPUT produttivo, l'unico confronto sensato tra mesi con volumi
    diversi (ed e' il formato richiesto da ISO 50001 / diagnosi energetiche).
    'Normalizzazione climatica' toglie l'effetto temperatura; qui si toglie
    l'effetto volume.

    NaN-safe: prezzi con NaN/duplicati/tz gestiti come negli altri helper
    (tz reso naive, duplicati: primo tenuto); produzione None/vuota/tutta
    non positiva/meno di 2 mesi in comune col periodo prezzi -> valido False
    con errore pulito; mesi duplicati in produzione sommati; baseline_mesi
    fuori [1, n_mesi] troncato; deterministico.

    Ritorna dict con 'errore', 'valido', 'n_mesi', 'mesi' (YYYY-MM),
    'energia_mwh', 'costo_eur', 'volumi', 'kwh_unita', 'eur_unita',
    'r2' (None se <3 mesi o produzione senza varianza), 'base_mwh_mese',
    'kwh_marginale_unita', 'quota_fissa_pct', 'baseline_kwh_unita',
    'miglioramento_ultimo_pct' (None se nessun mese oltre la baseline),
    'tabella', 'verdetto'.
    """

    colonne = ["Mese", "Produzione", "Energia (MWh)", "Costo (EUR)",
               "kWh/unita'", "EUR/unita'", "Scost. vs baseline (%)"]
    vuoto = {"errore": None, "valido": False, "n_mesi": 0, "mesi": [],
             "energia_mwh": np.array([]), "costo_eur": np.array([]),
             "volumi": np.array([]), "kwh_unita": np.array([]),
             "eur_unita": np.array([]), "r2": None, "base_mwh_mese": None,
             "kwh_marginale_unita": None, "quota_fissa_pct": None,
             "baseline_kwh_unita": None, "miglioramento_ultimo_pct": None,
             "tabella": pd.DataFrame(columns=colonne), "verdetto": ""}

    def _ko(msg):
        r = dict(vuoto)
        r["errore"] = msg
        return r

    # --- prezzi: pulizia standard ---
    try:
        p = prezzi.astype(float)
        p = p[~p.index.duplicated(keep="first")].sort_index()
        if not isinstance(p.index, pd.DatetimeIndex):
            return _ko("Serie prezzi non valida: serve un indice datetime orario.")
    except Exception:
        return _ko("Serie prezzi non valida: serve un indice datetime orario.")
    if getattr(p.index, "tz", None) is not None:
        p.index = p.index.tz_localize(None)
    p = p.dropna()
    if len(p) == 0:
        return _ko("Serie prezzi vuota.")
    try:
        mw = {"F1": float(mw_f1), "F2": float(mw_f2), "F3": float(mw_f3)}
    except Exception:
        return _ko("MW di fascia non validi.")
    if any(v < 0 for v in mw.values()) or sum(mw.values()) == 0:
        return _ko("Profilo MW nullo o negativo.")

    fasce = p.index.map(fascia_oraria)
    ore = pd.DataFrame({"mw": [mw.get(fx, 0.0) for fx in fasce],
                        "prezzo": p.to_numpy(dtype=float)}, index=p.index)
    ore["costo"] = ore["prezzo"] * ore["mw"]
    # groupby su Period M: compatibile pandas 2.1 (locale) e 2.2 (produzione)
    mens = ore.groupby(ore.index.to_period("M")).agg(
        energia_mwh=("mw", "sum"), costo_eur=("costo", "sum"))

    # --- produzione: normalizza a Series indicizzata per Period M ---
    if produzione is None:
        return _ko("Produzione mancante: carica il CSV (mese, volume) o compila la tabella.")
    try:
        if isinstance(produzione, pd.DataFrame):
            dfp = produzione.copy()
            mesi_p = pd.to_datetime(dfp.iloc[:, 0], errors="coerce").dt.to_period("M")
            vol_p = pd.to_numeric(dfp.iloc[:, 1], errors="coerce")
            prod = pd.Series(vol_p.to_numpy(dtype=float), index=mesi_p)
        elif isinstance(produzione, pd.Series):
            idx = produzione.index
            if isinstance(idx, pd.PeriodIndex):
                per = idx.asfreq("M")
            else:
                per = pd.DatetimeIndex(pd.to_datetime(idx, errors="coerce")).to_period("M")
            prod = pd.Series(pd.to_numeric(produzione, errors="coerce").to_numpy(dtype=float),
                             index=per)
        elif isinstance(produzione, dict):
            per = pd.DatetimeIndex(
                pd.to_datetime(list(produzione.keys()), errors="coerce")).to_period("M")
            prod = pd.Series(
                np.asarray(pd.to_numeric(list(produzione.values()), errors="coerce"),
                           dtype=float),
                index=per)
        else:
            return _ko("Formato produzione non riconosciuto (serve Series, DataFrame o dict).")
    except Exception:
        return _ko("Produzione non leggibile: servono mese e volume numerico.")
    prod = prod[prod.index.notna() & prod.notna()]
    prod = prod[prod > 0]
    if len(prod) == 0:
        return _ko("Nessun mese con produzione positiva.")
    prod = prod.groupby(prod.index).sum()  # mesi duplicati: volumi sommati

    comuni = mens.index.intersection(prod.index).sort_values()
    if len(comuni) < 2:
        return _ko("Servono almeno 2 mesi con prezzi e produzione in comune.")
    energia = mens.loc[comuni, "energia_mwh"].to_numpy(dtype=float)
    costo = mens.loc[comuni, "costo_eur"].to_numpy(dtype=float)
    vol = prod.loc[comuni].to_numpy(dtype=float)
    n = len(comuni)

    kwh_u = energia * 1000.0 / vol
    eur_u = costo / vol

    # --- modello OLS energia = a + b * produzione ---
    r2 = None
    a = None
    b = None
    quota_fissa = None
    if n >= 3 and float(np.var(vol)) > 0 and float(np.var(energia)) > 0:
        b, a = np.polyfit(vol, energia, 1)  # energia = a + b * vol
        yhat = a + b * vol
        ss_res = float(np.sum((energia - yhat) ** 2))
        ss_tot = float(np.sum((energia - energia.mean()) ** 2))
        r2 = float(1.0 - ss_res / ss_tot) if ss_tot > 0 else None
        e_media = float(energia.mean())
        quota_fissa = float(np.clip(a / e_media * 100.0, 0.0, 100.0)) if e_media > 0 else 0.0

    # --- baseline e miglioramento ---
    try:
        nb = int(baseline_mesi)
    except Exception:
        nb = 3
    nb = max(1, min(nb, n))
    baseline = float(np.mean(kwh_u[:nb]))
    scost_full = np.full(n, np.nan)
    if baseline > 0 and n > nb:
        scost_full[nb:] = (baseline - kwh_u[nb:]) / baseline * 100.0
    migl_ult = float(scost_full[-1]) if n > nb and np.isfinite(scost_full[-1]) else None

    # --- verdetto ---
    if r2 is None:
        giudizio_mod = "modello non stimabile (servono 3+ mesi con volumi diversi)"
        nota_base = ""
    elif r2 >= 0.70:
        giudizio_mod = "modello affidabile (R^2 = %.2f)" % r2
        nota_base = ("Baseload fisso stimato {:,.0f} MWh/mese ({:.0f}% del consumo medio): "
                     "questa quota non dipende dai volumi.".format(a, quota_fissa))
    elif r2 >= 0.40:
        giudizio_mod = "modello debole (R^2 = %.2f): la produzione spiega solo in parte i consumi" % r2
        nota_base = ""
    else:
        giudizio_mod = ("produzione poco legata ai consumi (R^2 = %.2f): EnPI instabile, "
                        "il driver e' altrove (clima? turni?)" % r2)
        nota_base = ""
    if migl_ult is None:
        nota_migl = "nessun mese oltre la baseline per il confronto."
    elif migl_ult >= 5:
        nota_migl = "ultimo mese %+.1f%% vs baseline: in miglioramento." % migl_ult
    elif migl_ult <= -5:
        nota_migl = "ultimo mese %.1f%% vs baseline: in peggioramento, verificare." % migl_ult
    else:
        nota_migl = "ultimo mese %+.1f%% vs baseline: stabile." % migl_ult
    verdetto = ("EnPI medio %.1f kWh/unita' (%.2f EUR/unita'). %s. %s %s"
                % (float(np.mean(kwh_u)), float(np.mean(eur_u)),
                   giudizio_mod, nota_base, nota_migl)).replace("  ", " ").strip()

    tabella = pd.DataFrame({
        "Mese": [str(m) for m in comuni],
        "Produzione": np.round(vol, 1),
        "Energia (MWh)": np.round(energia, 1),
        "Costo (EUR)": np.round(costo, 0),
        "kWh/unita'": np.round(kwh_u, 1),
        "EUR/unita'": np.round(eur_u, 2),
        "Scost. vs baseline (%)": np.round(scost_full, 1),
    })

    return {"errore": None, "valido": True, "n_mesi": n,
            "mesi": [str(m) for m in comuni],
            "energia_mwh": energia, "costo_eur": costo, "volumi": vol,
            "kwh_unita": kwh_u, "eur_unita": eur_u,
            "r2": r2, "base_mwh_mese": None if a is None else float(a),
            "kwh_marginale_unita": None if b is None else float(b * 1000.0),
            "quota_fissa_pct": quota_fissa,
            "baseline_kwh_unita": baseline,
            "miglioramento_ultimo_pct": migl_ult,
            "tabella": tabella, "verdetto": verdetto}


def calcola_impronta_co2(prezzi, mw_f1=1.0, mw_f2=1.0, mw_f3=1.0,
                         fattore_kg_mwh=380.0, eua_eur_t=75.0):
    """Impronta CO2 (Scope 2) dei consumi del profilo di prelievo.

    Domanda operativa: "quante tonnellate di CO2 generano i miei consumi e quanto
    valgono a prezzo EUA?" — il numero che serve per il reporting GHG/CSRD e per
    valorizzare gli investimenti di efficienza in tonnellate evitate (tab
    "Payback efficienza").

    Metodo: energia oraria (MWh) dal profilo MW F1/F2/F3 (via _fascia_aeegsi, come
    gli altri tab di costo) x fattore di emissione (kg CO2/MWh, editabile: il
    default 380 e' un mix residuo italiano indicativo — per il reporting
    ufficiale usare il fattore del proprio fornitore o del mix residuo
    nazionale). Il COSTO VALORIZZATO = tCO2 x prezzo EUA (EUR/t): il "prezzo
    ombra" interno per valutare efficienza e flessibilita'.

    Differenza dal tab "Costo CO2": quello scompone il PREZZO spot nella
    componente CO2 (pass-through dell'EUA sul marginale fossile); qui si misura
    l'impronta dei CONSUMI (tonnellate + costo valorizzato), lato domanda.

    Ritorna dict con 'errore', 'valido', 'n_mesi', 'mesi' (str), 'energia_mwh',
    'costo_energia_eur', 'tco2', 'costo_co2_eur', 'quota_co2_costo_pct' (liste per
    mese), 'tot_energia_mwh', 'tot_costo_energia_eur', 'tot_tco2',
    'tot_costo_co2_eur', 'quota_media_pct' (sul costo energia totale; None se
    costo <= 0), 'tco2_fascia' (dict F1/F2/F3), 'fascia_top', 'mese_max',
    'tabella' (DataFrame), 'verdetto' (str).

    NaN-safe: serie vuota / indice non datetime / non numerica / parametri non
    validi / energia <= 0 -> {'valido': False, 'errore': ...}, mai eccezioni.
    Indice tz-aware reso naive. Deterministico.
    """

    vuoto = {"errore": None, "valido": False, "n_mesi": 0, "mesi": [],
             "energia_mwh": [], "costo_energia_eur": [], "tco2": [],
             "costo_co2_eur": [], "quota_co2_costo_pct": [],
             "tot_energia_mwh": 0.0, "tot_costo_energia_eur": 0.0,
             "tot_tco2": 0.0, "tot_costo_co2_eur": 0.0, "quota_media_pct": None,
             "tco2_fascia": {"F1": 0.0, "F2": 0.0, "F3": 0.0}, "fascia_top": None,
             "mese_max": None, "tabella": pd.DataFrame(), "verdetto": ""}

    def _ko(msg):
        r = dict(vuoto)
        r["errore"] = msg
        return r

    try:
        p = prezzi.astype(float)
    except Exception:
        return _ko("Serie prezzi non numerica.")
    try:
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _ko("Indice della serie prezzi non valido.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _ko("La serie prezzi deve avere un indice datetime.")
    if p.index.tz is not None:
        p = p.tz_localize(None)
    p = p.dropna()
    if len(p) == 0:
        return _ko("Serie prezzi vuota.")
    try:
        mw = {"F1": float(mw_f1), "F2": float(mw_f2), "F3": float(mw_f3)}
        fattore = float(fattore_kg_mwh)
        eua = float(eua_eur_t)
    except Exception:
        return _ko("Parametri non numerici (MW, fattore di emissione o prezzo EUA).")
    if any(v < 0 for v in mw.values()):
        return _ko("I MW per fascia devono essere >= 0.")
    if fattore < 0:
        return _ko("Il fattore di emissione deve essere >= 0.")
    if eua < 0:
        return _ko("Il prezzo EUA deve essere >= 0.")

    fasce = [_fascia_aeegsi(int(h), int(wd))
             for h, wd in zip(p.index.hour, p.index.weekday)]
    energia_h = np.array([mw[f] for f in fasce], dtype=float)  # 1h x MW = MWh
    tco2_h = energia_h * fattore / 1000.0
    costo_h = energia_h * p.to_numpy(dtype=float)

    tot_energia = float(energia_h.sum())
    if tot_energia <= 0.0:
        return _ko("Energia nulla: imposta MW > 0 in almeno una fascia.")

    df_h = pd.DataFrame({"energia": energia_h, "costo": costo_h, "tco2": tco2_h},
                        index=p.index.to_period("M"))
    g = df_h.groupby(level=0)
    mesi = [str(m) for m in g.size().index]
    energia = g["energia"].sum().to_numpy(dtype=float)
    costo_e = g["costo"].sum().to_numpy(dtype=float)
    tco2 = g["tco2"].sum().to_numpy(dtype=float)
    costo_co2 = tco2 * eua
    quota = np.where(costo_e > 0, costo_co2 / costo_e * 100.0, np.nan)

    fasce_arr = np.array(fasce)
    t_fascia = {f: float(tco2_h[fasce_arr == f].sum()) for f in ("F1", "F2", "F3")}
    fascia_top = max(t_fascia, key=t_fascia.get)
    mese_max = mesi[int(np.argmax(tco2))]
    tot_tco2 = float(tco2.sum())
    tot_costo_e = float(costo_e.sum())
    tot_costo_co2 = float(costo_co2.sum())
    quota_media = (tot_costo_co2 / tot_costo_e * 100.0) if tot_costo_e > 0 else None

    tabella = pd.DataFrame({
        "Mese": mesi,
        "Energia (MWh)": np.round(energia, 2),
        "Costo energia (EUR)": np.round(costo_e, 2),
        "tCO2": np.round(tco2, 2),
        "Costo CO2 valorizzato (EUR)": np.round(costo_co2, 2),
        "Quota CO2 su costo (%)": np.round(quota, 2),
    })

    verdetto = (
        f"Impronta totale {tot_tco2:,.1f} tCO2 su {tot_energia:,.0f} MWh "
        f"({len(mesi)} mesi). Il costo valorizzato a {eua:,.0f} EUR/t EUA vale "
        f"{tot_costo_co2:,.0f} EUR"
        + (f" ({quota_media:.1f}% del costo energia)" if quota_media is not None else "")
        + f". La fascia {fascia_top} pesa di piu' ({t_fascia[fascia_top]:,.1f} tCO2): "
        "spostare consumi fuori dalle fasce care riduce sia il costo energia che "
        "l'impronta (tab Shifting carico). Il mese piu' emissivo e' " + mese_max + "."
    )
    return {"errore": None, "valido": True, "n_mesi": len(mesi), "mesi": mesi,
            "energia_mwh": [float(x) for x in energia],
            "costo_energia_eur": [float(x) for x in costo_e],
            "tco2": [float(x) for x in tco2],
            "costo_co2_eur": [float(x) for x in costo_co2],
            "quota_co2_costo_pct": [None if np.isnan(x) else float(x)
                                    for x in quota],
            "tot_energia_mwh": tot_energia,
            "tot_costo_energia_eur": tot_costo_e,
            "tot_tco2": tot_tco2, "tot_costo_co2_eur": tot_costo_co2,
            "quota_media_pct": quota_media,
            "tco2_fascia": t_fascia, "fascia_top": fascia_top,
            "mese_max": mese_max, "tabella": tabella, "verdetto": verdetto}


def calcola_rischio_orario(prezzi, mw_f1=1.0, mw_f2=1.0, mw_f3=1.0, min_giorni=30):
    """Scomposizione del rischio del costo giornaliero per ora del giorno.

    Domanda operativa: "quali ore guidano la volatilita' del mio costo
    giornaliero?" — un'ora puo' costare poco in media ma essere molto
    volatile (es. la punta serale). La scomposizione di Eulero attribuisce
    a ciascuna ora la sua quota della VARIANZA del costo giornaliero:
        contributo_h = cov(costo_h, costo_giornaliero) / var(costo_giornaliero)
    e la somma dei 24 contributi fa esattamente il 100%.

    La "leva di rischio" = contributo / quota di costo: sopra 1 l'ora pesa
    sul rischio piu' di quanto pesi sul costo — sono le ore dove coperture
    mirate, cap o spostamento del carico rendono di piu'.

    Il costo orario e' prezzo x MW della fascia AEEGSI di quell'ora (via
    _fascia_aeegsi). Giorni con < 20 ore valide scartati (bordi periodo);
    ore ambigue del cambio DST sommate.

    NaN-safe: serie vuota / indice non-datetime / troppo corta / MW non
    validi / costo giornaliero (quasi) costante -> errore pulito; tz-aware
    reso naive; deterministico.
    """
    def _err(msg):
        return {"errore": msg, "valido": False, "n_giorni": 0,
                "giorni_richiesti": min_giorni}

    try:
        mg = int(min_giorni)
    except (TypeError, ValueError):
        return _err("min_giorni non valido")
    if mg < 10:
        return _err("min_giorni non valido (minimo 10)")
    min_giorni = mg

    for nome, mw in (("mw_f1", mw_f1), ("mw_f2", mw_f2), ("mw_f3", mw_f3)):
        try:
            v = float(mw)
        except (TypeError, ValueError):
            return _err("%s non valido" % nome)
        if not np.isfinite(v) or v < 0:
            return _err("%s non valido (deve essere >= 0)" % nome)
    mw_f1, mw_f2, mw_f3 = float(mw_f1), float(mw_f2), float(mw_f3)
    if mw_f1 + mw_f2 + mw_f3 <= 0:
        return _err("potenza nulla in tutte le fasce: costo sempre zero")

    if prezzi is None or len(prezzi) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("indice non datetime")
    idxn = prezzi.index.tz_localize(None) if prezzi.index.tz is not None else prezzi.index
    p = pd.to_numeric(prezzi, errors="coerce")
    p.index = idxn
    p = p.dropna()
    if len(p) == 0:
        return _err("serie prezzi vuota dopo pulizia NaN")

    # ora/weekday allineati a p (dopo dropna)
    idxc = p.index
    ore = idxc.hour.to_numpy()
    wd = idxc.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    mw_ora = np.where(fasce == "F1", mw_f1, np.where(fasce == "F2", mw_f2, mw_f3))
    costo = pd.Series(p.to_numpy(dtype=float) * mw_ora, index=idxc, name="costo")

    df = pd.DataFrame({"giorno": idxc.floor("D"), "ora": ore, "costo": costo.to_numpy()})
    mat = df.groupby(["giorno", "ora"])["costo"].sum().unstack("ora")
    mat = mat.reindex(columns=range(24))
    mat = mat.dropna(thresh=20)  # giorni con almeno 20 ore valide
    n_giorni = int(len(mat))
    if n_giorni < min_giorni:
        return _err("serie troppo corta: %d giorni, richiesti %d" % (n_giorni, min_giorni))

    tot = mat.sum(axis=1)
    var_tot = float(tot.var(ddof=1))
    if not np.isfinite(var_tot) or var_tot <= 0:
        return _err("costo giornaliero (quasi) costante: nessun rischio da scomporre")

    covs = np.array([float(mat[h].cov(tot)) if mat[h].notna().any() else 0.0
                     for h in range(24)])
    covs = np.nan_to_num(covs, nan=0.0)
    contrib = covs / var_tot * 100.0

    medie = mat.mean(axis=0).to_numpy(dtype=float)
    medie = np.nan_to_num(medie, nan=0.0)
    somma_medie = float(medie.sum())
    quota = medie / somma_medie * 100.0 if somma_medie > 0 else np.zeros(24)
    vol_ora = mat.std(ddof=1).to_numpy(dtype=float)
    vol_ora = np.nan_to_num(vol_ora, nan=0.0)
    with np.errstate(divide="ignore", invalid="ignore"):
        leva = np.where(quota > 1e-9, contrib / np.maximum(quota, 1e-9), 0.0)
    leva = np.clip(np.nan_to_num(leva, nan=0.0, posinf=999.0, neginf=-99.0), -99.0, 999.0)

    tabella = pd.DataFrame({
        "Ora": ["%02d:00" % h for h in range(24)],
        "Costo medio (€/g)": np.round(medie, 2),
        "Quota costo (%)": np.round(quota, 2),
        "Volatilità (€/g)": np.round(vol_ora, 2),
        "Contributo rischio (%)": np.round(contrib, 2),
        "Leva rischio (x)": np.round(leva, 2),
    })

    ordine = np.argsort(-contrib, kind="stable")
    ora_top = int(ordine[0])
    contrib_top = float(contrib[ora_top])
    top3 = [int(h) for h in ordine[:3]]
    top3_conc = float(contrib[top3].sum())
    vol_giornaliera = float(tot.std(ddof=1))
    costo_medio_giorno = float(tot.mean())
    leva_top = float(leva[ora_top])

    if leva_top > 1.5:
        nota_leva = ("leva di rischio %.1fx: l'ora pesa sul rischio molto piu' "
                     "che sul costo — candidata ideale per coperture mirate o "
                     "spostamento del carico." % leva_top)
    elif leva_top > 1.0:
        nota_leva = ("leva di rischio %.1fx: l'ora pesa sul rischio piu' che "
                     "sul costo." % leva_top)
    else:
        nota_leva = ("leva di rischio %.1fx: l'ora e' costosa ma relativamente "
                     "prevedibile." % leva_top)
    verdetto = ("L'ora %02d:00 spiega il %.1f%% della varianza del costo "
                "giornaliero (%s). Le 3 ore piu' rischiose (%s) concentrano il "
                "%.1f%% del rischio: e' li' che si gioca la volatilita' del "
                "conto energia." % (ora_top, contrib_top, nota_leva,
                                    ", ".join("%02d:00" % h for h in top3),
                                    top3_conc))

    return {"errore": None, "valido": True, "n_giorni": n_giorni,
            "giorni_richiesti": min_giorni, "tabella": tabella,
            "ora_top": ora_top, "contrib_top": contrib_top,
            "top3_ore": top3, "top3_conc": top3_conc,
            "vol_giornaliera": vol_giornaliera,
            "costo_medio_giorno": costo_medio_giorno,
            "verdetto": verdetto}



def calcola_event_study(prezzi, data_evento, finestra_gg=30, min_giorni=5):
    """Event study: l'evento ha spostato il prezzo spot?

    Domanda operativa: "dopo l'evento X (nuova policy, fermo di una centrale,
    ondata di freddo, cambio di regole di mercato...) il prezzo e' cambiato in
    modo significativo?" Si lavora sulle MEDIE GIORNALIERE del prezzo orario:
    finestra pre = [evento - finestra_gg, evento), finestra post =
    [evento, evento + finestra_gg). Test t di Welch sulla differenza delle
    medie giornaliere; p-value con approssimazione normale (scipy.stats.norm,
    gia' dipendenza del progetto).

    NaN-safe: serie vuota / indice non-datetime / data evento non valida o
    fuori range / finestre con < min_giorni giorni / parametri non validi ->
    errore pulito; tz-aware reso naive; deterministico.
    """
    def _err(msg):
        return {"errore": msg, "valido": False, "n_pre": 0, "n_post": 0}

    try:
        fg = int(finestra_gg)
    except (TypeError, ValueError):
        return _err("finestra_gg non valida")
    if fg < 5 or fg > 365:
        return _err("finestra_gg non valida (5-365 giorni)")
    try:
        mg = int(min_giorni)
    except (TypeError, ValueError):
        return _err("min_giorni non valido")
    if mg < 2 or mg > fg:
        return _err("min_giorni non valido (2 <= min_giorni <= finestra_gg)")

    try:
        ev = pd.Timestamp(data_evento)
    except (TypeError, ValueError):
        return _err("data_evento non valida")
    if pd.isna(ev):
        return _err("data_evento non valida")
    if ev.tz is not None:
        ev = ev.tz_localize(None)
    ev = ev.normalize()

    if prezzi is None or len(prezzi) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("indice non datetime")
    idxn = prezzi.index.tz_localize(None) if prezzi.index.tz is not None else prezzi.index
    p = pd.to_numeric(prezzi, errors="coerce")
    p.index = idxn
    p = p[~p.index.duplicated(keep="first")].sort_index().dropna()
    if len(p) == 0:
        return _err("serie prezzi vuota dopo pulizia NaN")

    g = p.resample("D").mean().dropna()
    if len(g) == 0:
        return _err("nessun giorno con prezzo medio valido")
    d0 = g.index.min().normalize()
    d1 = g.index.max().normalize()
    if ev < d0 or ev > d1:
        return _err("data_evento fuori dal periodo dei dati (%s - %s)"
                    % (d0.date(), d1.date()))

    pre = g[(g.index >= ev - pd.Timedelta(days=fg)) & (g.index < ev)]
    post = g[(g.index >= ev) & (g.index < ev + pd.Timedelta(days=fg))]
    n_pre, n_post = int(len(pre)), int(len(post))
    if n_pre < mg or n_post < mg:
        return _err("finestre troppo corte: %d/%d giorni, richiesti %d"
                    % (n_pre, n_post, mg))

    m_pre, m_post = float(pre.mean()), float(post.mean())
    s_pre = float(pre.std(ddof=1)) if n_pre > 1 else 0.0
    s_post = float(post.std(ddof=1)) if n_post > 1 else 0.0
    delta = m_post - m_pre
    delta_pct = delta / abs(m_pre) * 100.0 if m_pre != 0 else None

    den = s_pre ** 2 / n_pre + s_post ** 2 / n_post
    if not np.isfinite(den) or den <= 0:
        t_stat = 0.0 if delta == 0 else (float("inf") if delta > 0 else float("-inf"))
    else:
        t_stat = delta / np.sqrt(den)
    p_value = 0.0 if np.isinf(t_stat) else float(2.0 * norm.sf(abs(float(t_stat))))
    p_value = float(min(max(p_value, 0.0), 1.0))
    significativo = bool(p_value < 0.05)
    direzione = "rialzo" if delta > 0 else ("ribasso" if delta < 0 else "invariato")

    giorni = pd.concat([pre, post])
    vals = giorni.to_numpy(dtype=float)
    tabella = pd.DataFrame({
        "Giorno": giorni.index.strftime("%Y-%m-%d"),
        "Periodo": ["Pre" if d < ev else "Post" for d in giorni.index],
        "Prezzo medio (EUR/MWh)": np.round(vals, 2),
        "Scostamento da media pre (EUR/MWh)": np.round(vals - m_pre, 2),
    })

    if significativo:
        giudizio = "variazione STATISTICAMENTE SIGNIFICATIVA (p=%.3g < 0.05)" % p_value
    else:
        giudizio = "variazione NON statisticamente significativa (p=%.3g >= 0.05)" % p_value
    verdetto = (
        "Dopo l'evento del %s il prezzo medio giornaliero e' passato da %.2f a "
        "%.2f EUR/MWh (%s%.2f, %s): %s. Direzione: %s. Nota: significativita' "
        "statistica non implica causalita' — l'evento puo' coincidere con altri "
        "driver (meteo, stagionalita', manutenzioni)." %
        (ev.date(), m_pre, m_post, "+" if delta >= 0 else "", delta,
         ("%.1f%%" % delta_pct) if delta_pct is not None else "n/d",
         giudizio, direzione.upper()))

    return {"errore": None, "valido": True,
            "data_evento": ev.date().isoformat(), "finestra_gg": fg,
            "n_pre": n_pre, "n_post": n_post,
            "media_pre": m_pre, "media_post": m_post,
            "std_pre": s_pre, "std_post": s_post,
            "delta": delta, "delta_pct": delta_pct,
            "t_stat": t_stat, "p_value": p_value,
            "significativo": significativo, "direzione": direzione,
            "tabella": tabella, "verdetto": verdetto}


def calcola_business_case_rinnovabile(prezzi, tecnologia="fv", potenza_mw=10.0,
                                             ore_equivalenti=1100.0, degrado_pct=0.5,
                                             capex_eur_kw=900.0, opex_eur_kw_anno=15.0,
                                             tasso_pct=6.0, vita_anni=25):
    """Business case di un impianto rinnovabile merchant (fotovoltaico / eolico).

    Domanda operativa: "se costruisco X MW che vendono a spot, il progetto
    si ripaga?" Si genera un profilo di produzione orario DETERMINISTICO
    (FV: campana diurna con durata del giorno e irraggiamento stagionali;
    eolico: profilo mensile invernale + lieve modulazione diurna), normalizzato
    in modo che l'energia annua sia esattamente potenza_mw x ore_equivalenti.
    Il PREZZO CATTURATO (ricavo/energia sulla finestra dei prezzi) e' applicato
    all'energia annua per il ricavo annuo; poi NPV, IRR (bisezione), payback semplice e
    attualizzato, prezzo catturato e sconto di cattura vs prezzo medio,
    sensibilita' a CAPEX e prezzo.

    NaN-safe: serie vuota / indice non-datetime / < 168 ore valide /
    parametri non validi -> errore pulito; tz-aware reso naive; duplicati
    keep-first; deterministico (nessun seed, profili analitici).
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    if tecnologia not in ("fv", "eolico"):
        return _err("tecnologia non valida (usare 'fv' o 'eolico')")
    try:
        pot = float(potenza_mw)
        ore_eq = float(ore_equivalenti)
        deg = float(degrado_pct)
        capex_kw = float(capex_eur_kw)
        opex_kw = float(opex_eur_kw_anno)
        tasso = float(tasso_pct)
        vita = int(vita_anni)
    except (TypeError, ValueError):
        return _err("parametri numerici non validi")
    if not (0.0 < pot <= 10000.0):
        return _err("potenza_mw non valida (0 < P <= 10000 MW)")
    if not (0.0 < ore_eq <= 8760.0):
        return _err("ore_equivalenti non valide (0 < h <= 8760)")
    if not (0.0 <= deg <= 20.0):
        return _err("degrado_pct non valido (0-20 %/anno)")
    if capex_kw < 0.0:
        return _err("capex_eur_kw non puo' essere negativo")
    if opex_kw < 0.0:
        return _err("opex_eur_kw_anno non puo' essere negativo")
    if not (0.0 <= tasso <= 100.0):
        return _err("tasso_pct non valido (0-100 %)")
    if not (1 <= vita <= 50):
        return _err("vita_anni non valida (1-50 anni)")
    if float(vita_anni) != float(vita):
        return _err("vita_anni deve essere un numero intero di anni")

    if prezzi is None or len(prezzi) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("indice non datetime")
    idxn = prezzi.index.tz_localize(None) if prezzi.index.tz is not None else prezzi.index
    p = pd.to_numeric(prezzi, errors="coerce")
    p.index = idxn
    p = p[~p.index.duplicated(keep="first")].sort_index().dropna()
    if len(p) < 168:
        return _err("servono almeno 168 ore valide di prezzi (una settimana)")

    def _shape(m, hh):
        m = np.asarray(m, dtype=float)
        hh = np.asarray(hh, dtype=float)
        if tecnologia == "fv":
            dl = 12.0 + 3.6 * np.sin(2.0 * np.pi * (m - 3.5) / 12.0)
            sr = 12.0 - dl / 2.0
            x = (hh + 0.5 - sr) / dl
            dentro = (x > 0.0) & (x < 1.0)
            bell = np.where(dentro, np.sin(np.pi * np.clip(x, 0.0, 1.0)), 0.0)
            irr = 0.60 + 0.40 * np.sin(2.0 * np.pi * (m - 4.5) / 12.0)
            return bell * irr
        w = 1.0 + 0.28 * np.cos(2.0 * np.pi * (m - 1.0) / 12.0)
        return w * (1.0 + 0.10 * np.sin(2.0 * np.pi * (hh - 14.0) / 24.0))

    giorni_mese = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    somma_anno = 0.0
    for mi, gm in enumerate(giorni_mese, start=1):
        hhg = np.arange(24.0)
        somma_anno += float(gm * _shape(np.full(24, mi), hhg).sum())
    if not np.isfinite(somma_anno) or somma_anno <= 0.0:
        return _err("profilo di generazione degenere")
    k = pot * ore_eq / somma_anno

    m_arr = p.index.month.to_numpy()
    hh_arr = p.index.hour.to_numpy()
    energia = _shape(m_arr, hh_arr) * k
    n_ore = int(len(p))
    energia_tot = float(energia.sum())
    ricavo = float((energia * p.to_numpy(dtype=float)).sum())
    if energia_tot <= 0.0:
        return _err("energia prodotta nulla sul periodo")
    prezzo_catturato = ricavo / energia_tot
    prezzo_medio = float(p.mean())
    sconto = ((prezzo_medio - prezzo_catturato) / prezzo_medio * 100.0
              if prezzo_medio > 0 else None)

    # Energia annua esatta per definizione (P x ore equivalenti); il ricavo
    # annuo usa il PREZZO CATTURATO stimato sulla finestra dei prezzi.
    energia_annua = pot * ore_eq
    ricavo_annuo = energia_annua * prezzo_catturato
    opex_annuo = pot * 1000.0 * opex_kw
    capex_tot = pot * 1000.0 * capex_kw

    anni = np.arange(1, vita + 1)
    deg_f = (1.0 - deg / 100.0) ** (anni - 1)
    cf = ricavo_annuo * deg_f - opex_annuo
    r_disc = tasso / 100.0
    df_att = 1.0 / (1.0 + r_disc) ** anni
    cf_att = cf * df_att
    npv = -capex_tot + float(cf_att.sum())

    def _npv_rate(rr):
        return -capex_tot + float(np.sum(cf / (1.0 + rr) ** anni))

    irr = None
    irr_oltre = False
    if np.all(cf <= 0.0):
        irr = None
    else:
        lo, hi = -0.999, 5.0
        n_lo, n_hi = _npv_rate(lo), _npv_rate(hi)
        if n_lo <= 0.0:
            irr = None
        elif n_hi > 0.0:
            irr_oltre = True
        else:
            for _ in range(200):
                mid = (lo + hi) / 2.0
                if _npv_rate(mid) > 0.0:
                    lo = mid
                else:
                    hi = mid
            irr = (lo + hi) / 2.0

    def _payback(flussi):
        cum = np.cumsum(flussi)
        idx = np.where(cum >= capex_tot)[0]
        if len(idx) == 0:
            return None
        t = int(idx[0])
        prev = float(cum[t - 1]) if t > 0 else 0.0
        fraz = (capex_tot - prev) / float(flussi[t]) if flussi[t] > 0 else 0.0
        return round(t + fraz, 2)

    payback = _payback(cf)
    payback_att = _payback(cf_att)

    fattori_capex = [0.70, 0.85, 1.0, 1.15, 1.30]
    sens_capex = pd.DataFrame({
        "Variazione CAPEX": ["-30%", "-15%", "base", "+15%", "+30%"],
        "CAPEX (kEUR)": [round(capex_tot * f / 1000.0, 1) for f in fattori_capex],
        "NPV (kEUR)": [round((npv + capex_tot * (1.0 - f)) / 1000.0, 1)
                       for f in fattori_capex],
    })
    fattori_prezzo = [0.80, 0.90, 1.0, 1.10, 1.20]
    sens_prezzo = pd.DataFrame({
        "Variazione prezzo": ["-20%", "-10%", "base", "+10%", "+20%"],
        "Prezzo catturato (EUR/MWh)": [round(prezzo_catturato * f, 2)
                                       for f in fattori_prezzo],
        "NPV (kEUR)": [round((npv + (f - 1.0) * float(np.sum(
            ricavo_annuo * deg_f * df_att))) / 1000.0, 1)
                       for f in fattori_prezzo],
    })

    cum_att = np.cumsum(cf_att) - capex_tot
    tabella = pd.DataFrame({
        "Anno": anni,
        "Energia (MWh)": np.round(energia_annua * deg_f, 1),
        "Ricavo (kEUR)": np.round(ricavo_annuo * deg_f / 1000.0, 1),
        "OPEX (kEUR)": np.round(np.full(vita, opex_annuo) / 1000.0, 1),
        "Cash flow (kEUR)": np.round(cf / 1000.0, 1),
        "CF attualizzato (kEUR)": np.round(cf_att / 1000.0, 1),
        "Cumulato att. (kEUR)": np.round(cum_att / 1000.0, 1),
    })

    nome_tec = "fotovoltaico" if tecnologia == "fv" else "eolico"
    if npv > 0:
        giudizio = "NPV POSITIVO: il progetto crea valore al tasso del %.1f%%" % tasso
    elif npv == 0:
        giudizio = "NPV nullo: il progetto rende esattamente il tasso del %.1f%%" % tasso
    else:
        giudizio = "NPV NEGATIVO: il progetto distrugge valore al tasso del %.1f%%" % tasso
    if irr is None:
        nota_irr = ("IRR non calcolabile (flussi mai positivi)" if not irr_oltre
                    else "IRR oltre il 500%")
    else:
        nota_irr = "IRR %.1f%% %s il tasso di sconto (%.1f%%)" % (
            irr * 100.0, "sopra" if irr * 100.0 > tasso else "sotto o pari a", tasso)
    nota_pb = ("payback semplice %s anni, attualizzato %s anni" % (
        ("%.1f" % payback) if payback is not None else "mai entro la vita utile",
        ("%.1f" % payback_att) if payback_att is not None else "mai entro la vita utile"))
    nota_prezzo = ("prezzo catturato %.2f EUR/MWh contro media di mercato %.2f "
                   "EUR/MWh (sconto di cattura %s)" % (
                       prezzo_catturato, prezzo_medio,
                       ("%.1f%%" % sconto) if sconto is not None else "n/d"))
    verdetto = (
        "Impianto %s da %.1f MW (%d ore equivalenti/anno, %.1f GWh/anno): %s. "
        "%s; %s. %s. Nota: prezzi del periodo ipotizzati ripetuti ogni anno, "
        "degrado %.1f%%/anno sull'energia, OPEX costante, nessun curtailment "
        "e nessuna valorizzazione di GO/certificati." % (
            nome_tec, pot, int(round(ore_eq)), energia_annua / 1000.0,
            giudizio, nota_irr, nota_pb, nota_prezzo, deg))

    return {"errore": None, "valido": True,
            "tecnologia": tecnologia, "potenza_mw": pot,
            "ore_equivalenti": ore_eq, "n_ore": n_ore,
            "energia_annua_mwh": energia_annua,
            "ricavo_annuo_eur": ricavo_annuo,
            "prezzo_catturato": prezzo_catturato,
            "prezzo_medio": prezzo_medio,
            "sconto_cattura_pct": sconto,
            "capex_eur": capex_tot, "opex_annuo_eur": opex_annuo,
            "npv_eur": npv, "irr": irr, "irr_oltre_500": irr_oltre,
            "payback_anni": payback, "payback_att_anni": payback_att,
            "tabella": tabella, "sens_capex": sens_capex,
            "sens_prezzo": sens_prezzo, "verdetto": verdetto}


def calcola_rischio_volume(prezzi, carico_base_mw=5.0, forma_carico="diurno",
                           quota_coperta_pct=70.0, prezzo_coperto_eur_mwh=100.0,
                           variazione_carico_pct=10.0):
    """Rischio volume di un portafoglio di carico con quota coperta a prezzo fisso.

    Domanda operativa: "se il carico reale si discosta da quello atteso,
    quanto varia il costo di fornitura?" Si modella un profilo di carico orario
    deterministico (piatto o diurno, normalizzato sulla potenza media base) e un
    blocco coperto a prezzo fisso (flat, in MW): ogni ora il carico sotto la
    copertura e' pagato a prezzo fisso, l'eccesso va a spot, e l'eventuale
    copertura in eccesso (long) viene rivenduta a spot. Si calcolano:
    - costo totale = energia coperta x prezzo fisso + energia aperta x spot
      - energia long x spot (rivendita dell'eccesso di copertura)
    - quota coperta effettiva = energia coperta / energia totale
    - costo tutto-a-spot (benchmark senza coperture)
    - scenari di carico x(1-v), x1, x(1+v) a copertura fissa: il range
      max-min del costo e' il RISCHIO VOLUME, e la tabella scenari mostra
      dove il costo si sposta.

    NaN-safe: serie vuota / indice non-datetime / parametri non numerici o
    fuori range / serie < 24h -> errore pulito; tz-aware reso naive;
    duplicati keep-first; deterministico.
    """
    PESI_FORME = {
        "piatto": [1.0] * 24,
        "diurno": [0.625, 0.625, 0.625, 0.625, 0.625, 0.625, 0.625,
                   1.25, 1.25, 1.25, 1.25, 1.25, 1.25, 1.25, 1.25, 1.25,
                   1.25, 1.25, 1.25, 1.25, 1.25, 0.625, 0.625, 0.625],
    }

    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        base = float(carico_base_mw)
    except (TypeError, ValueError):
        return _err("carico_base_mw non valido")
    if not (base > 0):
        return _err("carico_base_mw deve essere > 0")
    forma = str(forma_carico).lower()
    if forma not in PESI_FORME:
        return _err("forma_carico non valida: usare 'piatto' o 'diurno'")
    try:
        quota = float(quota_coperta_pct)
    except (TypeError, ValueError):
        return _err("quota_coperta_pct non valida")
    if not (0.0 <= quota <= 100.0):
        return _err("quota_coperta_pct deve essere tra 0 e 100")
    try:
        p_cop = float(prezzo_coperto_eur_mwh)
    except (TypeError, ValueError):
        return _err("prezzo_coperto_eur_mwh non valido")
    try:
        var = float(variazione_carico_pct)
    except (TypeError, ValueError):
        return _err("variazione_carico_pct non valida")
    if not (0.0 < var <= 50.0):
        return _err("variazione_carico_pct deve essere in (0, 50]")

    if prezzi is None or len(prezzi) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("indice non datetime")
    idxn = prezzi.index.tz_localize(None) if prezzi.index.tz is not None else prezzi.index
    p = pd.to_numeric(prezzi, errors="coerce")
    p.index = idxn
    p = p[~p.index.duplicated(keep="first")].sort_index().dropna()
    if len(p) < 24:
        return _err("serie prezzi troppo corta: servono almeno 24 ore valide")

    pesi = np.asarray(PESI_FORME[forma], dtype=float)
    pesi = pesi / pesi.mean()
    ore_giorno = p.index.hour.to_numpy()
    carico = base * pesi[ore_giorno]
    spot = p.to_numpy()
    hedge_mw = base * quota / 100.0

    def _costo(carico_h):
        coperto = np.minimum(carico_h, hedge_mw)
        aperto = carico_h - coperto
        lungo = np.maximum(hedge_mw - carico_h, 0.0)
        costo = (float(np.sum(coperto)) * p_cop
                 + float(np.sum(aperto * spot))
                 - float(np.sum(lungo * spot)))
        return (costo, float(np.sum(coperto)), float(np.sum(aperto)),
                float(np.sum(lungo)))

    costo_tot, en_cop, en_open, en_long = _costo(carico)
    energia_tot = float(np.sum(carico))
    costo_spot = float(np.sum(carico * spot))
    quota_eff = en_cop / energia_tot * 100.0 if energia_tot > 0 else 0.0
    risparmio = costo_spot - costo_tot

    fattori = [1.0 - var / 100.0, 1.0, 1.0 + var / 100.0]
    righe = []
    for f in fattori:
        c, ec, eo, el = _costo(carico * f)
        if f < 1:
            nome = "base -%.0f %%" % var
        elif f == 1:
            nome = "base"
        else:
            nome = "base +%.0f %%" % var
        righe.append({
            "Scenario carico": nome,
            "Energia (MWh)": round(energia_tot * f, 1),
            "Coperta (MWh)": round(ec, 1),
            "Aperta (MWh)": round(eo, 1),
            "Long (MWh)": round(el, 1),
            "Costo totale (EUR)": round(c, 0),
        })
    tabella = pd.DataFrame(righe)
    costi_scen = [r["Costo totale (EUR)"] for r in righe]
    rischio = max(costi_scen) - min(costi_scen)
    rischio_pct = rischio / costi_scen[1] * 100.0 if costi_scen[1] > 0 else None

    if rischio_pct is not None and rischio_pct > 15.0:
        giudizio = "ALTO"
        nota = ("il costo oscilla del %.1f %% tra gli scenari -/+" % rischio_pct
                + "%.0f %% di carico: aumenta la quota coperta per stabilizzarlo." % var)
    elif rischio_pct is not None and rischio_pct > 5.0:
        giudizio = "MEDIO"
        nota = ("il costo oscilla del %.1f %% tra gli scenari: esposizione gestibile, " % rischio_pct
                + "monitorare la quota coperta effettiva.")
    else:
        giudizio = "BASSO"
        nota = ("il costo oscilla solo del %s tra gli scenari: la copertura "
                % ("%.1f %%" % rischio_pct if rischio_pct is not None else "n/d")
                + "stabilizza bene il portafoglio.")

    return {
        "valido": True, "errore": None,
        "n_ore": len(p),
        "forma_carico": forma,
        "hedge_mw": hedge_mw,
        "energia_totale_mwh": energia_tot,
        "energia_coperta_mwh": en_cop,
        "energia_aperta_mwh": en_open,
        "energia_long_mwh": en_long,
        "quota_coperta_effettiva_pct": quota_eff,
        "costo_totale_eur": costo_tot,
        "costo_spot_eur": costo_spot,
        "risparmio_vs_spot_eur": risparmio,
        "tabella_scenari": tabella,
        "rischio_volume_eur": rischio,
        "rischio_volume_pct": rischio_pct,
        "variazione_carico_pct": var,
        "giudizio": giudizio,
        "verdetto": "RISCHIO VOLUME %s: %s" % (giudizio, nota),
    }


def calcola_costo_per_sito(prezzi, carichi):
    """Ripartizione del costo di fornitura su piu' siti/impianti (multi-sito).

    Domanda operativa: "quanto del costo totale dell'energia spetta a ciascun
    sito, e quale sito paga il MWh piu' caro per il suo profilo di consumo?"
    Il costo di ogni sito e' calcolato per causazione esatta
    (somma su ogni ora di prezzo_orario x carico_orario del sito), non con una
    ripartizione a forfait sull'energia: due siti con la stessa energia ma
    profili diversi pagano prezzi medi diversi perche' consumano in ore
    diverse (es. un sito notturno vs uno diurno).

    Parametri
    ---------
    prezzi : pd.Series — prezzi orari EUR/MWh, indice datetime.
    carichi : dict {nome_sito: pd.Series} oppure pd.DataFrame con una colonna
        per sito — carichi orari in MW, indice datetime (allineato per
        intersezione con l'indice dei prezzi).

    Ritorna dict con: valido, errore, tabella (pd.DataFrame, una riga per
    sito), energia_totale_mwh, costo_totale_eur,
    prezzo_medio_portafoglio_eur_mwh, n_ore, sito_piu_caro, sito_piu_economico,
    spread_eur_mwh, spread_pct, verdetto, giudizio.

    NaN-safe: serie prezzi vuota / indice non-datetime / <24h -> errore
    pulito; tz-aware reso naive; duplicati keep-first; carichi NaN -> 0
    (lettura mancante = sito fermo quell'ora, documentato); carichi negativi
    -> errore pulito; sito con energia nulla -> errore pulito; nomi
    vuoti/duplicati -> errore pulito; <24 ore in comune tra prezzi e carichi
    -> errore pulito; deterministico.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    # --- prezzi: pulizia standard ---
    if prezzi is None or len(prezzi) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("indice prezzi non datetime")
    idxn = prezzi.index.tz_localize(None) if prezzi.index.tz is not None else prezzi.index
    p = pd.to_numeric(prezzi, errors="coerce")
    p.index = idxn
    p = p[~p.index.duplicated(keep="first")].sort_index().dropna()
    if len(p) < 24:
        return _err("serie prezzi troppo corta: servono almeno 24 ore valide")

    # --- carichi: dict {nome: serie} o DataFrame ---
    if carichi is None:
        return _err("carichi non forniti")
    if isinstance(carichi, dict):
        nomi_raw = list(carichi.keys())
        serie_raw = list(carichi.values())
    elif isinstance(carichi, pd.DataFrame):
        nomi_raw = list(carichi.columns)
        serie_raw = [carichi[c] for c in nomi_raw]
    else:
        return _err("carichi deve essere dict {nome: serie} o DataFrame")
    if len(nomi_raw) == 0:
        return _err("nessun sito fornito")
    nomi = [str(n).strip() for n in nomi_raw]
    if any(n == "" for n in nomi):
        return _err("nome sito vuoto non ammesso")
    if len(set(nomi)) != len(nomi):
        return _err("nomi sito duplicati")

    pulite = {}
    for nome, s in zip(nomi, serie_raw):
        if s is None or len(s) == 0:
            return _err(f"sito '{nome}': serie carico vuota")
        if not isinstance(s.index, pd.DatetimeIndex):
            return _err(f"sito '{nome}': indice carico non datetime")
        idxs = s.index.tz_localize(None) if s.index.tz is not None else s.index
        q = pd.to_numeric(s, errors="coerce")
        q.index = idxs
        q = q[~q.index.duplicated(keep="first")].sort_index()
        # lettura mancante = sito fermo quell'ora -> 0 (documentato)
        pulite[nome] = q.fillna(0.0)

    idx_comune = p.index
    for q in pulite.values():
        idx_comune = idx_comune.intersection(q.index)
    idx_comune = idx_comune.sort_values()
    if len(idx_comune) < 24:
        return _err("meno di 24 ore in comune tra prezzi e carichi")
    pp = p.loc[idx_comune].to_numpy()

    righe = []
    for nome, q in pulite.items():
        vals = q.loc[idx_comune].to_numpy(dtype=float)
        if np.any(vals < 0):
            return _err(f"sito '{nome}': carichi negativi non ammessi "
                        "(usare i prelievi assoluti)")
        energia = float(np.sum(vals))
        if energia <= 0:
            return _err(f"sito '{nome}': energia nulla nel periodo")
        costo = float(np.sum(pp * vals))
        righe.append({
            "Sito": nome,
            "Energia (MWh)": energia,
            "Costo (EUR)": costo,
            "Prezzo medio (EUR/MWh)": costo / energia,
            "Ore attive": int(np.sum(vals > 0)),
        })

    tab = pd.DataFrame(righe)
    energia_tot = float(tab["Energia (MWh)"].sum())
    costo_tot = float(tab["Costo (EUR)"].sum())
    pmedio = costo_tot / energia_tot if energia_tot > 0 else 0.0
    tab["Quota costo (%)"] = 100.0 * tab["Costo (EUR)"] / costo_tot if costo_tot > 0 else 0.0
    tab["Quota energia (%)"] = 100.0 * tab["Energia (MWh)"] / energia_tot
    tab["Scost. vs medio (EUR/MWh)"] = tab["Prezzo medio (EUR/MWh)"] - pmedio
    if pmedio != 0:
        tab["Scost. vs medio (%)"] = 100.0 * tab["Scost. vs medio (EUR/MWh)"] / pmedio
    else:
        tab["Scost. vs medio (%)"] = 0.0

    i_max = int(tab["Prezzo medio (EUR/MWh)"].idxmax())
    i_min = int(tab["Prezzo medio (EUR/MWh)"].idxmin())
    sito_caro = tab.loc[i_max, "Sito"]
    sito_eco = tab.loc[i_min, "Sito"]
    spread = float(tab.loc[i_max, "Prezzo medio (EUR/MWh)"] - tab.loc[i_min, "Prezzo medio (EUR/MWh)"])
    spread_pct = (100.0 * spread / pmedio) if pmedio != 0 else 0.0

    if spread_pct > 15.0:
        giudizio = "RILEVANTI"
        verdetto = (f"⚠️ Differenze RILEVANTI tra siti: '{sito_caro}' paga il MWh "
                    f"{spread_pct:.1f}% in più di '{sito_eco}' "
                    f"({spread:.2f} €/MWh di scostamento). Vale la pena rivedere "
                    f"i profili di consumo o la struttura di acquisto per sito.")
    elif spread_pct > 5.0:
        giudizio = "MODERATE"
        verdetto = (f"ℹ️ Differenze moderate tra siti: '{sito_caro}' paga il MWh "
                    f"{spread_pct:.1f}% in più di '{sito_eco}'.")
    else:
        giudizio = "OMOGENEE"
        verdetto = (f"✅ Costi omogenei tra siti: scostamento massimo del prezzo "
                    f"medio del {spread_pct:.1f}%.")

    return {
        "errore": None,
        "valido": True,
        "tabella": tab,
        "n_ore": len(idx_comune),
        "energia_totale_mwh": energia_tot,
        "costo_totale_eur": costo_tot,
        "prezzo_medio_portafoglio_eur_mwh": pmedio,
        "sito_piu_caro": sito_caro,
        "sito_piu_economico": sito_eco,
        "spread_eur_mwh": spread,
        "spread_pct": spread_pct,
        "giudizio": giudizio,
        "verdetto": verdetto,
    }


def calcola_elasticita_domanda(prezzi, carico, shift_pct=10.0, min_ore=168):
    """Elasticita' della domanda al prezzo (regressione log-log OLS) + what-if demand response.

    Domanda operativa: "di quanto il consumo reagisce al prezzo? E se
    spostassi l'x% dell'energia dalle ore care a quelle economiche, quanto
    risparmierei?" Stima l'elasticita' eps della regressione
    log(carico) = a + eps * log(prezzo) sulle ore con prezzo e carico
    strettamente positivi (i logaritmi richiedono valori > 0: le ore con
    prezzo <= 0 — es. prezzi negativi — o carico <= 0 / NaN vengono
    scartate, non riempite: un'ora senza consumo non informa la risposta
    al prezzo).

    Parametri
    ---------
    prezzi : pd.Series — prezzi orari EUR/MWh, indice datetime.
    carico : pd.Series — carico orario MW, indice datetime.
    shift_pct : float — quota % di energia spostata dalle ore care
        (quartile di prezzo piu' alto) a quelle economiche (quartile piu'
        basso) nello scenario what-if del KPI.
    min_ore : int — ore utili minime per una stima attendibile.

    Ritorna dict con: valido, errore, elasticita, intercetta, r2, p_value,
    t_stat, n_ore, n_scartate, prezzo_medio, carico_medio_mw, tabella_cluster
    (pd.DataFrame: elasticita'/R2 per quartile di prezzo), tabella_whatif
    (pd.DataFrame: risparmio stimato per quote di spostamento 5/10/15/20/
    25/30%), e_q4_mwh, p_q4_medio, p_q1_medio, giudizio, verdetto.

    NaN-safe: serie vuota / indice non-datetime / <min_ore ore utili /
    prezzo costante / carico non-serie -> errore pulito; tz-aware reso
    naive; duplicati keep-first; deterministico (OLS puro, nessun seed).
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    def _ols(x, y):
        """OLS y = a + b*x su array numpy. Ritorna dict o None se degenere."""
        n = len(x)
        if n < 3:
            return None
        xm = float(x.mean())
        ym = float(y.mean())
        xc = x - xm
        yc = y - ym
        sxx = float((xc ** 2).sum())
        if sxx <= 0.0:
            return None
        b = float((xc * yc).sum() / sxx)
        a = float(ym - b * xm)
        yhat = a + b * x
        ssr = float(((y - yhat) ** 2).sum())
        sst = float((yc ** 2).sum())
        r2 = 1.0 - ssr / sst if sst > 0.0 else 0.0
        dof = n - 2
        se_b = float(np.sqrt(ssr / dof) / np.sqrt(sxx)) if dof > 0 and ssr >= 0.0 else float("nan")
        if not np.isfinite(se_b):
            t, p = 0.0, 1.0
        elif se_b == 0.0:
            # fit perfetto (ssr = 0): t -> +/-inf, p -> 0 (b != 0);
            # se anche b = 0 (carico costante) non c'e' relazione: p = 1
            t = np.inf if b > 0 else (-np.inf if b < 0 else 0.0)
            p = 0.0 if b != 0.0 else 1.0
        else:
            t = b / se_b
            p = float(2.0 * (1.0 - norm.cdf(abs(t))))
        return {"b": b, "a": a, "r2": max(0.0, min(1.0, r2)), "t": t, "p": p, "n": n}

    # --- pulizia prezzi ---
    if prezzi is None or len(prezzi) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("indice prezzi non datetime")
    idxn = prezzi.index.tz_localize(None) if prezzi.index.tz is not None else prezzi.index
    p = pd.to_numeric(prezzi, errors="coerce")
    p.index = idxn
    p = p[~p.index.duplicated(keep="first")].sort_index().dropna()
    if len(p) == 0:
        return _err("serie prezzi senza valori validi")

    # --- pulizia carico ---
    if carico is None:
        return _err("serie carico non fornita")
    if not isinstance(carico, pd.Series):
        return _err("carico deve essere una pd.Series oraria (MW)")
    if not isinstance(carico.index, pd.DatetimeIndex):
        return _err("indice carico non datetime")
    idxc = carico.index.tz_localize(None) if carico.index.tz is not None else carico.index
    q = pd.to_numeric(carico, errors="coerce")
    q.index = idxc
    q = q[~q.index.duplicated(keep="first")].sort_index()

    idx = p.index.intersection(q.index)
    if len(idx) == 0:
        return _err("nessuna ora in comune tra prezzi e carico")
    pp = p.loc[idx]
    qq = q.loc[idx]
    mask = (pp > 0) & (qq > 0) & pp.notna() & qq.notna()
    n_scartate = int((~mask).sum())
    pp = pp[mask]
    qq = qq[mask]
    n = len(pp)
    if n < int(min_ore):
        return _err(f"ore utili insufficienti: {n} "
                    f"(servono almeno {int(min_ore)} ore con prezzo e carico positivi)")
    if float(pp.std()) == 0.0 or int(pp.nunique()) < 2:
        return _err("prezzo costante sul periodo: elasticita' non identificabile")

    x = np.log(pp.to_numpy(dtype=float))
    y = np.log(qq.to_numpy(dtype=float))
    ols = _ols(x, y)
    if ols is None:
        return _err("regressione non identificabile sui dati")
    eps = ols["b"]

    # --- cluster per quartili di prezzo (stessa numerosita', ordinati per prezzo) ---
    order = np.argsort(pp.to_numpy())
    k = max(n // 4, 1)
    gruppi = [("Q1 (economiche)", order[:k]),
              ("Q2", order[k:2 * k]),
              ("Q3", order[2 * k:3 * k]),
              ("Q4 (care)", order[3 * k:])]
    righe_c = []
    for nome, pos in gruppi:
        if len(pos) < 24:
            continue
        oc = _ols(x[pos], y[pos])
        righe_c.append({
            "Fascia prezzo": nome,
            "Prezzo medio (EUR/MWh)": round(float(pp.iloc[pos].mean()), 2),
            "Carico medio (MW)": round(float(qq.iloc[pos].mean()), 3),
            "Ore": int(len(pos)),
            "Elasticita'": round(oc["b"], 3) if oc else None,
            "R2": round(oc["r2"], 3) if oc else None,
        })
    df_c = pd.DataFrame(righe_c)

    # --- what-if: sposta s% dell'energia delle ore care (Q4) a quelle economiche (Q1) ---
    pos_q4 = gruppi[3][1]
    pos_q1 = gruppi[0][1]
    e_q4 = float(qq.iloc[pos_q4].sum())
    p_q4 = float(pp.iloc[pos_q4].mean())
    p_q1 = float(pp.iloc[pos_q1].mean())
    costo_tot = float((pp * qq).sum())
    e_tot = float(qq.sum())
    righe_w = []
    for s in (5, 10, 15, 20, 25, 30):
        e_sp = s / 100.0 * e_q4
        risp = e_sp * (p_q4 - p_q1)
        righe_w.append({
            "Quota spostata (%)": s,
            "Energia spostata (MWh)": round(e_sp, 1),
            "Risparmio stimato (EUR)": round(risp, 0),
            "Risparmio (%)": round(100.0 * risp / costo_tot, 2) if costo_tot > 0 else 0.0,
            "Prezzo medio equivalente (EUR/MWh)": round((costo_tot - risp) / e_tot, 2) if e_tot > 0 else 0.0,
        })
    df_w = pd.DataFrame(righe_w)

    sp = float(shift_pct)
    e_sp_kpi = sp / 100.0 * e_q4
    risp_kpi = e_sp_kpi * (p_q4 - p_q1)

    pv = ols["p"]
    if pv >= 0.05:
        giudizio = "NON SIGNIFICATIVA"
        verdetto = (f"ℹ️ Elasticita' stimata {eps:+.3f} ma NON significativa "
                    f"(p-value {pv:.3f} ≥ 0.05): sui dati del periodo non c'e' "
                    f"evidenza che il carico risponda al prezzo. Lo scenario "
                    f"what-if resta una stima meccanica, non comportamentale.")
    elif eps > 0:
        giudizio = "CONTROINTUITIVA"
        verdetto = (f"⚠️ Elasticita' POSITIVA ({eps:+.3f}, p-value {pv:.4f}): il "
                    f"carico cresce quando il prezzo sale — comportamento "
                    f"controintuitivo. Verificare confondenti (es. ondate di "
                    f"calore/freddo che alzano insieme domanda e prezzi).")
    elif abs(eps) >= 0.3:
        giudizio = "ELASTICA"
        verdetto = (f"✅ Domanda ELASTICA (ε = {eps:.3f}, p-value {pv:.4f}, "
                    f"R² = {ols['r2']:.2f}): il carico risponde bene al prezzo — "
                    f"la flessibilita'/il demand response hanno valore economico "
                    f"reale. Spostare il {sp:.0f}% dell'energia dalle ore care "
                    f"vale ~{risp_kpi:,.0f} €.".replace(",", " "))
    elif abs(eps) >= 0.1:
        giudizio = "MODERATA"
        verdetto = (f"ℹ️ Domanda MODERATAMENTE reattiva (ε = {eps:.3f}, p-value "
                    f"{pv:.4f}, R² = {ols['r2']:.2f}): c'e' risposta al prezzo "
                    f"ma limitata — il demand response paga solo su volumi "
                    f"importanti.")
    else:
        giudizio = "RIGIDA"
        verdetto = (f"✅ Domanda RIGIDA (ε = {eps:.3f} ≈ 0, p-value {pv:.4f}): il "
                    f"carico non risponde al prezzo — la leva e' solo "
                    f"sull'acquisto (fissazioni, coperture), non sullo "
                    f"spostamento dei consumi.")

    return {
        "errore": None,
        "valido": True,
        "elasticita": eps,
        "intercetta": ols["a"],
        "r2": ols["r2"],
        "p_value": pv,
        "t_stat": ols["t"],
        "n_ore": n,
        "n_scartate": n_scartate,
        "prezzo_medio": float(pp.mean()),
        "carico_medio_mw": float(qq.mean()),
        "tabella_cluster": df_c,
        "tabella_whatif": df_w,
        "e_q4_mwh": e_q4,
        "p_q4_medio": p_q4,
        "p_q1_medio": p_q1,
        "costo_totale": costo_tot,
        "risparmio_kpi": risp_kpi,
        "giudizio": giudizio,
        "verdetto": verdetto,
    }


def calcola_fattore_carico(prezzi, mw_f1, mw_f2, mw_f3, costo_potenza_eur_kw_anno=40.0,
                          riduzione_picco_pct=10.0, min_ore=24):
    """Fattore di carico (load factor) del profilo di prelievo + costo della "puntitudine".

    Domanda operativa: "quanto e' piatto il mio profilo?" Il fattore di
    carico LF = potenza media / potenza di picco (0-100%) misura quanto bene
    si sfrutta la potenza impegnata: LF alto = prelievo costante (i fornitori
    quotano meglio e la quota potenza "rende"), LF basso = picchi concentrati
    (quota potenza cara e margine per appiattire il profilo). Le ore
    equivalenti a pieno carico (energia / picco) dicono in quante ore "a
    tutto picco" si consuma l'energia del periodo.

    In piu' si quantifica il "costo della puntitudine": quanto si paga IN PIU'
    rispetto a un profilo perfettamente piatto con la STESSA energia
    (premio = costo reale - energia x prezzo medio aritmetico del periodo),
    e uno scenario what-if che taglia il picco del r%: quanta energia sta
    sopra la nuova soglia, a che prezzo medio, e quanto vale il taglio in
    quota potenza (annualizzata sul periodo) + minor costo energia.

    Differenza dagli altri tab: "Potenza di picco" ottimizza la potenza
    impegnata contrattuale, "Peak shaving" simula la batteria, "Efficienza
    profilo" misura la smartness rispetto ai prezzi; qui si misura la
    PIATTEZZA del profilo in se' e il suo costo implicito, senza simulare
    nessuna azione.

    Metodo (tutto deterministico a parita' di input):
    - carico orario = MW della fascia di ciascuna ora (via fascia_oraria,
      stesso profilo piatto per fascia degli altri tab);
    - LF = media / picco; ore equivalenti = energia / picco;
    - tabella mensile via groupby su Period M dell'indice reso tz-naive
      (compatibile pandas 2.1/2.2);
    - what-if per tagli 5/10/15/20/25/30%: soglia = picco*(1-r/100);
      energia sopra soglia e prezzo medio delle ore sopra soglia;
      risparmio quota potenza = (picco-soglia)*1000*costo_potenza,
      annualizzato sul periodo (x ore_periodo/8760); risparmio energia =
      energia_sopra * max(0, p_medio_sopra - p_medio_periodo).

    NaN-safe: serie vuota / indice non-datetime / <min_ore ore / MW non
    numerici, negativi o tutti zero / costo potenza negativo / riduzione
    fuori [0, 50] -> errore pulito; tz-aware reso naive; duplicati
    keep-first; deterministico (nessun seed).
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    # --- parametri ---
    try:
        mws = [float(mw_f1), float(mw_f2), float(mw_f3)]
    except (TypeError, ValueError):
        return _err("MW per fascia non numerici")
    if any(m < 0.0 for m in mws):
        return _err("MW per fascia non possono essere negativi")
    if all(m == 0.0 for m in mws):
        return _err("carico nullo: tutti i MW a zero")
    try:
        cp = float(costo_potenza_eur_kw_anno)
    except (TypeError, ValueError):
        return _err("costo potenza non numerico")
    if cp < 0.0:
        return _err("costo potenza non puo' essere negativo")
    try:
        rid = float(riduzione_picco_pct)
    except (TypeError, ValueError):
        return _err("riduzione picco non numerica")
    if not (0.0 <= rid <= 50.0):
        return _err("riduzione picco fuori range [0, 50] %")

    # --- pulizia prezzi ---
    if prezzi is None or len(prezzi) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("indice prezzi non datetime")
    idxn = prezzi.index.tz_localize(None) if prezzi.index.tz is not None else prezzi.index
    p = pd.to_numeric(prezzi, errors="coerce")
    p.index = idxn
    p = p[~p.index.duplicated(keep="first")].sort_index().dropna()
    n = len(p)
    if n < int(min_ore):
        return _err(f"serie troppo corta: {n} ore (minimo {int(min_ore)})")

    def _fascia(ts):
        # Replica locale di fascia_oraria (AEEGSI F1/F2/F3): la versione
        # originale vive a livello modulo, ma qui serve una copia
        # self-contained per l'estrazione via AST nei test (il namespace
        # dei test non include le altre funzioni di app.py).
        wd, h = ts.weekday(), ts.hour
        if wd == 6:
            return "F3"
        if wd == 5:
            return "F2" if 7 <= h < 23 else "F3"
        if 8 <= h < 19:
            return "F1"
        if (7 <= h < 8) or (19 <= h < 23):
            return "F2"
        return "F3"

    # --- carico orario dal profilo piatto per fascia ---
    fasce = p.index.map(_fascia)
    mw_map = {"F1": mws[0], "F2": mws[1], "F3": mws[2]}
    q = pd.Series([mw_map[f] for f in fasce], index=p.index, dtype=float)

    energia = float(q.sum())
    picco = float(q.max())
    media = float(q.mean())
    lf = media / picco if picco > 0.0 else 0.0
    ore_eq = energia / picco if picco > 0.0 else 0.0
    p_medio = float(p.mean())
    costo_reale = float((p * q).sum())
    costo_flat = energia * p_medio
    premio = costo_reale - costo_flat
    premio_pct = 100.0 * premio / costo_flat if costo_flat > 0.0 else None

    # --- tabella mensile ---
    mesi = p.index.to_period("M")
    righe_m = []
    for per in sorted(set(mesi)):
        msk = mesi == per
        qm, pm = q[msk], p[msk]
        em = float(qm.sum())
        pkm = float(qm.max())
        righe_m.append({
            "Mese": str(per),
            "Ore": int(msk.sum()),
            "Energia (MWh)": round(em, 1),
            "Picco (MW)": round(pkm, 3),
            "Fattore di carico (%)": round(100.0 * float(qm.mean()) / pkm, 1) if pkm > 0.0 else 0.0,
            "Prezzo medio ponderato (EUR/MWh)": round(float((pm * qm).sum() / em), 2) if em > 0.0 else None,
        })
    df_m = pd.DataFrame(righe_m)

    # --- what-if: taglio del picco ---
    def _whatif(r):
        soglia = picco * (1.0 - r / 100.0)
        sopra = q > soglia
        n_sopra = int(sopra.sum())
        e_sopra = float((q - soglia)[sopra].sum())
        p_sopra = float(p[sopra].mean()) if n_sopra > 0 else None
        risp_pot = (picco - soglia) * 1000.0 * cp * (n / 8760.0)
        risp_en = e_sopra * max(0.0, p_sopra - p_medio) if p_sopra is not None else 0.0
        return {
            "soglia": soglia, "n_sopra": n_sopra, "e_sopra": e_sopra,
            "p_sopra": p_sopra, "risp_pot": risp_pot, "risp_en": risp_en,
        }

    righe_w = []
    for r in (5, 10, 15, 20, 25, 30):
        w = _whatif(r)
        righe_w.append({
            "Taglio picco (%)": r,
            "Nuova soglia (MW)": round(w["soglia"], 3),
            "Ore sopra soglia": w["n_sopra"],
            "Energia sopra soglia (MWh)": round(w["e_sopra"], 1),
            "Prezzo medio ore sopra (EUR/MWh)": round(w["p_sopra"], 2) if w["p_sopra"] is not None else None,
            "Risparmio quota potenza (EUR/anno)": round(w["risp_pot"], 0),
            "Risparmio energia stimato (EUR)": round(w["risp_en"], 0),
            "Risparmio totale stimato (EUR)": round(w["risp_pot"] + w["risp_en"], 0),
        })
    df_w = pd.DataFrame(righe_w)
    wk = _whatif(rid)

    premio_pct_txt = f"{premio_pct:.1f}%" if premio_pct is not None else "n/d"
    if lf >= 0.8:
        giudizio = "ECCELLENTE"
        verdetto = (f"✅ Profilo quasi piatto (LF {lf:.1%}): sfrutti bene la "
                    f"potenza impegnata ({ore_eq:,.0f} ore equivalenti a pieno "
                    f"carico). ".replace(",", " ") +
                    f"La 'puntitudine' ti costa {premio:,.0f} € in piu' "
                    f"rispetto a un profilo piatto a pari energia."
                    .replace(",", " "))
    elif lf >= 0.6:
        giudizio = "BUONO"
        verdetto = (f"ℹ️ Profilo abbastanza piatto (LF {lf:.1%}): la potenza "
                    f"impegnata rende ({ore_eq:,.0f} ore equivalenti). "
                    .replace(",", " ") +
                    f"Costo della puntitudine: {premio:,.0f} € sul periodo "
                    f"({premio_pct_txt} del costo piatto). Tagliare il picco "
                    f"del {rid:.0f}% varrebbe ~{wk['risp_pot'] + wk['risp_en']:,.0f} €/anno."
                    .replace(",", " "))
    elif lf >= 0.4:
        giudizio = "MEDIO"
        verdetto = (f"⚠️ Profilo con picchi marcati (LF {lf:.1%}): stai pagando "
                    f"potenza che usi poche ore ({ore_eq:,.0f} ore equivalenti "
                    f"su {n} ore). ".replace(",", " ") +
                    f"Costo della puntitudine: {premio:,.0f} € "
                    f"({premio_pct_txt} in piu' del piatto). Leva: appiattire "
                    f"il profilo o ridurre la potenza impegnata — tagliare il "
                    f"picco del {rid:.0f}% vale ~{wk['risp_pot'] + wk['risp_en']:,.0f} €/anno."
                    .replace(",", " "))
    else:
        giudizio = "BASSO"
        verdetto = (f"🚨 Profilo molto appuntito (LF {lf:.1%}): il picco di "
                    f"{picco:.2f} MW domina su una media di {media:.2f} MW "
                    f"({ore_eq:,.0f} ore equivalenti). ".replace(",", " ") +
                    f"Paghi {premio:,.0f} € in piu' rispetto a un profilo "
                    f"piatto a pari energia ({premio_pct_txt}). Priorita': "
                    f"shifting dei carichi, accumulo o potenza modulata — il "
                    f"taglio del {rid:.0f}% del picco vale "
                    f"~{wk['risp_pot'] + wk['risp_en']:,.0f} €/anno."
                    .replace(",", " "))
    if premio_pct is None:
        verdetto += " (Premio % non calcolabile: costo piatto non positivo.)"

    return {
        "errore": None,
        "valido": True,
        "lf": lf,
        "lf_pct": 100.0 * lf,
        "ore_equivalenti": ore_eq,
        "energia_mwh": energia,
        "picco_mw": picco,
        "potenza_media_mw": media,
        "n_ore": n,
        "prezzo_medio": p_medio,
        "costo_reale": costo_reale,
        "costo_flat": costo_flat,
        "premio_eur": premio,
        "premio_pct": premio_pct,
        "tabella_mensile": df_m,
        "tabella_whatif": df_w,
        "whatif_kpi": wk,
        "giudizio": giudizio,
        "verdetto": verdetto,
    }


def calcola_heat_rate_implicito(prezzi, gas_eur_mwh, co2_eur_t, ef_tco2_mwh=0.4,
                                min_ore=24):
    """Heat rate implicito orario del mercato: quale impianto fissa il prezzo?

    Domanda operativa: "che efficienza ha l'impianto marginale che sta
    fissando il prezzo?" L'heat rate implicito (IHR) inverte la formula dello
    spark spread: invece di fissare l'efficienza e calcolare il margine, si
    fissa il prezzo di mercato e si ricava l'efficienza dell'unita' marginale.

    IHR_clean(h) = (P(h) - ef x E) / G    [MWh termici / MWh elettrico]
    IHR_lordo(h) = P(h) / G               (senza scorporo CO2, per confronto)

    P = prezzo spot elettrico €/MWh, G = prezzo gas €/MWh termico,
    E = prezzo CO2 €/t, ef = fattore emissivo tCO2/MWh elettrico
    (default 0.4, CCGT). L'efficienza implicita e' 1 / IHR_clean.

    Lettura dei regimi (self-contained, stessa soglia in UI e test):
      IHR < 1.50 : Rinnovabili/nucleare sul margine (eff. implicita > 66.7%:
                   il prezzo scende sotto il costo variabile del gas)
      1.50-2.00 : CCGT moderno sul margine
      2.00-2.50 : Gas a media efficienza
      2.50-3.20 : OCGT / picco gas
      >= 3.20   : Scarsita' / premio di scarsita' (il mercato prezza oltre il
                   costo variabile anche dell'impianto a gas piu' inefficiente)

    Differenza dagli altri tab: "Spark spread" e "Tolling" fissano
    l'efficienza e calcolano il margine di UNA centrale; qui si legge il
    mercato per capire CHI fissa il prezzo, utile per posizionare le
    coperture gas-power e anticipare la risposta dello spot ai movimenti
    di TTF/EUA.

    NaN-safe: serie vuota / indice non datetime / non numerica / gas <= 0 /
    CO2 < 0 / ef <= 0 -> errore pulito; ore con (P - ef*E) <= 0 scartate e
    contate (ore_scartate); < min_ore ore valide -> errore pulito; tz-aware
    reso naive, duplicati keep-first; deterministico.
    """
    def _err(msg):
        return {"valido": False, "errore": msg, "serie_ihr": None,
                "serie_ihr_lordo": None, "tabella_mensile": None}

    regimi = (
        (1.50, "Rinnovabili/nucleare sul margine"),
        (2.00, "CCGT moderno sul margine"),
        (2.50, "Gas a media efficienza"),
        (3.20, "OCGT / picco gas"),
        (float("inf"), "Scarsita' / premio di scarsita'"),
    )

    def _regime(v):
        for soglia, nome in regimi:
            if v < soglia:
                return nome
        return regimi[-1][1]

    try:
        gas = float(gas_eur_mwh)
        co2 = float(co2_eur_t)
        ef = float(ef_tco2_mwh)
    except (TypeError, ValueError):
        return _err("Parametri gas/CO2 non numerici.")
    if not gas > 0:
        return _err("Il prezzo del gas deve essere > 0.")
    if not co2 >= 0:
        return _err("Il prezzo CO2 non puo' essere negativo.")
    if not ef > 0:
        return _err("Il fattore emissivo deve essere > 0.")

    if not isinstance(prezzi, pd.Series):
        return _err("Serie prezzi non valida.")
    try:
        s = prezzi.copy()
    except Exception:
        return _err("Serie prezzi non valida.")
    if not isinstance(s.index, pd.DatetimeIndex):
        return _err("L'indice dei prezzi deve essere datetime.")
    try:
        s = pd.to_numeric(s, errors="coerce")
    except Exception:
        return _err("Serie prezzi non numerica.")
    s = s.sort_index()
    if getattr(s.index, "tz", None) is not None:
        s.index = s.index.tz_localize(None)
    s = s[~s.index.duplicated(keep="first")]
    s = s.dropna()
    n_tot = int(len(s))
    if n_tot == 0:
        return _err("Serie prezzi vuota dopo la pulizia.")

    costo_co2 = co2 * ef
    num = s - costo_co2
    ihr = num / gas
    lordo = s / gas
    valida = ihr[ihr > 0]
    n_val = int(len(valida))
    if n_val < int(min_ore):
        return _err(f"Ore valide insufficienti ({n_val} < {min_ore}): il "
                    "numeratore (prezzo - costo CO2) e' <= 0 quasi ovunque.")

    serie_ihr = valida.copy()
    serie_ihr.name = "Heat rate implicito (MWh_th/MWh_e)"
    serie_lordo = lordo.loc[valida.index].copy()
    serie_lordo.name = "Heat rate implicito lordo (MWh_th/MWh_e)"

    medio = float(serie_ihr.mean())
    eff = 100.0 / medio if medio > 0 else None
    reg = serie_ihr.apply(_regime)
    conteggi = reg.value_counts()
    nomi = [nome for _, nome in regimi]
    quote = {nome: float(conteggi.get(nome, 0)) / n_val * 100.0 for nome in nomi}
    dominante = str(conteggi.idxmax())
    q_scars = quote[nomi[-1]]

    righe = []
    dfm = pd.DataFrame({"ihr": serie_ihr, "regime": reg})
    dfm["mese"] = dfm.index.to_period("M")
    for m, g in dfm.groupby("mese", observed=True):
        g_mean = float(g["ihr"].mean())
        righe.append({
            "Mese": str(m),
            "Ore valide": int(len(g)),
            "Heat rate implicito medio": round(g_mean, 2),
            "Efficienza implicita (%)": round(100.0 / g_mean, 1),
            "Regime dominante": str(g["regime"].mode().iloc[0]),
            "Scarsita' (%)": round(float((g["regime"] == nomi[-1]).mean() * 100), 1),
        })
    tabella_mensile = pd.DataFrame(righe)

    verdetto = (f"Sul margine sta soprattutto: {dominante} "
                f"({quote[dominante]:.1f}% delle ore).")
    if q_scars >= 10.0:
        verdetto += (f" Nel {q_scars:.1f}% delle ore il prezzo incorpora un "
                     "premio di scarsita' (IHR >= 3.20): il mercato prezza "
                     "oltre il costo variabile anche dell'impianto a gas "
                     "piu' inefficiente.")
    if eff is not None and eff > 66.7:
        verdetto += (" L'efficienza implicita media supera il 66.7%: nelle "
                     "ore rinnovabili/nucleare sul margine il prezzo scende "
                     "sotto il costo variabile del gas.")

    return {
        "valido": True,
        "errore": None,
        "serie_ihr": serie_ihr,
        "serie_ihr_lordo": serie_lordo,
        "medio": round(medio, 3),
        "mediana": round(float(serie_ihr.median()), 3),
        "minimo": round(float(serie_ihr.min()), 3),
        "massimo": round(float(serie_ihr.max()), 3),
        "medio_lordo": round(float(serie_lordo.mean()), 3),
        "eff_implicita_pct": round(eff, 1) if eff is not None else None,
        "ore_valide": n_val,
        "ore_totali": n_tot,
        "ore_scartate": n_tot - n_val,
        "quote_regimi": {k: round(v, 1) for k, v in quote.items()},
        "regime_dominante": dominante,
        "quota_scarsita": round(q_scars, 1),
        "tabella_mensile": tabella_mensile,
        "giudizio": dominante,
        "verdetto": verdetto,
    }



def calcola_prezzo_fisso_equo(prezzi, carico_base_mw=5.0, forma_carico="diurno",
                              premio_rischio_pct=5.0, margine_eur_mwh=3.0,
                              adder_volume_eur_mwh=1.0):
    """Prezzo fisso equo per un contratto di fornitura (fornitore che quota
    un prezzo fisso a un cliente finale).

    Domanda operativa: "a quale prezzo fisso posso vendere il MWh senza
    rimetterci, dato il profilo di carico del cliente?" Si costruisce il
    profilo di carico orario deterministico (piatto o diurno, normalizzato
    sulla potenza media base) e si calcola il prezzo medio ponderato sul
    profilo (PWP) dalla serie dei prezzi; il prezzo fisso equo aggiunge:
    - premio di rischio prezzo (forward risk premium, % sul PWP): copre il
      fatto che il prezzo futuro e' incerto;
    - margine commerciale (EUR/MWh): costi di struttura + utile;
    - adder volume (EUR/MWh): margine di sicurezza per lo scostamento del
      carico reale da quello atteso.
    Il risultato e' il prezzo fisso minimo sostenibile; la tabella di
    sensibilita' mostra come si muove al variare di premio e margine.

    NaN-safe: serie vuota / indice non-datetime / parametri non numerici o
    fuori range / serie < 24h -> errore pulito; tz-aware reso naive;
    duplicati keep-first; deterministico.
    """
    PESI_FORME = {
        "piatto": [1.0] * 24,
        "diurno": [0.625, 0.625, 0.625, 0.625, 0.625, 0.625, 0.625,
                   1.25, 1.25, 1.25, 1.25, 1.25, 1.25, 1.25, 1.25,
                   1.25, 1.25, 1.25, 1.25, 1.25, 1.25, 0.625, 0.625,
                   0.625],
    }

    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        base = float(carico_base_mw)
    except (TypeError, ValueError):
        return _err("carico_base_mw non valido")
    if not (base > 0):
        return _err("carico_base_mw deve essere > 0")
    forma = str(forma_carico).lower()
    if forma not in PESI_FORME:
        return _err("forma_carico non valida: usare 'piatto' o 'diurno'")
    try:
        premio = float(premio_rischio_pct)
    except (TypeError, ValueError):
        return _err("premio_rischio_pct non valido")
    if not (0.0 <= premio <= 100.0):
        return _err("premio_rischio_pct deve essere tra 0 e 100")
    try:
        marg = float(margine_eur_mwh)
    except (TypeError, ValueError):
        return _err("margine_eur_mwh non valido")
    if not (marg >= 0.0):
        return _err("margine_eur_mwh deve essere >= 0")
    try:
        adder = float(adder_volume_eur_mwh)
    except (TypeError, ValueError):
        return _err("adder_volume_eur_mwh non valido")
    if not (adder >= 0.0):
        return _err("adder_volume_eur_mwh deve essere >= 0")

    if prezzi is None or len(prezzi) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("indice non datetime")
    idxn = prezzi.index.tz_localize(None) if prezzi.index.tz is not None else prezzi.index
    p = pd.to_numeric(prezzi, errors="coerce")
    p.index = idxn
    p = p[~p.index.duplicated(keep="first")].sort_index().dropna()
    if len(p) < 24:
        return _err("serie prezzi troppo corta: servono almeno 24 ore valide")

    pesi = np.asarray(PESI_FORME[forma], dtype=float)
    pesi = pesi / pesi.mean()
    ore_giorno = p.index.hour.to_numpy()
    carico = base * pesi[ore_giorno]
    spot = p.to_numpy()

    energia_tot = float(np.sum(carico))
    if not (energia_tot > 0):
        return _err("energia totale nulla")
    costo_spot = float(np.sum(carico * spot))
    pwp = costo_spot / energia_tot
    premio_eur = pwp * premio / 100.0
    prezzo_equo = pwp + premio_eur + marg + adder
    addon = premio_eur + marg + adder
    addon_pct = addon / pwp * 100.0 if pwp > 0 else 0.0
    costo_equo = prezzo_equo * energia_tot

    if addon_pct > 20.0:
        giudizio = "ALTO"
        nota = ("gli add-on superano il 20%% del PWP: prezzo fisso poco "
                "competitivo, rivedi premio/margine/adder.")
    elif addon_pct > 10.0:
        giudizio = "MEDIO"
        nota = ("gli add-on sono tra il 10%% e il 20%% del PWP: prezzo "
                "fisso difendibile ma con margine di trattativa.")
    else:
        giudizio = "CONTENUTO"
        nota = ("gli add-on restano sotto il 10%% del PWP: prezzo fisso "
                "competitivo e comunque sostenibile.")

    scomposizione = pd.DataFrame({
        "Componente": ["Prezzo medio ponderato (PWP)",
                       "Premio di rischio prezzo",
                       "Margine commerciale",
                       "Adder volume",
                       "Prezzo fisso equo"],
        "EUR/MWh": [pwp, premio_eur, marg, adder, prezzo_equo],
    })

    livelli_premio = sorted({max(0.0, premio - 2.5), premio,
                             min(100.0, premio + 2.5)})
    livelli_marg = sorted({max(0.0, marg - 2.0), marg, marg + 2.0})
    righe = []
    for m in livelli_marg:
        riga = {"Margine (EUR/MWh)": m}
        for pr in livelli_premio:
            riga["Premio %.1f %%" % pr] = pwp * (1.0 + pr / 100.0) + m + adder
        righe.append(riga)
    sensibilita = pd.DataFrame(righe).round(2)

    return {
        "valido": True, "errore": None,
        "n_ore": len(p),
        "forma_carico": forma,
        "energia_totale_mwh": energia_tot,
        "pwp_eur_mwh": pwp,
        "premio_eur_mwh": premio_eur,
        "margine_eur_mwh": marg,
        "adder_volume_eur_mwh": adder,
        "prezzo_fisso_equo_eur_mwh": prezzo_equo,
        "addon_pct": addon_pct,
        "costo_equo_eur": costo_equo,
        "costo_spot_eur": costo_spot,
        "scomposizione": scomposizione,
        "sensibilita": sensibilita,
        "giudizio": giudizio,
        "verdetto": "ADD-ON %s: %s" % (giudizio, nota),
    }


def calcola_idrogeno_verde(prezzi, potenza_mw=10.0, capex_eur_kw=1500.0,
                           opex_eur_kw_anno=40.0, efficienza_pct=65.0,
                           prezzo_h2_eur_kg=6.0, tasso_pct=6.0, vita_anni=20):
    """Business case idrogeno VERDE da elettrolizzatore alimentato a spot.

    Domanda operativa: "con i prezzi spot del periodo, un elettrolizzatore
    che produce H2 da vendere a prezzo fisso conviene?" Si calcolano:
    - kg H2 per MWh consumato = 1000 * efficienza / 33.33 (33.33 kWh/kg = PCI H2)
    - prezzo di BREAK-EVEN dello spot: P_be = prezzo_h2 * kg_per_mwh; ogni ora
      con spot < P_be il margine lordo orario e' positivo
    - SOGLIA OTTIMALE: tra 61 candidati deterministici in [min(0, prezzo_min), P_be]
      si sceglie la soglia che massimizza il margine lordo annuo (ore con
      spot < soglia x margine unitario). OPEX fisso e' affondato e non entra
      nella scelta della soglia.
    - annualizzazione x 8760/n_ore; LCOH = (CRF*CAPEX + OPEX + costo elettricita')
      / kg annui; NPV con flussi = margine netto costante; payback semplice.

    NaN-safe: serie vuota / indice non-datetime / parametri non numerici o fuori
    range / efficienza fuori (0,100] / prezzo H2 <= 0 -> errore pulito;
    tz-aware reso naive; duplicati keep-first; deterministico (61 candidati,
    argmax = prima occorrenza a parita').
    """
    LHV_KWH_KG = 33.33

    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        pot = float(potenza_mw)
    except (TypeError, ValueError):
        return _err("potenza_mw non valida")
    if not (pot > 0):
        return _err("potenza_mw deve essere > 0")
    try:
        capex_kw = float(capex_eur_kw)
    except (TypeError, ValueError):
        return _err("capex_eur_kw non valido")
    if capex_kw < 0:
        return _err("capex_eur_kw non puo' essere negativo")
    try:
        opex_kw = float(opex_eur_kw_anno)
    except (TypeError, ValueError):
        return _err("opex_eur_kw_anno non valido")
    if opex_kw < 0:
        return _err("opex_eur_kw_anno non puo' essere negativo")
    try:
        eff = float(efficienza_pct)
    except (TypeError, ValueError):
        return _err("efficienza_pct non valida")
    if not (0.0 < eff <= 100.0):
        return _err("efficienza_pct deve essere in (0, 100]")
    try:
        ph2 = float(prezzo_h2_eur_kg)
    except (TypeError, ValueError):
        return _err("prezzo_h2_eur_kg non valido")
    if not (ph2 > 0):
        return _err("prezzo_h2_eur_kg deve essere > 0")
    try:
        tasso = float(tasso_pct)
    except (TypeError, ValueError):
        return _err("tasso_pct non valido")
    if tasso < 0:
        return _err("tasso_pct non puo' essere negativo")
    try:
        vita = int(vita_anni)
    except (TypeError, ValueError):
        return _err("vita_anni non valida")
    if vita < 1:
        return _err("vita_anni deve essere >= 1")

    if prezzi is None or len(prezzi) == 0:
        return _err("serie prezzi vuota")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("indice non datetime")
    idxn = prezzi.index.tz_localize(None) if prezzi.index.tz is not None else prezzi.index
    p = pd.to_numeric(prezzi, errors="coerce")
    p.index = idxn
    p = p[~p.index.duplicated(keep="first")].sort_index().dropna()
    if len(p) < 24:
        return _err("serie prezzi troppo corta: servono almeno 24 ore valide")

    n_ore = len(p)
    fattore_annuo = 8760.0 / n_ore
    eff_frac = eff / 100.0
    kg_per_mwh = 1000.0 * eff_frac / LHV_KWH_KG
    p_be = ph2 * kg_per_mwh
    margine_unitario = p_be - p

    soglia_min = min(0.0, float(p.min()))
    candidati = np.linspace(soglia_min, p_be, 61)
    prezzi_np = p.to_numpy()
    margini_lordi = np.array([
        float(np.sum((prezzi_np < thr) * (p_be - prezzi_np))) * pot
        for thr in candidati
    ])
    i_ott = int(np.argmax(margini_lordi))
    soglia_ott = float(candidati[i_ott])

    mask = prezzi_np < soglia_ott
    ore_run = int(mask.sum())
    margine_lordo_oss = float(np.sum(mask * (p_be - prezzi_np))) * pot
    costo_el_oss = float(np.sum(mask * prezzi_np)) * pot
    margine_lordo_annuo = margine_lordo_oss * fattore_annuo
    costo_el_annuo = costo_el_oss * fattore_annuo
    ore_annue = ore_run * fattore_annuo
    energia_annua_mwh = ore_annue * pot
    kg_annui = energia_annua_mwh * kg_per_mwh
    ricavo_annuo = kg_annui * ph2
    capex_tot = capex_kw * pot * 1000.0
    opex_annuo = opex_kw * pot * 1000.0
    margine_netto_annuo = margine_lordo_annuo - opex_annuo

    r = tasso / 100.0
    if r > 0:
        if vita > 0:
            crf = r * (1.0 + r) ** vita / ((1.0 + r) ** vita - 1.0)
            fattore_att = (1.0 - (1.0 + r) ** (-vita)) / r
        else:
            crf = 0.0
            fattore_att = 0.0
    else:
        crf = 1.0 / vita
        fattore_att = float(vita)
    npv = margine_netto_annuo * fattore_att - capex_tot
    lcoh = (crf * capex_tot + opex_annuo + costo_el_annuo) / kg_annui if kg_annui > 0 else None
    payback = capex_tot / margine_netto_annuo if margine_netto_annuo > 0 else None
    fattore_carico = ore_annue / 8760.0 * 100.0
    ore_possibili = int((prezzi_np < p_be).sum())

    tabella_soglie = pd.DataFrame({
        "Soglia (EUR/MWh)": np.round(candidati, 2),
        "Ore/anno": np.round(np.array([int((prezzi_np < thr).sum()) for thr in candidati]) * fattore_annuo, 1),
        "Margine lordo (kEUR/anno)": np.round(margini_lordi * fattore_annuo / 1000.0, 1),
    })

    if margine_netto_annuo <= 0:
        giudizio = "NON CONVIENE"
        nota = ("a %s EUR/kg il margine netto annuo e' %s: l'elettrolizzatore non "
                "si ripaga. Servirebbe un prezzo H2 sopra il LCOH (%.2f EUR/kg) o "
                "un CAPEX piu' basso." % (("%.2f" % ph2),
                                           "%.0f EUR" % margine_netto_annuo,
                                           lcoh if lcoh is not None else float("nan")))
    else:
        giudizio = "CONVIENE"
        nota_pb = ("payback semplice %.1f anni" % payback) if payback is not None else "payback entro la vita utile"
        nota = ("margine netto annuo %s kEUR; %s; NPV %s kEUR a %.1f%% su %d anni. "
                "Il LCOH (%.2f EUR/kg) resta sotto il prezzo di vendita (%.2f EUR/kg): "
                "margine di sicurezza %.1f%%." % (
                    ("%.0f" % (margine_netto_annuo / 1000.0)).replace(",", " "),
                    nota_pb, ("%.0f" % (npv / 1000.0)).replace(",", " "),
                    tasso, vita, lcoh, ph2,
                    (ph2 - lcoh) / ph2 * 100.0))
    verdetto = (
        "Elettrolizzatore da %.1f MW (efficienza %.1f%%): %s. Soglia ottimale "
        "%.2f EUR/MWh contro break-even %.2f EUR/MWh -> %.0f ore/anno (%.1f%% del "
        "tempo), %.0f kg H2/anno. %s Nota: prezzi del periodo ipotizzati ripetuti "
        "ogni anno, nessuna modularita'/minimo tecnico, nessuna valorizzazione "
        "di servizi di rete o certificati GO dell'H2." % (
            pot, eff, giudizio, soglia_ott, p_be, ore_annue, fattore_carico,
            kg_annui, nota))

    return {"errore": None, "valido": True,
            "potenza_mw": pot, "efficienza_pct": eff,
            "kg_per_mwh": kg_per_mwh, "prezzo_be_mwh": p_be,
            "soglia_ottima_mwh": soglia_ott,
            "ore_annue": ore_annue, "ore_possibili": ore_possibili,
            "fattore_carico_pct": fattore_carico,
            "energia_annua_mwh": energia_annua_mwh,
            "kg_annui": kg_annui, "ricavo_annuo_eur": ricavo_annuo,
            "costo_elettricita_annuo_eur": costo_el_annuo,
            "margine_lordo_annuo_eur": margine_lordo_annuo,
            "opex_annuo_eur": opex_annuo,
            "margine_netto_annuo_eur": margine_netto_annuo,
            "capex_eur": capex_tot, "npv_eur": npv,
            "payback_anni": payback, "lcoh_eur_kg": lcoh,
            "crf": crf, "fattore_annuo": fattore_annuo, "n_ore": n_ore,
            "tabella_soglie": tabella_soglie, "verdetto": verdetto}


def calcola_diversita_carico(siti, quota_potenza_eur_kw_anno=60.0, min_ore=24):
    """Fattore di diversita' del carico di un portafoglio multi-sito.

    Domanda operativa: "i picchi dei miei siti coincidono?" — se i siti
    piccano in ore diverse, il picco del PORTAFOGLIO e' minore della somma
    dei picchi individuali: la quota potenza, contrattata sul picco
    coincidente, costa meno che sommare le quote dei singoli siti.

    Fattore di diversita' = somma dei picchi individuali / picco coincidente (>= 1)
    Fattore di coincidenza = 1 / fattore di diversita'

    Input: dict {nome: Series MW} o DataFrame (una colonna per sito).
    NaN-safe: NaN del carico -> 0 (sito fermo in quell'ora), contati;
    tz-aware reso naive; duplicati keep-first; join per intersezione con
    < min_ore ore in comune -> errore pulito; carichi negativi / nomi
    vuoti o duplicati / sito a energia nulla / < 2 siti -> errore pulito.
    Deterministico.
    """

    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        min_ore = int(min_ore)
    except (TypeError, ValueError):
        return _err("min_ore non valido.")
    if min_ore < 2:
        return _err("min_ore deve essere almeno 2.")
    try:
        quota = float(quota_potenza_eur_kw_anno)
    except (TypeError, ValueError):
        return _err("Quota potenza non valida.")
    if not np.isfinite(quota) or quota < 0:
        return _err("Quota potenza non valida.")

    if siti is None:
        return _err("Nessun sito fornito.")
    if isinstance(siti, pd.DataFrame):
        items = [(str(c), siti[c]) for c in siti.columns]
    elif isinstance(siti, dict):
        items = list(siti.items())
    else:
        return _err("Input non valido: serve dict {nome: serie MW} o DataFrame.")
    if len(items) < 2:
        return _err("Servono almeno 2 siti per calcolare la diversita'.")
    nomi = [str(n).strip() for n, _ in items]
    if any(n == "" for n in nomi):
        return _err("Nome sito vuoto non ammesso.")
    if len(set(nomi)) != len(nomi):
        return _err("Nomi sito duplicati.")

    serie, nan_ore = {}, {}
    for (_n_raw, s), nome in zip(items, nomi):
        if not isinstance(s, pd.Series):
            return _err("Sito '%s': serve una Series pandas." % nome)
        try:
            idx = pd.to_datetime(s.index, errors="coerce")
        except Exception:
            return _err("Sito '%s': indice non convertibile a datetime." % nome)
        if idx.isna().all():
            return _err("Sito '%s': indice non datetime." % nome)
        vals = pd.to_numeric(s.values, errors="coerce")
        okm = ~idx.isna()
        idx, vals = idx[okm], vals[okm]
        if len(idx) == 0:
            return _err("Sito '%s': serie vuota." % nome)
        if bool(np.any(vals < 0)):
            return _err("Sito '%s': carichi negativi non ammessi." % nome)
        n_nan = int(np.isnan(vals).sum())
        vals = np.where(np.isnan(vals), 0.0, vals)
        ser = pd.Series(vals, index=idx)
        if ser.index.tz is not None:
            ser.index = ser.index.tz_localize(None)
        ser = ser[~ser.index.duplicated(keep="first")].sort_index()
        serie[nome] = ser
        nan_ore[nome] = n_nan

    comune = serie[nomi[0]].index
    for nome in nomi[1:]:
        comune = comune.intersection(serie[nome].index)
    comune = comune.sort_values()
    if len(comune) < min_ore:
        return _err("Solo %d ore in comune tra i siti (minimo %d)."
                    % (len(comune), min_ore))
    mat = pd.DataFrame({nome: serie[nome].reindex(comune) for nome in nomi})
    n_ore = len(comune)

    energie = mat.sum(axis=0)
    if bool((energie <= 0).any()):
        fermo = str(energie[energie <= 0].index[0])
        return _err("Sito '%s' a energia nulla nel periodo." % fermo)

    picchi = mat.max(axis=0)
    ore_picco_sito = mat.idxmax(axis=0)
    portafoglio = mat.sum(axis=1)
    picco_coinc = float(portafoglio.max())
    ora_picco = portafoglio.idxmax()
    somma_picchi = float(picchi.sum())
    fat_div = somma_picchi / picco_coinc if picco_coinc > 0 else 1.0
    fat_coin = 1.0 / fat_div if fat_div > 0 else 1.0

    carico_ora_picco = mat.loc[ora_picco]
    energia_tot = float(energie.sum())
    righe = []
    for nome in nomi:
        en = float(energie[nome])
        pk = float(picchi[nome])
        righe.append({
            "Sito": nome,
            "Picco individuale (MW)": round(pk, 3),
            "Ora del picco": ore_picco_sito[nome].strftime("%d/%m/%Y %H:%M"),
            "Energia (MWh)": round(en, 1),
            "Fattore di carico (%)": round(en / (pk * n_ore) * 100.0, 1),
            "Carico all'ora di picco (MW)": round(float(carico_ora_picco[nome]), 3),
            "Contributo al picco coincidente (%)":
                round(float(carico_ora_picco[nome]) / picco_coinc * 100.0, 1),
            "Quota energia (%)": round(en / energia_tot * 100.0, 1),
            "Ore con NaN": nan_ore[nome],
        })
    tabella = pd.DataFrame(righe)

    mesi = []
    for periodo, grp in portafoglio.groupby(pd.PeriodIndex(portafoglio.index, freq="M")):
        pv = float(grp.max())
        pk = grp.idxmax()
        sp = float(mat.loc[grp.index].max(axis=0).sum())
        mesi.append({"Mese": str(periodo),
                     "Picco coincidente (MW)": round(pv, 3),
                     "Somma picchi (MW)": round(sp, 3),
                     "Fattore di diversita'": round(sp / pv, 3) if pv > 0 else None,
                     "Ora del picco": pk.strftime("%d/%m/%Y %H:%M")})
    tabella_mensile = pd.DataFrame(mesi)

    kw_risp = (somma_picchi - picco_coinc) * 1000.0
    risparmio = kw_risp * quota

    if fat_div >= 1.25:
        giudizio = "ALTA"
        nota_g = ("diversificazione efficace: i picchi dei siti cadono in ore "
                  "diverse, conviene contrattare la potenza sul portafoglio aggregato.")
    elif fat_div >= 1.10:
        giudizio = "MEDIA"
        nota_g = ("diversificazione parziale: c'e' margine di risparmio sulla "
                  "quota potenza aggregando i siti.")
    else:
        giudizio = "BASSA"
        nota_g = ("i siti piccano quasi insieme: poca differenza tra somma dei "
                  "picchi e picco coincidente, l'aggregazione da' poco beneficio.")

    top = str(tabella.loc[tabella["Contributo al picco coincidente (%)"].idxmax(),
                          "Sito"])
    verdetto = (
        "Portafoglio di %d siti: fattore di diversita' %.3f (%s), picco coincidente "
        "%.2f MW il %s contro somma dei picchi individuali %.2f MW. %s "
        "Risparmio stimato sulla quota potenza: %.0f EUR/anno "
        "(%.0f kW x %.2f EUR/kW/anno). Il sito piu' presente all'ora di picco e' '%s'." % (
            len(nomi), fat_div, giudizio, picco_coinc,
            ora_picco.strftime("%d/%m/%Y %H:%M"), somma_picchi, nota_g,
            risparmio, kw_risp, quota, top))

    return {"errore": None, "valido": True,
            "n_siti": len(nomi), "n_ore": n_ore,
            "picco_coincidente_mw": picco_coinc, "ora_picco": ora_picco,
            "somma_picchi_mw": somma_picchi,
            "fattore_diversita": fat_div, "fattore_coincidenza": fat_coin,
            "kw_risparmiati": kw_risp, "risparmio_eur_anno": risparmio,
            "quota_potenza_eur_kw_anno": quota,
            "serie_portafoglio": portafoglio.rename("Carico portafoglio (MW)"),
            "tabella": tabella, "tabella_mensile": tabella_mensile,
            "giudizio": giudizio, "verdetto": verdetto}


def calcola_dunkelflaute(prezzi, cap_fv_mw=100.0, cap_eolico_mw=100.0,
                         percentile_df=10.0, min_giorni=7):
    """Giorni di dunkelflaute: quando né il sole né il vento producono.

    Domanda operativa: "quanto costano i peggiori giorni rinnovabili?" —
    con alta penetrazione di FV+eolico, i giorni di calma piatta e cielo
    coperto tolgono offerta dal mercato e i prezzi schizzano: questa tab
    quantifica il PREMIO DI SCARSITA' rinnovabile.

    Metodo: i profili sintetici deterministici `profilo_solare` /
    `profilo_eolico` (stessi della tab price capture) generano la
    produzione oraria FV+eolico; fattore rinnovabile giornaliero =
    energia FV+eolico del giorno / (ore_giorno x capacita' totale).
    Giorno di dunkelflaute: fattore sotto il `percentile_df`-esimo
    percentile della distribuzione del periodo (default 10%): e' il
    peggior decile rinnovabile, cioe' lo stress "tipo VaR" del sistema.

    KPI: n giorni DF, quota % sul periodo, prezzo medio nei giorni DF,
    premio DF vs media periodo (EUR/MWh e %), peggior giorno DF,
    fattore rinnovabile medio nei giorni DF; tabella mensile
    (giorni totali, giorni DF, quota %, prezzo DF, prezzo mese, premio);
    giudizio RILEVANTE / MODERATO / LIMITATO sul premio medio;
    verdetto con nota operativa su riserva e coperture invernali.
    E' un'analisi di STRESS su profili sintetici, non una misura: serve a
    dimensionare flessibilita'/riserva, non a prevedere il meteo.

    NaN-safe: serie vuota / indice non datetime / < min_giorni giorni /
    capacita' <= 0 / percentile fuori (0, 50] / min_giorni < 2 -> errore
    pulito; tz-aware reso naive; duplicati keep-first; prezzi NaN
    scartati e contati. Deterministico.
    """

    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        min_giorni = int(min_giorni)
    except (TypeError, ValueError):
        return _err("min_giorni non valido.")
    if min_giorni < 2:
        return _err("min_giorni deve essere almeno 2.")
    try:
        cap_fv = float(cap_fv_mw)
        cap_eo = float(cap_eolico_mw)
        perc = float(percentile_df)
    except (TypeError, ValueError):
        return _err("Capacita' o percentile non validi.")
    for v in (cap_fv, cap_eo):
        if not np.isfinite(v) or v <= 0:
            return _err("Le capacita' FV ed eolico devono essere > 0.")
    if not np.isfinite(perc) or not (0.0 < perc <= 50.0):
        return _err("Il percentile deve essere tra 0 e 50.")
    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series di prezzi orari.")
    try:
        idx = pd.to_datetime(prezzi.index, errors="coerce")
    except Exception:
        return _err("Indice non convertibile a datetime.")
    if idx.isna().all():
        return _err("Indice non datetime.")
    vals = pd.to_numeric(prezzi.values, errors="coerce")
    okm = ~idx.isna()
    idx, vals = idx[okm], vals[okm]
    if len(idx) == 0:
        return _err("Serie prezzi vuota.")
    n_nan = int(np.isnan(vals).sum())
    dfp = pd.DataFrame({"prezzo": vals}, index=idx).dropna(subset=["prezzo"])
    if dfp.index.tz is not None:
        dfp.index = dfp.index.tz_localize(None)
    dfp = dfp[~dfp.index.duplicated(keep="first")].sort_index()
    if len(dfp) == 0:
        return _err("Serie prezzi vuota dopo la pulizia dei NaN.")

    cap_tot = cap_fv + cap_eo
    gen_fv = profilo_solare(dfp["prezzo"], cap_fv)
    gen_eo = profilo_eolico(dfp["prezzo"], cap_eo)
    if len(gen_fv) == 0 or len(gen_eo) == 0:
        return _err("Profili di generazione non generati.")
    gen = (pd.to_numeric(gen_fv, errors="coerce").fillna(0.0)
           + pd.to_numeric(gen_eo, errors="coerce").fillna(0.0))
    gen = gen.reindex(dfp.index).fillna(0.0)

    giorni = dfp.index.floor("D")
    n_ore_g = giorni.value_counts().sort_index()
    en_g = gen.groupby(giorni).sum()
    p_g = dfp["prezzo"].groupby(giorni).mean()
    fattore = en_g / (n_ore_g.reindex(en_g.index) * cap_tot)
    if len(p_g) < min_giorni:
        return _err("Servono almeno %d giorni di dati (trovati %d)."
                    % (min_giorni, len(p_g)))

    lim = float(np.percentile(fattore.values, perc))
    is_df = fattore <= lim
    n_df = int(is_df.sum())
    n_gg = len(p_g)
    quota = n_df / n_gg * 100.0 if n_gg else 0.0
    p_medio = float(p_g.mean())
    fattore_medio_df = float(fattore[is_df].mean()) if n_df else 0.0
    if n_df:
        p_df = float(p_g[is_df].mean())
        premio = p_df - p_medio
        premio_pct = premio / p_medio * 100.0 if p_medio != 0 else None
        peggior_g = p_g[is_df].idxmax()
        peggior_p = float(p_g[is_df].max())
    else:
        p_df, premio, premio_pct, peggior_g, peggior_p = None, None, None, None, None

    if n_df == 0:
        giudizio = "NESSUN GIORNO"
        nota_g = ("nessun giorno sotto il percentile scelto: aumenta il "
                  "percentile per allargare lo stress.")
    elif premio >= 15.0:
        giudizio = "RILEVANTE"
        nota_g = ("i peggiori giorni rinnovabili costano in media almeno "
                  "15 €/MWh piu' della media: il rischio scarsita' rinnovabile "
                  "e' materiale, servono riserva o coperture invernali.")
    elif premio >= 5.0:
        giudizio = "MODERATO"
        nota_g = ("premio di scarsita' contenuto ma visibile: i giorni di "
                  "dunkelflaute costano di piu', da monitorare nei mesi "
                  "invernali.")
    else:
        giudizio = "LIMITATO"
        nota_g = ("premio di scarsita' piccolo o nullo nel periodo: la "
                  "dunkelflaute c'e' ma il mercato non la prezza (o i prezzi "
                  "dei giorni DF sono addirittura piu' bassi).")

    mesi = []
    for periodo, grp in p_g.groupby(pd.PeriodIndex(p_g.index, freq="M")):
        gdf = is_df.loc[grp.index]
        nd = int(gdf.sum())
        pm = float(grp.mean())
        pdf = float(grp[gdf].mean()) if nd else None
        mesi.append({
            "Mese": str(periodo),
            "Giorni totali": len(grp),
            "Giorni dunkelflaute": nd,
            "Quota DF (%)": round(nd / len(grp) * 100.0, 1),
            "Prezzo medio DF (€/MWh)": round(pdf, 2) if pdf is not None else None,
            "Prezzo medio mese (€/MWh)": round(pm, 2),
            "Premio DF (€/MWh)": round(pdf - pm, 2) if pdf is not None else None,
        })
    tabella_mensile = pd.DataFrame(mesi)

    serie_fattore = fattore.rename("Fattore rinnovabile giornaliero")
    serie_prezzo_g = p_g.rename("Prezzo medio giornaliero (€/MWh)")

    if n_df:
        verdetto = (
            "%d giorni di dunkelflaute su %d (%.1f %%, peggior %s-esimo "
            "percentile del fattore rinnovabile). Prezzo medio nei giorni DF: "
            "%.2f €/MWh contro %.2f €/MWh di media periodo: premio di "
            "scarsita' %+.2f €/MWh%s. Fattore rinnovabile medio nei giorni "
            "DF: %.1f %%. Peggior giorno: %s a %.2f €/MWh. %s" % (
                n_df, n_gg, quota, ("%g" % perc), p_df, p_medio, premio,
                (" (%+.1f %%)" % premio_pct) if premio_pct is not None else "",
                fattore_medio_df * 100.0,
                peggior_g.strftime("%d/%m/%Y"), peggior_p, nota_g))
    else:
        verdetto = ("%d giorni di dati, nessun giorno di dunkelflaute al "
                    "percentile scelto. %s" % (n_gg, nota_g))

    return {"errore": None, "valido": True,
            "n_giorni": n_gg, "n_df": n_df, "quota_df_pct": quota,
            "percentile_df": perc, "limite_fattore": lim,
            "cap_fv_mw": cap_fv, "cap_eolico_mw": cap_eo,
            "cap_tot_mw": cap_tot, "n_nan_prezzi": n_nan,
            "prezzo_medio": p_medio, "prezzo_medio_df": p_df,
            "premio_eur_mwh": premio, "premio_pct": premio_pct,
            "fattore_medio_df": fattore_medio_df,
            "peggior_giorno": peggior_g, "peggior_prezzo": peggior_p,
            "serie_fattore": serie_fattore, "serie_prezzo_g": serie_prezzo_g,
            "giorni_df": p_g[is_df].index,
            "tabella_mensile": tabella_mensile,
            "giudizio": giudizio, "verdetto": verdetto}


def calcola_test_stazionarieta(prezzi, regression="c", lags="auto", max_lags=None):
    """Test ADF (Augmented Dickey-Fuller) di radice unitaria sulla serie prezzi.

    H0: la serie ha una radice unitaria (non stazionaria, es. random walk).
    Dalla regressione OLS
        Δy_t = det_t + gamma*y_{t-1} + Σ_{i=1..p} delta_i*Δy_{t-i} + e_t
    con det_t = {niente | costante | costante+trend} secondo `regression`,
    la statistica test e' t = gamma/se(gamma). H0 si rifiuta quando la
    statistica e' PIU' NEGATIVA del valore critico (valori critici asintotici
    di MacKinnon): la serie e' stazionaria.

    Implementazione propria con OLS numpy (niente statsmodels): selezione dei
    lag con AIC su campione troncato comune (pmax da regola di Schwert),
    test ripetuto sulla differenza prima per l'ordine di integrazione
    (I(0)/I(1)/I(2+)) e verdetto ADF mese per mese (finestre con >=168 ore).

    Parametri: regression in {"n","c","ct"}; lags "auto" o intero >= 0;
    max_lags tetto opzionale ai lag automatici.
    Ritorna dict con "valido"/"errore"; mai eccezioni su input strani.
    """
    _CV = {
        "n": {1: -2.566, 5: -1.941, 10: -1.617},
        "c": {1: -3.430, 5: -2.862, 10: -2.567},
        "ct": {1: -3.959, 5: -3.410, 10: -3.127},
    }
    _LAB = {"n": "nessun termine deterministico", "c": "costante",
            "ct": "costante + trend"}

    def _err(msg):
        return {"valido": False, "errore": msg}

    if regression not in _CV:
        return _err("regression deve essere 'n', 'c' o 'ct'.")

    lag_fisso = None
    if isinstance(lags, str):
        if lags != "auto":
            return _err("lags deve essere 'auto' o un intero >= 0.")
    else:
        try:
            lag_fisso = int(lags)
        except (TypeError, ValueError):
            return _err("lags deve essere 'auto' o un intero >= 0.")
        if lag_fisso < 0:
            return _err("lags deve essere 'auto' o un intero >= 0.")

    ml_cap = None
    if max_lags is not None:
        try:
            ml_cap = int(max_lags)
        except (TypeError, ValueError):
            return _err("max_lags deve essere un intero >= 0 o None.")
        if ml_cap < 0:
            return _err("max_lags deve essere un intero >= 0 o None.")

    try:
        s = pd.Series(prezzi)
    except (TypeError, ValueError):
        return _err("La serie prezzi non e' leggibile come Series.")
    s = pd.to_numeric(s, errors="coerce").dropna()
    if len(s) < 30:
        return _err("Servono almeno 30 osservazioni valide per il test ADF "
                    f"(trovate {len(s)}).")
    idx = s.index
    is_dt = isinstance(idx, pd.DatetimeIndex)
    if is_dt:
        try:
            idx = idx.tz_localize(None)
        except (TypeError, AttributeError, ValueError):
            pass
        s = pd.Series(s.to_numpy(), index=idx)
    y = s.to_numpy(dtype=float)
    if not np.all(np.isfinite(y)):
        return _err("La serie contiene valori non finiti.")
    T = len(y)
    n_det = 0 if regression == "n" else (1 if regression == "c" else 2)
    y_costante = bool(np.all(y == y[0]))

    def _pmax(Tv):
        pm = int(12.0 * (Tv / 100.0) ** 0.25)
        pm = max(0, min(pm, (Tv - n_det - 10) // 2))
        if ml_cap is not None:
            pm = max(0, min(pm, ml_cap))
        return pm

    def _fit(yv, reg, p, n_use=None):
        """OLS della regressione ADF con p lag; None se non stimabile."""
        Tv = len(yv)
        n = Tv - 1 - p
        if n <= 0:
            return None
        dy = np.diff(yv)
        yl = yv[:-1]
        cols = []
        if reg in ("c", "ct"):
            cols.append(np.ones(n))
        if reg == "ct":
            cols.append(np.arange(1, n + 1, dtype=float))
        i_gamma = len(cols)
        cols.append(yl[p:])
        for i in range(1, p + 1):
            cols.append(dy[p - i: Tv - 1 - i])
        Y = dy[p:]
        X = np.column_stack(cols)
        if n_use is not None:
            n_use = min(n_use, n)
            Y = Y[-n_use:]
            X = X[-n_use:, :]
            n = n_use
        k = X.shape[1]
        if n <= k + 1:
            return None
        beta, _r, _rk, _sv = np.linalg.lstsq(X, Y, rcond=None)
        resid = Y - X @ beta
        dof = n - k
        if dof <= 0:
            return None
        rss = float(resid @ resid)
        if not np.isfinite(rss):
            return None
        gamma = float(beta[i_gamma])
        yss = float(Y @ Y)
        if rss == 0.0 or (yss > 0.0 and rss <= 1e-24 * yss):
            # fit (quasi) perfetto: serie deterministica senza rumore
            stat = -np.inf if gamma < 0 else (np.inf if gamma > 0 else 0.0)
            return {"stat": stat, "gamma": gamma, "n": n, "k": k,
                    "rss": 0.0, "p": p, "perfetto": True}
        s2 = rss / dof
        try:
            xtx_inv = np.linalg.pinv(X.T @ X)
        except np.linalg.LinAlgError:
            return None
        v = float(xtx_inv[i_gamma, i_gamma])
        if not np.isfinite(v) or v <= 0:
            return None
        stat = gamma / np.sqrt(s2 * v)
        if not np.isfinite(stat):
            return None
        return {"stat": float(stat), "gamma": gamma, "n": n, "k": k,
                "rss": rss, "p": p, "perfetto": False}

    def _seleziona(yv, reg):
        """Sceglie i lag con AIC su campione troncato comune."""
        pm = _pmax(len(yv))
        n0 = len(yv) - 1 - pm
        if n0 <= n_det + 2:
            return None
        best = None
        perfetto = None
        for p in range(pm + 1):
            f = _fit(yv, reg, p, n_use=n0)
            if f is None:
                continue
            if f["perfetto"]:
                # serie deterministica senza rumore: niente AIC da calcolare
                if perfetto is None:
                    perfetto = f
                if f["stat"] == -np.inf:
                    return f  # mean reversion perfetta: non c'e' di meglio
                continue
            aic = n0 * np.log(f["rss"] / n0) + 2.0 * f["k"]
            if best is None or aic < best[0]:
                best = (aic, f)
        if best is not None:
            return best[1]
        return perfetto  # solo fit perfetti non mean-reverting (es. esplosiva)

    def _verdetto(stat, cv):
        return {"rifiuta_1": bool(stat < cv[1]),
                "rifiuta_5": bool(stat < cv[5]),
                "rifiuta_10": bool(stat < cv[10])}

    cv = _CV[regression]
    if y_costante:
        fit = {"stat": -np.inf, "gamma": np.nan, "n": T - 1,
               "k": n_det + 1, "rss": 0.0, "p": 0}
        fit_d = dict(fit)
        p_usato = 0
    else:
        if lag_fisso is None:
            fit = _seleziona(y, regression)
            if fit is None:
                return _err("Regressione ADF non stimabile su questa serie.")
            p_usato = fit["p"]
        else:
            fit = _fit(y, regression, lag_fisso)
            if fit is None:
                return _err(f"lag={lag_fisso} non stimabile con {T} osservazioni.")
            p_usato = lag_fisso
        yd = np.diff(y)
        fit_d = _seleziona(yd, regression) if len(yd) >= 30 else None

    stat = float(fit["stat"])
    v = _verdetto(stat, cv)
    verdetto = "STAZIONARIA" if v["rifiuta_5"] else "RADICE UNITARIA"

    stat_diff, rifiuta_diff_5 = None, None
    if fit_d is not None:
        stat_diff = float(fit_d["stat"])
        rifiuta_diff_5 = _verdetto(stat_diff, cv)["rifiuta_5"]
    if v["rifiuta_5"]:
        ordine = "I(0)"
    elif rifiuta_diff_5 is True:
        ordine = "I(1)"
    elif rifiuta_diff_5 is False:
        ordine = "I(2+)"
    else:
        ordine = "I(1)? (differenze non testate)"

    righe = []
    if is_dt:
        try:
            mesi = s.index.to_period("M")
        except (TypeError, ValueError, AttributeError):
            mesi = None
        if mesi is not None:
            for per, grp in s.groupby(mesi):
                gv = grp.to_numpy(dtype=float)
                if len(gv) < 168 or not np.all(np.isfinite(gv)):
                    continue
                if np.all(gv == gv[0]):
                    righe.append({"Mese": str(per), "Ore": len(gv),
                                  "Statistica": -np.inf,
                                  "Verdetto": "STAZIONARIA"})
                    continue
                fm = _seleziona(gv, regression)
                if fm is None:
                    righe.append({"Mese": str(per), "Ore": len(gv),
                                  "Statistica": np.nan, "Verdetto": "n.d."})
                else:
                    vm = _verdetto(float(fm["stat"]), cv)
                    righe.append({
                        "Mese": str(per), "Ore": len(gv),
                        "Statistica": float(fm["stat"]),
                        "Verdetto": ("STAZIONARIA" if vm["rifiuta_5"]
                                     else "RADICE UNITARIA")})
    df_roll = pd.DataFrame(righe,
                           columns=["Mese", "Ore", "Statistica", "Verdetto"])
    ok_roll = df_roll[df_roll["Verdetto"].isin(["STAZIONARIA",
                                                "RADICE UNITARIA"])]
    quota_mesi = (float((ok_roll["Verdetto"] == "STAZIONARIA").mean())
                  if len(ok_roll) else None)

    if v["rifiuta_5"]:
        giudizio = ("La serie dei prezzi e' STAZIONARIA (rifiuto di H0 al 5%): "
                    "media e varianza stabili nel tempo, gli shock rientrano. "
                    "Ha senso parlare di prezzo medio, bande e mean reversion "
                    "sui livelli.")
    elif rifiuta_diff_5:
        giudizio = ("La serie ha una RADICE UNITARIA in livelli ma la differenza "
                    "prima e' stazionaria: il prezzo e' I(1). Lavora sulle "
                    "VARIAZIONI, non sui livelli: medie e bande calcolate sui "
                    "livelli non sono affidabili.")
    else:
        giudizio = ("La serie NON e' stazionaria nemmeno alle differenze prime: "
                    "processo oltre I(1) o break strutturali. Verifica la qualita' "
                    "dei dati e valuta finestre piu' corte o la rimozione del trend.")

    return {
        "valido": True, "errore": None,
        "regression": regression, "regression_label": _LAB[regression],
        "n_obs": T, "lags": p_usato, "lags_auto": lag_fisso is None,
        "stat": stat, "cv": dict(cv),
        "rifiuta_1": v["rifiuta_1"], "rifiuta_5": v["rifiuta_5"],
        "rifiuta_10": v["rifiuta_10"],
        "verdetto": verdetto, "serie_costante": y_costante,
        "stat_diff": stat_diff, "rifiuta_diff_5": rifiuta_diff_5,
        "ordine_integrazione": ordine,
        "rolling": df_roll, "quota_mesi_stazionari": quota_mesi,
        "giudizio": giudizio,
    }


def calcola_cointegrazione(prezzi_giorno, gas_giorno, regression="c", lags="auto",
                           min_giorni=90):
    """Test di cointegrazione Engle-Granger (due passi) tra spot elettrico e gas TTF.

    Domanda operativa: la beta gas-power (tab140) e' un hedge statico difendibile
    nel lungo periodo, o una regressione spuria? Due serie I(1) sono cointegrate
    quando una loro combinazione lineare (P - a - b*G) e' STAZIONARIA: il prezzo
    elettrico torna verso l'equilibrio di lungo periodo fissato dal gas.

    Passo 1 - regressione di cointegrazione OLS sui livelli:
        P_t = a + b*G_t  (+ trend lineare se regression="ct")
        b e' l'hedge ratio gas-to-power di lungo periodo.
    Passo 2 - test ADF sui residui u_t con valori critici di Engle-Granger
    (piu' severi dei MacKinnon puri perche' i residui sono stimati, valori
    asintotici standard per 1 regressore):
        "n":  1% -2.57 / 5% -1.94 / 10% -1.62
        "c":  1% -3.90 / 5% -3.34 / 10% -3.04
        "ct": 1% -4.32 / 5% -3.78 / 10% -3.50
    H0: i residui hanno radice unitaria (NESSUNA cointegrazione). Si rifiuta
    quando la statistica e' PIU' NEGATIVA del critico.

    Dal gamma della regressione ADF sui residui si ricava l'half-life del
    rientro verso l'equilibrio: HL = -ln(2)/ln(1+gamma) giorni (solo se gamma<0).

    Input: serie GIORNALIERE (la tab costruisce base/peak dalla serie oraria).
    NaN-safe: serie vuote / indici non datetime / giorni comuni < min_giorni /
    gas costante / regression o lag non validi -> errore pulito; tz-aware reso
    naive; duplicati keep-first; residui di scala trascurabile (std <= 1e-9
    della scala dei prezzi) trattati come costanti = cointegrazione perfetta;
    deterministico. Mai eccezioni.

    Ritorna dict con "valido"/"errore"; "alpha", "beta" (hedge ratio),
    "r2", "correlazione"; "stat", "cv", "rifiuta_1/5/10", "cointegrata" (bool
    al 5%), "lags", "lags_auto"; "half_life_giorni" (None se non stimabile),
    "z_score" e "spread_eur" dell'ultimo giorno (scostamento dall'equilibrio),
    "n_giorni", "n_scartate", "gas_medio", "power_medio", "std_residui";
    "df_mesi" (Mese, Giorni, Residuo medio, Z-score medio); "df_serie"
    (Giorno, Gas, Power, Residuo, Z-score); "giudizio".
    """
    _EG_CV = {"n": {1: -2.57, 5: -1.94, 10: -1.62},
              "c": {1: -3.90, 5: -3.34, 10: -3.04},
              "ct": {1: -4.32, 5: -3.78, 10: -3.50}}
    col_mesi = ["Mese", "Giorni", "Residuo medio (€/MWh)", "Z-score medio"]
    col_serie = ["Giorno", "Gas (€/MWh)", "Power (€/MWh)", "Residuo (€/MWh)",
                 "Z-score"]
    vuoto = {"valido": False, "errore": None, "alpha": None, "beta": None,
             "r2": None, "correlazione": None, "stat": None, "cv": None,
             "rifiuta_1": None, "rifiuta_5": None, "rifiuta_10": None,
             "cointegrata": None, "lags": None, "lags_auto": None,
             "half_life_giorni": None, "z_score": None, "spread_eur": None,
             "n_giorni": 0, "n_scartate": 0, "gas_medio": None,
             "power_medio": None, "std_residui": None,
             "df_mesi": pd.DataFrame(columns=col_mesi),
             "df_serie": pd.DataFrame(columns=col_serie), "giudizio": ""}

    def _err(msg):
        out = dict(vuoto)
        out["df_mesi"] = pd.DataFrame(columns=col_mesi)
        out["df_serie"] = pd.DataFrame(columns=col_serie)
        out["errore"] = msg
        return out

    if regression not in _EG_CV:
        return _err("regression non valida: 'n', 'c' o 'ct'.")
    if lags != "auto":
        try:
            lags = int(lags)
        except (TypeError, ValueError):
            return _err("lags non valido: 'auto' o intero >= 0.")
        if lags < 0:
            return _err("lags non valido: 'auto' o intero >= 0.")
    try:
        min_giorni = int(min_giorni)
    except (TypeError, ValueError):
        return _err("min_giorni non valido: intero >= 30.")
    if min_giorni < 30:
        return _err("min_giorni non valido: intero >= 30.")
    if prezzi_giorno is None or gas_giorno is None:
        return _err("Serie prezzi o gas mancante.")
    try:
        p = pd.Series(prezzi_giorno)
        g = pd.Series(gas_giorno)
    except Exception:
        return _err("Input non interpretabili come serie.")
    if (not isinstance(p.index, pd.DatetimeIndex)
            or not isinstance(g.index, pd.DatetimeIndex)):
        return _err("Gli indici di entrambe le serie devono essere di tipo data/ora.")
    pv = pd.to_numeric(p.values, errors="coerce")
    gv = pd.to_numeric(g.values, errors="coerce")
    if np.isnan(pv).all():
        return _err("Nessun valore numerico nella serie elettrica.")
    if np.isnan(gv).all():
        return _err("Nessun valore numerico nella serie gas.")
    ip = p.index.tz_localize(None) if p.index.tz is not None else p.index
    ig = g.index.tz_localize(None) if g.index.tz is not None else g.index
    s_p = pd.Series(pv, index=ip).dropna()
    s_g = pd.Series(gv, index=ig).dropna()
    s_p = s_p[~s_p.index.duplicated(keep="first")]
    s_g = s_g[~s_g.index.duplicated(keep="first")]
    df = pd.DataFrame({"gas": s_g.groupby(s_g.index.normalize()).mean(),
                       "power": s_p.groupby(s_p.index.normalize()).mean()})
    n_scartate = int(df[["gas", "power"]].isna().any(axis=1).sum())
    df = df.dropna()
    if len(df) < min_giorni:
        return _err(f"Dati insufficienti: {len(df)} giorni comuni, "
                    f"servono almeno {min_giorni}.")
    x = df["gas"].to_numpy()
    y = df["power"].to_numpy()
    if float(np.var(x)) <= 0:
        return _err("Prezzo gas costante sul periodo: regressione impossibile.")

    # Passo 1: regressione di cointegrazione OLS  y = a + b*x (+ trend)
    cols = []
    if regression in ("c", "ct"):
        cols.append(np.ones(len(x)))
    if regression == "ct":
        cols.append(np.arange(1, len(x) + 1, dtype=float))
    cols.append(x)
    X = np.column_stack(cols)
    try:
        coef, _r, _rk, _sv = np.linalg.lstsq(X, y, rcond=None)
    except np.linalg.LinAlgError:
        return _err("Regressione di cointegrazione non stimabile.")
    i_beta = len(cols) - 1
    beta = float(coef[i_beta])
    alpha = float(coef[0]) if regression in ("c", "ct") else 0.0
    u = y - X @ coef
    ss_res = float(u @ u)
    ss_tot = float(((y - y.mean()) ** 2).sum())
    r2 = (1.0 - ss_res / ss_tot) if ss_tot > 0 else None
    corr = float(np.corrcoef(x, y)[0, 1]) if len(x) > 1 else None
    u_const = bool(np.all(u == u[0]))
    std_u = float(np.std(u, ddof=1)) if len(u) > 1 else 0.0
    # residui di scala trascurabile rispetto al prezzo = zeri numerici
    # (relazione deterministica): trattati come costanti
    scala_prezzo = max(1.0, float(np.std(y)))
    u_eff_const = u_const or (std_u <= 1e-9 * scala_prezzo)

    # Passo 2: ADF sui residui (stessa meccanica della tab171, CV Engle-Granger)
    n_det_adf = 0 if regression == "n" else (1 if regression == "c" else 2)

    def _pmax(Tv):
        pm = int(12.0 * (Tv / 100.0) ** 0.25)
        pm = max(0, min(pm, (Tv - n_det_adf - 10) // 2))
        return pm

    def _fit(yv, reg, pl, n_use=None):
        Tv = len(yv)
        n = Tv - 1 - pl
        if n <= 0:
            return None
        dy = np.diff(yv)
        yl = yv[:-1]
        c2 = []
        if reg in ("c", "ct"):
            c2.append(np.ones(n))
        if reg == "ct":
            c2.append(np.arange(1, n + 1, dtype=float))
        i_g = len(c2)
        c2.append(yl[pl:])
        for i in range(1, pl + 1):
            c2.append(dy[pl - i: Tv - 1 - i])
        Y = dy[pl:]
        XX = np.column_stack(c2)
        if n_use is not None:
            n_use = min(n_use, n)
            Y = Y[-n_use:]
            XX = XX[-n_use:, :]
            n = n_use
        k = XX.shape[1]
        if n <= k + 1:
            return None
        bq, _r, _rk, _sv = np.linalg.lstsq(XX, Y, rcond=None)
        res = Y - XX @ bq
        dof = n - k
        if dof <= 0:
            return None
        rss = float(res @ res)
        if not np.isfinite(rss):
            return None
        gamma = float(bq[i_g])
        yss = float(Y @ Y)
        if rss == 0.0 or (yss > 0.0 and rss <= 1e-24 * yss):
            stat = (-np.inf if gamma < 0
                    else (np.inf if gamma > 0 else 0.0))
            return {"stat": stat, "gamma": gamma, "p": pl, "perfetto": True}
        s2 = rss / dof
        try:
            xtxi = np.linalg.pinv(XX.T @ XX)
        except np.linalg.LinAlgError:
            return None
        v = float(xtxi[i_g, i_g])
        if not np.isfinite(v) or v <= 0:
            return None
        stat = gamma / np.sqrt(s2 * v)
        if not np.isfinite(stat):
            return None
        return {"stat": float(stat), "gamma": gamma, "p": pl, "rss": rss,
                "k": k, "perfetto": False}

    def _seleziona(yv, reg):
        pm = _pmax(len(yv))
        n0 = len(yv) - 1 - pm
        if n0 <= n_det_adf + 2:
            return None
        best, perf = None, None
        for pl in range(pm + 1):
            f = _fit(yv, reg, pl, n_use=n0)
            if f is None:
                continue
            if f["perfetto"]:
                if perf is None:
                    perf = f
                if f["stat"] == -np.inf:
                    return f
                continue
            aic = n0 * np.log(f["rss"] / n0) + 2.0 * f["k"]
            if best is None or aic < best[0]:
                best = (aic, f)
        return best[1] if best is not None else perf

    lag_fisso = None if lags == "auto" else lags
    cv = _EG_CV[regression]
    if u_eff_const:
        fit = {"stat": -np.inf, "gamma": np.nan, "p": 0}
        p_usato = 0
    else:
        if lag_fisso is None:
            fit = _seleziona(u, regression)
            if fit is None:
                return _err("Regressione ADF sui residui non stimabile.")
            p_usato = fit["p"]
        else:
            fit = _fit(u, regression, lag_fisso)
            if fit is None:
                return _err(f"lag={lag_fisso} non stimabile con "
                            f"{len(u)} osservazioni.")
            p_usato = lag_fisso
    stat = float(fit["stat"])
    rifiuta = {q: bool(stat < cv[q]) for q in (1, 5, 10)}
    cointegrata = rifiuta[5]

    gamma = fit.get("gamma", np.nan)
    half_life = None
    try:
        if np.isfinite(gamma) and -1.0 < gamma < 0.0:
            den = np.log(1.0 + gamma)
            if np.isfinite(den) and den < 0:
                half_life = float(-np.log(2.0) / den)
    except (ValueError, ZeroDivisionError):
        half_life = None

    z = ((float(u[-1]) - float(u.mean())) / std_u) if std_u > 0 else None
    spread = float(u[-1])

    righe = []
    try:
        mesi = df.index.to_period("M")
    except (TypeError, ValueError, AttributeError):
        mesi = None
    if mesi is not None:
        for per, grp in df.groupby(mesi):
            idxm = grp.index
            um = u[df.index.get_indexer(idxm)]
            zm = ((um - float(u.mean())) / std_u) if std_u > 0 else np.full(len(um), np.nan)
            righe.append({"Mese": str(per), "Giorni": len(grp),
                          "Residuo medio (€/MWh)": round(float(np.mean(um)), 2),
                          "Z-score medio": (round(float(np.mean(zm)), 2)
                                            if np.all(np.isfinite(zm)) else None)})
    df_mesi = pd.DataFrame(righe, columns=col_mesi)

    df_serie = pd.DataFrame({
        "Giorno": df.index.date,
        "Gas (€/MWh)": np.round(x, 2),
        "Power (€/MWh)": np.round(y, 2),
        "Residuo (€/MWh)": np.round(u, 2),
        "Z-score": (np.round((u - float(u.mean())) / std_u, 2)
                    if std_u > 0 else np.full(len(u), np.nan))})

    if cointegrata:
        giudizio = (f"Serie COINTEGRATE al 5% (stat {stat:.2f} < critico "
                    f"{cv[5]:.2f}): la beta {beta:.2f} e' un hedge ratio di lungo "
                    f"periodo difendibile — {beta:.2f} MW di TTF coprono ~1 MW "
                    f"elettrico. ")
        if half_life is not None:
            giudizio += (f"Gli scostamenti dall'equilibrio rientrano con "
                         f"half-life di ~{half_life:.0f} giorni. ")
        if z is not None and abs(z) >= 2:
            giudizio += (f"Attenzione: lo spread e' a {abs(z):.1f} sigma "
                         f"dall'equilibrio ({spread:+.2f} €/MWh) — dislocazione "
                         f"anomala da monitorare.")
        else:
            giudizio += "Lo spread e' vicino all'equilibrio di lungo periodo."
    else:
        giudizio = (f"NESSUNA cointegrazione al 5% (stat {stat:.2f} >= critico "
                    f"{cv[5]:.2f}): la beta {beta:.2f} e' una regressione "
                    f"SPURIA sul lungo periodo. Non usare l'hedge statico "
                    f"gas-to-power come copertura strutturale: ricalibra spesso "
                    f"(beta rolling, tab140) o copri con prodotti power.")

    return {"valido": True, "errore": None, "alpha": round(alpha, 4),
            "beta": round(beta, 4), "r2": (round(float(r2), 4)
                                           if r2 is not None else None),
            "correlazione": (round(float(corr), 4)
                             if corr is not None else None),
            "stat": stat, "cv": dict(cv),
            "rifiuta_1": rifiuta[1], "rifiuta_5": rifiuta[5],
            "rifiuta_10": rifiuta[10], "cointegrata": cointegrata,
            "lags": p_usato, "lags_auto": lag_fisso is None,
            "half_life_giorni": (round(float(half_life), 1)
                                 if half_life is not None else None),
            "z_score": (round(float(z), 2) if z is not None else None),
            "spread_eur": round(spread, 2), "n_giorni": len(df),
            "n_scartate": n_scartate, "gas_medio": round(float(x.mean()), 2),
            "power_medio": round(float(y.mean()), 2),
            "std_residui": round(std_u, 2), "df_mesi": df_mesi,
            "df_serie": df_serie, "giudizio": giudizio}

def calcola_causalita_granger(prezzi_giorno, gas_giorno, lags="auto",
                              differenzia=True, min_giorni=60):
    """Test di causalita' di Granger gas <-> power su serie giornaliere.

    Domanda operativa: il gas TTF ANTICIPA davvero il prezzo elettrico, o le
    due serie si muovono insieme senza un verso? La causalita' di Granger non
    e' causalita' economica: X "Granger-causa" Y quando i lag di X migliorano
    la previsione di Y oltre i soli lag di Y. Per un energy analyst e' il test
    che dice se il TTF e' un driver anticipatore difendibile nei modelli di
    prezzo e negli hedge (a valle di beta gas-power tab140 e cointegrazione
    tab172: la cointegrazione dice "tornano insieme nel lungo periodo", qui si
    chiede "chi muove chi nel breve").

    VAR(p) bivariato su [power, gas] con costante, stimato per direzione:
        P_t = c + sum a_i*P_{t-i} + sum b_i*G_{t-i} + e_t   (non ristretta)
        P_t = c + sum a_i*P_{t-i} + e_t                     (ristretta)
    H0 "il gas NON Granger-causa il power": b_1 = ... = b_p = 0.
    Statistica F = ((RSS_r - RSS_u)/p) / (RSS_u/(n-2p-1)) con p-value dalla
    F(p, n-2p-1); H0 si rifiuta a p-value < 5%. Stesso test nella direzione
    opposta (power -> gas) per rilevare il feedback.

    Selezione lag: BIC sull'equazione non ristretta del power, p = 1..pmax
    con pmax = min(12, (T-2)//3) cosi' i gdl residui restano positivi; fit
    perfetti (RSS ~ 0) danno F = +inf e p-value 0. Su serie I(1) e' buona
    pratica testare sulle DIFFERENZE PRIME (differenzia=True, default): sui
    livelli due trend comuni possono dare causalita' spuria (vedi tab171).

    Input: serie GIORNALIERE (la tab costruisce base/peak dalla serie oraria).
    NaN-safe: serie vuote / indici non datetime / giorni comuni < min_giorni /
    serie costanti / lags o min_giorni non validi -> errore pulito; tz-aware
    reso naive; duplicati keep-first; NaN scartati e contati; deterministico.
    Mai eccezioni.

    Ritorna dict con "valido"/"errore"; "lags", "lags_auto"; "f_gp"/"pval_gp"
    (gas->power) e "f_pg"/"pval_pg" (power->gas), "crit_5" (uguale per le due
    direzioni: stessi lag e gdl), "sig_gp"/"sig_pg" (bool al 5%); "verdetto"
    in {"GAS->POWER", "POWER->GAS", "FEEDBACK", "NESSUNA"}; "r2_u"/"r2_r"
    (equazione power); "n_giorni", "n_scartate"; "df_dettaglio" (Direzione, F,
    p-value, Lag, Gdl residui, Critica 5%, Significativa (5%)); "df_coef"
    (Direzione, Lag, Coeff. propri, Coeff. incrociati); "giudizio".
    """
    from scipy.stats import f as _fdist
    col_det = ["Direzione", "F", "p-value", "Lag", "Gdl residui",
               "Critica 5%", "Significativa (5%)"]
    col_coef = ["Direzione", "Lag", "Coeff. propri", "Coeff. incrociati"]
    vuoto = {"valido": False, "errore": None, "lags": None, "lags_auto": None,
             "f_gp": None, "pval_gp": None, "f_pg": None, "pval_pg": None,
             "crit_5": None, "sig_gp": None, "sig_pg": None, "verdetto": None,
             "r2_u": None, "r2_r": None, "n_giorni": 0, "n_scartate": 0,
             "df_dettaglio": pd.DataFrame(columns=col_det),
             "df_coef": pd.DataFrame(columns=col_coef), "giudizio": ""}

    def _err(msg):
        out = dict(vuoto)
        out["df_dettaglio"] = pd.DataFrame(columns=col_det)
        out["df_coef"] = pd.DataFrame(columns=col_coef)
        out["errore"] = msg
        return out

    if lags != "auto":
        try:
            lf = float(lags)
        except (TypeError, ValueError):
            return _err("lags non valido: 'auto' o intero >= 1.")
        if not lf.is_integer() or lf < 1:
            return _err("lags non valido: 'auto' o intero >= 1.")
        lags = int(lf)
    try:
        min_giorni = int(min_giorni)
    except (TypeError, ValueError):
        return _err("min_giorni non valido: intero >= 30.")
    if min_giorni < 30:
        return _err("min_giorni non valido: intero >= 30.")
    if prezzi_giorno is None or gas_giorno is None:
        return _err("Serie prezzi o gas mancante.")
    try:
        p = pd.Series(prezzi_giorno)
        g = pd.Series(gas_giorno)
    except Exception:
        return _err("Input non interpretabili come serie.")
    if (not isinstance(p.index, pd.DatetimeIndex)
            or not isinstance(g.index, pd.DatetimeIndex)):
        return _err("Gli indici di entrambe le serie devono essere di tipo data/ora.")
    pv = pd.to_numeric(p.values, errors="coerce")
    gv = pd.to_numeric(g.values, errors="coerce")
    if np.isnan(pv).all():
        return _err("Nessun valore numerico nella serie elettrica.")
    if np.isnan(gv).all():
        return _err("Nessun valore numerico nella serie gas.")
    ip = p.index.tz_localize(None) if p.index.tz is not None else p.index
    ig = g.index.tz_localize(None) if g.index.tz is not None else g.index
    s_p = pd.Series(pv, index=ip).dropna()
    s_g = pd.Series(gv, index=ig).dropna()
    s_p = s_p[~s_p.index.duplicated(keep="first")]
    s_g = s_g[~s_g.index.duplicated(keep="first")]
    df = pd.DataFrame({"gas": s_g.groupby(s_g.index.normalize()).mean(),
                       "power": s_p.groupby(s_p.index.normalize()).mean()})
    n_scartate = int(df[["gas", "power"]].isna().any(axis=1).sum())
    df = df.dropna()
    if bool(differenzia):
        df = df.diff().dropna()
    if len(df) < min_giorni:
        return _err(f"Dati insufficienti: {len(df)} giorni utili, "
                    f"servono almeno {min_giorni}.")
    x = df["gas"].to_numpy()
    y = df["power"].to_numpy()
    T = len(df)
    if float(np.var(x)) <= 0:
        return _err("Prezzo gas costante sul periodo: test impossibile.")
    if float(np.var(y)) <= 0:
        return _err("Prezzo elettrico costante sul periodo: test impossibile.")
    pmax = min(12, (T - 2) // 3)
    if pmax < 1:
        return _err(f"Serie troppo corta per un VAR: {T} giorni utili.")

    def _stima(pv_lag, yv, xv):
        n = T - pv_lag
        Y = yv[pv_lag:]
        Xu = np.column_stack(
            [np.ones(n)]
            + [yv[pv_lag - i: T - i] for i in range(1, pv_lag + 1)]
            + [xv[pv_lag - i: T - i] for i in range(1, pv_lag + 1)])
        Xr = Xu[:, :pv_lag + 1]
        try:
            bu, _, _, _ = np.linalg.lstsq(Xu, Y, rcond=None)
            br, _, _, _ = np.linalg.lstsq(Xr, Y, rcond=None)
        except np.linalg.LinAlgError:
            return None
        ru = Y - Xu @ bu
        rr = Y - Xr @ br
        rss_u = float(ru @ ru)
        rss_r = float(rr @ rr)
        if not (np.isfinite(rss_u) and np.isfinite(rss_r)):
            return None
        return {"rss_u": rss_u, "rss_r": rss_r, "coef_u": bu, "n": n,
                "k_u": 2 * pv_lag + 1}

    def _bic(pv_lag):
        s = _stima(pv_lag, y, x)
        if s is None:
            return None
        n, k = s["n"], s["k_u"]
        rss = s["rss_u"]
        scala = max(1.0, float(np.dot(y, y)))
        if rss <= 1e-24 * scala:
            return (float("-inf"), s)
        return (n * np.log(rss / n) + k * np.log(n), s)

    if lags == "auto":
        best = None
        for pc in range(1, pmax + 1):
            b = _bic(pc)
            if b is None:
                continue
            if best is None or b[0] < best[0]:
                best = (b[0], pc)
        if best is None:
            return _err("Stima VAR impossibile sul campione.")
        p_sel = best[1]
        lags_auto = True
    else:
        p_sel = lags
        if p_sel > pmax:
            return _err(f"lags={p_sel} troppo alto per {T} giorni utili "
                        f"(massimo {pmax}).")
        lags_auto = False

    def _ftest(yv, xv):
        s = _stima(p_sel, yv, xv)
        if s is None:
            return None
        n = s["n"]
        dof_den = n - s["k_u"]
        if dof_den <= 0:
            return None
        rss_u, rss_r = s["rss_u"], s["rss_r"]
        scala = max(1.0, float(np.dot(yv, yv)))
        if rss_u <= 1e-24 * scala:
            fstat = float("inf") if rss_r > rss_u else 0.0
            pval = 0.0 if rss_r > rss_u else 1.0
        else:
            fstat = (max(0.0, rss_r - rss_u) / p_sel) / (rss_u / dof_den)
            pval = float(_fdist.sf(fstat, p_sel, dof_den))
            if not np.isfinite(pval):
                pval = 0.0 if fstat > 0 else 1.0
        crit = float(_fdist.ppf(0.95, p_sel, dof_den))
        ys = yv[p_sel:]
        ss_tot = float(((ys - ys.mean()) ** 2).sum())
        r2_u = (1.0 - rss_u / ss_tot) if ss_tot > 0 else None
        r2_r = (1.0 - rss_r / ss_tot) if ss_tot > 0 else None
        return {"f": fstat, "pval": pval, "crit": crit, "dof_den": dof_den,
                "r2_u": r2_u, "r2_r": r2_r, "coef_u": s["coef_u"]}

    r_gp = _ftest(y, x)
    r_pg = _ftest(x, y)
    if r_gp is None or r_pg is None:
        return _err("Stima VAR impossibile sul campione.")
    sig_gp = bool(r_gp["pval"] < 0.05)
    sig_pg = bool(r_pg["pval"] < 0.05)
    if sig_gp and sig_pg:
        verdetto = "FEEDBACK"
    elif sig_gp:
        verdetto = "GAS->POWER"
    elif sig_pg:
        verdetto = "POWER->GAS"
    else:
        verdetto = "NESSUNA"
    serie_txt = "differenze prime" if bool(differenzia) else "livelli"
    if verdetto == "GAS->POWER":
        giudizio = (f"CAUSALITA' GAS->POWER al 5% (F {r_gp['f']:.2f}, p-value "
                    f"{r_gp['pval']:.4f}, lag {p_sel} su {serie_txt}): il gas "
                    f"TTF anticipa il prezzo elettrico — includere i lag del "
                    f"gas nei modelli di prezzo/hedge ha potere predittivo. "
                    f"Coerente con l'uso del TTF come driver dell'hedge.")
    elif verdetto == "POWER->GAS":
        giudizio = (f"CAUSALITA' POWER->GAS al 5% (F {r_pg['f']:.2f}, p-value "
                    f"{r_pg['pval']:.4f}, lag {p_sel} su {serie_txt}): e' il "
                    f"prezzo elettrico ad anticipare il gas — pattern anomalo "
                    f"per il mercato italiano, verificare shock idiosincratici "
                    f"sul power o errori nei dati.")
    elif verdetto == "FEEDBACK":
        giudizio = (f"FEEDBACK BIDIREZIONALE al 5% (gas->power p-value "
                    f"{r_gp['pval']:.4f}, power->gas p-value {r_pg['pval']:.4f}, "
                    f"lag {p_sel} su {serie_txt}): i due mercati si trascinano "
                    f"a vicenda nel breve periodo — l'hedge gas-power va "
                    f"ricalibrato spesso (beta rolling, tab140).")
    else:
        giudizio = (f"NESSUNA causalita' di Granger al 5% (gas->power p-value "
                    f"{r_gp['pval']:.4f}, power->gas p-value {r_pg['pval']:.4f}, "
                    f"lag {p_sel} su {serie_txt}): i lag del gas non migliorano "
                    f"la previsione del power oltre i suoi stessi lag — il TTF "
                    f"non e' un driver anticipatore su questi dati. Nota: "
                    f"causalita' di Granger non significa causalita' economica.")

    righe_det = [
        {"Direzione": "Gas → Power", "F": r_gp["f"], "p-value": r_gp["pval"],
         "Lag": p_sel, "Gdl residui": r_gp["dof_den"],
         "Critica 5%": r_gp["crit"],
         "Significativa (5%)": "SÌ" if sig_gp else "NO"},
        {"Direzione": "Power → Gas", "F": r_pg["f"], "p-value": r_pg["pval"],
         "Lag": p_sel, "Gdl residui": r_pg["dof_den"],
         "Critica 5%": r_pg["crit"],
         "Significativa (5%)": "SÌ" if sig_pg else "NO"},
    ]
    df_dettaglio = pd.DataFrame(righe_det, columns=col_det)
    righe_coef = []
    for direzione, rr in (("Gas → Power", r_gp), ("Power → Gas", r_pg)):
        cu = rr["coef_u"]
        for i in range(1, p_sel + 1):
            righe_coef.append({
                "Direzione": direzione, "Lag": i,
                "Coeff. propri": round(float(cu[i]), 4),
                "Coeff. incrociati": round(float(cu[p_sel + i]), 4)})
    df_coef = pd.DataFrame(righe_coef, columns=col_coef)

    def _r4(v):
        return round(float(v), 4) if v is not None else None

    return {"valido": True, "errore": None, "lags": p_sel,
            "lags_auto": lags_auto,
            "f_gp": (float(r_gp["f"]) if np.isfinite(r_gp["f"]) else float("inf")),
            "pval_gp": float(r_gp["pval"]), "f_pg": (
                float(r_pg["f"]) if np.isfinite(r_pg["f"]) else float("inf")),
            "pval_pg": float(r_pg["pval"]), "crit_5": round(r_gp["crit"], 3),
            "sig_gp": sig_gp, "sig_pg": sig_pg, "verdetto": verdetto,
            "r2_u": _r4(r_gp["r2_u"]), "r2_r": _r4(r_gp["r2_r"]),
            "n_giorni": T, "n_scartate": n_scartate,
            "df_dettaglio": df_dettaglio, "df_coef": df_coef,
            "giudizio": giudizio}


def calcola_anticipazione_gas(prezzi_giorno, gas_giorno, max_lag=15,
                              differenzia=True, min_giorni=60):
    """Cross-correlazione gas <-> power con lag: di quanti giorni il TTF
    anticipa (o segue) lo Swissix.

    Domanda operativa: il gas muove prima e la borsa elettrica segue con
    ritardo di quanti giorni? La tab173 (Granger) dice "il gas aiuta a
    prevedere il power", qui si quantifica IL RITARDO: la funzione di
    cross-correlazione (CCF) tra le serie giornaliere.

        CCF(k) = corr(gas_t, power_{t+k})   per k = -max_lag..+max_lag

    Convenzione: k > 0 significa che il gas di oggi e' correlato con il power
    di domani(+k) -> il GAS ANTICIPA il power di k giorni. k < 0 -> il power
    anticipa il gas. k = 0 -> movimento contestuale. Il "lag stellare" e'
    l'argmax di |CCF(k)|; la significativita' usa la banda 1.96/sqrt(n_k).

    Al lag stellare si stima anche il pass-through: regressione OLS
    dpower_{t+k*} = alpha + beta * dgas_t (beta = covarianza/varianza),
    che dice "se il TTF si muove di 1 EUR/MWh, lo Swissix si muove di beta
    EUR/MWh dopo k* giorni" - il numero che serve per tempificare gli hedge.

    Su serie I(1) e' buona pratica lavorare sulle DIFFERENZE PRIME
    (differenzia=True, default): sui livelli due trend comuni gonfiano la
    correlazione spuria (vedi tab171). Deterministico, mai eccezioni.

    Input: serie GIORNALIERE (la tab costruisce base/peak dalla serie oraria).
    NaN-safe: serie vuote / indici non datetime / giorni comuni < min_giorni /
    serie costanti / max_lag o min_giorni non validi -> errore pulito;
    tz-aware reso naive; duplicati keep-first; NaN scartati e contati.

    Ritorna dict con "valido"/"errore"; "lag_star", "corr_star",
    "significativo" (bool: |corr_star| oltre la banda con correzione di
    Bonferroni sui lag multipli), "verdetto" in {"GAS_ANTICIPA",
    "POWER_ANTICIPA", "CONTESTUALI", "NESSUNA"}; "beta_pt", "alpha_pt",
    "r2_pt" (pass-through al lag stellare); "banda95" (banda per lag sul
    grafico) e "banda_bonf" (banda corretta per il verdetto); "n_giorni",
    "n_scartate"; "df_ccf" (Lag, Correlazione, Banda 95%, Significativo);
    "giudizio".
    """
    col_ccf = ["Lag", "Correlazione", "Banda 95%", "Significativo"]
    vuoto = {"valido": False, "errore": None, "lag_star": None,
             "corr_star": None, "significativo": None, "verdetto": None,
             "beta_pt": None, "alpha_pt": None, "r2_pt": None,
             "banda95": None, "banda_bonf": None, "n_giorni": 0,
             "n_scartate": 0,
             "df_ccf": pd.DataFrame(columns=col_ccf), "giudizio": ""}

    def _err(msg):
        out = dict(vuoto)
        out["df_ccf"] = pd.DataFrame(columns=col_ccf)
        out["errore"] = msg
        return out

    try:
        ml = float(max_lag)
    except (TypeError, ValueError):
        return _err("max_lag non valido: intero >= 1.")
    if not ml.is_integer() or ml < 1:
        return _err("max_lag non valido: intero >= 1.")
    max_lag = int(ml)
    try:
        min_giorni = int(min_giorni)
    except (TypeError, ValueError):
        return _err("min_giorni non valido: intero >= 30.")
    if min_giorni < 30:
        return _err("min_giorni non valido: intero >= 30.")
    if prezzi_giorno is None or gas_giorno is None:
        return _err("Serie prezzi o gas mancante.")
    try:
        p = pd.Series(prezzi_giorno)
        g = pd.Series(gas_giorno)
    except Exception:
        return _err("Input non interpretabili come serie.")
    if (not isinstance(p.index, pd.DatetimeIndex)
            or not isinstance(g.index, pd.DatetimeIndex)):
        return _err("Gli indici di entrambe le serie devono essere di tipo data/ora.")
    pv = pd.to_numeric(p.values, errors="coerce")
    gv = pd.to_numeric(g.values, errors="coerce")
    if np.isnan(pv).all():
        return _err("Nessun valore numerico nella serie elettrica.")
    if np.isnan(gv).all():
        return _err("Nessun valore numerico nella serie gas.")
    ip = p.index.tz_localize(None) if p.index.tz is not None else p.index
    ig = g.index.tz_localize(None) if g.index.tz is not None else g.index
    s_p = pd.Series(pv, index=ip).dropna()
    s_g = pd.Series(gv, index=ig).dropna()
    s_p = s_p[~s_p.index.duplicated(keep="first")]
    s_g = s_g[~s_g.index.duplicated(keep="first")]
    df = pd.DataFrame({"gas": s_g.groupby(s_g.index.normalize()).mean(),
                       "power": s_p.groupby(s_p.index.normalize()).mean()})
    n_scartate = int(df[["gas", "power"]].isna().any(axis=1).sum())
    df = df.dropna()
    if bool(differenzia):
        df = df.diff().dropna()
    if len(df) < min_giorni:
        return _err(f"Dati insufficienti: {len(df)} giorni utili, "
                    f"servono almeno {min_giorni}.")
    if df["gas"].std() < 1e-12:
        return _err("Serie gas costante: correlazione non definita.")
    if df["power"].std() < 1e-12:
        return _err("Serie elettrica costante: correlazione non definita.")
    max_lag = min(max_lag, len(df) - min_giorni)
    if max_lag < 1:
        return _err("max_lag troppo alto rispetto ai dati disponibili.")
    x = df["gas"].to_numpy()
    y = df["power"].to_numpy()
    n = len(df)

    righe = []
    for k in range(-max_lag, max_lag + 1):
        if k >= 0:
            a, b = x[:n - k], y[k:]
        else:
            a, b = x[-k:], y[:n + k]
        nk = len(a)
        banda = 1.96 / np.sqrt(nk)
        if nk < 2 or np.std(a) < 1e-12 or np.std(b) < 1e-12:
            corr = np.nan
        else:
            corr = float(np.corrcoef(a, b)[0, 1])
        sig = bool(np.isfinite(corr) and abs(corr) > banda)
        righe.append({"Lag": k, "Correlazione": (round(corr, 4) if np.isfinite(corr) else None),
                      "Banda 95%": round(banda, 4), "Significativo": "Sì" if sig else "No"})
    df_ccf = pd.DataFrame(righe, columns=col_ccf)
    corr_vals = np.array([r["Correlazione"] if r["Correlazione"] is not None else np.nan
                          for r in righe])
    if np.isnan(corr_vals).all():
        return _err("Cross-correlazione non calcolabile su nessun lag.")
    idx_star = int(np.nanargmax(np.abs(corr_vals)))
    lag_star = int(righe[idx_star]["Lag"])
    corr_star = float(corr_vals[idx_star])
    if lag_star >= 0:
        a_s, b_s = x[:n - lag_star], y[lag_star:]
    else:
        a_s, b_s = x[-lag_star:], y[:n + lag_star]
    n_s = len(a_s)
    banda_star = 1.96 / np.sqrt(n_s)
    # Correzione di Bonferroni per i test multipli (2*max_lag+1 lag):
    # il lag stellare e' l'argmax di |CCF|, quindi il verdetto usa la banda
    # con alpha corretta; il grafico mostra comunque la banda 95% per lag.
    from scipy.stats import norm as _norm
    m_lag = 2 * max_lag + 1
    z_bonf = float(_norm.ppf(1.0 - 0.05 / (2.0 * m_lag)))
    banda_bonf = z_bonf / np.sqrt(n_s)
    significativo = bool(abs(corr_star) > banda_bonf)
    cov = float(np.cov(a_s, b_s, ddof=1)[0, 1])
    var_a = float(np.var(a_s, ddof=1))
    beta_pt = cov / var_a if var_a > 1e-12 else None
    alpha_pt = float(np.mean(b_s) - beta_pt * np.mean(a_s)) if beta_pt is not None else None
    r2_pt = float(corr_star ** 2)
    if significativo:
        if lag_star > 0:
            verdetto = "GAS_ANTICIPA"
        elif lag_star < 0:
            verdetto = "POWER_ANTICIPA"
        else:
            verdetto = "CONTESTUALI"
    else:
        verdetto = "NESSUNA"
    if verdetto == "GAS_ANTICIPA":
        giudizio = (f"Il gas anticipa il power di {lag_star} giorni (corr. {corr_star:+.2f}): "
                    "difendibile come driver anticipatore e per tempificare gli hedge "
                    f"(pass-through {beta_pt:+.2f} EUR/MWh di power per 1 EUR/MWh di TTF).")
    elif verdetto == "POWER_ANTICIPA":
        giudizio = (f"Attenzione: e' il power ad anticipare il gas di {abs(lag_star)} giorni "
                    "(corr. {:+.2f}): il TTF non e' un anticipatore affidabile qui.".format(corr_star))
    elif verdetto == "CONTESTUALI":
        giudizio = ("Gas e power si muovono insieme lo stesso giorno "
                    f"(corr. {corr_star:+.2f}): nessun anticipo sfruttabile per il timing.")
    else:
        giudizio = ("Nessuna cross-correlazione significativa entro i lag esplorati: "
                    "il gas non offre un timing affidabile per il power.")
    return {"valido": True, "errore": None, "lag_star": lag_star,
            "corr_star": round(corr_star, 4), "significativo": significativo,
            "verdetto": verdetto,
            "beta_pt": (round(beta_pt, 4) if beta_pt is not None else None),
            "alpha_pt": (round(alpha_pt, 4) if alpha_pt is not None else None),
            "r2_pt": round(r2_pt, 4), "banda95": round(banda_star, 4),
            "banda_bonf": round(banda_bonf, 4),
            "n_giorni": n, "n_scartate": n_scartate,
            "df_ccf": df_ccf, "giudizio": giudizio}


def calcola_matrice_costo_settimana(prezzi, mw_f1, mw_f2, mw_f3, top_n=10):
    """Matrice 7x24 del costo del periodo: costo_h = prezzo_h * MW(fascia_h).

    Domanda operativa: in quali celle (giorno della settimana x ora) si
    concentra la spesa? E' la base numerica per il demand response: spostare
    carico dalle celle peggiori a quelle migliori.

    Ritorna dict con:
    - valido/errore
    - mat_prezzo: DataFrame 7x24 (Lun..Dom x 0..23), prezzo medio €/MWh
    - mat_costo: DataFrame 7x24, costo totale € per cella
    - df_top: top_n celle per costo (giorno, ora, prezzo medio, costo, quota %)
    - ora_peggiore: ora con prezzo medio piu' alto; giorno_peggiore: giorno con costo piu' alto
    - costo_totale, energia_totale, n_ore
    - quota_top_n: % del costo nelle top_n celle
    - risparmio_spostamento(quota_pct): stima € risparmiati spostando quota_pct
      dell'energia dalle top_n celle peggiori alle top_n migliori (MWh conservati).
    """
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return {"valido": False, "errore": "Serie prezzi non valida."}
    if len(p) == 0:
        return {"valido": False, "errore": "Serie prezzi vuota."}
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
    except (TypeError, ValueError):
        return {"valido": False, "errore": "MW per fascia non validi."}
    if sum(mws) <= 0:
        return {"valido": False, "errore": "Carico nullo: imposta MW > 0 in almeno una fascia."}
    mw_of = {"F1": mws[0], "F2": mws[1], "F3": mws[2]}
    try:
        fasce = p.index.map(fascia_oraria)
    except Exception:
        return {"valido": False, "errore": "Indice prezzi non valido (serve un DatetimeIndex)."}
    prezzi_v = p.to_numpy(dtype=float)
    carico = np.array([mw_of[fx] for fx in fasce], dtype=float)
    costo_h = prezzi_v * carico
    dow = p.index.dayofweek.to_numpy()
    ore = p.index.hour.to_numpy()
    nomi = ["Lun", "Mar", "Mer", "Gio", "Ven", "Sab", "Dom"]
    mat_prezzo = pd.DataFrame(np.nan, index=nomi, columns=list(range(24)))
    mat_costo = pd.DataFrame(0.0, index=nomi, columns=list(range(24)))
    mat_energia = pd.DataFrame(0.0, index=nomi, columns=list(range(24)))
    for d in range(7):
        for h in range(24):
            m = (dow == d) & (ore == h)
            if bool(m.any()):
                mat_prezzo.iloc[d, h] = float(np.mean(prezzi_v[m]))
                mat_costo.iloc[d, h] = float(np.nansum(costo_h[m]))
                mat_energia.iloc[d, h] = float(np.nansum(carico[m]))
    costo_tot = float(np.nansum(costo_h))
    energia_tot = float(np.nansum(carico))
    n_ore = int(len(p))
    if costo_tot <= 0:
        return {"valido": False, "errore": "Costo totale nullo o negativo: verifica prezzi e carico."}
    righe = []
    for d in range(7):
        for h in range(24):
            righe.append((nomi[d], h, mat_prezzo.iloc[d, h], mat_costo.iloc[d, h],
                          mat_energia.iloc[d, h]))
    df = pd.DataFrame(righe, columns=["Giorno", "Ora", "Prezzo medio (€/MWh)",
                                      "Costo (€)", "Energia (MWh)"])
    df["Quota costo %"] = df["Costo (€)"] / costo_tot * 100.0
    df = df.sort_values("Costo (€)", ascending=False).reset_index(drop=True)
    n_top = int(max(1, min(int(top_n), len(df))))
    df_top = df.head(n_top).copy()
    quota_top = float(df_top["Costo (€)"].sum() / costo_tot * 100.0)
    ore_medie = df.groupby("Ora")["Prezzo medio (€/MWh)"].mean()
    ora_peggiore = int(ore_medie.idxmax())
    giorno_peggiore = mat_costo.sum(axis=1).idxmax()

    def risparmio_spostamento(quota_pct):
        """Sposta quota_pct dell'energia dalle top_n celle peggiori alle
        top_n migliori (stesso MWh, prezzo pesato per energia)."""
        q = max(0.0, min(100.0, float(quota_pct))) / 100.0
        worst = df_top.copy()
        best = df.tail(n_top).copy()
        e_w = float(worst["Energia (MWh)"].sum())
        e_b = float(best["Energia (MWh)"].sum())
        if e_w <= 0 or e_b <= 0 or q <= 0:
            return 0.0
        px_w = float((worst["Prezzo medio (€/MWh)"] * worst["Energia (MWh)"]).sum() / e_w)
        px_b = float((best["Prezzo medio (€/MWh)"] * best["Energia (MWh)"]).sum() / e_b)
        return float(q * e_w * (px_w - px_b))

    return {"valido": True, "errore": None,
            "mat_prezzo": mat_prezzo, "mat_costo": mat_costo,
            "mat_energia": mat_energia, "df_top": df_top, "df_celle": df,
            "ora_peggiore": ora_peggiore, "giorno_peggiore": giorno_peggiore,
            "costo_totale": costo_tot, "energia_totale": energia_tot, "n_ore": n_ore,
            "quota_top_n": quota_top, "top_n": n_top,
            "risparmio_spostamento": risparmio_spostamento}


def calcola_finestra_fermo_consumo(prezzi, mw_f1, mw_f2, mw_f3, giorni_fermo=3,
                                 carico_residuo_pct=10.0):
    """Finestra ottimale di fermo manutenzione per un CONSUMATORE industriale.

    Domanda operativa: la linea deve fermarsi N giorni consecutivi per
    manutenzione programmata — in quale finestra pianificarla per MASSIMIZZARE
    il costo energetico evitato? Durante il fermo il carico non va a zero:
    restano gli ausiliari (carico_residuo_pct % del carico normale).

    Metodo (deterministico a parita' di input):
    - ore con prezzo NaN scartate; timestamp duplicati: primo tenuto;
    - carico orario = MW della fascia di ciascuna ora (via fascia_oraria);
    - costo evitato orario = prezzo_h * MW_h * (1 - residuo);
    - aggregazione giornaliera; sliding window di N giorni consecutivi:
      vince la finestra con costo evitato MASSIMO (a parita' vince la prima,
      mergesort stabile);
    - la finestra peggiore (minimo) quantifica il costo di una cattiva
      pianificazione (best - worst).

    E' lo specchio lato consumo del tab "Fermo impianto" (lato generazione,
    che MINIMIZZA il margine perso: li' la finestra migliore e' la piu'
    economica, qui e' la piu' cara). Nota: con prezzi negativi fermarsi
    in quelle ore FA PERDERE soldi (si rinuncia a consumare a prezzo
    negativo): la finestra ottimale le evita da sola.

    Ritorna dict con valido/errore, df_giorni (Data, Costo evitato EUR,
    Energia evitata MWh), df_finestre (Inizio, Fine, Costo evitato EUR —
    tutte le finestre consecutive ordinate per costo evitato decrescente),
    best/worst (dict inizio/fine/costo_evitato), costo_totale (EUR, periodo),
    quota_best_pct (% del costo periodo evitata nella finestra migliore),
    costo_cattiva_pianificazione (EUR = best - worst), giorni, durata_gg,
    carico_residuo_pct. NaN-safe: serie vuota / parametri non validi ->
    valido False con errore pulito, mai eccezioni.
    """
    cols_g = ["Data", "Costo evitato (EUR)", "Energia evitata (MWh)"]
    cols_f = ["Inizio", "Fine", "Costo evitato (EUR)"]
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return {"valido": False, "errore": "Serie prezzi non valida."}
    if len(p) == 0:
        return {"valido": False, "errore": "Serie prezzi vuota."}
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
        d = int(float(giorni_fermo))
        residuo = float(carico_residuo_pct) / 100.0
    except (TypeError, ValueError):
        return {"valido": False, "errore": "Parametri non validi (MW, giorni, carico residuo)."}
    if sum(mws) <= 0:
        return {"valido": False, "errore": "Carico nullo: imposta MW > 0 in almeno una fascia."}
    if d < 1:
        return {"valido": False, "errore": "Durata del fermo non valida (minimo 1 giorno)."}
    if not (0.0 <= residuo < 1.0):
        return {"valido": False, "errore": "Carico residuo non valido (0-99%)."}
    mw_of = {"F1": mws[0], "F2": mws[1], "F3": mws[2]}
    try:
        fasce = p.index.map(fascia_oraria)
    except Exception:
        return {"valido": False, "errore": "Indice prezzi non valido (serve un DatetimeIndex)."}
    prezzi_v = p.to_numpy(dtype=float)
    carico = np.array([mw_of[fx] for fx in fasce], dtype=float)
    fattore = 1.0 - residuo
    evitato_h = prezzi_v * carico * fattore
    evit_g = pd.Series(evitato_h, index=p.index).resample("D").sum()
    en_g = pd.Series(carico * fattore, index=p.index).resample("D").sum()
    evit_g.index = pd.to_datetime(evit_g.index.date)
    n = len(evit_g)
    if n == 0:
        return {"valido": False, "errore": "Serie prezzi vuota."}
    d = min(d, n)
    roll = evit_g.rolling(d, min_periods=d).sum().dropna()
    righe = [{"Inizio": (fine - pd.Timedelta(days=d - 1)).date(),
              "Fine": fine.date(),
              "Costo evitato (EUR)": float(roll.loc[fine])} for fine in roll.index]
    df_finestre = (pd.DataFrame(righe, columns=cols_f)
                     .sort_values("Costo evitato (EUR)", ascending=False, kind="mergesort")
                     .reset_index(drop=True))
    df_giorni = pd.DataFrame({"Data": evit_g.index.date,
                              "Costo evitato (EUR)": evit_g.values,
                              "Energia evitata (MWh)": en_g.values})
    costo_tot = float((prezzi_v * carico).sum())
    b0 = df_finestre.iloc[0]
    w0 = df_finestre.iloc[-1]
    best = {"inizio": b0["Inizio"], "fine": b0["Fine"],
            "costo_evitato": float(b0["Costo evitato (EUR)"])}
    worst = {"inizio": w0["Inizio"], "fine": w0["Fine"],
             "costo_evitato": float(w0["Costo evitato (EUR)"])}
    quota = (best["costo_evitato"] / costo_tot * 100.0) if costo_tot > 0 else 0.0
    return {"valido": True, "errore": None,
            "df_giorni": df_giorni, "df_finestre": df_finestre,
            "best": best, "worst": worst,
            "costo_totale": costo_tot, "quota_best_pct": float(quota),
            "costo_cattiva_pianificazione": float(best["costo_evitato"] - worst["costo_evitato"]),
            "giorni": n, "durata_gg": d,
            "carico_residuo_pct": float(carico_residuo_pct)}


def calcola_make_or_buy(prezzi, mw_f1, mw_f2, mw_f3, costo_marginale=85.0,
                        mw_cogen=2.0, costo_avviamento=500.0,
                        min_up=4, min_down=2, breakeven=True):
    """Make-or-buy orario per un consumatore industriale con cogeneratore.

    Domanda operativa: ho un cogeneratore (o gruppo elettrogeno) da P MW
    con costo marginale cm (€/MWh tutto incluso: combustibile, manutenzione
    variabile, CO2) — in quali ore conviene autoprodurre invece di comprare
    dalla rete al prezzo spot?

    Metodo: spark_h = prezzo_h - cm (€/MWh per MW di cogeneratore). Lo
    schedule ottimale di accensione e' calcolato da ottimizza_dispatch
    (stessa matematica del tab 'Dispatch ottimale', ma qui e' il
    CONSUMATORE che decide: ON = autoproduco, OFF = compro dalla rete),
    con costo di avviamento e tempi minimi di marcia/fermo. Nelle ore ON
    l'energia autoprodotta e' min(P, carico_h): il cogeneratore copre solo
    il proprio carico, non vende in rete (lo schedule DP e' ottimale per il
    caso non cappato e resta un'ottima euristica con il cap).
    Break-even: il costo marginale massimo che mantiene il valore >= 0,
    via bisezione (valore decrescente in cm); None se mai conveniente,
    inf se sempre conveniente nel periodo.

    Ritorna dict con valido/errore, df_ore (Ora, Prezzo EUR/MWh, Carico MW,
    Spread EUR/MWh, Autoproduci, Energia autoprodotta MWh, Risparmio EUR),
    df_blocchi (Inizio, Fine, Ore, Energia MWh, Risparmio lordo EUR,
    Risparmio netto EUR), ore_on, energia_mwh, risparmio_totale,
    costo_acquisto_totale (EUR, prezzo*carico su tutto il periodo),
    quota_risparmio_pct, avviamenti, fattore_utilizzo_pct,
    prezzo_medio_on/off, costo_vincoli (EUR/MW, dal DP), breakeven_cm,
    n_ore. NaN-safe: serie vuota / parametri non validi -> valido False
    con errore pulito, mai eccezioni. Deterministico.
    """
    cols_o = ["Ora", "Prezzo (EUR/MWh)", "Carico (MW)", "Spread (EUR/MWh)",
              "Autoproduci", "Energia autoprodotta (MWh)", "Risparmio (EUR)"]
    cols_b = ["Inizio", "Fine", "Ore", "Energia (MWh)",
              "Risparmio lordo (EUR)", "Risparmio netto (EUR)"]
    vuoto = {"valido": False, "errore": None, "df_ore": pd.DataFrame(columns=cols_o),
             "df_blocchi": pd.DataFrame(columns=cols_b)}
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto, errore="Serie prezzi non valida.")
    if len(p) == 0:
        return dict(vuoto, errore="Serie prezzi vuota.")
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
        cm = float(costo_marginale)
        pcogen = float(mw_cogen)
        ca = float(costo_avviamento)
        mu = int(min_up)
        md = int(min_down)
    except (TypeError, ValueError):
        return dict(vuoto, errore="Parametri non validi.")
    if sum(mws) <= 0:
        return dict(vuoto, errore="Carico nullo: imposta MW > 0 in almeno una fascia.")
    if cm < 0 or pcogen <= 0 or ca < 0:
        return dict(vuoto, errore="Costo marginale, potenza e avviamento devono essere >= 0 (potenza > 0).")
    if mu < 1 or md < 1 or float(mu) != float(min_up) or float(md) != float(min_down):
        return dict(vuoto, errore="Tempi minimi di marcia/fermo non validi (interi >= 1).")
    try:
        fasce = p.index.map(fascia_oraria)
    except Exception:
        return dict(vuoto, errore="Indice prezzi non valido (serve un DatetimeIndex).")
    mw_of = {"F1": mws[0], "F2": mws[1], "F3": mws[2]}
    carico = np.array([mw_of[fx] for fx in fasce], dtype=float)
    spark = p.to_numpy(dtype=float) - cm
    dp = ottimizza_dispatch(spark, costo_avvio=ca, costo_fisso_orario=0.0,
                            min_up=mu, min_down=md)
    sched = dp["schedule"].astype(bool)
    n = len(p)
    energia_h = np.where(sched, np.minimum(pcogen, carico), 0.0)
    risparmio_h = np.where(sched, spark * energia_h, 0.0)
    # costo di avviamento ripartito sui blocchi ON consecutivi
    idx = np.arange(n)
    df_ore = pd.DataFrame({
        "Ora": p.index, "Prezzo (EUR/MWh)": p.to_numpy(dtype=float),
        "Carico (MW)": carico, "Spread (EUR/MWh)": spark,
        "Autoproduci": np.where(sched, "SI", "NO"),
        "Energia autoprodotta (MWh)": energia_h,
        "Risparmio (EUR)": risparmio_h})
    blocchi, avv_count = [], 0
    if sched.any():
        cambi = np.diff(sched.astype(int))
        ini = np.r_[0, np.where(cambi == 1)[0] + 1]
        fin = np.r_[np.where(cambi == -1)[0], n - 1]
        for a, b in zip(ini, fin):
            avv_count += 1
            lordo = float(risparmio_h[a:b + 1].sum())
            blocchi.append({
                "Inizio": p.index[a], "Fine": p.index[b],
                "Ore": int(b - a + 1),
                "Energia (MWh)": float(energia_h[a:b + 1].sum()),
                "Risparmio lordo (EUR)": lordo,
                "Risparmio netto (EUR)": lordo - ca})
    df_blocchi = pd.DataFrame(blocchi, columns=cols_b)
    costo_acq = float((p.to_numpy(dtype=float) * carico).sum())
    risp_tot = float(risparmio_h.sum()) - avv_count * ca
    ore_on = int(sched.sum())
    be = None
    if breakeven:
        pmax = float(np.max(p.to_numpy(dtype=float)))
        v0 = ottimizza_dispatch(p.to_numpy(dtype=float) - 0.0, costo_avvio=ca,
                                min_up=mu, min_down=md)["valore"]
        if v0 <= 0:
            be = None
        elif ottimizza_dispatch(p.to_numpy(dtype=float) - pmax, costo_avvio=ca,
                                min_up=mu, min_down=md)["valore"] > 0:
            be = float("inf")
        else:
            lo, hi = 0.0, pmax
            for _ in range(24):
                mid = (lo + hi) / 2.0
                v = ottimizza_dispatch(p.to_numpy(dtype=float) - mid, costo_avvio=ca,
                                       min_up=mu, min_down=md)["valore"]
                if v > 0:
                    lo = mid
                else:
                    hi = mid
            be = (lo + hi) / 2.0
    on_px = p.to_numpy(dtype=float)[sched]
    off_px = p.to_numpy(dtype=float)[~sched]
    return {"valido": True, "errore": None,
            "df_ore": df_ore, "df_blocchi": df_blocchi,
            "ore_on": ore_on, "n_ore": n,
            "energia_mwh": float(energia_h.sum()),
            "risparmio_totale": risp_tot,
            "costo_acquisto_totale": costo_acq,
            "quota_risparmio_pct": (risp_tot / costo_acq * 100.0 if costo_acq > 0 else 0.0),
            "avviamenti": avv_count,
            "fattore_utilizzo_pct": (ore_on / n * 100.0 if n else 0.0),
            "prezzo_medio_on": (float(on_px.mean()) if on_px.size else float("nan")),
            "prezzo_medio_off": (float(off_px.mean()) if off_px.size else float("nan")),
            "costo_vincoli": float(dp["costo_vincoli"]) * pcogen,
            "breakeven_cm": be,
            "costo_marginale": cm, "mw_cogen": pcogen,
            "costo_avviamento": ca, "min_up": mu, "min_down": md}


def calcola_orologio_prezzo(prezzi):
    """Orologio del prezzo: profilo orario medio per mese, su quadrante polare.

    Domanda operativa: in quale mese e a che ora il prezzo e' sistematicamente
    piu' alto o piu' basso? L'orologio mostra, per ogni mese di calendario, il
    profilo medio delle 24 ore: la struttura giorno/notte cambia con le
    stagioni, e leggerla dice quando conviene spostare i consumi (shifting
    stagionale del carico), quando pianificare la manutenzione e quando
    comprare spot.

    Metodo: media del prezzo per coppia (mese, ora del giorno) su tutta la
    serie storica; per ogni mese con dati, ora piu' economica / piu' cara e
    spread giorno/notte; profilo annuo medio per ora (media sui mesi) con ora
    migliore e peggiore dell'anno.

    Ritorna dict con valido/errore, df_matrice (Mese, Ora del giorno, Prezzo
    medio (EUR/MWh) — 12x24 righe), df_mesi (Mese, Ora più economica,
    Prezzo min (EUR/MWh), Ora più cara, Prezzo max (EUR/MWh),
    Spread (EUR/MWh)), ora_migliore_anno, ora_peggiore_anno,
    spread_medio_mensile, mese_spread_max, prezzo_medio_annuo, n_ore,
    mesi_presenti. NaN-safe: serie vuota / indice non datetime / <24 ore
    valide -> valido False con errore pulito, mai eccezioni. Deterministico
    (nanargmin/nanargmax prendono la prima occorrenza a parita' di prezzo).
    """
    cols_m = ["Mese", "Ora del giorno", "Prezzo medio (EUR/MWh)"]
    cols_s = ["Mese", "Ora più economica", "Prezzo min (EUR/MWh)",
              "Ora più cara", "Prezzo max (EUR/MWh)", "Spread (EUR/MWh)"]
    vuoto = {"valido": False, "errore": None,
             "df_matrice": pd.DataFrame(columns=cols_m),
             "df_mesi": pd.DataFrame(columns=cols_s)}
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto, errore="Serie prezzi non valida.")
    if len(p) == 0:
        return dict(vuoto, errore="Serie prezzi vuota.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return dict(vuoto, errore="Indice prezzi non valido (serve un DatetimeIndex).")
    if len(p) < 24:
        return dict(vuoto, errore="Serie troppo corta: servono almeno 24 ore valide.")
    mesi = p.index.month.to_numpy()
    ore = p.index.hour.to_numpy()
    vals = p.to_numpy(dtype=float)
    somma = np.zeros((12, 24))
    conte = np.zeros((12, 24))
    for m, h, v in zip(mesi, ore, vals):
        somma[m - 1, h] += v
        conte[m - 1, h] += 1
    with np.errstate(invalid="ignore", divide="ignore"):
        media = np.where(conte > 0, somma / conte, np.nan)
    righe_m = [{"Mese": m + 1, "Ora del giorno": h,
                "Prezzo medio (EUR/MWh)": float(media[m, h])}
               for m in range(12) for h in range(24)]
    df_matrice = pd.DataFrame(righe_m, columns=cols_m)
    righe_s = []
    for m in range(12):
        riga = media[m]
        if np.isnan(riga).all():
            continue
        i_min = int(np.nanargmin(riga))
        i_max = int(np.nanargmax(riga))
        righe_s.append({"Mese": m + 1, "Ora più economica": i_min,
                        "Prezzo min (EUR/MWh)": float(riga[i_min]),
                        "Ora più cara": i_max,
                        "Prezzo max (EUR/MWh)": float(riga[i_max]),
                        "Spread (EUR/MWh)": float(riga[i_max] - riga[i_min])})
    df_mesi = pd.DataFrame(righe_s, columns=cols_s)
    profilo_annuo = np.nanmean(media, axis=0)
    ora_best = int(np.nanargmin(profilo_annuo))
    ora_worst = int(np.nanargmax(profilo_annuo))
    spread_medio = float(df_mesi["Spread (EUR/MWh)"].mean()) if len(df_mesi) else 0.0
    m_spread_max = (int(df_mesi.loc[df_mesi["Spread (EUR/MWh)"].idxmax(), "Mese"])
                    if len(df_mesi) else None)
    return {"valido": True, "errore": None,
            "df_matrice": df_matrice, "df_mesi": df_mesi,
            "ora_migliore_anno": ora_best, "ora_peggiore_anno": ora_worst,
            "spread_medio_mensile": spread_medio, "mese_spread_max": m_spread_max,
            "prezzo_medio_annuo": float(vals.mean()), "n_ore": len(p),
            "mesi_presenti": sorted({int(m) for m in mesi})}


def calcola_flessibilita_oraria(prezzi, mw_f1, mw_f2, mw_f3, quota_flessibile_pct=10.0,
                               raggio_spostamento=6):
    """Valore orario della flessibilita' di spostamento del carico (demand response).

    Domanda operativa: ho una quota flessibile del carico (es. il 10% di ogni
    ora, un processo che posso anticipare o posticipare) e posso spostarla di
    al massimo +-R ore — qual e' il valore massimo di quello spostamento,
    ora per ora?

    Metodo: per ogni ora h, la quota flessibile e' q_h = quota% * carico_h
    (MWh spostabili). La destinazione ottimale e' l'ora piu' economica nella
    finestra [h-R, h+R]; il risparmio e' q_h * (p_h - p_min), floorato a zero
    (se nessuna ora in finestra e' piu' economica, non si sposta). Lo
    spostamento e' a somma energetica zero: e' la "curva d'offerta" oraria
    della flessibilita', utile per negoziare contratti di demand response.
    L'aggregazione per ora del giorno (0-23) mostra il profilo tipico della
    flessibilita'.

    Ritorna dict con valido/errore, df_ore (Ora, Prezzo EUR/MWh, Carico MW,
    Quota spostabile MWh, Ora destinazione, Prezzo destinazione EUR/MWh,
    Risparmio EUR), df_profilo (Ora del giorno, Risparmio medio EUR/ora,
    Risparmio totale EUR, Ore con valore, Ore totali), risparmio_totale,
    costo_totale_acquisto, quota_risparmio_pct, ore_con_risparmio,
    miglior_ora_giorno, peggior_ora_giorno, quota_flessibile_pct,
    raggio_spostamento, n_ore. NaN-safe: serie vuota / parametri non validi
    -> valido False con errore pulito, mai eccezioni. Deterministico
    (a parita' di prezzo, argmin prende la prima occorrenza).
    """
    cols_o = ["Ora", "Prezzo (EUR/MWh)", "Carico (MW)", "Quota spostabile (MWh)",
              "Ora destinazione", "Prezzo destinazione (EUR/MWh)", "Risparmio (EUR)"]
    cols_p = ["Ora del giorno", "Risparmio medio (EUR/ora)",
              "Risparmio totale (EUR)", "Ore con valore", "Ore totali"]
    vuoto = {"valido": False, "errore": None,
             "df_ore": pd.DataFrame(columns=cols_o),
             "df_profilo": pd.DataFrame(columns=cols_p)}
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto, errore="Serie prezzi non valida.")
    if len(p) == 0:
        return dict(vuoto, errore="Serie prezzi vuota.")
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
        quota = float(quota_flessibile_pct)
        raggio = int(raggio_spostamento)
    except (TypeError, ValueError):
        return dict(vuoto, errore="Parametri non validi.")
    if sum(mws) <= 0:
        return dict(vuoto, errore="Carico nullo: imposta MW > 0 in almeno una fascia.")
    if not (0.0 <= quota <= 100.0):
        return dict(vuoto, errore="Quota flessibile fuori intervallo [0, 100]%.")
    if raggio < 1 or float(raggio) != float(raggio_spostamento):
        return dict(vuoto, errore="Raggio di spostamento non valido (intero >= 1).")
    try:
        fasce = p.index.map(fascia_oraria)
    except Exception:
        return dict(vuoto, errore="Indice prezzi non valido (serve un DatetimeIndex).")
    n = len(p)
    mw_of = {"F1": mws[0], "F2": mws[1], "F3": mws[2]}
    carico = np.array([mw_of[fx] for fx in fasce], dtype=float)
    prezzi_a = p.to_numpy(dtype=float)
    q_shift = quota / 100.0 * carico
    risparmio = np.zeros(n)
    dest_idx = np.arange(n)
    for i in range(n):
        a = max(0, i - raggio)
        b = min(n - 1, i + raggio)
        j = a + int(np.argmin(prezzi_a[a:b + 1]))
        dest_idx[i] = j
        risparmio[i] = max(0.0, (prezzi_a[i] - prezzi_a[j]) * q_shift[i])
    df_ore = pd.DataFrame({
        "Ora": p.index, "Prezzo (EUR/MWh)": prezzi_a,
        "Carico (MW)": carico, "Quota spostabile (MWh)": q_shift,
        "Ora destinazione": p.index[dest_idx],
        "Prezzo destinazione (EUR/MWh)": prezzi_a[dest_idx],
        "Risparmio (EUR)": risparmio})
    ore_giorno = np.array([t.hour for t in p.index])
    righe_p = []
    for h in range(24):
        m = ore_giorno == h
        risp_h = risparmio[m]
        righe_p.append({
            "Ora del giorno": h,
            "Risparmio medio (EUR/ora)": float(risp_h.mean()) if m.sum() else 0.0,
            "Risparmio totale (EUR)": float(risp_h.sum()),
            "Ore con valore": int((risp_h > 0).sum()),
            "Ore totali": int(m.sum())})
    df_profilo = pd.DataFrame(righe_p, columns=cols_p)
    risp_tot = float(risparmio.sum())
    costo_tot = float((prezzi_a * carico).sum())
    ore_val = int((risparmio > 0).sum())
    miglior = int(df_profilo.loc[df_profilo["Risparmio medio (EUR/ora)"].idxmax(), "Ora del giorno"])
    peggior = int(df_profilo.loc[df_profilo["Risparmio medio (EUR/ora)"].idxmin(), "Ora del giorno"])
    return {"valido": True, "errore": None,
            "df_ore": df_ore, "df_profilo": df_profilo,
            "risparmio_totale": risp_tot,
            "costo_totale_acquisto": costo_tot,
            "quota_risparmio_pct": (risp_tot / costo_tot * 100.0 if costo_tot > 0 else 0.0),
            "ore_con_risparmio": ore_val, "n_ore": n,
            "miglior_ora_giorno": miglior, "peggior_ora_giorno": peggior,
            "quota_flessibile_pct": quota, "raggio_spostamento": raggio}


def calcola_quantili_orari(prezzi, q_bassa=10.0, q_alta=90.0):
    """Quantili orari del prezzo: bande di prezzo per ora del giorno (0-23).

    Domanda operativa: a che ora del giorno il prezzo e' tipicamente basso o
    alto, e quanto e' ampio l'intervallo realistico? Per ogni ora del giorno
    (0-23) calcola i quantili del prezzo spot sulle ore di quella fascia nel
    periodo: P_bassa / P25 / P50 (mediana) / P75 / P_alta, piu' min, max,
    media e numerosita'. Le bande P25-P75 e P_bassa-P_alta sono la "forchetta"
    attesa del prezzo ora per ora: servono a piazzare ordini limite, a
    tarare le soglie degli alert e a valutare se un prezzo fisso offerto e'
    dentro o fuori la norma per quell'ora.

    Ritorna dict con valido/errore, df_quantili (Ora del giorno, N ore, Min,
    P_bassa, P25, P50, P75, P_alta, Max, Media, Ampiezza banda), n_ore,
    ora_mediana_max (ora con mediana piu' alta), ora_mediana_min (ora con
    mediana piu' bassa), ora_iqr_max (ora con IQR P75-P25 piu' ampio, la piu'
    volatile), ampiezza_banda_media, q_bassa, q_alta. NaN-safe: serie vuota /
    indice non datetime / parametri non validi -> valido False con errore
    pulito, mai eccezioni. Deterministico (quantili pandas, interpolazione
    lineare).
    """
    try:
        qb = float(q_bassa)
        qa = float(q_alta)
    except (TypeError, ValueError):
        return {"valido": False, "errore": "Percentili di banda non validi.",
                "df_quantili": pd.DataFrame()}
    if not (0.0 <= qb < qa <= 100.0):
        return {"valido": False,
                "errore": "Percentili non validi: serve 0 <= P_bassa < P_alta <= 100.",
                "df_quantili": pd.DataFrame()}
    cols = ["Ora del giorno", "N ore", "Min (EUR/MWh)", f"P{qb:g} (EUR/MWh)",
            "P25 (EUR/MWh)", "P50 (EUR/MWh)", "P75 (EUR/MWh)",
            f"P{qa:g} (EUR/MWh)", "Max (EUR/MWh)", "Media (EUR/MWh)",
            "Ampiezza banda (EUR/MWh)"]
    vuoto = {"valido": False, "errore": None, "df_quantili": pd.DataFrame(columns=cols)}
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto, errore="Serie prezzi non valida.")
    if len(p) == 0:
        return dict(vuoto, errore="Serie prezzi vuota.")
    try:
        ore = np.array([t.hour for t in p.index])
    except Exception:
        return dict(vuoto, errore="Indice prezzi non valido (serve un DatetimeIndex).")
    vals = p.to_numpy(dtype=float)
    righe = []
    for h in range(24):
        v = vals[ore == h]
        if len(v) == 0:
            righe.append({"Ora del giorno": h, "N ore": 0,
                          "Min (EUR/MWh)": np.nan, f"P{qb:g} (EUR/MWh)": np.nan,
                          "P25 (EUR/MWh)": np.nan, "P50 (EUR/MWh)": np.nan,
                          "P75 (EUR/MWh)": np.nan, f"P{qa:g} (EUR/MWh)": np.nan,
                          "Max (EUR/MWh)": np.nan, "Media (EUR/MWh)": np.nan,
                          "Ampiezza banda (EUR/MWh)": np.nan})
            continue
        q = np.quantile(v, [qb / 100.0, 0.25, 0.5, 0.75, qa / 100.0])
        righe.append({"Ora del giorno": h, "N ore": int(len(v)),
                      "Min (EUR/MWh)": float(v.min()),
                      f"P{qb:g} (EUR/MWh)": float(q[0]),
                      "P25 (EUR/MWh)": float(q[1]),
                      "P50 (EUR/MWh)": float(q[2]),
                      "P75 (EUR/MWh)": float(q[3]),
                      f"P{qa:g} (EUR/MWh)": float(q[4]),
                      "Max (EUR/MWh)": float(v.max()),
                      "Media (EUR/MWh)": float(v.mean()),
                      "Ampiezza banda (EUR/MWh)": float(q[4] - q[0])})
    df = pd.DataFrame(righe, columns=cols)
    med = df["P50 (EUR/MWh)"].to_numpy(dtype=float)
    iqr = (df["P75 (EUR/MWh)"] - df["P25 (EUR/MWh)"]).to_numpy(dtype=float)
    if np.all(np.isnan(med)):
        return dict(vuoto, errore="Serie prezzi vuota.")
    ora_max = int(df.loc[np.nanargmax(med), "Ora del giorno"])
    ora_min = int(df.loc[np.nanargmin(med), "Ora del giorno"])
    ora_iqr = int(df.loc[np.nanargmax(iqr), "Ora del giorno"])
    return {"valido": True, "errore": None, "df_quantili": df,
            "n_ore": int(len(p)),
            "ora_mediana_max": ora_max, "ora_mediana_min": ora_min,
            "ora_iqr_max": ora_iqr,
            "ampiezza_banda_media": float(np.nanmean(df["Ampiezza banda (EUR/MWh)"].to_numpy(dtype=float))),
            "q_bassa": qb, "q_alta": qa}


def calcola_curva_forward_attesa(prezzi, prezzo_base=None, data_inizio=None,
                                 n_mesi=12, q_bassa=10.0, q_alta=90.0):
    """Curva forward mensile attesa: stagionalita' storica x prezzo forward base.

    Domanda operativa: "il broker mi quota il calendar a X EUR/MWh - come si
    ripartisce mese per mese per il mio budget energia?" Dai prezzi orari
    storici estrae il FATTORE STAGIONALE mensile (media del mese solare su
    tutti gli anni / media annuale, stessa logica del tab Stagionalita') e la
    dispersione intra-mese (quantili q_bassa/q_alta delle ore di quel mese su
    tutti gli anni). Il prezzo forward base inserito dall'utente (o, in
    mancanza, la media storica) viene scalato per i fattori: si ottiene la
    curva forward mensile attesa con banda di incertezza, pronta per budget,
    negoziazione e validazione delle quotazioni dei broker (confronto con il
    tab Strip forward).

    Ritorna dict con valido/errore, df_curva (Mese, Periodo, Fattore
    stagionale, Prezzo atteso, Banda bassa, Banda alta), prezzo_base_usato,
    mese_piu_caro / mese_piu_economico (dict {'periodo','prezzo'} o None),
    ampiezza_eur, ampiezza_pct, giudizio ('ALTA'/'MODERATA'/'CONTENUTA'
    stagionalita'), n_anni_storico, media_annua, q_bassa, q_alta.

    NaN-safe: serie vuota / indice non datetime / parametri non validi /
    media annua <= 0 / mese proiettato senza storico -> valido False con
    errore pulito, mai eccezioni. Deterministico (quantili numpy,
    interpolazione lineare).
    """
    try:
        qb = float(q_bassa)
        qa = float(q_alta)
    except (TypeError, ValueError):
        return {"valido": False, "errore": "Percentili di banda non validi.",
                "df_curva": pd.DataFrame()}
    if not (0.0 <= qb < qa <= 100.0):
        return {"valido": False,
                "errore": "Percentili non validi: serve 0 <= P_bassa < P_alta <= 100.",
                "df_curva": pd.DataFrame()}
    if isinstance(n_mesi, bool) or not isinstance(n_mesi, (int, np.integer)):
        return {"valido": False,
                "errore": "Numero di mesi non valido (serve un intero).",
                "df_curva": pd.DataFrame()}
    n_mesi = int(n_mesi)
    if not (1 <= n_mesi <= 36):
        return {"valido": False,
                "errore": "Numero di mesi non valido: serve un intero tra 1 e 36.",
                "df_curva": pd.DataFrame()}
    base_in = None
    if prezzo_base is not None:
        try:
            base_in = float(prezzo_base)
        except (TypeError, ValueError):
            return {"valido": False,
                    "errore": "Prezzo forward base non valido.",
                    "df_curva": pd.DataFrame()}
        if not np.isfinite(base_in) or base_in <= 0:
            return {"valido": False,
                    "errore": "Prezzo forward base non valido: deve essere > 0.",
                    "df_curva": pd.DataFrame()}
    cols = ["Mese", "Periodo", "Fattore stagionale",
            "Prezzo atteso (EUR/MWh)", "Banda bassa (EUR/MWh)",
            "Banda alta (EUR/MWh)"]
    vuoto = {"valido": False, "errore": None,
             "df_curva": pd.DataFrame(columns=cols)}
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto, errore="Serie prezzi non valida.")
    if len(p) == 0:
        return dict(vuoto, errore="Serie prezzi vuota.")
    try:
        idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
        mesi_idx = np.asarray(idxn.month)
    except Exception:
        return dict(vuoto, errore="Indice prezzi non valido (serve un DatetimeIndex).")
    vals = p.to_numpy(dtype=float)
    media_ann = float(vals.mean())
    if not np.isfinite(media_ann) or media_ann <= 0:
        return dict(vuoto, errore="Media annua non positiva: la curva non si puo' scalare.")
    stat = {}
    for m in range(1, 13):
        v = vals[mesi_idx == m]
        if len(v) == 0:
            continue
        qq = np.quantile(v, [qb / 100.0, qa / 100.0])
        media_m = float(v.mean())
        stat[m] = {"fattore": float(media_m / media_ann),
                   "p_bassa": float(qq[0]), "p_alta": float(qq[1]),
                   "media_m": media_m}
    try:
        if data_inizio is None:
            inizio = (pd.Timestamp(idxn.max()).normalize().replace(day=1)
                      + pd.offsets.MonthBegin(1))
        else:
            inizio = pd.Timestamp(data_inizio).normalize().replace(day=1)
    except Exception:
        return dict(vuoto, errore="Data di inizio proiezione non valida.")
    periodi = pd.date_range(start=inizio, periods=n_mesi, freq="MS")
    mancanti = sorted({int(d.month) for d in periodi if int(d.month) not in stat})
    if mancanti:
        return dict(vuoto, errore="Storico insufficiente: nessun dato per "
                   + ", ".join(f"mese {m}" for m in mancanti) + ".")
    base = base_in if base_in is not None else media_ann
    nomi = ["Gen", "Feb", "Mar", "Apr", "Mag", "Giu",
            "Lug", "Ago", "Set", "Ott", "Nov", "Dic"]
    righe = []
    for d in periodi:
        m = int(d.month)
        s = stat[m]
        atteso = base * s["fattore"]
        if s["media_m"] > 0:
            bb = atteso * s["p_bassa"] / s["media_m"]
            ba = atteso * s["p_alta"] / s["media_m"]
        else:
            bb, ba = atteso, atteso
        righe.append({"Mese": d.strftime("%Y-%m"),
                      "Periodo": f"{nomi[m - 1]} {d.year}",
                      "Fattore stagionale": round(s["fattore"], 3),
                      "Prezzo atteso (EUR/MWh)": round(atteso, 2),
                      "Banda bassa (EUR/MWh)": round(bb, 2),
                      "Banda alta (EUR/MWh)": round(ba, 2)})
    df = pd.DataFrame(righe, columns=cols)
    att = df["Prezzo atteso (EUR/MWh)"].to_numpy(dtype=float)
    i_max, i_min = int(np.argmax(att)), int(np.argmin(att))
    amp = float(att[i_max] - att[i_min])
    media_att = float(att.mean())
    amp_pct = float(amp / media_att * 100.0) if media_att != 0 else 0.0
    if amp_pct >= 30.0:
        giudizio = "ALTA"
    elif amp_pct >= 15.0:
        giudizio = "MODERATA"
    else:
        giudizio = "CONTENUTA"
    return {"valido": True, "errore": None, "df_curva": df,
            "prezzo_base_usato": base,
            "mese_piu_caro": {"periodo": df.loc[i_max, "Periodo"],
                              "prezzo": float(att[i_max])},
            "mese_piu_economico": {"periodo": df.loc[i_min, "Periodo"],
                                   "prezzo": float(att[i_min])},
            "ampiezza_eur": amp, "ampiezza_pct": amp_pct,
            "giudizio": giudizio, "n_anni_storico": int(idxn.year.nunique()),
            "media_annua": media_ann, "q_bassa": qb, "q_alta": qa}


def calcola_costo_ritardo_fixing(prezzi, settimane_attesa=4, soglia_eur=5.0):
    """Costo atteso del ritardo di fissazione: replay storico del 'wait k weeks'.

    Domanda operativa: "devo fissare un prezzo a termine - quanto mi costa
    ASPETTARE k settimane prima di fissare?" La serie oraria viene aggregata in
    medie settimanali di calendario; per ogni settimana dello storico si misura
    la variazione del prezzo medio a distanza di k settimane
    (Delta_k = media(t) - media(t-k), rolling sulle settimane). La distribuzione
    dei Delta storici e' la stima empirica del costo del ritardo: per un
    COMPRATORE, Delta > 0 = aspettare e' costato di piu' (rimpianto),
    Delta < 0 = aspettare ha fatto risparmiare. Statistiche: costo atteso
    (media dei Delta), mediana, P10/P90, probabilita' di risparmio aspettando,
    probabilita' che il ritardo costi piu' della soglia di tolleranza,
    rimpianto massimo storico e miglior risparmio storico. La 'curva del
    rimpianto' ripete il calcolo per k = 1..K_max e mostra come il rischio di
    timing cresce con l'orizzonte (E|Delta_k| e P90). Giudizio sul rischio di
    timing: spread P90-P10 rapportato al prezzo medio settimanale
    (ALTO >= 25%, MODERATO >= 10%, CONTENUTA sotto; NON VALUTABILE se il prezzo
    medio settimanale non e' positivo).

    Ritorna dict con valido/errore, df_settimane (Settimana, Prezzo medio
    (EUR/MWh)), df_delta (Settimana, Variazione (EUR/MWh)) per il k scelto,
    costo_atteso, mediana_delta, std_delta, p10, p90, prob_risparmio,
    prob_sopra_soglia, max_rimpianto, max_risparmio, prezzo_medio_settimanale,
    df_curva_rimpianto (Settimane di attesa, Costo atteso |Delta| (EUR/MWh),
    P90 Delta (EUR/MWh), Media Delta (EUR/MWh)), giudizio, n_settimane, n_oss,
    settimane_attesa, soglia_eur.
    """
    def _err(msg):
        return {"valido": False, "errore": msg}
    # --- validazione parametri ---
    if isinstance(settimane_attesa, bool) or not isinstance(settimane_attesa, (int, np.integer)):
        return _err("settimane_attesa deve essere un intero tra 1 e 26.")
    k = int(settimane_attesa)
    if not 1 <= k <= 26:
        return _err("settimane_attesa deve essere un intero tra 1 e 26.")
    if isinstance(soglia_eur, bool):
        return _err("soglia_eur deve essere un numero >= 0.")
    try:
        soglia = float(soglia_eur)
    except (TypeError, ValueError):
        return _err("soglia_eur deve essere un numero >= 0.")
    if not np.isfinite(soglia) or soglia < 0:
        return _err("soglia_eur deve essere un numero finito >= 0.")
    # --- pulizia serie ---
    try:
        s = pd.Series(prezzi)
    except Exception:
        return _err("prezzi: serie non valida.")
    if s.empty:
        return _err("prezzi: serie vuota.")
    try:
        idx = pd.DatetimeIndex(s.index)
    except Exception:
        return _err("prezzi: indice non datetime.")
    if idx.tz is not None:
        idx = idx.tz_localize(None)
    s = pd.Series(pd.to_numeric(s, errors="coerce").to_numpy(), index=idx)
    s = s[~s.index.isna()].dropna()
    if s.empty:
        return _err("prezzi: nessun valore numerico valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    # --- medie settimanali di calendario ---
    try:
        sett = s.resample("W").mean().dropna()
    except Exception as e:
        return _err(f"aggregazione settimanale fallita: {e}")
    n_sett = int(len(sett))
    if n_sett < k + 2:
        return _err(f"serie troppo corta: servono almeno {k + 2} settimane di "
                    f"calendario per un'attesa di {k} settimane (disponibili {n_sett}).")
    delta = sett.diff(k).dropna()
    n_oss = int(len(delta))
    vals = delta.to_numpy(dtype=float)
    prezzo_medio = float(np.nanmean(sett.to_numpy(dtype=float)))
    costo_atteso = float(np.nanmean(vals))
    mediana = float(np.nanmedian(vals))
    std = float(np.nanstd(vals, ddof=1)) if n_oss >= 2 else float("nan")
    p10 = float(np.nanquantile(vals, 0.10))
    p90 = float(np.nanquantile(vals, 0.90))
    prob_risparmio = float(np.mean(vals < 0.0))
    prob_sopra_soglia = float(np.mean(vals > soglia))
    max_rimpianto = float(np.nanmax(vals))
    max_risparmio = float(np.nanmin(vals))  # Delta piu' negativo = miglior risparmio
    # --- giudizio sul rischio di timing ---
    if not np.isfinite(prezzo_medio) or prezzo_medio <= 0:
        giudizio = "NON VALUTABILE"
        spread_pct = float("nan")
    else:
        spread_pct = float((p90 - p10) / prezzo_medio * 100.0)
        if spread_pct >= 25.0:
            giudizio = "ALTO"
        elif spread_pct >= 10.0:
            giudizio = "MODERATO"
        else:
            giudizio = "CONTENUTA"
    # --- curva del rimpianto: k = 1..K_max ---
    k_max = min(26, n_sett - 2)
    righe = []
    for kk in range(1, k_max + 1):
        dk = sett.diff(kk).dropna().to_numpy(dtype=float)
        righe.append({"Settimane di attesa": kk,
                      "Costo atteso |Delta| (EUR/MWh)": float(np.mean(np.abs(dk))),
                      "P90 Delta (EUR/MWh)": float(np.nanquantile(dk, 0.90)),
                      "Media Delta (EUR/MWh)": float(np.mean(dk)),
                      "N osservazioni": int(len(dk))})
    df_curva = pd.DataFrame(righe)
    df_settimane = pd.DataFrame({"Settimana": sett.index.strftime("%Y-%m-%d"),
                                 "Prezzo medio (EUR/MWh)": sett.to_numpy(dtype=float)})
    df_d = pd.DataFrame({"Settimana": delta.index.strftime("%Y-%m-%d"),
                         "Variazione (EUR/MWh)": vals})
    return {"valido": True, "errore": None,
            "df_settimane": df_settimane, "df_delta": df_d,
            "costo_atteso": costo_atteso, "mediana_delta": mediana,
            "std_delta": std, "p10": p10, "p90": p90,
            "prob_risparmio": prob_risparmio,
            "prob_sopra_soglia": prob_sopra_soglia,
            "max_rimpianto": max_rimpianto, "max_risparmio": max_risparmio,
            "prezzo_medio_settimanale": prezzo_medio,
            "spread_p90_p10_pct": spread_pct,
            "df_curva_rimpianto": df_curva,
            "giudizio": giudizio, "n_settimane": n_sett, "n_oss": n_oss,
            "settimane_attesa": k, "soglia_eur": soglia}


def calcola_slippage_esecuzione(prezzi, mw, giorni_fornitura=30,
                                giorni_esecuzione=10, direzione="acquisto",
                                liquidita_giornaliera_mwh=50000.0,
                                coeff_impatto=0.5, prezzo_riferimento=None):
    """Slippage di esecuzione di un ordine di copertura a blocchi.

    Domanda operativa: "devo coprire Q MW baseload per D giorni di fornitura
    - se eseguo l'ordine in N tranche giornaliere, quanto mi costa l'impatto
    di mercato e quanto rischio di timing mi prendo?" La serie oraria viene
    aggregata in medie giornaliere; la finestra di esecuzione sono i primi
    n = min(giorni_esecuzione, giorni disponibili) giorni del periodo.

      - MWh totali = MW x 24 h x giorni_fornitura; ogni tranche compra/vende
        totale/n MWh al prezzo medio del giorno.
      - Impatto di mercato temporaneo (modello a radice quadrata):
        impatto = coeff x sqrt(MWh_tranche / liquidita_giornaliera).
        In acquisto il prezzo eseguito e' P x (1 + impatto), in vendita
        P x (1 - impatto).
      - Prezzo di arrivo = prezzo_riferimento se dato, altrimenti media del
        primo giorno di esecuzione; costo "carta" = MWh totali x arrivo.
      - Slippage = eseguito - carta (acquisto) oppure carta - eseguito
        (vendita): positivo = l'esecuzione e' costata di piu' del riferimento;
        negativo = il mercato si e' mosso a favore durante l'esecuzione.
      - Rischio di timing = std(prezzi giornalieri della finestra, ddof=1)
        x MWh totali: quanto balla il costo se il prezzo si muove mentre
        esegui.
      - Frontiera di esecuzione: per k = 1..min(30, giorni) ricalcola
        slippage e rischio di timing - piu' tranche = meno impatto ma
        (in genere) piu' esposizione al movimento dei prezzi.

    Giudizio sullo slippage % del nozionale: TRASCURABILE < 0.5%,
    MODERATO < 2%, RILEVANTE >= 2% (uno slippage negativo rientra in
    TRASCURABILE: il mercato si e' mosso a favore).

    Ritorna dict con valido/errore, df_slice (Data, Prezzo medio (EUR/MWh),
    MWh, Impatto (%), Prezzo eseguito (EUR/MWh), Controvalore (EUR)),
    df_frontiera (Tranche giornaliere, Slippage (EUR), Slippage (EUR/MWh),
    Rischio di timing (EUR)), totale_mwh, mwh_tranche, n_tranche, impatto,
    prezzo_arrivo, costo_carta, costo_eseguito, slippage_eur,
    slippage_eur_mwh, slippage_pct, rischio_timing_eur, giudizio,
    n_giorni, direzione, giorni_fornitura.
    """
    def _err(msg):
        return {"valido": False, "errore": msg}
    # --- validazione parametri ---
    if isinstance(mw, bool):
        return _err("mw deve essere un numero > 0.")
    try:
        mw_f = float(mw)
    except (TypeError, ValueError):
        return _err("mw deve essere un numero > 0.")
    if not np.isfinite(mw_f) or mw_f <= 0:
        return _err("mw deve essere un numero > 0.")
    for _nome, _val, _vmin, _vmax in (("giorni_fornitura", giorni_fornitura, 1, 365),
                                      ("giorni_esecuzione", giorni_esecuzione, 1, 90)):
        if isinstance(_val, bool) or not isinstance(_val, (int, np.integer)):
            return _err(f"{_nome} deve essere un intero tra {_vmin} e {_vmax}.")
        if not _vmin <= int(_val) <= _vmax:
            return _err(f"{_nome} deve essere un intero tra {_vmin} e {_vmax}.")
    gf = int(giorni_fornitura)
    ge = int(giorni_esecuzione)
    if direzione not in ("acquisto", "vendita"):
        return _err("direzione deve essere 'acquisto' o 'vendita'.")
    if isinstance(liquidita_giornaliera_mwh, bool):
        return _err("liquidita_giornaliera_mwh deve essere un numero > 0.")
    try:
        liq = float(liquidita_giornaliera_mwh)
    except (TypeError, ValueError):
        return _err("liquidita_giornaliera_mwh deve essere un numero > 0.")
    if not np.isfinite(liq) or liq <= 0:
        return _err("liquidita_giornaliera_mwh deve essere un numero > 0.")
    if isinstance(coeff_impatto, bool):
        return _err("coeff_impatto deve essere un numero >= 0.")
    try:
        coeff = float(coeff_impatto)
    except (TypeError, ValueError):
        return _err("coeff_impatto deve essere un numero >= 0.")
    if not np.isfinite(coeff) or coeff < 0:
        return _err("coeff_impatto deve essere un numero >= 0.")
    if prezzo_riferimento is None:
        pref = None
    else:
        if isinstance(prezzo_riferimento, bool):
            return _err("prezzo_riferimento deve essere None oppure un numero > 0.")
        try:
            pref = float(prezzo_riferimento)
        except (TypeError, ValueError):
            return _err("prezzo_riferimento deve essere None oppure un numero > 0.")
        if not np.isfinite(pref) or pref <= 0:
            return _err("prezzo_riferimento deve essere None oppure un numero > 0.")
    # --- pulizia serie ---
    try:
        s = pd.Series(prezzi)
    except Exception:
        return _err("prezzi: serie non valida.")
    if s.empty:
        return _err("prezzi: serie vuota.")
    try:
        idx = pd.DatetimeIndex(s.index)
    except Exception:
        return _err("prezzi: indice non datetime.")
    if idx.tz is not None:
        idx = idx.tz_localize(None)
    s = pd.Series(pd.to_numeric(s, errors="coerce").to_numpy(), index=idx)
    s = s[~s.index.isna()].dropna()
    if s.empty:
        return _err("prezzi: nessun valore numerico valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    # --- medie giornaliere di calendario ---
    try:
        gg = s.resample("D").mean().dropna()
    except Exception as e:
        return _err(f"aggregazione giornaliera fallita: {e}")
    n_gg = int(len(gg))
    if n_gg < 2:
        return _err("serie troppo corta: servono almeno 2 giorni di calendario.")
    n = min(ge, n_gg)
    prezzi_g = gg.iloc[:n].to_numpy(dtype=float)
    date_g = gg.index[:n]
    # --- ordine ed esecuzione ---
    totale_mwh = float(mw_f * 24.0 * gf)
    q_slice = totale_mwh / n
    impatto = float(coeff * np.sqrt(q_slice / liq))
    arrival = float(pref) if pref is not None else float(prezzi_g[0])
    if direzione == "acquisto":
        prezzi_exec = prezzi_g * (1.0 + impatto)
    else:
        prezzi_exec = prezzi_g * (1.0 - impatto)
    costo_eseguito = float(q_slice * prezzi_exec.sum())
    costo_carta = float(totale_mwh * arrival)
    if direzione == "acquisto":
        slippage = costo_eseguito - costo_carta
    else:
        slippage = costo_carta - costo_eseguito
    slippage_mwh = slippage / totale_mwh
    slippage_pct = (slippage / costo_carta * 100.0) if costo_carta != 0 else float("nan")
    rischio_timing = float(np.std(prezzi_g, ddof=1) * totale_mwh) if n >= 2 else 0.0
    if not np.isfinite(slippage_pct) or slippage_pct < 0.5:
        giudizio = "TRASCURABILE"
    elif slippage_pct < 2.0:
        giudizio = "MODERATO"
    else:
        giudizio = "RILEVANTE"
    # --- dettaglio tranche ---
    df_slice = pd.DataFrame({
        "Data": [d.strftime("%Y-%m-%d") for d in date_g],
        "Prezzo medio (EUR/MWh)": np.round(prezzi_g, 2),
        "MWh": np.round(np.full(n, q_slice), 1),
        "Impatto (%)": np.round(np.full(n, impatto * 100.0), 3),
        "Prezzo eseguito (EUR/MWh)": np.round(prezzi_exec, 2),
        "Controvalore (EUR)": np.round(q_slice * prezzi_exec, 2),
    })
    # --- frontiera di esecuzione k = 1..min(30, n_gg) ---
    k_max = min(30, n_gg)
    righe = []
    for k in range(1, k_max + 1):
        qk = totale_mwh / k
        impk = float(coeff * np.sqrt(qk / liq))
        pgk = gg.iloc[:k].to_numpy(dtype=float)
        if direzione == "acquisto":
            exk = float(qk * (pgk * (1.0 + impk)).sum())
            slk = exk - costo_carta
        else:
            exk = float(qk * (pgk * (1.0 - impk)).sum())
            slk = costo_carta - exk
        rtk = float(np.std(pgk, ddof=1) * totale_mwh) if k >= 2 else 0.0
        righe.append({"Tranche giornaliere": k, "Slippage (EUR)": slk,
                      "Slippage (EUR/MWh)": slk / totale_mwh,
                      "Rischio di timing (EUR)": rtk})
    df_frontiera = pd.DataFrame(righe)
    return {"valido": True, "errore": None, "df_slice": df_slice,
            "df_frontiera": df_frontiera, "totale_mwh": totale_mwh,
            "mwh_tranche": q_slice, "n_tranche": n, "impatto": impatto,
            "impatto_pct": impatto * 100.0, "prezzo_arrivo": arrival,
            "costo_carta": costo_carta, "costo_eseguito": costo_eseguito,
            "slippage_eur": slippage, "slippage_eur_mwh": slippage_mwh,
            "slippage_pct": slippage_pct, "rischio_timing_eur": rischio_timing,
            "giudizio": giudizio, "n_giorni": n_gg,
            "direzione": direzione, "giorni_fornitura": gf}


def calcola_scala_copertura(prezzi, mw_f1=2.0, mw_f2=2.0, mw_f3=2.0,
                            tranche=None, target_pct=80.0):
    """Scala di copertura mensile: quanta energia del periodo e' coperta a prezzo fisso.

    Domanda operativa: "mese per mese, che quota del mio carico e' gia'
    fissata a prezzo fisso e dove resto esposto al mercato?" - la scala
    confronta il carico mensile (da profilo MW F1/F2/F3) con le tranche di
    copertura inserite (nome, MW, inizio, fine, prezzo fisso) e segnala i
    mesi sotto il target di copertura della policy di procurement.

    Metodo: carico orario MW dalle fasce AEEGSI via `fascia_oraria`;
    per ogni tranche valida, le ore la cui data e' compresa tra inizio e
    fine (estremi inclusi) accumulano MW coperti e controvalore a prezzo
    fisso; aggregazione mensile su Period M; quota = coperto / carico * 100;
    prezzo medio coperture = controvalore / MWh coperti (ponderato);
    scoperto = max(carico - coperto, 0); over-hedge se quota > 100.

    tranche: DataFrame (da st.data_editor) o lista di dict con colonne
    "Tranche", "MW", "Inizio", "Fine", "Prezzo (€/MWh)". Le righe non
    valide (date non parsabili, inizio > fine, MW <= 0, prezzo non
    numerico) vengono scartate e contate in `n_tranche_scartate`.

    KPI: quota coperta media ponderata sul periodo, n. mesi sotto target
    (+ elenco), prezzo medio ponderato delle coperture, MWh scoperti
    totali; tabella mensile (Mese, Carico, Coperto, Quota %, Prezzo medio
    coperture, Scoperto, Stato); giudizio COPERTURA OK / ATTENZIONE /
    NESSUNA COPERTURA; verdetto con mesi critici e nota sull'over-hedge.

    NaN-safe: serie vuota / indice non datetime / MW tutti <= 0 /
    target fuori (0, 100] / formato tranche non valido -> errore pulito;
    nessuna tranche -> valido con quote a 0 (tutto scoperto); tz-aware
    reso naive; duplicati keep-first; prezzi NaN scartati e contati.
    Deterministico.
    """

    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        mws = [float(mw_f1), float(mw_f2), float(mw_f3)]
        target = float(target_pct)
    except (TypeError, ValueError):
        return _err("Parametri non validi.")
    if not all(np.isfinite(m) and m >= 0 for m in mws):
        return _err("I MW per fascia devono essere >= 0.")
    if sum(mws) <= 0:
        return _err("Imposta una potenza maggiore di zero in almeno una fascia.")
    if not np.isfinite(target) or not (0.0 < target <= 100.0):
        return _err("Il target di copertura deve essere tra 0 e 100 (escluso lo 0).")
    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series di prezzi orari.")
    try:
        idx = pd.to_datetime(prezzi.index, errors="coerce")
    except Exception:
        return _err("Indice non convertibile a datetime.")
    if idx.isna().all():
        return _err("Indice non datetime.")
    vals = pd.to_numeric(prezzi.values, errors="coerce")
    okm = ~idx.isna()
    idx, vals = idx[okm], vals[okm]
    if len(idx) == 0:
        return _err("Serie prezzi vuota.")
    n_nan = int(np.isnan(vals).sum())
    dfp = pd.DataFrame({"prezzo": vals}, index=idx).dropna(subset=["prezzo"])
    if dfp.index.tz is not None:
        dfp.index = dfp.index.tz_localize(None)
    dfp = dfp[~dfp.index.duplicated(keep="first")].sort_index()
    if len(dfp) == 0:
        return _err("Serie prezzi vuota dopo la pulizia dei NaN.")

    fasce = dfp.index.map(fascia_oraria)
    mw_h = fasce.map({"F1": mws[0], "F2": mws[1], "F3": mws[2]}).astype(float).to_numpy()

    if isinstance(tranche, pd.DataFrame):
        righe = tranche.to_dict("records")
    elif isinstance(tranche, (list, tuple)):
        righe = list(tranche)
    elif tranche is None:
        righe = []
    else:
        return _err("Formato tranche non valido: serve DataFrame o lista di dict.")
    t_valide, n_scartate = [], 0
    for r in righe:
        try:
            d = dict(r)
            nome = str(d.get("Tranche") or "Tranche").strip() or "Tranche"
            mw = float(d.get("MW"))
            px = float(d.get("Prezzo (€/MWh)"))
            g1 = pd.to_datetime(d.get("Inizio"), errors="coerce")
            g2 = pd.to_datetime(d.get("Fine"), errors="coerce")
        except (TypeError, ValueError, AttributeError):
            n_scartate += 1
            continue
        if pd.isna(g1) or pd.isna(g2):
            n_scartate += 1
            continue
        if g1.tzinfo is not None:
            g1 = g1.tz_localize(None)
        if g2.tzinfo is not None:
            g2 = g2.tz_localize(None)
        g1, g2 = g1.normalize(), g2.normalize()
        if not (np.isfinite(mw) and mw > 0):
            n_scartate += 1
            continue
        if not np.isfinite(px):
            n_scartate += 1
            continue
        if g2 < g1:
            n_scartate += 1
            continue
        t_valide.append({"nome": nome, "mw": mw, "prezzo": px,
                         "inizio": g1, "fine": g2})

    giorni = dfp.index.normalize().to_numpy()
    hedge_mw = np.zeros(len(dfp))
    hedge_eur = np.zeros(len(dfp))
    for t in t_valide:
        mask = (giorni >= t["inizio"].to_numpy()) & (giorni <= t["fine"].to_numpy())
        hedge_mw[mask] += t["mw"]
        hedge_eur[mask] += t["mw"] * t["prezzo"]

    mese = dfp.index.to_period("M")
    dfh = pd.DataFrame({"carico": mw_h, "coperto": hedge_mw, "controval": hedge_eur})
    gm = dfh.groupby(mese)
    carico_m = gm["carico"].sum()
    coperto_m = gm["coperto"].sum()
    controval_m = gm["controval"].sum()

    righe_m, mesi_sotto, mesi_over = [], [], []
    for per in carico_m.index:
        car = float(carico_m.loc[per])
        cop = float(coperto_m.loc[per])
        cv = float(controval_m.loc[per])
        quota = (cop / car * 100.0) if car > 0 else 0.0
        pm = (cv / cop) if cop > 0 else None
        sco = max(car - cop, 0.0)
        over = quota > 100.0
        sotto = quota < target
        if sotto:
            mesi_sotto.append(str(per))
        if over:
            mesi_over.append(str(per))
        stato = "OVER-HEDGE" if over else ("SOTTO TARGET" if sotto else "OK")
        righe_m.append({
            "Mese": str(per),
            "Carico (MWh)": round(car, 1),
            "Coperto (MWh)": round(cop, 1),
            "Quota (%)": round(quota, 1),
            "Prezzo medio coperture (€/MWh)": round(pm, 2) if pm is not None else None,
            "Scoperto (MWh)": round(sco, 1),
            "Stato": stato,
        })
    tabella = pd.DataFrame(righe_m)

    car_tot = float(carico_m.sum())
    cop_tot = float(coperto_m.sum())
    quota_media = (cop_tot / car_tot * 100.0) if car_tot > 0 else 0.0
    pm_tot = (float(controval_m.sum()) / cop_tot) if cop_tot > 0 else None
    mwh_scoperti = max(car_tot - cop_tot, 0.0)

    if not t_valide:
        giudizio = "NESSUNA COPERTURA"
        verdetto = ("Nessuna tranche di copertura valida inserita: tutto il carico "
                    "resta esposto al mercato spot. Aggiungi righe nella tabella "
                    "tranche per simulare la scala di copertura.")
    elif not mesi_sotto and not mesi_over:
        giudizio = "COPERTURA OK"
        verdetto = (f"Tutti i {len(righe_m)} mesi sono sopra il target del "
                    f"{target:.0f} % (quota media {quota_media:.1f} %).")
    elif not mesi_sotto:
        giudizio = "COPERTURA OK"
        verdetto = (f"Tutti i mesi sono sopra il target del {target:.0f} %, ma "
                    f"{len(mesi_over)} mese/i in over-hedge "
                    f"({', '.join(mesi_over)}): quota oltre il 100% del carico.")
    else:
        giudizio = "ATTENZIONE"
        verdetto = (f"{len(mesi_sotto)} mese/i sotto il target del {target:.0f} %: "
                    f"{', '.join(mesi_sotto)}. Aumenta le tranche su quei mesi o "
                    f"accetta l'esposizione residua.")
        if mesi_over:
            verdetto += f" Over-hedge in: {', '.join(mesi_over)}."

    ts_mesi = carico_m.index.to_timestamp()
    quota_m = (coperto_m / carico_m * 100.0).fillna(0.0)
    serie_quota = pd.Series(quota_m.to_numpy(), index=ts_mesi, name="Quota (%)")
    serie_coperto = pd.Series(coperto_m.to_numpy(), index=ts_mesi, name="Coperto (MWh)")
    serie_scoperto = pd.Series((carico_m - coperto_m).clip(lower=0).to_numpy(),
                               index=ts_mesi, name="Scoperto (MWh)")

    return {
        "errore": None, "valido": True,
        "tabella_mensile": tabella,
        "quota_media_pct": round(quota_media, 2),
        "n_mesi_sotto_target": len(mesi_sotto),
        "mesi_sotto_target": mesi_sotto,
        "mesi_over_hedge": mesi_over,
        "prezzo_medio_coperture": round(pm_tot, 2) if pm_tot is not None else None,
        "mwh_scoperti": round(mwh_scoperti, 1),
        "mwh_carico_tot": round(car_tot, 1),
        "mwh_coperti_tot": round(cop_tot, 1),
        "n_tranche_valide": len(t_valide),
        "n_tranche_scartate": n_scartate,
        "target_pct": target,
        "n_nan_prezzi": n_nan,
        "giudizio": giudizio,
        "verdetto": verdetto,
        "serie_quota": serie_quota,
        "serie_coperto": serie_coperto,
        "serie_scoperto": serie_scoperto,
        "tranche_valide": [
            {"Tranche": t["nome"], "MW": t["mw"],
             "Inizio": t["inizio"].strftime("%Y-%m-%d"),
             "Fine": t["fine"].strftime("%Y-%m-%d"),
             "Prezzo (€/MWh)": t["prezzo"]} for t in t_valide
        ],
    }


def calcola_hellbrise(prezzi, cap_fv_mw=100.0, cap_eolico_mw=100.0,
                      percentile_hb=90.0, soglia_curtail_pct=80.0,
                      prezzo_curtail=0.0, min_giorni=7):
    """Giorni di hellbrise: quando sole e vento producono troppo.

    Domanda operativa: "quanto si perde nei giorni di eccesso
    rinnovabile?" - con alta penetrazione di FV+eolico, i giorni di
    sole pieno e vento forte saturano l'offerta e i prezzi crollano:
    questa tab quantifica lo SCONTO DI ECCESSO (cannibalizzazione)
    speculare alla dunkelflaute.

    Metodo: gli stessi profili sintetici deterministici `profilo_solare` /
    `profilo_eolico` della tab price capture generano la produzione oraria
    FV+eolico; fattore rinnovabile giornaliero = energia FV+eolico del
    giorno / (ore_giorno x capacita' totale). Giorno di hellbrise: fattore
    sopra il `percentile_hb`-esimo percentile della distribuzione del
    periodo (default 90: il miglior decile rinnovabile). Ore di potenziale
    curtailment: ore con fattore orario >= soglia_curtail_pct e prezzo <=
    prezzo_curtail (default: fattore >= 80% e prezzo <= 0).

    KPI: n giorni HB, quota % sul periodo, prezzo medio nei giorni HB,
    sconto di eccesso vs media periodo (EUR/MWh e %), tasso di cattura
    rinnovabile nel periodo e nei giorni HB, ore di potenziale
    curtailment (n, quota % sulle ore, MWh potenzialmente persi),
    peggior giorno HB (prezzo minimo), fattore rinnovabile medio nei
    giorni HB; tabella mensile (giorni totali, giorni HB, quota %,
    prezzo medio HB, prezzo mese, sconto, tasso di cattura HB);
    giudizio CANNIBALIZZAZIONE FORTE / MODERATA / CONTENUTA sullo sconto
    medio; verdetto con nota operativa su stoccaggio, domanda
    flessibile e struttura dei PPA.
    E' un'analisi di STRESS su profili sintetici, non una misura: serve a
    valutare il rischio di cattura dei ricavi rinnovabili, non a
    prevedere il meteo.

    NaN-safe: serie vuota / indice non datetime / < min_giorni giorni /
    capacita' <= 0 / percentile fuori (50, 100) / soglia curtailment fuori
    (0, 100] / min_giorni < 2 -> errore pulito; tz-aware reso naive;
    duplicati keep-first; prezzi NaN scartati e contati. Deterministico.
    """

    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        min_giorni = int(min_giorni)
    except (TypeError, ValueError):
        return _err("min_giorni non valido.")
    if min_giorni < 2:
        return _err("min_giorni deve essere almeno 2.")
    try:
        cap_fv = float(cap_fv_mw)
        cap_eo = float(cap_eolico_mw)
        perc = float(percentile_hb)
        soglia_c = float(soglia_curtail_pct)
        p_curt = float(prezzo_curtail)
    except (TypeError, ValueError):
        return _err("Parametri non validi.")
    for v in (cap_fv, cap_eo):
        if not np.isfinite(v) or v <= 0:
            return _err("Le capacita' FV ed eolico devono essere > 0.")
    if not np.isfinite(perc) or not (50.0 <= perc < 100.0):
        return _err("Il percentile deve essere tra 50 e 100 (escluso).")
    if not np.isfinite(soglia_c) or not (0.0 < soglia_c <= 100.0):
        return _err("La soglia di curtailment deve essere tra 0 e 100.")
    if not np.isfinite(p_curt):
        return _err("Il prezzo di curtailment non e' valido.")
    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series di prezzi orari.")
    try:
        idx = pd.to_datetime(prezzi.index, errors="coerce")
    except Exception:
        return _err("Indice non convertibile a datetime.")
    if idx.isna().all():
        return _err("Indice non datetime.")
    vals = pd.to_numeric(prezzi.values, errors="coerce")
    okm = ~idx.isna()
    idx, vals = idx[okm], vals[okm]
    if len(idx) == 0:
        return _err("Serie prezzi vuota.")
    n_nan = int(np.isnan(vals).sum())
    dfp = pd.DataFrame({"prezzo": vals}, index=idx).dropna(subset=["prezzo"])
    if dfp.index.tz is not None:
        dfp.index = dfp.index.tz_localize(None)
    dfp = dfp[~dfp.index.duplicated(keep="first")].sort_index()
    if len(dfp) == 0:
        return _err("Serie prezzi vuota dopo la pulizia dei NaN.")

    cap_tot = cap_fv + cap_eo
    gen_fv = profilo_solare(dfp["prezzo"], cap_fv)
    gen_eo = profilo_eolico(dfp["prezzo"], cap_eo)
    if len(gen_fv) == 0 or len(gen_eo) == 0:
        return _err("Profili di generazione non generati.")
    gen = (pd.to_numeric(gen_fv, errors="coerce").fillna(0.0)
           + pd.to_numeric(gen_eo, errors="coerce").fillna(0.0))
    gen = gen.reindex(dfp.index).fillna(0.0)

    giorni = dfp.index.floor("D")
    n_ore_g = giorni.value_counts().sort_index()
    en_g = gen.groupby(giorni).sum()
    p_g = dfp["prezzo"].groupby(giorni).mean()
    fattore = en_g / (n_ore_g.reindex(en_g.index) * cap_tot)
    if len(p_g) < min_giorni:
        return _err("Servono almeno %d giorni di dati (trovati %d)."
                    % (min_giorni, len(p_g)))

    lim = float(np.percentile(fattore.values, perc))
    is_hb = fattore >= lim
    n_hb = int(is_hb.sum())
    n_gg = len(p_g)
    quota = n_hb / n_gg * 100.0 if n_gg else 0.0
    p_medio = float(p_g.mean())
    fattore_medio_hb = float(fattore[is_hb].mean()) if n_hb else 0.0
    if n_hb:
        p_hb = float(p_g[is_hb].mean())
        sconto = p_medio - p_hb
        sconto_pct = sconto / p_medio * 100.0 if p_medio != 0 else None
        peggior_g = p_g[is_hb].idxmin()
        peggior_p = float(p_g[is_hb].min())
    else:
        p_hb, sconto, sconto_pct, peggior_g, peggior_p = None, None, None, None, None

    # Tasso di cattura rinnovabile: prezzo catturato / prezzo medio base.
    def _tasso(mask_ore):
        gsel = gen[mask_ore]
        psel = dfp["prezzo"][mask_ore]
        en = float(gsel.sum())
        if en <= 0:
            return None
        catt = float((psel * gsel).sum()) / en
        base = float(psel.mean())
        if base == 0 or not np.isfinite(base):
            return None
        return catt / base * 100.0

    tasso_per = _tasso(np.ones(len(dfp), dtype=bool))
    mask_hb = dfp.index.floor("D").isin(p_g[is_hb].index)
    tasso_hb = _tasso(mask_hb)

    # Ore di potenziale curtailment: tanta rinnovabile e prezzo basso.
    fattore_ora = gen / cap_tot
    ore_curt = (fattore_ora >= soglia_c / 100.0) & (dfp["prezzo"] <= p_curt)
    n_curt = int(ore_curt.sum())
    n_ore = len(dfp)
    quota_curt = n_curt / n_ore * 100.0 if n_ore else 0.0
    mwh_curt = float(gen[ore_curt].sum())

    if n_hb == 0:
        giudizio = "NESSUN GIORNO"
        nota_g = ("nessun giorno sopra il percentile scelto: abbassa il "
                  "percentile per allargare l'analisi.")
    elif sconto >= 15.0:
        giudizio = "CANNIBALIZZAZIONE FORTE"
        nota_g = ("i giorni di eccesso rinnovabile costano in media almeno "
                  "15 €/MWh meno della media: il rischio di cattura dei "
                  "ricavi rinnovabili e' materiale, servono stoccaggio, "
                  "domanda flessibile o coperture sul capture price.")
    elif sconto >= 5.0:
        giudizio = "CANNIBALIZZAZIONE MODERATA"
        nota_g = ("sconto di eccesso contenuto ma visibile: i giorni di "
                  "hellbrise rendono meno, da valutare nei mesi estivi e "
                  "nei PPA pay-as-produced.")
    else:
        giudizio = "CANNIBALIZZAZIONE CONTENUTA"
        nota_g = ("sconto di eccesso piccolo o nullo nel periodo: "
                  "l'hellbrise c'e' ma il mercato non la sconta (o i "
                  "prezzi dei giorni HB sono addirittura piu' alti).")

    mesi = []
    for periodo, grp in p_g.groupby(pd.PeriodIndex(p_g.index, freq="M")):
        ghb = is_hb.loc[grp.index]
        nh = int(ghb.sum())
        pm = float(grp.mean())
        phb = float(grp[ghb].mean()) if nh else None
        mask_m = dfp.index.floor("D").isin(grp[ghb].index)
        mesi.append({
            "Mese": str(periodo),
            "Giorni totali": len(grp),
            "Giorni hellbrise": nh,
            "Quota HB (%)": round(nh / len(grp) * 100.0, 1),
            "Prezzo medio HB (€/MWh)": round(phb, 2) if phb is not None else None,
            "Prezzo medio mese (€/MWh)": round(pm, 2),
            "Sconto HB (€/MWh)": round(pm - phb, 2) if phb is not None else None,
            "Tasso di cattura HB (%)": round(_tasso(mask_m), 1) if _tasso(mask_m) is not None else None,
        })
    tabella_mensile = pd.DataFrame(mesi)

    serie_fattore = fattore.rename("Fattore rinnovabile giornaliero")
    serie_prezzo_g = p_g.rename("Prezzo medio giornaliero (€/MWh)")

    if n_hb:
        verdetto = (
            "%d giorni di hellbrise su %d (%.1f %%, miglior %s-esimo "
            "percentile del fattore rinnovabile). Prezzo medio nei giorni HB: "
            "%.2f €/MWh contro %.2f €/MWh di media periodo: sconto di "
            "eccesso %+.2f €/MWh%s. Tasso di cattura rinnovabile: %s nel "
            "periodo, %s nei giorni HB. Ore di potenziale curtailment: %d "
            "(%.1f %%, %.0f MWh). Fattore rinnovabile medio nei giorni "
            "HB: %.1f %%. Peggior giorno: %s a %.2f €/MWh. %s" % (
                n_hb, n_gg, quota, ("%g" % perc), p_hb, p_medio, sconto,
                (" (%+.1f %%)" % sconto_pct) if sconto_pct is not None else "",
                ("%.1f %%" % tasso_per) if tasso_per is not None else "—",
                ("%.1f %%" % tasso_hb) if tasso_hb is not None else "—",
                n_curt, quota_curt, mwh_curt,
                fattore_medio_hb * 100.0,
                peggior_g.strftime("%d/%m/%Y"), peggior_p, nota_g))
    else:
        verdetto = ("%d giorni di dati, nessun giorno di hellbrise al "
                    "percentile scelto. %s" % (n_gg, nota_g))

    return {"errore": None, "valido": True,
            "n_giorni": n_gg, "n_hb": n_hb, "quota_hb_pct": quota,
            "percentile_hb": perc, "limite_fattore": lim,
            "cap_fv_mw": cap_fv, "cap_eolico_mw": cap_eo,
            "cap_tot_mw": cap_tot, "n_nan_prezzi": n_nan,
            "prezzo_medio": p_medio, "prezzo_medio_hb": p_hb,
            "sconto_eur_mwh": sconto, "sconto_pct": sconto_pct,
            "tasso_cattura_periodo": tasso_per,
            "tasso_cattura_hb": tasso_hb,
            "fattore_medio_hb": fattore_medio_hb,
            "peggior_giorno": peggior_g, "peggior_prezzo": peggior_p,
            "n_ore_curtailment": n_curt,
            "quota_ore_curtailment_pct": quota_curt,
            "mwh_curtailment": mwh_curt,
            "soglia_curtail_pct": soglia_c, "prezzo_curtail": p_curt,
            "serie_fattore": serie_fattore, "serie_prezzo_g": serie_prezzo_g,
            "giorni_hb": p_g[is_hb].index,
            "tabella_mensile": tabella_mensile,
            "giudizio": giudizio, "verdetto": verdetto}


def calcola_revenue_stacking(prezzi, pot_mw=2.0, cap_mwh=4.0, eff=0.85,
                             prezzo_fcr=18.0, prezzo_afrr=10.0,
                             ore_fcr=24.0, ore_afrr=24.0,
                             modo="ottimale", p_fcr=0.0, p_afrr=0.0,
                             lock_fcr_h=0.5, lock_afrr_h=1.0):
    """Revenue stacking batteria: arbitraggio day-ahead + riserva FCR + riserva aFRR.

    Domanda operativa: "ho una batteria da P MW / C MWh - come ripartisco la
    potenza tra arbitraggio sul day-ahead, riserva primaria FCR e riserva
    secondaria aFRR per massimizzare il ricavo sul periodo dei prezzi,
    rispettando i vincoli di potenza e di energia?"

    Modello (deterministico, su prezzi storici):
      - Arbitraggio: 1 ciclo/giorno, spread netto giornaliero
        max(0, pmax - pmin/eff); energia per ciclo = min(cap_disp, P_arb x 2h).
      - FCR: ricavo = P_fcr x prezzo_fcr (EUR/MW/h) x ore_fcr x giorni.
      - aFRR: ricavo = P_afrr x prezzo_afrr x ore_afrr x giorni.
      - Vincoli: P_fcr + P_afrr + P_arb <= pot_mw; headroom di energia delle
        riserve (P_fcr x lock_fcr_h + P_afrr x lock_afrr_h) <= cap_mwh,
        altrimenti l'allocazione e' non fattibile.
      - modo "ottimale": griglia 21x21 su (P_fcr, P_afrr), P_arb = resto;
        tiene il massimo (a parita' il primo in ordine di scansione, cioe'
        piu' arbitraggio).
      - modo "manuale": usa p_fcr / p_afrr dati dall'utente.

    Giudizio: "STACKING VINCENTE" se l'ottimo usa >= 2 flussi con > 5% del
    ricavo ciascuno e batte il miglior flusso singolo; "FLUSSO DOMINANTE: X"
    se un flusso fa > 90% del ricavo; "MIX BILANCIATO" altrimenti;
    "NESSUN RICAVO" se il totale e' zero.

    Ritorna dict con valido/errore, modo, p_fcr, p_afrr, p_arb,
    r_fcr_eur, r_afrr_eur, r_arb_eur, ricavo_totale_eur, ricavo_medio_giorno,
    ricavo_per_mw_giorno, energia_lock_mwh, cap_residua_mwh, e_ciclo_mwh,
    quota_fcr_pct, quota_afrr_pct, quota_arb_pct, n_giorni,
    spread_medio_netto, df_giornaliero, df_griglia (solo modo ottimale),
    giudizio, verdetto, nome_miglior_singolo, miglior_singolo_eur.
    """
    def _err(msg):
        return {"valido": False, "errore": msg}

    # --- pulizia serie prezzi ---
    if not isinstance(prezzi, pd.Series):
        return _err("prezzi deve essere una Series pandas con indice datetime.")
    s = prezzi.copy()
    try:
        s.index = pd.to_datetime(s.index, errors="coerce")
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    if s.index.isna().any():
        return _err("prezzi deve avere un indice datetime valido.")
    try:
        if getattr(s.index, "tz", None) is not None:
            s.index = s.index.tz_localize(None)
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    s = pd.to_numeric(s, errors="coerce").dropna()
    if len(s) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")

    # --- validazione parametri ---
    def _pos(v, nome):
        if isinstance(v, bool):
            return None, f"{nome} deve essere un numero > 0."
        try:
            x = float(v)
        except (TypeError, ValueError):
            return None, f"{nome} deve essere un numero > 0."
        if not np.isfinite(x) or x <= 0:
            return None, f"{nome} deve essere un numero > 0."
        return x, None

    def _nonneg(v, nome):
        if isinstance(v, bool):
            return None, f"{nome} deve essere un numero >= 0."
        try:
            x = float(v)
        except (TypeError, ValueError):
            return None, f"{nome} deve essere un numero >= 0."
        if not np.isfinite(x) or x < 0:
            return None, f"{nome} deve essere un numero >= 0."
        return x, None

    pot_f, em = _pos(pot_mw, "pot_mw")
    if em:
        return _err(em)
    cap_f, em = _pos(cap_mwh, "cap_mwh")
    if em:
        return _err(em)
    eff_f, em = _pos(eff, "eff")
    if em:
        return _err(em)
    if eff_f > 1.0:
        return _err("eff deve essere tra 0 e 1.")
    pfcr_p, em = _nonneg(prezzo_fcr, "prezzo_fcr")
    if em:
        return _err(em)
    pafrr_p, em = _nonneg(prezzo_afrr, "prezzo_afrr")
    if em:
        return _err(em)
    for _nome, _v in (("ore_fcr", ore_fcr), ("ore_afrr", ore_afrr)):
        if isinstance(_v, bool):
            return _err(f"{_nome} deve essere un numero tra 0 e 24.")
        try:
            _x = float(_v)
        except (TypeError, ValueError):
            return _err(f"{_nome} deve essere un numero tra 0 e 24.")
        if not np.isfinite(_x) or not 0.0 <= _x <= 24.0:
            return _err(f"{_nome} deve essere un numero tra 0 e 24.")
    ore_fcr_f = float(ore_fcr)
    ore_afrr_f = float(ore_afrr)
    lock_f, em = _nonneg(lock_fcr_h, "lock_fcr_h")
    if em:
        return _err(em)
    lock_a, em = _nonneg(lock_afrr_h, "lock_afrr_h")
    if em:
        return _err(em)
    if modo not in ("ottimale", "manuale"):
        return _err("modo deve essere 'ottimale' o 'manuale'.")
    pf_m = pa_m = 0.0
    if modo == "manuale":
        pf_m, em = _nonneg(p_fcr, "p_fcr")
        if em:
            return _err(em)
        pa_m, em = _nonneg(p_afrr, "p_afrr")
        if em:
            return _err(em)
        if pf_m + pa_m > pot_f + 1e-9:
            return _err("p_fcr + p_afrr non puo' superare pot_mw.")

    # --- spread netti giornalieri ---
    giorni = []
    for giorno, grp in s.groupby(s.index.date):
        if len(grp) >= 4:
            giorni.append((giorno, float(grp.min()), float(grp.max())))
    if not giorni:
        return _err("Servono giorni con almeno 4 ore di prezzo per lo stacking.")
    n_giorni = len(giorni)
    spread_net = np.array([max(0.0, pmax - pmin / eff_f) for _, pmin, pmax in giorni])
    spread_sum = float(spread_net.sum())

    def _valuta(pf, pa):
        """Ricavi di un'allocazione; None se non fattibile."""
        p_arb = pot_f - pf - pa
        if p_arb < -1e-9:
            return None
        p_arb = max(p_arb, 0.0)
        lock = pf * lock_f + pa * lock_a
        cap_disp = cap_f - lock
        if cap_disp < -1e-9:
            return None
        cap_disp = max(cap_disp, 0.0)
        e_ciclo = min(cap_disp, p_arb * 2.0)
        r_arb = spread_sum * e_ciclo
        r_fcr = pf * pfcr_p * ore_fcr_f * n_giorni
        r_afrr = pa * pafrr_p * ore_afrr_f * n_giorni
        return {"p_arb": p_arb, "lock_mwh": lock, "cap_disp_mwh": cap_disp,
                "e_ciclo_mwh": e_ciclo, "r_arb": r_arb, "r_fcr": r_fcr,
                "r_afrr": r_afrr, "totale": r_arb + r_fcr + r_afrr}

    griglia = []
    best = None
    if modo == "ottimale":
        n_step = 20
        for i in range(n_step + 1):
            pf = pot_f * i / n_step
            for j in range(n_step + 1):
                pa = pot_f * j / n_step
                if pf + pa > pot_f + 1e-9:
                    continue
                v = _valuta(pf, pa)
                if v is None:
                    continue
                griglia.append((round(pf, 6), round(pa, 6), v["totale"]))
                if best is None or v["totale"] > best["totale"] + 1e-9:
                    best = {"p_fcr": pf, "p_afrr": pa, **v}
    else:
        v = _valuta(pf_m, pa_m)
        if v is None:
            return _err("Allocazione non fattibile: l'headroom di energia supera la capacita'.")
        best = {"p_fcr": pf_m, "p_afrr": pa_m, **v}

    # --- riferimenti a flusso singolo e giudizio ---
    def _tot(pf, pa):
        v = _valuta(pf, pa)
        return v["totale"] if v else 0.0

    singoli = {"FCR": _tot(pot_f, 0.0), "aFRR": _tot(0.0, pot_f),
               "arbitraggio": _tot(0.0, 0.0)}
    nome_best_singolo = max(singoli, key=singoli.get)
    best_singolo = singoli[nome_best_singolo]

    tot = best["totale"]
    if tot > 0:
        q_fcr, q_afrr, q_arb = best["r_fcr"] / tot, best["r_afrr"] / tot, best["r_arb"] / tot
    else:
        q_fcr = q_afrr = q_arb = 0.0
    n_attivi = sum(1 for q in (q_fcr, q_afrr, q_arb) if q > 0.05)
    if tot <= 0:
        giudizio = "NESSUN RICAVO"
        verdetto = ("Con questi prezzi nessun flusso genera ricavo: la batteria "
                    "resta ferma e non si ciclizza.")
    elif n_attivi >= 2 and tot > best_singolo * 1.001:
        giudizio = "STACKING VINCENTE"
        verdetto = (f"Il mix ottimale ({best['p_fcr']:.2f} MW FCR, {best['p_afrr']:.2f} MW aFRR, "
                    f"{best['p_arb']:.2f} MW arbitraggio) batte il miglior flusso singolo "
                    f"({nome_best_singolo}, {best_singolo:,.0f} EUR): lo stacking paga.")
    else:
        quote = {"FCR": q_fcr, "aFRR": q_afrr, "arbitraggio": q_arb}
        dom = max(quote, key=quote.get)
        if quote[dom] > 0.90:
            giudizio = f"FLUSSO DOMINANTE: {dom.upper()}"
            verdetto = (f"Il {dom} fa il {quote[dom] * 100:.0f}% del ricavo: dedica tutta la "
                        f"potenza a questo flusso, lo stacking non aggiunge valore.")
        else:
            giudizio = "MIX BILANCIATO"
            verdetto = ("Piu' flussi contribuiscono in modo simile: il mix ottimale "
                        "diversifica il ricavo senza un flusso chiaramente superiore.")

    # --- tabelle ---
    righe_g = []
    for (giorno, _pmin, _pmax), sn in zip(giorni, spread_net):
        r_arb_g = sn * best["e_ciclo_mwh"]
        r_fcr_g = best["p_fcr"] * pfcr_p * ore_fcr_f
        r_afrr_g = best["p_afrr"] * pafrr_p * ore_afrr_f
        righe_g.append({"Giorno": giorno, "Spread netto (EUR/MWh)": round(float(sn), 2),
                        "Ricavo arbitraggio (EUR)": round(r_arb_g, 2),
                        "Ricavo FCR (EUR)": round(r_fcr_g, 2),
                        "Ricavo aFRR (EUR)": round(r_afrr_g, 2),
                        "Ricavo totale (EUR)": round(r_arb_g + r_fcr_g + r_afrr_g, 2)})
    df_g = pd.DataFrame(righe_g)
    df_grid = pd.DataFrame(
        [{"P FCR (MW)": pf, "P aFRR (MW)": pa,
          "P arbitraggio (MW)": round(pot_f - pf - pa, 2),
          "Ricavo totale (EUR)": round(t, 2)} for pf, pa, t in griglia])

    return {"valido": True, "errore": None, "modo": modo,
            "p_fcr": best["p_fcr"], "p_afrr": best["p_afrr"], "p_arb": best["p_arb"],
            "r_fcr_eur": best["r_fcr"], "r_afrr_eur": best["r_afrr"],
            "r_arb_eur": best["r_arb"], "ricavo_totale_eur": tot,
            "ricavo_medio_giorno": tot / n_giorni,
            "ricavo_per_mw_giorno": tot / (pot_f * n_giorni),
            "energia_lock_mwh": best["lock_mwh"],
            "cap_residua_mwh": best["cap_disp_mwh"],
            "e_ciclo_mwh": best["e_ciclo_mwh"],
            "quota_fcr_pct": q_fcr * 100.0, "quota_afrr_pct": q_afrr * 100.0,
            "quota_arb_pct": q_arb * 100.0,
            "n_giorni": n_giorni, "spread_medio_netto": spread_sum / n_giorni,
            "df_giornaliero": df_g, "df_griglia": df_grid,
            "giudizio": giudizio, "verdetto": verdetto,
            "nome_miglior_singolo": nome_best_singolo,
            "miglior_singolo_eur": best_singolo,
            "singoli_eur": singoli}


def calcola_carbonio_implicito(prezzi, prezzo_gas_eur_mwh=40.0, heat_rate=2.0,
                               fattore_emissione_t_mwh_th=0.202,
                               vom_eur_mwh=3.0, prezzo_eua_riferimento=75.0):
    """CO2 implicita nello spark spread di un CCGT: quale prezzo della CO2
    azzera il margine ora per ora.

    Domanda operativa: "il mercato power sta prezzando la CO2 sopra o sotto
    il prezzo spot degli EUA?" — per un ciclo combinato a gas, il margine
    orario e'  P_h - G*HR - CO2*EF*HR - VOM.  Ponendolo a zero si ricava la
    CO2 implicita:  CO2_impl_h = (P_h - G*HR - VOM) / (EF*HR), in EUR/t.

    - prezzi: Series oraria dei prezzi elettrici (EUR/MWh, indice datetime;
      tz-aware reso naive come negli altri tab);
    - prezzo_gas_eur_mwh: prezzo del gas (EUR/MWh termico, scalare);
    - heat_rate: MWh termici per MWh elettrico (2.0 = rendimento 50%);
    - fattore_emissione_t_mwh_th: tCO2 per MWh termico di gas (0.202 default);
    - vom_eur_mwh: costi variabili O&M per MWh elettrico;
    - prezzo_eua_riferimento: prezzo spot EUA per il confronto (EUR/t).

    Ritorna dict con 'valido'/'errore', co2_media, co2_mediana, co2_p10,
    co2_p90, quota_sopra_riferimento_pct, ore_con_margine_positivo,
    clean_spark_medio (margine con l'EUA al prezzo di riferimento),
    giudizio, verdetto, df_oraria (Ora, Prezzo, CO2 implicita),
    df_mensile (Mese, CO2 implicita media, Ore).

    Giudizio: "CO2 SOPRA L'EUA" se la mediana implicita supera il riferimento
    di oltre il 10% (il power paga un premio carbone oltre l'EUA, tipico con
    margini termici tesi); "CO2 SOTTO L'EUA" se sta oltre il 10% sotto
    (marginale non a gas o spark depresso); "IN LINEA" altrimenti.

    NaN-safe: serie vuota / non numerica / indice non-datetime, parametri non
    validi -> errore pulito, mai eccezioni.
    """
    def _err(msg):
        return {"valido": False, "errore": msg}

    # --- pulizia serie prezzi ---
    if not isinstance(prezzi, pd.Series):
        return _err("prezzi deve essere una Series pandas con indice datetime.")
    s = prezzi.copy()
    try:
        s.index = pd.to_datetime(s.index, errors="coerce")
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    if s.index.isna().any():
        return _err("prezzi deve avere un indice datetime valido.")
    try:
        if getattr(s.index, "tz", None) is not None:
            s.index = s.index.tz_localize(None)
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    s = pd.to_numeric(s, errors="coerce").dropna()
    if len(s) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")

    # --- validazione parametri ---
    def _num(v, nome, minimo, massimo=None):
        if isinstance(v, bool):
            return None, f"{nome} deve essere un numero >= {minimo}."
        try:
            x = float(v)
        except (TypeError, ValueError):
            return None, f"{nome} deve essere un numero >= {minimo}."
        if not np.isfinite(x) or x < minimo:
            return None, f"{nome} deve essere un numero >= {minimo}."
        if massimo is not None and x > massimo:
            return None, f"{nome} deve essere un numero <= {massimo}."
        return x, None

    gas, em = _num(prezzo_gas_eur_mwh, "prezzo_gas_eur_mwh", 0.0)
    if em:
        return _err(em)
    hr, em = _num(heat_rate, "heat_rate", 1.0, 5.0)
    if em:
        return _err(em)
    ef, em = _num(fattore_emissione_t_mwh_th, "fattore_emissione_t_mwh_th", 1e-6)
    if em:
        return _err(em)
    vom, em = _num(vom_eur_mwh, "vom_eur_mwh", 0.0)
    if em:
        return _err(em)
    eua_ref, em = _num(prezzo_eua_riferimento, "prezzo_eua_riferimento", 0.0)
    if em:
        return _err(em)

    # --- calcolo ---
    denom = ef * hr  # tCO2 per MWh elettrico
    co2_impl = (s - gas * hr - vom) / denom
    spark_pulito = s - gas * hr - eua_ref * denom - vom

    media = float(co2_impl.mean())
    mediana = float(co2_impl.median())
    p10 = float(co2_impl.quantile(0.10))
    p90 = float(co2_impl.quantile(0.90))
    quota_sopra = float((co2_impl > eua_ref).mean() * 100.0)
    ore_pos = int((spark_pulito > 0).sum())
    spark_medio = float(spark_pulito.mean())

    if mediana > eua_ref * 1.10:
        giudizio = "CO2 SOPRA L'EUA"
        verdetto = ("Il mercato power prezza la CO2 oltre il 10% sopra lo spot "
                    "EUA: margini termici tesi o premio di scarsita' sul "
                    "marginale a gas.")
    elif mediana < eua_ref * 0.90:
        giudizio = "CO2 SOTTO L'EUA"
        verdetto = ("La CO2 implicita sta oltre il 10% sotto lo spot EUA: "
                    "spark spread depresso oppure il marginale non e' il gas "
                    "(carbone, idro, import).")
    else:
        giudizio = "IN LINEA"
        verdetto = ("La CO2 implicita e' allineata allo spot EUA (entro il "
                    "10%): il prezzo power riflette fedelmente gas + carbonio.")

    df_oraria = pd.DataFrame({
        "Ora": co2_impl.index,
        "Prezzo (EUR/MWh)": s.values.round(2),
        "CO2 implicita (EUR/t)": co2_impl.values.round(2),
    })
    mens = co2_impl.groupby(pd.Grouper(freq="M"))
    df_mensile = pd.DataFrame({
        "Mese": [d.strftime("%Y-%m") for d in mens.mean().index],
        "CO2 implicita media (EUR/t)": mens.mean().values.round(2),
        "Ore": mens.size().values,
    })

    return {"valido": True, "errore": None,
            "co2_media": media, "co2_mediana": mediana,
            "co2_p10": p10, "co2_p90": p90,
            "quota_sopra_riferimento_pct": quota_sopra,
            "ore_con_margine_positivo": ore_pos,
            "clean_spark_medio": spark_medio,
            "giudizio": giudizio, "verdetto": verdetto,
            "df_oraria": df_oraria, "df_mensile": df_mensile,
            "n_ore": len(s), "heat_rate": hr,
            "emissioni_t_mwh_e": denom}


def calcola_pompaggio(prezzi, pot_turbina_mw=100.0, pot_pompa_mw=100.0,
                      capacita_mwh=800.0, eff_turbina=0.90, eff_pompa=0.90,
                      livello_iniziale_pct=50.0, apporto_naturale_mw=0.0,
                      vom_eur_mwh=2.0, soglia_pompaggio_pct=25.0):
    """Arbitraggio day-ahead di un impianto di pompaggio idroelettrico.

    Domanda operativa: "ho turbina da P_t MW, pompa da P_p MW e bacino da
    C MWh — quanto ricavo pompando nelle ore piu' economiche e generando in
    quelle piu' care?"

    Simulazione oraria causale con strategia a soglie sui percentili
    giornalieri: ogni giorno si calcolano il percentile `soglia` e il
    percentile (100 - soglia) dei prezzi; ora per ora si pompa se il prezzo
    e' sotto la soglia bassa (e c'e' posto nel bacino), si genera se e' sopra
    la soglia alta (e c'e' acqua nel bacino), altrimenti fermo. L'apporto
    naturale (MWh/h gratuiti) modella i bacini alpini con afflussi propri.

    Dinamica del bacino (L = livello in MWh accumulati):
      pompaggio:   preleva E_p dalla rete,  L += E_p * eff_pompa
      generazione: scarica E_s dal bacino,   immette E_s * eff_turbina in rete
    Round-trip = eff_turbina * eff_pompa: lo spread deve superarlo piu' i
    VOM perche' il ciclo paghi.

    - prezzi: Series oraria EUR/MWh, indice datetime (tz-aware reso naive);
    - pot_turbina_mw / pot_pompa_mw: potenze nominali (> 0);
    - capacita_mwh: energia massima accumulabile nel bacino (> 0);
    - eff_turbina / eff_pompa: rendimenti in (0, 1];
    - livello_iniziale_pct: riempimento iniziale del bacino [0, 100];
    - apporto_naturale_mw: afflusso gratuito nel bacino (MWh per ora, >= 0);
    - vom_eur_mwh: costi variabili su ogni MWh movimentato (pompa+turbina);
    - soglia_pompaggio_pct: percentile giornaliero che separa le ore attive
      da quelle di fermo, in (0, 50).

    Ritorna dict con 'valido'/'errore', ricavo_generazione_eur,
    costo_pompaggio_eur, ricavo_lordo_eur, vom_totale_eur, ricavo_netto_eur,
    ricavo_eur_mw_giorno, spread_medio_catturato_eur_mwh,
    breakeven_spread_pct, energia_pompata_mwh, energia_generata_mwh,
    cicli_equivalenti, ore_pompaggio, ore_generazione, fattore_utilizzo_pct,
    livello_finale_pct, round_trip, giudizio, verdetto, df_oraria
    (Ora, Prezzo, Azione, Livello bacino, Energia pompata/generata),
    df_giornaliera, n_ore, n_giorni.

    Giudizio: "ARBITRAGGIO VINCENTE" se ricavo_netto > 0, altrimenti
    "NON CONVIENE" (gli spread non coprono perdite di round-trip + VOM).

    NaN-safe: serie vuota / non numerica / indice non-datetime, parametri non
    validi -> errore pulito, mai eccezioni.
    """
    def _err(msg):
        return {"valido": False, "errore": msg}

    # --- pulizia serie prezzi (stesso schema delle altre tab) ---
    if not isinstance(prezzi, pd.Series):
        return _err("prezzi deve essere una Series pandas con indice datetime.")
    s = prezzi.copy()
    try:
        s.index = pd.to_datetime(s.index, errors="coerce")
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    if s.index.isna().any():
        return _err("prezzi deve avere un indice datetime valido.")
    try:
        if getattr(s.index, "tz", None) is not None:
            s.index = s.index.tz_localize(None)
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    s = pd.to_numeric(s, errors="coerce").dropna()
    if len(s) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")

    # --- validazione parametri ---
    def _num(v, nome, minimo, massimo=None):
        if isinstance(v, bool):
            return None, f"{nome} deve essere un numero."
        try:
            x = float(v)
        except (TypeError, ValueError):
            return None, f"{nome} deve essere un numero."
        if not np.isfinite(x) or x < minimo:
            return None, f"{nome} deve essere un numero >= {minimo}."
        if massimo is not None and x > massimo:
            return None, f"{nome} deve essere un numero <= {massimo}."
        return x, None

    pt, em = _num(pot_turbina_mw, "pot_turbina_mw", 1e-9)
    if em:
        return _err(em)
    pp, em = _num(pot_pompa_mw, "pot_pompa_mw", 1e-9)
    if em:
        return _err(em)
    cap, em = _num(capacita_mwh, "capacita_mwh", 1e-9)
    if em:
        return _err(em)
    et, em = _num(eff_turbina, "eff_turbina", 1e-9, 1.0)
    if em:
        return _err(em)
    epu, em = _num(eff_pompa, "eff_pompa", 1e-9, 1.0)
    if em:
        return _err(em)
    liv0, em = _num(livello_iniziale_pct, "livello_iniziale_pct", 0.0, 100.0)
    if em:
        return _err(em)
    apporto, em = _num(apporto_naturale_mw, "apporto_naturale_mw", 0.0)
    if em:
        return _err(em)
    vom, em = _num(vom_eur_mwh, "vom_eur_mwh", 0.0)
    if em:
        return _err(em)
    soglia, em = _num(soglia_pompaggio_pct, "soglia_pompaggio_pct", 1e-9)
    if em:
        return _err(em)
    if not (soglia < 50.0):
        return _err("soglia_pompaggio_pct deve essere < 50.")

    # --- simulazione oraria ---
    round_trip = et * epu
    livello = cap * liv0 / 100.0
    q_low_f = soglia / 100.0
    q_high_f = 1.0 - soglia / 100.0

    righe = []
    ric_gen = 0.0
    costo_pump = 0.0
    e_gen = 0.0
    e_pump = 0.0
    ore_p = 0
    ore_g = 0
    for _giorno, sg in s.groupby(pd.Grouper(freq="D")):
        q_low = float(np.quantile(sg.values, q_low_f))
        q_high = float(np.quantile(sg.values, q_high_f))
        for ts, p in sg.items():
            if apporto > 0.0:
                livello = min(cap, livello + apporto)
            azione = "Fermo"
            en_p = 0.0
            en_g = 0.0
            if p <= q_low and livello < cap:
                en_p = min(pp, (cap - livello) / epu)
                if en_p > 1e-9:
                    livello += en_p * epu
                    costo_pump += en_p * p
                    e_pump += en_p
                    ore_p += 1
                    azione = "Pompaggio"
            elif p >= q_high and livello > 0.0:
                scarico = min(pt / et, livello)
                if scarico > 1e-9:
                    en_g = scarico * et
                    livello -= scarico
                    ric_gen += en_g * p
                    e_gen += en_g
                    ore_g += 1
                    azione = "Generazione"
            righe.append((ts, float(p), azione, float(livello),
                          float(en_p), float(en_g)))

    df_raw = pd.DataFrame(righe, columns=["Ora", "Prezzo (EUR/MWh)", "Azione",
                                          "Livello bacino (MWh)",
                                          "Energia pompata (MWh)",
                                          "Energia generata (MWh)"])

    # --- KPI ---
    vom_tot = vom * (e_gen + e_pump)
    lordo = ric_gen - costo_pump
    netto = lordo - vom_tot
    n_giorni = int(pd.Series(s.index.date).nunique())
    spread_medio = lordo / e_gen if e_gen > 0 else 0.0
    cicli = e_pump / cap
    eur_mw_g = netto / pt / n_giorni if n_giorni > 0 else 0.0
    util = (ore_p + ore_g) / len(s) * 100.0
    liv_finale = livello / cap * 100.0
    breakeven_spread = (1.0 / round_trip - 1.0) * 100.0

    if netto > 0:
        giudizio = "ARBITRAGGIO VINCENTE"
        verdetto = (f"Il pompaggio rende {netto:,.0f} EUR netti sul periodo "
                    f"({eur_mw_g:,.0f} EUR/MW/giorno), con {cicli:.1f} cicli "
                    f"equivalenti e spread medio catturato di "
                    f"{spread_medio:.1f} EUR/MWh.")
    else:
        giudizio = "NON CONVIENE"
        verdetto = (f"Gli spread non coprono le perdite: con round-trip al "
                    f"{round_trip * 100:.0f}% lo spread deve superare il "
                    f"{breakeven_spread:.0f}% piu' i VOM perche' il ciclo "
                    f"paghi. Ricavo netto {netto:,.0f} EUR sul periodo.")

    # --- tabelle ---
    df_oraria = df_raw.copy()
    for c in ["Prezzo (EUR/MWh)", "Livello bacino (MWh)",
              "Energia pompata (MWh)", "Energia generata (MWh)"]:
        df_oraria[c] = df_oraria[c].round(2)

    dfg = df_raw.copy()
    dfg["Giorno"] = pd.to_datetime(dfg["Ora"]).dt.strftime("%Y-%m-%d")
    dfg["Ricavo gen (EUR)"] = (dfg["Energia generata (MWh)"]
                               * dfg["Prezzo (EUR/MWh)"])
    dfg["Costo pump (EUR)"] = (dfg["Energia pompata (MWh)"]
                               * dfg["Prezzo (EUR/MWh)"])
    grp = dfg.groupby("Giorno")
    df_giornaliera = pd.DataFrame({
        "Giorno": list(grp.groups.keys()),
        "Ricavo generazione (EUR)": grp["Ricavo gen (EUR)"].sum().values.round(0),
        "Costo pompaggio (EUR)": grp["Costo pump (EUR)"].sum().values.round(0),
        "Energia generata (MWh)": grp["Energia generata (MWh)"].sum().values.round(1),
        "Energia pompata (MWh)": grp["Energia pompata (MWh)"].sum().values.round(1),
    })
    df_giornaliera["Ricavo netto (EUR)"] = (
        df_giornaliera["Ricavo generazione (EUR)"]
        - df_giornaliera["Costo pompaggio (EUR)"]).round(0)
    df_giornaliera["Cicli"] = (
        df_giornaliera["Energia pompata (MWh)"] / cap).round(2)

    return {"valido": True, "errore": None,
            "ricavo_generazione_eur": ric_gen,
            "costo_pompaggio_eur": costo_pump,
            "ricavo_lordo_eur": lordo,
            "vom_totale_eur": vom_tot,
            "ricavo_netto_eur": netto,
            "ricavo_eur_mw_giorno": eur_mw_g,
            "spread_medio_catturato_eur_mwh": spread_medio,
            "breakeven_spread_pct": breakeven_spread,
            "energia_pompata_mwh": e_pump,
            "energia_generata_mwh": e_gen,
            "cicli_equivalenti": cicli,
            "ore_pompaggio": ore_p,
            "ore_generazione": ore_g,
            "fattore_utilizzo_pct": util,
            "livello_finale_pct": liv_finale,
            "round_trip": round_trip,
            "giudizio": giudizio, "verdetto": verdetto,
            "df_oraria": df_oraria, "df_giornaliera": df_giornaliera,
            "n_ore": len(s), "n_giorni": n_giorni}


def calcola_matching_ppa_orario(prezzi, gen_mw=10.0, mix_solare_pct=50.0,
                                cf_solare=0.18, cf_eolico=0.40,
                                carico_mw=8.0, profilo_carico="Piatto",
                                prezzo_ppa=70.0):
    """Matching orario di un PPA rinnovabile contro un profilo di carico.

    Domanda operativa: "contratto PPA da G MW su un carico da C MW — quanta
    energia e' davvero abbinata ora per ora (matching 24/7), quanto deficit
    compro a spot e quanto surplus vendo a spot?"

    Profili sintetici deterministici costruiti sul calendario della serie
    prezzi (normalizzati ai capacity factor medi annui inseriti):
    - solare: campana attorno al mezzogiorno con durata del giorno
      stagionale (dl = 12 + 4.5*cos(2*pi*(doy-172)/365));
    - eolico: stagionalita' invernale + lieve profilo notturno + rumore
      moltiplicativo deterministico (seed 187);
    - carico: Piatto / Uffici (8-18 lun-ven) / Industriale 3 turni /
      Residenziale (picco serale); carico_mw = picco MW.

    Economia pay-as-produced: tutta la generazione si paga a prezzo_ppa,
    il deficit si compra a spot, il surplus si vende a spot.
      matched_h = min(gen_h, carico_h)
      surplus_h = gen_h - matched_h ; deficit_h = carico_h - matched_h

    - prezzi: Series oraria EUR/MWh, indice datetime (tz-aware reso naive);
    - gen_mw: potenza contrattuale PPA (> 0);
    - mix_solare_pct: quota solare nel mix [0, 100] (resto eolico);
    - cf_solare / cf_eolico: capacity factor medi annui in (0, 0.9];
    - carico_mw: picco di carico (> 0);
    - profilo_carico: uno tra "Piatto", "Uffici (8-18, lun-ven)",
      "Industriale 3 turni", "Residenziale";
    - prezzo_ppa: strike pay-as-produced in EUR/MWh (>= 0).

    Ritorna dict con 'valido'/'errore', mwh_gen, mwh_carico, mwh_abbinati,
    mwh_surplus, mwh_deficit, costo_ppa_eur, ricavo_surplus_eur,
    costo_deficit_eur, costo_totale_eur, costo_spot_puro_eur, delta_eur,
    delta_pct, prezzo_effettivo_eur_mwh, copertura_media_pct, ore_100_pct,
    giudizio, verdetto, df_giornaliera, df_mensile, n_ore, n_giorni.

    Giudizio: "MATCHING ECCELLENTE" se copertura_media >= 85%,
    "MATCHING BUONO" >= 60%, "MATCHING PARZIALE" >= 35%, altrimenti
    "MATCHING DEBOLE".

    NaN-safe: serie vuota / non numerica / indice non-datetime, parametri
    non validi -> errore pulito, mai eccezioni.
    """
    def _err(msg):
        return {"valido": False, "errore": msg}

    # --- pulizia serie prezzi (stesso schema delle altre tab) ---
    if not isinstance(prezzi, pd.Series):
        return _err("prezzi deve essere una Series pandas con indice datetime.")
    s = prezzi.copy()
    try:
        s.index = pd.to_datetime(s.index, errors="coerce")
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    if s.index.isna().any():
        return _err("prezzi deve avere un indice datetime valido.")
    try:
        if getattr(s.index, "tz", None) is not None:
            s.index = s.index.tz_localize(None)
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    s = pd.to_numeric(s, errors="coerce").dropna()
    if len(s) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")
    spot = s.to_numpy(dtype=float)
    n = len(s)

    # --- validazione parametri ---
    def _num(v, nome, minimo, massimo=None):
        if isinstance(v, bool):
            return None, f"{nome} deve essere un numero."
        try:
            x = float(v)
        except (TypeError, ValueError):
            return None, f"{nome} deve essere un numero."
        if not np.isfinite(x) or x < minimo:
            return None, f"{nome} deve essere un numero >= {minimo}."
        if massimo is not None and x > massimo:
            return None, f"{nome} deve essere un numero <= {massimo}."
        return x, None

    gen, em = _num(gen_mw, "gen_mw", 1e-9)
    if em:
        return _err(em)
    mix, em = _num(mix_solare_pct, "mix_solare_pct", 0.0, 100.0)
    if em:
        return _err(em)
    cfs, em = _num(cf_solare, "cf_solare", 1e-9, 0.9)
    if em:
        return _err(em)
    cfw, em = _num(cf_eolico, "cf_eolico", 1e-9, 0.9)
    if em:
        return _err(em)
    car, em = _num(carico_mw, "carico_mw", 1e-9)
    if em:
        return _err(em)
    profili_validi = ("Piatto", "Uffici (8-18, lun-ven)",
                      "Industriale 3 turni", "Residenziale")
    if profilo_carico not in profili_validi:
        return _err("profilo_carico non valido: scegli tra "
                    + ", ".join(profili_validi) + ".")
    ppa, em = _num(prezzo_ppa, "prezzo_ppa", 0.0)
    if em:
        return _err(em)

    # --- profili sintetici deterministici ---
    idx = s.index
    doy = idx.dayofyear.to_numpy(dtype=float)
    ora = idx.hour.to_numpy(dtype=float)
    dow = idx.dayofweek.to_numpy()  # 0 = lunedi'

    # Solare: campana sul giorno solare con durata stagionale
    dl = 12.0 + 4.5 * np.cos(2.0 * np.pi * (doy - 172.0) / 365.0)
    alba = 12.0 - dl / 2.0
    fraz = np.clip((ora - alba) / dl, 0.0, 1.0)
    raw_sol = np.sin(np.pi * fraz)
    media_sol = float(raw_sol.mean())
    cf_sol_h = raw_sol / media_sol * cfs if media_sol > 0 else np.zeros(n)

    # Eolico: stagionalita' invernale + profilo notturno + rumore det.
    stag = 1.0 + 0.30 * np.cos(2.0 * np.pi * (doy - 15.0) / 365.0)
    nott = 1.0 + 0.15 * np.cos(2.0 * np.pi * (ora - 3.0) / 24.0)
    rng = np.random.RandomState(187)
    rumore = 0.85 + 0.30 * rng.rand(n)
    raw_eol = stag * nott * rumore
    media_eol = float(raw_eol.mean())
    cf_eol_h = raw_eol / media_eol * cfw if media_eol > 0 else np.zeros(n)

    gen_h = gen * (mix / 100.0 * cf_sol_h + (1.0 - mix / 100.0) * cf_eol_h)

    # Carico: shape 0..1 x picco MW
    if profilo_carico == "Piatto":
        shape = np.ones(n)
    elif profilo_carico == "Uffici (8-18, lun-ven)":
        lav = (dow < 5) & (ora >= 8.0) & (ora < 18.0)
        shape = np.where(lav, 1.0, 0.25)
    elif profilo_carico == "Industriale 3 turni":
        shape = np.where(dow < 5, 1.0, 0.5)
    else:  # Residenziale
        shape = np.full(n, 0.35)
        shape[(ora >= 7.0) & (ora < 9.0)] = 0.70
        shape[(ora >= 18.0) & (ora < 22.0)] = 1.0
    car_h = car * shape

    matched = np.minimum(gen_h, car_h)
    surplus = gen_h - matched
    deficit = car_h - matched

    # --- economia pay-as-produced ---
    mwh_gen = float(gen_h.sum())
    mwh_carico = float(car_h.sum())
    mwh_abb = float(matched.sum())
    mwh_sur = float(surplus.sum())
    mwh_def = float(deficit.sum())
    costo_ppa = mwh_gen * ppa
    ric_sur = float((surplus * spot).sum())
    cos_def = float((deficit * spot).sum())
    costo_tot = costo_ppa + cos_def - ric_sur
    costo_spot = float((car_h * spot).sum())
    delta = costo_spot - costo_tot
    delta_pct = delta / costo_spot * 100.0 if costo_spot > 0 else 0.0
    prezzo_eff = costo_tot / mwh_carico if mwh_carico > 0 else 0.0

    maschera = car_h > 1e-9
    if maschera.any():
        copertura_media = float((matched[maschera] / car_h[maschera]).mean()
                                * 100.0)
        ore_100 = float((matched[maschera]
                         >= car_h[maschera] * (1.0 - 1e-9)).mean() * 100.0)
    else:
        copertura_media = 0.0
        ore_100 = 0.0

    if copertura_media >= 85.0:
        giudizio = "MATCHING ECCELLENTE"
    elif copertura_media >= 60.0:
        giudizio = "MATCHING BUONO"
    elif copertura_media >= 35.0:
        giudizio = "MATCHING PARZIALE"
    else:
        giudizio = "MATCHING DEBOLE"
    verdetto = (f"{giudizio}: il {copertura_media:.1f}% del carico e' coperto "
                f"ora per ora dalla generazione PPA ({mwh_abb:,.0f} MWh su "
                f"{mwh_carico:,.0f} MWh); deficit a spot {mwh_def:,.0f} MWh, "
                f"surplus venduto {mwh_sur:,.0f} MWh. Delta vs tutto-spot "
                f"{delta:+,.0f} EUR ({delta_pct:+.1f}%).")

    # --- tabelle ---
    df_raw = pd.DataFrame({
        "Ora": idx,
        "Generazione (MW)": gen_h,
        "Carico (MW)": car_h,
        "Abbinati (MWh)": matched,
        "Surplus (MWh)": surplus,
        "Deficit (MWh)": deficit,
        "Prezzo (EUR/MWh)": spot,
    })
    df_raw["Costo gen (EUR)"] = df_raw["Generazione (MW)"] * ppa
    df_raw["Costo def (EUR)"] = df_raw["Deficit (MWh)"] * df_raw["Prezzo (EUR/MWh)"]
    df_raw["Ric sur (EUR)"] = df_raw["Surplus (MWh)"] * df_raw["Prezzo (EUR/MWh)"]
    df_raw["Costo carico spot (EUR)"] = (df_raw["Carico (MW)"]
                                         * df_raw["Prezzo (EUR/MWh)"])

    dfg = df_raw.copy()
    dfg["Giorno"] = pd.to_datetime(dfg["Ora"]).dt.strftime("%Y-%m-%d")
    grp = dfg.groupby("Giorno")
    carico_g = grp["Carico (MW)"].sum().values
    abb_g = grp["Abbinati (MWh)"].sum().values
    df_giornaliera = pd.DataFrame({
        "Giorno": list(grp.groups.keys()),
        "MWh abbinati": np.round(abb_g, 1),
        "MWh surplus": np.round(grp["Surplus (MWh)"].sum().values, 1),
        "MWh deficit": np.round(grp["Deficit (MWh)"].sum().values, 1),
        "MWh carico": np.round(carico_g, 1),
        "Copertura %": np.round(np.where(carico_g > 0, abb_g / carico_g * 100.0,
                                         0.0), 1),
        "Costo totale (EUR)": np.round(
            grp["Costo gen (EUR)"].sum().values
            + grp["Costo def (EUR)"].sum().values
            - grp["Ric sur (EUR)"].sum().values, 0),
    })

    dfm = df_raw.copy()
    dfm["Mese"] = pd.to_datetime(dfm["Ora"]).dt.strftime("%Y-%m")
    grm = dfm.groupby("Mese")
    carico_m = grm["Carico (MW)"].sum().values
    abb_m = grm["Abbinati (MWh)"].sum().values
    costo_m = (grm["Costo gen (EUR)"].sum().values
               + grm["Costo def (EUR)"].sum().values
               - grm["Ric sur (EUR)"].sum().values)
    df_mensile = pd.DataFrame({
        "Mese": list(grm.groups.keys()),
        "MWh carico": np.round(carico_m, 0),
        "MWh generati": np.round(grm["Generazione (MW)"].sum().values, 0),
        "MWh abbinati": np.round(abb_m, 0),
        "Copertura %": np.round(np.where(carico_m > 0, abb_m / carico_m * 100.0,
                                         0.0), 1),
        "MWh surplus": np.round(grm["Surplus (MWh)"].sum().values, 0),
        "MWh deficit": np.round(grm["Deficit (MWh)"].sum().values, 0),
        "Costo totale (EUR)": np.round(costo_m, 0),
        "Delta vs spot (EUR)": np.round(
            grm["Costo carico spot (EUR)"].sum().values - costo_m, 0),
    })

    return {"valido": True, "errore": None,
            "mwh_gen": mwh_gen, "mwh_carico": mwh_carico,
            "mwh_abbinati": mwh_abb, "mwh_surplus": mwh_sur,
            "mwh_deficit": mwh_def,
            "costo_ppa_eur": costo_ppa, "ricavo_surplus_eur": ric_sur,
            "costo_deficit_eur": cos_def, "costo_totale_eur": costo_tot,
            "costo_spot_puro_eur": costo_spot, "delta_eur": delta,
            "delta_pct": delta_pct,
            "prezzo_effettivo_eur_mwh": prezzo_eff,
            "copertura_media_pct": copertura_media, "ore_100_pct": ore_100,
            "giudizio": giudizio, "verdetto": verdetto,
            "df_giornaliera": df_giornaliera, "df_mensile": df_mensile,
            "n_ore": n, "n_giorni": int(df_giornaliera.shape[0])}


def calcola_comunita_energetica(prezzi, potenza_fv_kwp=100.0, cf_fv=0.13,
                                n_utenze=20, picco_kw=4.0,
                                profilo_utenze="Mix automatico",
                                maggiorazione_retail=45.0, premio_cer=0.0):
    """Autoconsumo collettivo / Comunita' energetica rinnovabile (CER).

    Domanda operativa: "N utenze condividono un impianto FV — quanta energia
    e' davvero condivisa ora per ora, e quanto vale rispetto al caso in cui
    ognuno compra da solo e l'impianto vende tutto a spot?"

    Impianto FV condiviso (kWp) con profilo solare sintetico deterministico
    (campana sul giorno solare a durata stagionale, normalizzato al capacity
    factor medio annuo cf_fv); N utenze con profili di carico sintetici
    deterministici (stesse shape della tab matching PPA: Piatto / Uffici
    (8-18, lun-ven) / Industriale 3 turni / Residenziale), picco per utenza
    variabile in modo deterministico (seed 188) attorno a picco_kw.

    Energia condivisa (modello CER "virtuale", es. GSE):
      condivisa_h = min(gen_h, carico_h)
      surplus_h   = gen_h - condivisa_h   (venduto a spot)
      deficit_h   = carico_h - condivisa_h (comprato a retail = spot + markup)

    Beneficio della comunita' vs baseline "ognuno per se'":
      beneficio = mwh_condivisi * (maggiorazione_retail + premio_cer)
    La maggiorazione retail (oneri di rete/imposte evitati sull'energia
    condivisa) e' il vero motore economico; il premio CER e' l'eventuale
    incentivo (es. tariffa incentivante). Il prezzo di scambio interno tra
    membri si elide a livello di comunita' (puro trasferimento).

    Ritorna dict con 'valido'/'errore', mwh_gen, mwh_carico, mwh_condivisi,
    mwh_surplus, mwh_deficit, beneficio_eur, beneficio_per_utenza_eur,
    costo_baseline_eur, costo_comunita_eur, risparmio_pct,
    quota_condivisa_pct, autoconsumo_collettivo_pct, giudizio, verdetto,
    df_giornaliera, df_mensile, n_utenze, n_ore, n_giorni.

    Giudizio sulla quota di carico coperta dall'energia condivisa:
    "COMUNITA' MOLTO EFFICIENTE" >= 50%, "COMUNITA' EFFICIENTE" >= 35%,
    "COMUNITA' MODERATA" >= 20%, altrimenti "COMUNITA' LIMITATA".

    NaN-safe: serie vuota / non numerica / indice non-datetime, parametri
    non validi -> errore pulito, mai eccezioni.
    """
    def _err(msg):
        return {"valido": False, "errore": msg}

    # --- pulizia serie prezzi (stesso schema delle altre tab) ---
    if not isinstance(prezzi, pd.Series):
        return _err("prezzi deve essere una Series pandas con indice datetime.")
    s = prezzi.copy()
    try:
        s.index = pd.to_datetime(s.index, errors="coerce")
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    if s.index.isna().any():
        return _err("prezzi deve avere un indice datetime valido.")
    try:
        if getattr(s.index, "tz", None) is not None:
            s.index = s.index.tz_localize(None)
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    s = pd.to_numeric(s, errors="coerce").dropna()
    if len(s) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")
    spot = s.to_numpy(dtype=float)
    n = len(s)

    # --- validazione parametri ---
    def _num(v, nome, minimo, massimo=None):
        if isinstance(v, bool):
            return None, f"{nome} deve essere un numero."
        try:
            x = float(v)
        except (TypeError, ValueError):
            return None, f"{nome} deve essere un numero."
        if not np.isfinite(x) or x < minimo:
            return None, f"{nome} deve essere un numero >= {minimo}."
        if massimo is not None and x > massimo:
            return None, f"{nome} deve essere un numero <= {massimo}."
        return x, None

    fv, em = _num(potenza_fv_kwp, "potenza_fv_kwp", 1e-9)
    if em:
        return _err(em)
    cfv, em = _num(cf_fv, "cf_fv", 1e-9, 0.9)
    if em:
        return _err(em)
    nu, em = _num(n_utenze, "n_utenze", 2.0, 500.0)
    if em:
        return _err(em)
    n_ut = int(round(nu))
    if n_ut < 2:
        return _err("n_utenze deve essere un numero >= 2.")
    pk, em = _num(picco_kw, "picco_kw", 1e-9, 1000.0)
    if em:
        return _err(em)
    profili_validi = ("Piatto", "Uffici (8-18, lun-ven)", "Industriale 3 turni",
                      "Residenziale", "Mix automatico")
    if profilo_utenze not in profili_validi:
        return _err("profilo_utenze non valido: scegli tra "
                    + ", ".join(profili_validi) + ".")
    mark, em = _num(maggiorazione_retail, "maggiorazione_retail", 0.0)
    if em:
        return _err(em)
    prem, em = _num(premio_cer, "premio_cer", 0.0)
    if em:
        return _err(em)

    # --- profili sintetici deterministici ---
    idx = s.index
    doy = idx.dayofyear.to_numpy(dtype=float)
    ora = idx.hour.to_numpy(dtype=float)
    dow = idx.dayofweek.to_numpy()  # 0 = lunedi'

    def _shape(nome):
        if nome == "Piatto":
            return np.ones(n)
        if nome == "Uffici (8-18, lun-ven)":
            lav = (dow < 5) & (ora >= 8.0) & (ora < 18.0)
            return np.where(lav, 1.0, 0.25)
        if nome == "Industriale 3 turni":
            return np.where(dow < 5, 1.0, 0.5)
        shp = np.full(n, 0.35)  # Residenziale
        shp[(ora >= 7.0) & (ora < 9.0)] = 0.70
        shp[(ora >= 18.0) & (ora < 22.0)] = 1.0
        return shp

    rng = np.random.RandomState(188)
    if profilo_utenze == "Mix automatico":
        nomi = rng.permutation(
            [profili_validi[i % 4] for i in range(n_ut)]).tolist()
    else:
        nomi = [profilo_utenze] * n_ut
    picchi = pk * (0.6 + 0.8 * rng.rand(n_ut))  # kW di picco per utenza
    car_kw = np.zeros(n)
    for nome in profili_validi[:4]:
        m = np.array([x == nome for x in nomi])
        if m.any():
            car_kw = car_kw + _shape(nome) * picchi[m].sum()

    # Solare: campana sul giorno solare con durata stagionale, normalizzata
    # al capacity factor medio annuo cf_fv.
    dl = 12.0 + 4.5 * np.cos(2.0 * np.pi * (doy - 172.0) / 365.0)
    alba = 12.0 - dl / 2.0
    fraz = np.clip((ora - alba) / dl, 0.0, 1.0)
    raw_sol = np.sin(np.pi * fraz)
    media_sol = float(raw_sol.mean())
    cf_sol_h = raw_sol / media_sol * cfv if media_sol > 0 else np.zeros(n)
    gen_kw = fv * cf_sol_h

    # --- energia condivisa ora per ora (MWh) ---
    gen = gen_kw / 1000.0
    car = car_kw / 1000.0
    condiv = np.minimum(gen, car)
    surplus = gen - condiv
    deficit = car - condiv

    mwh_gen = float(gen.sum())
    mwh_carico = float(car.sum())
    mwh_con = float(condiv.sum())
    mwh_sur = float(surplus.sum())
    mwh_def = float(deficit.sum())

    # --- economia: comunita' vs baseline "ognuno per se'" ---
    beneficio = mwh_con * (mark + prem)
    costo_base = float((car * (spot + mark)).sum() - (gen * spot).sum())
    costo_cer = float((deficit * (spot + mark)).sum()
                      - (surplus * spot).sum())

    quota = mwh_con / mwh_carico * 100.0 if mwh_carico > 0 else 0.0
    auto = mwh_con / mwh_gen * 100.0 if mwh_gen > 0 else 0.0
    ben_ut = beneficio / n_ut
    risp_pct = beneficio / costo_base * 100.0 if costo_base > 0 else 0.0

    if quota >= 50.0:
        giudizio = "COMUNITA' MOLTO EFFICIENTE"
    elif quota >= 35.0:
        giudizio = "COMUNITA' EFFICIENTE"
    elif quota >= 20.0:
        giudizio = "COMUNITA' MODERATA"
    else:
        giudizio = "COMUNITA' LIMITATA"
    verdetto = (f"{giudizio}: {mwh_con:,.0f} MWh condivisi ora per ora "
                f"({quota:.1f}% del carico di {mwh_carico:,.0f} MWh), "
                f"autoconsumo collettivo {auto:.1f}%, surplus venduto "
                f"{mwh_sur:,.0f} MWh, deficit comprato {mwh_def:,.0f} MWh. "
                f"Beneficio comunita' {beneficio:,.0f} EUR "
                f"({ben_ut:,.0f} EUR/utenza, {risp_pct:+.1f}% sul costo "
                f"baseline).")

    # --- tabelle ---
    df_raw = pd.DataFrame({
        "Ora": idx,
        "Generazione (kW)": gen_kw,
        "Carico (kW)": car_kw,
        "Condivisi (MWh)": condiv,
        "Surplus (MWh)": surplus,
        "Deficit (MWh)": deficit,
        "Prezzo (EUR/MWh)": spot,
    })
    df_raw["Beneficio (EUR)"] = df_raw["Condivisi (MWh)"] * (mark + prem)

    dfg = df_raw.copy()
    dfg["Giorno"] = pd.to_datetime(dfg["Ora"]).dt.strftime("%Y-%m-%d")
    grp = dfg.groupby("Giorno")
    carico_g = grp["Carico (kW)"].sum().values / 1000.0
    con_g = grp["Condivisi (MWh)"].sum().values
    df_giornaliera = pd.DataFrame({
        "Giorno": list(grp.groups.keys()),
        "MWh generati": np.round(grp["Generazione (kW)"].sum().values
                                / 1000.0, 2),
        "MWh carico": np.round(carico_g, 2),
        "MWh condivisi": np.round(con_g, 2),
        "MWh surplus": np.round(grp["Surplus (MWh)"].sum().values, 2),
        "MWh deficit": np.round(grp["Deficit (MWh)"].sum().values, 2),
        "Quota condivisa %": np.round(np.where(
            carico_g > 0, con_g / carico_g * 100.0, 0.0), 1),
        "Beneficio (EUR)": np.round(grp["Beneficio (EUR)"].sum().values, 0),
    })

    dfm = df_raw.copy()
    dfm["Mese"] = pd.to_datetime(dfm["Ora"]).dt.strftime("%Y-%m")
    grm = dfm.groupby("Mese")
    carico_m = grm["Carico (kW)"].sum().values / 1000.0
    con_m = grm["Condivisi (MWh)"].sum().values
    ben_m = grm["Beneficio (EUR)"].sum().values
    df_mensile = pd.DataFrame({
        "Mese": list(grm.groups.keys()),
        "MWh carico": np.round(carico_m, 0),
        "MWh generati": np.round(grm["Generazione (kW)"].sum().values
                                / 1000.0, 0),
        "MWh condivisi": np.round(con_m, 0),
        "Quota condivisa %": np.round(np.where(
            carico_m > 0, con_m / carico_m * 100.0, 0.0), 1),
        "Beneficio (EUR)": np.round(ben_m, 0),
        "Beneficio cumulato (EUR)": np.round(np.cumsum(ben_m), 0),
    })

    return {"valido": True, "errore": None,
            "mwh_gen": mwh_gen, "mwh_carico": mwh_carico,
            "mwh_condivisi": mwh_con, "mwh_surplus": mwh_sur,
            "mwh_deficit": mwh_def,
            "beneficio_eur": beneficio,
            "beneficio_per_utenza_eur": ben_ut,
            "costo_baseline_eur": costo_base,
            "costo_comunita_eur": costo_cer,
            "risparmio_pct": risp_pct,
            "quota_condivisa_pct": quota,
            "autoconsumo_collettivo_pct": auto,
            "giudizio": giudizio, "verdetto": verdetto,
            "df_giornaliera": df_giornaliera, "df_mensile": df_mensile,
            "n_utenze": n_ut, "n_ore": n,
            "n_giorni": int(df_giornaliera.shape[0])}


def calcola_curtailment(prezzi, potenza_mw=10.0, profilo="solare",
                        soglia_curtailment=0.0, costo_marginale=2.0, seed=190):
    """Curtailment economico di un impianto rinnovabile (FV/eolico).

    Domanda operativa: "Ho un impianto rinnovabile da P MW — in quali ore
    conviene fermarlo invece di vendere a prezzi sotto soglia (es. negativi),
    quanta energia perdo e quanto risparmio? E come cambia il mio prezzo di
    cattura?"

    Per ogni ora h l'impianto potrebbe generare g_h = f_h * potenza_mw, dove
    f_h in [0,1] e' il fattore di capacita' orario del profilo scelto:
      "solare": campana deterministica 6:00-20:00 con picco alle 13:00;
      "eolico": profilo sintetico deterministico (random walk smussata, seed);
      "piatto":  f_h = 1.0 sempre.
    L'impianto viene fermato (curtailment) nelle ore con spot < soglia.

    Economia (costo_marginale = O&M variabile per MWh prodotto):
      profitto_senza = Σ (spot_h - costo_marginale) * g_h   (sempre in marcia)
      profitto_con   = Σ (spot_h - costo_marginale) * g_h   (solo ore non curtailate)
      beneficio      = profitto_con - profitto_senza
                     = - Σ_ore_curtailate (spot_h - costo_marginale) * g_h
    Con soglia == costo_marginale il curtailment e' l'ottimo economico (fermi
    esattamente le ore in perdita); con soglia > costo_marginale il beneficio
    puo' essere negativo: stai buttando ricavi positivi.

    Ritorna dict con 'valido'/'errore', ore_curtailment, mwh_potenziali,
    mwh_curtailed, mwh_consegnati, quota_curtailment_pct, ricavo_senza_eur,
    ricavo_con_eur, profitto_senza_eur, profitto_con_eur, beneficio_eur,
    onm_risparmiati_eur, cattura_senza_eur_mwh, cattura_con_eur_mwh,
    giudizio, verdetto, df_giornaliera, df_mensile, n_ore, profilo, soglia.

    Giudizio:
    "NON NECESSARIO" (nessuna ora sotto soglia),
    "CONSIGLIATO" (beneficio > 0 e quota curtailment >= 1%),
    "MARGINALE" (beneficio > 0 ma quota < 1%: valuta i costi di start/stop),
    "SOGLIA TROPPO ALTA" (beneficio <= 0 con ore curtailate: la soglia
    scelta distrugge valore, abbassala verso il costo marginale).

    NaN-safe: serie vuota / non numerica / indice non-datetime, parametri
    non validi -> errore pulito, mai eccezioni.
    """
    def _err(msg):
        return {"valido": False, "errore": msg}

    # --- pulizia serie prezzi (stesso schema delle altre tab) ---
    if not isinstance(prezzi, pd.Series):
        return _err("prezzi deve essere una Series pandas con indice datetime.")
    s = prezzi.copy()
    try:
        s.index = pd.to_datetime(s.index, errors="coerce")
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    if s.index.isna().any():
        return _err("prezzi deve avere un indice datetime valido.")
    try:
        if getattr(s.index, "tz", None) is not None:
            s.index = s.index.tz_localize(None)
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    s = pd.to_numeric(s, errors="coerce").dropna()
    if len(s) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")
    spot = s.to_numpy(dtype=float)
    n = len(s)

    # --- validazione parametri ---
    def _num(v, nome, minimo, massimo=None):
        if isinstance(v, bool):
            return None, f"{nome} deve essere un numero."
        try:
            x = float(v)
        except (TypeError, ValueError):
            return None, f"{nome} deve essere un numero."
        if not np.isfinite(x) or x < minimo:
            return None, f"{nome} deve essere un numero >= {minimo}."
        if massimo is not None and x > massimo:
            return None, f"{nome} deve essere un numero <= {massimo}."
        return x, None

    pmw, em = _num(potenza_mw, "potenza_mw", 1e-9, 100000.0)
    if em:
        return _err(em)
    if not isinstance(profilo, str) or profilo not in ("solare", "eolico", "piatto"):
        return _err("profilo deve essere 'solare', 'eolico' o 'piatto'.")
    soglia, em = _num(soglia_curtailment, "soglia_curtailment", -10000.0, 10000.0)
    if em:
        return _err(em)
    cm, em = _num(costo_marginale, "costo_marginale", 0.0, 10000.0)
    if em:
        return _err(em)
    if isinstance(seed, bool):
        return _err("seed deve essere un intero.")
    try:
        seed_i = int(seed)
    except (TypeError, ValueError):
        return _err("seed deve essere un intero.")

    # --- profilo di generazione orario (fattore di capacita' 0..1) ---
    ore = s.index.hour.to_numpy()
    if profilo == "piatto":
        f = np.ones(n)
    elif profilo == "solare":
        x = (ore - 6.0) / 14.0
        f = np.where((ore >= 6) & (ore < 20),
                     np.sin(np.pi * np.clip(x, 0.0, 1.0)) ** 1.2, 0.0)
    else:  # eolico: deterministico a parita' di seed
        rng = np.random.default_rng(seed_i)
        base = rng.uniform(0.05, 1.0, n)
        f = pd.Series(base).rolling(6, min_periods=1, center=True).mean().to_numpy()
        f = np.clip(f, 0.05, 0.95)

    g = f * pmw
    curt = spot < soglia
    ore_curt = int(curt.sum())

    mwh_pot = float(g.sum())
    mwh_curt = float(g[curt].sum())
    mwh_del = mwh_pot - mwh_curt

    marg_senza = (spot - cm) * g
    marg_con = np.where(curt, 0.0, marg_senza)
    ricavo_senza = float((spot * g).sum())
    ricavo_con = float((spot[~curt] * g[~curt]).sum())
    profitto_senza = float(marg_senza.sum())
    profitto_con = float(marg_con.sum())
    beneficio = profitto_con - profitto_senza
    onm_risp = cm * mwh_curt
    quota = 100.0 * mwh_curt / mwh_pot if mwh_pot > 0 else 0.0
    cattura_senza = ricavo_senza / mwh_pot if mwh_pot > 0 else 0.0
    cattura_con = ricavo_con / mwh_del if mwh_del > 0 else 0.0

    if ore_curt == 0:
        giudizio = "NON NECESSARIO"
        verdetto = ("Nessuna ora con prezzo sotto la soglia di "
                    f"{soglia:,.2f} EUR/MWh: nessun curtailment da applicare.")
    elif beneficio > 0 and quota >= 1.0:
        giudizio = "CONSIGLIATO"
        verdetto = (f"Curtailment consigliato: fermando l'impianto nelle {ore_curt} "
                    f"ore sotto soglia risparmi {beneficio:,.0f} EUR "
                    f"({mwh_curt:,.0f} MWh non prodotti, O&M risparmiati "
                    f"{onm_risp:,.0f} EUR).")
    elif beneficio > 0:
        giudizio = "MARGINALE"
        verdetto = (f"Beneficio positivo ma modesto ({beneficio:,.0f} EUR su "
                    f"{mwh_curt:,.1f} MWh curtailati): valuta se i costi di "
                    f"start/stop lo giustificano.")
    else:
        giudizio = "SOGLIA TROPPO ALTA"
        verdetto = (f"La soglia di {soglia:,.2f} EUR/MWh distrugge valore "
                    f"({beneficio:,.0f} EUR): stai fermando ore con margine "
                    f"positivo. Abbassala verso il costo marginale "
                    f"({cm:,.2f} EUR/MWh).")

    giorni = s.index.floor("D")
    df_g = pd.DataFrame({
        "Giorno": giorni,
        "MWh potenziali": g,
        "MWh curtailati": np.where(curt, g, 0.0),
        "Beneficio (EUR)": marg_con - marg_senza,
    }).groupby("Giorno", as_index=False).sum()
    df_g["Giorno"] = pd.to_datetime(df_g["Giorno"]).dt.date
    df_g["Quota curtailment %"] = np.where(
        df_g["MWh potenziali"] > 0,
        100.0 * df_g["MWh curtailati"] / df_g["MWh potenziali"], 0.0)

    mesi = s.index.to_period("M").astype(str)
    df_m = pd.DataFrame({
        "Mese": mesi,
        "MWh potenziali": g,
        "MWh curtailati": np.where(curt, g, 0.0),
        "Beneficio (EUR)": marg_con - marg_senza,
    }).groupby("Mese", as_index=False).sum()
    df_m["Beneficio cumulato (EUR)"] = df_m["Beneficio (EUR)"].cumsum()

    return {
        "valido": True, "errore": None,
        "ore_curtailment": ore_curt, "mwh_potenziali": mwh_pot,
        "mwh_curtailed": mwh_curt, "mwh_consegnati": mwh_del,
        "quota_curtailment_pct": quota,
        "ricavo_senza_eur": ricavo_senza, "ricavo_con_eur": ricavo_con,
        "profitto_senza_eur": profitto_senza, "profitto_con_eur": profitto_con,
        "beneficio_eur": beneficio, "onm_risparmiati_eur": onm_risp,
        "cattura_senza_eur_mwh": cattura_senza,
        "cattura_con_eur_mwh": cattura_con,
        "giudizio": giudizio, "verdetto": verdetto,
        "df_giornaliera": df_g, "df_mensile": df_m, "n_ore": n,
        "profilo": profilo, "soglia": soglia,
    }


def calcola_strategia_offerta(prezzi, potenza_mw=5.0, costo_marginale=45.0,
                              quota_volume=90.0, n_punti=61):
    """Strategia di offerta di vendita sul day-ahead (lato produttore).

    Domanda operativa: "Ho un impianto da P MW con costo marginale cm da
    vendere sul mercato day-ahead in pay-as-cleared (se l'offerta a b
    EUR/MWh viene accettata incasso il prezzo di clearing, non b) — a che
    prezzo di offerta entro, ora per ora, per massimizzare il margine
    atteso?"

    Modello (price-taker: l'offerta non sposta il prezzo; distribuzione
    empirica dei prezzi storici per fascia oraria h):
      quota(b)   = P(spot_h >= b)                    l'offerta "cleara" se il
                                                     clearing >= b
      margine(b) = E[(spot_h - cm) * 1(spot_h >= b)]  per MWh offerto
      cattura(b) = E[spot_h | spot_h >= b]
    Per b >= cm ogni ora clearata ha margine >= 0, e alzare b rimuove solo
    termini positivi: il massimo del margine atteso e' a b = cm (risultato
    classico: in pay-as-cleared senza potere di mercato l'offerta ottima
    e' il costo marginale). Un bid piu' basso aumenta la quota venduta
    (certezza di dispatch) a costo di un margine atteso minore: la tab
    calcola la frontiera margine-vs-quota (bid uniforme) e tre politiche
    di bid per fascia oraria:
      "margine" (b = cm: margine atteso massimo),
      "volume"  (b = quantile orario con quota venduta ~= quota_volume %),
      "prezzo"  (b = mediana oraria: vende solo la meta' migliore delle
                 ore, cattura piu' alta ma meno MWh),
    piu' il baseline "mercato" (b = -inf: vende tutto, anche le ore in
    perdita).

    Differenza vs tab75 (Backtest ordini limite): quella e' lato domanda
    (a che prezzo limite COMPRARE per risparmiare); questa e' lato
    produttore (a che prezzo di offerta VENDERE per massimizzare il
    margine, con costo marginale, quota di vendita e prezzo di cattura).
    Diversa anche da tab101 (Dispatch ottimale: unit commitment con
    vincoli tecnici) e da tab177 (autoproduzione vs acquisto): qui nessun
    vincolo di impianto, solo strategia di offerta al mercato.

    Ritorna dict con 'valido'/'errore', n_ore, n_giorni, potenza_mw,
    costo_marginale, quota_volume, grid_bid, df_frontiera, politiche
    (per 'margine', 'volume', 'prezzo', 'mercato': bids_orari (24),
    marg_giorno_eur, margine_atteso_eur (periodo), quota_venduta_pct,
    cattura_eur_mwh, mwh_venduti_attesi), df_oraria (24 righe), df_mensile,
    giudizio, verdetto.

    Giudizio: "NON CONVENIENTE" (margine atteso <= 0 con la politica
    ottima), "STRATEGIA CONSIGLIATA" (quota venduta >= 50%),
    "MARGINALE" (quota >= 10%), "MERCATO DIFFICILE" (quota < 10%).

    NaN-safe: serie vuota / non Series / indice non-datetime, parametri
    non validi -> errore pulito; duplicati keep-first, tz-aware reso
    naive, deterministico (nessuna componente casuale).
    """
    def _err(msg):
        return {"valido": False, "errore": msg}

    # --- pulizia serie prezzi (stesso schema delle altre tab) ---
    if not isinstance(prezzi, pd.Series):
        return _err("prezzi deve essere una Series pandas con indice datetime.")
    s = prezzi.copy()
    try:
        s.index = pd.to_datetime(s.index, errors="coerce")
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    if s.index.isna().any():
        return _err("prezzi deve avere un indice datetime valido.")
    try:
        if getattr(s.index, "tz", None) is not None:
            s.index = s.index.tz_localize(None)
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    s = pd.to_numeric(s, errors="coerce").dropna()
    if len(s) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")
    spot = s.to_numpy(dtype=float)
    n = len(s)
    n_giorni = n / 24.0

    # --- validazione parametri ---
    def _num(v, nome, minimo, massimo=None):
        if isinstance(v, bool):
            return None, f"{nome} deve essere un numero."
        try:
            x = float(v)
        except (TypeError, ValueError):
            return None, f"{nome} deve essere un numero."
        if not np.isfinite(x) or x < minimo:
            return None, f"{nome} deve essere un numero >= {minimo}."
        if massimo is not None and x > massimo:
            return None, f"{nome} deve essere un numero <= {massimo}."
        return x, None

    pmw, em = _num(potenza_mw, "potenza_mw", 1e-9, 100000.0)
    if em:
        return _err(em)
    cm, em = _num(costo_marginale, "costo_marginale", -10000.0, 10000.0)
    if em:
        return _err(em)
    qv, em = _num(quota_volume, "quota_volume", 1e-9, 100.0)
    if em:
        return _err(em)
    if isinstance(n_punti, bool):
        return _err("n_punti deve essere un intero.")
    try:
        np_i = int(n_punti)
    except (TypeError, ValueError):
        return _err("n_punti deve essere un intero.")
    if np_i < 11 or np_i > 501:
        return _err("n_punti deve essere tra 11 e 501.")

    # --- gruppi per fascia oraria ---
    ore = s.index.hour.to_numpy()
    gruppi = [spot[ore == h] for h in range(24)]

    def _riepilogo(ss, bids_pol):
        """Metriche attese per una sottoserie, date le politiche di bid."""
        sp = ss.to_numpy(dtype=float)
        oh = ss.index.hour.to_numpy()
        out = {}
        per_ora = []
        for h in range(24):
            g = sp[oh == h]
            riga = {"Ora": h}
            for nome, bids in bids_pol.items():
                b = bids[h]
                if g.size == 0:
                    riga[f"quota_{nome}"] = 0.0
                    riga[f"marg_{nome}"] = 0.0
                    riga[f"bid_{nome}"] = b
                    continue
                cl = g >= b
                riga[f"quota_{nome}"] = float(cl.mean())
                riga[f"marg_{nome}"] = float(np.where(cl, g - cm, 0.0).mean())
                riga[f"bid_{nome}"] = b
            per_ora.append(riga)
        for nome in bids_pol:
            qq = np.array([r[f"quota_{nome}"] for r in per_ora])
            mm = np.array([r[f"marg_{nome}"] for r in per_ora])
            nh = np.array([float((oh == h).sum()) for h in range(24)])
            marg_giorno = pmw * float(mm.sum())
            vend = pmw * float((qq * nh).sum())
            pot = pmw * float(nh.sum())
            quota = 100.0 * vend / pot if pot > 0 else 0.0
            catt = 0.0
            if vend > 0:
                num = 0.0
                den = 0.0
                for h in range(24):
                    g = sp[oh == h]
                    b = bids_pol[nome][h]
                    cl = g >= b
                    if cl.any():
                        num += float(g[cl].mean()) * float(cl.mean()) * float(g.size)
                        den += float(cl.mean()) * float(g.size)
                catt = num / den if den > 0 else 0.0
            out[nome] = {"marg_giorno_eur": marg_giorno,
                         "mwh_venduti": vend, "mwh_potenziali": pot,
                         "quota_pct": quota, "cattura": catt}
        return out, per_ora

    # --- politiche di bid per fascia oraria ---
    bids_pol = {
        "margine": np.full(24, cm),
        "volume": np.array([float(np.quantile(g, 1.0 - qv / 100.0))
                            if g.size else cm for g in gruppi]),
        "prezzo": np.array([float(np.median(g)) if g.size else cm
                            for g in gruppi]),
        "mercato": np.full(24, -np.inf),
    }

    r0, per_ora = _riepilogo(s, bids_pol)
    politiche = {}
    for nome in ("margine", "volume", "prezzo", "mercato"):
        rr = r0[nome]
        politiche[nome] = {
            "bids_orari": bids_pol[nome].copy(),
            "marg_giorno_eur": rr["marg_giorno_eur"],
            "margine_atteso_eur": rr["marg_giorno_eur"] * n_giorni,
            "quota_venduta_pct": rr["quota_pct"],
            "cattura_eur_mwh": rr["cattura"],
            "mwh_venduti_attesi": rr["mwh_venduti"],
        }

    # --- frontiera margine-vs-quota con bid uniforme ---
    grid = np.unique(np.quantile(spot, np.linspace(0.0, 1.0, np_i)))
    fr_bid, fr_marg, fr_quota = [], [], []
    for b in grid:
        q_t = 100.0 * float(np.mean(spot >= b))
        m_t = pmw * float(sum(np.where(g >= b, g - cm, 0.0).mean()
                              for g in gruppi if g.size))
        fr_bid.append(float(b))
        fr_marg.append(m_t)
        fr_quota.append(q_t)
    df_frontiera = pd.DataFrame({
        "Bid (EUR/MWh)": fr_bid,
        "Margine atteso/giorno (EUR)": fr_marg,
        "Quota venduta %": fr_quota,
    })

    # --- tabella oraria (24 righe) ---
    df_oraria = pd.DataFrame([{
        "Ora": r["Ora"],
        "Bid margine": r["bid_margine"],
        "Bid volume": r["bid_volume"],
        "Bid prezzo": r["bid_prezzo"],
        "Quota margine %": 100.0 * r["quota_margine"],
        "Quota volume %": 100.0 * r["quota_volume"],
        "Quota prezzo %": 100.0 * r["quota_prezzo"],
        "Margine/giorno margine (EUR)": pmw * r["marg_margine"],
        "Margine/giorno volume (EUR)": pmw * r["marg_volume"],
        "Margine/giorno prezzo (EUR)": pmw * r["marg_prezzo"],
    } for r in per_ora])

    # --- tabella mensile ---
    mesi = s.index.to_period("M").astype(str)
    righe_m = []
    for m in sorted(mesi.unique()):
        sub = s[mesi == m]
        rm, _ = _riepilogo(sub, bids_pol)
        ngm = len(sub) / 24.0
        riga = {"Mese": m}
        for nome in ("margine", "volume", "prezzo", "mercato"):
            riga[f"Margine {nome} (EUR)"] = rm[nome]["marg_giorno_eur"] * ngm
            riga[f"Quota {nome} %"] = rm[nome]["quota_pct"]
        righe_m.append(riga)
    df_mensile = pd.DataFrame(righe_m, columns=[
        "Mese",
        "Margine margine (EUR)", "Margine volume (EUR)",
        "Margine prezzo (EUR)", "Margine mercato (EUR)",
        "Quota margine %", "Quota volume %", "Quota prezzo %",
        "Quota mercato %",
    ])

    # --- giudizio ---
    m_marg = politiche["margine"]["margine_atteso_eur"]
    q_marg = politiche["margine"]["quota_venduta_pct"]
    if m_marg <= 0:
        giudizio = "NON CONVENIENTE"
        verdetto = (f"Con costo marginale {cm:,.2f} EUR/MWh il margine atteso "
                    f"e' {m_marg:,.0f} EUR sul periodo: i prezzi storici "
                    f"coprono raramente il costo. Meglio non offrire (o "
                    f"ridurre il costo marginale).")
    elif q_marg >= 50.0:
        giudizio = "STRATEGIA CONSIGLIATA"
        verdetto = (f"Offrendo a {cm:,.2f} EUR/MWh (costo marginale) vendi il "
                    f"{q_marg:.0f}% delle ore con margine atteso "
                    f"{m_marg:,.0f} EUR sul periodo: in pay-as-cleared e' "
                    f"l'offerta che massimizza il margine atteso. Bid piu' "
                    f"bassi aumentano la quota venduta a costo del margine "
                    f"(vedi frontiera).")
    elif q_marg >= 10.0:
        giudizio = "MARGINALE"
        verdetto = (f"Margine atteso positivo ({m_marg:,.0f} EUR) ma quota "
                    f"venduta bassa ({q_marg:.0f}%): l'impianto cleara poche "
                    f"ore. Valuta se abbassare il bid per vendere di piu' "
                    f"(politica 'volume') accettando un margine minore.")
    else:
        giudizio = "MERCATO DIFFICILE"
        verdetto = (f"Solo il {q_marg:.0f}% delle ore copre il costo "
                    f"marginale ({cm:,.2f} EUR/MWh): il mercato day-ahead "
                    f"storico e' difficile per questo impianto. Margine "
                    f"atteso {m_marg:,.0f} EUR.")

    return {
        "valido": True, "errore": None,
        "n_ore": n, "n_giorni": n_giorni,
        "potenza_mw": pmw, "costo_marginale": cm, "quota_volume": qv,
        "grid_bid": grid, "df_frontiera": df_frontiera,
        "politiche": politiche,
        "df_oraria": df_oraria, "df_mensile": df_mensile,
        "giudizio": giudizio, "verdetto": verdetto,
    }


def calcola_valore_capacita(prezzi, potenza_mw=100.0, costo_marginale=60.0,
                          derating_pct=85.0, prezzo_asta_eur_kw=30.0,
                          opex_fisso_eur_kw=25.0, ore_indisponibili=500.0,
                          quota_ore_critiche_pct=2.0,
                          penalita_eur_mw_h=5000.0, n_punti=11,
                          min_ore=168):
    """Remunerazione della capacita' (capacity market) per un produttore.

    Domanda operativa: "Ho un impianto termico da P MW con costo marginale
    cm: quanto mi rende partecipare al mercato della capacita' (asta a
    prezzo fisso EUR/kW/anno sulla potenza de-ratata), tenuto conto del
    margine che farei comunque sull'energia e delle penalita' se sono
    indisponibile nelle ore critiche di sistema?"

    Modello (lato produttore, price-taker sull'energia):
      margine energia = somma oraria max(spot - cm, 0) * P, annualizzato
                        (fattore 8760 / n_ore osservate): l'impianto
                        dispaccia solo quando in-the-money;
      ricavo capacita' = P * derating% * prezzo_asta (EUR/kW/anno);
      penalita'         = P * derating% * penalita' (EUR/MW/h) *
                        ore_indisponibili * quota_ore_critiche% :
                        l'indisponibilita' e' ripartita in modo
                        proporzionale sulle ore dell'anno, quindi la quota
                        attesa di indisponibilita' nelle ore critiche e'
                        ore_indisponibili * quota_critiche%;
      netto annuo       = ricavo_capacita' + margine_energia - penalita'
                        - opex_fisso;
      prezzo_asta break-even = (opex_fisso + penalita' - margine_energia)
                        / (P * derating% in kW), mai negativo.

    La tabella di sensibilita' mostra il netto annuo al variare del
    prezzo d'asta (0 .. 2x il prezzo inserito), per leggere a colpo
    d'occhio il margine di sicurezza sul prezzo.

    Differenza vs tab63 "Margine per impianto" (margine energia puro,
    senza capacita'/penalita'/opex) e vs tab191 (strategia di offerta
    sul day-ahead): questa e' l'economia complessiva dell'impianto in
    un mercato con remunerazione della capacita'.

    Ritorna dict con: valido, errore, n_ore, margine_energia_annuo,
    ore_run_annue, prezzo_medio_run, potenza_derated_mw, ricavo_capacita,
    penalita_annua, opex_fisso_annuo, netto_annuo,
    prezzo_asta_break_even, df_sensibilita (pd.DataFrame),
    df_mensile (pd.DataFrame: margine energia e ore di funzionamento
    per mese del periodo osservato), giudizio, verdetto.

    NaN-safe: serie vuota / non Series / indice non-datetime /
    <min_ore ore / parametri non validi -> errore pulito; tz-aware reso
    naive; duplicati keep-first; deterministico (nessuna componente
    casuale).
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    def _num(x, nome, minimo=None, massimo=None, intero=False):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        if intero:
            if v != int(v):
                return None
            v = int(v)
        if minimo is not None and v < minimo:
            return None
        if massimo is not None and v > massimo:
            return None
        return v

    pmw = _num(potenza_mw, "potenza_mw", minimo=0.01)
    cm = _num(costo_marginale, "costo_marginale")
    dr = _num(derating_pct, "derating_pct", minimo=0.01, massimo=100.0)
    pa = _num(prezzo_asta_eur_kw, "prezzo_asta_eur_kw", minimo=0.0)
    ox = _num(opex_fisso_eur_kw, "opex_fisso_eur_kw", minimo=0.0)
    oi = _num(ore_indisponibili, "ore_indisponibili", minimo=0.0)
    qc = _num(quota_ore_critiche_pct, "quota_ore_critiche_pct",
              minimo=0.0, massimo=100.0)
    pe = _num(penalita_eur_mw_h, "penalita_eur_mw_h", minimo=0.0)
    npt = _num(n_punti, "n_punti", minimo=3, intero=True)
    mho = _num(min_ore, "min_ore", minimo=24, intero=True)
    if None in (pmw, cm, dr, pa, ox, oi, qc, pe, npt, mho):
        return _err("Parametri non validi: potenza > 0, derating in "
                    "(0, 100], prezzo asta / opex / indisponibilita' / "
                    "penalita' >= 0, quota ore critiche in [0, 100], "
                    "n_punti >= 3 intero.")

    if not isinstance(prezzi, pd.Series):
        return _err("La serie dei prezzi deve essere una pd.Series.")
    if not isinstance(prezzi.index, pd.DatetimeIndex):
        return _err("L'indice della serie prezzi deve essere datetime.")
    s = prezzi.copy()
    try:
        if s.index.tz is not None:
            s.index = s.index.tz_convert(None)
    except Exception:
        return _err("Impossibile normalizzare il fuso orario "
                    "dell'indice prezzi.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    s = pd.to_numeric(s, errors="coerce").dropna()
    n = int(len(s))
    if n < mho:
        return _err(f"Servono almeno {mho} ore di prezzi (trovate {n}).")

    # --- margine energia (dispatch in-the-money) ---
    vals = s.to_numpy(dtype=float)
    run = vals >= cm
    marg_ore = np.where(run, (vals - cm) * pmw, 0.0)
    fattore = 8760.0 / n
    marg_energia_annuo = float(marg_ore.sum() * fattore)
    ore_run_annue = float(run.sum() * fattore)
    prezzo_medio_run = (float(vals[run].mean()) if run.any() else 0.0)

    # --- mercato della capacita' ---
    derated_mw = pmw * dr / 100.0
    derated_kw = derated_mw * 1000.0
    ricavo_capacita = derated_kw * pa
    ore_critiche_indisp = oi * qc / 100.0
    penalita_annua = derated_mw * pe * ore_critiche_indisp
    opex_annuo = pmw * 1000.0 * ox
    netto_annuo = ricavo_capacita + marg_energia_annuo - penalita_annua - opex_annuo
    prezzo_asta_be = max(0.0, (opex_annuo + penalita_annua - marg_energia_annuo)
                         / derated_kw)

    # --- giudizio ---
    if netto_annuo >= 0.0:
        giudizio = "CONVENIENTE"
        verdetto = (f"Ricavo netto annuo {netto_annuo:,.0f} EUR: la "
                    f"capacita' ({ricavo_capacita:,.0f} EUR) piu' il margine "
                    f"energia ({marg_energia_annuo:,.0f} EUR) coprono opex "
                    f"fisso ({opex_annuo:,.0f} EUR) e penalita' attese "
                    f"({penalita_annua:,.0f} EUR).")
    elif netto_annuo >= -0.5 * opex_annuo:
        giudizio = "MARGINALE"
        verdetto = (f"Ricavo netto annuo {netto_annuo:,.0f} EUR: perdita "
                    f"contenuta (entro il 50% dell'opex fisso). Alza il "
                    f"prezzo d'asta sopra {prezzo_asta_be:,.2f} EUR/kW/anno "
                    f"per andare a break-even.")
    else:
        giudizio = "NON CONVENIENTE"
        verdetto = (f"Ricavo netto annuo {netto_annuo:,.0f} EUR: la perdita "
                    f"supera il 50% dell'opex fisso. Servirebbe un prezzo "
                    f"d'asta di almeno {prezzo_asta_be:,.2f} EUR/kW/anno "
                    f"per il break-even.")

    # --- sensibilita' al prezzo d'asta ---
    pa_max = max(2.0 * pa, prezzo_asta_be * 1.5, 1.0)
    grid = np.linspace(0.0, pa_max, npt)
    df_sens = pd.DataFrame({
        "Prezzo asta (EUR/kW/anno)": np.round(grid, 2),
        "Ricavo capacita' (EUR/anno)": np.round(derated_kw * grid, 0),
        "Netto annuo (EUR)": np.round(derated_kw * grid + marg_energia_annuo
                                     - penalita_annua - opex_annuo, 0),
    })

    # --- margine energia per mese (periodo osservato, non annualizzato) ---
    df_m = pd.DataFrame({"margine_ore": marg_ore, "run": run.astype(int)},
                        index=s.index)
    mens = df_m.groupby(pd.Grouper(freq="M")).agg(
        margine_eur=("margine_ore", "sum"),
        ore_funzionamento=("run", "sum"))
    mens.index = mens.index.strftime("%Y-%m")
    mens = mens.reset_index().rename(columns={"index": "Mese"})
    mens["Margine energia (EUR)"] = mens["margine_eur"].round(0)
    mens["Ore di funzionamento"] = mens["ore_funzionamento"].astype(int)
    df_mensile = mens[["Mese", "Margine energia (EUR)",
                       "Ore di funzionamento"]]

    return {
        "valido": True, "errore": None,
        "n_ore": n, "fattore_annuo": fattore,
        "potenza_mw": pmw, "costo_marginale": cm,
        "derating_pct": dr, "prezzo_asta_eur_kw": pa,
        "opex_fisso_eur_kw": ox, "ore_indisponibili": oi,
        "quota_ore_critiche_pct": qc, "penalita_eur_mw_h": pe,
        "margine_energia_annuo": marg_energia_annuo,
        "ore_run_annue": ore_run_annue,
        "prezzo_medio_run": prezzo_medio_run,
        "potenza_derated_mw": derated_mw,
        "ricavo_capacita_annuo": ricavo_capacita,
        "penalita_annua": penalita_annua,
        "opex_fisso_annuo": opex_annuo,
        "netto_annuo": netto_annuo,
        "prezzo_asta_break_even": prezzo_asta_be,
        "df_sensibilita": df_sens,
        "df_mensile": df_mensile,
        "giudizio": giudizio, "verdetto": verdetto,
    }

def calcola_ccs(emissioni_annue_t=500000.0, tasso_cattura_pct=90.0,
                penalita_energetica_pct=20.0, costo_ccs_eur_t=90.0,
                prezzo_co2=85.0, potenza_mw=400.0, ore_annue=6000.0,
                n_punti=11):
    """Cattura e stoccaggio della CO2 (CCS) su impianto termoelettrico.

    Domanda operativa: "Il mio impianto emette E tCO2/anno: a che prezzo
    della CO2 conviene installare la cattura (post-combustione) con
    trasporto e stoccaggio geologico?"

    Modello (lato produttore, costi annualizzati):
      emissioni_lorde = E * (1 + penalita_energetica%) : la cattura
                        consuma energia (rigenerazione solvente,
                        compressione) -> piu' combustibile -> piu'
                        emissioni lorde da trattare;
      t_catturate     = emissioni_lorde * tasso_cattura%;
      t_residue       = emissioni_lorde * (1 - tasso_cattura%) : pagano
                        comunque l'ETS;
      costo_ccs       = t_catturate * costo_ccs_eur_t (cattura +
                        trasporto + stoccaggio, EUR/t catturata);
      risparmio_ets   = (E - t_residue) * prezzo_co2;
      netto_annuo     = risparmio_ets - costo_ccs;
      break-even      = costo_ccs / (E - t_residue): prezzo CO2 al
                        quale il CCS si ripaga da solo (None se la
                        penalita' energetica annulla il beneficio).
    La tabella di sensibilita' mostra il netto annuo al variare del
    prezzo CO2 (0 .. max(2x prezzo inserito, 1.5x break-even)).

    Differenza vs tab55 "Costo CO2" (costo ETS dell'impianto senza
    mitigazione) e vs tab185 "CO2 implicita" (intensita' carbonica
    implicita nei prezzi): questa e' l'economia di un investimento di
    decarbonizzazione con break-even regolatorio.

    Ritorna dict con: valido, errore, emissioni_annue_t,
    tasso_cattura_pct, penalita_energetica_pct, costo_ccs_eur_t,
    prezzo_co2, emissioni_lorde_t, t_catturate, t_residue,
    costo_ccs_annuo, costo_ets_senza, costo_ets_con, risparmio_ets,
    netto_annuo, prezzo_co2_break_even (None se n.d.),
    costo_eur_mwh, df_sensibilita (pd.DataFrame), df_confronto
    (pd.DataFrame), giudizio, verdetto.

    NaN-safe: parametri non numerici o fuori dominio -> errore pulito;
    deterministico (nessuna componente casuale).
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    def _num(x, minimo=None, massimo=None, intero=False):
        if isinstance(x, bool):
            return None
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        if not np.isfinite(v):
            return None
        if intero:
            if v != int(v):
                return None
            v = int(v)
        if minimo is not None and v < minimo:
            return None
        if massimo is not None and v > massimo:
            return None
        return v

    E = _num(emissioni_annue_t, minimo=1.0)
    c = _num(tasso_cattura_pct, minimo=0.01, massimo=100.0)
    pe = _num(penalita_energetica_pct, minimo=0.0, massimo=200.0)
    ca = _num(costo_ccs_eur_t, minimo=0.0)
    p = _num(prezzo_co2, minimo=0.0)
    pmw = _num(potenza_mw, minimo=0.01)
    ore = _num(ore_annue, minimo=1.0, massimo=8760.0)
    npt = _num(n_punti, minimo=3, intero=True)
    if None in (E, c, pe, ca, p, pmw, ore, npt):
        return _err("Parametri non validi: emissioni > 0, tasso di "
                    "cattura in (0, 100], penalita' energetica in "
                    "[0, 200], costo CCS / prezzo CO2 >= 0, potenza > 0, "
                    "ore annue in (0, 8760], n_punti >= 3 intero.")

    # --- bilancio di massa ---
    lorde = E * (1.0 + pe / 100.0)
    catt = lorde * c / 100.0
    res = lorde * (1.0 - c / 100.0)

    # --- economia annua ---
    costo_ccs = catt * ca
    ets_senza = E * p
    ets_con = res * p
    risparmio = ets_senza - ets_con
    netto = risparmio - costo_ccs
    denom_be = E - res
    be = costo_ccs / denom_be if denom_be > 0 else None
    mwh_annui = pmw * ore
    costo_mwh = costo_ccs / mwh_annui

    # --- giudizio ---
    if netto >= 0.25 * ets_senza:
        giudizio = "MOLTO CONVENIENTE"
        verdetto = (f"Beneficio netto annuo {netto:,.0f} EUR (>= 25% del "
                    f"costo ETS senza CCS, {ets_senza:,.0f} EUR): il CCS "
                    f"si ripaga ampiamente al prezzo CO2 corrente "
                    f"({p:,.0f} EUR/t).")
    elif netto >= 0.0:
        giudizio = "CONVENIENTE"
        verdetto = (f"Beneficio netto annuo {netto:,.0f} EUR: il risparmio "
                    f"ETS ({risparmio:,.0f} EUR) copre il costo del CCS "
                    f"({costo_ccs:,.0f} EUR).")
    elif netto >= -0.10 * ets_senza:
        giudizio = "MARGINALE"
        verdetto = (f"Beneficio netto annuo {netto:,.0f} EUR: perdita "
                    f"contenuta (entro il 10% del costo ETS). Servirebbe "
                    f"un prezzo CO2 di almeno "
                    f"{be:,.0f} EUR/t per il break-even."
                    if be is not None else
                    f"Beneficio netto annuo {netto:,.0f} EUR: la "
                    f"penalita' energetica annulla quasi tutto il "
                    f"beneficio di cattura.")
    else:
        verdetto = (f"Beneficio netto annuo {netto:,.0f} EUR: il costo del "
                    f"CCS ({costo_ccs:,.0f} EUR) supera di molto il "
                    f"risparmio ETS ({risparmio:,.0f} EUR)."
                    + (f" Break-even a {be:,.0f} EUR/t di CO2."
                       if be is not None else ""))
        giudizio = "NON CONVENIENTE"

    # --- sensibilita' al prezzo CO2 ---
    p_max = max(2.0 * p, (be * 1.5 if be is not None else 0.0), 1.0)
    grid = np.linspace(0.0, p_max, npt)
    df_sens = pd.DataFrame({
        "Prezzo CO2 (EUR/t)": np.round(grid, 1),
        "Risparmio ETS (EUR/anno)": np.round((E - res) * grid, 0),
        "Netto annuo (EUR)": np.round((E - res) * grid - costo_ccs, 0),
    })

    # --- confronto scenari ---
    df_conf = pd.DataFrame({
        "Scenario": ["Senza CCS", "Con CCS"],
        "Costo ETS (EUR/anno)": [round(ets_senza, 0), round(ets_con, 0)],
        "Costo CCS (EUR/anno)": [0.0, round(costo_ccs, 0)],
        "Totale (EUR/anno)": [round(ets_senza, 0),
                              round(ets_con + costo_ccs, 0)],
        "Emissioni nette (t/anno)": [round(E, 0), round(res, 0)],
    })

    return {
        "valido": True, "errore": None,
        "emissioni_annue_t": E, "tasso_cattura_pct": c,
        "penalita_energetica_pct": pe, "costo_ccs_eur_t": ca,
        "prezzo_co2": p,
        "emissioni_lorde_t": lorde, "t_catturate": catt,
        "t_residue": res,
        "costo_ccs_annuo": costo_ccs, "costo_ets_senza": ets_senza,
        "costo_ets_con": ets_con, "risparmio_ets": risparmio,
        "netto_annuo": netto, "prezzo_co2_break_even": be,
        "costo_eur_mwh": costo_mwh,
        "df_sensibilita": df_sens, "df_confronto": df_conf,
        "giudizio": giudizio, "verdetto": verdetto,
    }

def calcola_cogenerazione(prezzi, potenza_mw=1.0, rend_elettrico=0.38,
                          rend_termico=0.45, prezzo_gas=40.0, prezzo_co2=80.0,
                          fattore_emissione=0.202, valore_calore=55.0,
                          eta_e_ref=0.525, eta_t_ref=0.90):
    """Cogenerazione (CHP): spark spread con credito termico + PES per CAR.

    Domanda operativa: "Ho un cogeneratore da P MW — in quali ore conviene
    farlo girare, quanto margine fa, e si qualifica come cogenerazione ad
    alto rendimento (CAR)?"

    Per ogni MWh elettrico prodotto servono 1/eta_e MWh di combustibile e si
    producono eta_t/eta_e MWh di calore utile:
      costo_fuel_e   = (prezzo_gas + prezzo_co2 * fattore_emissione) / eta_e
      credito_termico_e = (eta_t / eta_e) * valore_calore
      strike = costo_fuel_e - credito_termico_e   (EUR/MWh elettrico)
    L'impianto marcia nelle ore con spot > strike (dispatch a spark spread);
    il margine orario e' (spot - strike) * potenza_mw.

    Risparmio di energia primaria (Direttiva efficienza energetica):
      PES = 1 - 1 / (eta_e/eta_e_ref + eta_t/eta_t_ref)
    CAR (cogenerazione ad alto rendimento) se PES >= 10%.

    Ritorna dict con 'valido'/'errore', prezzo_strike, ore_funzionamento,
    fattore_carico_pct, mwh_elettrici, mwh_termici, mwh_fuel,
    margine_totale_eur, margine_medio_eur_mwh, clean_spark_medio_eur_mwh,
    costo_fuel_eur, ricavo_elettrico_eur, valore_calore_eur, pes_pct,
    qualifica_car, giudizio, verdetto, df_giornaliera, df_mensile,
    n_ore, n_giorni.

    Giudizio sul margine totale e sul fattore di carico:
    "MOLTO REDDITIZIO" (margine > 0 e CF >= 50%),
    "REDDITIZIO" (margine > 0 e CF >= 25%),
    "MARGINALE" (margine > 0), altrimenti "IN PERDITA".

    NaN-safe: serie vuota / non numerica / indice non-datetime, parametri
    non validi -> errore pulito, mai eccezioni.
    """
    def _err(msg):
        return {"valido": False, "errore": msg}

    # --- pulizia serie prezzi (stesso schema delle altre tab) ---
    if not isinstance(prezzi, pd.Series):
        return _err("prezzi deve essere una Series pandas con indice datetime.")
    s = prezzi.copy()
    try:
        s.index = pd.to_datetime(s.index, errors="coerce")
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    if s.index.isna().any():
        return _err("prezzi deve avere un indice datetime valido.")
    try:
        if getattr(s.index, "tz", None) is not None:
            s.index = s.index.tz_localize(None)
    except Exception:
        return _err("prezzi deve avere un indice datetime valido.")
    s = s[~s.index.duplicated(keep="first")].sort_index()
    s = pd.to_numeric(s, errors="coerce").dropna()
    if len(s) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")
    spot = s.to_numpy(dtype=float)
    n = len(s)

    # --- validazione parametri ---
    def _num(v, nome, minimo, massimo=None):
        if isinstance(v, bool):
            return None, f"{nome} deve essere un numero."
        try:
            x = float(v)
        except (TypeError, ValueError):
            return None, f"{nome} deve essere un numero."
        if not np.isfinite(x) or x < minimo:
            return None, f"{nome} deve essere un numero >= {minimo}."
        if massimo is not None and x > massimo:
            return None, f"{nome} deve essere un numero <= {massimo}."
        return x, None

    pmw, em = _num(potenza_mw, "potenza_mw", 1e-9, 1000.0)
    if em:
        return _err(em)
    etae, em = _num(rend_elettrico, "rend_elettrico", 1e-9, 0.99)
    if em:
        return _err(em)
    etat, em = _num(rend_termico, "rend_termico", 0.0, 0.99)
    if em:
        return _err(em)
    if etae + etat > 0.99:
        return _err("rend_elettrico + rend_termico deve essere < 0.99.")
    pgas, em = _num(prezzo_gas, "prezzo_gas", 0.0)
    if em:
        return _err(em)
    pco2, em = _num(prezzo_co2, "prezzo_co2", 0.0)
    if em:
        return _err(em)
    ef, em = _num(fattore_emissione, "fattore_emissione", 0.0, 2.0)
    if em:
        return _err(em)
    vcal, em = _num(valore_calore, "valore_calore", 0.0)
    if em:
        return _err(em)
    eref, em = _num(eta_e_ref, "eta_e_ref", 1e-9, 0.99)
    if em:
        return _err(em)
    tref, em = _num(eta_t_ref, "eta_t_ref", 1e-9, 0.99)
    if em:
        return _err(em)

    # --- economia per MWh elettrico ---
    costo_fuel_e = (pgas + pco2 * ef) / etae
    credito_termico_e = (etat / etae) * vcal
    strike = costo_fuel_e - credito_termico_e

    run = spot > strike
    ore_run = int(run.sum())
    margine_h = np.where(run, (spot - strike) * pmw, 0.0)
    margine_tot = float(margine_h.sum())
    margine_medio = float(margine_h[run].mean() / pmw) if ore_run else 0.0
    clean_spark = float(((spot - costo_fuel_e)[run]).mean()) if ore_run else 0.0

    mwh_e = pmw * ore_run
    mwh_t = pmw * (etat / etae) * ore_run
    mwh_fuel = pmw / etae * ore_run
    ricavo_e = float((spot[run] * pmw).sum())
    costo_fuel = costo_fuel_e * mwh_e
    valore_cal = credito_termico_e * mwh_e
    cf = 100.0 * ore_run / n

    pes = 1.0 - 1.0 / (etae / eref + etat / tref)
    pes_pct = 100.0 * pes
    car = bool(pes >= 0.10)

    if margine_tot <= 0:
        giudizio = "IN PERDITA"
    elif cf >= 50.0:
        giudizio = "MOLTO REDDITIZIO"
    elif cf >= 25.0:
        giudizio = "REDDITIZIO"
    else:
        giudizio = "MARGINALE"

    verdetto = (
        f"Strike {strike:,.2f} EUR/MWh: l'impianto marcia {ore_run} ore su {n} "
        f"(CF {cf:.1f}%), margine {margine_tot:,.0f} EUR "
        f"({margine_medio:,.2f} EUR/MWh elettrico). "
        f"PES {pes_pct:.1f}% -> {'SI qualifica come CAR' if car else 'NON si qualifica come CAR'} "
        f"(soglia 10%)."
    )

    # --- aggregazioni ---
    df_h = pd.DataFrame({"ts": s.index, "margine": margine_h, "run": run})
    df_h["giorno"] = df_h["ts"].dt.date
    g = df_h.groupby("giorno", as_index=False)
    df_giornaliera = pd.DataFrame({
        "Giorno": g["giorno"].first()["giorno"],
        "MWh elettrici": g["run"].sum()["run"] * pmw,
        "MWh termici": g["run"].sum()["run"] * pmw * (etat / etae),
        "Ore funzionamento": g["run"].sum()["run"].astype(int),
        "Margine (EUR)": g["margine"].sum()["margine"],
    })
    df_h["mese"] = df_h["ts"].dt.to_period("M").astype(str)
    m = df_h.groupby("mese", as_index=False)
    df_mensile = pd.DataFrame({
        "Mese": m["mese"].first()["mese"],
        "Margine (EUR)": m["margine"].sum()["margine"],
        "Ore funzionamento": m["run"].sum()["run"].astype(int),
    })
    df_mensile["Margine cumulato (EUR)"] = df_mensile["Margine (EUR)"].cumsum()

    return {"valido": True, "errore": None,
            "prezzo_strike": strike,
            "ore_funzionamento": ore_run, "fattore_carico_pct": cf,
            "mwh_elettrici": mwh_e, "mwh_termici": mwh_t,
            "mwh_fuel": mwh_fuel,
            "margine_totale_eur": margine_tot,
            "margine_medio_eur_mwh": margine_medio,
            "clean_spark_medio_eur_mwh": clean_spark,
            "costo_fuel_eur": costo_fuel,
            "ricavo_elettrico_eur": ricavo_e,
            "valore_calore_eur": valore_cal,
            "pes_pct": pes_pct, "qualifica_car": car,
            "giudizio": giudizio, "verdetto": verdetto,
            "df_giornaliera": df_giornaliera, "df_mensile": df_mensile,
            "n_ore": n, "n_giorni": int(df_giornaliera.shape[0])}


def calcola_pca_forma_prezzo(prezzi, n_fattori=3, min_giorni=30):
    """PCA dei profili orari di prezzo (24h): i fattori di forma della curva.

    Domanda operativa: "Quando il prezzo si muove durante il giorno, cosa
    si muove davvero -- il livello generale, lo spread giorno/notte, la
    forma dei picchi?" La PCA sui profili orari giornalieri (matrice
    giorni x 24 ore) estrae i fattori ortogonali che spiegano la varianza:
    gli stessi "livello / pendenza / curvatura" della curva dei rendimenti,
    qui applicati alla curva oraria del prezzo spot.

    Metodo: si tengono solo i giorni completi (24 ore; i giorni con ore
    mancanti -- es. cambi d'ora -- sono scartati e conteggiati); centratura
    sulle medie di colonna; autodecomposizione della covarianza 24x24 con
    eigh (deterministico a meno del segno: il segno di ciascun fattore e'
    fissato per convenzione -- correlazione positiva con la forma di
    riferimento meglio corrispondente -- cosi' l'output e' stabile tra
    esecuzioni); loadings = autovettori, scores = proiezione dei profili
    centrati sui fattori.

    Interpretazione automatica di ciascun fattore:
      - "Livello": loadings quasi costanti (shift parallelo del profilo;
        CV = std/|media| < 0.5);
      - "Pendenza giorno/notte": |corr| >= 0.60 con la rampa 0..23;
      - "Curvatura (picchi)": |corr| >= 0.60 con (ora-11.5)^2;
      altrimenti "Forma residua". Per il Livello la colonna
    "|Correlazione|" riporta l'indice di piattezza 1-CV.

    Differenza vs tab36 "Decomposizione" (scomposizione temporale
    trend/stagionale/residuo della serie) e vs tab71 "Struttura a termine"
    (curva forward): qui si scompone la FORMA ORARIA del prezzo in fattori
    di rischio indipendenti, utili per disegnare coperture per fascia.

    Ritorna dict con: valido, errore, giorni_validi, giorni_scartati,
    n_fattori, autovalori (tutti i 24, decrescenti), var_spiegata_pct,
    var_cumulata_pct, k_95 (fattori per il 95% della varianza),
    df_loadings (Ora + Fattore 1..k), df_scores (Giorno + Score F1..Fk),
    interpretazione (DataFrame), profilo_medio (Series 0..23), verdetto.

    NaN-safe: serie vuota / indice non-datetime / meno di min_giorni
    giorni completi / varianza nulla -> errore pulito; mai eccezioni.
    """
    def _err(msg):
        return {"errore": msg, "valido": False, "giorni_validi": 0,
                "giorni_scartati": 0, "n_fattori": 0, "autovalori": [],
                "var_spiegata_pct": [], "var_cumulata_pct": [], "k_95": 0,
                "df_loadings": pd.DataFrame(), "df_scores": pd.DataFrame(),
                "interpretazione": pd.DataFrame(),
                "profilo_medio": pd.Series(dtype=float), "verdetto": ""}

    def _num_int(x, minimo, massimo):
        if isinstance(x, bool):
            return None
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        if not np.isfinite(v) or v != int(v):
            return None
        v = int(v)
        if v < minimo or v > massimo:
            return None
        return v

    k = _num_int(n_fattori, 1, 24)
    mg = _num_int(min_giorni, 5, 3650)
    if k is None or mg is None:
        return _err("Parametri non validi: n_fattori intero in [1, 24], "
                    "min_giorni intero >= 5.")
    try:
        p = pd.to_numeric(pd.Series(prezzi), errors="coerce").dropna()
    except Exception:
        return _err("Serie prezzi non valida.")
    if len(p) == 0:
        return _err("Serie prezzi vuota.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("La serie deve avere un indice datetime orario.")
    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    try:
        d = pd.DataFrame({"p": p.to_numpy(dtype=float),
                          "giorno": idxn.date, "ora": idxn.hour})
    except Exception:
        return _err("Serie prezzi non valida.")
    n_date_totali = int(d["giorno"].nunique())
    pv = d.pivot_table(index="giorno", columns="ora", values="p",
                       aggfunc="mean")
    pv = pv.reindex(columns=list(range(24))).dropna()
    scartati = n_date_totali - len(pv)
    if len(pv) < mg:
        return _err("Giorni completi insufficienti: %d trovati, ne "
                    "servono almeno %d." % (len(pv), mg))
    X = pv.to_numpy(dtype=float)
    n = X.shape[0]
    profilo = X.mean(axis=0)
    Xc = X - profilo
    var_tot = float(np.sum(Xc ** 2) / (n - 1)) if n > 1 else 0.0
    if not np.isfinite(var_tot) or var_tot <= 0:
        return _err("Serie senza varianza: tutti i profili giornalieri "
                    "sono identici.")
    cov = (Xc.T @ Xc) / (n - 1)
    try:
        autoval, autovet = np.linalg.eigh(cov)
    except Exception:
        return _err("Decomposizione non riuscita.")
    order = np.argsort(autoval)[::-1]
    autoval = np.clip(autoval[order], 0.0, None)
    autovet = autovet[:, order]
    somma = float(autoval.sum())
    if not np.isfinite(somma) or somma <= 0:
        return _err("Serie senza varianza: tutti i profili giornalieri "
                    "sono identici.")
    var_pct = 100.0 * autoval / somma
    cum_pct = np.cumsum(var_pct)
    k95 = int(np.searchsorted(cum_pct, 95.0) + 1)

    ore = np.arange(24, dtype=float)
    rif_pen = ore - ore.mean()
    rif_cur = (ore - 11.5) ** 2
    rif_cur = rif_cur - rif_cur.mean()

    def _corr(a, b):
        a = np.asarray(a, dtype=float)
        b = np.asarray(b, dtype=float)
        sa = a.std(ddof=0)
        sb = b.std(ddof=0)
        if not np.isfinite(sa) or not np.isfinite(sb) or sa == 0 or sb == 0:
            return 0.0
        r = float(np.mean((a - a.mean()) * (b - b.mean())) / (sa * sb))
        return max(-1.0, min(1.0, r))

    kk = min(k, 24)
    loadings = autovet[:, :kk].copy()
    scores = Xc @ loadings
    tipi, corrs = [], []
    for j in range(kk):
        v = loadings[:, j]
        mv = float(np.mean(v))
        sv = float(v.std(ddof=0))
        cv = sv / (abs(mv) + 1e-12)
        if cv < 0.5 and abs(mv) > 1e-12:
            # shift (quasi) parallelo del profilo -> livello
            if mv < 0:
                loadings[:, j] = -v
                scores[:, j] = -scores[:, j]
            tipi.append("Livello")
            corrs.append(round(max(0.0, 1.0 - cv), 3))
            continue
        r_pen = _corr(v, rif_pen)
        r_cur = _corr(v, rif_cur)
        if abs(r_pen) >= abs(r_cur):
            nome, r = "pen", r_pen
        else:
            nome, r = "cur", r_cur
        if r < 0:
            loadings[:, j] = -v
            scores[:, j] = -scores[:, j]
            r = -r
        if nome == "pen" and r >= 0.60:
            tipo = "Pendenza giorno/notte"
        elif nome == "cur" and r >= 0.60:
            tipo = "Curvatura (picchi)"
        else:
            tipo = "Forma residua"
        tipi.append(tipo)
        corrs.append(round(r, 3))

    df_load = pd.DataFrame({"Ora": list(range(24))})
    for j in range(kk):
        df_load["Fattore %d" % (j + 1)] = np.round(loadings[:, j], 4)
    df_sco = pd.DataFrame({"Giorno": [str(g) for g in pv.index]})
    for j in range(kk):
        df_sco["Score F%d" % (j + 1)] = np.round(scores[:, j], 2)
    df_int = pd.DataFrame({
        "Fattore": ["F%d" % (j + 1) for j in range(kk)],
        "Varianza spiegata %": [round(float(var_pct[j]), 2)
                                for j in range(kk)],
        "Varianza cumulata %": [round(float(cum_pct[j]), 2)
                                for j in range(kk)],
        "Tipo": tipi,
        "|Correlazione|": corrs,
    })
    if k95 <= 2:
        hint = ("Il movimento del prezzo e' quasi unidimensionale: per "
                "l'hedging basta coprire il livello, la forma oraria e' "
                "stabile.")
    elif k95 <= 4:
        hint = ("Il prezzo si muove su poche dimensioni indipendenti: "
                "gestisci livello e forma (spread giorno/notte, picchi) "
                "come rischi separati.")
    else:
        hint = ("Il prezzo ha molte dimensioni indipendenti: servono "
                "coperture granulari per fascia oraria, un solo prodotto "
                "base/peak non basta.")
    verdetto = ("%d %s il 95%% della varianza dei profili giornalieri "
                "(%d giorni completi). Fattore dominante: %s (%.1f%% della "
                "varianza). %s" % (
                    k95, "fattore spiega" if k95 == 1 else "fattori spiegano",
                    n, tipi[0], float(var_pct[0]), hint))
    return {"errore": None, "valido": True, "giorni_validi": int(n),
            "giorni_scartati": int(scartati), "n_fattori": int(kk),
            "autovalori": [float(v) for v in autoval],
            "var_spiegata_pct": [float(v) for v in var_pct],
            "var_cumulata_pct": [float(v) for v in cum_pct],
            "k_95": k95, "df_loadings": df_load, "df_scores": df_sco,
            "interpretazione": df_int,
            "profilo_medio": pd.Series(profilo, index=list(range(24))),
            "verdetto": verdetto}


def calcola_copertura_proxy(pa, pb, forward_hub, mw=1.0):
    """Copertura proxy (cross-hedge) dello Swissix con il prodotto di un hub vicino.

    Domanda operativa: "Non esistono future liquidi sullo Swissix: mi copro
    comprando baseload tedesco (o francese) a termine. Quanto rischio mi resta
    davvero?" -- il buyer paga lo spot Swissix pa ogni ora e compra h MW di
    forward sull'hub B al prezzo F: costo netto unitario
      c(h) = pa - h * (pb - F)
    (il forward incassa a scadenza la differenza tra spot hub realizzato e
    prezzo fissato). Il ratio di minima varianza e' h* = Cov(pa, pb)/Var(pb);
    l'efficacia e' 1 - Var(c(h*))/Var(pa) = R^2 della regressione di pa su pb.
    Quello che resta e' il BASIS RISK: la basis b = pa - pb non e' copribile
    col prodotto hub.

    Differenza dalle altre tab: tab52 "Hedge ratio" calcola il ratio ottimale
    su un forward SINTETICO (media mobile della stessa serie); tab112 "Spread
    transfrontaliero" valorizza la capacita' di interconnessione (lato offerta
    di trasporto); tab131 "Test efficacia hedge" monitora nel tempo una
    copertura esistente su fixing interno. Qui si dimensiona e si prezza una
    copertura REALE su un SECONDO mercato (due serie storiche allineate), con
    il prezzo forward inserito dall'utente e il confronto tra hedge naive 1:1
    e hedge ottimale di minima varianza.

    Parametri:
      pa: serie oraria spot Swissix (€/MWh);
      pb: serie oraria spot hub B (€/MWh), allineata per timestamp (inner join);
      forward_hub: prezzo forward bloccabile sull'hub (€/MWh);
      mw: MW di consumo da coprire (scala i controvalori).

    Ritorna dict con: valido, errore, n_ore, h_star, correlazione, r2,
    std_spot, std_residua_star, std_residua_naive, eff_naive,
    costo_atteso_spot, costo_atteso_star, costo_atteso_naive (€/MWh),
    controvalore_spot, controvalore_star (€ totali),
    basis_media, basis_std, basis_min, basis_max, profilo_basis (lista 24),
    df_h (h, efficacia), df_basis (Ora, Basis media),
    pa_allineata, pb_allineata, verdetto.

    NaN-safe: serie vuote / non allineabili / < 24 ore valide / varianza
    nulla di pb o pa / indice non orario / parametri non validi -> errore
    pulito; mai eccezioni. Deterministico.
    """
    colonne_h = ["h (ratio)", "Efficacia (R^2)"]
    colonne_b = ["Ora", "Basis media (€/MWh)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_ore": 0, "h_star": None,
                "correlazione": None, "r2": 0.0, "std_spot": None,
                "std_residua_star": None, "std_residua_naive": None,
                "eff_naive": 0.0, "costo_atteso_spot": None,
                "costo_atteso_star": None, "costo_atteso_naive": None,
                "controvalore_spot": None, "controvalore_star": None,
                "basis_media": None, "basis_std": None, "basis_min": None,
                "basis_max": None, "profilo_basis": [float("nan")] * 24,
                "df_h": pd.DataFrame(columns=colonne_h),
                "df_basis": pd.DataFrame(columns=colonne_b),
                "pa_allineata": pd.Series(dtype=float),
                "pb_allineata": pd.Series(dtype=float),
                "verdetto": ""}

    def _num(x):
        if isinstance(x, bool):
            return None
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return v if np.isfinite(v) else None

    fwd = _num(forward_hub)
    w = _num(mw)
    if fwd is None:
        return _err("Prezzo forward hub non valido: serve un numero finito (€/MWh).")
    if w is None or w <= 0:
        return _err("MW da coprire non validi: serve un numero > 0.")
    try:
        a = pd.to_numeric(pd.Series(pa), errors="coerce")
        b = pd.to_numeric(pd.Series(pb), errors="coerce")
        df = pd.concat({"a": a, "b": b}, axis=1).dropna()
    except Exception:
        return _err("Serie di prezzo non valide.")
    if len(df) < 24:
        return _err("Ore valide insufficienti dopo l'allineamento: %d trovate, "
                    "ne servono almeno 24." % len(df))
    x = df["a"].to_numpy(dtype=float)
    y = df["b"].to_numpy(dtype=float)
    var_x = float(np.var(x, ddof=1))
    var_y = float(np.var(y, ddof=1))
    if not np.isfinite(var_x) or not np.isfinite(var_y):
        return _err("Serie di prezzo non valide (valori non finiti).")
    if var_y <= 0:
        return _err("Serie hub senza varianza: regressione impossibile, "
                    "scegli un altro hub.")
    if var_x <= 0:
        return _err("Serie Swissix senza varianza: niente da coprire.")
    cov = float(np.cov(x, y, ddof=1)[0, 1])
    h_star = cov / var_y
    if not np.isfinite(h_star):
        return _err("Ratio di copertura non calcolabile.")
    var_resid = float(np.var(x - h_star * y, ddof=1))
    r2 = max(0.0, min(1.0, 1.0 - var_resid / var_x))
    corr = float(np.corrcoef(x, y)[0, 1])
    corr = max(-1.0, min(1.0, corr)) if np.isfinite(corr) else 0.0
    std_spot = float(np.sqrt(var_x))
    std_star = float(np.sqrt(max(var_resid, 0.0)))
    # hedge naive 1:1, per confronto
    var_n = float(np.var(x - y, ddof=1))
    eff_n = max(0.0, min(1.0, 1.0 - var_n / var_x))
    std_n = float(np.sqrt(max(var_n, 0.0)))
    # costi attesi (€/MWh): E[pa] - h * (E[pb] - F)
    mx, my = float(np.mean(x)), float(np.mean(y))
    c_spot = mx
    c_star = mx - h_star * (my - fwd)
    c_naive = mx - (my - fwd)
    n = len(df)
    # basis b = pa - pb: il rischio non copribile
    basis = x - y
    b_mean = float(np.mean(basis))
    b_std = float(np.std(basis, ddof=1))
    b_min = float(np.min(basis))
    b_max = float(np.max(basis))
    try:
        ore_idx = df.index.hour.to_numpy()
    except Exception:
        return _err("Indice non orario: impossibile calcolare il profilo della basis.")
    prof = [float(np.mean(basis[ore_idx == h])) if (ore_idx == h).any()
            else float("nan") for h in range(24)]
    # curva efficacia vs h (per il grafico)
    h_max = max(2.0 * abs(h_star), 2.0)
    hs = np.linspace(0.0, h_max, 81)
    effs = [max(0.0, min(1.0, 1.0 - float(np.var(x - h * y, ddof=1)) / var_x))
            for h in hs]
    df_h = pd.DataFrame({"h (ratio)": np.round(hs, 4),
                         "Efficacia (R^2)": np.round(effs, 4)})
    df_b = pd.DataFrame({"Ora": list(range(24)),
                         "Basis media (€/MWh)": [round(v, 2) if np.isfinite(v)
                                                 else None for v in prof]})
    if r2 >= 0.80:
        giudizio = ("copertura proxy MOLTO EFFICACE: l'hub replica bene lo "
                    "Swissix, il basis risk residuo e' contenuto.")
    elif r2 >= 0.50:
        giudizio = ("copertura proxy EFFICACE, ma resta un basis risk "
                    "significativo: valuta prodotti hub piu' granulari "
                    "(peak/off-peak) o un ratio dinamico.")
    else:
        giudizio = ("copertura proxy POCO EFFICACE: l'hub non replica lo "
                    "Swissix, il basis risk domina -- cosi' com'e' il "
                    "cross-hedge serve a poco.")
    if abs(h_star - 1.0) > 0.15:
        nota_h = ("Il ratio ottimale si discosta parecchio dall'1:1 naive: "
                  "coprire 'un tanto al chilo' lascia sul tavolo rischio "
                  "evitabile.")
    else:
        nota_h = "Il ratio ottimale e' vicino a 1: la copertura naive 1:1 e' quasi ottimale."
    verdetto = ("h* = %.3f (%.1f MW di hub ogni 100 MW di consumo): R^2 = %.1f%%, "
                "la deviazione std del costo orario scende da %.1f a %.1f €/MWh "
                "(naive 1:1: %.1f €/MWh, R^2 = %.1f%%). %s %s" % (
                    h_star, h_star * 100.0, 100.0 * r2, std_spot, std_star,
                    std_n, 100.0 * eff_n, giudizio, nota_h))
    return {"errore": None, "valido": True, "n_ore": int(n),
            "h_star": float(h_star), "correlazione": corr, "r2": float(r2),
            "std_spot": std_spot, "std_residua_star": std_star,
            "std_residua_naive": std_n, "eff_naive": float(eff_n),
            "costo_atteso_spot": float(c_spot),
            "costo_atteso_star": float(c_star),
            "costo_atteso_naive": float(c_naive),
            "controvalore_spot": float(c_spot * w * n),
            "controvalore_star": float(c_star * w * n),
            "basis_media": b_mean, "basis_std": b_std,
            "basis_min": b_min, "basis_max": b_max,
            "profilo_basis": prof, "df_h": df_h, "df_basis": df_b,
            "pa_allineata": df["a"], "pb_allineata": df["b"],
            "verdetto": verdetto}



def calcola_business_case_accumulo(prezzi, potenza_mw=10.0, energia_mwh=20.0,
                                   capex_eur_kwh=350.0, opex_eur_kw_anno=10.0,
                                   efficienza_pct=85.0, cicli_giorno=1.0,
                                   degrado_pct=2.0, ricavi_fissi_eur_anno=0.0,
                                   tasso_pct=6.0, vita_anni=15, n_punti_sens=11):
    """Business case di un accumulo elettrochimico merchant (arbitraggio + ricavi fissi).

    Domanda operativa: "Conviene investire in una batteria che compra nelle ore
    a basso prezzo e rivende nelle ore di picco?" -- stima il ricavo annuo da
    arbitraggio dai dati storici (spread giornaliero max-min con rendimento di
    ciclo), lo proietta sulla vita utile con degrado della capacita', aggiunge
    eventuali ricavi fissi (es. riserva) e sottrae opex: ne escono NPV, IRR e
    payback.

    Differenza dalle altre tab: tab6 "Arbitraggio Batteria" ottimizza il
    DISPATCH orario (quando caricare/scaricare); tab77 "Sizing batteria"
    dimensiona potenza/energia sul profilo; tab138 "LCOS" calcola il costo
    livellato per MWh scaricato; tab184 "Revenue stacking" somma i flussi di
    ricavo. Qui si risponde alla domanda d'INVESTIMENTO: con capex, opex,
    degrado e tasso di attualizzazione, il progetto crea o distrugge valore?

    Parametri:
      prezzi: serie oraria dei prezzi spot (€/MWh), indice datetime;
      potenza_mw: potenza nominale (MW); energia_mwh: capacita' utile (MWh);
      capex_eur_kwh: costo d'investimento all-in (€/kWh installato);
      opex_eur_kw_anno: O&M annuo (€/kW/anno);
      efficienza_pct: rendimento di ciclo carica+scarica (%);
      cicli_giorno: cicli equivalenti completi al giorno (<=4);
      degrado_pct: perdita annua di capacita' (%), scala i ricavi;
      ricavi_fissi_eur_anno: altri ricavi annui certi (es. riserva);
      tasso_pct: tasso di attualizzazione (%); vita_anni: vita utile;
      n_punti_sens: punti della sensibilita' NPV vs capex.

    Ritorna dict con: valido, errore, n_giorni, capex_eur, opex_annuo_eur,
    ricavo_arb_anno_eur, npv_eur, irr_pct (None se non esiste),
    payback_anni (None se mai), flussi (lista annua netta),
    df_sens (Capex, NPV), df_flussi (tabella anni), verdetto.

    NaN-safe: serie vuota / < 24 ore / nessun giorno con >= 12 ore valide /
    parametri non validi (incl. bool, inf, fuori range) -> errore pulito;
    mai eccezioni. Deterministico.
    """
    colonne_s = ["Capex (€/kWh)", "NPV (€ mln)"]
    colonne_f = ["Anno", "Ricavo arbitraggio (€)", "Ricavi fissi (€)",
                 "Opex (€)", "Flusso netto (€)", "Cumulato (€)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_giorni": 0,
                "capex_eur": None, "opex_annuo_eur": None,
                "ricavo_arb_anno_eur": None, "npv_eur": None, "irr_pct": None,
                "payback_anni": None, "flussi": [],
                "df_sens": pd.DataFrame(columns=colonne_s),
                "df_flussi": pd.DataFrame(columns=colonne_f),
                "verdetto": ""}

    def _num(x):
        if isinstance(x, bool):
            return None
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return v if np.isfinite(v) else None

    p_mw = _num(potenza_mw)
    e_mwh = _num(energia_mwh)
    cx = _num(capex_eur_kwh)
    ox = _num(opex_eur_kw_anno)
    eff = _num(efficienza_pct)
    cic = _num(cicli_giorno)
    deg = _num(degrado_pct)
    rf = _num(ricavi_fissi_eur_anno)
    tasso = _num(tasso_pct)
    vita = _num(vita_anni)
    npt = _num(n_punti_sens)

    if p_mw is None or p_mw <= 0:
        return _err("Potenza non valida: serve un numero > 0 (MW).")
    if e_mwh is None or e_mwh <= 0:
        return _err("Energia non valida: serve un numero > 0 (MWh).")
    if cx is None or cx < 0:
        return _err("Capex non valido: serve un numero >= 0 (€/kWh).")
    if ox is None or ox < 0:
        return _err("Opex non valido: serve un numero >= 0 (€/kW/anno).")
    if eff is None or eff <= 0 or eff > 100:
        return _err("Efficienza non valida: serve un numero in (0, 100] (%).")
    if cic is None or cic <= 0 or cic > 4:
        return _err("Cicli/giorno non validi: serve un numero in (0, 4].")
    if deg is None or deg < 0 or deg > 50:
        return _err("Degrado non valido: serve un numero in [0, 50] (%/anno).")
    if rf is None or rf < 0:
        return _err("Ricavi fissi non validi: serve un numero >= 0 (€/anno).")
    if tasso is None or tasso < 0 or tasso > 50:
        return _err("Tasso non valido: serve un numero in [0, 50] (%).")
    if vita is None or int(vita) != vita or vita < 1 or vita > 40:
        return _err("Vita utile non valida: serve un intero in [1, 40] (anni).")
    if npt is None or int(npt) != npt or npt < 3 or npt > 101:
        return _err("Punti sensibilita' non validi: serve un intero in [3, 101].")
    vita = int(vita)
    npt = int(npt)

    try:
        s = pd.to_numeric(pd.Series(prezzi), errors="coerce").dropna()
    except Exception:
        return _err("Serie prezzi non valida.")
    if len(s) < 24:
        return _err("Servono almeno 24 ore di prezzi per stimare l'arbitraggio.")
    try:
        giorni = pd.to_datetime(s.index).normalize()
    except Exception:
        giorni = pd.Series([i // 24 for i in range(len(s))], index=s.index)
    df_d = pd.DataFrame({"g": np.asarray(giorni), "p": s.to_numpy(dtype=float)})
    agg = df_d.groupby("g")["p"].agg(["min", "max", "count"])
    agg = agg[agg["count"] >= 12]
    n_g = len(agg)
    if n_g < 1:
        return _err("Nessun giorno con almeno 12 ore di prezzi valide.")

    eta = eff / 100.0
    spread = agg["max"].to_numpy(dtype=float) * eta - agg["min"].to_numpy(dtype=float)
    rev_giorno = np.maximum(0.0, e_mwh * spread) * cic
    ric_arb_anno = float(np.sum(rev_giorno)) * (365.0 / n_g)

    capex = e_mwh * 1000.0 * cx
    opex_a = p_mw * 1000.0 * ox
    d = deg / 100.0
    rr = tasso / 100.0
    flussi = [ric_arb_anno * ((1.0 - d) ** (t - 1)) + rf - opex_a
              for t in range(1, vita + 1)]

    def _npv(rate, capex_v):
        return -capex_v + sum(cf / ((1.0 + rate) ** t)
                              for t, cf in enumerate(flussi, start=1))

    npv = _npv(rr, capex)

    irr = None
    if any(cf > 0 for cf in flussi):
        lo, hi = -0.9999, 10.0
        f_lo, f_hi = _npv(lo, capex), _npv(hi, capex)
        if f_lo * f_hi < 0:
            for _ in range(200):
                mid = 0.5 * (lo + hi)
                if _npv(lo, capex) * _npv(mid, capex) <= 0:
                    hi = mid
                else:
                    lo = mid
            irr = 0.5 * (lo + hi) * 100.0
        elif f_hi > 0:
            irr = 1000.0

    payback = None
    cum = -capex
    for t, cf in enumerate(flussi, start=1):
        prev = cum
        cum += cf
        if cum >= 0:
            payback = float(t - 1) + (-prev) / cf if cf > 0 else float(t)
            break

    base_cx = 0.5 * cx if cx > 0 else 0.0
    top_cx = 2.0 * cx if cx > 0 else 700.0
    xs = np.linspace(base_cx, top_cx, npt)
    npvs = [_npv(rr, x * e_mwh * 1000.0) / 1e6 for x in xs]
    df_s = pd.DataFrame({"Capex (€/kWh)": np.round(xs, 2),
                         "NPV (€ mln)": np.round(npvs, 3)})

    righe = []
    cum2 = -capex
    for t, cf in enumerate(flussi, start=1):
        arb_t = ric_arb_anno * ((1.0 - d) ** (t - 1))
        cum2 += cf
        righe.append({"Anno": t,
                      "Ricavo arbitraggio (€)": round(arb_t, 0),
                      "Ricavi fissi (€)": round(rf, 0),
                      "Opex (€)": round(opex_a, 0),
                      "Flusso netto (€)": round(cf, 0),
                      "Cumulato (€)": round(cum2, 0)})
    df_f = pd.DataFrame(righe, columns=colonne_f)

    if irr is None or npv < 0:
        giudizio = ("NON CONVENIENTE: a questi prezzi e costi il progetto "
                    "distrugge valore (NPV negativo o flussi mai positivi). "
                    "Servono spread piu' ampi, capex piu' basso o ricavi "
                    "fissi da servizi di rete.")
    elif tasso > 0 and irr >= 2.0 * tasso:
        giudizio = ("MOLTO CONVENIENTE: IRR pari ad almeno il doppio del tasso "
                    "di attualizzazione, con margine contro degrado e cali di "
                    "spread futuri.")
    elif irr >= tasso:
        giudizio = ("CONVENIENTE: IRR sopra il tasso di attualizzazione, ma "
                    "senza grande margine -- verifica la sensibilita' al capex "
                    "e allo spread storico.")
    else:
        giudizio = ("MARGINALE: NPV positivo ma IRR sotto il tasso -- il "
                    "progetto si ripaga solo se il costo del capitale e' "
                    "davvero piu' basso.")
    verdetto = ("Capex %.1f M€, ricavo arbitraggio %.0f k€/anno (da %d giorni "
                "di spread storico), NPV %.2f M€, IRR %s, payback %s. %s" % (
                    capex / 1e6, ric_arb_anno / 1e3, n_g, npv / 1e6,
                    ("%.1f%%" % irr) if irr is not None else "n.d.",
                    ("%.1f anni" % payback) if payback is not None else "mai",
                    giudizio))
    return {"errore": None, "valido": True, "n_giorni": int(n_g),
            "capex_eur": float(capex), "opex_annuo_eur": float(opex_a),
            "ricavo_arb_anno_eur": float(ric_arb_anno),
            "npv_eur": float(npv),
            "irr_pct": float(irr) if irr is not None else None,
            "payback_anni": float(payback) if payback is not None else None,
            "flussi": [float(c) for c in flussi],
            "df_sens": df_s, "df_flussi": df_f, "verdetto": verdetto}



# ==========================================
def calcola_kpi_performance(serie_pnl, periodi_anno=365, tasso_free_pct=0.0):
    """KPI di performance risk-adjusted di una serie P&L per periodo.

    Domanda operativa: "il mio book rende abbastanza per il rischio che
    corro?" -- Sharpe, Sortino, Calmar, win rate e profit factor sono lo
    standard dei factsheet di trading e dei report di risk: qui applicati
    al P&L giornaliero della posizione aperta sullo spot (stessa serie
    della tab130 "Drawdown MtM", che ne analizza solo il drawdown, e
    coerente con la tab9 "MtM hedging").

    Differenza dalle altre tab: tab27 "VaR costo (MC)" e tab56 "Expected
    Shortfall" misurano il rischio del COSTO di fornitura; tab130 misura
    solo il drawdown del MtM; tab129 attribuisce il P&L alle sue cause.
    Qui si risponde alla domanda di PERFORMANCE: rendimento contro
    rischio, con i ratio che un risk manager chiede prima di aumentare
    la size.

    Parametri:
      serie_pnl: P&L per periodo in € (es. giornaliero), indice datetime;
      periodi_anno: periodi in un anno per l'annualizzazione
        (365 = mercato elettrico 7/7, 252 = convenzione trading classica);
      tasso_free_pct: tasso risk-free annuo (%) sottratto dal rendimento
        nei ratio di Sharpe e Sortino.

    Ritorna dict con: valido, errore, n_periodi, pnl_totale_eur,
    rend_medio_periodo_eur, rend_annuo_eur, vol_annua_eur, sharpe (None se
    volatilita' nulla), sortino (None se mai sotto il risk-free),
    max_drawdown_eur (<= 0), calmar (None se drawdown nullo),
    win_rate_pct, profit_factor (None se senza perdite o senza profitti),
    best_periodo_eur, worst_periodo_eur (+ date se indice datetime),
    equity (Series cumulata), drawdown (Series <= 0), df_mensile (pivot
    anni x mesi, vuoto se senza date), verdetto.

    NaN-safe: serie vuota / < 2 punti / non numerica / inf / parametri non
    validi (incl. bool) -> errore pulito; mai eccezioni. Deterministico.
    """
    colonne_m = ["Anno"] + ["M%02d" % i for i in range(1, 13)]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_periodi": 0,
                "pnl_totale_eur": None, "rend_medio_periodo_eur": None,
                "rend_annuo_eur": None, "vol_annua_eur": None,
                "sharpe": None, "sortino": None, "max_drawdown_eur": None,
                "calmar": None, "win_rate_pct": None, "profit_factor": None,
                "best_periodo_eur": None, "best_data": None,
                "worst_periodo_eur": None, "worst_data": None,
                "equity": pd.Series(dtype=float),
                "drawdown": pd.Series(dtype=float),
                "df_mensile": pd.DataFrame(columns=colonne_m),
                "verdetto": ""}

    def _num(x):
        if isinstance(x, bool):
            return None
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return v if np.isfinite(v) else None

    npa = _num(periodi_anno)
    trf = _num(tasso_free_pct)
    if npa is None or int(npa) != npa or npa < 12 or npa > 366:
        return _err("Periodi/anno non validi: serve un intero in [12, 366] "
                    "(365 energia, 252 trading).")
    if trf is None or trf < 0 or trf > 50:
        return _err("Tasso risk-free non valido: serve un numero in [0, 50] (%).")
    npa = int(npa)

    try:
        pnl = pd.Series(serie_pnl)
        pnl = pd.to_numeric(pnl, errors="coerce").dropna()
        if len(pnl) == 0:
            return _err("Serie P&L vuota o non numerica.")
        if not bool(np.isfinite(pnl.to_numpy(dtype=float)).all()):
            return _err("Serie P&L con valori non finiti.")
        if len(pnl) < 2:
            return _err("Servono almeno 2 periodi di P&L.")
        pnl = pnl.astype(float)
        n = len(pnl)

        rf_p = trf / 100.0 / npa
        exc = pnl - rf_p
        media_exc = float(exc.mean())
        std_exc = float(exc.std(ddof=1))
        sharpe = (media_exc / std_exc * np.sqrt(npa)) if std_exc > 0 else None

        downside = exc.clip(upper=0.0)
        dd_dev = float(np.sqrt((downside ** 2).mean()))
        sortino = (media_exc / dd_dev * np.sqrt(npa)) if dd_dev > 0 else None

        equity = pnl.cumsum()
        runmax = equity.cummax()
        dd = equity - runmax
        max_dd = float(dd.min())

        rend_annuo = float(pnl.mean() * npa)
        vol_annua = float(pnl.std(ddof=1) * np.sqrt(npa))
        calmar = (rend_annuo / abs(max_dd)) if max_dd < 0 else None

        win_rate = float((pnl > 0).mean() * 100.0)
        gp = float(pnl[pnl > 0].sum())
        gl = float(-pnl[pnl < 0].sum())
        profit_factor = (gp / gl) if gl > 0 and gp > 0 else None

        best = float(pnl.max())
        worst = float(pnl.min())
        best_data = None
        worst_data = None
        df_m = pd.DataFrame(columns=colonne_m)
        if isinstance(pnl.index, pd.DatetimeIndex) and len(pnl.index) > 0:
            arr = pnl.to_numpy(dtype=float)
            best_data = pnl.index[int(np.argmax(arr))]
            worst_data = pnl.index[int(np.argmin(arr))]
            tmp = pd.DataFrame({"pnl": arr}, index=pnl.index)
            mens = tmp["pnl"].groupby([tmp.index.year,
                                       tmp.index.month]).sum()
            if len(mens):
                piv = mens.unstack(fill_value=0.0)
                piv = piv.reindex(columns=range(1, 13), fill_value=0.0)
                piv.columns = ["M%02d" % i for i in piv.columns]
                piv.index.name = "Anno"
                df_m = piv.reset_index()

        def _f(x, fmt="%.2f"):
            return (fmt % x) if x is not None else "n.d."

        if sharpe is None:
            tag = "N.D."
            giudizio = ("volatilita' nulla: il P&L e' costante periodo su "
                        "periodo, i ratio risk-adjusted non sono definibili.")
        elif sharpe >= 2.0:
            tag = "ECCELLENTE"
            giudizio = ("profilo da aumentare: rendimento ampiamente sopra "
                        "il rischio corso, anche al netto del risk-free.")
        elif sharpe >= 1.0:
            tag = "BUONO"
            giudizio = ("profilo solido: il rendimento ripaga il rischio; "
                        "verifica la tenuta su finestre diverse.")
        elif sharpe >= 0.5:
            tag = "DISCRETO"
            giudizio = ("profilo accettabile ma senza margine: basta poco "
                        "per scivolare in territorio debole.")
        elif sharpe >= 0.0:
            tag = "DEBOLE"
            giudizio = ("rendimento positivo ma non commisurato al rischio: "
                        "riduci la size o migliora il timing.")
        else:
            tag = "NEGATIVO"
            giudizio = ("il book distrugge valore anche prima dei costi: "
                        "fermati e rivedi la strategia.")
        verdetto = ("Su %d periodi: P&L totale %s €, Sharpe %s, Sortino %s, "
                    "Calmar %s, win rate %s%%, profit factor %s, max drawdown "
                    "%s €. %s: %s" % (
                        n, _f(float(pnl.sum()), "%.0f"), _f(sharpe),
                        _f(sortino), _f(calmar), _f(win_rate, "%.1f"),
                        _f(profit_factor), _f(max_dd, "%.0f"), tag, giudizio))
        return {"errore": None, "valido": True, "n_periodi": int(n),
                "pnl_totale_eur": float(pnl.sum()),
                "rend_medio_periodo_eur": float(pnl.mean()),
                "rend_annuo_eur": rend_annuo, "vol_annua_eur": vol_annua,
                "sharpe": sharpe, "sortino": sortino,
                "max_drawdown_eur": max_dd, "calmar": calmar,
                "win_rate_pct": win_rate, "profit_factor": profit_factor,
                "best_periodo_eur": best, "best_data": best_data,
                "worst_periodo_eur": worst, "worst_data": worst_data,
                "equity": equity, "drawdown": dd, "df_mensile": df_m,
                "verdetto": verdetto}
    except Exception as e:  # pragma: no cover - guardia totale
        return _err("Errore interno: %s" % e)


"""Sviluppo standalone helper tab198 - test logica prima dell'inserimento."""
import numpy as np
import pandas as pd


def genera_demo_var_portafoglio(n_giorni=365, seed=198):
    if isinstance(n_giorni, bool) or not isinstance(n_giorni, int):
        n_giorni = 365
    n_giorni = max(60, min(2000, n_giorni))
    rng = np.random.default_rng(seed)
    corr = np.array([[1.0, 0.7, 0.4],
                     [0.7, 1.0, 0.3],
                     [0.4, 0.3, 1.0]])
    z = rng.standard_normal((n_giorni, 3)) @ np.linalg.cholesky(corr).T
    vol = np.array([0.06, 0.045, 0.03])
    base = np.array([85.0, 40.0, 70.0])
    prezzi = base * np.exp(np.cumsum(z * vol, axis=0))
    idx = pd.date_range(end=pd.Timestamp.today().normalize(),
                        periods=n_giorni, freq="D")
    return pd.DataFrame(prezzi, index=idx,
                        columns=["Power (€/MWh)", "Gas (€/MWh)", "CO2 (€/t)"])


def calcola_var_portafoglio(df_prezzi, posizioni, moltiplicatori=None,
                            confidenza=0.99, orizzonte_giorni=1):
    def _err(msg):
        return {"errore": msg, "valido": False}

    def _fx(x, fmt="%.2f"):
        try:
            return fmt % x if x is not None and np.isfinite(x) else "n.d."
        except Exception:
            return "n.d."
    try:
        if not isinstance(df_prezzi, pd.DataFrame) or df_prezzi.empty:
            return _err("Servono prezzi giornalieri: DataFrame non vuoto.")
        if not isinstance(posizioni, dict) or not posizioni:
            return _err("Servono le posizioni: dict {commodity: quantita'}.")
        if isinstance(confidenza, bool) or not isinstance(confidenza, (int, float)) \
                or not np.isfinite(confidenza) or not 0.90 <= confidenza <= 0.9999:
            return _err("Confidenza non valida: usare un valore tra 0.90 e 0.9999.")
        if isinstance(orizzonte_giorni, bool) or not isinstance(orizzonte_giorni, int) \
                or not 1 <= orizzonte_giorni <= 30:
            return _err("Orizzonte non valido: intero tra 1 e 30 giorni.")
        molt = moltiplicatori if isinstance(moltiplicatori, dict) else {}
        cols, pesi = [], []
        for comm, qty in posizioni.items():
            if isinstance(qty, bool) or not isinstance(qty, (int, float)) \
                    or not np.isfinite(qty):
                return _err("Quantita' non valida per '%s'." % comm)
            if qty == 0:
                continue
            if comm not in df_prezzi.columns:
                return _err("Commodity '%s' non presente nei prezzi." % comm)
            m = molt.get(comm, 1.0)
            if isinstance(m, bool) or not isinstance(m, (int, float)) \
                    or not np.isfinite(m) or m <= 0:
                return _err("Moltiplicatore non valido per '%s'." % comm)
            cols.append(comm)
            pesi.append(float(qty) * float(m))
        if not cols:
            return _err("Nessuna posizione diversa da zero.")
        px = df_prezzi[cols].apply(pd.to_numeric, errors="coerce").dropna()
        if len(px) < 31:
            return _err("Servono almeno 31 giorni di prezzi validi (allineati).")
        d = px.diff().dropna()
        if len(d) < 30:
            return _err("Serie storica troppo corta dopo le differenze.")
        w = np.array(pesi)
        pnl = pd.Series(d.values @ w, index=d.index, name="P&L simulato (€)")
        n = len(pnl)
        soglia = float(np.quantile(pnl.values, 1.0 - float(confidenza)))
        var_1d = max(0.0, -soglia)
        coda = pnl.values[pnl.values <= soglia]
        es_1d = max(0.0, float(-coda.mean())) if len(coda) else var_1d
        scala = float(np.sqrt(orizzonte_giorni))
        var_h, es_h = var_1d * scala, es_1d * scala
        last = px.iloc[-1].values
        nozionale = float(np.sum(np.abs(w) * last))
        var_pct = (var_h / nozionale) if nozionale > 0 else 0.0
        corr = d.corr()
        cov = d.cov().values
        denom = float(w @ cov @ w)
        if denom > 0:
            comp_1d = var_1d * (w * (cov @ w)) / denom
        else:
            comp_1d = np.zeros_like(w)
        quota = np.zeros_like(comp_1d)
        if var_h > 0:
            quota = comp_1d * scala / var_h * 100.0
        df_comp = pd.DataFrame({
            "Commodity": cols,
            "Posizione": [posizioni[c] for c in cols],
            "VaR componente (€)": comp_1d * scala,
            "Quota VaR (%)": quota,
        })
        stand = []
        for i, c in enumerate(cols):
            pc = d[c].values * w[i]
            sc = float(np.quantile(pc, 1.0 - float(confidenza)))
            stand.append(max(0.0, -sc) * scala)
        df_comp["VaR standalone (€)"] = stand
        diversif = float(np.sum(stand) - var_h)
        pegg = pnl.nsmallest(5)
        df_peg = pd.DataFrame({"Data": pegg.index, "P&L simulato (€)": pegg.values})
        if var_h == 0:
            tag = "NULLO"
            giudizio = ("nessuna perdita simulata alla confidenza scelta: "
                        "book coperto o prezzi fermi nel campione.")
        elif var_pct >= 0.05:
            tag = "ELEVATO"
            giudizio = ("il VaR supera il 5% del nozionale: riduci la size o "
                        "copri la componente dominante.")
        elif var_pct >= 0.02:
            tag = "MODERATO"
            giudizio = ("rischio sotto controllo ma non trascurabile: "
                        "monitora la componente dominante.")
        else:
            tag = "CONTENUTO"
            giudizio = ("VaR sotto il 2% del nozionale: il book regge bene "
                        "la coda storica.")
        verdetto = ("Su %d giorni, confidenza %s%%, orizzonte %d g.: VaR %s €, "
                    "ES %s €, nozionale %s € (VaR %s%%). Diversificazione: %s €. "
                    "%s: %s" % (
                        n, _fx(float(confidenza) * 100.0), orizzonte_giorni,
                        _fx(var_h, "%.0f"), _fx(es_h, "%.0f"),
                        _fx(nozionale, "%.0f"), _fx(var_pct * 100.0, "%.2f"),
                        _fx(diversif, "%.0f"), tag, giudizio))
        return {"errore": None, "valido": True, "n_giorni": int(n),
                "confidenza": float(confidenza),
                "orizzonte_giorni": int(orizzonte_giorni),
                "var_eur": float(var_h), "es_eur": float(es_h),
                "var_1d_eur": float(var_1d), "es_1d_eur": float(es_1d),
                "nozionale_eur": float(nozionale),
                "var_pct_nozionale": float(var_pct),
                "correlazione": corr, "componenti": df_comp,
                "diversificazione_eur": float(diversif),
                "df_peggiori": df_peg, "serie_pnl": pnl,
                "verdetto": verdetto}
    except Exception as e:  # pragma: no cover - guardia totale
        return _err("Errore interno: %s" % e)


"""Sviluppo standalone helper tab199 - test logica prima dell'inserimento."""
def genera_demo_basis(n_giorni=365, seed=199):
    """Serie giornaliere sintetiche deterministiche: hub (GBM con stagionalita')
    + basis mean-reverting (OU) con spike occasionali; locale = hub + basis."""
    if isinstance(n_giorni, bool) or not isinstance(n_giorni, int):
        n_giorni = 365
    n_giorni = max(60, min(2000, n_giorni))
    rng = np.random.default_rng(seed)
    # Hub: GBM giornaliera intorno a 85 EUR/MWh + stagionalita' annua
    t = np.arange(n_giorni)
    shock = rng.standard_normal(n_giorni) * 0.045
    hub = 85.0 * np.exp(np.cumsum(shock)
                        + 0.15 * np.sin(2 * np.pi * t / 365.0))
    hub = np.clip(hub, 5.0, 400.0)
    # Basis: OU intorno a +4 EUR/MWh + spike occasionali (+/-)
    mu, kappa, sigma = 4.0, 0.10, 1.1
    basis = np.empty(n_giorni)
    b = mu
    for i in range(n_giorni):
        b = b + kappa * (mu - b) + sigma * rng.standard_normal()
        if rng.random() < 0.03:  # ~3% giorni: spike di congestione
            b = b + rng.choice([-1.0, 1.0]) * rng.uniform(8.0, 22.0)
        basis[i] = b
    locale = hub + basis
    idx = pd.date_range(end=pd.Timestamp.today().normalize(),
                        periods=n_giorni, freq="D")
    return pd.DataFrame({"Hub (€/MWh)": hub, "Locale (€/MWh)": locale},
                        index=idx)


def calcola_basis_risk(df_prezzi, col_hub, col_locale, confidenza=0.99,
                       soglia_spike=3.0, volume_mwh_giorno=None):
    """Analisi del rischio basis (locale - hub).

    Ritorna dict con 'errore' (None se ok) e statistiche; mai eccezioni.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        if not isinstance(df_prezzi, pd.DataFrame) or df_prezzi.empty:
            return _err("Dati prezzi mancanti o vuoti.")
        if col_hub not in df_prezzi.columns:
            return _err("Colonna hub '%s' non trovata." % col_hub)
        if col_locale not in df_prezzi.columns:
            return _err("Colonna locale '%s' non trovata." % col_locale)
        if col_hub == col_locale:
            return _err("Hub e locale devono essere due colonne diverse.")
        if isinstance(confidenza, bool) or not isinstance(
                confidenza, (int, float)) or not (0.90 < confidenza <= 0.9999):
            return _err("Confidenza fuori intervallo (0.90, 0.9999].")
        if isinstance(soglia_spike, bool) or not isinstance(
                soglia_spike, (int, float)) or not (1.0 <= soglia_spike <= 10.0):
            return _err("Soglia spike fuori intervallo [1, 10].")
        vol = None
        if volume_mwh_giorno is not None:
            if (isinstance(volume_mwh_giorno, bool)
                    or not isinstance(volume_mwh_giorno, (int, float))
                    or not np.isfinite(volume_mwh_giorno)
                    or volume_mwh_giorno < 0):
                return _err("Volume esposto non valido (>= 0).")
            vol = float(volume_mwh_giorno)

        hub = pd.to_numeric(df_prezzi[col_hub], errors="coerce")
        loc = pd.to_numeric(df_prezzi[col_locale], errors="coerce")
        ok = hub.notna() & loc.notna()
        hub, loc = hub[ok], loc[ok]
        n = int(len(hub))
        if n < 31:
            return _err("Servono almeno 31 osservazioni allineate (trovate %d)." % n)

        basis = loc - hub
        b_media = float(basis.mean())
        b_med = float(basis.median())
        b_std = float(basis.std(ddof=1))
        b_min = float(basis.min())
        b_max = float(basis.max())
        b_skew = float(basis.skew())
        b_kurt = float(basis.kurt())
        mean_loc = float(loc.mean())

        # Decomposizione varianza: Var(loc) = Var(hub) + Var(basis) + 2*Cov
        vh = float(hub.var(ddof=1))
        vb = float(basis.var(ddof=1))
        cv = float(hub.cov(basis))
        vtot = vh + vb + 2.0 * cv
        quota_basis = quota_hub = quota_cov = None
        if vtot > 0:
            quota_basis = vb / vtot
            quota_hub = vh / vtot
            quota_cov = 2.0 * cv / vtot

        ratio = abs(b_std / mean_loc) if mean_loc != 0 else None

        # VaR sulla variazione giornaliera del basis (perdita se il basis si
        # muove contro: qui VaR = -quantile delle variazioni, €/MWh)
        db = basis.diff().dropna()
        q = float(db.quantile(1.0 - confidenza))
        var_basis = -q
        coda = db[db <= q]
        es_basis = float(-coda.mean()) if len(coda) else 0.0
        var_eur = var_basis * vol if vol else None
        es_eur = es_basis * vol if vol else None

        # Spike: |basis - media| > soglia * std
        if b_std > 0:
            dev = (basis - b_media).abs()
            m_spike = dev > float(soglia_spike) * b_std
            n_spike = int(m_spike.sum())
            spike_max = float(dev[m_spike].max()) if n_spike else 0.0
            date_spike = basis[m_spike].index
        else:
            n_spike, spike_max = 0, 0.0
            date_spike = basis.iloc[0:0].index

        # Giornate critiche: basis piu' alta (sfavorevole a chi compra locale)
        df_crit = pd.DataFrame({
            "Data": basis.index,
            "Hub (€/MWh)": hub.values,
            "Locale (€/MWh)": loc.values,
            "Basis (€/MWh)": basis.values,
        }).sort_values("Basis (€/MWh)", ascending=False).head(5)
        df_crit["Data"] = pd.to_datetime(df_crit["Data"]).dt.strftime("%Y-%m-%d")

        corr_hb = float(hub.corr(basis)) if b_std > 0 and vh > 0 else 0.0

        if b_std == 0:
            verdetto = "NULLO — basis costante: nessun rischio basis."
        elif ratio is not None and ratio >= 0.10:
            verdetto = ("ELEVATO — la volatilita' del basis supera il 10% del "
                        "prezzo locale: coprire il basis o rinegoziare l'indice.")
        elif ratio is not None and ratio >= 0.04:
            verdetto = ("MODERATO — basis materiale: monitorare congestioni e "
                        "differenziali di zona.")
        else:
            verdetto = "CONTENUTO — il basis e' una frazione piccola del prezzo."

        return {"errore": None, "valido": True, "n_giorni": n,
                "basis_media": b_media, "basis_mediana": b_med,
                "basis_std": b_std, "basis_min": b_min, "basis_max": b_max,
                "basis_skew": b_skew, "basis_kurt": b_kurt,
                "mean_locale": mean_loc,
                "quota_basis_var": quota_basis, "quota_hub_var": quota_hub,
                "quota_cov_var": quota_cov,
                "basis_su_prezzo": ratio,
                "var_basis_mwh": float(var_basis), "es_basis_mwh": float(es_basis),
                "var_eur_giorno": var_eur, "es_eur_giorno": es_eur,
                "n_spike": n_spike, "spike_max_dev": spike_max,
                "date_spike": list(date_spike),
                "corr_hub_basis": corr_hb,
                "serie_basis": basis, "serie_hub": hub, "serie_locale": loc,
                "df_critiche": df_crit, "verdetto": verdetto}
    except Exception as e:  # pragma: no cover - guardia totale
        return {"errore": "Errore interno: %s" % e, "valido": False}

"""Sviluppo standalone helper tab200 - test logica prima dell'inserimento."""
def genera_demo_rolling_risk(n_giorni=365, seed=200):
    """Costo giornaliero sintetico deterministico (€/giorno): GBM con
    stagionalita' annua, sconto weekend (-7%), spike di stress ~2% e shift
    di regime (+15%) sull'ultimo quarto della serie."""
    if isinstance(n_giorni, bool) or not isinstance(n_giorni, int):
        n_giorni = 365
    n_giorni = max(60, min(2000, n_giorni))
    rng = np.random.default_rng(seed)
    t = np.arange(n_giorni)
    costo = 900.0 * np.exp(np.cumsum(rng.standard_normal(n_giorni) * 0.02)
                           + 0.18 * np.sin(2 * np.pi * t / 365.0))
    costo = costo * np.where(t % 7 >= 5, 0.93, 1.0)
    spike = rng.random(n_giorni) < 0.02
    costo = costo + spike * rng.uniform(150.0, 450.0, n_giorni)
    costo[int(n_giorni * 0.75):] *= 1.15
    costo = np.clip(costo, 50.0, 5000.0)
    idx = pd.date_range(end=pd.Timestamp.today().normalize(),
                        periods=n_giorni, freq="D")
    return pd.Series(costo, index=idx, name="Costo (€/giorno)")


def calcola_rolling_var(serie_costi, finestra=90, confidenza=0.95,
                        soglia_eur_giorno=None):
    """VaR/ES storici rolling sul costo giornaliero.

    Per ogni finestra di `finestra` giorni calcola il quantile `confidenza`
    (VaR = costo giornaliero superato con prob. 1-confidenza) e l'ES (media
    della coda). Ritorna dict con 'errore' (None se ok); mai eccezioni.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        if not isinstance(serie_costi, pd.Series) or serie_costi.empty:
            return _err("Serie costi mancante o vuota.")
        if isinstance(finestra, bool) or not isinstance(
                finestra, (int, np.integer)):
            return _err("Finestra non valida.")
        finestra = int(finestra)
        if not (30 <= finestra <= 240):
            return _err("Finestra fuori intervallo [30, 240] giorni.")
        if isinstance(confidenza, bool) or not isinstance(
                confidenza, (int, float)) or not (0.90 < confidenza <= 0.9999):
            return _err("Confidenza fuori intervallo (0.90, 0.9999].")
        soglia = None
        if soglia_eur_giorno is not None:
            if (isinstance(soglia_eur_giorno, bool)
                    or not isinstance(soglia_eur_giorno, (int, float))
                    or not np.isfinite(soglia_eur_giorno)
                    or soglia_eur_giorno < 0):
                return _err("Soglia non valida (>= 0 €/giorno).")
            soglia = float(soglia_eur_giorno)

        s = pd.to_numeric(serie_costi, errors="coerce").dropna()
        n = int(len(s))
        if n < max(60, finestra + 1):
            return _err("Servono almeno %d giorni di costo (trovati %d)."
                        % (max(60, finestra + 1), n))

        q = float(confidenza)
        var_s = s.rolling(finestra, min_periods=finestra).quantile(q)

        def _es(w):
            qw = np.quantile(w, q)
            return float(w[w >= qw].mean())

        es_s = s.rolling(finestra, min_periods=finestra).apply(_es, raw=True)
        var_s = var_s.dropna()
        es_s = es_s.dropna()

        var_att = float(var_s.iloc[-1])
        es_att = float(es_s.iloc[-1])
        var_max = float(var_s.max())
        data_max = var_s.idxmax()
        var_min = float(var_s.min())
        var_media = float(var_s.mean())
        var_prima = float(var_s.iloc[0])
        trend = (var_att - var_prima) / var_prima if var_prima > 0 else 0.0

        n_breach = pct_breach = None
        date_breach = []
        if soglia is not None and soglia > 0:
            m_br = s > soglia
            n_breach = int(m_br.sum())
            pct_breach = 100.0 * n_breach / n
            date_breach = list(s[m_br].index)

        df_pegg = pd.DataFrame({"Data": var_s.index, "VaR (€/g)": var_s.values,
                                "ES (€/g)": es_s.reindex(var_s.index).values})
        df_pegg = df_pegg.sort_values("VaR (€/g)", ascending=False).head(5)
        df_pegg["Data"] = pd.to_datetime(
            df_pegg["Data"]).dt.strftime("%Y-%m-%d")

        if soglia is not None and soglia > 0 and var_att > soglia:
            verdetto = ("ATTENZIONE — il VaR rolling attuale supera la soglia "
                        "di budget: il rischio di coda e' oltre il limite.")
        elif pct_breach is not None and pct_breach >= 10.0:
            verdetto = ("SOTTO PRESSIONE — oltre il 10% dei giorni supera la "
                        "soglia: rivedi le coperture o il budget.")
        elif trend >= 0.20:
            verdetto = ("RISCHIO IN CRESCITA — il VaR rolling e' salito del "
                        "%d%% dall'inizio: il mercato sta peggiorando."
                        % int(round(trend * 100)))
        elif trend <= -0.20:
            verdetto = ("IN MIGLIORAMENTO — il VaR rolling e' calato del "
                        "%d%%: il rischio si sta alleggerendo."
                        % int(round(-trend * 100)))
        else:
            verdetto = ("SOTTO CONTROLLO — il rischio di coda resta entro "
                        "i limiti.")

        return {"errore": None, "valido": True, "n_giorni": n,
                "finestra": finestra, "confidenza": float(confidenza),
                "serie_var": var_s, "serie_es": es_s, "serie_costi": s,
                "var_attuale": var_att, "es_attuale": es_att,
                "var_max": var_max, "var_min": var_min,
                "var_media": var_media, "data_var_max": data_max,
                "trend": float(trend),
                "n_breach": n_breach, "pct_breach": pct_breach,
                "date_breach": date_breach,
                "df_peggiori": df_pegg, "verdetto": verdetto}
    except Exception as e:  # pragma: no cover - guardia totale
        return {"errore": "Errore interno: %s" % e, "valido": False}


def genera_demo_carico_anomalie(seed=219, giorni=60):
    """Profilo di carico orario sintetico deterministico con anomalie iniettate.

    Base: 500 kW con profilo giornaliero (picco ~13:00, notte ~380 kW),
    weekend al 55%, rumore gaussiano sigma 12 kW. Anomalie iniettate a
    indici fissi (deterministiche):
      - 6 ore a +900 kW (picco anomalo);
      - 30 ore a 0 kW (contatore guasto / fermo);
      - 12 ore costanti a 412.7 kW (contatore bloccato);
      - 4 ore al 25% del carico (crollo).
    """
    rng = np.random.default_rng(seed)
    idx = pd.date_range("2026-01-05", periods=giorni * 24, freq="h")
    ora = idx.hour.to_numpy()
    dow = idx.dayofweek.to_numpy()
    profilo = 500.0 + 220.0 * np.sin((ora - 7.0) / 24.0 * 2.0 * np.pi)
    profilo = np.where(ora < 6, 380.0, profilo)
    profilo = np.where(dow >= 5, profilo * 0.55, profilo)
    vals = np.maximum(50.0, profilo + rng.normal(0.0, 12.0, len(idx)))
    s = pd.Series(vals, index=idx, name="Carico (kW)")
    s.iloc[500:506] = s.iloc[500:506] + 900.0
    s.iloc[900:930] = 0.0
    s.iloc[1200:1212] = 412.7
    s.iloc[1300:1304] = s.iloc[1300:1304] * 0.25
    return s


def calcola_anomalie_carico(carico, soglia_z=3.5, run_min_ore=3,
                            prezzo_eur_mwh=None):
    """Rileva anomalie nel profilo di carico orario (kW).

    Domanda operativa: "il contatore misura bene e il prelievo e'
    quello atteso?" — picchi, crolli, zeri prolungati o valori congelati
    possono essere guasti del contatore, errori di misura, fermi impianto
    non dichiarati o consumi anomali da indagare prima della fattura.

    Metodo:
      - baseline stagionale = mediana del carico per ora della settimana
        (168 bucket ora x giorno);
      - residui = carico - baseline; sigma robusta = 1.4826 * MAD
        (fallback: deviazione standard se MAD = 0);
      - ore con |z| >= soglia_z raggruppate in episodi contigui;
      - controlli strutturali indipendenti dallo z-score: sequenze di zeri
        (>= 6 ore) e di valori costanti (>= 12 ore) = contatore guasto/
        bloccato anche quando lo z-score non scatta;
      - ogni episodio e' classificato: "🧊 Zero", "🧱 Piatto",
        "⚡ Picco", "📉 Crollo", "↕️ Misto";
      - impatto energetico = somma dei residui dell'episodio (MWh);
        con prezzo_eur_mwh si stima anche il controvalore.

    Verdetto: "🔴 SOSPETTO GUASTO CONTATORE" se un episodio Zero/Piatto
    dura >= 24 ore o l'intera serie e' piatta; "🟠 ANOMALIE RILEVANTI" se
    >= 3 episodi oppure un episodio con |z| >= 6 o |impatto| >= 20 MWh;
    "🟡 ANOMALIE LIEVI" se ci sono episodi minori; "🟢 SOTTO CONTROLLO"
    se nessun episodio.

    NaN-safe: serie vuota / indice non-datetime / valori non numerici /
    < 168 ore valide / parametri fuori range -> errore pulito.
    Deterministico a parita' di input.

    Ritorna dict con 'errore', 'valido', 'verdetto', 'n_episodi',
    'ore_anomale', 'impatto_tot_mwh', 'costo_stimato_eur',
    'df_episodi' (Inizio, Fine, Ore, Tipo, Scostamento MWh, z max,
    Costo stimato €), 'df_serie' (Timestamp, kW, Baseline kW, z-score,
    Episodio).
    """
    colonne_ep = ["Inizio", "Fine", "Ore", "Tipo", "Scostamento (MWh)",
                  "z max", "Costo stimato (€)"]
    colonne_sr = ["Timestamp", "kW", "Baseline (kW)", "z-score", "Episodio"]
    vuoto = {"errore": None, "valido": False, "verdetto": None,
             "n_episodi": 0, "ore_anomale": 0, "impatto_tot_mwh": 0.0,
             "costo_stimato_eur": None,
             "df_episodi": pd.DataFrame(columns=colonne_ep),
             "df_serie": pd.DataFrame(columns=colonne_sr)}

    def _err(msg):
        out = dict(vuoto)
        out["df_episodi"] = pd.DataFrame(columns=colonne_ep)
        out["df_serie"] = pd.DataFrame(columns=colonne_sr)
        out["errore"] = msg
        return out

    try:
        if isinstance(soglia_z, bool):
            raise ValueError
        soglia_z = float(soglia_z)
        if isinstance(run_min_ore, bool):
            raise ValueError
        _run_f = float(run_min_ore)
        if not _run_f.is_integer():
            raise ValueError
        run_min_ore = int(_run_f)
        if prezzo_eur_mwh is not None:
            if isinstance(prezzo_eur_mwh, bool):
                raise ValueError
            prezzo_eur_mwh = float(prezzo_eur_mwh)
    except (TypeError, ValueError):
        return _err("Parametri non validi: soglia_z numerica, "
                    "run_min_ore intero, prezzo numerico o None.")
    if not 0.0 < soglia_z <= 20.0:
        return _err("Parametri non validi: soglia_z in (0, 20].")
    if run_min_ore < 1:
        return _err("Parametri non validi: run_min_ore >= 1.")
    if prezzo_eur_mwh is not None and not np.isfinite(prezzo_eur_mwh):
        return _err("Parametri non validi: prezzo non finito.")
    if prezzo_eur_mwh is not None and prezzo_eur_mwh < 0:
        return _err("Parametri non validi: prezzo >= 0.")

    if carico is None:
        return _err("Serie di carico vuota: niente da analizzare.")
    try:
        s0 = pd.Series(carico)
    except Exception:
        return _err("Input non interpretabile come serie di carico.")
    if not isinstance(s0.index, pd.DatetimeIndex):
        return _err("L'indice della serie deve essere di tipo data/ora.")
    vals = pd.to_numeric(s0.values, errors="coerce")
    if np.isnan(vals).all():
        return _err("Nessun valore numerico nella serie di carico.")
    idx = s0.index.tz_localize(None) if s0.index.tz is not None else s0.index
    s = pd.Series(vals, index=idx).sort_index().dropna()
    if len(s) < 168:
        return _err("Servono almeno 168 ore valide di carico (una "
                    "settimana) per la baseline stagionale.")

    try:
        v = s.to_numpy(dtype=float)
        n = len(v)
        med = float(np.median(v))
        # --- controlli strutturali: serie intera piatta o a zero ---
        if np.all(v <= 1.0):
            ep = pd.DataFrame([{
                "Inizio": s.index[0], "Fine": s.index[-1], "Ore": n,
                "Tipo": "🧊 Zero",
                "Scostamento (MWh)": 0.0, "z max": np.nan,
                "Costo stimato (€)": 0.0}])
            return {"errore": None, "valido": True,
                    "verdetto": "🔴 SOSPETTO GUASTO CONTATORE",
                    "n_episodi": 1, "ore_anomale": n,
                    "impatto_tot_mwh": 0.0, "costo_stimato_eur": 0.0,
                    "df_episodi": ep,
                    "df_serie": pd.DataFrame({
                        "Timestamp": s.index, "kW": v,
                        "Baseline (kW)": np.zeros(n),
                        "z-score": np.zeros(n),
                        "Episodio": "🧊 Zero"})}
        mu, sd = float(np.mean(v)), float(np.std(v))
        if mu > 0.0 and sd / mu < 5e-4:
            return {"errore": None, "valido": True,
                    "verdetto": "🔴 SOSPETTO GUASTO CONTATORE",
                    "n_episodi": 1, "ore_anomale": n,
                    "impatto_tot_mwh": 0.0, "costo_stimato_eur": 0.0,
                    "df_episodi": pd.DataFrame([{
                        "Inizio": s.index[0], "Fine": s.index[-1],
                        "Ore": n, "Tipo": "🧱 Piatto",
                        "Scostamento (MWh)": 0.0, "z max": np.nan,
                        "Costo stimato (€)": 0.0}]),
                    "df_serie": pd.DataFrame({
                        "Timestamp": s.index, "kW": v,
                        "Baseline (kW)": np.full(n, mu),
                        "z-score": np.zeros(n),
                        "Episodio": "🧱 Piatto"})}

        # --- baseline stagionale ora x giorno settimana ---
        bucket = (s.index.dayofweek * 24 + s.index.hour).to_numpy()
        base = np.empty(n)
        for b in range(168):
            msk = bucket == b
            base[msk] = np.median(v[msk]) if msk.any() else med
        resid = v - base
        mad = float(np.median(np.abs(resid - np.median(resid))))
        sigma = 1.4826 * mad
        if sigma <= 1e-9:
            sigma = float(np.std(resid))
        z = resid / sigma if sigma > 1e-9 else np.zeros(n)
        flag = np.abs(z) >= soglia_z

        # --- controlli strutturali: run di zeri e di valori costanti ---
        zero_tol = max(1.0, 0.005 * med)
        flat_tol = max(0.5, 0.0005 * med)
        is_zero = v <= zero_tol
        # step piatto i (i>=1): v[i] ~= v[i-1]; prepend=nan -> step 0 mai piatto
        dv = np.abs(np.diff(v, prepend=np.nan))
        is_flat_step = dv <= flat_tol

        def _runs(mask, min_len):
            runs = []
            i = 0
            while i < n:
                if mask[i]:
                    j = i
                    while j + 1 < n and mask[j + 1]:
                        j += 1
                    if j - i + 1 >= min_len:
                        runs.append((i, j))
                    i = j + 1
                else:
                    i += 1
            return runs

        intervalli = []  # (i0, i1, tipo_strutturale o None)
        for i0, i1 in _runs(is_zero, 6):
            intervalli.append((i0, i1, "🧊 Zero"))
        # run di step piatti i0..i1 (i0>=1) -> valori costanti i0-1..i1:
        # 11 step = 12 valori
        for i0, i1 in _runs(is_flat_step, 11):
            intervalli.append((i0 - 1, i1, "🧱 Piatto"))
        for i0, i1 in _runs(flag, run_min_ore):
            intervalli.append((i0, i1, None))

        # --- unione intervalli sovrapposti/adiacenti ---
        intervalli.sort(key=lambda t: (t[0], t[1]))
        uniti = []
        for i0, i1, tp in intervalli:
            if uniti and i0 <= uniti[-1][1] + 1:
                p0, p1, ptp = uniti[-1]
                prio = {"🧊 Zero": 3, "🧱 Piatto": 2}
                new_tp = ptp if prio.get(ptp, 0) >= prio.get(tp, 0) else tp
                uniti[-1] = (p0, max(p1, i1), new_tp)
            else:
                uniti.append((i0, i1, tp))

        righe = []
        ep_label = np.array([""] * n, dtype=object)
        for k, (i0, i1, tp) in enumerate(uniti):
            ore = i1 - i0 + 1
            seg_v = v[i0:i1 + 1]
            seg_r = resid[i0:i1 + 1]
            seg_z = z[i0:i1 + 1]
            impatto = float(np.sum(seg_r) / 1000.0)
            zmax = float(np.max(np.abs(seg_z)))
            if tp == "🧊 Zero":
                tipo = "🧊 Zero"
            elif tp == "🧱 Piatto":
                tipo = "🧱 Piatto"
            elif np.all(seg_v <= zero_tol):
                tipo = "🧊 Zero"
            elif float(np.std(seg_v)) <= flat_tol:
                tipo = "🧱 Piatto"
            elif np.all(seg_r > 0):
                tipo = "⚡ Picco"
            elif np.all(seg_r < 0):
                tipo = "📉 Crollo"
            else:
                tipo = "↕️ Misto"
            costo = (impatto * prezzo_eur_mwh
                     if prezzo_eur_mwh is not None else None)
            righe.append({
                "Inizio": s.index[i0], "Fine": s.index[i1], "Ore": ore,
                "Tipo": tipo, "Scostamento (MWh)": round(impatto, 3),
                "z max": round(zmax, 2),
                "Costo stimato (€)": (round(costo, 2)
                                      if costo is not None else None)})
            ep_label[i0:i1 + 1] = "%d · %s" % (k + 1, tipo)

        df_ep = pd.DataFrame(righe, columns=colonne_ep)
        n_ep = len(righe)
        ore_anom = int(sum(r["Ore"] for r in righe))
        impatto_tot = round(float(sum(r["Scostamento (MWh)"] for r in righe)),
                            3)
        costo_tot = (round(impatto_tot * prezzo_eur_mwh, 2)
                     if prezzo_eur_mwh is not None else None)

        if n_ep == 0:
            verdetto = "🟢 SOTTO CONTROLLO"
        elif any(r["Tipo"] in ("🧊 Zero", "🧱 Piatto") and r["Ore"] >= 24
                 for r in righe):
            verdetto = "🔴 SOSPETTO GUASTO CONTATORE"
        elif (n_ep >= 3 or any(r["z max"] >= 6.0 for r in righe)
              or any(abs(r["Scostamento (MWh)"]) >= 20.0 for r in righe)):
            verdetto = "🟠 ANOMALIE RILEVANTI"
        else:
            verdetto = "🟡 ANOMALIE LIEVI"

        df_sr = pd.DataFrame({
            "Timestamp": s.index, "kW": np.round(v, 3),
            "Baseline (kW)": np.round(base, 3),
            "z-score": np.round(z, 2), "Episodio": ep_label})
        return {"errore": None, "valido": True, "verdetto": verdetto,
                "n_episodi": n_ep, "ore_anomale": ore_anom,
                "impatto_tot_mwh": impatto_tot,
                "costo_stimato_eur": costo_tot,
                "df_episodi": df_ep, "df_serie": df_sr}
    except Exception as e:  # pragma: no cover - guardia totale
        return _err("Errore interno: %s" % e)


def calcola_cbam(quantita_annua, fattore_emissione_tco2, prezzo_ets_eur_t,
                 anno=2026, carbonio_pagato_origine_eur=0.0,
                 prezzo_bene_eur_unita=None):
    """Stima del costo CBAM per merci importate nell'UE.

    Domanda operativa: "quanto mi costera' il meccanismo di adeguamento del
    carbonio alle frontiere sulle importazioni?" CBAM (fase definitiva dal
    01/01/2026) obbliga il dichiarante UE di cemento, ferro/acciaio,
    alluminio, fertilizzanti, idrogeno ed elettricita' a restituire
    certificati pari alle emissioni incorporate, moltiplicate per il fattore
    di phase-in dell'anno, al netto del prezzo del carbonio gia' pagato nel
    paese d'origine. Prezzo del certificato = prezzo medio delle aste EU ETS
    (Q1 2026: 75,36 €/tCO2; Q2 2026: 75,28 €/tCO2).

    Fattori di phase-in (quota delle emissioni soggetta a CBAM):
    2026: 2,5% - 2027: 5% - 2028: 10% - 2029: 22,5% - 2030: 48,5% -
    2031: 61% - 2032: 73,5% - 2033: 86% - 2034: 100%.

    Formule:
      emissioni (tCO2) = quantita' x fattore_emissione
      certificati_lordi = emissioni x fattore_phasein(anno)
      deduzione_origine (tCO2 eq.) = carbonio_pagato_origine / prezzo_ets
      certificati_netti = max(0, certificati_lordi - deduzione_origine)
      costo = certificati_netti x prezzo_ets
      aggravio = costo_unitario / prezzo_bene (se prezzo_bene fornito)

    Nota: Islanda, Liechtenstein, Norvegia e Svizzera sono escluse dal CBAM
    come paesi d'origine.

    NaN-safe: parametri fuori range / anno non in 2026-2034 -> errore
    pulito. Deterministico.

    Ritorna dict con 'errore', 'valido', 'verdetto', 'emissioni_tco2',
    'fattore_cbam', 'certificati_lordi', 'deduzione_origine_tco2',
    'certificati_netti', 'costo_annuo_eur', 'costo_unitario_eur',
    'aggravio_pct' (None se prezzo_bene non fornito),
    'df_traiettoria' (Anno, Fattore CBAM %, Certificati netti (tCO2),
    Costo annuo (€) per il 2026-2034 allo stesso prezzo ETS).
    """
    fattori = {2026: 0.025, 2027: 0.05, 2028: 0.10, 2029: 0.225,
               2030: 0.485, 2031: 0.61, 2032: 0.735, 2033: 0.86,
               2034: 1.0}
    colonne_tr = ["Anno", "Fattore CBAM (%)", "Certificati netti (tCO2)",
                  "Costo annuo (€)"]
    vuoto = {"errore": None, "valido": False, "verdetto": None,
             "emissioni_tco2": 0.0, "fattore_cbam": None,
             "certificati_lordi": 0.0, "deduzione_origine_tco2": 0.0,
             "certificati_netti": 0.0, "costo_annuo_eur": 0.0,
             "costo_unitario_eur": 0.0, "aggravio_pct": None,
             "df_traiettoria": pd.DataFrame(columns=colonne_tr)}

    def _err(msg):
        out = dict(vuoto)
        out["df_traiettoria"] = pd.DataFrame(columns=colonne_tr)
        out["errore"] = msg
        return out

    def _num(x, nome):
        if isinstance(x, bool):
            raise ValueError(nome)
        v = float(x)
        if not np.isfinite(v):
            raise ValueError(nome)
        return v

    try:
        q = _num(quantita_annua, "quantita")
        fe = _num(fattore_emissione_tco2, "fattore")
        pe = _num(prezzo_ets_eur_t, "prezzo_ets")
        cp = _num(carbonio_pagato_origine_eur, "carbonio_pagato")
        if isinstance(anno, bool):
            raise ValueError("anno")
        anno_i = int(anno)
        if anno_i != anno:
            raise ValueError("anno")
        pb = None
        if prezzo_bene_eur_unita is not None:
            pb = _num(prezzo_bene_eur_unita, "prezzo_bene")
    except (TypeError, ValueError):
        return _err("Parametri non validi: numeri finiti; anno intero "
                    "2026-2034.")
    if q <= 0:
        return _err("Parametri non validi: quantita' annua > 0.")
    if fe <= 0:
        return _err("Parametri non validi: fattore di emissione > 0.")
    if pe <= 0:
        return _err("Parametri non validi: prezzo ETS > 0.")
    if cp < 0:
        return _err("Parametri non validi: carbonio pagato >= 0.")
    if anno_i not in fattori:
        return _err("Parametri non validi: anno tra 2026 e 2034.")
    if pb is not None and pb < 0:
        return _err("Parametri non validi: prezzo del bene >= 0.")

    f = fattori[anno_i]
    emissioni = q * fe
    lordi = emissioni * f
    deduzione = min(lordi, cp / pe)
    netti = lordi - deduzione
    costo = netti * pe
    unitario = costo / q
    aggravio = (unitario / pb * 100.0) if (pb is not None and pb > 0) else None

    righe = []
    for a in sorted(fattori):
        fa = fattori[a]
        lordi_a = emissioni * fa
        netti_a = max(0.0, lordi_a - min(lordi_a, cp / pe))
        righe.append({"Anno": a, "Fattore CBAM (%)": round(fa * 100.0, 2),
                      "Certificati netti (tCO2)": round(netti_a, 3),
                      "Costo annuo (€)": round(netti_a * pe, 2)})
    df_tr = pd.DataFrame(righe, columns=colonne_tr)

    if aggravio is None:
        verdetto = "ℹ️ STIMA COMPLETATA"
    elif aggravio < 1.0:
        verdetto = "🟢 AGGRAVIO TRASCURABILE (<1% del prezzo del bene)"
    elif aggravio < 5.0:
        verdetto = "🟡 AGGRAVIO MODERATO (<5%)"
    elif aggravio < 15.0:
        verdetto = "🟠 AGGRAVIO RILEVANTE (<15%)"
    else:
        verdetto = "🔴 AGGRAVIO CRITICO (>=15%)"

    return {"errore": None, "valido": True, "verdetto": verdetto,
            "emissioni_tco2": emissioni, "fattore_cbam": f,
            "certificati_lordi": lordi,
            "deduzione_origine_tco2": deduzione,
            "certificati_netti": netti, "costo_annuo_eur": costo,
            "costo_unitario_eur": unitario, "aggravio_pct": aggravio,
            "df_traiettoria": df_tr}


def profilo_mensile_demo(tipo="piatto"):
    """Quote mensili (12 valori con somma 1.0) per ripartire l'energia annua.

    Tipi disponibili: "piatto" (1/12 al mese), "estivo" (picco lug-ago,
    climatizzazione), "invernale" (picco gen-feb, riscaldamento elettrico),
    "doppia_punta" (picchi estate e inverno). Tipo sconosciuto -> "piatto".
    Ritorna sempre 12 float la cui somma e' 1.0. Deterministico.
    """
    base = {
        "piatto": [1.0] * 12,
        "estivo": [0.90, 0.85, 0.90, 0.95, 1.05, 1.25, 1.45, 1.45,
                   1.15, 1.00, 0.90, 0.90],
        "invernale": [1.45, 1.35, 1.15, 0.95, 0.85, 0.80, 0.80, 0.85,
                      0.90, 1.00, 1.20, 1.40],
        "doppia_punta": [1.30, 1.20, 1.05, 0.95, 0.95, 1.10, 1.25, 1.25,
                         1.05, 0.95, 1.05, 1.25],
    }
    pesi = base.get(tipo, base["piatto"])
    tot = float(sum(pesi))
    return [p / tot for p in pesi]


def calcola_componenti_trasporto_misura(energia_mwh_annua, potenza_kw, n_pod=1,
                                             tensione="BT", comp=None,
                                             quote_mensili=None,
                                             energia_scenari=None):
    """Stima dei corrispettivi regolati di TRASMISSIONE, DISTRIBUZIONE e
    MISURA per un prelievo italiano (struttura TIT, delibera ARERA
    654/2015/R/eel e successive; i valori vengono aggiornati ogni anno).

    Domanda operativa: "oltre la materia energia, il dispacciamento e gli
    oneri generali, quanto pesano i servizi di rete regolati in bolletta?"
    Tre gruppi, ognuno con quota fissa (euro/POD/anno) + quota potenza
    (euro/kW/anno sulla potenza impegnata) + quota energia (euro/MWh):
      - TRASMISSIONE: tau1 (fissa), tau2 (potenza), tau3 (energia) --
        corrispettivi di trasmissione definiti da ARERA a livello nazionale;
      - DISTRIBUZIONE: quota fissa, quota potenza, quota energia;
      - MISURA: sigma1 (fissa), sigma2 (potenza), sigma3 (energia).

    comp: dict opzionale con le 9 chiavi ("tau1_fissa", "tau2_potenza",
    "tau3_energia", "distr_fissa", "distr_potenza", "distr_energia",
    "sigma1_fissa", "sigma2_potenza", "sigma3_energia"); se None, o per le
    chiavi mancanti, si usano i default INDICATIVI per la tensione scelta
    (BT o MT).

    Formule:
      fissa   = n_pod x (tau1 + distr_fissa + sigma1)
      potenza = potenza_kw x (tau2 + distr_potenza + sigma2)
      energia = energia_mwh x (tau3 + distr_energia + sigma3)
      totale  = fissa + potenza + energia
      equivalente (euro/MWh) = totale / energia
      trasm/distr/misura = somma delle tre quote di ciascun gruppo

    Il mensile riparte le quote energia per quote_mensili (12 quote, default
    piatto) e fissa/potenza in dodicesimi. La sensibilita' ricalcola il
    totale al variare della quota energia di distribuzione (default:
    -30%/-15%/base/+15%/+30%).

    NaN-safe: parametri non numerici, energia <= 0, potenza < 0, n_pod non
    intero >= 1, tensione diversa da BT/MT, componenti negative o non
    numeriche, quote non 12/normalizzabili, scenari non validi -> errore
    pulito. Deterministico.

    Ritorna dict con 'errore', 'valido', 'verdetto', 'costo_fissa',
    'costo_potenza', 'costo_energia', 'costo_totale_annuo', 'trasm_eur',
    'distr_eur', 'misura_eur', 'equivalente_eur_mwh', 'quote_pct' (dict
    gruppo -> %), 'df_mensile', 'df_sensitivita'.
    """
    mesi = ["Gen", "Feb", "Mar", "Apr", "Mag", "Giu",
            "Lug", "Ago", "Set", "Ott", "Nov", "Dic"]
    chiavi = ["tau1_fissa", "tau2_potenza", "tau3_energia",
              "distr_fissa", "distr_potenza", "distr_energia",
              "sigma1_fissa", "sigma2_potenza", "sigma3_energia"]
    gruppi = {
        "trasmissione": ["tau1_fissa", "tau2_potenza", "tau3_energia"],
        "distribuzione": ["distr_fissa", "distr_potenza", "distr_energia"],
        "misura": ["sigma1_fissa", "sigma2_potenza", "sigma3_energia"],
    }
    default = {
        "BT": {"tau1_fissa": 25.0, "tau2_potenza": 25.0,
               "tau3_energia": 0.85, "distr_fissa": 31.0,
               "distr_potenza": 31.0, "distr_energia": 0.75,
               "sigma1_fissa": 26.0, "sigma2_potenza": 0.0,
               "sigma3_energia": 0.40},
        "MT": {"tau1_fissa": 25.0, "tau2_potenza": 25.0,
               "tau3_energia": 0.75, "distr_fissa": 200.0,
               "distr_potenza": 28.0, "distr_energia": 0.55,
               "sigma1_fissa": 450.0, "sigma2_potenza": 0.0,
               "sigma3_energia": 0.30},
    }
    col_m = ["Mese", "Energia (MWh)", "Trasmissione (\u20ac)",
             "Distribuzione (\u20ac)", "Misura (\u20ac)", "Totale (\u20ac)"]
    col_s = ["Scenario", "Quota distr. energia (\u20ac/MWh)",
             "Totale annuo (\u20ac)", "Equivalente (\u20ac/MWh)"]
    vuoto = {"errore": None, "valido": False, "verdetto": None,
             "costo_fissa": 0.0, "costo_potenza": 0.0,
             "costo_energia": 0.0, "costo_totale_annuo": 0.0,
             "trasm_eur": 0.0, "distr_eur": 0.0, "misura_eur": 0.0,
             "equivalente_eur_mwh": 0.0,
             "quote_pct": {"trasmissione": 0.0, "distribuzione": 0.0,
                           "misura": 0.0},
             "df_mensile": pd.DataFrame(columns=col_m),
             "df_sensitivita": pd.DataFrame(columns=col_s)}

    def _err(msg):
        out = dict(vuoto)
        out["df_mensile"] = pd.DataFrame(columns=col_m)
        out["df_sensitivita"] = pd.DataFrame(columns=col_s)
        out["quote_pct"] = {"trasmissione": 0.0, "distribuzione": 0.0,
                            "misura": 0.0}
        out["errore"] = msg
        return out

    def _num(x, nome):
        if isinstance(x, bool):
            raise ValueError(nome)
        v = float(x)
        if not np.isfinite(v):
            raise ValueError(nome)
        return v

    try:
        en = _num(energia_mwh_annua, "energia")
        pk = _num(potenza_kw, "potenza")
        if isinstance(n_pod, bool):
            raise ValueError("n_pod")
        npod = int(n_pod)
        if npod != n_pod or npod < 1:
            raise ValueError("n_pod")
        if en <= 0:
            raise ValueError("energia")
        if pk < 0:
            raise ValueError("potenza")
        tens = str(tensione).strip().upper()
        if tens not in default:
            raise ValueError("tensione")
        vals = dict(default[tens])
        if comp is not None:
            if not isinstance(comp, dict):
                raise ValueError("comp")
            for k in chiavi:
                if k in comp:
                    v = _num(comp[k], k)
                    if v < 0:
                        raise ValueError(k)
                    vals[k] = v
        if quote_mensili is None:
            quote = [1.0 / 12.0] * 12
        else:
            quote = [float(q) for q in quote_mensili]
            if len(quote) != 12 or any(q < 0 for q in quote):
                raise ValueError("quote_mensili")
            stot = sum(quote)
            if not np.isfinite(stot) or stot <= 0:
                raise ValueError("quote_mensili")
            quote = [q / stot for q in quote]
        if energia_scenari is None:
            scenari = [("meno30", 0.70), ("meno15", 0.85), ("base", 1.0),
                       ("piu15", 1.15), ("piu30", 1.30)]
        else:
            scenari = []
            for s in energia_scenari:
                nome, molt = s
                m = _num(molt, "scenario")
                if m <= 0:
                    raise ValueError("scenario")
                scenari.append((str(nome), m))
            if not scenari:
                raise ValueError("scenari")

        qf = vals["tau1_fissa"] + vals["distr_fissa"] + vals["sigma1_fissa"]
        qp = (vals["tau2_potenza"] + vals["distr_potenza"]
              + vals["sigma2_potenza"])
        qe = (vals["tau3_energia"] + vals["distr_energia"]
              + vals["sigma3_energia"])
        c_fissa = npod * qf
        c_potenza = pk * qp
        c_energia = en * qe
        totale = c_fissa + c_potenza + c_energia
        equiv = totale / en
        grp = {}
        for g, ks in gruppi.items():
            grp[g] = (npod * vals[ks[0]] + pk * vals[ks[1]]
                      + en * vals[ks[2]])
        quote_pct = {g: (grp[g] / totale * 100.0 if totale > 0 else 0.0)
                     for g in gruppi}
        if equiv < 5.0:
            verdetto = "CONTENUTI: i servizi di rete pesano poco sul tuo MWh."
        elif equiv < 10.0:
            verdetto = ("RILEVANTI: i servizi di rete sono una quota "
                        "visibile del costo all-in.")
        else:
            verdetto = ("PESANTI: a bassi consumi la componente fissa/potenza "
                        "domina il costo dei servizi di rete.")

        righe_m = []
        for i in range(12):
            en_m = en * quote[i]
            g_m = {}
            for g, ks in gruppi.items():
                g_m[g] = (npod * vals[ks[0]] / 12.0 + pk * vals[ks[1]] / 12.0
                          + en_m * vals[ks[2]])
            righe_m.append([mesi[i], en_m, g_m["trasmissione"],
                            g_m["distribuzione"], g_m["misura"],
                            g_m["trasmissione"] + g_m["distribuzione"]
                            + g_m["misura"]])
        df_m = pd.DataFrame(righe_m, columns=col_m)

        righe_s = []
        for nome, molt in scenari:
            qe_s = (vals["tau3_energia"] + vals["distr_energia"] * molt
                    + vals["sigma3_energia"])
            tot_s = c_fissa + c_potenza + en * qe_s
            righe_s.append([nome, vals["distr_energia"] * molt, tot_s,
                            tot_s / en])
        df_s = pd.DataFrame(righe_s, columns=col_s)

        return {"errore": None, "valido": True, "verdetto": verdetto,
                "costo_fissa": c_fissa, "costo_potenza": c_potenza,
                "costo_energia": c_energia, "costo_totale_annuo": totale,
                "trasm_eur": grp["trasmissione"],
                "distr_eur": grp["distribuzione"],
                "misura_eur": grp["misura"],
                "equivalente_eur_mwh": equiv, "quote_pct": quote_pct,
                "df_mensile": df_m, "df_sensitivita": df_s}
    except (ValueError, TypeError):
        return _err("Input non validi: controlla energia (>0), potenza (>=0), "
                    "n_pod (intero >=1), tensione (BT/MT) e i 9 corrispettivi "
                    "(numeri >= 0).")


def calcola_accise_iva(energia_kwh_annua, tipo_utenza="non_domestica",
                       costo_energia_eur=0.0, altri_oneri_eur=0.0,
                       accise=None, aliquota_iva=None,
                       energia_scenari=None):
    """Accisa sull'energia elettrica + IVA per una fornitura italiana.

    Domanda operativa: "della mia bolletta, quanto e' imposta (accisa +
    IVA) e quanto dipende dallo scaglione in cui cado?" L'accisa si
    applica sui kWh prelevati con scaglioni MENSILI (il calcolo viene
    fatto mese per mese, come fa il venditore in fattura):

    Domestici:
      - residente: esenzione sui primi `dom_esenzione_kwh_mese`
        (default 150) kWh/mese, oltre `dom_aliquota` (default 0,0227
        euro/kWh) su tutto il resto;
      - non residente: `dom_aliquota` su tutti i kWh.
    Non domestici (usi diversi da domestici/illuminazione pubblica):
      - fino a `nd_soglia_kwh_mese` (default 1.200.000) kWh/mese:
        `nd_aliquota_1` (default 0,0125 euro/kWh);
      - oltre: `nd_aliquota_2` (default 0,0075 euro/kWh).
    Illuminazione pubblica: esente (accisa 0).

    L'IVA si applica sulla base imponibile che INCLUDE l'accisa:
      base = costo_energia + altri_oneri + accisa
    aliquota default: 10% domestici, 22% altri (sovrascrivibile con
    `aliquota_iva`).

    accise: dict opzionale con le 5 chiavi ("dom_esenzione_kwh_mese",
    "dom_aliquota", "nd_soglia_kwh_mese", "nd_aliquota_1",
    "nd_aliquota_2"); se None, o per le chiavi mancanti, si usano i
    default INDICATIVI sopra (modificabili in UI).

    Formule:
      accisa_annua   = somma mensile (vedi sopra)
      base_iva       = costo_energia_eur + altri_oneri_eur + accisa_annua
      iva            = base_iva x aliquota_iva / 100
      totale_fattura = base_iva + iva
      totale_imposte = accisa_annua + iva
      quota_fiscale% = totale_imposte / totale_fattura x 100
      equivalente    = totale_imposte / (energia_kwh / 1000)

    Il mensile riparte l'energia annua in dodicesimi. La sensibilita'
    ricalcola accisa/IVA/imposte al variare dell'energia annua
    (default: -30%/-15%/base/+15%/+30%).

    NaN-safe: energia <= 0, tipo_utenza non valido, costi < 0, accise
    non-dict/negative/non numeriche, aliquota_iva fuori 0..100,
    scenari non validi -> errore pulito. Deterministico.

    Ritorna dict con 'errore', 'valido', 'verdetto', 'accisa_annua',
    'iva_eur', 'base_imponibile_eur', 'totale_fattura_eur',
    'totale_imposte', 'equivalente_eur_mwh', 'quota_fiscale_pct',
    'aliquota_iva_usata', 'df_mensile', 'df_sensitivita'.
    """
    mesi = ["Gen", "Feb", "Mar", "Apr", "Mag", "Giu",
            "Lug", "Ago", "Set", "Ott", "Nov", "Dic"]
    tipi = ["domestica_residente", "domestica_non_residente",
            "non_domestica", "illuminazione_pubblica"]
    chiavi = ["dom_esenzione_kwh_mese", "dom_aliquota",
              "nd_soglia_kwh_mese", "nd_aliquota_1", "nd_aliquota_2"]
    default = {"dom_esenzione_kwh_mese": 150.0, "dom_aliquota": 0.0227,
               "nd_soglia_kwh_mese": 1200000.0, "nd_aliquota_1": 0.0125,
               "nd_aliquota_2": 0.0075}
    col_m = ["Mese", "Energia (kWh)", "Accisa (€)", "Quota oltre soglia (kWh)",
             "Base IVA cumulata (€)"]
    col_s = ["Scenario", "Energia (kWh/anno)", "Accisa (€)",
             "IVA (€)", "Totale imposte (€)"]
    vuoto = {"errore": None, "valido": False, "verdetto": None,
             "accisa_annua": 0.0, "iva_eur": 0.0,
             "base_imponibile_eur": 0.0, "totale_fattura_eur": 0.0,
             "totale_imposte": 0.0, "equivalente_eur_mwh": 0.0,
             "quota_fiscale_pct": 0.0, "aliquota_iva_usata": 0.0,
             "df_mensile": pd.DataFrame(columns=col_m),
             "df_sensitivita": pd.DataFrame(columns=col_s)}

    def _err(msg):
        out = dict(vuoto)
        out["df_mensile"] = pd.DataFrame(columns=col_m)
        out["df_sensitivita"] = pd.DataFrame(columns=col_s)
        out["errore"] = msg
        return out

    def _num(x, nome):
        if isinstance(x, bool):
            raise ValueError(nome)
        v = float(x)
        if not np.isfinite(v):
            raise ValueError(nome)
        return v

    def _accisa_mese(e_m, tipo, acc):
        if tipo == "illuminazione_pubblica":
            return 0.0, 0.0
        if tipo == "domestica_residente":
            oltre = max(0.0, e_m - acc["dom_esenzione_kwh_mese"])
            return oltre * acc["dom_aliquota"], oltre
        if tipo == "domestica_non_residente":
            return e_m * acc["dom_aliquota"], e_m
        # non_domestica: doppio scaglione mensile
        sotto = min(e_m, acc["nd_soglia_kwh_mese"])
        sopra = max(0.0, e_m - acc["nd_soglia_kwh_mese"])
        return (sotto * acc["nd_aliquota_1"]
                + sopra * acc["nd_aliquota_2"]), sopra

    try:
        en = _num(energia_kwh_annua, "energia")
        ce = _num(costo_energia_eur, "costo_energia")
        ao = _num(altri_oneri_eur, "altri_oneri")
        if en <= 0:
            raise ValueError("energia")
        if ce < 0 or ao < 0:
            raise ValueError("costi")
        tipo = str(tipo_utenza).strip().lower()
        if tipo not in tipi:
            raise ValueError("tipo_utenza")
        acc = dict(default)
        if accise is not None:
            if not isinstance(accise, dict):
                raise ValueError("accise")
            for k in chiavi:
                if k in accise:
                    v = _num(accise[k], k)
                    if v < 0:
                        raise ValueError(k)
                    acc[k] = v
        if aliquota_iva is None:
            aliq = 10.0 if tipo.startswith("domestica") else 22.0
        else:
            aliq = _num(aliquota_iva, "aliquota_iva")
            if aliq < 0 or aliq > 100:
                raise ValueError("aliquota_iva")

        # --- mensile (energia in dodicesimi, scaglioni applicati al mese)
        e_mese = en / 12.0
        righe_m, accisa_annua, oltre_tot = [], 0.0, 0.0
        for m in mesi:
            a_m, oltre_m = _accisa_mese(e_mese, tipo, acc)
            accisa_annua += a_m
            oltre_tot += oltre_m
            righe_m.append({"Mese": m,
                            "Energia (kWh)": round(e_mese, 1),
                            "Accisa (€)": round(a_m, 2),
                            "Quota oltre soglia (kWh)": round(oltre_m, 1),
                            "Base IVA cumulata (€)":
                                round((ce + ao) / 12.0 + a_m, 2)})
        df_m = pd.DataFrame(righe_m)

        base = ce + ao + accisa_annua
        iva = base * aliq / 100.0
        tot_fatt = base + iva
        tot_imp = accisa_annua + iva
        quota_fisc = (tot_imp / tot_fatt * 100.0) if tot_fatt > 0 else 0.0
        equiv = tot_imp / (en / 1000.0)

        if quota_fisc < 10.0:
            verdetto = (f"Peso fiscale LEGGERO: imposte al "
                        f"{quota_fisc:.1f}% della fattura "
                        f"({equiv:.2f} €/MWh).")
        elif quota_fisc < 20.0:
            verdetto = (f"Peso fiscale MEDIO: imposte al "
                        f"{quota_fisc:.1f}% della fattura "
                        f"({equiv:.2f} €/MWh).")
        else:
            verdetto = (f"Peso fiscale PESANTE: imposte al "
                        f"{quota_fisc:.1f}% della fattura "
                        f"({equiv:.2f} €/MWh) — verifica scaglione "
                        f"ed esenzioni.")

        # --- sensibilita' all'energia annua
        if energia_scenari is None:
            energia_scenari = [-30.0, -15.0, 0.0, 15.0, 30.0]
        scen = []
        for s in energia_scenari:
            sv = _num(s, "scenari")
            e_s = en * (1.0 + sv / 100.0)
            if e_s <= 0:
                raise ValueError("scenari")
            e_ms = e_s / 12.0
            a_s = sum(_accisa_mese(e_ms, tipo, acc)[0] for _ in mesi)
            b_s = ce + ao + a_s
            i_s = b_s * aliq / 100.0
            scen.append({"Scenario": (f"{sv:+.0f}%" if sv != 0 else "base"),
                         "Energia (kWh/anno)": round(e_s, 0),
                         "Accisa (€)": round(a_s, 2),
                         "IVA (€)": round(i_s, 2),
                         "Totale imposte (€)": round(a_s + i_s, 2)})
        df_s = pd.DataFrame(scen)

        return {"errore": None, "valido": True, "verdetto": verdetto,
                "accisa_annua": accisa_annua, "iva_eur": iva,
                "base_imponibile_eur": base, "totale_fattura_eur": tot_fatt,
                "totale_imposte": tot_imp, "equivalente_eur_mwh": equiv,
                "quota_fiscale_pct": quota_fisc,
                "aliquota_iva_usata": aliq,
                "df_mensile": df_m, "df_sensitivita": df_s}
    except (ValueError, TypeError):
        return _err("Input non validi: controlla energia (>0), tipo_utenza "
                    "(domestica_residente / domestica_non_residente / "
                    "non_domestica / illuminazione_pubblica), costi (>=0), "
                    "le 5 aliquote/esenzioni (numeri >= 0) e l'aliquota IVA "
                    "(0..100).")

def calcola_duck_curve(carico_picco_mw, capacita_fv_mw=0.0,
                       capacita_eolico_mw=0.0, stagione="estate",
                       fattore_eolico=0.35):
    """Curva dell'anatra (duck curve): carico netto residuo orario.

    Domanda operativa: "con tot FV/eolico installato, quanto si svuota il
    carico a mezzogiorno e quanto deve rampare il parco flessibile la
    sera?" Carico netto = carico - solare - eolico, ora per ora.

    Profili deterministici (frazioni di picco / capacita', niente
    randomness):
      - carico: 24 valori espliciti (doppia gobba: spalla mattutina,
        plateau diurno, picco serale ore 19 = 1.00);
      - solare: campana sinusoidale tra alba e tramonto
        (estate: 6-20, fattore di picco 0.90; inverno: 8-16, fattore 0.60);
      - eolico: piatto a `fattore_eolico` (default 0.35) della capacita'.

    KPI: pancia (minimo del carico netto e ora), rampa serale massima
    oraria tra le 15 e le 22 (il "collo" dell'anatra), rampa mattutina
    massima in discesa tra le 6 e le 13, ore di overgeneration
    (carico netto < 0) e indice duck = pancia / picco.
    Ritorna dict con valido/errore, df_orario e i KPI. Input non validi
    -> valido=False.
    """
    _PROFILO_CARICO = (
        0.60, 0.60, 0.60, 0.60, 0.60,  # 0-4 valle notturna
        0.62, 0.68, 0.78,              # 5-7 risveglio
        0.85, 0.88,                    # 8-9 spalla mattutina
        0.80, 0.80, 0.80, 0.80, 0.80, 0.80, 0.80,  # 10-16 plateau diurno
        0.85, 0.93, 1.00,              # 17-19 picco serale
        0.95, 0.85, 0.72, 0.64,        # 20-23 rientro
    )
    _STAGIONI = {"estate": (6, 20, 0.90), "inverno": (8, 16, 0.60)}

    def _err(msg):
        return {"valido": False, "errore": msg}

    try:
        if isinstance(carico_picco_mw, bool):
            raise ValueError("picco")
        picco = float(carico_picco_mw)
        fv = float(capacita_fv_mw)
        eo = float(capacita_eolico_mw)
        fe = float(fattore_eolico)
        for v, nome in ((picco, "carico_picco_mw"), (fv, "capacita_fv_mw"),
                        (eo, "capacita_eolico_mw"), (fe, "fattore_eolico")):
            if not np.isfinite(v):
                raise ValueError(nome)
        if picco <= 0:
            return _err("carico_picco_mw deve essere > 0.")
        if fv < 0 or eo < 0:
            return _err("Le capacita' FV/eolico non possono essere negative.")
        if not 0.0 <= fe <= 1.0:
            return _err("fattore_eolico deve stare in [0, 1].")
        stag = str(stagione).strip().lower()
        if stag not in _STAGIONI:
            return _err("stagione deve essere 'estate' o 'inverno'.")
        alba, tramonto, cf_picco = _STAGIONI[stag]

        ore = list(range(24))
        carico = [picco * _PROFILO_CARICO[h] for h in ore]
        solare = []
        for h in ore:
            if alba <= h <= tramonto:
                f = cf_picco * max(0.0, np.sin(np.pi * (h - alba)
                                              / (tramonto - alba)))
            else:
                f = 0.0
            solare.append(fv * f)
        eolico = [eo * fe] * 24
        netto = [c - s - e for c, s, e in zip(carico, solare, eolico)]

        i_min = int(np.argmin(netto))
        pancia = picco - netto[i_min]
        # rampa serale: max incremento orario tra le 15 e le 22
        rampa_serale = max((netto[h + 1] - netto[h]) for h in range(15, 22))
        # rampa mattutina: max decremento orario tra le 6 e le 13
        rampa_matt = max((netto[h] - netto[h + 1]) for h in range(6, 13))
        ore_overgen = sum(1 for v in netto if v < 0.0)

        df = pd.DataFrame({"ora": ore, "carico_MW": carico,
                           "solare_MW": solare, "eolico_MW": eolico,
                           "carico_netto_MW": netto})
        return {"valido": True, "errore": None,
                "df_orario": df,
                "carico_netto_min_MW": float(netto[i_min]),
                "ora_minimo": i_min,
                "profondita_pancia_MW": float(pancia),
                "indice_duck": float(pancia / picco),
                "rampa_serale_max_MW_h": float(rampa_serale),
                "rampa_mattutina_max_MW_h": float(rampa_matt),
                "ore_overgeneration": int(ore_overgen),
                "stagione_usata": stag}
    except (ValueError, TypeError):
        return _err("Input non validi: controlla carico_picco_mw (>0), "
                    "capacita_fv_mw e capacita_eolico_mw (>=0), "
                    "fattore_eolico in [0,1] e stagione ('estate'/'inverno').")


def calcola_mef_orario(carico_picco_mw, cap_nucleare_mw=0.0, cap_idro_mw=0.0,
                       cap_eolico_mw=0.0, cap_fv_mw=0.0, cap_carbone_mw=0.0,
                       cap_ccgt_mw=0.0, cap_ocgt_mw=0.0, cap_import_mw=0.0,
                       stagione="estate", fattore_eolico=0.35):
    """Fattore di emissione marginale (MEF) orario da merit order.

    Domanda operativa: "se sposto 1 MWh di consumo da un'ora all'altra,
    quanta CO2 evito davvero?" Il MEF di un'ora e' il fattore di emissione
    della centrale MARGINALE, cioe' l'ultima chiamata in ordine di costo
    per coprire il carico di quell'ora (non la media del mix: la media
    sottostima l'effetto dello shifting).

    Stack deterministico (costo marginale crescente, niente randomness):
      Fotovoltaico (0 eur/MWh, 0 tCO2/MWh, campana solare stagionale),
      Eolico (0, 0, piatto a fattore_eolico), Idroelettrico ad acqua
      fluente (2, 0, piatto al 50%), Nucleare (10, 0, piatto all'85%),
      Carbone (45, 0.95), Import (60, 0.45), Gas CCGT (75, 0.40),
      Gas OCGT (130, 0.55). Costi ed emissioni sono default indicativi
      documentati nel codice, non quotazioni di mercato.

    Per ogni ora il carico segue il profilo standard a doppia gobba
    (picco ore 19 = 1.00); il dispacciamento copre il carico in ordine
    di costo e la tecnologia marginale fissa il MEF. Se le rinnovabili
    coprono tutto il carico il MEF e' 0 (curtailment). Se la capacita'
    non basta, deficit=True (il MEF resta quello dell'ultima tecnologia
    disponibile e la UI deve segnalarlo).

    KPI: MEF medio ponderato sul carico, MEF max/min con ora, delta
    spostabile (max-min = CO2 evitabile spostando 1 MWh dall'ora peggiore
    alla migliore), ore con MEF=0, mix delle tecnologie marginali.
    Ritorna dict con valido/errore, df_orario e i KPI. Input non validi
    -> valido=False.
    """
    _PROFILO_CARICO = (
        0.60, 0.60, 0.60, 0.60, 0.60,  # 0-4 valle notturna
        0.62, 0.68, 0.78,              # 5-7 risveglio
        0.85, 0.88,                    # 8-9 spalla mattutina
        0.80, 0.80, 0.80, 0.80, 0.80, 0.80, 0.80,  # 10-16 plateau diurno
        0.85, 0.93, 1.00,              # 17-19 picco serale
        0.95, 0.85, 0.72, 0.64,        # 20-23 rientro
    )
    _STAGIONI = {"estate": (6, 20, 0.90), "inverno": (8, 16, 0.60)}
    _EPS = 1e-6
    # (nome, costo marginale eur/MWh, fattore emissione tCO2/MWh, profilo)
    _STACK = (
        ("Fotovoltaico", 0.0, 0.0, "solare"),
        ("Eolico", 0.0, 0.0, "eolico"),
        ("Idroelettrico", 2.0, 0.0, "idro"),
        ("Nucleare", 10.0, 0.0, "nucleare"),
        ("Carbone", 45.0, 0.95, "piatto"),
        ("Import", 60.0, 0.45, "piatto"),
        ("Gas CCGT", 75.0, 0.40, "piatto"),
        ("Gas OCGT", 130.0, 0.55, "piatto"),
    )
    _FATTORI_PIATTI = {"idro": 0.50, "nucleare": 0.85, "piatto": 1.0}

    def _err(msg):
        return {"valido": False, "errore": msg}

    try:
        if isinstance(carico_picco_mw, bool):
            raise ValueError("picco")
        picco = float(carico_picco_mw)
        fe = float(fattore_eolico)
        caps = {
            "Nucleare": float(cap_nucleare_mw),
            "Idroelettrico": float(cap_idro_mw),
            "Eolico": float(cap_eolico_mw),
            "Fotovoltaico": float(cap_fv_mw),
            "Carbone": float(cap_carbone_mw),
            "Gas CCGT": float(cap_ccgt_mw),
            "Gas OCGT": float(cap_ocgt_mw),
            "Import": float(cap_import_mw),
        }
        for v in list(caps.values()) + [picco, fe]:
            if not np.isfinite(v):
                raise ValueError("non finito")
        if picco <= 0:
            return _err("carico_picco_mw deve essere > 0.")
        if any(v < 0 for v in caps.values()):
            return _err("Le capacita' installate non possono essere negative.")
        if not 0.0 <= fe <= 1.0:
            return _err("fattore_eolico deve stare in [0, 1].")
        if sum(caps.values()) <= 0:
            return _err("Capacita' totale nulla: impossibile coprire il carico.")
        stag = str(stagione).strip().lower()
        if stag not in _STAGIONI:
            return _err("stagione deve essere 'estate' o 'inverno'.")
        alba, tramonto, cf_picco = _STAGIONI[stag]

        def _solare(h):
            if alba <= h <= tramonto:
                return cf_picco * max(0.0, np.sin(np.pi * (h - alba)
                                                 / (tramonto - alba)))
            return 0.0

        ore = list(range(24))
        stack = []
        for nome, _costo, ef, tipo in _STACK:
            cap = caps[nome]
            if tipo == "solare":
                disp = [cap * _solare(h) for h in ore]
            elif tipo == "eolico":
                disp = [cap * fe] * 24
            else:
                disp = [cap * _FATTORI_PIATTI[tipo]] * 24
            stack.append((nome, ef, disp))

        carichi, mef, marg, deficit = [], [], [], False
        for h in ore:
            carico = picco * _PROFILO_CARICO[h]
            residuo = carico
            tec, f = None, 0.0
            for nome, ef, disp in stack:
                p = disp[h]
                if p <= _EPS:
                    continue
                take = p if p < residuo else residuo
                residuo -= take
                if take > _EPS:
                    tec, f = nome, ef
                if residuo <= _EPS:
                    break
            if residuo > _EPS:
                deficit = True
            carichi.append(carico)
            mef.append(round(f, 4))
            marg.append(tec if tec else "Nessuna")

        tot_carico = sum(carichi)
        medio = sum(m * c for m, c in zip(mef, carichi)) / tot_carico
        i_max = int(np.argmax(mef))
        i_min = int(np.argmin(mef))
        mix = {}
        for t in marg:
            mix[t] = mix.get(t, 0) + 1
        df = pd.DataFrame({"ora": ore, "carico_MW": carichi,
                           "mef_tco2_mwh": mef,
                           "tecnologia_marginale": marg})
        return {"valido": True, "errore": None,
                "df_orario": df,
                "mef_medio_ponderato_tco2_mwh": round(medio, 4),
                "mef_max_tco2_mwh": mef[i_max],
                "ora_mef_max": i_max,
                "mef_min_tco2_mwh": mef[i_min],
                "ora_mef_min": i_min,
                "delta_mef_spostabile_tco2_mwh": round(mef[i_max] - mef[i_min], 4),
                "ore_mef_zero": sum(1 for m in mef if m <= _EPS),
                "mix_marginale_ore": mix,
                "deficit": bool(deficit),
                "stagione_usata": stag}
    except (ValueError, TypeError):
        return _err("Input non validi: controlla carico_picco_mw (>0), "
                    "le capacita' (>=0, almeno una >0), "
                    "fattore_eolico in [0,1] e stagione ('estate'/'inverno').")


def calcola_budget_rischio(nomi, esposizioni_eur, volatilita_annua_pct,
                           correlazione_media=0.3, confidenza=0.95,
                           orizzonte_giorni=10):
    """Budget di rischio di portafoglio: Component VaR (allocazione di Eulero).

    Domanda operativa: "quale posizione mi sta facendo correre piu' rischio?"
    Il VaR di portafoglio NON e' la somma dei VaR standalone (diversificazione);
    il contributo marginale di ogni posizione al rischio totale si ottiene con
    l'allocazione di Eulero: CVaR_i = w_i * dVaR/dw_i (i CVaR sommano
    esattamente al VaR di portafoglio).

    Parametri:
      nomi, esposizioni_eur, volatilita_annua_pct: liste lunghe n>=2
      correlazione_media: correlazione uniforme tra coppie di posizioni (-1..1)
      confidenza: livello VaR (es. 0.95 / 0.99)
      orizzonte_giorni: orizzonte VaR in giorni di mercato (252/anno)

    KPI: VaR di portafoglio, VaR standalone sommati, benefit di
    diversificazione, contributo % al rischio per posizione, target equal-risk
    (1/n), numero effettivo di scommesse (ENB = 1/sum(c_i^2)), posizione
    dominante e verdetto sulla concentrazione.
    """
    import math
    def _err(msg):
        return {"valido": False, "errore": msg}

    try:
        nomi = [str(x).strip() or f"Posizione {i+1}"
                for i, x in enumerate(nomi)]
        E = [float(x) for x in esposizioni_eur]
        S = [float(x) / 100.0 for x in volatilita_annua_pct]
        rho = float(correlazione_media)
        conf = float(confidenza)
        T = float(orizzonte_giorni)
        for nome, v in (("esposizioni", E), ("volatilita", S)):
            if any(isinstance(x, bool) for x in v):
                raise ValueError(nome)
    except (TypeError, ValueError):
        return _err("Input non validi: esposizioni e volatilita' devono essere numeri.")

    n = len(nomi)
    if n < 2 or not (len(E) == len(S) == n):
        return _err("Servono almeno 2 posizioni con nome, esposizione e volatilita'.")
    if any(e <= 0 for e in E):
        return _err("Le esposizioni devono essere positive.")
    if any(s <= 0 for s in S):
        return _err("Le volatilita' devono essere positive.")
    if not (-1.0 <= rho <= 1.0):
        return _err("La correlazione media deve stare tra -1 e 1.")
    if not (0.5 <= conf < 1.0):
        return _err("La confidenza deve stare tra 0.50 e 0.99.")
    if T <= 0:
        return _err("L'orizzonte deve essere positivo.")
    if len(set(nomi)) != n:
        return _err("I nomi delle posizioni devono essere univoci.")

    E = np.array(E)
    S = np.array(S)
    E_tot = E.sum()
    w = E / E_tot
    # matrice di covarianza con correlazione uniforme
    C = np.full((n, n), rho)
    np.fill_diagonal(C, 1.0)
    cov = np.outer(S, S) * C
    var_p = float(w @ cov @ w)
    if var_p <= 0:
        return _err("Varianza di portafoglio non positiva: ricontrolla input.")
    vol_p = math.sqrt(var_p)
    z = float(norm.ppf(conf))
    scala = z * math.sqrt(T / 252.0)
    var_portafoglio = scala * vol_p * E_tot
    # Component VaR di Eulero: CVaR_i = E_tot * scala * w_i * (cov w)_i / vol_p
    marg = (cov @ w) / vol_p
    cvar = E_tot * scala * w * marg
    var_standalone = scala * S * E
    benefit_div = float(var_standalone.sum() - var_portafoglio)
    contrib_pct = cvar / var_portafoglio  # somma = 1
    enb = float(1.0 / np.sum(contrib_pct ** 2))
    target = 1.0 / n
    i_dom = int(np.argmax(contrib_pct))

    if contrib_pct[i_dom] >= 0.50:
        verdetto = (f"CONCENTRAZIONE: {nomi[i_dom]} spiega da sola il "
                    f"{contrib_pct[i_dom]*100:.0f}% del rischio di portafoglio "
                    f"(soglia 50%). Valuta se ridurre l'esposizione o coprirla.")
    elif enb < n / 2:
        verdetto = (f"Rischio sbilanciato: il numero effettivo di scommesse "
                    f"({enb:.1f}) e' meno della meta' delle posizioni ({n}). "
                    f"Il portafoglio si comporta come poche posizioni concentrate.")
    else:
        verdetto = (f"Rischio ben distribuito: nessuna posizione supera il "
                    f"{contrib_pct[i_dom]*100:.0f}% del rischio e il numero "
                    f"effettivo di scommesse ({enb:.1f} su {n}) e' alto.")

    df = pd.DataFrame({
        "Posizione": nomi,
        "Esposizione (eur)": np.round(E, 0),
        "Volatilita' annua (%)": np.round(S * 100.0, 1),
        "VaR standalone (eur)": np.round(var_standalone, 0),
        "Component VaR (eur)": np.round(cvar, 0),
        "Contributo al rischio (%)": np.round(contrib_pct * 100.0, 1),
        "Target equal-risk (%)": round(target * 100.0, 1),
    }).sort_values("Contributo al rischio (%)", ascending=False).reset_index(drop=True)

    return {
        "valido": True, "errore": None,
        "var_portafoglio_eur": var_portafoglio,
        "var_standalone_somma_eur": float(var_standalone.sum()),
        "benefit_diversificazione_eur": benefit_div,
        "volatilita_portafoglio_annua_pct": vol_p * 100.0,
        "numero_effettivo_scommesse": enb,
        "posizione_dominante": nomi[i_dom],
        "contributo_dominante_pct": float(contrib_pct[i_dom] * 100.0),
        "verdetto": verdetto,
        "df": df,
        "confidenza": conf, "orizzonte_giorni": T,
        "correlazione_media": rho,
    }


def calcola_valore_forecast(quantita_mwh, n_giorni=30, prezzo_medio_eur_mwh=95.0,
                            vol_giornaliera_eur_mwh=6.0, sigma_forecast=3.0,
                            n_sim=20000, seed=7):
    """Valore economico del forecast per il timing di acquisto (EVPI).

    Domanda operativa: "quanto vale in euro un forecast migliore?" Un buyer
    deve acquistare Q MWh una sola volta dentro una finestra di N giorni.
    Il prezzo spot giornaliero e' incerto; con un forecast (segnale rumoroso
    del prezzo effettivo) compra nel giorno col forecast minimo. Il valore
    del forecast = costo atteso della strategia naive (acquisto al prezzo
    medio atteso) meno costo atteso della strategia col forecast. Con
    forecast perfetto (sigma=0) si ottiene l'EVPI = upper bound teorico del
    valore dell'informazione: nessun sistema di previsione puo' valere di
    piu' di cosi'.

    Modello (Monte Carlo, seed fissato -> deterministico):
      P_t = mu + X_t,  X_t = phi * X_{t-1} + vol * sqrt(1-phi^2) * Z_t
      (AR(1) stazionario, phi=0.7: i prezzi giornalieri sono persistenti)
      F_t = P_t + sigma * eps_t   (segnale unbiased, errore iid)
    Strategie per simulazione:
      naive    -> compra al prezzo medio atteso mu (giorno casuale)
      forecast -> compra in t* = argmin(F_t), paga P_{t*}
      perfect  -> compra in argmin(P_t), paga min(P_t)  (EVPI)
    KPI: risparmio atteso eur/MWh e totale per forecast e perfect,
    % di EVPI catturata, curva valore-vs-sigma (il valore decade con
    l'errore del forecast), distribuzione del risparmio (p5/mediana/p95).
    """
    _phi = 0.7  # persistenza AR(1) dei prezzi giornalieri

    def _err(msg):
        return {"valido": False, "errore": msg}

    try:
        for nome, v in (("quantita_mwh", quantita_mwh),
                        ("n_giorni", n_giorni),
                        ("prezzo_medio", prezzo_medio_eur_mwh),
                        ("vol_giornaliera", vol_giornaliera_eur_mwh),
                        ("sigma_forecast", sigma_forecast),
                        ("n_sim", n_sim)):
            if isinstance(v, bool):
                raise ValueError(nome)
        q = float(quantita_mwh)
        n = int(n_giorni)
        mu = float(prezzo_medio_eur_mwh)
        vol = float(vol_giornaliera_eur_mwh)
        sig = float(sigma_forecast)
        ns = int(n_sim)
        if q <= 0:
            return _err("La quantita' da acquistare deve essere > 0 MWh.")
        if n < 2:
            return _err("La finestra decisionale deve avere almeno 2 giorni.")
        if mu <= 0:
            return _err("Il prezzo medio atteso deve essere > 0 eur/MWh.")
        if vol < 0:
            return _err("La volatilita' giornaliera non puo' essere negativa.")
        if sig < 0:
            return _err("L'errore del forecast (sigma) non puo' essere negativo.")
        if ns < 500:
            return _err("Servono almeno 500 simulazioni per un Monte Carlo stabile.")
    except (TypeError, ValueError):
        return _err("Parametri non numerici o non validi.")

    rng = np.random.default_rng(seed)
    innov = np.sqrt(max(1e-12, 1.0 - _phi ** 2))
    z = rng.standard_normal((ns, n))
    x = np.empty((ns, n))
    x[:, 0] = vol * z[:, 0]
    for t in range(1, n):
        x[:, t] = _phi * x[:, t - 1] + vol * innov * z[:, t]
    prezzi = mu + x
    prezzi = np.maximum(prezzi, 0.01)  # floor: niente prezzi negativi qui

    if sig <= 0:
        forecast = prezzi.copy()
    else:
        forecast = prezzi + sig * rng.standard_normal((ns, n))

    t_star = np.argmin(forecast, axis=1)
    costo_forecast = prezzi[np.arange(ns), t_star]
    costo_perfect = prezzi.min(axis=1)  # EVPI
    risp_forecast = mu - costo_forecast
    risp_perfect = mu - costo_perfect

    evpi_mwh = float(risp_perfect.mean())
    val_mwh = float(risp_forecast.mean())
    pct_catturata = float(100.0 * val_mwh / evpi_mwh) if evpi_mwh > 1e-9 else 0.0

    # Curva valore-vs-sigma: riusa gli stessi prezzi veri, ricampiona solo
    # l'errore del forecast su una griglia di sigma (seed derivati -> stabile).
    griglia = np.array([0.0, 0.5, 1.0, 2.0, 3.0, 5.0, 8.0, 12.0, 20.0])
    griglia = griglia[griglia <= max(20.0, sig * 2.0)]
    valori = []
    for i, s in enumerate(griglia):
        r2 = np.random.default_rng(seed + 1000 + i)
        f2 = prezzi if s <= 0 else prezzi + s * r2.standard_normal((ns, n))
        t2 = np.argmin(f2, axis=1)
        valori.append(float((mu - prezzi[np.arange(ns), t2]).mean()))
    df_curva = pd.DataFrame({"sigma_forecast_eur_mwh": griglia,
                             "valore_atteso_eur_mwh": valori})

    p5, p50, p95 = np.percentile(risp_forecast, [5, 50, 95])

    return {
        "valido": True,
        "errore": "",
        "evpi_eur_mwh": evpi_mwh,
        "valore_forecast_eur_mwh": val_mwh,
        "valore_forecast_eur_tot": val_mwh * q,
        "evpi_eur_tot": evpi_mwh * q,
        "pct_evpi_catturata": pct_catturata,
        "costo_atteso_naive_eur_mwh": mu,
        "costo_atteso_forecast_eur_mwh": float(costo_forecast.mean()),
        "costo_atteso_perfect_eur_mwh": float(costo_perfect.mean()),
        "risparmio_p5_eur_mwh": float(p5),
        "risparmio_mediano_eur_mwh": float(p50),
        "risparmio_p95_eur_mwh": float(p95),
        "df_curva_sigma": df_curva,
        "df_risparmio": pd.DataFrame({"risparmio_eur_mwh": risp_forecast}),
        "n_giorni": n,
        "quantita_mwh": q,
    }


def calcola_oneri_generali(energia_mwh_annua, quota_fissa_eur_pod_anno,
                             quota_potenza_eur_kw_anno,
                             quota_energia_eur_mwh, potenza_kw,
                             n_pod=1, quota_asos_pct=85.0,
                             quote_mensili=None, energia_scenari=None):
    """Stima degli oneri generali di sistema per un prelievo in Italia (BT).

    Domanda operativa: "oltre la materia energia e il dispacciamento, quanto
    pesano gli oneri generali di sistema (ASOS + ARIM) in bolletta?" Voci
    (struttura TIT per la BT, delibera ARERA 654/2015/R/eel):
      - quota FISSA: euro/POD/anno;
      - quota POTENZA: euro/kW/anno sulla potenza impegnata;
      - quota ENERGIA: euro/MWh sull'energia prelevata.
    ASOS copre gli oneri generali del sistema elettrico (ex A3 e altri),
    ARIM i rimanenti oneri: si ripartisce ogni voce per quota_asos_pct
    (default 85%, indicativo -- varia con le delibere trimestrali ARERA).

    Formule:
      fissa   = n_pod x quota_fissa
      potenza = potenza_kw x quota_potenza
      energia = energia_mwh x quota_energia
      totale  = fissa + potenza + energia
      equivalente (€/MWh) = totale / energia

    Il mensile riparte la quota energia per quote_mensili (12 quote, default
    piatto) e fissa/potenza in dodicesimi. La sensitivita' ricalcola il
    totale al variare della quota energia (default: -30%/-15%/base/+15%/+30%).

    NaN-safe: parametri non numerici, energia <= 0, n_pod non intero >= 1,
    quota_asos_pct fuori [0,100], quote non 12/normalizzabili, scenari non
    validi -> errore pulito. Deterministico.

    Ritorna dict con 'errore', 'valido', 'verdetto', 'costo_quota_fissa',
    'costo_quota_potenza', 'costo_quota_energia', 'costo_totale_annuo',
    'quota_asos_eur', 'quota_arim_eur', 'equivalente_eur_mwh', 'quote_pct'
    (dict voce -> %), 'df_mensile', 'df_sensitivita'.
    """
    mesi = ["Gen", "Feb", "Mar", "Apr", "Mag", "Giu",
            "Lug", "Ago", "Set", "Ott", "Nov", "Dic"]
    col_m = ["Mese", "Energia (MWh)", "Quota fissa (\u20ac)",
             "Quota potenza (\u20ac)", "Quota energia (\u20ac)",
             "Totale (\u20ac)"]
    col_s = ["Scenario", "Quota energia (\u20ac/MWh)",
             "Totale annuo (\u20ac)", "Equivalente (\u20ac/MWh)"]
    vuoto = {"errore": None, "valido": False, "verdetto": None,
             "costo_quota_fissa": 0.0, "costo_quota_potenza": 0.0,
             "costo_quota_energia": 0.0, "costo_totale_annuo": 0.0,
             "quota_asos_eur": 0.0, "quota_arim_eur": 0.0,
             "equivalente_eur_mwh": 0.0,
             "quote_pct": {"quota_fissa": 0.0, "quota_potenza": 0.0,
                           "quota_energia": 0.0},
             "df_mensile": pd.DataFrame(columns=col_m),
             "df_sensitivita": pd.DataFrame(columns=col_s)}

    def _err(msg):
        out = dict(vuoto)
        out["df_mensile"] = pd.DataFrame(columns=col_m)
        out["df_sensitivita"] = pd.DataFrame(columns=col_s)
        out["errore"] = msg
        return out

    def _num(x, nome):
        if isinstance(x, bool):
            raise ValueError(nome)
        v = float(x)
        if not np.isfinite(v):
            raise ValueError(nome)
        return v

    try:
        en = _num(energia_mwh_annua, "energia")
        qf = _num(quota_fissa_eur_pod_anno, "quota_fissa")
        qp = _num(quota_potenza_eur_kw_anno, "quota_potenza")
        qe = _num(quota_energia_eur_mwh, "quota_energia")
        pk = _num(potenza_kw, "potenza")
        ap = _num(quota_asos_pct, "quota_asos")
        if isinstance(n_pod, bool):
            raise ValueError("n_pod")
        npod = int(n_pod)
        if npod != n_pod or npod < 1:
            raise ValueError("n_pod")
        if en <= 0:
            raise ValueError("energia")
        if qf < 0 or qp < 0 or qe < 0 or pk < 0:
            raise ValueError("negativi")
        if ap < 0 or ap > 100:
            raise ValueError("asos")
        quote = None
        if quote_mensili is not None:
            quote = [_num(q, "quota") for q in quote_mensili]
            if len(quote) != 12:
                raise ValueError("quote_len")
            if any(q < 0 for q in quote) or sum(quote) <= 0:
                raise ValueError("quote_sum")
        scenari = None
        if energia_scenari is not None:
            scenari = [(str(lbl), _num(v, "scen")) for lbl, v in energia_scenari]
            if not scenari:
                raise ValueError("scenari")
    except (ValueError, TypeError):
        return _err("Parametri non validi: controlla valori numerici "
                    "(energia > 0, quote >= 0, n_pod intero >= 1, "
                    "quota ASOS 0-100%).")

    if quote is None:
        quote = [1.0 / 12.0] * 12
    else:
        tot_q = sum(quote)
        quote = [q / tot_q for q in quote]
    if scenari is None:
        scenari = [("-30%", qe * 0.70), ("-15%", qe * 0.85),
                   ("base", qe), ("+15%", qe * 1.15), ("+30%", qe * 1.30)]

    c_fissa = npod * qf
    c_pot = pk * qp
    c_en = en * qe
    totale = c_fissa + c_pot + c_en
    eq = totale / en
    c_asos = totale * ap / 100.0
    c_arim = totale - c_asos
    pct = {}
    for k, v in (("quota_fissa", c_fissa), ("quota_potenza", c_pot),
                 ("quota_energia", c_en)):
        pct[k] = (v / totale * 100.0) if totale > 0 else 0.0

    if eq < 10.0:
        verdetto = "TRASCURABILI: gli oneri generali incidono meno di 10 €/MWh."
    elif eq < 25.0:
        verdetto = "MODERATI: gli oneri generali valgono %.1f €/MWh -- voce da confrontare tra offerte." % eq
    else:
        verdetto = "RILEVANTI: %.1f €/MWh di oneri generali -- pesano piu' di molti spread di fornitura." % eq

    righe_m = []
    for i, m in enumerate(mesi):
        en_m = en * quote[i]
        qf_m = c_fissa / 12.0
        qp_m = c_pot / 12.0
        qe_m = en_m * qe
        righe_m.append((m, round(en_m, 1), round(qf_m, 2), round(qp_m, 2),
                        round(qe_m, 2), round(qf_m + qp_m + qe_m, 2)))
    df_m = pd.DataFrame(righe_m, columns=col_m)

    righe_s = []
    for lbl, qes in scenari:
        t = c_fissa + c_pot + en * qes
        righe_s.append((lbl, round(qes, 2), round(t, 2),
                        round(t / en, 3)))
    df_s = pd.DataFrame(righe_s, columns=col_s)

    out = dict(vuoto)
    out.update({
        "errore": None, "valido": True, "verdetto": verdetto,
        "costo_quota_fissa": c_fissa, "costo_quota_potenza": c_pot,
        "costo_quota_energia": c_en, "costo_totale_annuo": totale,
        "quota_asos_eur": c_asos, "quota_arim_eur": c_arim,
        "equivalente_eur_mwh": eq, "quote_pct": pct,
        "df_mensile": df_m, "df_sensitivita": df_s,
    })
    return out


def calcola_oneri_dispacciamento(energia_mwh_annua, uplift_eur_mwh,
                                 quota_fissa_eur_pod_anno,
                                 quota_potenza_eur_kw_anno, potenza_kw,
                                 n_pod=1, quote_mensili=None,
                                 uplift_scenari=None):
    """Stima degli oneri di dispacciamento per un prelievo in Italia.

    Domanda operativa: "quanto pesano in bolletta gli oneri di
    dispacciamento (Terna/ARERA) oltre la materia energia?" Voci:
      - UPLIFT: corrispettivo a copertura dei costi di approvvigionamento
        delle risorse nel mercato per il servizio di dispacciamento (MSD),
        addebitato in euro/MWh sull'energia prelevata (valore mensile
        pubblicato da Terna, variabile);
      - quota FISSA: euro/POD/anno (componente fissa del corrispettivo di
        dispacciamento per la BT);
      - quota POTENZA: euro/kW/anno sulla potenza impegnata.

    Formule:
      uplift = energia x uplift_eur_mwh
      fissa  = n_pod x quota_fissa_eur_pod_anno
      potenza = potenza_kw x quota_potenza_eur_kw_anno
      totale = uplift + fissa + potenza
      equivalente (€/MWh) = totale / energia

    Il mensile riparte l'uplift per quote_mensili (12 quote, default
    piatto) e fissa/potenza in dodicesimi. La sensitivita' ricalcola il
    totale al variare dell'uplift (default: -50%/-25%/base/+25%/+50%).

    NaN-safe: parametri non numerici, negativi (energia <= 0), n_pod non
    intero >= 1, quote non 12/normalizzabili, scenari non validi -> errore
    pulito. Deterministico.

    Ritorna dict con 'errore', 'valido', 'verdetto', 'costo_uplift',
    'costo_quota_fissa', 'costo_quota_potenza', 'costo_totale_annuo',
    'equivalente_eur_mwh', 'quote_pct' (dict voce -> %), 'df_mensile'
    (Mese, Energia (MWh), Uplift (€), Quota fissa (€), Quota potenza (€),
    Totale (€)), 'df_sensitivita' (Scenario, Uplift (€/MWh),
    Totale annuo (€), Equivalente (€/MWh)).
    """
    mesi = ["Gen", "Feb", "Mar", "Apr", "Mag", "Giu",
            "Lug", "Ago", "Set", "Ott", "Nov", "Dic"]
    col_m = ["Mese", "Energia (MWh)", "Uplift (\u20ac)",
             "Quota fissa (\u20ac)", "Quota potenza (\u20ac)", "Totale (\u20ac)"]
    col_s = ["Scenario", "Uplift (\u20ac/MWh)", "Totale annuo (\u20ac)",
             "Equivalente (\u20ac/MWh)"]
    vuoto = {"errore": None, "valido": False, "verdetto": None,
             "costo_uplift": 0.0, "costo_quota_fissa": 0.0,
             "costo_quota_potenza": 0.0, "costo_totale_annuo": 0.0,
             "equivalente_eur_mwh": 0.0,
             "quote_pct": {"uplift": 0.0, "quota_fissa": 0.0,
                           "quota_potenza": 0.0},
             "df_mensile": pd.DataFrame(columns=col_m),
             "df_sensitivita": pd.DataFrame(columns=col_s)}

    def _err(msg):
        out = dict(vuoto)
        out["df_mensile"] = pd.DataFrame(columns=col_m)
        out["df_sensitivita"] = pd.DataFrame(columns=col_s)
        out["errore"] = msg
        return out

    def _num(x, nome):
        if isinstance(x, bool):
            raise ValueError(nome)
        v = float(x)
        if not np.isfinite(v):
            raise ValueError(nome)
        return v

    try:
        en = _num(energia_mwh_annua, "energia")
        up = _num(uplift_eur_mwh, "uplift")
        qf = _num(quota_fissa_eur_pod_anno, "quota_fissa")
        qp = _num(quota_potenza_eur_kw_anno, "quota_potenza")
        pk = _num(potenza_kw, "potenza")
        if isinstance(n_pod, bool):
            raise ValueError("n_pod")
        npod = int(n_pod)
        if npod != n_pod:
            raise ValueError("n_pod")
        quote = None
        if quote_mensili is not None:
            quote = [_num(q, "quota") for q in quote_mensili]
            if len(quote) != 12:
                raise ValueError("quote_len")
            if any(q < 0 for q in quote) or sum(quote) <= 0:
                raise ValueError("quote_sum")
        scenari = None
        if uplift_scenari is not None:
            scenari = [_num(s, "scenario") for s in uplift_scenari]
            if not scenari or any(s < 0 for s in scenari):
                raise ValueError("scenari")
    except (TypeError, ValueError):
        return _err("Parametri non validi: numeri finiti >= 0; energia > 0; "
                    "n_pod intero >= 1; 12 quote mensili >= 0 con somma > 0.")
    if en <= 0:
        return _err("Parametri non validi: energia annua > 0.")
    if up < 0:
        return _err("Parametri non validi: uplift >= 0.")
    if qf < 0:
        return _err("Parametri non validi: quota fissa >= 0.")
    if qp < 0:
        return _err("Parametri non validi: quota potenza >= 0.")
    if pk < 0:
        return _err("Parametri non validi: potenza >= 0.")
    if npod < 1:
        return _err("Parametri non validi: n_pod >= 1.")

    c_uplift = en * up
    c_fissa = npod * qf
    c_potenza = pk * qp
    totale = c_uplift + c_fissa + c_potenza
    eq = totale / en
    if totale > 0:
        qpct = {"uplift": c_uplift / totale * 100.0,
                "quota_fissa": c_fissa / totale * 100.0,
                "quota_potenza": c_potenza / totale * 100.0}
    else:
        qpct = {"uplift": 0.0, "quota_fissa": 0.0, "quota_potenza": 0.0}

    if quote is None:
        quote = [1.0 / 12.0] * 12
    else:
        s = sum(quote)
        quote = [q / s for q in quote]
    righe_m = []
    for i in range(12):
        en_m = en * quote[i]
        up_m = en_m * up
        qf_m = c_fissa / 12.0
        qp_m = c_potenza / 12.0
        righe_m.append({"Mese": mesi[i],
                        "Energia (MWh)": round(en_m, 2),
                        "Uplift (\u20ac)": round(up_m, 2),
                        "Quota fissa (\u20ac)": round(qf_m, 2),
                        "Quota potenza (\u20ac)": round(qp_m, 2),
                        "Totale (\u20ac)": round(up_m + qf_m + qp_m, 2)})
    df_m = pd.DataFrame(righe_m, columns=col_m)

    if scenari is None:
        fattori = [0.50, 0.75, 1.00, 1.25, 1.50]
        etichette = ["Uplift -50%", "Uplift -25%", "Uplift base",
                     "Uplift +25%", "Uplift +50%"]
        scenari = [up * f for f in fattori]
    else:
        etichette = ["Scenario %d (%.2f \u20ac/MWh)" % (i + 1, s)
                     for i, s in enumerate(scenari)]
    righe_s = []
    for lab, up_s in zip(etichette, scenari):
        tot_s = en * up_s + c_fissa + c_potenza
        righe_s.append({"Scenario": lab,
                        "Uplift (\u20ac/MWh)": round(up_s, 2),
                        "Totale annuo (\u20ac)": round(tot_s, 2),
                        "Equivalente (\u20ac/MWh)": round(tot_s / en, 3)})
    df_s = pd.DataFrame(righe_s, columns=col_s)

    if eq < 2.5:
        verdetto = "\U0001F7E2 ONERI TRASCURABILI (<2,50 \u20ac/MWh)"
    elif eq < 5.0:
        verdetto = "\U0001F7E1 ONERI MODERATI (<5,00 \u20ac/MWh)"
    elif eq < 8.0:
        verdetto = "\U0001F7E0 ONERI RILEVANTI (<8,00 \u20ac/MWh)"
    else:
        verdetto = "\U0001F534 ONERI SIGNIFICATIVI (>=8,00 \u20ac/MWh)"

    return {"errore": None, "valido": True, "verdetto": verdetto,
            "costo_uplift": c_uplift, "costo_quota_fissa": c_fissa,
            "costo_quota_potenza": c_potenza, "costo_totale_annuo": totale,
            "equivalente_eur_mwh": eq, "quote_pct": qpct,
            "df_mensile": df_m, "df_sensitivita": df_s}


def calcola_radar_scadenze(df_contratti, prezzo_mercato_eur_mwh,
                           data_rif=None, orizzonte_mesi=6):
    """Radar scadenze contratti di fornitura.

    df_contratti: DataFrame con colonne Fornitore (str), Inizio/Fine
    (date), Volume_MWh_anno (>0), Prezzo_EUR_MWh (>0 se Tipo=Fisso),
    Tipo ("Fisso"/"Indicizzato", case-insensitive).
    prezzo_mercato_eur_mwh: prezzo di riferimento (€/MWh) per stimare il
    costo di repricing del volume che torna esposto (es. media spot
    recente o quotazione forward del periodo di rinnovo).
    data_rif: data di valutazione (default: oggi). orizzonte_mesi: 1-24.
    Ritorna dict con 'errore' (None se ok); mai eccezioni.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        cols = ["Fornitore", "Inizio", "Fine", "Volume_MWh_anno",
                "Prezzo_EUR_MWh", "Tipo"]
        if not isinstance(df_contratti, pd.DataFrame) or df_contratti.empty:
            return _err("Tabella contratti mancante o vuota.")
        manc = [c for c in cols if c not in df_contratti.columns]
        if manc:
            return _err("Colonne mancanti: %s." % ", ".join(manc))
        df = df_contratti[cols].copy()

        if data_rif is None:
            rif = pd.Timestamp.today().normalize()
        else:
            rif = pd.to_datetime(data_rif, errors="coerce")
            if pd.isna(rif):
                return _err("Data di riferimento non valida.")
            rif = pd.Timestamp(rif).normalize()
        if rif.tzinfo is not None:
            rif = rif.tz_localize(None)

        if isinstance(orizzonte_mesi, bool) or not isinstance(
                orizzonte_mesi, (int, np.integer)):
            return _err("Orizzonte non valido (1-24 mesi).")
        orizzonte_mesi = int(orizzonte_mesi)
        if not (1 <= orizzonte_mesi <= 24):
            return _err("Orizzonte fuori intervallo [1, 24] mesi.")

        pm = prezzo_mercato_eur_mwh
        if (isinstance(pm, bool) or not isinstance(pm, (int, float))
                or not np.isfinite(pm) or pm <= 0):
            return _err("Prezzo di mercato non valido (> 0 €/MWh).")
        pm = float(pm)

        forn = df["Fornitore"].astype(str).str.strip()
        if (forn == "").any() or forn.isna().any():
            return _err("Fornitore mancante in una o piu' righe.")

        def _naive(s):
            s = pd.to_datetime(s, errors="coerce")
            try:
                if s.dt.tz is not None:
                    s = s.dt.tz_localize(None)
            except (TypeError, AttributeError):
                pass
            return s.dt.normalize()

        ini = _naive(df["Inizio"])
        fin = _naive(df["Fine"])
        if ini.isna().any() or fin.isna().any():
            return _err("Date Inizio/Fine non valide in una o piu' righe.")
        if (fin < ini).any():
            return _err("Fine precedente a Inizio in una o piu' righe.")

        vol = pd.to_numeric(df["Volume_MWh_anno"], errors="coerce")
        if vol.isna().any() or (vol <= 0).any():
            return _err("Volume_MWh_anno non valido (deve essere > 0).")

        tipo = df["Tipo"].astype(str).str.strip().str.lower()
        if (~tipo.isin(["fisso", "indicizzato"])).any():
            return _err("Tipo non valido (usare Fisso o Indicizzato).")

        prezzo = pd.to_numeric(df["Prezzo_EUR_MWh"], errors="coerce")
        m_fisso = tipo == "fisso"
        if prezzo[m_fisso].isna().any() or (prezzo[m_fisso] <= 0).any():
            return _err("Prezzo_EUR_MWh non valido per i contratti Fisso "
                        "(deve essere > 0).")
        prezzo = prezzo.where(m_fisso, np.nan)

        giorni = (fin - rif).dt.days

        condizioni = [giorni < 0, giorni <= 90, giorni <= 180,
                      giorni <= 365]
        classi = ["⛔ Scaduto", "🔴 Critico",
                  "🟡 Attenzione", "🔵 Monitoraggio"]
        classe = np.select(condizioni, classi,
                           default="🟢 Tranquillo")

        limite = rif + pd.DateOffset(months=orizzonte_mesi)
        esposto = fin <= limite
        repricing = np.where(m_fisso & esposto, vol * (pm - prezzo), 0.0)

        n = len(df)
        n_scaduti = int((giorni < 0).sum())
        n_critici = int(((giorni >= 0) & (giorni <= 90)).sum())
        vol_tot = float(vol.sum())
        vol_esp = float(vol[esposto].sum())
        quota_esp = 100.0 * vol_esp / vol_tot
        repr_tot = float(np.sum(repricing))

        trim_picco = quota_picco = None
        df_trim = None
        m_att = fin >= rif
        if m_att.any():
            tq = fin[m_att].dt.to_period("Q")
            g = vol[m_att].groupby(tq.values).sum()
            vol_att = float(vol[m_att].sum())
            df_trim = pd.DataFrame({
                "Trimestre": [str(p) for p in g.index],
                "Volume (MWh/anno)": g.values,
                "Quota volume (%)": 100.0 * g.values / vol_att})
            df_trim = df_trim.sort_values("Trimestre").reset_index(drop=True)
            i_max = int(df_trim["Quota volume (%)"].idxmax())
            trim_picco = df_trim.loc[i_max, "Trimestre"]
            quota_picco = float(df_trim.loc[i_max, "Quota volume (%)"])

        if n_scaduti > 0:
            verdetto = ("⛔ CONTRATTI SCADUTI — %d contratto/i gia' scaduto/i: "
                        "il volume e' esposto al mercato, rinegozia subito."
                        % n_scaduti)
        elif repr_tot > 0:
            verdetto = ("🔴 RIPREZZAMENTO IN VISTA — rinnovare il volume "
                        "esposto al prezzo di mercato costerebbe circa "
                        "%.0f €/anno in piu' rispetto ai prezzi fissi "
                        "attuali." % repr_tot)
        elif n_critici > 0:
            verdetto = ("🟡 SCADENZE RAVVICINATE — %d contratto/i scade/scadono "
                        "entro 90 giorni: avvia la trattativa di rinnovo."
                        % n_critici)
        elif quota_picco is not None and quota_picco >= 50.0:
            verdetto = ("🟡 CONCENTRAZIONE SCADENZE — il %.0f%% del volume "
                        "scade nel %s: rischio di rinegoziare tutto insieme."
                        % (quota_picco, trim_picco))
        else:
            verdetto = ("🟢 SOTTO CONTROLLO — nessuna scadenza critica "
                        "nell'orizzonte.")

        df_det = pd.DataFrame({
            "Fornitore": forn.values,
            "Tipo": tipo.str.capitalize().values,
            "Inizio": ini.dt.strftime("%Y-%m-%d"),
            "Fine": fin.dt.strftime("%Y-%m-%d"),
            "Giorni rimanenti": giorni.values,
            "Classe": classe,
            "Volume (MWh/anno)": vol.values,
            "Prezzo (€/MWh)": np.where(m_fisso, prezzo.values, np.nan),
            "Repricing stimato (€/anno)": repricing})

        return {"errore": None, "valido": True, "n_contratti": n,
                "n_scaduti": n_scaduti, "n_critici": n_critici,
                "volume_totale": vol_tot, "volume_esposto": vol_esp,
                "quota_esposta_pct": quota_esp,
                "repricing_totale": repr_tot,
                "trimestre_picco": trim_picco,
                "quota_picco_pct": quota_picco,
                "df_dettaglio": df_det, "df_trimestri": df_trim,
                "data_rif": rif, "orizzonte_mesi": orizzonte_mesi,
                "verdetto": verdetto}
    except Exception as e:  # pragma: no cover - guardia totale
        return {"errore": "Errore interno: %s" % e, "valido": False}

def calcola_concentrazione_controparte(df_contratti, prezzo_mercato_eur_mwh,
                                        data_rif=None):
    """Concentrazione del rischio controparte nel portafoglio contratti.

    df_contratti: stesso schema della tab radar scadenze (Fornitore,
    Inizio, Fine, Volume_MWh_anno, Prezzo_EUR_MWh, Tipo Fisso/Indicizzato).
    Si considerano solo i contratti ATTIVI (Fine >= data_rif).
    prezzo_mercato_eur_mwh: prezzo di mercato (> 0) per stimare il MtM dei
    contratti a prezzo fisso. data_rif: data di valutazione (default oggi).
    Per controparte: volume annuo aggregato, quota %, MtM sul volume
    residuo (vol_residuo x (mercato - prezzo fisso); 0 per gli indicizzati)
    ed esposizione positiva = max(MtM, 0) = costo di sostituzione se la
    controparte fallisce quando il mercato e' sopra il prezzo fissato.
    Indice HHI sulle quote volume (bande: <1500 bassa, 1500-2500 moderata,
    >2500 alta concentrazione); alert quota top > 50% critica, > 30% warning.
    Ritorna dict con 'errore' (None se ok); mai eccezioni.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        cols = ["Fornitore", "Inizio", "Fine", "Volume_MWh_anno",
                "Prezzo_EUR_MWh", "Tipo"]
        if not isinstance(df_contratti, pd.DataFrame) or df_contratti.empty:
            return _err("Tabella contratti mancante o vuota.")
        manc = [c for c in cols if c not in df_contratti.columns]
        if manc:
            return _err("Colonne mancanti: %s." % ", ".join(manc))

        if data_rif is None:
            rif = pd.Timestamp.today().normalize()
        else:
            rif = pd.to_datetime(data_rif, errors="coerce")
            if pd.isna(rif):
                return _err("Data di riferimento non valida.")
            rif = pd.Timestamp(rif).normalize()
        if rif.tzinfo is not None:
            rif = rif.tz_localize(None)

        pm = prezzo_mercato_eur_mwh
        if (isinstance(pm, bool) or not isinstance(pm, (int, float))
                or not np.isfinite(pm) or pm <= 0):
            return _err("Prezzo di mercato non valido (> 0 EUR/MWh).")
        pm = float(pm)

        df = df_contratti[cols].copy()
        forn = df["Fornitore"].astype(str).str.strip()
        if (forn == "").any() or forn.isna().any():
            return _err("Fornitore mancante in una o piu' righe.")

        def _naive(s):
            s = pd.to_datetime(s, errors="coerce")
            try:
                if s.dt.tz is not None:
                    s = s.dt.tz_localize(None)
            except (TypeError, AttributeError):
                pass
            return s.dt.normalize()

        ini = _naive(df["Inizio"])
        fin = _naive(df["Fine"])
        if ini.isna().any() or fin.isna().any():
            return _err("Date Inizio/Fine non valide in una o piu' righe.")
        if (fin < ini).any():
            return _err("Fine precedente a Inizio in una o piu' righe.")

        vol = pd.to_numeric(df["Volume_MWh_anno"], errors="coerce")
        if vol.isna().any() or (vol <= 0).any():
            return _err("Volume_MWh_anno non valido (deve essere > 0).")

        tipo = df["Tipo"].astype(str).str.strip().str.lower()
        if (~tipo.isin(["fisso", "indicizzato"])).any():
            return _err("Tipo non valido (usare Fisso o Indicizzato).")
        m_fisso = tipo == "fisso"

        prezzo = pd.to_numeric(df["Prezzo_EUR_MWh"], errors="coerce")
        if prezzo[m_fisso].isna().any() or (prezzo[m_fisso] <= 0).any():
            return _err("Prezzo_EUR_MWh non valido per i contratti Fisso "
                        "(deve essere > 0).")

        attivi = fin >= rif
        if not attivi.any():
            return _err("Nessun contratto attivo alla data di riferimento.")
        forn_a = forn[attivi]
        vol_a = vol[attivi]
        prezzo_a = prezzo[attivi]
        fisso_a = m_fisso[attivi]
        fin_a = fin[attivi]

        # Volume residuo pro-rata sui prossimi 12 mesi (cap 365 giorni).
        giorni_res = (fin_a - rif).dt.days.clip(lower=0)
        vol_res = vol_a * np.minimum(giorni_res, 365) / 365.0
        mtm = np.where(fisso_a, vol_res * (pm - prezzo_a), 0.0)
        esposizione = np.maximum(mtm, 0.0)

        agg = pd.DataFrame({"Fornitore": forn_a.values,
                            "Volume (MWh/anno)": vol_a.values,
                            "Volume residuo (MWh)": vol_res.values,
                            "MtM (€)": mtm,
                            "Esposizione (€)": esposizione})
        g = agg.groupby("Fornitore", as_index=False).agg(
            {"Volume (MWh/anno)": "sum",
             "Volume residuo (MWh)": "sum",
             "MtM (€)": "sum",
             "Esposizione (€)": "sum"})
        conteggi = agg.groupby("Fornitore").size()
        g["Contratti"] = g["Fornitore"].map(conteggi).astype(int).values
        vol_tot = float(g["Volume (MWh/anno)"].sum())
        g["Quota volume (%)"] = 100.0 * g["Volume (MWh/anno)"] / vol_tot
        g = g.sort_values("Quota volume (%)", ascending=False).reset_index(
            drop=True)
        g = g[["Fornitore", "Contratti", "Volume (MWh/anno)",
               "Quota volume (%)", "Volume residuo (MWh)", "MtM (€)",
               "Esposizione (€)"]]

        quote = g["Quota volume (%)"].to_numpy()
        hhi = float(np.sum(quote ** 2))
        cr1 = float(quote[0])
        cr2 = float(quote[:2].sum())
        esp_tot = float(g["Esposizione (€)"].sum())
        mtm_tot = float(g["MtM (€)"].sum())
        n_cp = int(len(g))

        if cr1 > 50.0:
            verdetto = ("🔴 CONCENTRAZIONE CRITICA: la prima controparte "
                        "(%s) copre il %.1f%% del volume annuo attivo: "
                        "se fallisce o rinegozia, meta' della fornitura e' "
                        "a rischio. Riduci la quota sotto il 50%% "
                        "diversificando su nuovi fornitori."
                        % (g.loc[0, "Fornitore"], cr1))
        elif cr1 > 30.0:
            verdetto = ("🟡 Concentrazione ELEVATA: %s copre il %.1f%% del "
                        "volume (soglia di attenzione 30%%). Valuta di "
                        "spostare parte del volume su altre controparti."
                        % (g.loc[0, "Fornitore"], cr1))
        elif hhi > 2500.0:
            verdetto = ("🟡 HHI alto (%.0f): il portafoglio e' concentrato "
                        "su poche controparti anche se nessuna supera il "
                        "30%%. Monitora le esposizioni positive."
                        % hhi)
        else:
            verdetto = ("🟢 Portafoglio diversificato: HHI %.0f, prima "
                        "controparte al %.1f%%. Nessun alert di "
                        "concentrazione." % (hhi, cr1))

        classe_hhi = ("Alta concentrazione" if hhi > 2500.0
                      else "Moderata" if hhi > 1500.0 else "Bassa")

        return {"errore": None, "valido": True, "n_controparti": n_cp,
                "n_contratti_attivi": int(attivi.sum()),
                "volume_totale": vol_tot, "hhi": hhi,
                "classe_hhi": classe_hhi, "cr1_pct": cr1, "cr2_pct": cr2,
                "mtm_totale": mtm_tot, "esposizione_totale": esp_tot,
                "df_controparti": g, "data_rif": rif,
                "verdetto": verdetto}
    except Exception as e:  # pragma: no cover - guardia totale
        return {"errore": "Errore interno: %s" % e, "valido": False}


def calcola_costo_liquidazione(df_posizioni, spread_bps=10.0,
                               partecipazione_max=0.2, giorni_max=10,
                               fattore_impatto=1.0):
    """Costo stimato di liquidazione delle posizioni forward.

    df_posizioni: colonne Prodotto, MW (segno = direzione long/short, il
    volume usa |MW|), Ore (ore di consegna, es. 744 per un mese base),
    Prezzo_EUR_MWh (mid di riferimento), Vol_medio_giornaliero_MWh (volume
    medio scambiato al giorno su quel prodotto).
    spread_bps: bid-ask spread in bps; partecipazione_max: quota max del
    volume giornaliero che si e' disposti a prendere (0,1]; giorni_max:
    orizzonte entro cui chiudere; fattore_impatto: moltiplicatore
    dell'impatto di mercato rispetto allo spread.

    Per riga: volume = |MW|*Ore; nozionale = volume*prezzo;
    costo_spread = volume*prezzo*spread_bps/20000 (attraversare meta' spread);
    giorni_necessari = ceil(volume/(partecipazione_max*vol_medio));
    partecipazione_media = volume/(giorni_necessari*vol_medio) (<= max);
    impatto_bps = spread_bps*fattore_impatto*(partecipazione_media/
    partecipazione_max); costo_impatto = volume*prezzo*impatto_bps/10000;
    costo_totale = spread + impatto; costo_per_MWh = costo_totale/volume.
    Alert: giorni_necessari > giorni_max -> 'FUORI TEMPO'.
    Verdetto: CRITICO se posizioni fuori tempo; ELEVATO se costo > 1%
    del nozionale; altrimenti CONTENUTO.
    Ritorna dict con 'errore' (None se ok), 'valido', df_dettaglio e
    aggregati; mai eccezioni.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        cols = ["Prodotto", "MW", "Ore", "Prezzo_EUR_MWh",
                "Vol_medio_giornaliero_MWh"]
        if not isinstance(df_posizioni, pd.DataFrame) or df_posizioni.empty:
            return _err("Tabella posizioni mancante o vuota.")
        manc = [c for c in cols if c not in df_posizioni.columns]
        if manc:
            return _err("Colonne mancanti: %s." % ", ".join(manc))

        def _num_ok(x, cond):
            if isinstance(x, bool) or not isinstance(x, (int, float)):
                return False
            if not np.isfinite(x):
                return False
            return cond(x)

        if not _num_ok(spread_bps, lambda v: v >= 0):
            return _err("spread_bps non valido (deve essere >= 0).")
        if not _num_ok(partecipazione_max, lambda v: 0 < v <= 1):
            return _err("partecipazione_max non valida (0 < p <= 1).")
        if not _num_ok(giorni_max, lambda v: v >= 1):
            return _err("giorni_max non valido (deve essere >= 1).")
        if not _num_ok(fattore_impatto, lambda v: v >= 0):
            return _err("fattore_impatto non valido (deve essere >= 0).")
        spread_bps = float(spread_bps)
        partecipazione_max = float(partecipazione_max)
        giorni_max = int(giorni_max)
        fattore_impatto = float(fattore_impatto)

        df = df_posizioni[cols].copy()
        prod = df["Prodotto"].astype(str).str.strip()
        if (prod == "").any() or prod.isna().any():
            return _err("Prodotto mancante in una o piu' righe.")
        mw = pd.to_numeric(df["MW"], errors="coerce")
        if mw.isna().any() or (mw == 0).any():
            return _err("MW non valido (deve essere != 0).")
        ore = pd.to_numeric(df["Ore"], errors="coerce")
        if ore.isna().any() or (ore <= 0).any():
            return _err("Ore non valide (devono essere > 0).")
        prezzo = pd.to_numeric(df["Prezzo_EUR_MWh"], errors="coerce")
        if prezzo.isna().any() or (prezzo <= 0).any():
            return _err("Prezzo_EUR_MWh non valido (deve essere > 0).")
        volm = pd.to_numeric(df["Vol_medio_giornaliero_MWh"],
                             errors="coerce")
        if volm.isna().any() or (volm <= 0).any():
            return _err("Vol_medio_giornaliero_MWh non valido "
                        "(deve essere > 0).")

        vol = mw.abs() * ore
        noz = vol * prezzo
        costo_spread = noz * (spread_bps / 20000.0)
        capacita_gg = partecipazione_max * volm
        giorni_nec = np.ceil(vol / capacita_gg).astype(int)
        giorni_nec = np.maximum(giorni_nec, 1)
        part_media = vol / (giorni_nec * volm)
        impatto_bps = (spread_bps * fattore_impatto
                       * (part_media / partecipazione_max))
        costo_impatto = noz * (impatto_bps / 10000.0)
        costo_tot = costo_spread + costo_impatto
        costo_mwh = costo_tot / vol
        fuori = giorni_nec > giorni_max

        g = pd.DataFrame({
            "Prodotto": prod,
            "Direzione": np.where(mw > 0, "Long", "Short"),
            "Volume (MWh)": np.round(vol, 1),
            "Nozionale (EUR)": np.round(noz, 2),
            "Costo spread (EUR)": np.round(costo_spread, 2),
            "Impatto (bps)": np.round(impatto_bps, 2),
            "Costo impatto (EUR)": np.round(costo_impatto, 2),
            "Costo totale (EUR)": np.round(costo_tot, 2),
            "Costo (EUR/MWh)": np.round(costo_mwh, 4),
            "Giorni necessari": giorni_nec,
            "Stato": np.where(fuori, "FUORI TEMPO", "OK")})

        costo_totale = float(costo_tot.sum())
        nozionale_totale = float(noz.sum())
        volume_totale = float(vol.sum())
        pct = (100.0 * costo_totale / nozionale_totale
               if nozionale_totale > 0 else None)
        n_fuori = int(fuori.sum())
        if n_fuori > 0:
            verdetto = ("CRITICO: %d posizione/i non liquidabile/i entro %d "
                        "giorni con partecipazione <= %.0f%% — ridurre la "
                        "taglia o allungare l'orizzonte."
                        % (n_fuori, giorni_max, partecipazione_max * 100))
        elif pct is not None and pct > 1.0:
            verdetto = ("ELEVATO: il costo di liquidazione supera l'1%% del "
                        "nozionale (%.2f%%) — spread o impatto alti rispetto "
                        "alla liquidita'." % pct)
        else:
            verdetto = ("CONTENUTO: costo di liquidazione %.2f%% del "
                        "nozionale, tutte le posizioni liquidabili entro "
                        "%d giorni." % (pct if pct is not None else 0.0,
                                        giorni_max))

        return {"errore": None, "valido": True,
                "n_posizioni": len(g),
                "volume_totale": volume_totale,
                "nozionale_totale": nozionale_totale,
                "costo_totale": costo_totale,
                "costo_medio_mwh": (costo_totale / volume_totale
                                    if volume_totale > 0 else None),
                "costo_pct_nozionale": pct,
                "giorni_max_riga": int(giorni_nec.max()),
                "n_fuori_tempo": n_fuori,
                "df_dettaglio": g, "verdetto": verdetto}
    except Exception as e:  # pragma: no cover - guardia totale
        return {"errore": "Errore interno: %s" % e, "valido": False}


def calcola_debt_sizing(potenza_mw, ore_eq, prezzo_catturato, capex_eur_kw,
                        opex_eur_kw_anno, degrado_pct, tasso_pct,
                        durata_anni, dscr_target, vita_anni):
    """Dimensionamento del debito project-finance con debt service sculpted.

    Debt service annuo = CFADS_anno / dscr_target (sculpting a DSCR costante);
    debito massimo = valore attuale del debt service al tasso del debito.
    Funzione pura: nessun accesso a Streamlit.
    """
    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _ko(msg):
        return {"errore": msg, "valido": False}

    def _irr(flussi, lo=-0.9999, hi=5.0, tol=1e-7, it=200):
        def _npv(t):
            s = 0.0
            d = 1.0
            for c in flussi:
                s += c / d
                d *= (1.0 + t)
            return s
        vlo, vhi = _npv(lo), _npv(hi)
        if vlo == 0.0:
            return lo
        if vhi == 0.0:
            return hi
        if vlo * vhi > 0:
            return None
        for _ in range(it):
            mid = 0.5 * (lo + hi)
            vm = _npv(mid)
            if abs(vm) < tol:
                return mid
            if vlo * vm <= 0:
                hi, vhi = mid, vm
            else:
                lo, vlo = mid, vm
        return 0.5 * (lo + hi)

    p = _num(potenza_mw); ore = _num(ore_eq); prz = _num(prezzo_catturato)
    ck = _num(capex_eur_kw); ok = _num(opex_eur_kw_anno); dg = _num(degrado_pct)
    r = _num(tasso_pct); dur = _num(durata_anni)
    dscr_t = _num(dscr_target); vita = _num(vita_anni)
    if None in (p, ore, prz, ck, ok, dg, r, dur, dscr_t, vita):
        return _ko("Tutti i parametri devono essere numerici.")
    if p <= 0:
        return _ko("La potenza deve essere > 0 MW.")
    if ore <= 0:
        return _ko("Le ore equivalenti devono essere > 0.")
    if prz <= 0:
        return _ko("Il prezzo catturato deve essere > 0 EUR/MWh.")
    if ck <= 0:
        return _ko("Il CAPEX deve essere > 0 EUR/kW.")
    if ok < 0:
        return _ko("L'OPEX non puo' essere negativo.")
    if not 0.0 <= dg < 100.0:
        return _ko("Il degrado deve essere tra 0 (incluso) e 100 (escluso) %/anno.")
    if r < 0:
        return _ko("Il tasso del debito non puo' essere negativo.")
    if dur < 1:
        return _ko("La durata del debito deve essere >= 1 anno.")
    if dscr_t < 1.0:
        return _ko("Il DSCR target deve essere >= 1.0.")
    if vita < 1:
        return _ko("La vita del progetto deve essere >= 1 anno.")
    dur = int(round(dur)); vita = int(round(vita))
    tenor = min(dur, vita)

    capex = p * 1000.0 * ck
    opex = p * 1000.0 * ok
    energia = [p * ore * (1.0 - dg / 100.0) ** (y - 1)
               for y in range(1, vita + 1)]
    ricavi = [e * prz for e in energia]
    cfads = [rv - opex for rv in ricavi]
    if cfads[0] <= 0:
        return _ko("CFADS anno 1 non positivo: i ricavi non coprono l'OPEX.")
    if any(c <= 0 for c in cfads[:tenor]):
        return _ko("CFADS non positivo in uno degli anni del debito: "
                   "progetto non finanziabile a questo DSCR.")

    ds = [c / dscr_t for c in cfads[:tenor]]
    if r == 0.0:
        debt = float(sum(ds))
        pv_tenor = float(sum(cfads[:tenor]))
        pv_vita = float(sum(cfads))
    else:
        rf = 1.0 + r / 100.0
        debt = float(sum(d / rf ** (y + 1) for y, d in enumerate(ds)))
        pv_tenor = float(sum(c / rf ** (y + 1)
                             for y, c in enumerate(cfads[:tenor])))
        pv_vita = float(sum(c / rf ** (y + 1)
                            for y, c in enumerate(cfads)))
    gearing = debt / capex
    finanziabile = bool(gearing <= 1.0)
    llcr = pv_tenor / debt if debt > 0 else None
    plcr = pv_vita / debt if debt > 0 else None
    equity = capex - debt
    dscr_prof = [cfads[y] / ds[y] for y in range(tenor)]
    dscr_min = min(dscr_prof)
    dscr_medio = sum(dscr_prof) / len(dscr_prof)

    irr_eq = None
    if equity > 0:
        cf_eq = [-equity] + [cfads[y] - (ds[y] if y < tenor else 0.0)
                             for y in range(vita)]
        if any(c > 0 for c in cf_eq[1:]):
            irr_eq = _irr(cf_eq)

    df = pd.DataFrame({
        "Anno": list(range(1, vita + 1)),
        "Energia (MWh)": [round(e, 1) for e in energia],
        "Ricavi (EUR)": [round(rv, 0) for rv in ricavi],
        "OPEX (EUR)": [round(opex, 0)] * vita,
        "CFADS (EUR)": [round(c, 0) for c in cfads],
        "Debt service (EUR)": [round(ds[y], 0) if y < tenor else 0.0
                               for y in range(vita)],
        "DSCR": [round(dscr_prof[y], 3) if y < tenor else None
                 for y in range(vita)],
    })
    return {
        "errore": None, "valido": True,
        "capex": capex, "debito_max": debt, "gearing": gearing,
        "finanziabile": finanziabile, "equity": equity,
        "llcr": llcr, "plcr": plcr, "tenor": tenor,
        "dscr_min": dscr_min, "dscr_medio": dscr_medio,
        "dscr_target": dscr_t, "irr_equity": irr_eq,
        "cfads_anno1": cfads[0], "energia_anno1": energia[0],
        "df_annuale": df,
    }


def calcola_competitivita_offerta(prezzo_mercato, prezzo_offerta,
                                  consumo_mwh_anno, margine_target_pct):
    """Competitivita' di un'offerta a prezzo fisso vs prezzo di mercato.

    sconto_pct = (mercato - offerta) / mercato * 100
    risparmio annuo = (mercato - offerta) * consumo
    L'offerta e' competitiva se offerta <= mercato * (1 - margine_target/100).
    df_scenari: mercato *(0.9, 0.95, 1, 1.05, 1.1) con risparmio annuo relativo.
    Funzione pura: nessun accesso a Streamlit.
    """
    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _ko(msg):
        return {"errore": msg, "valido": False}

    mercato = _num(prezzo_mercato); offerta = _num(prezzo_offerta)
    consumo = _num(consumo_mwh_anno); margine = _num(margine_target_pct)
    if None in (mercato, offerta, consumo, margine):
        return _ko("Tutti i parametri devono essere numerici.")
    if mercato <= 0:
        return _ko("Il prezzo di mercato deve essere > 0 EUR/MWh.")
    if offerta <= 0:
        return _ko("Il prezzo dell'offerta deve essere > 0 EUR/MWh.")
    if consumo <= 0:
        return _ko("Il consumo annuo deve essere > 0 MWh.")
    if not 0.0 <= margine < 100.0:
        return _ko("Il margine target deve essere tra 0 (incluso) e 100 (escluso) %.")

    sconto_pct = (mercato - offerta) / mercato * 100.0
    risparmio = (mercato - offerta) * consumo
    competitiva = offerta <= mercato * (1.0 - margine / 100.0)

    fattori = [0.9, 0.95, 1.0, 1.05, 1.1]
    nomi = ["-10%", "-5%", "Base", "+5%", "+10%"]
    df = pd.DataFrame({
        "Scenario": nomi,
        "Prezzo mercato (EUR/MWh)": [round(mercato * f, 2) for f in fattori],
        "Risparmio annuo (EUR)": [round((mercato * f - offerta) * consumo, 0)
                                  for f in fattori],
    })
    return {
        "errore": None, "valido": True,
        "prezzo_mercato": mercato, "prezzo_offerta": offerta,
        "consumo_mwh_anno": consumo, "margine_target_pct": margine,
        "sconto_pct": sconto_pct, "risparmio_annuo": risparmio,
        "competitiva": competitiva, "df_scenari": df,
    }


def calcola_gradi_giorno(temp_medie_mensili, base_risc, base_raff, coeff_kwh_per_hdd):
    """Gradi giorno mensili (HDD/CDD) e stima del fabbisogno termico.

    HDD_mese = max(0, base_risc - T_mese) * giorni_mese
    CDD_mese = max(0, T_mese - base_raff) * giorni_mese
    stima_kwh_termici = hdd_annuo * coeff_kwh_per_hdd.
    Funzione pura: nessun accesso a Streamlit.
    """
    _GIORNI = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    _MESI = ["Gen", "Feb", "Mar", "Apr", "Mag", "Giu",
             "Lug", "Ago", "Set", "Ott", "Nov", "Dic"]

    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _ko(msg):
        return {"errore": msg, "valido": False}

    temps = temp_medie_mensili
    if not isinstance(temps, (list, tuple)) or len(temps) != 12:
        return _ko("Servono esattamente 12 temperature medie mensili.")
    t = [_num(v) for v in temps]
    if any(v is None for v in t):
        return _ko("Le temperature devono essere tutte numeriche (niente NaN).")
    br = _num(base_risc)
    bc = _num(base_raff)
    k = _num(coeff_kwh_per_hdd)
    if None in (br, bc, k):
        return _ko("Base riscaldamento, base raffrescamento e coefficiente "
                   "devono essere numerici.")
    if k < 0:
        return _ko("Il coefficiente kWh/HDD non puo' essere negativo.")

    hdd_m = [max(0.0, br - tv) * g for tv, g in zip(t, _GIORNI)]
    cdd_m = [max(0.0, tv - bc) * g for tv, g in zip(t, _GIORNI)]
    hdd_annuo = float(sum(hdd_m))
    cdd_annuo = float(sum(cdd_m))
    df = pd.DataFrame({
        "Mese": _MESI,
        "HDD": [round(v, 2) for v in hdd_m],
        "CDD": [round(v, 2) for v in cdd_m],
    })
    return {
        "errore": None, "valido": True,
        "hdd_mensili": hdd_m, "cdd_mensili": cdd_m,
        "hdd_annuo": hdd_annuo, "cdd_annuo": cdd_annuo,
        "stima_kwh_termici": hdd_annuo * k,
        "base_risc": br, "base_raff": bc, "coeff_kwh_per_hdd": k,
        "df_mensile": df,
    }


def calcola_confronto_fornitori(consumo_mwh, offerte):
    """Confronta le offerte di fornitura energia su un consumo annuo dato.

    costo_tot = quota_energia*consumo + quota_fissa + quota_potenza*kw.
    Funzione pura: nessun accesso a Streamlit.
    """
    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _ko(msg):
        return {"errore": msg, "valido": False, "df": None,
                "migliore": None, "delta": {}}

    c = _num(consumo_mwh)
    if c is None or c <= 0:
        return _ko("Il consumo annuo deve essere > 0 MWh.")
    if not offerte or not isinstance(offerte, (list, tuple)):
        return _ko("Nessuna offerta da confrontare: "
                   "inserisci i parametri dei fornitori.")
    righe = []
    for off in offerte:
        if not isinstance(off, dict):
            return _ko("Ogni offerta deve essere un dizionario di parametri.")
        nome = str(off.get("nome", "")).strip() or "Senza nome"
        qe = _num(off.get("quota_energia"))
        qf = _num(off.get("quota_fissa"))
        qp = _num(off.get("quota_potenza"))
        kw = _num(off.get("kw"))
        if None in (qe, qf, qp, kw):
            return _ko(f"Parametri non numerici per l'offerta '{nome}'.")
        if qe < 0 or qf < 0 or qp < 0 or kw < 0:
            return _ko(f"Parametri negativi non ammessi per l'offerta '{nome}'.")
        quota_e = qe * c
        quota_p = qp * kw
        totale = quota_e + qf + quota_p
        righe.append({
            "Fornitore": nome,
            "Quota energia €": round(quota_e, 2),
            "Quota fissa €": round(qf, 2),
            "Quota potenza €": round(quota_p, 2),
            "Totale €": round(totale, 2),
        })
    df = pd.DataFrame(righe)
    idx_min = df["Totale €"].idxmin()
    migliore = df.loc[idx_min, "Fornitore"]
    tot_min = float(df.loc[idx_min, "Totale €"])
    delta = {r["Fornitore"]: round(r["Totale €"] - tot_min, 2)
             for r in righe}
    return {
        "errore": None, "valido": True,
        "df": df, "migliore": migliore, "delta": delta,
    }


def calcola_sconto_pronta_cassa(importo, sconto_pct, giorni_anticipo, wacc_pct):
    """Confronto sconto per pagamento anticipato vs costo del capitale (WACC).

    Uno sconto del fornitore per il pagamento anticipato equivale a
    prendere a prestito: il tasso implicito annualizzato e'
        (sconto / (1 - sconto)) * (365 / giorni_anticipo) * 100
    con sconto in frazione. Lo sconto conviene se il tasso implicito
    supera il WACC.
    Funzione pura: nessun accesso a Streamlit.
    """
    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _ko(msg):
        return {"errore": msg, "valido": False}

    try:
        imp = _num(importo); sc = _num(sconto_pct)
        gg = _num(giorni_anticipo); w = _num(wacc_pct)
        if None in (imp, sc, gg, w):
            return _ko("Tutti i parametri devono essere numerici.")
        if imp <= 0:
            return _ko("L'importo deve essere > 0 EUR.")
        if not 0.0 < sc < 100.0:
            return _ko("Lo sconto deve essere tra 0 e 100 (esclusi) %.")
        if gg <= 0:
            return _ko("I giorni di anticipo devono essere > 0.")
        if w < 0:
            return _ko("Il WACC non puo' essere negativo.")

        fraz = sc / 100.0
        tasso_implicito = (fraz / (1.0 - fraz)) * (365.0 / gg) * 100.0
        costo_sconto = imp * fraz
        costo_wacc = imp * (w / 100.0) * (gg / 365.0)
        risparmio = costo_sconto - costo_wacc
        conviene = bool(tasso_implicito > w)

        giorni_range = list(range(7, 91))
        tassi = [(fraz / (1.0 - fraz)) * (365.0 / g) * 100.0
                 for g in giorni_range]
        df_sens = pd.DataFrame({
            "Giorni anticipo": giorni_range,
            "Tasso implicito (%/anno)": tassi})

        return {"errore": None, "valido": True,
                "importo": imp, "sconto_pct": sc,
                "giorni_anticipo": int(round(gg)), "wacc_pct": w,
                "tasso_implicito_pct": tasso_implicito,
                "costo_sconto_eur": costo_sconto,
                "costo_wacc_eur": costo_wacc,
                "risparmio_vs_wacc_eur": risparmio,
                "conviene": conviene,
                "df_sensibilita": df_sens}
    except Exception as e:  # pragma: no cover - guardia totale
        return {"errore": "Errore interno: %s" % e, "valido": False}


def calcola_scoring_ppa(offerte, pesi):
    """Scoring multi-criterio di offerte PPA (funzione pura).

    offerte: lista di dict {"nome": str, "prezzo": EUR/MWh,
      "durata": anni, "profilo": % di match del profilo (0-100),
      "floor": bool (prezzo minimo garantito)}.
    pesi: dict {"prezzo": w1, "durata": w2, "profilo": w3, "floor": w4}
      (somma > 0; vengono normalizzati internamente).

    Normalizzazione min-max per criterio (scala 0-100): prezzo -> 100 al
    MINIMO (prezzo minore = meglio), durata -> 100 al MASSIMO,
    profilo -> valore diretto 0-100, floor -> 100 se True else 0.
    Se max == min su un criterio, score 100 a tutti su quel criterio.
    score_tot = somma(peso_norm * score_criterio).

    NaN-safe: offerte vuote, pesi non validi, valori non numerici ->
    {"errore": ...} senza eccezioni. Deterministica.
    Ritorna dict con errore, df (Offerta, Prezzo, Durata, Profilo, Floor,
    Score), df_criteri (score 0-100 per criterio, per il radar),
    classifica (nomi ordinati per score desc) e pesi_norm.
    """
    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _ko(msg):
        return {"errore": msg, "valido": False}

    if not isinstance(offerte, (list, tuple)) or len(offerte) == 0:
        return _ko("Servono una o piu' offerte PPA da confrontare.")
    if not isinstance(pesi, dict):
        return _ko("I pesi devono essere un dict "
                   "{'prezzo', 'durata', 'profilo', 'floor'}.")

    nomi, prezzi, durate, profili, floors = [], [], [], [], []
    for i, off in enumerate(offerte):
        if not isinstance(off, dict):
            return _ko("L'offerta #%d non e' valida." % (i + 1))
        nome = off.get("nome")
        if not isinstance(nome, str) or not nome.strip():
            return _ko("L'offerta #%d non ha un nome valido." % (i + 1))
        nome = nome.strip()
        p = _num(off.get("prezzo"))
        d = _num(off.get("durata"))
        pr = _num(off.get("profilo"))
        if p is None or d is None or pr is None:
            return _ko("L'offerta '%s' ha valori non numerici." % nome)
        if p <= 0:
            return _ko("Il prezzo dell'offerta '%s' deve essere > 0 "
                       "EUR/MWh." % nome)
        if d < 1:
            return _ko("La durata dell'offerta '%s' deve essere >= 1 "
                       "anno." % nome)
        nomi.append(nome)
        prezzi.append(p)
        durate.append(d)
        profili.append(min(100.0, max(0.0, pr)))
        floors.append(bool(off.get("floor")))

    chiavi = ("prezzo", "durata", "profilo", "floor")
    w = []
    for k in chiavi:
        v = _num(pesi.get(k, 0.0))
        if v is None or v < 0:
            return _ko("Il peso '%s' deve essere un numero >= 0." % k)
        w.append(v)
    somma = sum(w)
    if somma <= 0:
        return _ko("La somma dei pesi deve essere > 0.")
    pesi_norm = {k: w[j] / somma for j, k in enumerate(chiavi)}

    def _mm_norm(vals, inverti=False):
        vmin, vmax = min(vals), max(vals)
        if vmax == vmin:
            return [100.0] * len(vals)
        if inverti:  # prezzo: 100 al minimo (minore = meglio)
            return [100.0 * (vmax - v) / (vmax - vmin) for v in vals]
        return [100.0 * (v - vmin) / (vmax - vmin) for v in vals]

    s_prezzo = _mm_norm(prezzi, inverti=True)
    s_durata = _mm_norm(durate, inverti=False)
    s_profilo = list(profili)
    s_floor = [100.0 if f else 0.0 for f in floors]

    scores = []
    for i in range(len(nomi)):
        tot = (pesi_norm["prezzo"] * s_prezzo[i]
               + pesi_norm["durata"] * s_durata[i]
               + pesi_norm["profilo"] * s_profilo[i]
               + pesi_norm["floor"] * s_floor[i])
        scores.append(round(tot, 2))

    # sorted stabile: a parita' di score vince l'ordine di input
    ordine = sorted(range(len(nomi)), key=lambda i: -scores[i])
    classifica = [nomi[i] for i in ordine]

    df = pd.DataFrame({
        "Offerta": nomi,
        "Prezzo": [round(p, 2) for p in prezzi],
        "Durata": [round(d, 1) for d in durate],
        "Profilo": [round(pr, 1) for pr in profili],
        "Floor": ["Si" if f else "No" for f in floors],
        "Score": scores,
    }).iloc[ordine].reset_index(drop=True)
    df_criteri = pd.DataFrame({
        "Offerta": nomi,
        "Prezzo": [round(s, 1) for s in s_prezzo],
        "Durata": [round(s, 1) for s in s_durata],
        "Profilo": [round(s, 1) for s in s_profilo],
        "Floor": [round(s, 1) for s in s_floor],
    }).iloc[ordine].reset_index(drop=True)

    return {"errore": None, "valido": True, "df": df,
            "df_criteri": df_criteri, "classifica": classifica,
            "pesi_norm": pesi_norm}


def calcola_valore_tee(risparmio_mwh_anno, vettore, anni_vita_utile,
                      prezzo_tee_eur, tasso_sconto_pct,
                      costo_istruttoria_eur_anno, costo_intervento_eur):
    """Valutazione dei Titoli di Efficienza Energetica (Certificati Bianchi)
    generati da un intervento di risparmio energetico.

    1 TEE = 1 tep (tonnellata equivalente di petrolio) di risparmio.
    Fattori di conversione convenzionali: elettrico 5.346 MWh/tep,
    gas 11.63 MWh/tep (1 tep = 11.63 MWh termici PCI).

    TEE_annui = risparmio / fattore; ricavo_lordo = TEE_annui * prezzo_tee;
    flusso_annuo_netto = ricavo_lordo - costo_istruttoria.
    VAN sul periodo di vita utile al tasso di sconto con costo_intervento
    all'anno 0; TIR per bisezione; payback semplice.
    Funzione pura: nessun accesso a Streamlit.
    """
    _FATTORI = {"elettrico": 5.346, "gas": 11.63}

    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _ko(msg):
        return {"errore": msg, "valido": False}

    risparmio = _num(risparmio_mwh_anno)
    anni = _num(anni_vita_utile)
    prezzo = _num(prezzo_tee_eur)
    tasso = _num(tasso_sconto_pct)
    istruttoria = _num(costo_istruttoria_eur_anno)
    costo = _num(costo_intervento_eur)
    if None in (risparmio, anni, prezzo, tasso, istruttoria, costo):
        return _ko("Tutti i parametri numerici devono essere numeri.")
    if risparmio <= 0:
        return _ko("Il risparmio annuo deve essere > 0 MWh.")
    if not (vettore in _FATTORI):
        return _ko("Vettore non valido: 'elettrico' o 'gas'.")
    if not (1 <= anni <= 20) or anni != int(anni):
        return _ko("La vita utile deve essere un numero intero tra 1 e 20 anni.")
    if prezzo <= 0:
        return _ko("Il prezzo del TEE deve essere > 0 EUR.")
    if tasso < 0:
        return _ko("Il tasso di sconto non puo' essere negativo.")
    if istruttoria < 0 or costo < 0:
        return _ko("Costi di istruttoria e intervento non possono essere negativi.")
    n = int(anni)
    r = tasso / 100.0

    fattore = _FATTORI[vettore]
    tee_annui = risparmio / fattore
    ricavo_lordo = tee_annui * prezzo
    flusso_annuo = ricavo_lordo - istruttoria

    def _van(t):
        return sum(flusso_annuo / (1.0 + t) ** k for k in range(1, n + 1))

    van = -costo + _van(r)

    # TIR per bisezione, flussi: [-costo, flusso, ..., flusso]
    tir_pct = None
    if costo > 0 and flusso_annuo > 0 and -costo + _van(0.0) > 0 \
            and -costo + _van(5.0) < 0:
        lo, hi = 0.0, 5.0
        for _ in range(200):
            mid = (lo + hi) / 2.0
            if -costo + _van(mid) > 0:
                lo = mid
            else:
                hi = mid
        tir_pct = lo * 100.0

    # Payback semplice
    if costo <= 0:
        payback_anni = 0.0 if flusso_annuo > 0 else None
    elif flusso_annuo <= 0:
        payback_anni = None
    else:
        payback_anni = None
        for k in range(1, n + 1):
            if k * flusso_annuo >= costo:
                payback_anni = float(k)
                break

    righe = []
    cumulato = -costo
    for k in range(n + 1):
        if k == 0:
            tee, lordo, istr, netto, att = 0.0, 0.0, 0.0, -costo, -costo
        else:
            tee, lordo, istr = tee_annui, ricavo_lordo, istruttoria
            netto = flusso_annuo
            att = flusso_annuo / (1.0 + r) ** k
        cumulato += (att if k > 0 else 0.0)
        righe.append({
            "Anno": k,
            "TEE generati": round(tee, 2),
            "Ricavo lordo (€)": round(lordo, 0),
            "Costo istruttoria (€)": round(istr, 0),
            "Flusso netto (€)": round(netto, 0),
            "Flusso attualizzato (€)": round(att, 0),
            "Cumulato attualizzato (€)": round(cumulato, 0),
        })
    df = pd.DataFrame(righe, columns=["Anno", "TEE generati",
                                      "Ricavo lordo (€)",
                                      "Costo istruttoria (€)",
                                      "Flusso netto (€)",
                                      "Flusso attualizzato (€)",
                                      "Cumulato attualizzato (€)"])
    return {
        "errore": None, "valido": True,
        "vettore": vettore, "fattore_mwh_per_tee": fattore,
        "tee_annui": tee_annui, "ricavo_lordo_annuo": ricavo_lordo,
        "ricavo_netto_annuo": flusso_annuo, "van": van,
        "tir_pct": tir_pct, "payback_anni": payback_anni,
        "verdetto": "CONVENIENTE" if van > 0 else "NON CONVENIENTE",
        "df": df,
    }


def calcola_costo_uscita(prezzo_fisso_eur_mwh, volume_mensile_mwh,
                         mesi_residui, forward_eur_mwh,
                         tasso_annuo_pct, penale_eur=0.0):
    """Costo/beneficio di uscita anticipata da un contratto di fornitura a
    prezzo fisso.

    Restare nel contratto costa P_fisso per ogni MWh; uscire e ricomprare a
    mercato costa il forward F. Risparmio mensile = (P_fisso - F) * volume.
    VAN_uscita = somma attualizzata dei risparmi mensili - penale di uscita
    (se positiva conviene uscire, se negativa conviene restare).
    Forward di pareggio F* = P_fisso - penale / (volume * A), con A fattore
    di rendita mensile al tasso annuo: se il forward scende sotto F*
    l'uscita torna conveniente. Funzione pura: nessun accesso a Streamlit.
    """
    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _ko(msg):
        return {"errore": msg, "valido": False}

    pfix = _num(prezzo_fisso_eur_mwh)
    vol = _num(volume_mensile_mwh)
    mesi = _num(mesi_residui)
    fwd = _num(forward_eur_mwh)
    tasso = _num(tasso_annuo_pct)
    penale = _num(penale_eur)
    if None in (pfix, vol, mesi, fwd, tasso, penale):
        return _ko("Tutti i parametri numerici devono essere numeri.")
    if pfix <= 0:
        return _ko("Il prezzo fisso contrattuale deve essere > 0 EUR/MWh.")
    if vol <= 0:
        return _ko("Il volume mensile deve essere > 0 MWh.")
    if mesi != int(mesi) or not (1 <= mesi <= 60):
        return _ko("I mesi residui devono essere un intero tra 1 e 60.")
    if fwd <= 0:
        return _ko("Il prezzo forward deve essere > 0 EUR/MWh.")
    if tasso < 0:
        return _ko("Il tasso annuo non puo' essere negativo.")
    if penale < 0:
        return _ko("La penale di uscita non puo' essere negativa.")
    n = int(mesi)
    r = tasso / 100.0

    risparmio_unitario = pfix - fwd
    risparmio_mensile = risparmio_unitario * vol
    fattori = [(1.0 + r) ** (k / 12.0) for k in range(1, n + 1)]
    attualizzati = [risparmio_mensile / f for f in fattori]
    a_rendita = sum(1.0 / f for f in fattori)
    van_uscita = sum(attualizzati) - penale
    # Forward di pareggio: (P - F*) * V * A = penale
    f_pareggio = pfix - (penale / (vol * a_rendita) if a_rendita > 0 else 0.0)

    if van_uscita > 0:
        verdetto = "CONVIENE USCIRE"
    elif van_uscita < 0:
        verdetto = "RESTA NEL CONTRATTO"
    else:
        verdetto = "INDIFFERENTE"

    righe = []
    cumulato = 0.0
    for k in range(1, n + 1):
        att = attualizzati[k - 1]
        cumulato += att
        righe.append({
            "Mese": k,
            "Prezzo fisso (€/MWh)": round(pfix, 2),
            "Forward (€/MWh)": round(fwd, 2),
            "Risparmio unitario (€/MWh)": round(risparmio_unitario, 2),
            "Risparmio mensile (€)": round(risparmio_mensile, 0),
            "Risparmio attualizzato (€)": round(att, 0),
            "Cumulato attualizzato (€)": round(cumulato, 0),
        })
    cols = ["Mese", "Prezzo fisso (€/MWh)", "Forward (€/MWh)",
            "Risparmio unitario (€/MWh)", "Risparmio mensile (€)",
            "Risparmio attualizzato (€)", "Cumulato attualizzato (€)"]
    df = pd.DataFrame(righe, columns=cols)
    return {
        "errore": None, "valido": True,
        "risparmio_unitario": risparmio_unitario,
        "risparmio_mensile": risparmio_mensile,
        "risparmio_totale": risparmio_mensile * n,
        "van_uscita": van_uscita,
        "forward_pareggio": f_pareggio,
        "verdetto": verdetto,
        "df": df,
    }


def calcola_confronto_offerte(offerte, volume_annuo_mwh):
    """Confronta offerte di fornitura: rinnovo del contratto attuale contro
    proposte alternative (switch fornitore).

    Ogni offerta e' un dict con chiavi: nome, prezzo_energia_eur_mwh,
    canone_fisso_eur_mese, durata_mesi, costo_attivazione_eur, sconto_pct
    (opzionale, 0-100, applicato al prezzo energia).
    TCO annuo = V * prezzo_eff + 12 * canone + attivazione; la prima offerta
    della lista e' il riferimento (rinnovo). Volume di pareggio tra due
    offerte i,j: V* = (12*(canone_j-canone_i) + (att_j-att_i)) /
    (prezzo_eff_i - prezzo_eff_j); None se non esiste per volumi positivi.
    Funzione pura: nessun accesso a Streamlit.
    """
    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _ko(msg):
        return {"errore": msg, "valido": False}

    vol = _num(volume_annuo_mwh)
    if vol is None:
        return _ko("Il volume annuo deve essere un numero.")
    if vol <= 0:
        return _ko("Il volume annuo deve essere > 0 MWh.")
    if not isinstance(offerte, (list, tuple)) or len(offerte) < 2:
        return _ko("Servono almeno 2 offerte da confrontare.")

    righe = []
    for i, o in enumerate(offerte):
        if not isinstance(o, dict):
            return _ko("L'offerta #%d non e' valida." % (i + 1))
        nome = str(o.get("nome", "Offerta %d" % (i + 1)))
        prezzo = _num(o.get("prezzo_energia_eur_mwh"))
        canone = _num(o.get("canone_fisso_eur_mese"))
        durata = _num(o.get("durata_mesi"))
        att = _num(o.get("costo_attivazione_eur"))
        sconto = _num(o.get("sconto_pct", 0.0))
        if None in (prezzo, canone, durata, att, sconto):
            return _ko("L'offerta '%s' ha parametri non numerici." % nome)
        if prezzo < 0:
            return _ko("L'offerta '%s': il prezzo energia non puo' essere "
                       "negativo." % nome)
        if canone < 0:
            return _ko("L'offerta '%s': il canone fisso non puo' essere "
                       "negativo." % nome)
        if durata != int(durata) or not (1 <= durata <= 120):
            return _ko("L'offerta '%s': la durata deve essere un intero tra "
                       "1 e 120 mesi." % nome)
        if att < 0:
            return _ko("L'offerta '%s': il costo di attivazione non puo' "
                       "essere negativo." % nome)
        if not (0 <= sconto <= 100):
            return _ko("L'offerta '%s': lo sconto deve stare tra 0 e "
                       "100 %%." % nome)
        prezzo_eff = prezzo * (1.0 - sconto / 100.0)
        costo_energia = vol * prezzo_eff
        fisso_annuo = 12.0 * canone
        tco = costo_energia + fisso_annuo + att
        righe.append({
            "Offerta": nome,
            "Prezzo eff. (€/MWh)": round(prezzo_eff, 2),
            "Canone annuo (€)": round(fisso_annuo, 0),
            "Attivazione (€)": round(att, 0),
            "Durata (mesi)": int(durata),
            "TCO annuo (€)": round(tco, 0),
            "All-in (€/MWh)": round(tco / vol, 2),
            "_pe": prezzo_eff, "_canone": canone, "_att": att, "_tco": tco,
        })

    df = pd.DataFrame(righe).drop(columns=["_pe", "_canone", "_att", "_tco"])
    tco_vals = [r["_tco"] for r in righe]
    nomi = [r["Offerta"] for r in righe]
    pes = [r["_pe"] for r in righe]
    canoni = [r["_canone"] for r in righe]
    atts = [r["_att"] for r in righe]
    i_best = int(min(range(len(tco_vals)), key=lambda k: tco_vals[k]))
    tco_rinnovo = tco_vals[0]
    risparmio = tco_rinnovo - tco_vals[i_best]
    # Verdetto relativo al rinnovo (prima offerta della lista)
    tco_alt_min = min(tco_vals[1:])
    if tco_alt_min < tco_rinnovo:
        verdetto = "CONVIENE LO SWITCH"
    elif tco_alt_min > tco_rinnovo:
        verdetto = "RESTA NEL CONTRATTO"
    else:
        verdetto = "INDIFFERENTE"

    pareggi = []
    for i in range(len(righe)):
        for j in range(i + 1, len(righe)):
            a = pes[i] - pes[j]
            num = 12.0 * (canoni[j] - canoni[i]) + (atts[j] - atts[i])
            if a == 0.0:
                v_star = None
            else:
                v_star = num / a
                if not (v_star is not None and v_star > 0):
                    v_star = None
            if v_star is None:
                vincitore = nomi[i] if tco_vals[i] <= tco_vals[j] else nomi[j]
                lettura = ("%s sempre piu' economica "
                           "(nessun incrocio)" % vincitore)
                v_out = None
            else:
                # A volume -> 0 vince chi ha costi fissi minori:
                # TCO_i - TCO_j = a*V - num, a V=0 vale -num.
                vinc_basso = nomi[i] if num > 0 else nomi[j]
                vinc_alto = nomi[j] if num > 0 else nomi[i]
                v_fmt = "{:,.0f}".format(v_star).replace(",", ".")
                lettura = ("Fino a %s MWh/anno conviene %s, "
                           "oltre conviene %s" % (v_fmt, vinc_basso,
                                                 vinc_alto))
                v_out = round(v_star, 0)
            pareggi.append({
                "Coppia": "%s vs %s" % (nomi[i], nomi[j]),
                "Volume pareggio (MWh/anno)": v_out,
                "Lettura": lettura,
            })
    df_par = pd.DataFrame(pareggi)

    return {
        "errore": None, "valido": True,
        "df": df, "df_pareggi": df_par,
        "nomi": nomi, "tco": tco_vals,
        "migliore": nomi[i_best],
        "tco_migliore": tco_vals[i_best],
        "allin_migliore": tco_vals[i_best] / vol,
        "tco_rinnovo": tco_rinnovo,
        "risparmio_vs_rinnovo": risparmio,
        "verdetto": verdetto,
        "volume_annuo": vol,
    }


def calcola_backtest_indicizzato(prezzi, prezzo_fisso_eur_mwh, spread_eur_mwh,
                                 cap_eur_mwh=None, floor_eur_mwh=None,
                                 volume_mensile_mwh=100.0):
    """Backtest ex-post di un'offerta a prezzo indicizzato contro un'offerta a
    prezzo fisso, sulla serie spot oraria del periodo selezionato.

    Formula indicizzata (tipica delle offerte luce business):
        prezzo_indicizzato_mese = clamp(media_spot_mese + spread, floor, cap)
    - media_spot_mese: media aritmetica delle ore spot osservate nel mese;
    - spread: maggiorazione (o sconto, se negativo) del fornitore in EUR/MWh;
    - cap/floor opzionali: tetto e pavimento mensili sul prezzo indicizzato
      (None = nessun limite).

    Il volume mensile e' scalato sulle ore osservate
    (mesi DST da 23/25 ore, periodi parziali):
        vol_mese = volume_mensile_mwh * ore_osservate / ore_mese_calendario.

    Differenza dalle altre tab: 'Fisso vs indicizzato' confronta due prezzi
    teorici; qui si REGOLA ex-post una clausola specifica (spread + cap/floor)
    sulla storia spot, e si ricava il PREZZO FISSO DI PAREGGIO: il fisso che
    avrebbe eguagliato il costo totale dell'indicizzato — utile in trattativa
    ("l'indicizzato mi conviene se il fisso supera X").

    NaN-safe: serie vuota o indice non datetime -> valido=False con 'errore'.
    Ore con prezzo NaN escluse dalle medie; mesi senza ore osservate esclusi.

    Ritorna dict con 'errore', 'valido', 'df_mesi' (Mese, Ore osservate,
    Prezzo spot medio (EUR/MWh), Prezzo indicizzato (EUR/MWh),
    Costo indicizzato (EUR), Costo fisso (EUR), Risparmio indicizzato (EUR)),
    'volume_totale_mwh', 'costo_totale_indicizzato', 'costo_totale_fisso',
    'risparmio_totale', 'risparmio_pct', 'pmp_indicizzato',
    'prezzo_fisso_pareggio', 'mesi', 'mesi_vinti_indicizzato'.
    """
    colonne = ["Mese", "Ore osservate", "Prezzo spot medio (\u20ac/MWh)",
               "Prezzo indicizzato (\u20ac/MWh)", "Costo indicizzato (\u20ac)",
               "Costo fisso (\u20ac)", "Risparmio indicizzato (\u20ac)"]
    vuoto = {"errore": None, "valido": False, "df_mesi": pd.DataFrame(columns=colonne),
             "volume_totale_mwh": 0.0, "costo_totale_indicizzato": 0.0,
             "costo_totale_fisso": 0.0, "risparmio_totale": 0.0,
             "risparmio_pct": 0.0, "pmp_indicizzato": None,
             "prezzo_fisso_pareggio": None, "mesi": 0,
             "mesi_vinti_indicizzato": 0}

    def _ko(msg):
        out = dict(vuoto)
        out["errore"] = msg
        return out

    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    pf = _num(prezzo_fisso_eur_mwh)
    sp = _num(spread_eur_mwh)
    cap = _num(cap_eur_mwh) if cap_eur_mwh is not None else None
    flr = _num(floor_eur_mwh) if floor_eur_mwh is not None else None
    vol = _num(volume_mensile_mwh)
    if pf is None or sp is None or vol is None:
        return _ko("Prezzo fisso, spread e volume mensile devono essere numeri.")
    if pf < 0:
        return _ko("Il prezzo fisso non puo' essere negativo.")
    if vol <= 0:
        return _ko("Il volume mensile deve essere > 0 MWh.")
    if cap is not None and cap < 0:
        return _ko("Il cap non puo' essere negativo.")
    if flr is not None and flr < 0:
        return _ko("Il floor non puo' essere negativo.")
    if cap is not None and flr is not None and flr > cap:
        return _ko("Il floor non puo' superare il cap.")
    try:
        p = pd.Series(prezzi, dtype=float)
    except Exception:
        return _ko("Serie prezzi non valida.")
    p = p[~p.index.duplicated(keep="first")].sort_index()
    p = p[np.isfinite(p.values)]
    if p.empty:
        return _ko("Serie prezzi vuota: nessun dato spot nel periodo selezionato.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _ko("La serie prezzi deve avere un indice temporale.")

    righe = []
    vol_mesi = []
    for mese_ts, grp in p.groupby(pd.Grouper(freq="M")):
        ore_oss = int(len(grp))
        if ore_oss == 0:
            continue
        media_spot = float(grp.mean())
        px_idx = media_spot + sp
        if flr is not None:
            px_idx = max(px_idx, flr)
        if cap is not None:
            px_idx = min(px_idx, cap)
        ore_cal = mese_ts.days_in_month * 24
        vol_mese = vol * ore_oss / ore_cal if ore_cal else 0.0
        vol_mesi.append(vol_mese)
        costo_idx = vol_mese * px_idx
        costo_fix = vol_mese * pf
        righe.append({
            "Mese": mese_ts.strftime("%Y-%m"),
            "Ore osservate": ore_oss,
            "Prezzo spot medio (\u20ac/MWh)": round(media_spot, 2),
            "Prezzo indicizzato (\u20ac/MWh)": round(px_idx, 2),
            "Costo indicizzato (\u20ac)": round(costo_idx, 2),
            "Costo fisso (\u20ac)": round(costo_fix, 2),
            "Risparmio indicizzato (\u20ac)": round(costo_fix - costo_idx, 2),
        })
    if not righe:
        return _ko("Nessun mese con ore osservate nel periodo selezionato.")

    df = pd.DataFrame(righe, columns=colonne)
    vol_tot = float(sum(vol_mesi))
    costo_idx = float(df["Costo indicizzato (\u20ac)"].sum())
    costo_fix = float(df["Costo fisso (\u20ac)"].sum())
    risparmio = costo_fix - costo_idx
    out = dict(vuoto)
    out.update({
        "valido": True,
        "df_mesi": df,
        "volume_totale_mwh": round(vol_tot, 3),
        "costo_totale_indicizzato": round(costo_idx, 2),
        "costo_totale_fisso": round(costo_fix, 2),
        "risparmio_totale": round(risparmio, 2),
        "risparmio_pct": round(100.0 * risparmio / costo_fix, 2) if costo_fix else 0.0,
        "pmp_indicizzato": round(costo_idx / vol_tot, 2) if vol_tot else None,
        "prezzo_fisso_pareggio": round(costo_idx / vol_tot, 2) if vol_tot else None,
        "mesi": len(righe),
        "mesi_vinti_indicizzato": int((df["Risparmio indicizzato (\u20ac)"] > 0).sum()),
    })
    return out


def calcola_robustezza_offerta(prezzi, mw_f1=1.0, mw_f2=1.0, mw_f3=1.0,
                               offerte=None, spostamento_pct=20.0):
    """Robustezza delle offerte di fornitura al profilo di carico (F1/F2/F3).

    Domanda operativa: "l'offerta piu' economica resta la piu' economica se
    il mio profilo di carico cambia?" Le offerte si valutano sul TUO profilo
    orario reale (MW per fascia F1/F2/F3 sulle ore del periodo selezionato),
    non su un volume piatto: a parita' di MWh totali, un'offerta con F1 cara
    penalizza chi consuma di giorno. Poi la classifica viene stressata con
    tre scenari di spostamento del carico:
      - "Verso picco": una quota q% dell'energia F2+F3 si sposta in F1
        (es. piu' produzione diurna);
      - "Verso notte": una quota q% dell'energia F1 si sposta in F3
        (es. turni notturni, ricariche notturne);
      - "Profilo piatto": gli stessi MWh totali distribuiti uniformemente
        sulle ore.
    L'offerta "robusta" e' quella che vince in piu' scenari; il RIMPIANTO
    massimo quantifica quanto costerebbe aver scelto l'offerta sbagliata
    nello scenario peggiore.

    Ogni offerta e' un dict con: nome, prezzo_f1/prezzo_f2/prezzo_f3
    (€/MWh, opzionali), prezzo_energia (€/MWh piatto, usato per le fasce non
    valorizzate), canone_fisso_eur_mese (default 0), sconto_pct (default 0,
    applicato ai prezzi energia). Costo offerta = Σ fascia MWh×prezzo ×
    (1 - sconto/100) + canone × mesi equivalenti (ore totali / 730.5).

    Differenza dagli altri tab: 'Confronto offerte' e 'Confronto fornitori'
    confrontano su un volume annuo piatto; qui il costo e' calcolato per
    causazione oraria sul profilo reale e la classifica e' testata contro
    spostamenti del carico.

    NaN-safe: serie vuota / indice non datetime / profilo MW nullo o
    negativo / meno di 2 offerte / parametri non numerici o fuori range /
    nomi duplicati -> {'valido': False, 'errore': ...}, mai eccezioni;
    tz-aware reso naive; deterministico.

    Ritorna dict con 'errore', 'valido', 'scenari' (nomi), 'n_ore',
    'mwh_fasce' (dict F1/F2/F3), 'mesi_equiv', 'df_base' (ranking sul
    profilo attuale), 'df_scenari' (costi per scenario x offerta +
    vincitore), 'vittorie' (dict nome -> n. scenari vinti),
    'vincitore_base', 'vincitore_robusto', 'rimpianto' (dict nome -> EUR),
    'rimpianto_max', 'verdetto'.
    """
    colonne_base = ["Offerta", "MWh F1", "MWh F2", "MWh F3",
                    "Costo energia (€)", "Canone (€)", "Costo totale (€)",
                    "€/MWh medio", "Δ vs migliore (€)"]
    vuoto = {"errore": None, "valido": False, "scenari": [], "n_ore": 0,
             "mwh_fasce": {}, "mesi_equiv": 0.0,
             "df_base": pd.DataFrame(columns=colonne_base),
             "df_scenari": pd.DataFrame(), "vittorie": {},
             "vincitore_base": None, "vincitore_robusto": None,
             "rimpianto": {}, "rimpianto_max": None, "verdetto": ""}

    def _ko(msg):
        r = dict(vuoto)
        r["errore"] = msg
        return r

    def _num(x):
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        return None if v != v else v

    def _eur(x):
        return "{:,.0f}".format(float(x)).replace(",", ".")

    # --- ore del periodo -> fasce ---
    try:
        idx = prezzi.index[~prezzi.index.duplicated(keep="first")].sort_values()
    except Exception:
        return _ko("Serie prezzi non valida: serve un indice datetime orario.")
    if not isinstance(idx, pd.DatetimeIndex):
        return _ko("La serie prezzi deve avere un indice temporale.")
    if getattr(idx, "tz", None) is not None:
        idx = idx.tz_localize(None)
    if len(idx) == 0:
        return _ko("Serie prezzi vuota.")
    fasce = idx.map(fascia_oraria)
    n1 = int((fasce == "F1").sum())
    n2 = int((fasce == "F2").sum())
    n3 = int((fasce == "F3").sum())
    n_ore = len(idx)

    try:
        mw = [float(mw_f1), float(mw_f2), float(mw_f3)]
    except (TypeError, ValueError):
        return _ko("MW di fascia non validi.")
    if any(v < 0 for v in mw) or sum(mw) == 0:
        return _ko("Profilo MW nullo o negativo.")
    try:
        q = float(spostamento_pct)
    except (TypeError, ValueError):
        return _ko("spostamento_pct non valido.")
    q = max(0.0, min(100.0, q)) / 100.0

    e1, e2, e3 = mw[0] * n1, mw[1] * n2, mw[2] * n3
    e_tot = e1 + e2 + e3
    mesi_equiv = n_ore / 730.5

    # --- offerte ---
    if not isinstance(offerte, (list, tuple)) or len(offerte) < 2:
        return _ko("Servono almeno 2 offerte da confrontare.")
    offs = []
    for i, o in enumerate(offerte):
        if not isinstance(o, dict):
            return _ko("L'offerta #%d non e' valida." % (i + 1))
        nome = str(o.get("nome", "Offerta %d" % (i + 1))).strip()
        if not nome or nome.lower() == "nan":
            nome = "Offerta %d" % (i + 1)
        flat = _num(o.get("prezzo_energia"))
        p1 = _num(o.get("prezzo_f1"))
        p2 = _num(o.get("prezzo_f2"))
        p3 = _num(o.get("prezzo_f3"))
        if p1 is None:
            p1 = flat
        if p2 is None:
            p2 = flat
        if p3 is None:
            p3 = flat
        if None in (p1, p2, p3):
            return _ko("L'offerta '%s': servono i prezzi F1/F2/F3 o un prezzo "
                       "energia piatto." % nome)
        if min(p1, p2, p3) < 0:
            return _ko("L'offerta '%s': i prezzi energia non possono essere "
                       "negativi." % nome)
        canone = _num(o.get("canone_fisso_eur_mese", 0.0))
        if canone is None or canone < 0:
            return _ko("L'offerta '%s': canone fisso non valido." % nome)
        sconto = _num(o.get("sconto_pct", 0.0))
        if sconto is None or not (0.0 <= sconto <= 100.0):
            return _ko("L'offerta '%s': sconto_pct deve stare tra 0 e 100."
                       % nome)
        offs.append({"nome": nome, "p": (p1, p2, p3),
                     "canone": canone, "sconto": sconto})
    nomi = [o["nome"] for o in offs]
    if len(set(nomi)) != len(nomi):
        return _ko("I nomi delle offerte devono essere univoci.")

    def _costo(off, ee1, ee2, ee3):
        p1, p2, p3 = off["p"]
        energia = (ee1 * p1 + ee2 * p2 + ee3 * p3) * (1.0 - off["sconto"] / 100.0)
        return energia + off["canone"] * mesi_equiv

    qlbl = "%g" % (q * 100.0)
    scen = {
        "Profilo attuale": (e1, e2, e3),
        "Verso picco (+%s%% F1)" % qlbl: (e1 + q * (e2 + e3),
                                          e2 * (1.0 - q), e3 * (1.0 - q)),
        "Verso notte (+%s%% F3)" % qlbl: (e1 * (1.0 - q), e2, e3 + q * e1),
        "Profilo piatto": (e_tot * n1 / n_ore, e_tot * n2 / n_ore,
                           e_tot * n3 / n_ore),
    }

    costi = {s: {o["nome"]: _costo(o, *ee) for o in offs}
             for s, ee in scen.items()}
    vincitori = {s: min(c, key=lambda k: c[k]) for s, c in costi.items()}
    vittorie = {nm: sum(1 for s in scen if vincitori[s] == nm) for nm in nomi}
    base = "Profilo attuale"
    vincitore_base = vincitori[base]
    max_v = max(vittorie.values())
    candidati = [nm for nm in nomi if vittorie[nm] == max_v]
    vincitore_robusto = min(candidati, key=lambda nm: costi[base][nm])
    rimpianto = {nm: max(costi[s][nm] - min(costi[s].values()) for s in scen)
                 for nm in nomi}
    rimpianto_max = max(rimpianto.values())

    righe = []
    for o in offs:
        nm = o["nome"]
        ce = ((e1 * o["p"][0] + e2 * o["p"][1] + e3 * o["p"][2])
              * (1.0 - o["sconto"] / 100.0))
        can = o["canone"] * mesi_equiv
        tot = ce + can
        righe.append({"Offerta": nm, "MWh F1": e1, "MWh F2": e2, "MWh F3": e3,
                      "Costo energia (€)": ce, "Canone (€)": can,
                      "Costo totale (€)": tot,
                      "€/MWh medio": tot / e_tot if e_tot else None,
                      "Δ vs migliore (€)": None})
    df_base = pd.DataFrame(righe, columns=colonne_base)
    df_base = df_base.sort_values("Costo totale (€)").reset_index(drop=True)
    best = float(df_base["Costo totale (€)"].iloc[0])
    df_base["Δ vs migliore (€)"] = df_base["Costo totale (€)"] - best
    for c in colonne_base[1:]:
        df_base[c] = pd.to_numeric(df_base[c], errors="coerce").round(
            1 if c.startswith("MWh") else 2)

    righe_s = []
    for s in scen:
        r = {"Scenario": s}
        for nm in nomi:
            r[nm] = round(costi[s][nm], 2)
        r["Vincitore"] = vincitori[s]
        righe_s.append(r)
    df_scenari = pd.DataFrame(righe_s, columns=["Scenario"] + nomi + ["Vincitore"])

    nv = len(scen)
    vb, vr = vincitore_base, vincitore_robusto
    if vb == vr:
        verdetto = ("«%s» vince sul profilo attuale ed e' anche la piu' robusta "
                    "(%d scenari vinti su %d). Rimpianto massimo scegliendola: "
                    "€ %s." % (vb, vittorie[vb], nv, _eur(rimpianto[vb])))
    else:
        verdetto = ("«%s» e' la piu' economica sul profilo attuale, ma «%s» vince "
                    "in piu' scenari (%d su %d). Se il profilo cambiasse, "
                    "scegliere «%s» costerebbe al massimo € %s in piu' rispetto "
                    "alla migliore di scenario." % (
                        vb, vr, vittorie[vr], nv, vb, _eur(rimpianto[vb])))

    out = dict(vuoto)
    out.update({
        "valido": True,
        "scenari": list(scen.keys()),
        "n_ore": n_ore,
        "mwh_fasce": {"F1": e1, "F2": e2, "F3": e3},
        "mesi_equiv": mesi_equiv,
        "df_base": df_base,
        "df_scenari": df_scenari,
        "vittorie": vittorie,
        "vincitore_base": vincitore_base,
        "vincitore_robusto": vincitore_robusto,
        "rimpianto": rimpianto,
        "rimpianto_max": rimpianto_max,
        "verdetto": verdetto,
    })
    return out


def calcola_break_even_offerte(off_a, off_b, quote_fasce, volume_max_mwh=5000.0,
                                n_punti=101):
    """Punto di pareggio tra due offerte a parita' di profilo di consumo.

    costo(V) = V * prezzo_effettivo + 12*canone + attivazione, con prezzo
    effettivo = prezzo piatto oppure media delle fasce F1/F2/F3 pesata sulle
    quote fornite. Ritorna il volume di break-even V* (None in dominanza) e
    la curva dei costi per il grafico.
    """
    vuoto = {"valido": False, "errore": None, "volume_pareggio_mwh": None,
             "dominanza": None, "verdetto": None, "df_curva": None}

    def _num(x):
        return (isinstance(x, (int, float)) and not isinstance(x, bool)
                and x == x and abs(x) != float("inf"))

    if (not isinstance(quote_fasce, (list, tuple)) or len(quote_fasce) != 3
            or not all(_num(q) and q >= 0 for q in quote_fasce)
            or sum(quote_fasce) <= 0):
        return dict(vuoto, errore="Quote fasce non valide: servono 3 valori >= 0 con somma > 0.")
    tot_q = float(sum(quote_fasce))
    q1, q2, q3 = (float(q) / tot_q for q in quote_fasce)
    if not _num(volume_max_mwh) or volume_max_mwh <= 0:
        return dict(vuoto, errore="Volume massimo deve essere > 0.")
    if isinstance(n_punti, bool) or not isinstance(n_punti, int) or n_punti < 2:
        return dict(vuoto, errore="n_punti deve essere un intero >= 2.")

    def _parse(off, tag):
        if not isinstance(off, dict):
            return None, "%s: formato non valido (serve un dict)." % tag
        nome = off.get("nome")
        if not isinstance(nome, str) or not nome.strip():
            return None, "%s: nome mancante." % tag
        nome = nome.strip()
        canone = off.get("canone_eur_mese", 0.0)
        attiv = off.get("attivazione_eur", 0.0)
        if not _num(canone) or canone < 0:
            return None, "«%s»: canone €/mese deve essere >= 0." % nome
        if not _num(attiv) or attiv < 0:
            return None, "«%s»: attivazione € deve essere >= 0." % nome
        prezzi = off.get("prezzi")
        if not isinstance(prezzi, dict):
            return None, "«%s»: prezzi mancanti (piatto o F1/F2/F3)." % nome
        if "piatto" in prezzi:
            p = prezzi["piatto"]
            if not _num(p) or p < 0:
                return None, "«%s»: prezzo €/MWh deve essere >= 0." % nome
            p_eff = float(p)
        else:
            vals = []
            for f in ("F1", "F2", "F3"):
                v = prezzi.get(f)
                if not _num(v) or v < 0:
                    return None, "«%s»: prezzo fascia %s mancante o < 0." % (nome, f)
                vals.append(float(v))
            p_eff = q1 * vals[0] + q2 * vals[1] + q3 * vals[2]
        fisso = 12.0 * float(canone) + float(attiv)
        return {"nome": nome, "p_eff": p_eff, "fisso": fisso}, None

    pa, err = _parse(off_a, "Offerta A")
    if err:
        return dict(vuoto, errore=err)
    pb, err = _parse(off_b, "Offerta B")
    if err:
        return dict(vuoto, errore=err)
    if pa["nome"] == pb["nome"]:
        return dict(vuoto, errore="Le due offerte devono avere nomi diversi.")

    d = pa["p_eff"] - pb["p_eff"]          # differenza prezzo variabile
    n = pb["fisso"] - pa["fisso"]          # differenza fissi (B - A)
    eps = 1e-9
    out = dict(vuoto)
    out.update({"valido": True, "p_eff_a": pa["p_eff"], "p_eff_b": pb["p_eff"],
                "fisso_a": pa["fisso"], "fisso_b": pb["fisso"],
                "nome_a": pa["nome"], "nome_b": pb["nome"],
                "quote_fasce": (q1, q2, q3)})

    if abs(d) < eps and abs(n) < eps:
        out["dominanza"] = "pareggio"
        out["verdetto"] = ("Offerte equivalenti: «%s» e «%s» costano uguale "
                           "a qualsiasi volume." % (pa["nome"], pb["nome"]))
    elif abs(d) < eps:
        win = "A" if pa["fisso"] < pb["fisso"] else "B"
        out["dominanza"] = win
        out["verdetto"] = ("Stesso prezzo €/MWh: vince sempre «%s» "
                           "(fissi annui piu' bassi)." % (pa["nome"] if win == "A" else pb["nome"]))
    else:
        v_star = n / d
        if v_star <= 0:
            # una delle due domina per ogni V > 0: vince il prezzo variabile minore
            win = "A" if d < 0 else "B"
            out["dominanza"] = win
            out["verdetto"] = ("«%s» vince a qualsiasi volume: prezzo €/MWh e fissi "
                               "non lasciano spazio all'altra offerta."
                               % (pa["nome"] if win == "A" else pb["nome"]))
        else:
            out["volume_pareggio_mwh"] = v_star
            # a volumi bassi vince chi ha i fissi piu' bassi
            win_bassi = "A" if pa["fisso"] <= pb["fisso"] else "B"
            win_alti = "B" if win_bassi == "A" else "A"
            out["vincitore_bassi_volumi"] = win_bassi
            out["vincitore_alti_volumi"] = win_alti
            if v_star > volume_max_mwh:
                out["verdetto"] = ("Break-even a %s MWh/anno, oltre il volume massimo "
                                   "analizzato (%s): nel range vince «%s»."
                                   % (_fmt_mwh(v_star), _fmt_mwh(volume_max_mwh),
                                      pa["nome"] if win_bassi == "A" else pb["nome"]))
            else:
                out["verdetto"] = ("Sotto %s MWh/anno vince «%s», sopra vince «%s»."
                                   % (_fmt_mwh(v_star),
                                      pa["nome"] if win_bassi == "A" else pb["nome"],
                                      pa["nome"] if win_alti == "A" else pb["nome"]))

    volumi = np.linspace(0.0, float(volume_max_mwh), n_punti)
    out["df_curva"] = pd.DataFrame({
        "Volume MWh": np.round(volumi, 2),
        "Costo «%s» €" % pa["nome"]: np.round(volumi * pa["p_eff"] + pa["fisso"], 2),
        "Costo «%s» €" % pb["nome"]: np.round(volumi * pb["p_eff"] + pb["fisso"], 2),
    })
    return out


def calcola_opzione_estensione(prezzo_estensione_eur_mwh, volume_annuo_mwh,
                               forward_anno2_eur_mwh, vol_annua_pct=30.0,
                               tasso_annuo_pct=3.0, giorni_a_decisione=365,
                               n_punti=101):
    """Valuta un'opzione di estensione del contratto come call sul forward.

    Alcuni contratti prevedono il diritto (non l'obbligo) di estendere la
    fornitura di un altro anno al prezzo pattuito K: e' una call europea sul
    prezzo forward dell'anno 2, valutata con Black-76 (sottostante = forward).

    Ritorna: valore totale e unitario dell'opzione (premio equo), valore
    intrinseco, probabilita' di esercizio N(d2), forward di break-even e
    curva valore-vs-forward per il grafico.
    """
    vuoto = {"valido": False, "errore": None, "valore_tot_eur": None,
             "premio_equo_eur_mwh": None, "intrinseco_eur_mwh": None,
             "intrinseco_tot_eur": None, "prob_esercizio_pct": None,
             "forward_breakeven_eur_mwh": None, "verdetto": None,
             "df_curva": None}

    def _num(x):
        return (isinstance(x, (int, float)) and not isinstance(x, bool)
                and x == x and abs(x) != float("inf"))

    for nome, val, cond in [
            ("Prezzo di estensione K", prezzo_estensione_eur_mwh, lambda v: v > 0),
            ("Volume annuo", volume_annuo_mwh, lambda v: v > 0),
            ("Forward anno 2", forward_anno2_eur_mwh, lambda v: v > 0),
            ("Volatilita' annua %", vol_annua_pct, lambda v: v >= 0),
            ("Tasso annuo %", tasso_annuo_pct, lambda v: v > -100.0),
            ("Giorni alla decisione", giorni_a_decisione, lambda v: v > 0)]:
        if not _num(val) or not cond(val):
            return dict(vuoto, errore="%s non valido." % nome)
    if isinstance(n_punti, bool) or not isinstance(n_punti, int) or n_punti < 2:
        return dict(vuoto, errore="n_punti deve essere un intero >= 2.")

    K = float(prezzo_estensione_eur_mwh)
    V = float(volume_annuo_mwh)
    F = float(forward_anno2_eur_mwh)
    sig = float(vol_annua_pct) / 100.0
    r = float(tasso_annuo_pct) / 100.0
    T = float(giorni_a_decisione) / 365.0
    disc = float(np.exp(-r * T))

    intr_mwh = max(F - K, 0.0)
    if sig <= 0.0 or T <= 0.0:
        premio_mwh = disc * intr_mwh
        prob = 1.0 if F > K else 0.0
    else:
        import math
        d1 = (math.log(F / K) + 0.5 * sig * sig * T) / (sig * math.sqrt(T))
        d2 = d1 - sig * math.sqrt(T)
        premio_mwh = disc * (F * _phi_std(d1) - K * _phi_std(d2))
        prob = _phi_std(d2)

    # Forward di break-even: F* tale che premio(F*) = intrinseco atteso nullo
    # -> per una call, approx K + premio pagato; qui lo risolviamo sulla curva.
    f_min, f_max = 0.5 * K, 1.75 * K
    fwd = np.linspace(f_min, f_max, n_punti)
    curva = np.array([disc * max(f - K, 0.0) if sig <= 0.0 else
                      disc * (f * _phi_std((np.log(f / K) + 0.5 * sig * sig * T)
                                            / (sig * np.sqrt(T)))
                              - K * _phi_std((np.log(f / K) + 0.5 * sig * sig * T)
                                             / (sig * np.sqrt(T))
                                             - sig * np.sqrt(T)))
                      for f in fwd])
    intr_curva = np.maximum(fwd - K, 0.0)

    if prob >= 0.75:
        verdetto = ("Estensione molto probabile (%.0f%%): il diritto vale "
                    "€ %s — negoziare il premio sotto il fair value."
                    % (prob * 100.0, _fmt_mwh(premio_mwh * V)))
    elif prob >= 0.4:
        verdetto = ("Estensione possibile (%.0f%%): vale € %s come "
                    "assicurazione contro rialzi del forward."
                    % (prob * 100.0, _fmt_mwh(premio_mwh * V)))
    else:
        verdetto = ("Estensione improbabile (%.0f%%): il forward e' sotto K, "
                    "il diritto vale solo € %s di valore temporale."
                    % (prob * 100.0, _fmt_mwh(premio_mwh * V)))

    out = dict(vuoto)
    out.update({
        "valido": True,
        "valore_tot_eur": round(premio_mwh * V, 2),
        "premio_equo_eur_mwh": round(premio_mwh, 4),
        "intrinseco_eur_mwh": round(intr_mwh, 4),
        "intrinseco_tot_eur": round(disc * intr_mwh * V, 2),
        "prob_esercizio_pct": round(prob * 100.0, 2),
        "forward_breakeven_eur_mwh": round(K + premio_mwh, 2),
        "verdetto": verdetto,
        "df_curva": pd.DataFrame({
            "Forward €/MWh": np.round(fwd, 2),
            "Valore opzione €/MWh": np.round(curva, 4),
            "Intrinseco €/MWh": np.round(intr_curva, 4),
        }),
    })
    return out


def _fmt_mwh(v):
    return ("%s" % f"{v:,.0f}").replace(",", ".")


def calcola_van_offerte_pluriennali(offerte, volume_annuo_mwh, tasso_annuo_pct,
                                    forward_base_eur_mwh,
                                    escalation_annua_pct=0.0):
    """VAN di offerte di fornitura pluriennali con durate diverse.

    Domanda operativa: "mi conviene il fisso a 1 anno a 120 €/MWh o il
    fisso a 3 anni a 132 €/MWh?" Le offerte con durata diversa non si
    confrontano sul solo prezzo energia: l'offerta corta va "rinnovata"
    negli anni oltre la sua durata al prezzo forward atteso, e tutti i
    flussi vanno attualizzati al tasso di sconto. Vince il VAN (Valore
    Attuale Netto) minore, calcolato sul comune orizzonte
    H = durata massima tra le offerte.

    Ogni offerta e' un dict con: nome (str), prezzo_eur_mwh (> 0),
    durata_anni (intero 1..10), canone_fisso_eur_mese (default 0),
    attivazione_eur (default 0, una tantum a t=0, non attualizzata).
    Costo anno k (1..H): se k <= durata: V*P + 12*canone, altrimenti
    V*F_k + 12*canone, con F_k = forward_base*(1+g)^(k-1).
    VAN = attivazione + Σ costo_k/(1+r)^k.
    Rata equivalente annua = VAN*r/(1-(1+r)^-H) se r > 0, altrimenti VAN/H.

    Differenza dagli altri tab: 'Rinnovo vs switch' confronta TCO annui a
    parita' di orizzonte; qui durate diverse si confrontano in VAN con
    rinnovo al forward atteso oltre la scadenza.

    NaN-safe: input non numerici / durate non intere / valori fuori range
    -> errore pulito, mai eccezioni. Deterministica.
    """
    def _num(x):
        return (isinstance(x, (int, float)) and not isinstance(x, bool)
                and x == x and abs(x) != float("inf"))

    vuoto = {"ok": False, "valido": False, "errore": None}
    if not isinstance(offerte, (list, tuple)) or len(offerte) < 2:
        return dict(vuoto, errore="Servono almeno 2 offerte da confrontare.")
    righe = []
    visti = set()
    for i, off in enumerate(offerte):
        tag = "Offerta #%d" % (i + 1)
        if not isinstance(off, dict):
            return dict(vuoto, errore="%s: formato non valido (serve un dict)." % tag)
        nome = off.get("nome")
        if not isinstance(nome, str) or not nome.strip():
            return dict(vuoto, errore="%s: nome mancante." % tag)
        nome = nome.strip()
        if nome in visti:
            return dict(vuoto, errore="Nome offerta duplicato: «%s»." % nome)
        visti.add(nome)
        prezzo = off.get("prezzo_eur_mwh")
        durata = off.get("durata_anni")
        canone = off.get("canone_fisso_eur_mese", 0.0)
        attiv = off.get("attivazione_eur", 0.0)
        if not _num(prezzo) or prezzo <= 0:
            return dict(vuoto, errore="«%s»: prezzo €/MWh deve essere > 0." % nome)
        _di = None
        if isinstance(durata, bool):
            pass
        elif isinstance(durata, int):
            _di = durata
        elif isinstance(durata, float) and durata.is_integer():
            _di = int(durata)
        elif isinstance(durata, (np.integer,)) and not isinstance(durata, bool):
            _di = int(durata)
        elif isinstance(durata, (np.floating,)) and float(durata).is_integer():
            _di = int(durata)
        if _di is None or not (1 <= _di <= 10):
            return dict(vuoto,
                        errore="«%s»: durata_anni deve essere un intero tra 1 e 10." % nome)
        if not _num(canone) or canone < 0:
            return dict(vuoto, errore="«%s»: canone €/mese deve essere >= 0." % nome)
        if not _num(attiv) or attiv < 0:
            return dict(vuoto, errore="«%s»: attivazione € deve essere >= 0." % nome)
        righe.append({"nome": nome, "prezzo": float(prezzo), "durata": _di,
                      "canone": float(canone), "attiv": float(attiv)})
    for etichetta, val, ok in (
            ("Volume annuo MWh", volume_annuo_mwh, lambda v: v > 0),
            ("Tasso annuo %", tasso_annuo_pct, lambda v: 0.0 <= v <= 50.0),
            ("Forward base €/MWh", forward_base_eur_mwh, lambda v: v > 0),
            ("Escalation annua %", escalation_annua_pct, lambda v: -50.0 <= v <= 100.0)):
        if not _num(val) or not ok(val):
            return dict(vuoto, errore="%s: valore non valido." % etichetta)
    V = float(volume_annuo_mwh)
    r = float(tasso_annuo_pct) / 100.0
    F0 = float(forward_base_eur_mwh)
    g = float(escalation_annua_pct) / 100.0
    H = max(o["durata"] for o in righe)
    fwd = [F0 * (1.0 + g) ** (k - 1) for k in range(1, H + 1)]
    van, rata, costi_att = {}, {}, {}
    for o in righe:
        ck = []
        for k in range(1, H + 1):
            p = o["prezzo"] if k <= o["durata"] else fwd[k - 1]
            ck.append((V * p + 12.0 * o["canone"]) / (1.0 + r) ** k)
        v = o["attiv"] + sum(ck)
        van[o["nome"]] = v
        rata[o["nome"]] = (v * r / (1.0 - (1.0 + r) ** (-H)) if r > 0
                           else v / H)
        costi_att[o["nome"]] = ck
    nomi = [o["nome"] for o in righe]
    vincitore = min(nomi, key=lambda n: van[n])
    peggiore = max(nomi, key=lambda n: van[n])
    risparmio = van[peggiore] - van[vincitore]
    df_anni = pd.DataFrame({"Anno": list(range(1, H + 1)),
                            "Forward €/MWh": [round(f, 2) for f in fwd]})
    for n in nomi:
        df_anni["Costo att. «%s» €" % n] = [round(c, 2) for c in costi_att[n]]
    df_riep = pd.DataFrame([{
        "Offerta": o["nome"],
        "Prezzo €/MWh": o["prezzo"],
        "Durata anni": o["durata"],
        "Canone €/mese": o["canone"],
        "Attivazione €": o["attiv"],
        "VAN €": round(van[o["nome"]], 2),
        "Rata equiv. €/anno": round(rata[o["nome"]], 2),
    } for o in righe]).sort_values("VAN €").reset_index(drop=True)
    verdetto = ("«%s» vince sul VAN a %d anni: € %s contro € %s della peggiore "
                "(«%s»), risparmio € %s. Rata equivalente € %s/anno." % (
                    vincitore, H,
                    "{:,.0f}".format(van[vincitore]).replace(",", "."),
                    "{:,.0f}".format(van[peggiore]).replace(",", "."),
                    peggiore,
                    "{:,.0f}".format(risparmio).replace(",", "."),
                    "{:,.0f}".format(rata[vincitore]).replace(",", ".")))
    out = dict(vuoto)
    out.update({
        "valido": True,
        "orizzonte_anni": H,
        "forward_annui": fwd,
        "van": van,
        "rata_equivalente": rata,
        "vincitore": vincitore,
        "peggiore": peggiore,
        "risparmio": risparmio,
        "df_anni": df_anni,
        "df_riepilogo": df_riep,
        "verdetto": verdetto,
    })
    return out


def calcola_opzione_differimento(V, K, T_anni, vol_pct, tasso_pct,
                               dy_pct=0.0, n_step=200):
    """Opzione REALE di differimento di un investimento energetico.

    Investire subito in un impianto (batteria, FV, CCGT...) quando i prezzi
    sono volatili equivale a esercitare immediatamente una call AMERICANA sul
    valore attuale del progetto V con strike = CAPEX K. Aspettare ha un
    valore: l'opzione di differimento, prezzata qui con un albero binomiale
    CRR sul valore del progetto.

    Parametri:
    V: valore attuale del progetto (€, PV dei flussi attesi a prezzi correnti);
    K: CAPEX (€, strike dell'opzione); T_anni: orizzonte entro cui si puo'
    decidere (anni, >= 0); vol_pct: volatilita' annua del valore del progetto
    (%); tasso_pct: tasso risk-free annuo (%); dy_pct: dividend yield annuo
    (%): flussi/mancati ricavi persi restando fermi (e' il COSTO dell'attesa:
    piu' e' alto, piu' conviene investire subito); n_step: passi dell'albero.

    Albero CRR sul valore spot con cost of carry b = r - dy:
      dt = T/N; u = exp(sig*sqrt(dt)); d = 1/u;
      p = (exp(b*dt) - d)/(u - d) (risk-neutral); df = exp(-r*dt).
    Backward induction con esercizio anticipato a ogni nodo:
      V_nodo = max(intrinseco, df*(p*V_up + (1-p)*V_down)).
    Soglia critica V*: bisezione sul V per cui l'esercizio immediato diventa
    ottimale (opzione == V - K); se dy = 0 e r = 0 non conviene mai
    esercitare prima -> soglia None (corretto: senza costo dell'attesa ne'
    interessi, aspettare e' sempre gratis).

    Ritorna dict con 'errore' (None se ok), 'valido', 'valore_opzione'
    (americana), 'valore_europea' (stesso albero), 'early_premium',
    'van_immediato' (V - K), 'valore_attesa' (opzione - max(V-K,0) >= 0),
    'soglia_critica' (V* o None), 'decisione' ('INVESTI ORA' / 'ASPETTA' /
    'NON INVESTIRE'), 'motivo', 'df_vs_V' e 'df_vs_vol' (sensibilita',
    griglia a 100 passi), 'parametri'. Mai eccezioni.
    """
    def _err(msg):
        return {"errore": msg, "valido": False}

    try:
        V = float(V)
        K = float(K)
        T = float(T_anni)
        sig = float(vol_pct) / 100.0
        r = float(tasso_pct) / 100.0
        dy = float(dy_pct) / 100.0
        Ns = float(n_step)
    except (TypeError, ValueError):
        return _err("Parametri non numerici.")
    if not all(np.isfinite(x) for x in (V, K, T, sig, r, dy, Ns)):
        return _err("Parametri non validi (NaN o infiniti).")
    if V <= 0:
        return _err("V non valido (valore progetto deve essere > 0).")
    if K <= 0:
        return _err("K non valido (CAPEX deve essere > 0).")
    if T < 0:
        return _err("T_anni non valido (deve essere >= 0).")
    if sig < 0 or sig > 5.0:
        return _err("vol_pct non valida (0-500%).")
    if r < -0.05 or r > 1.0:
        return _err("tasso_pct non valido (-5%..100%).")
    if dy < 0 or dy > 1.0:
        return _err("dy_pct non valido (0-100%).")
    if not Ns.is_integer() or not 1 <= Ns <= 500:
        return _err("n_step non valido (intero 1-500).")
    N = int(Ns)

    def _crr(v0, k0, t0, s0, r0, d0, n0, americana=True):
        """Prezzo CRR di una call su spot con dividend yield. Ritorna float."""
        intr = max(v0 - k0, 0.0)
        if t0 <= 0.0 or s0 <= 0.0:
            return intr
        dt = t0 / n0
        u = np.exp(s0 * np.sqrt(dt))
        d = 1.0 / u
        b = r0 - d0
        disc = np.exp(-r0 * dt)
        den = u - d
        if den <= 0:
            return intr
        p = (np.exp(b * dt) - d) / den
        if not (0.0 < p < 1.0):
            return float("nan")
        j = np.arange(n0 + 1)
        st = v0 * (u ** j) * (d ** (n0 - j))
        vals = np.maximum(st - k0, 0.0)
        for i in range(n0, 0, -1):
            vals = disc * (p * vals[1:] + (1.0 - p) * vals[:-1])
            if americana:
                jj = np.arange(i)
                si = v0 * (u ** jj) * (d ** ((i - 1) - jj))
                intr_i = si - k0
                vals = np.where(intr_i > vals, np.maximum(intr_i, 0.0),
                                vals)
        return float(vals[0])

    try:
        am = _crr(V, K, T, sig, r, dy, N, americana=True)
        eu = _crr(V, K, T, sig, r, dy, N, americana=False)
        if not (np.isfinite(am) and np.isfinite(eu)):
            return _err("Parametri estremi: probabilita' risk-neutral "
                        "fuori (0,1), riduci volatilita'/dividend yield.")
        eu = min(eu, am)
        intr_now = max(V - K, 0.0)
        attesa = max(am - intr_now, 0.0)
        early = am - eu
        van = V - K

        # Soglia critica V*: bisezione su f(x) = americana(x) - (x - K).
        soglia = None
        if sig > 0.0 and T > 0.0 and not (dy == 0.0 and r == 0.0):
            def _f(x):
                return _crr(x, K, T, sig, r, dy, N, americana=True) - (x - K)

            lo, hi = K, max(2.0 * K, K * 1.5)
            f_hi = _f(hi)
            while f_hi > 1e-6 * hi and hi < 1e9 * K:
                hi *= 2.0
                f_hi = _f(hi)
            if f_hi <= 1e-6 * hi:
                for _ in range(60):
                    mid = 0.5 * (lo + hi)
                    if _f(mid) > 0:
                        lo = mid
                    else:
                        hi = mid
                soglia = float(0.5 * (lo + hi))
        elif sig <= 0.0 or T <= 0.0:
            soglia = float(K)

        if van <= 0:
            if attesa > 0.005 * V:
                decisione = "NON INVESTIRE ORA"
                motivo = ("VAN negativo: investire oggi distrugge valore. "
                          "L'opzione di attesa vale %s €: rivaluta se V sale "
                          "o se il CAPEX scende." % ("%.0f" % attesa))
            else:
                decisione = "NON INVESTIRE"
                motivo = ("VAN negativo e attesa senza valore: il progetto "
                          "non conviene ne' ora ne' come scommessa sul "
                          "futuro.")
        elif attesa <= 0.005 * V:
            decisione = "INVESTI ORA"
            motivo = ("Il valore dell'attesa e' trascurabile (%s €): ogni "
                      "giorno di ritardo costa piu' di quanto l'opzione "
                      "renda." % ("%.0f" % attesa))
        else:
            decisione = "ASPETTA"
            motivo = ("Aspettare vale %s € piu' che investire oggi: la "
                      "volatilita' rende l'opzione di differimento "
                      "preziosa. Investi solo se V supera %s €."
                      % (("%.0f" % attesa),
                         ("%.0f" % soglia) if soglia else "n.d."))

        # Sensibilita' (griglia a 100 passi: veloce e deterministica).
        Ns2 = 100
        v_lo, v_hi = 0.3 * K, max(2.5 * K, V * 1.5)
        vv = np.linspace(v_lo, v_hi, 21)
        righe_v = []
        for x in vv:
            a = _crr(float(x), K, T, sig, r, dy, Ns2, americana=True)
            righe_v.append((float(x), a, float(x) - K,
                            max(a - max(float(x) - K, 0.0), 0.0)))
        df_v = pd.DataFrame(righe_v, columns=[
            "V_progetto (EUR)", "Opzione (EUR)", "VAN immediato (EUR)",
            "Valore attesa (EUR)"])
        s_grid = np.linspace(0.0, min(1.0, max(sig * 2.0, 0.2)), 11)
        righe_s = []
        for s in s_grid:
            a = _crr(V, K, T, float(s), r, dy, Ns2, americana=True)
            righe_s.append((float(s) * 100.0, a,
                            max(a - intr_now, 0.0)))
        df_s = pd.DataFrame(righe_s, columns=[
            "Volatilita' (%)", "Opzione (EUR)", "Valore attesa (EUR)"])

        return {"errore": None, "valido": True,
                "valore_opzione": am, "valore_europea": eu,
                "early_premium": early, "van_immediato": van,
                "valore_attesa": attesa, "soglia_critica": soglia,
                "decisione": decisione, "motivo": motivo,
                "df_vs_V": df_v, "df_vs_vol": df_s,
                "parametri": {"V": V, "K": K, "T_anni": T,
                              "vol_pct": float(vol_pct),
                              "tasso_pct": float(tasso_pct),
                              "dy_pct": float(dy_pct), "n_step": N}}
    except Exception as e:  # pragma: no cover - guardia totale
        return {"errore": "Errore interno: %s" % e, "valido": False}

# WORKSPACE 1: SIMULATORE STRATEGICO
# =========================================="

# ---------- W231: funzioni pure qualita dati (nessuno streamlit qui dentro) ----------

def dq231_genera_serie(n_ore, prezzo_base, rumore_std, n_outlier, amp_outlier,
                       n_gap, max_gap_ore, seed):
    # Serie sintetica oraria di prezzi. Ritorna (df[timestamp, prezzo], outlier_iniettati_ts).
    rng = np.random.default_rng(seed)
    ore = np.arange(n_ore)
    profilo = 12.0 * np.sin(2.0 * np.pi * ore / 24.0) + 6.0 * np.sin(2.0 * np.pi * ore / 168.0)
    prezzi = prezzo_base + profilo + rng.normal(0.0, rumore_std, n_ore)
    ts = pd.date_range("2026-01-01", periods=n_ore, freq="h")
    n_out = int(min(n_outlier, n_ore))
    pos = rng.choice(n_ore, size=n_out, replace=False) if n_out > 0 else np.array([], dtype=int)
    segni = np.where(rng.random(len(pos)) < 0.5, -1.0, 1.0)
    prezzi[pos] = prezzi[pos] + segni * amp_outlier * rng.uniform(1.0, 2.0, len(pos))
    inj_ts = [ts[p] for p in sorted(pos.tolist())]
    df = pd.DataFrame({"timestamp": ts, "prezzo": prezzi})
    da_togliere = set()
    for _ in range(int(n_gap)):
        lunghezza = int(rng.integers(1, int(max_gap_ore) + 1))
        inizio = int(rng.integers(0, max(n_ore - lunghezza, 1)))
        da_togliere.update(range(inizio, min(inizio + lunghezza, n_ore)))
    df = df.drop(index=sorted(da_togliere)).reset_index(drop=True)
    return df, inj_ts


def dq231_detect_gaps(df):
    # Ritorna lista di dict {'inizio','fine','ore_mancanti'} per i buchi nella griglia oraria.
    if df is None or df.empty:
        return []
    ts = pd.to_datetime(df["timestamp"]).sort_values().reset_index(drop=True)
    atteso = pd.date_range(ts.min(), ts.max(), freq="h")
    mancanti = atteso.difference(ts)
    gap = []
    for t in mancanti:
        if gap and t == gap[-1]["fine"] + pd.Timedelta(hours=1):
            gap[-1]["fine"] = t
            gap[-1]["ore_mancanti"] += 1
        else:
            gap.append({"inizio": t, "fine": t, "ore_mancanti": 1})
    return gap


def dq231_detect_outliers_iqr(df, k=1.5):
    # Outlier con metodo IQR. Ritorna dict con mask, soglie e statistiche.
    if df is None or df.empty:
        return {"mask": np.zeros(0, dtype=bool), "q1": float("nan"),
                "q3": float("nan"), "iqr": float("nan"),
                "soglia_bassa": float("nan"), "soglia_alta": float("nan"),
                "n_outlier": 0}
    v = df["prezzo"].to_numpy(dtype=float)
    q1 = float(np.quantile(v, 0.25))
    q3 = float(np.quantile(v, 0.75))
    iqr = q3 - q1
    lo = q1 - k * iqr
    hi = q3 + k * iqr
    mask = (v < lo) | (v > hi)
    return {"mask": mask, "q1": q1, "q3": q3, "iqr": float(iqr),
            "soglia_bassa": float(lo), "soglia_alta": float(hi),
            "n_outlier": int(mask.sum())}


def dq231_detect_spikes(df, soglia_pct=50.0):
    # Spike: variazione % in valore assoluto rispetto all'ora precedente oltre soglia.
    if df is None or df.empty:
        return {"mask": np.zeros(0, dtype=bool),
                "variazioni_pct": np.zeros(0), "n_spike": 0}
    v = df["prezzo"].to_numpy(dtype=float)
    if len(v) < 2:
        return {"mask": np.zeros(len(v), dtype=bool),
                "variazioni_pct": np.full(len(v), np.nan), "n_spike": 0}
    prev = v[:-1]
    cur = v[1:]
    with np.errstate(divide="ignore", invalid="ignore"):
        var = np.abs((cur - prev) / np.where(prev != 0, prev, np.nan)) * 100.0
    var = np.concatenate([[np.nan], var])
    mask = np.zeros(len(v), dtype=bool)
    mask[1:] = var[1:] > soglia_pct
    return {"mask": mask, "variazioni_pct": var, "n_spike": int(mask.sum())}


def dq231_quality_summary(df, gaps, out_res, spike_res):
    # KPI riepilogativi. Ritorna dict.
    ore_mancanti = int(sum(g["ore_mancanti"] for g in gaps))
    ore_effettive = int(len(df)) if df is not None else 0
    ore_attese = ore_effettive + ore_mancanti
    gap_max = int(max([g["ore_mancanti"] for g in gaps], default=0))
    mask_unione = out_res["mask"] | spike_res["mask"]
    n_anomale = int(mask_unione.sum())
    return {
        "ore_attese": ore_attese,
        "ore_effettive": ore_effettive,
        "ore_mancanti": ore_mancanti,
        "pct_ore_mancanti": (100.0 * ore_mancanti / ore_attese) if ore_attese else 0.0,
        "n_gap": len(gaps),
        "gap_piu_lungo_ore": gap_max,
        "n_outlier": int(out_res["n_outlier"]),
        "n_spike": int(spike_res["n_spike"]),
        "n_ore_anomale": n_anomale,
        "pct_ore_anomale": (100.0 * n_anomale / ore_effettive) if ore_effettive else 0.0,
    }

