def profilo_carico_sintetico_t235(ore=24, base_kw=50.0, picco_kw=150.0,
                                  ora_picco=12.0, larghezza_picco=3.0,
                                  rumore_pct=0.0, seed=235):
    """Profilo di carico sintetico (kW): base + picco gaussiano + rumore."""
    n = int(ore)
    t = np.arange(n, dtype=float)
    w = max(float(larghezza_picco), 0.5)
    profilo = float(base_kw) + (float(picco_kw) - float(base_kw)) * np.exp(
        -0.5 * ((t - float(ora_picco)) / w) ** 2)
    if float(rumore_pct) > 0.0:
        rng = np.random.default_rng(int(seed))
        profilo = profilo * (1.0 + rng.normal(0.0, float(rumore_pct) / 100.0, size=n))
    return np.maximum(profilo, 0.0)


def profilo_prezzo_sintetico_t235(ore=24, base_eur_mwh=80.0, picco_eur_mwh=250.0,
                                   ora_picco=18.0, larghezza_picco=2.0,
                                   rumore_pct=0.0, seed=236):
    """Profilo di prezzo sintetico (eur/MWh): base + picco serale + rumore."""
    n = int(ore)
    t = np.arange(n, dtype=float)
    w = max(float(larghezza_picco), 0.5)
    profilo = float(base_eur_mwh) + (float(picco_eur_mwh) - float(base_eur_mwh)) * np.exp(
        -0.5 * ((t - float(ora_picco)) / w) ** 2
    )
    if float(rumore_pct) > 0.0:
        rng = np.random.default_rng(int(seed))
        profilo = profilo * (1.0 + rng.normal(0.0, float(rumore_pct) / 100.0, size=n))
    return np.maximum(profilo, 0.5)


def load_price_corr(load_kw, prezzo_eur_mwh, top_n=4):
    """Correlazione tra profilo di carico (kW orari) e prezzo orario (eur/MWh).

    Ritorna un dict con:
      r_pearson, r_spearman: correlazione lineare / di rango [-1, 1]
      costo_effettivo_eur: somma(carico_kWh * prezzo) sul periodo
      costo_scorrelato_eur: stesso consumo totale ma profilo piatto
        (nessuna concomitanza carico-prezzo)
      extra_costo_vs_scorrelato_eur: differenza (positivo = paghi di piu'
        perche' consumi nelle ore care)
      ore_top_concomitanti: ore tra le top_n di carico E le top_n di prezzo
    """
    try:
        load = np.asarray(load_kw, dtype=float).ravel()
        prezzo = np.asarray(prezzo_eur_mwh, dtype=float).ravel()
    except (ValueError, TypeError):
        return {"valido": False, "errore": "Input non numerici."}
    if load.size != prezzo.size:
        return {"valido": False, "errore": "Carico e prezzo devono avere la stessa lunghezza."}
    n = int(load.size)
    if n < 3:
        return {"valido": False, "errore": "Servono almeno 3 osservazioni orarie."}
    if bool(np.isnan(load).any()) or bool(np.isnan(prezzo).any()):
        return {"valido": False, "errore": "Valori mancanti (NaN) nelle serie."}
    # Pearson e ranghi medi calcolati a mano (funzione autocontenuta: niente scipy)
    def _pearson(x, y):
        xc = x - x.mean()
        yc = y - y.mean()
        den = float(np.sqrt(float((xc ** 2).sum()) * float((yc ** 2).sum())))
        if den <= 0.0:
            return 0.0
        return max(-1.0, min(1.0, float((xc * yc).sum() / den)))

    def _ranghi(a):
        order = np.argsort(a, kind="mergesort")
        ranks = np.empty(int(a.size), dtype=float)
        i, nn = 0, int(a.size)
        while i < nn:
            j = i
            while j + 1 < nn and a[order[j + 1]] == a[order[i]]:
                j += 1
            ranks[order[i:j + 1]] = (i + j) / 2.0 + 1.0
            i = j + 1
        return ranks

    r_p = _pearson(load, prezzo)
    r_s = _pearson(_ranghi(load), _ranghi(prezzo))
    costo_effettivo = float(np.sum(load * prezzo) / 1000.0)
    costo_scorrelato = float(load.mean() * prezzo.sum() / 1000.0)
    extra = costo_effettivo - costo_scorrelato
    k = max(1, min(int(top_n), n))
    idx_l = set(np.argsort(load)[-k:].tolist())
    idx_p = set(np.argsort(prezzo)[-k:].tolist())
    concomitanti = len(idx_l & idx_p)
    if r_p >= 0.5:
        verdetto = ("Profilo SFORTUNATO: il carico e' concentrato nelle ore piu' care. "
                    "Spostare consumi fuori picco riduce il costo.")
    elif r_p <= -0.5:
        verdetto = ("Profilo FORTUNATO: il carico e' concentrato nelle ore piu' economiche. "
                    "Il profilo lavora a favore del prezzo.")
    else:
        verdetto = ("Profilo NEUTRO: nessuna correlazione forte tra carico e prezzo "
                    "(|r di Pearson| < 0,5).")
    return {
        "valido": True,
        "errore": "",
        "n": n,
        "r_pearson": r_p,
        "r_spearman": r_s,
        "costo_effettivo_eur": costo_effettivo,
        "costo_scorrelato_eur": costo_scorrelato,
        "extra_costo_vs_scorrelato_eur": extra,
        "ore_top_concomitanti": concomitanti,
        "top_n": k,
        "verdetto": verdetto,
    }


def checklist_score(items):
    """Score ponderato di una offerta.
    items: list di (voce, peso_pct, score) con score in [0, 5].
    Ritorna dict(totale_ponderato, dettaglio, somma_pesi, pesi_validi).
    """
    dettaglio = []
    somma_pesi = 0.0
    accumulo = 0.0
    for voce, peso, score in items:
        try:
            p = float(peso)
            s = float(score)
        except (TypeError, ValueError):
            p, s = 0.0, 0.0
        s = max(0.0, min(5.0, s))
        p = max(0.0, p)
        somma_pesi += p
        accumulo += p * s
        dettaglio.append({"Voce": voce, "Peso (%)": round(p, 1),
                          "Punteggio": round(s, 1),
                          "Ponderato": round(p * s, 2)})
    totale = accumulo / somma_pesi if somma_pesi > 0 else 0.0
    return {"totale_ponderato": round(totale, 3),
            "dettaglio": dettaglio,
            "somma_pesi": round(somma_pesi, 1),
            "pesi_validi": 0 < somma_pesi <= 100}


def rank_offers(offerte):
    """Classifica fino a 3 offerte. offerte: list di (nome, items).
    Ritorna lista di dict ordinata per score decrescente."""
    righe = []
    for nome, items in offerte:
        ris = checklist_score(items)
        righe.append({"offerta": nome,
                      "score": ris["totale_ponderato"],
                      "dettaglio": ris["dettaglio"],
                      "somma_pesi": ris["somma_pesi"]})
    righe.sort(key=lambda r: r["score"], reverse=True)
    for i, r in enumerate(righe, start=1):
        r["posizione"] = i
    return righe



def night_share238(load_kw, price_eur_mwh, ore_notte=None):
    """Quota e costi della fascia notturna su un profilo di 24 ore (funzione pura).

    load_kw: 24 valori orari di carico (kW); price_eur_mwh: 24 prezzi orari (eur/MWh).
    Ritorna dict con quota, energia_notte_kwh, energia_giorno_kwh, costo_notte,
    costo_giorno, prezzo_medio_notte, prezzo_medio_giorno, rapporto, ore_notte.
    """
    load = [float(x) for x in load_kw]
    price = [float(x) for x in price_eur_mwh]
    if len(load) != 24 or len(price) != 24:
        raise ValueError("load_kw e price_eur_mwh devono avere 24 valori orari")
    ore = list(ore_notte) if ore_notte is not None else [22, 23, 0, 1, 2, 3, 4, 5]
    notte = [h for h in ore if 0 <= h < 24]
    if not notte:
        raise ValueError("nessuna ora notturna valida")
    giorno = [h for h in range(24) if h not in set(notte)]
    en_notte = sum(load[h] for h in notte)
    en_tot = sum(load)
    costo_notte = sum(load[h] * price[h] for h in notte) / 1000.0
    costo_giorno = sum(load[h] * price[h] for h in giorno) / 1000.0
    p_notte = sum(price[h] for h in notte) / len(notte)
    p_giorno = sum(price[h] for h in giorno) / len(giorno) if giorno else 0.0
    return {
        "quota": en_notte / en_tot if en_tot > 0 else 0.0,
        "energia_notte_kwh": en_notte,
        "energia_giorno_kwh": en_tot - en_notte,
        "costo_notte": costo_notte,
        "costo_giorno": costo_giorno,
        "prezzo_medio_notte": p_notte,
        "prezzo_medio_giorno": p_giorno,
        "rapporto": (p_notte / p_giorno) if p_giorno > 0 else 0.0,
        "ore_notte": notte,
    }


def ghost_load238(load_kw, ore_notte=None):
    """Carico fantasma: minimo notturno mai spento (kW) su un profilo di 24 ore (funzione pura)."""
    load = [float(x) for x in load_kw]
    if len(load) != 24:
        raise ValueError("load_kw deve avere 24 valori orari")
    ore = list(ore_notte) if ore_notte is not None else [22, 23, 0, 1, 2, 3, 4, 5]
    notte = [h for h in ore if 0 <= h < 24]
    if not notte:
        raise ValueError("nessuna ora notturna valida")
    return min(load[h] for h in notte)


def profilo_sintetico238(base_kw, picco_kw, ora_picco, fattore_serale):
    """Profilo 24h sintetico: baseload costante + gaussiana diurna + coda serale (funzione pura)."""
    prof = []
    for h in range(24):
        gauss = picco_kw * np.exp(-((h - ora_picco) ** 2) / (2 * 4.0 ** 2))
        sera = fattore_serale * picco_kw * np.exp(-((h - 20.0) ** 2) / (2 * 2.5 ** 2)) if h >= 15 else 0.0
        prof.append(round(base_kw + gauss + sera, 3))
    return prof


def clc236_carico_residuo(carico_kw, fv_kw):
    """Carico residuo orario = carico - FV (kW). Valori negativi = surplus immesso."""
    import numpy as np
    carico = np.asarray(list(carico_kw), dtype=float)
    fv = np.asarray(list(fv_kw), dtype=float)
    if fv.shape != carico.shape:
        raise ValueError("carico e fv devono avere la stessa lunghezza")
    return carico - fv


def clc236_duration_curve(serie):
    """Curva di durata: valori ordinati in senso decrescente."""
    import numpy as np
    s = np.asarray(list(serie), dtype=float)
    return np.sort(s)[::-1]


def clc236_kpi_anno(carico_kw, fv_kw):
    """KPI annuali su una serie oraria (tipicamente 8760 ore)."""
    import numpy as np
    residuo = clc236_carico_residuo(carico_kw, fv_kw)
    ore_surplus = int((residuo < 0).sum())
    energia_surplus = float(-residuo[residuo < 0].sum())
    energia_residua = float(residuo[residuo > 0].sum())
    fv_tot = float(np.asarray(list(fv_kw), dtype=float).sum())
    autoconsumo = float(1.0 - energia_surplus / fv_tot) if fv_tot > 0 else 1.0
    return {
        "ore_surplus": ore_surplus,
        "energia_surplus_kwh": round(energia_surplus, 1),
        "energia_residua_kwh": round(energia_residua, 1),
        "picco_residuo_kw": round(float(residuo.max()), 2),
        "picco_lordo_kw": round(float(np.asarray(list(carico_kw), dtype=float).max()), 2),
        "autoconsumo_pct": round(autoconsumo * 100.0, 1),
    }


def clc236_profilo_giornaliero(base_kw, picco_matt_kw, ora_picco_matt, picco_sera_kw, ora_picco_sera):
    """Profilo giornaliero sintetico 24h: baseload + due gaussiane (mattina/sera)."""
    import numpy as np
    h = np.arange(24)
    prof = (base_kw
            + picco_matt_kw * np.exp(-((h - ora_picco_matt) ** 2) / 8.0)
            + picco_sera_kw * np.exp(-((h - ora_picco_sera) ** 2) / 8.0))
    return [round(float(x), 3) for x in prof]


def clc236_fv_giornaliero(kwp, ora_picco_fv, fattore_nuvola):
    """Produzione FV giornaliera sintetica 24h: campana diurna attenuata dalle nuvole."""
    import numpy as np
    h = np.arange(24)
    fv = kwp * np.exp(-((h - ora_picco_fv) ** 2) / 18.0) * (1.0 - fattore_nuvola)
    return [round(float(max(x, 0.0)), 3) for x in fv]


def flx237_top_bottom(load_kw, price_eur_mwh, quota_top=0.10):
    """Indici delle ore piu' care (top quota) e piu' economiche (bottom quota)."""
    import numpy as np
    price = np.asarray(list(price_eur_mwh), dtype=float)
    n = price.size
    k = max(1, int(round(n * quota_top)))
    idx_top = np.argsort(price)[-k:]
    idx_bottom = np.argsort(price)[:k]
    return idx_top.tolist(), idx_bottom.tolist()


def flx237_shifting_saving(load_kw, price_eur_mwh, pct_shift=0.5, quota_top=0.10):
    """Risparmio spostando pct_shift del carico dalle ore top alle ore bottom."""
    import numpy as np
    load = np.asarray(list(load_kw), dtype=float)
    price = np.asarray(list(price_eur_mwh), dtype=float)
    if load.shape != price.shape:
        raise ValueError("carico e prezzo devono avere la stessa lunghezza")
    idx_top, idx_bottom = flx237_top_bottom(load, price, quota_top)
    e_top = float(load[idx_top].sum())
    spostabile = e_top * pct_shift
    p_top = float(price[idx_top].mean())
    p_bottom = float(price[idx_bottom].mean())
    risparmio = spostabile * (p_top - p_bottom) / 1000.0
    costo_base = float((load * price).sum() / 1000.0)
    return {
        "energia_spostabile_kwh": round(spostabile, 1),
        "risparmio_eur": round(risparmio, 2),
        "risparmio_pct": round(100.0 * risparmio / costo_base, 2) if costo_base else 0.0,
        "prezzo_medio_top": round(p_top, 2),
        "prezzo_medio_bottom": round(p_bottom, 2),
        "costo_base_eur": round(costo_base, 2),
    }


def flx237_profilo_sintetico(base_kw, picco_kw, ora_picco, seed=0):
    """Profilo di carico giornaliero sintetico 24h con rumore (seed per ripetibilita')."""
    import numpy as np
    rng = np.random.default_rng(seed)
    h = np.arange(24)
    prof = base_kw + picco_kw * np.exp(-((h - ora_picco) ** 2) / 8.0)
    prof = prof * (1 + rng.normal(0, 0.05, 24))
    return [round(float(max(x, 0.0)), 3) for x in prof]


def flx237_prezzo_sintetico(base_eur, ampiezza_eur, ora_picco, seed=0):
    """Prezzo orario sintetico 24h: picco serale + rumore (seed per ripetibilita')."""
    import numpy as np
    rng = np.random.default_rng(seed)
    h = np.arange(24)
    prezzo = base_eur + ampiezza_eur * np.exp(-((h - ora_picco) ** 2) / 12.0)
    prezzo = prezzo * (1 + rng.normal(0, 0.08, 24))
    return [round(float(max(x, 1.0)), 2) for x in prezzo]


def pot242_profilo_annuo(base_kw, picco_kw, ora_picco, stagionalita_pct, seed=242):
    """Profilo di carico orario sintetico per un anno (8760 ore), kW.

    Profilo giornaliero = base + gaussiana centrata sull'ora di picco, con
    stagionalita' sinusoidale (max a luglio, min a gennaio) e rumore 5%.
    Deterministico a parita' di seed. Ritorna lista di 8760 float arrotondati.
    """
    import numpy as np
    base_kw = float(base_kw)
    picco_kw = float(picco_kw)
    ora_picco = float(ora_picco)
    stag = float(stagionalita_pct) / 100.0
    if base_kw < 0 or picco_kw < 0:
        raise ValueError("base_kw e picco_kw devono essere >= 0")
    rng = np.random.default_rng(int(seed))
    out = []
    for d in range(365):
        stag_d = 1.0 + stag * (-np.cos(2.0 * np.pi * (d - 14) / 365.0)) / 2.0 * 2.0
        for h in range(24):
            prof = base_kw + picco_kw * np.exp(-((h - ora_picco) ** 2) / 8.0)
            out.append(prof * stag_d * (1.0 + rng.normal(0, 0.05)))
    return [round(float(max(x, 0.0)), 3) for x in out]


def pot242_picchi_mensili(profilo_kw):
    """Picchi mensili (kW) da una serie oraria annua 8760: 12 massimi su blocchi da 730 h."""
    import numpy as np
    p = np.asarray(list(profilo_kw), dtype=float)
    if p.size != 8760:
        raise ValueError(f"profilo_kw deve avere 8760 ore, trovate {p.size}")
    if np.isnan(p).any():
        raise ValueError("profilo_kw contiene NaN")
    return [round(float(p[i * 730:(i + 1) * 730].max()), 3) for i in range(12)]


def pot242_costo_annuo(picchi_mensili, p_impegnata, fisso_eur_kw_anno, penale_eur_kw_mese):
    """Costo annuo di potenza: fisso sull'impegnata + penale mensile sugli sforamenti.

    penale = sum(max(0, picco_mese - p_impegnata)) * penale_eur_kw_mese.
    """
    import numpy as np
    picchi = np.asarray(list(picchi_mensili), dtype=float)
    if picchi.size != 12:
        raise ValueError("picchi_mensili deve avere 12 valori")
    if np.isnan(picchi).any():
        raise ValueError("picchi_mensili contiene NaN")
    p_impegnata = float(p_impegnata)
    fisso = float(fisso_eur_kw_anno)
    penale_u = float(penale_eur_kw_mese)
    if p_impegnata < 0 or fisso < 0 or penale_u < 0:
        raise ValueError("p_impegnata, fisso_eur_kw_anno e penale_eur_kw_mese devono essere >= 0")
    sforamenti = np.maximum(0.0, picchi - p_impegnata)
    costo_fisso = p_impegnata * fisso
    costo_penale = float(sforamenti.sum()) * penale_u
    return {
        "fisso": round(costo_fisso, 2),
        "penale": round(costo_penale, 2),
        "totale": round(costo_fisso + costo_penale, 2),
        "mesi_sforati": int((sforamenti > 0).sum()),
        "sforamento_max_kw": round(float(sforamenti.max()), 2),
    }


def pot242_curva_ottimo(picchi_mensili, fisso_eur_kw_anno, penale_eur_kw_mese,
                        p_min=0.0, p_max=None, passo=1.0):
    """Sweep sulla potenza impegnata: trova il minimo del costo annuo.

    Ritorna {"p_ottima", "costo_ottimo", "curva": [(p, costo), ...]}.
    p_max default = 1.5 * picco massimo. passo > 0.
    """
    import numpy as np
    picchi = list(picchi_mensili)
    if float(passo) <= 0:
        raise ValueError("passo deve essere > 0")
    p_hi = float(p_max) if p_max is not None else 1.5 * float(max(picchi))
    p_lo = float(p_min)
    if p_hi < p_lo:
        raise ValueError("p_max deve essere >= p_min")
    curva = []
    for p in np.arange(p_lo, p_hi + passo / 2.0, passo):
        c = pot242_costo_annuo(picchi, float(p), fisso_eur_kw_anno, penale_eur_kw_mese)
        curva.append((round(float(p), 3), c["totale"]))
    i_min = min(range(len(curva)), key=lambda i: curva[i][1])
    return {
        "p_ottima": curva[i_min][0],
        "costo_ottimo": curva[i_min][1],
        "curva": curva,
    }


def q243_a_quarti(profilo_orario, picco_intraore_pct=15.0, seed=243):
    """Da una serie oraria (kW) a una serie quartoraria (kW): ogni ora -> 4 quarti.

    Il quarto di picco vale h*(1+delta), gli altri tre h*(1-delta/3): l'energia
    dell'ora si conserva esattamente. Il quarto di picco e' scelto a caso per
    ogni ora (rng con seed -> deterministico). Ore <= 0 -> quarti a zero.
    delta = picco_intraore_pct/100 (ammesso 0..300: oltre, i quarti non di picco
    diventerebbero negativi). Ritorna lista di 4*N float a piena precisione
    (l'energia dell'ora si conserva esattamente: sum(quarti)/4 == sum(ore)).
    """
    import numpy as np
    try:
        h = np.asarray(list(profilo_orario), dtype=float)
    except (TypeError, ValueError):
        raise ValueError("profilo_orario deve essere una sequenza numerica")
    if h.ndim != 1 or h.size < 24:
        raise ValueError(f"profilo_orario deve avere almeno 24 ore, trovate {int(h.size)}")
    if np.isnan(h).any():
        raise ValueError("profilo_orario contiene NaN")
    if isinstance(picco_intraore_pct, bool):
        raise ValueError("picco_intraore_pct deve essere un numero tra 0 e 300")
    try:
        delta = float(picco_intraore_pct) / 100.0
    except (TypeError, ValueError):
        raise ValueError("picco_intraore_pct deve essere un numero tra 0 e 300")
    if delta < 0.0 or delta > 3.0:
        raise ValueError("picco_intraore_pct deve essere tra 0 e 300")
    rng = np.random.default_rng(int(seed))
    out = []
    for v in h:
        v = float(v)
        if v <= 0.0:
            out.extend([0.0, 0.0, 0.0, 0.0])
            continue
        qp = int(rng.integers(0, 4))
        base = v * (1.0 - delta / 3.0)
        qq = [base, base, base, base]
        qq[qp] = v * (1.0 + delta)
        out.extend(qq)
    return [float(x) for x in out]


def q243_picchi_mensili_q(profilo_quarti):
    """Picchi mensili (kW) da una serie quartoraria: 12 massimi (array_split in 12)."""
    import numpy as np
    try:
        q = np.asarray(list(profilo_quarti), dtype=float)
    except (TypeError, ValueError):
        raise ValueError("profilo_quarti deve essere una sequenza numerica")
    if q.ndim != 1 or q.size < 96:
        raise ValueError(f"profilo_quarti deve avere almeno 96 quarti, trovati {int(q.size)}")
    if np.isnan(q).any():
        raise ValueError("profilo_quarti contiene NaN")
    return [round(float(b.max()), 3) for b in np.array_split(q, 12)]


def q243_sintesi(profilo_orario, picco_intraore_pct=15.0, seed=243):
    """Sintesi picchi orari vs quartorari.

    Ritorna dict con: n_ore, n_quarti, energia_mwh, picco_orario_kw,
    picco_quartorario_kw, rapporto_qh_pct, delta_picco_kw,
    picchi_mensili_orari, picchi_mensili_quartorari.
    """
    import numpy as np
    try:
        h = np.asarray(list(profilo_orario), dtype=float)
    except (TypeError, ValueError):
        raise ValueError("profilo_orario deve essere una sequenza numerica")
    q = np.asarray(q243_a_quarti(h, picco_intraore_pct, seed))
    p_h = float(h.max())
    p_q = float(q.max())
    return {
        "n_ore": int(h.size),
        "n_quarti": int(q.size),
        "energia_mwh": round(float(h.sum()) / 1000.0, 3),
        "picco_orario_kw": round(p_h, 3),
        "picco_quartorario_kw": round(p_q, 3),
        "rapporto_qh_pct": round(100.0 * p_q / p_h, 2) if p_h > 0 else 0.0,
        "delta_picco_kw": round(p_q - p_h, 3),
        "picchi_mensili_orari": [round(float(b.max()), 3) for b in np.array_split(h, 12)],
        "picchi_mensili_quartorari": [round(float(b.max()), 3) for b in np.array_split(q, 12)],
    }


def a244_sintesi(consumo_annuo_kwh, quote_mensili, prezzo_kwh, fisso_annuo,
                 n_acconti, var_consumo_pct=0.0, mese_ricalcolo=None):
    """Simula bollette in acconto (su stima) vs costo reale e conguaglio.

    Modello: il fornitore fattura `n_acconti` bollette uguali calcolate sul
    costo annuo STIMATO (mesi 1..n_acconti); a fine anno il conguaglio salda
    la differenza col costo REALE (stima +/- var_consumo_pct). Con
    `mese_ricalcolo` (1..11) gli acconti successivi vengono ricalibrati sul
    costo reale proiettato, come fanno i fornitori su richiesta del cliente.

    Ritorna dict con serie mensili (12 valori) e KPI. Tutto deterministico.
    """
    import numpy as np
    consumo_annuo_kwh = float(consumo_annuo_kwh)
    if consumo_annuo_kwh <= 0:
        raise ValueError("consumo_annuo_kwh deve essere > 0")
    quote = [float(q) for q in quote_mensili]
    if len(quote) != 12:
        raise ValueError("quote_mensili deve avere 12 valori")
    tot_q = float(sum(quote))
    if tot_q <= 0:
        raise ValueError("quote_mensili non puo' sommare a 0")
    quote = [q / tot_q for q in quote]
    prezzo_kwh = float(prezzo_kwh)
    if prezzo_kwh < 0:
        raise ValueError("prezzo_kwh non puo' essere negativo")
    fisso_annuo = float(fisso_annuo)
    if fisso_annuo < 0:
        raise ValueError("fisso_annuo non puo' essere negativo")
    n_acconti = int(n_acconti)
    if not 1 <= n_acconti <= 11:
        raise ValueError("n_acconti deve stare tra 1 e 11")
    var = float(var_consumo_pct) / 100.0

    kwh_stim = np.array(quote) * consumo_annuo_kwh
    kwh_real = kwh_stim * (1.0 + var)
    fisso_mese = fisso_annuo / 12.0
    costo_stim = kwh_stim * prezzo_kwh + fisso_mese
    costo_real = kwh_real * prezzo_kwh + fisso_mese
    e_stim = float(costo_stim.sum())
    e_real = float(costo_real.sum())

    acconto_base = e_stim / n_acconti
    versato = np.zeros(12)
    versato[:n_acconti] = acconto_base
    ricalcolato = False
    if mese_ricalcolo is not None:
        mr = int(mese_ricalcolo)
        if 1 <= mr <= 11 and mr < n_acconti:
            pagato_finora = float(versato[:mr].sum())
            residui = n_acconti - mr
            nuovo = (e_real - pagato_finora) / residui if residui > 0 else 0.0
            versato[mr:n_acconti] = max(nuovo, 0.0)
            ricalcolato = True

    tot_versato = float(versato.sum())
    conguaglio = e_real - tot_versato  # >0 = a debito (cliente deve), <0 = a credito
    cum_costo = np.cumsum(costo_real)
    cum_vers = np.cumsum(versato)
    saldo = cum_costo - cum_vers  # scoperto progressivo (>0 = il cliente e' sotto di cassa)
    i_max = int(np.argmax(saldo))
    mesi = ["Gen", "Feb", "Mar", "Apr", "Mag", "Giu",
            "Lug", "Ago", "Set", "Ott", "Nov", "Dic"]
    return {
        "mesi": mesi,
        "kwh_stim_mese": [round(float(v), 1) for v in kwh_stim],
        "kwh_real_mese": [round(float(v), 1) for v in kwh_real],
        "costo_stim_mese": [round(float(v), 2) for v in costo_stim],
        "costo_real_mese": [round(float(v), 2) for v in costo_real],
        "versato_mese": [round(float(v), 2) for v in versato],
        "saldo_progressivo": [round(float(v), 2) for v in saldo],
        "costo_annuo_stimato": round(e_stim, 2),
        "costo_annuo_reale": round(e_real, 2),
        "totale_acconti": round(tot_versato, 2),
        "conguaglio": round(conguaglio, 2),
        "acconto_base": round(acconto_base, 2),
        "acconto_ottimale": round(e_real / n_acconti, 2),
        "max_scoperto": round(float(saldo[i_max]), 2),
        "mese_max_scoperto": mesi[i_max],
        "ricalcolato": ricalcolato,
        "n_acconti": n_acconti,
    }

def r245_rata_francese(capitale, tan_annuo_pct, n_rate):
    """Rata mensile costante di un piano francese posticipato.

    capitale: importo finanziato (euro); tan_annuo_pct: TAN nominale annuo
    in percentuale; n_rate: numero di rate mensili (1..60).
    Ritorna la rata mensile in euro. Tutto deterministico.
    """
    capitale = float(capitale)
    n = int(n_rate)
    tan = float(tan_annuo_pct)
    if capitale <= 0:
        raise ValueError("capitale deve essere > 0")
    if not 1 <= n <= 60:
        raise ValueError("n_rate deve stare tra 1 e 60")
    if tan < 0:
        raise ValueError("tan_annuo_pct non puo' essere negativo")
    i = tan / 100.0 / 12.0
    if i == 0.0:
        return capitale / n
    return capitale * i / (1.0 - (1.0 + i) ** -n)


def r245_piano(capitale, tan_annuo_pct, n_rate, costi_fissi=0.0):
    """Piano di ammortamento francese mese per mese.

    I costi_fissi (spese di istruttoria, bolli) vengono addebitati con la
    prima rata. Ritorna una lista di dict con chiavi:
    rata_n, rata, quota_capitale, quota_interessi, costi, residuo
    (residuo = debito residuo dopo il pagamento della rata). L'ultima rata
    azzera il residuo per costruzione.
    """
    costi_fissi = float(costi_fissi)
    if costi_fissi < 0:
        raise ValueError("costi_fissi non puo' essere negativo")
    capitale = float(capitale)
    n = int(n_rate)
    rata = r245_rata_francese(capitale, tan_annuo_pct, n)
    i = float(tan_annuo_pct) / 100.0 / 12.0
    piano = []
    residuo = capitale
    for k in range(1, n + 1):
        interessi = residuo * i
        if k == n:
            quota_cap = residuo
            rata_k = quota_cap + interessi
        else:
            quota_cap = rata - interessi
            rata_k = rata
        residuo = residuo - quota_cap
        piano.append({
            "rata_n": k,
            "rata": round(rata_k, 2),
            "quota_capitale": round(quota_cap, 2),
            "quota_interessi": round(interessi, 2),
            "costi": round(costi_fissi, 2) if k == 1 else 0.0,
            "residuo": round(max(residuo, 0.0), 2),
        })
    return piano


def r245_taeg(capitale, pagamenti_mensili, costi_iniziali=0.0, tol=1e-10):
    """TAEG annuo equivalente del piano, via bisezione sul tasso mensile.

    pagamenti_mensili: lista delle rate mensili in euro (costi inclusi dove
    addebitati); costi_iniziali: esborsi al tempo 0 non inclusi nelle rate.
    Risolve capitale = costi_iniziali + sum(p_k / (1+r)^k) e annualizza
    come (1+r)^12 - 1, in percentuale. Se il piano e' a costo zero
    ritorna 0.0.
    """
    capitale = float(capitale)
    pag = [float(p) for p in pagamenti_mensili]
    costi0 = float(costi_iniziali)
    if capitale <= 0:
        raise ValueError("capitale deve essere > 0")
    if not pag or any(p < 0 for p in pag):
        raise ValueError("pagamenti_mensili non valido")
    if costi0 < 0:
        raise ValueError("costi_iniziali non puo' essere negativo")

    def van(r):
        s = costi0
        f = 1.0
        for p in pag:
            f *= (1.0 + r)
            s += p / f
        return s - capitale

    if van(0.0) <= 0.0:
        return 0.0
    lo, hi = 0.0, 1.0
    while van(hi) > 0.0 and hi < 1e6:
        hi *= 2.0
    for _ in range(200):
        mid = (lo + hi) / 2.0
        if van(mid) > 0.0:
            lo = mid
        else:
            hi = mid
        if hi - lo < tol:
            break
    r_m = (lo + hi) / 2.0
    return round(((1.0 + r_m) ** 12 - 1.0) * 100.0, 3)


def r245_sintesi(capitale, tan_annuo_pct, n_rate, costi_fissi=0.0,
                 sconto_pronta_cassa_pct=0.0):
    """KPI della rateizzazione del conguaglio a debito.

    sconto_pronta_cassa_pct: sconto % ottenibile pagando il conguaglio in
    un'unica soluzione immediata (se > 0, il confronto rate vs immediato
    include lo sconto). Ritorna dict con KPI + piano. Deterministico.
    """
    sconto = float(sconto_pronta_cassa_pct)
    if sconto < 0 or sconto >= 100:
        raise ValueError("sconto_pronta_cassa_pct deve stare tra 0 e 100")
    piano = r245_piano(capitale, tan_annuo_pct, n_rate, costi_fissi=costi_fissi)
    pagamenti = [r["rata"] + r["costi"] for r in piano]
    totale = round(sum(pagamenti), 2)
    interessi = round(sum(r["quota_interessi"] for r in piano), 2)
    taeg = r245_taeg(capitale, pagamenti)
    rata = piano[0]["rata"]
    immediato = round(float(capitale) * (1.0 - sconto / 100.0), 2)
    return {
        "piano": piano,
        "rata_mensile": rata,
        "totale_versato": totale,
        "interessi_totali": interessi,
        "costi_fissi": round(float(costi_fissi), 2),
        "costo_finanziario": round(interessi + float(costi_fissi), 2),
        "taeg_pct": taeg,
        "pagamento_immediato": immediato,
        "delta_vs_immediato": round(totale - immediato, 2),
        "n_rate": int(n_rate),
        "tan_annuo_pct": round(float(tan_annuo_pct), 2),
    }


def d246_deposito(costo_annuo_euro, mesi, sconto_sdd_pct):
    """Deposito cauzionale: lordo e netto in euro.

    Il deposito lordo vale (costo_annuo / 12) * mesi; quello netto applica la
    riduzione concessa con addebito diretto SEPA (sconto_sdd_pct).
    costo_annuo_euro: spesa annua stimata (> 0); mesi: mensilita' richieste
    (0..6); sconto_sdd_pct: riduzione per addebito diretto SEPA (0..100).
    Ritorna la tupla (deposito_lordo, deposito_netto). Tutto deterministico.
    """
    costo = float(costo_annuo_euro)
    m = int(mesi)
    s = float(sconto_sdd_pct)
    if costo <= 0:
        raise ValueError("costo_annuo_euro deve essere > 0")
    if not 0 <= m <= 6:
        raise ValueError("mesi deve stare tra 0 e 6")
    if not 0.0 <= s <= 100.0:
        raise ValueError("sconto_sdd_pct deve stare tra 0 e 100")
    lordo = costo / 12.0 * m
    netto = lordo * (1.0 - s / 100.0)
    return lordo, netto


def d246_costo_opportunita(deposito_euro, tan_annuo_pct, anni=1.0):
    """Costo opportunita' del capitale immobilizzato nel deposito.

    deposito_euro: importo del deposito (>= 0); tan_annuo_pct: TAN nominale
    annuo del capitale (>= 0); anni: orizzonte (default 1 anno).
    Ritorna il costo in euro.
    """
    d = float(deposito_euro)
    t = float(tan_annuo_pct)
    y = float(anni)
    if d < 0:
        raise ValueError("deposito_euro non puo' essere negativo")
    if t < 0:
        raise ValueError("tan_annuo_pct non puo' essere negativo")
    if y <= 0:
        raise ValueError("anni deve essere > 0")
    return d * t / 100.0 * y


def d246_costo_fideiussione(deposito_euro, commissione_annua_pct):
    """Costo annuo della fideiussione bancaria posta a garanzia del deposito.

    deposito_euro: importo garantito (>= 0); commissione_annua_pct: commissione
    annua della banca in percentuale (>= 0). Ritorna il costo in euro.
    """
    d = float(deposito_euro)
    c = float(commissione_annua_pct)
    if d < 0:
        raise ValueError("deposito_euro non puo' essere negativo")
    if c < 0:
        raise ValueError("commissione_annua_pct non puo' essere negativa")
    return d * c / 100.0


def d246_sintesi(costo_annuo_euro, mesi, sconto_sdd_pct, tan_annuo_pct,
                 commissione_fideiussione_pct):
    """Sintesi completa del deposito cauzionale.

    Ritorna un dict con deposito lordo/netto, costo opportunita' annuo, costo
    fideiussione annuo, costo totale annuo e incidenza percentuale sul costo
    annuo stimato. Tutto deterministico.
    """
    lordo, netto = d246_deposito(costo_annuo_euro, mesi, sconto_sdd_pct)
    opp = d246_costo_opportunita(netto, tan_annuo_pct)
    fid = d246_costo_fideiussione(netto, commissione_fideiussione_pct)
    costo = float(costo_annuo_euro)
    return {
        "deposito_lordo": round(lordo, 2),
        "deposito_netto": round(netto, 2),
        "costo_opportunita_annuo": round(opp, 2),
        "costo_fideiussione_annuo": round(fid, 2),
        "costo_totale_annuo": round(opp + fid, 2),
        "incidenza_pct": round((opp + fid) / costo * 100.0, 3),
        "mesi": int(mesi),
        "sconto_sdd_pct": round(float(sconto_sdd_pct), 1),
    }




def d247_costo_pratica(corrispettivo_euro, iva_pct, bollo_euro=0.0,
                       contributo_distributore_euro=0.0, onere_riattivazione_euro=0.0):
    """Costo una tantum di una pratica amministrativa: voltura o subentro.

    Per voltura e subentro il contributo amministrativo del distributore e' 0 EUR
    (ARERA, Testo integrato delle condizioni economiche di connessione, art. 28).
    Il venditore applica un corrispettivo commerciale per la gestione della pratica
    (IVA applicata); l'imposta di bollo da 16 EUR, quando dovuta, e' fuori campo IVA.
    Nel subentro il punto e' disattivato: si aggiunge l'onere di riattivazione
    (IVA applicata).

    Ritorna dict con imponibile, iva, bollo e totale. Tutto deterministico.
    """
    corr = float(corrispettivo_euro)
    iva_p = float(iva_pct)
    bollo = float(bollo_euro)
    contrib = float(contributo_distributore_euro)
    riatt = float(onere_riattivazione_euro)
    if corr < 0:
        raise ValueError("corrispettivo commerciale negativo")
    if riatt < 0:
        raise ValueError("onere di riattivazione negativo")
    if bollo < 0:
        raise ValueError("imposta di bollo negativa")
    if contrib < 0:
        raise ValueError("contributo distributore negativo")
    if not 0.0 <= iva_p <= 100.0:
        raise ValueError("aliquota IVA fuori range 0-100")
    imponibile = corr + contrib + riatt
    iva = imponibile * iva_p / 100.0
    totale = imponibile + iva + bollo
    return {
        "imponibile": round(imponibile, 2),
        "iva": round(iva, 2),
        "bollo": round(bollo, 2),
        "totale": round(totale, 2),
    }


def d247_confronto(tot_voltura_euro, tot_subentro_euro):
    """Delta e rapporto tra costo subentro e costo voltura."""
    delta = float(tot_subentro_euro) - float(tot_voltura_euro)
    rapporto = (float(tot_subentro_euro) / float(tot_voltura_euro)
                if float(tot_voltura_euro) > 0 else None)
    return {
        "delta": round(delta, 2),
        "rapporto": round(rapporto, 3) if rapporto is not None else None,
    }


def d247_sintesi(corrispettivo_euro, iva_pct, bollo_euro, onere_riattivazione_euro,
                 deposito_euro=0.0, contributo_distributore_euro=0.0):
    """Sintesi voltura vs subentro.

    Ritorna i costi di pratica dei due scenari, il confronto e l'esborso iniziale
    stimato (pratica + eventuale deposito cauzionale). Tutto deterministico.
    """
    dep = float(deposito_euro)
    if dep < 0:
        raise ValueError("deposito cauzionale negativo")
    voltura = d247_costo_pratica(corrispettivo_euro, iva_pct, bollo_euro,
                                 contributo_distributore_euro, 0.0)
    subentro = d247_costo_pratica(corrispettivo_euro, iva_pct, bollo_euro,
                                  contributo_distributore_euro,
                                  onere_riattivazione_euro)
    conf = d247_confronto(voltura["totale"], subentro["totale"])
    return {
        "voltura": voltura,
        "subentro": subentro,
        "delta": conf["delta"],
        "rapporto": conf["rapporto"],
        "esborso_voltura": round(voltura["totale"] + dep, 2),
        "esborso_subentro": round(subentro["totale"] + dep, 2),
        "deposito": round(dep, 2),
    }

def d248_tasso_moratorio(tasso_bce_pct, maggiorazione_pp=8.0):
    """Tasso moratorio annuo nei rapporti B2B (D.Lgs. 231/2002): saggio di
    riferimento BCE + maggiorazione di legge (8 punti percentuali).

    Ritorna un dict con il saggio BCE, la maggiorazione e il tasso moratorio
    risultante. Tutto deterministico.
    """
    bce = float(tasso_bce_pct)
    magg = float(maggiorazione_pp)
    if bce < 0 or magg < 0:
        raise ValueError("tassi negativi non ammessi")
    return {
        "tasso_bce_pct": round(bce, 2),
        "maggiorazione_pp": round(magg, 2),
        "tasso_moratorio_pct": round(bce + magg, 2),
    }


def d248_interessi_moratori(importo_euro, tasso_moratorio_pct, giorni_ritardo,
                            base_giorni=365):
    """Interessi di mora su base giornaliera: I = C * r * giorni / base.

    Ritorna capitale, tasso applicato, giorni e interessi arrotondati.
    Tutto deterministico.
    """
    cap = float(importo_euro)
    r = float(tasso_moratorio_pct)
    gg = int(giorni_ritardo)
    base = int(base_giorni)
    if cap < 0 or r < 0 or gg < 0 or base <= 0:
        raise ValueError("valori non validi per il calcolo degli interessi")
    interessi = cap * (r / 100.0) * gg / base
    return {
        "capitale": round(cap, 2),
        "tasso_pct": round(r, 2),
        "giorni": gg,
        "interessi": round(interessi, 2),
    }


def d248_costo_ritardo(importo_euro, tasso_moratorio_pct, giorni_ritardo,
                       recupero_spese_euro=40.0, base_giorni=365):
    """Costo totale di un ritardo di pagamento: interessi di mora + rimborso
    forfettario delle spese di recupero (art. 6 D.Lgs. 231/2002: minimo 40 €).

    Ritorna interessi, spese, totale, incidenza % sull'importo e costo medio
    giornaliero. Tutto deterministico.
    """
    int_d = d248_interessi_moratori(importo_euro, tasso_moratorio_pct,
                                    giorni_ritardo, base_giorni)
    spese = float(recupero_spese_euro)
    if spese < 0:
        raise ValueError("spese di recupero negative")
    tot = int_d["interessi"] + spese
    cap = int_d["capitale"]
    gg = int_d["giorni"]
    return {
        "interessi": int_d["interessi"],
        "recupero_spese": round(spese, 2),
        "totale": round(tot, 2),
        "incidenza_pct": round(tot / cap * 100.0, 3) if cap > 0 else 0.0,
        "costo_giornaliero": round(tot / gg, 2) if gg > 0 else round(tot, 2),
    }


def d248_confronto_sconto(importo_euro, costo_ritardo_totale_euro,
                          sconto_pronta_cassa_pct):
    """Confronto ritardo vs sconto per pronta cassa: pagare in ritardo non solo
    costa interessi e spese, ma fa perdere lo sconto che si sarebbe ottenuto
    pagando subito (mancato risparmio = sconto + costo del ritardo).
    Tutto deterministico.
    """
    imp = float(importo_euro)
    if imp < 0:
        raise ValueError("importo negativo")
    sconto = imp * float(sconto_pronta_cassa_pct) / 100.0
    costo = float(costo_ritardo_totale_euro)
    return {
        "sconto_valore": round(sconto, 2),
        "costo_ritardo": round(costo, 2),
        "mancato_risparmio": round(sconto + costo, 2),
    }


def cnx249_quota_potenza(kw, tariffa_eur_kw):
    """Quota potenza del contributo di allacciamento: kW impegnati x tariffa.

    Ritorna potenza, tariffa applicata e importo arrotondato.
    Tutto deterministico.
    """
    kw = float(kw)
    tar = float(tariffa_eur_kw)
    if kw <= 0:
        raise ValueError("potenza impegnata non positiva")
    if tar < 0:
        raise ValueError("tariffa potenza negativa")
    return {
        "kw": round(kw, 2),
        "tariffa_eur_kw": round(tar, 2),
        "importo": round(kw * tar, 2),
    }


def cnx249_quota_distanza(metri, franchigia_m, tariffa_eur_m):
    """Quota distanza del contributo di allacciamento: tariffa x metri oltre la
    franchigia (se la rete esistente e' entro la franchigia la quota e' zero).

    Ritorna metri, franchigia, metri fatturabili e importo arrotondato.
    Tutto deterministico.
    """
    m = float(metri)
    fr = float(franchigia_m)
    tar = float(tariffa_eur_m)
    if m < 0 or fr < 0:
        raise ValueError("metri o franchigia negativi")
    if tar < 0:
        raise ValueError("tariffa distanza negativa")
    m_fatt = max(0.0, m - fr)
    return {
        "metri": round(m, 1),
        "franchigia_m": round(fr, 1),
        "metri_fatturabili": round(m_fatt, 1),
        "tariffa_eur_m": round(tar, 2),
        "importo": round(m_fatt * tar, 2),
    }


def cnx249_preventivo(kw, metri, franchigia_m, tariffa_eur_kw, tariffa_eur_m,
                      onere_amministrativo_eur=50.0, iva_pct=10.0):
    """Preventivo di allacciamento completo: quota potenza + quota distanza +
    onere amministrativo, con IVA sul totale.

    Ritorna il dettaglio per voce, imponibile, IVA, totale e costo per kW.
    Tutto deterministico.
    """
    qp = cnx249_quota_potenza(kw, tariffa_eur_kw)
    qd = cnx249_quota_distanza(metri, franchigia_m, tariffa_eur_m)
    onere = float(onere_amministrativo_eur)
    iva = float(iva_pct)
    if onere < 0:
        raise ValueError("onere amministrativo negativo")
    if iva < 0 or iva > 100:
        raise ValueError("aliquota IVA non valida")
    imponibile = round(qp["importo"] + qd["importo"] + onere, 2)
    iva_eur = round(imponibile * iva / 100.0, 2)
    totale = round(imponibile + iva_eur, 2)
    return {
        "quota_potenza": qp["importo"],
        "quota_distanza": qd["importo"],
        "metri_fatturabili": qd["metri_fatturabili"],
        "onere_amministrativo": round(onere, 2),
        "imponibile": imponibile,
        "iva_pct": round(iva, 2),
        "iva": iva_eur,
        "totale": totale,
        "costo_per_kw": round(totale / qp["kw"], 2),
    }


def cnx249_confronto_bt_mt(kw, metri, params_bt, params_mt,
                           costo_cabina_mt_eur=0.0):
    """Confronto contributo di allacciamento BT vs MT (cabina MT/BT a carico
    del cliente nella MT: costo extra da sommare al preventivo MT).

    params_bt/params_mt sono dict con franchigia_m, tariffa_eur_kw,
    tariffa_eur_m, onere_amministrativo_eur, iva_pct.
    Ritorna preventivi BT e MT, investimento MT (con cabina), differenza e
    livello piu' economico. Tutto deterministico.
    """
    for p, nome in ((params_bt, "BT"), (params_mt, "MT")):
        if not isinstance(p, dict):
            raise ValueError(f"parametri {nome} non validi")
        for k in ("franchigia_m", "tariffa_eur_kw", "tariffa_eur_m",
                  "onere_amministrativo_eur", "iva_pct"):
            if k not in p:
                raise ValueError(f"parametri {nome}: manca {k}")
    cab = float(costo_cabina_mt_eur)
    if cab < 0:
        raise ValueError("costo cabina negativo")
    prev_bt = cnx249_preventivo(kw, metri, params_bt["franchigia_m"],
                                params_bt["tariffa_eur_kw"],
                                params_bt["tariffa_eur_m"],
                                params_bt["onere_amministrativo_eur"],
                                params_bt["iva_pct"])
    prev_mt = cnx249_preventivo(kw, metri, params_mt["franchigia_m"],
                                params_mt["tariffa_eur_kw"],
                                params_mt["tariffa_eur_m"],
                                params_mt["onere_amministrativo_eur"],
                                params_mt["iva_pct"])
    invest_mt = round(prev_mt["totale"] + cab, 2)
    diff = round(invest_mt - prev_bt["totale"], 2)
    return {
        "preventivo_bt": prev_bt,
        "preventivo_mt": prev_mt,
        "cabina_mt": round(cab, 2),
        "investimento_mt": invest_mt,
        "differenza": diff,
        "conveniente": "BT" if diff > 0 else "MT",
    }


def cnx249_sensibilita(kw_list, metri_list, franchigia_m, tariffa_eur_kw,
                       tariffa_eur_m, onere_amministrativo_eur=50.0,
                       iva_pct=10.0):
    """Matrice del totale del preventivo (IVA inclusa) al variare di potenza
    e distanza dalla rete: righe di dict {kw, metri, totale}.

    Tutto deterministico.
    """
    kws = [float(x) for x in kw_list]
    ms = [float(x) for x in metri_list]
    if len(kws) < 2 or len(ms) < 2:
        raise ValueError("servono almeno 2 potenze e 2 distanze")
    if any(x <= 0 for x in kws):
        raise ValueError("potenze non positive")
    if any(x < 0 for x in ms):
        raise ValueError("distanze negative")
    righe = []
    for kw in kws:
        for m in ms:
            tot = cnx249_preventivo(kw, m, franchigia_m, tariffa_eur_kw,
                                    tariffa_eur_m, onere_amministrativo_eur,
                                    iva_pct)["totale"]
            righe.append({"kw": round(kw, 2), "metri": round(m, 1),
                          "totale": tot})
    return righe



def cc250_ciclo_cassa(dso_gg, dpo_gg, dio_gg=0.0):
    """Ciclo di cassa (cash conversion cycle): DSO + DIO - DPO, in giorni.

    DSO: giorni medi di incasso dai clienti; DPO: giorni medi di pagamento
    ai fornitori; DIO: giorni di giacenza (0 per trader/fornitore di energia).
    Ciclo negativo = i fornitori finanziano l'attivita'.
    Tutto deterministico.
    """
    dso = float(dso_gg)
    dpo = float(dpo_gg)
    dio = float(dio_gg)
    if dso < 0:
        raise ValueError("DSO negativo")
    if dpo < 0:
        raise ValueError("DPO negativo")
    if dio < 0:
        raise ValueError("DIO negativo")
    return {
        "dso_gg": dso,
        "dpo_gg": dpo,
        "dio_gg": dio,
        "ciclo_gg": round(dso + dio - dpo, 1),
    }


def cc250_fabbisogno(costo_acquisto_annuo_eur, ciclo_gg):
    """Fabbisogno medio di capitale circolante: costo annuo x ciclo/365."""
    costo = float(costo_acquisto_annuo_eur)
    ciclo = float(ciclo_gg)
    if costo < 0:
        raise ValueError("costo acquisto annuo negativo")
    return {
        "costo_acquisto_annuo_eur": costo,
        "ciclo_gg": ciclo,
        "fabbisogno_medio_eur": round(costo * ciclo / 365.0, 2),
    }


def cc250_costo_finanziario(fabbisogno_eur, wacc_pct):
    """Costo annuo del capitale che finanzia il circolante: fabbisogno x WACC.

    Il fabbisogno puo' essere negativo (ciclo di cassa negativo: i fornitori
    finanziano l'attivita'): in tal caso il costo e' negativo = beneficio.
    """
    fab = float(fabbisogno_eur)
    w = float(wacc_pct)
    if w < 0 or w > 100:
        raise ValueError("WACC fuori range 0-100%")
    return {
        "fabbisogno_eur": fab,
        "wacc_pct": w,
        "costo_annuo_eur": round(fab * w / 100.0, 2),
    }


def cc250_costo_per_mwh(costo_annuo_eur, volumi_mwh_annui):
    """Ricarico del costo del circolante sui volumi venduti, in EUR/MWh.

    Il costo puo' essere negativo (beneficio da ciclo di cassa negativo):
    in tal caso anche il ricarico e' negativo.
    """
    costo = float(costo_annuo_eur)
    vol = float(volumi_mwh_annui)
    if vol <= 0:
        raise ValueError("volumi annui non positivi")
    return {
        "costo_annuo_eur": costo,
        "volumi_mwh_annui": vol,
        "costo_per_mwh": round(costo / vol, 3),
    }


def cc250_confronto_scenari(costo_acquisto_annuo_eur, volumi_mwh_annui, scenari):
    """Confronta scenari di incasso/pagamento.

    scenari: lista di dict {"nome": str, "dso": gg, "dpo": gg, "wacc_pct": %}.
    Ritorna una riga per scenario con ciclo, fabbisogno, costo annuo e EUR/MWh.
    """
    costo = float(costo_acquisto_annuo_eur)
    vol = float(volumi_mwh_annui)
    if costo < 0:
        raise ValueError("costo acquisto annuo negativo")
    if vol <= 0:
        raise ValueError("volumi annui non positivi")
    if not scenari:
        raise ValueError("nessuno scenario da confrontare")
    righe = []
    for s in scenari:
        try:
            nome = str(s["nome"])
            dso = float(s["dso"])
            dpo = float(s["dpo"])
            w = float(s["wacc_pct"])
        except (KeyError, TypeError, ValueError):
            raise ValueError("scenario malformato: servono nome, dso, dpo, wacc_pct")
        ciclo = cc250_ciclo_cassa(dso, dpo)["ciclo_gg"]
        fab = cc250_fabbisogno(costo, ciclo)["fabbisogno_medio_eur"]
        cfin = cc250_costo_finanziario(fab, w)["costo_annuo_eur"]
        pmwh = cc250_costo_per_mwh(cfin, vol)["costo_per_mwh"]
        righe.append({
            "scenario": nome,
            "dso_gg": dso,
            "dpo_gg": dpo,
            "ciclo_gg": ciclo,
            "fabbisogno_eur": fab,
            "costo_annuo_eur": cfin,
            "costo_per_mwh": pmwh,
        })
    return righe


def cc250_sensibilita(dso_list, wacc_list, costo_acquisto_annuo_eur, dpo_gg,
                      volumi_mwh_annui):
    """Matrice costo annuo / EUR-MWh al variare di DSO e WACC."""
    if not dso_list or not wacc_list:
        raise ValueError("liste DSO/WACC vuote")
    dso_l = [float(x) for x in dso_list]
    wacc_l = [float(x) for x in wacc_list]
    costo = float(costo_acquisto_annuo_eur)
    dpo = float(dpo_gg)
    vol = float(volumi_mwh_annui)
    if any(x < 0 for x in dso_l):
        raise ValueError("DSO negativo in lista")
    if any(x < 0 or x > 100 for x in wacc_l):
        raise ValueError("WACC fuori range 0-100% in lista")
    if costo < 0:
        raise ValueError("costo acquisto annuo negativo")
    if dpo < 0:
        raise ValueError("DPO negativo")
    if vol <= 0:
        raise ValueError("volumi annui non positivi")
    righe = []
    for dso in dso_l:
        ciclo = cc250_ciclo_cassa(dso, dpo)["ciclo_gg"]
        fab = cc250_fabbisogno(costo, ciclo)["fabbisogno_medio_eur"]
        for w in wacc_l:
            cfin = cc250_costo_finanziario(fab, w)["costo_annuo_eur"]
            righe.append({
                "dso_gg": dso,
                "wacc_pct": w,
                "ciclo_gg": ciclo,
                "fabbisogno_eur": fab,
                "costo_annuo_eur": cfin,
                "costo_per_mwh": cc250_costo_per_mwh(cfin, vol)["costo_per_mwh"],
            })
    return righe



def r251_fattore_potenza(attiva_kwh, reattiva_kvarh):
    """Fattore di potenza da energie mensili: tan(phi) = Q/P, cos(phi).

    NaN-safe; energie negative o attiva nulla -> ValueError (cosphi non
    definito senza potenza attiva).
    """
    p = float(attiva_kwh)
    q = float(reattiva_kvarh)
    if p != p or q != q:
        raise ValueError("NaN non ammesso")
    if p < 0:
        raise ValueError("energia attiva negativa")
    if q < 0:
        raise ValueError("energia reattiva negativa")
    if p <= 0:
        raise ValueError("energia attiva nulla: cos(phi) non definito")
    tan_phi = q / p
    cos_phi = 1.0 / (1.0 + tan_phi * tan_phi) ** 0.5
    return {
        "attiva_kwh": p,
        "reattiva_kvarh": q,
        "tan_phi": round(tan_phi, 4),
        "cos_phi": round(cos_phi, 4),
    }


def r251_eccedenze(attiva_kwh, reattiva_kvarh, soglia1_pct=33.0,
                   soglia2_pct=75.0):
    """Ripartisce la reattiva mensile in esente / fascia1 / fascia2.

    fascia1: quota di Q tra soglia1% e soglia2% di P (penale base);
    fascia2: quota di Q oltre soglia2% di P (penale maggiorata).
    Default 33/75 = regola italiana (ARERA) per periodo di riferimento.
    """
    p = float(attiva_kwh)
    q = float(reattiva_kvarh)
    s1 = float(soglia1_pct)
    s2 = float(soglia2_pct)
    if p != p or q != q or s1 != s1 or s2 != s2:
        raise ValueError("NaN non ammesso")
    if p <= 0:
        raise ValueError("energia attiva non positiva")
    if q < 0:
        raise ValueError("energia reattiva negativa")
    if not (0 < s1 < s2):
        raise ValueError("soglie non valide: serve 0 < soglia1 < soglia2")
    lim1 = p * s1 / 100.0
    lim2 = p * s2 / 100.0
    q_f1 = max(0.0, min(q, lim2) - lim1)
    q_f2 = max(0.0, q - lim2)
    q_esente = max(0.0, q - q_f1 - q_f2)
    return {
        "attiva_kwh": p,
        "reattiva_kvarh": q,
        "q_esente_kvarh": round(q_esente, 2),
        "q_fascia1_kvarh": round(q_f1, 2),
        "q_fascia2_kvarh": round(q_f2, 2),
    }


def r251_penale(eccedenze, tariffa_fascia1_eur_kvarh,
                tariffa_fascia2_eur_kvarh):
    """Penale mensile: eccedenza fascia1 x tariffa1 + fascia2 x tariffa2."""
    if not isinstance(eccedenze, dict):
        raise ValueError("eccedenze deve essere un dict da r251_eccedenze")
    try:
        q1 = float(eccedenze["q_fascia1_kvarh"])
        q2 = float(eccedenze["q_fascia2_kvarh"])
    except (KeyError, TypeError, ValueError):
        raise ValueError("dict eccedenze malformato")
    t1 = float(tariffa_fascia1_eur_kvarh)
    t2 = float(tariffa_fascia2_eur_kvarh)
    if t1 != t1 or t2 != t2:
        raise ValueError("NaN non ammesso")
    if t1 < 0 or t2 < 0:
        raise ValueError("tariffe negative")
    p1 = q1 * t1
    p2 = q2 * t2
    return {
        "penale_fascia1_eur": round(p1, 2),
        "penale_fascia2_eur": round(p2, 2),
        "penale_totale_eur": round(p1 + p2, 2),
    }


def r251_rifasamento(attiva_kwh, reattiva_kvarh, cosphi_target,
                     ore_mese=730.0):
    """Batteria di condensatori (kVAr) per raggiungere cosphi_target.

    Stima su profilo piatto: potenza media = energia / ore_mese, poi
    Qc = P_media * (tan(phi) - tan(phi_target)). Per profili variabili il
    dimensionamento va fatto sul picco di reattiva, non sulla media.
    """
    import math
    p = float(attiva_kwh)
    q = float(reattiva_kvarh)
    tgt = float(cosphi_target)
    ore = float(ore_mese)
    if p != p or q != q or tgt != tgt or ore != ore:
        raise ValueError("NaN non ammesso")
    if p <= 0:
        raise ValueError("energia attiva non positiva")
    if q < 0:
        raise ValueError("energia reattiva negativa")
    if not (0.0 < tgt < 1.0):
        raise ValueError("cosphi target fuori (0, 1)")
    if ore <= 0:
        raise ValueError("ore mese non positive")
    p_med = p / ore
    q_med = q / ore
    tan_phi = q_med / p_med if p_med > 0 else 0.0
    tan_tgt = math.sqrt(1.0 - tgt * tgt) / tgt
    kvar = max(0.0, p_med * (tan_phi - tan_tgt))
    return {
        "potenza_media_kw": round(p_med, 2),
        "reattiva_media_kvar": round(q_med, 2),
        "cosphi_target": tgt,
        "batteria_kvar": round(kvar, 2),
    }


def r251_payback(penale_annua_eur, batteria_kvar, costo_batteria_eur_kvar):
    """Payback della batteria di rifasamento contro le penali annue evitate."""
    pen = float(penale_annua_eur)
    kvar = float(batteria_kvar)
    costo = float(costo_batteria_eur_kvar)
    if pen != pen or kvar != kvar or costo != costo:
        raise ValueError("NaN non ammesso")
    if pen < 0:
        raise ValueError("penale annua negativa")
    if kvar < 0:
        raise ValueError("batteria negativa")
    if costo < 0:
        raise ValueError("costo batteria negativo")
    investimento = kvar * costo
    if pen <= 0 or kvar <= 0:
        return {
            "investimento_eur": round(investimento, 2),
            "risparmio_annuo_eur": round(pen, 2),
            "payback_mesi": None,
            "conviene": False,
        }
    mesi = investimento / pen * 12.0
    return {
        "investimento_eur": round(investimento, 2),
        "risparmio_annuo_eur": round(pen, 2),
        "payback_mesi": round(mesi, 1),
        "conviene": mesi <= 60.0,
    }


def r251_analisi_fasce(attiva_fasce, reattiva_fasce, fasce, tariffa_fascia1,
                       tariffa_fascia2, soglia1_pct=33.0, soglia2_pct=75.0):
    """Analisi per fascia oraria: cosphi, eccedenze e penale per fascia.

    attiva_fasce/reattiva_fasce: liste di kWh/kVArh; fasce: nomi (es. F1..F3).
    Ritorna una riga per fascia.
    """
    att = [float(x) for x in attiva_fasce]
    rea = [float(x) for x in reattiva_fasce]
    nomi = [str(x) for x in fasce]
    if not att or not rea or not nomi:
        raise ValueError("liste vuote")
    if not (len(att) == len(rea) == len(nomi)):
        raise ValueError("liste di lunghezza diversa")
    righe = []
    for nome, p, q in zip(nomi, att, rea):
        fp = r251_fattore_potenza(p, q)
        ecc = r251_eccedenze(p, q, soglia1_pct, soglia2_pct)
        pen = r251_penale(ecc, tariffa_fascia1, tariffa_fascia2)
        righe.append({
            "fascia": nome,
            "attiva_kwh": p,
            "reattiva_kvarh": q,
            "tan_phi": fp["tan_phi"],
            "cos_phi": fp["cos_phi"],
            "q_esente_kvarh": ecc["q_esente_kvarh"],
            "q_fascia1_kvarh": ecc["q_fascia1_kvarh"],
            "q_fascia2_kvarh": ecc["q_fascia2_kvarh"],
            "penale_eur": pen["penale_totale_eur"],
        })
    return righe


def be252_bilancio(fonti_kwh, usi_kwh):
    """Bilancio energetico di sito: fonti (input) vs usi (output).

    fonti_kwh/usi_kwh: dict {nome: kWh}. Ritorna totali, sbilancio
    (fonti - usi), perdite % sulle fonti. Uno sbilancio positivo e'
    perdite/errori di misura; negativo = usi non coperti dalle fonti.
    NaN-safe; valori negativi o dict vuoti -> ValueError.
    """
    def _check(d, cosa):
        if not isinstance(d, dict) or not d:
            raise ValueError(f"{cosa}: serve un dict non vuoto")
        vals = {}
        for k, v in d.items():
            nome = str(k)
            x = float(v)
            if x != x:
                raise ValueError(f"{cosa}: NaN non ammesso ({nome})")
            if x < 0:
                raise ValueError(f"{cosa}: valore negativo ({nome})")
            vals[nome] = x
        return vals
    fonti = _check(fonti_kwh, "fonti")
    usi = _check(usi_kwh, "usi")
    tot_in = sum(fonti.values())
    tot_out = sum(usi.values())
    sbil = tot_in - tot_out
    return {
        "totale_fonti_kwh": round(tot_in, 2),
        "totale_usi_kwh": round(tot_out, 2),
        "sbilancio_kwh": round(sbil, 2),
        "perdite_pct": round(100.0 * sbil / tot_in, 2) if tot_in > 0 else 0.0,
    }


def be252_quote(serie_kwh):
    """Quote percentuali di un dict {nome: kWh}, ordinate desc.

    Ritorna lista di (nome, pct) con pct a 2 decimali; la somma e'
    normalizzata a 100% anche con arrotondamenti.
    """
    if not isinstance(serie_kwh, dict) or not serie_kwh:
        raise ValueError("serve un dict non vuoto")
    vals = {}
    for k, v in serie_kwh.items():
        x = float(v)
        if x != x:
            raise ValueError("NaN non ammesso")
        if x < 0:
            raise ValueError("valore negativo")
        vals[str(k)] = x
    tot = sum(vals.values())
    if tot <= 0:
        raise ValueError("totale nullo: quote non definite")
    righe = sorted(((n, 100.0 * x / tot) for n, x in vals.items()),
                   key=lambda r: -r[1])
    # normalizza l'ultima riga per chiudere a 100.00
    somma = sum(round(p, 2) for _, p in righe)
    nome_u, _ = righe[-1]
    righe[-1] = (nome_u, round(righe[-1][1] + (100.0 - somma), 2))
    return [{"nome": n, "quota_pct": round(p, 2)} for n, p in righe]


def be252_intensita(totale_kwh, unita_prodotte):
    """Intensita' energetica (EnPI): kWh per unita' prodotta.

    Es. kWh/tonnellata, kWh/pezzo. Unita' non positive -> ValueError.
    """
    e = float(totale_kwh)
    u = float(unita_prodotte)
    if e != e or u != u:
        raise ValueError("NaN non ammesso")
    if e < 0:
        raise ValueError("energia negativa")
    if u <= 0:
        raise ValueError("unita' prodotte non positive")
    return round(e / u, 3)


def be252_costo_ponderato(fonti_kwh, costi_eur_kwh):
    """Costo energia per vettore e costo medio ponderato.

    fonti_kwh: {nome: kWh}; costi_eur_kwh: {nome: EUR/kWh}. Le chiavi di
    costi devono coprire tutte le fonti. Ritorna costo per vettore,
    costo totale, costo medio EUR/kWh e quota di costo per vettore.
    """
    bil = be252_bilancio(fonti_kwh, {"__dummy__": 1.0})
    if not isinstance(costi_eur_kwh, dict):
        raise ValueError("costi deve essere un dict")
    righe = []
    for nome, kwh in fonti_kwh.items():
        if nome not in costi_eur_kwh:
            raise ValueError(f"costo mancante per la fonte '{nome}'")
        c = float(costi_eur_kwh[nome])
        if c != c:
            raise ValueError("NaN non ammesso")
        if c < 0:
            raise ValueError(f"costo negativo per '{nome}'")
        righe.append({"fonte": str(nome), "kwh": float(kwh),
                      "costo_eur_kwh": c, "costo_eur": round(float(kwh) * c, 2)})
    tot_kwh = bil["totale_fonti_kwh"]
    tot_costo = round(sum(r["costo_eur"] for r in righe), 2)
    for r in righe:
        r["quota_costo_pct"] = (round(100.0 * r["costo_eur"] / tot_costo, 2)
                                if tot_costo > 0 else 0.0)
    righe.sort(key=lambda r: -r["costo_eur"])
    return {
        "righe": righe,
        "costo_totale_eur": tot_costo,
        "costo_medio_eur_kwh": (round(tot_costo / tot_kwh, 4)
                                if tot_kwh > 0 else 0.0),
    }


def be252_link_sankey(fonti_kwh, usi_kwh):
    """Nodi e link per il diagramma di Sankey del bilancio.

    Allocazione proporzionale che conserva l'energia su ogni nodo:
    ogni fonte alimenta ogni uso in proporzione (fonte/tot_in x uso/tot_in
    quando lo sbilancio e' >= 0); la quota residua va al nodo
    'Perdite / errori di misura'. Se gli usi superano le fonti, il
    deficit e' rappresentato come sorgente 'Deficit (usi oltre le fonti)'.
    Valori < 0.01 kWh scartati.
    """
    bil = be252_bilancio(fonti_kwh, usi_kwh)
    tot_in = bil["totale_fonti_kwh"]
    tot_out = bil["totale_usi_kwh"]
    sbil = bil["sbilancio_kwh"]
    nomi_fonti = [str(k) for k in fonti_kwh]
    nomi_usi = [str(k) for k in usi_kwh]
    labels = nomi_fonti + nomi_usi
    idx = {n: i for i, n in enumerate(labels)}
    fonti_vals = {str(k): float(v) for k, v in fonti_kwh.items()}
    usi_vals = {str(k): float(v) for k, v in usi_kwh.items()}
    sources, targets, values = [], [], []

    def _link(s, t, val):
        if val >= 0.01:
            sources.append(idx[s])
            targets.append(idx[t])
            values.append(round(val, 2))

    if sbil >= 0:
        denom = tot_in if tot_in > 0 else 1.0
        for nf in nomi_fonti:
            for nu in nomi_usi:
                _link(nf, nu, fonti_vals[nf] * usi_vals[nu] / denom)
        if sbil >= 0.01:
            nodo_perd = "Perdite / errori di misura"
            labels.append(nodo_perd)
            idx[nodo_perd] = len(labels) - 1
            for nf in nomi_fonti:
                _link(nf, nodo_perd,
                      fonti_vals[nf] * sbil / tot_in if tot_in > 0 else 0.0)
    else:
        denom = tot_out if tot_out > 0 else 1.0
        deficit = -sbil
        nodo_def = "Deficit (usi oltre le fonti)"
        labels.append(nodo_def)
        idx[nodo_def] = len(labels) - 1
        for nf in nomi_fonti:
            for nu in nomi_usi:
                _link(nf, nu, fonti_vals[nf] * usi_vals[nu] / denom)
        for nu in nomi_usi:
            _link(nodo_def, nu, deficit * usi_vals[nu] / denom)
    return {"labels": labels, "source": sources, "target": targets,
            "value": values, "sbilancio_kwh": sbil}



def ci253_costo_evento(voll_eur_kwh, potenza_kw, durata_ore):
    """Costo di un singolo evento di interruzione.

    ENS (energia non servita) = potenza interrotta x durata;
    costo = ENS x VoLL (Value of Lost Load, EUR/kWh).
    NaN-safe; valori negativi -> ValueError.
    """
    v = float(voll_eur_kwh)
    p = float(potenza_kw)
    t = float(durata_ore)
    if v != v or p != p or t != t:
        raise ValueError("NaN non ammesso")
    if v < 0:
        raise ValueError("VoLL negativo")
    if p < 0:
        raise ValueError("potenza negativa")
    if t < 0:
        raise ValueError("durata negativa")
    ens = p * t
    return {
        "voll_eur_kwh": v,
        "potenza_kw": p,
        "durata_ore": t,
        "ens_kwh": round(ens, 2),
        "costo_eur": round(ens * v, 2),
    }


def ci253_costo_atteso(voll_eur_kwh, potenza_kw, durata_media_ore, eventi_anno):
    """Costo atteso annuo = costo del singolo evento x eventi attesi/anno."""
    ev = ci253_costo_evento(voll_eur_kwh, potenza_kw, durata_media_ore)
    n = float(eventi_anno)
    if n != n:
        raise ValueError("NaN non ammesso")
    if n < 0:
        raise ValueError("eventi/anno negativi")
    return {
        "costo_evento_eur": ev["costo_eur"],
        "ens_evento_kwh": ev["ens_kwh"],
        "eventi_anno": n,
        "ens_annua_kwh": round(ev["ens_kwh"] * n, 2),
        "costo_atteso_annuo_eur": round(ev["costo_eur"] * n, 2),
    }


def ci253_indici(storico_durate_ore):
    """Indici di affidabilita' dallo storico delle durate (ore per evento).

    SAIDI = ore totali di interruzione / anno; n = eventi / anno;
    CAIDI = durata media per evento;
    disponibilita' % = (1 - SAIDI / 8760) * 100.
    """
    durs = [float(x) for x in storico_durate_ore]
    if not durs:
        raise ValueError("storico vuoto")
    for d in durs:
        if d != d:
            raise ValueError("NaN non ammesso")
        if d < 0:
            raise ValueError("durata negativa")
    saidi = sum(durs)
    n = len(durs)
    return {
        "eventi_anno": n,
        "saidi_ore_anno": round(saidi, 3),
        "caidi_ore_evento": round(saidi / n, 3),
        "disponibilita_pct": round((1.0 - saidi / 8760.0) * 100.0, 4),
    }


def ci253_backup(costo_atteso_annuo, quota_coperta_pct, capex_eur,
                 opex_annuo_eur):
    """Convenienza di un sistema di backup (UPS / gruppo elettrogeno).

    quota_coperta_pct: % del costo atteso annuo evitata dal backup;
    risparmio = costo_atteso - (residuo + opex); payback semplice sul capex,
    conveniente se <= 60 mesi.
    """
    c = float(costo_atteso_annuo)
    q = float(quota_coperta_pct)
    k = float(capex_eur)
    o = float(opex_annuo_eur)
    if c != c or q != q or k != k or o != o:
        raise ValueError("NaN non ammesso")
    if c < 0:
        raise ValueError("costo atteso negativo")
    if not (0.0 <= q <= 100.0):
        raise ValueError("quota coperta fuori [0, 100]")
    if k < 0:
        raise ValueError("capex negativo")
    if o < 0:
        raise ValueError("opex negativo")
    residuo = c * (1.0 - q / 100.0)
    con_backup = residuo + o
    risparmio = c - con_backup
    if risparmio <= 0 or k <= 0:
        payback = None
        conviene = False
    else:
        payback = k / risparmio * 12.0
        conviene = payback <= 60.0
    return {
        "costo_atteso_senza_eur": round(c, 2),
        "quota_coperta_pct": q,
        "costo_residuo_eur": round(residuo, 2),
        "opex_annuo_eur": round(o, 2),
        "costo_con_backup_eur": round(con_backup, 2),
        "risparmio_annuo_eur": round(risparmio, 2),
        "capex_eur": round(k, 2),
        "payback_mesi": round(payback, 1) if payback is not None else None,
        "conviene": conviene,
    }


def ci253_matrice(durate_ore, frequenze_anno, voll_eur_kwh, potenza_kw):
    """Matrice costo atteso annuo per durata x frequenza (per heatmap).

    Ritorna una riga per combinazione (durata_ore, eventi_anno).
    """
    durs = [float(x) for x in durate_ore]
    freqs = [float(x) for x in frequenze_anno]
    v = float(voll_eur_kwh)
    p = float(potenza_kw)
    if not durs or not freqs:
        raise ValueError("assi vuoti")
    for x in durs + freqs + [v, p]:
        if x != x:
            raise ValueError("NaN non ammesso")
    if any(x < 0 for x in durs + freqs) or v < 0 or p < 0:
        raise ValueError("valori negativi")
    righe = []
    for d in durs:
        for n in freqs:
            righe.append({
                "durata_ore": d,
                "eventi_anno": n,
                "costo_atteso_annuo_eur": round(v * p * d * n, 2),
            })
    return righe





def _wh254_num(x, nome):
    """Valida uno scalare numerico: no bool, no NaN/inf."""
    import math
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def wh254_energia_recuperabile(potenza_termica_kw, ore_anno, rendimento_recupero_pct):
    """Energia termica utile recuperabile in un anno.

    energia_utile_kwh = potenza_termica_kw x ore_anno x rendimento_recupero.
    NaN-safe; negativi / ore > 8760 / rendimento fuori [0,100] -> ValueError.
    """
    p = _wh254_num(potenza_termica_kw, "potenza_termica_kw")
    ore = _wh254_num(ore_anno, "ore_anno")
    eta = _wh254_num(rendimento_recupero_pct, "rendimento_recupero_pct")
    if p < 0:
        raise ValueError("potenza_termica_kw: non puo' essere negativa")
    if not 0 <= ore <= 8760:
        raise ValueError("ore_anno: deve stare in [0, 8760]")
    if not 0 <= eta <= 100:
        raise ValueError("rendimento_recupero_pct: deve stare in [0, 100]")
    energia_utile_kwh = p * ore * eta / 100.0
    return {"potenza_utile_kw": round(p * eta / 100.0, 2),
            "energia_utile_kwh": round(energia_utile_kwh, 2)}


def wh254_risparmio_gas(energia_utile_kwh, prezzo_gas_eur_kwh, rendimento_caldaia_pct):
    """Gas sostituito e risparmio lordo.

    gas_risparmiato = energia_utile / rendimento_caldaia (il gas bruciato
    con rendimento eta fornisce energia_utile); risparmio = gas x prezzo.
    """
    e = _wh254_num(energia_utile_kwh, "energia_utile_kwh")
    pg = _wh254_num(prezzo_gas_eur_kwh, "prezzo_gas_eur_kwh")
    eta = _wh254_num(rendimento_caldaia_pct, "rendimento_caldaia_pct")
    if e < 0:
        raise ValueError("energia_utile_kwh: non puo' essere negativa")
    if pg < 0:
        raise ValueError("prezzo_gas_eur_kwh: non puo' essere negativo")
    if not 0 < eta <= 100:
        raise ValueError("rendimento_caldaia_pct: deve stare in (0, 100]")
    gas_risparmiato_kwh = e / (eta / 100.0)
    return {"gas_risparmiato_kwh": round(gas_risparmiato_kwh, 2),
            "risparmio_lordo_eur": round(gas_risparmiato_kwh * pg, 2)}


def wh254_pompa_calore(calore_scarico_kw, cop, ore_anno, prezzo_elettrico_eur_kwh,
                      prezzo_gas_eur_kwh, rendimento_caldaia_pct):
    """Recupero con pompa di calore: il calore di scarto e' la sorgente fredda.

    calore_utile = calore_scarico x COP/(COP-1); elettricita' = calore_utile/COP.
    Convenienza vs caldaia a gas: cop_min = prezzo_elettrico x eta_caldaia / prezzo_gas
    (la PdC costa meno del gas per kWh utile quando COP > cop_min).
    COP deve essere > 1.
    """
    q = _wh254_num(calore_scarico_kw, "calore_scarico_kw")
    c = _wh254_num(cop, "cop")
    ore = _wh254_num(ore_anno, "ore_anno")
    pe = _wh254_num(prezzo_elettrico_eur_kwh, "prezzo_elettrico_eur_kwh")
    pg = _wh254_num(prezzo_gas_eur_kwh, "prezzo_gas_eur_kwh")
    eta = _wh254_num(rendimento_caldaia_pct, "rendimento_caldaia_pct")
    if q < 0:
        raise ValueError("calore_scarico_kw: non puo' essere negativo")
    if c <= 1:
        raise ValueError("cop: deve essere > 1")
    if not 0 <= ore <= 8760:
        raise ValueError("ore_anno: deve stare in [0, 8760]")
    if pe < 0 or pg < 0:
        raise ValueError("i prezzi non possono essere negativi")
    if not 0 < eta <= 100:
        raise ValueError("rendimento_caldaia_pct: deve stare in (0, 100]")
    calore_utile_kw = q * c / (c - 1.0)
    energia_utile_kwh = calore_utile_kw * ore
    energia_elettrica_kwh = calore_utile_kw / c * ore
    costo_elettrico_eur = energia_elettrica_kwh * pe
    gas_risparmiato_kwh = energia_utile_kwh / (eta / 100.0)
    risparmio_lordo_eur = gas_risparmiato_kwh * pg
    cop_min = pe * (eta / 100.0) / pg if pg > 0 else None
    return {"calore_utile_kw": round(calore_utile_kw, 2),
            "energia_utile_kwh": round(energia_utile_kwh, 2),
            "energia_elettrica_kwh": round(energia_elettrica_kwh, 2),
            "costo_elettrico_eur": round(costo_elettrico_eur, 2),
            "gas_risparmiato_kwh": round(gas_risparmiato_kwh, 2),
            "risparmio_lordo_eur": round(risparmio_lordo_eur, 2),
            "risparmio_netto_eur": round(risparmio_lordo_eur - costo_elettrico_eur, 2),
            "cop_min_convenienza": round(cop_min, 2) if cop_min is not None else None,
            "pdc_conveniente": bool(cop_min is not None and c > cop_min)}


def wh254_co2_evitata(gas_risparmiato_kwh, fattore_kg_kwh=0.201):
    """CO2 evitata sostituendo gas naturale (default 0,201 kgCO2/kWh)."""
    g = _wh254_num(gas_risparmiato_kwh, "gas_risparmiato_kwh")
    f = _wh254_num(fattore_kg_kwh, "fattore_kg_kwh")
    if g < 0:
        raise ValueError("gas_risparmiato_kwh: non puo' essere negativo")
    if f < 0:
        raise ValueError("fattore_kg_kwh: non puo' essere negativo")
    return {"co2_evitata_t_anno": round(g * f / 1000.0, 2)}


def wh254_business_case(risparmio_netto_annuo_eur, capex_eur, opex_annuo_eur):
    """Payback semplice dell'intervento di recupero.

    flusso = risparmio_netto - OPEX; payback = CAPEX/flusso (mesi).
    Conviene se payback <= 60 mesi; None/mai se il flusso non e' positivo.
    """
    r = _wh254_num(risparmio_netto_annuo_eur, "risparmio_netto_annuo_eur")
    cx = _wh254_num(capex_eur, "capex_eur")
    ox = _wh254_num(opex_annuo_eur, "opex_annuo_eur")
    if cx < 0:
        raise ValueError("capex_eur: non puo' essere negativo")
    if ox < 0:
        raise ValueError("opex_annuo_eur: non puo' essere negativo")
    flusso = r - ox
    payback = round(cx / flusso * 12.0, 1) if flusso > 0 else None
    return {"flusso_annuo_eur": round(flusso, 2),
            "payback_mesi": payback,
            "conviene": bool(payback is not None and payback <= 60)}


def wh254_sensitivita(prezzi_gas_list, ore_list, potenza_kw, rendimento_pct,
                     eta_caldaia_pct, opex_annuo):
    """Matrice risparmio netto annuo al variare di prezzo gas e ore/anno."""
    if not prezzi_gas_list or not ore_list:
        raise ValueError("prezzi_gas_list e ore_list non possono essere vuoti")
    righe = []
    for pg in prezzi_gas_list:
        for ore in ore_list:
            en = wh254_energia_recuperabile(potenza_kw, ore, rendimento_pct)
            rg = wh254_risparmio_gas(en["energia_utile_kwh"], pg, eta_caldaia_pct)
            righe.append({"prezzo_gas_eur_kwh": float(pg),
                          "ore_anno": float(ore),
                          "risparmio_netto_annuo_eur": round(rg["risparmio_lordo_eur"] - float(opex_annuo), 2)})
    return righe


def wh254_sensitivita_pdc(prezzi_gas_list, ore_list, calore_scarico_kw, cop,
                          prezzo_elettrico_eur_kwh, eta_caldaia_pct, opex_annuo):
    """Matrice risparmio netto annuo (pompa di calore) al variare di prezzo gas e ore/anno.

    Per ogni cella: risparmio netto PdC - OPEX.
    """
    if not prezzi_gas_list or not ore_list:
        raise ValueError("prezzi_gas_list e ore_list non possono essere vuoti")
    righe = []
    for pg in prezzi_gas_list:
        for ore in ore_list:
            r = wh254_pompa_calore(calore_scarico_kw, cop, ore,
                                   prezzo_elettrico_eur_kwh, pg, eta_caldaia_pct)
            righe.append({"prezzo_gas_eur_kwh": float(pg),
                          "ore_anno": float(ore),
                          "risparmio_netto_annuo_eur": round(r["risparmio_netto_eur"] - float(opex_annuo), 2)})
    return righe


def _cg255_num(x, nome):
    """Valida uno scalare numerico: no bool, no NaN/inf."""
    import math
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def cg255_parsa_prelievi(testo):
    """Parsa l'area di testo: un valore Smc/giorno per riga, righe vuote ignorate.

    Accetta la virgola come separatore decimale. Riga non numerica -> ValueError
    con il numero di riga; testo vuoto -> ValueError.
    """
    if testo is None or not str(testo).strip():
        raise ValueError("nessun dato inserito")
    vals = []
    for i, riga in enumerate(str(testo).strip().splitlines(), start=1):
        riga = riga.strip().replace(",", ".")
        if not riga:
            continue
        try:
            vals.append(float(riga))
        except ValueError:
            raise ValueError(f"riga {i}: '{riga}' non e' un numero")
    if not vals:
        raise ValueError("nessun valore valido trovato")
    return vals


def cg255_statistiche_prelievi(prelievi_smc_g):
    """Statistiche dei prelievi giornalieri (Smc/giorno): max, p95, media, giorni.

    p95 = percentile 95 con metodo nearest-rank. Lista vuota o negativi -> ValueError.
    """
    if not prelievi_smc_g:
        raise ValueError("prelievi_smc_g: lista vuota")
    vals = [_cg255_num(v, f"prelievi_smc_g[{i}]") for i, v in enumerate(prelievi_smc_g)]
    if any(v < 0 for v in vals):
        raise ValueError("prelievi_smc_g: valori negativi non ammessi")
    s = sorted(vals)
    n = len(s)
    p95 = s[min(n - 1, int(0.95 * n))]
    return {"giorni": n,
            "prelievo_max_smc_g": round(max(vals), 2),
            "prelievo_p95_smc_g": round(p95, 2),
            "prelievo_medio_smc_g": round(sum(vals) / n, 2)}


def cg255_costo_capacita(capacita_smc_g, tariffa_eur_smc_g_anno, giorni_fatturazione=365.0):
    """Costo annuo della capacita' giornaliera prenotata (Smc/giorno).

    costo = capacita x tariffa annua x giorni_fatturazione/365.
    """
    c = _cg255_num(capacita_smc_g, "capacita_smc_g")
    t = _cg255_num(tariffa_eur_smc_g_anno, "tariffa_eur_smc_g_anno")
    g = _cg255_num(giorni_fatturazione, "giorni_fatturazione")
    if c < 0:
        raise ValueError("capacita_smc_g: non puo' essere negativa")
    if t < 0:
        raise ValueError("tariffa_eur_smc_g_anno: non puo' essere negativa")
    if not 0 < g <= 366:
        raise ValueError("giorni_fatturazione: deve stare in (0, 366]")
    return {"costo_capacita_eur_anno": round(c * t * g / 365.0, 2)}


def cg255_sforamenti(prelievi_smc_g, capacita_smc_g):
    """Sforamenti: giorni sopra capacita', volume eccedente totale, sforamento max."""
    if not prelievi_smc_g:
        raise ValueError("prelievi_smc_g: lista vuota")
    vals = [_cg255_num(v, f"prelievi_smc_g[{i}]") for i, v in enumerate(prelievi_smc_g)]
    c = _cg255_num(capacita_smc_g, "capacita_smc_g")
    if c < 0:
        raise ValueError("capacita_smc_g: non puo' essere negativa")
    eccedenze = [max(0.0, v - c) for v in vals]
    giorni = sum(1 for e in eccedenze if e > 0)
    return {"giorni_sforamento": giorni,
            "volume_eccedente_smc": round(sum(eccedenze), 2),
            "sforamento_max_smc_g": round(max(eccedenze), 2),
            "quota_giorni_sforamento_pct": round(giorni / len(vals) * 100.0, 2)}


def cg255_costo_totale(prelievi_smc_g, capacita_smc_g, tariffa_eur_smc_g_anno,
                      penale_eur_smc, giorni_fatturazione=365.0):
    """Costo totale annuo = corrispettivo di capacita' + penali di sforamento.

    penali = volume eccedente (Smc) x penale unitaria (€/Smc).
    """
    pen = _cg255_num(penale_eur_smc, "penale_eur_smc")
    if pen < 0:
        raise ValueError("penale_eur_smc: non puo' essere negativa")
    cap = cg255_costo_capacita(capacita_smc_g, tariffa_eur_smc_g_anno, giorni_fatturazione)
    sfo = cg255_sforamenti(prelievi_smc_g, capacita_smc_g)
    penali = sfo["volume_eccedente_smc"] * pen
    return {"costo_capacita_eur_anno": cap["costo_capacita_eur_anno"],
            "giorni_sforamento": sfo["giorni_sforamento"],
            "volume_eccedente_smc": sfo["volume_eccedente_smc"],
            "penali_eur_anno": round(penali, 2),
            "costo_totale_eur_anno": round(cap["costo_capacita_eur_anno"] + penali, 2)}


def cg255_capacita_ottimale(prelievi_smc_g, tariffa_eur_smc_g_anno, penale_eur_smc,
                           n_punti=50, giorni_fatturazione=365.0):
    """Capacita' che minimizza il costo totale annuo.

    Scorre n_punti capacita' candidate dal 50-esimo percentile al massimo dei
    prelievi: il costo totale (capacita' crescente + penali decrescenti) e'
    convesso a tratti, quindi il primo minimo trovato e' l'ottimo.
    Penale 0 -> ottimo = p50 (mai pagare capacita' inutile).
    """
    if not prelievi_smc_g:
        raise ValueError("prelievi_smc_g: lista vuota")
    n_p = int(n_punti)
    if n_p < 2:
        raise ValueError("n_punti: almeno 2")
    vals = sorted(_cg255_num(v, "prelievi_smc_g") for v in prelievi_smc_g)
    lo, hi = vals[len(vals) // 2], vals[-1]
    if hi <= 0:
        return {"capacita_ottimale_smc_g": 0.0,
                "costo_capacita_eur_anno": 0.0,
                "penali_eur_anno": 0.0,
                "costo_totale_eur_anno": 0.0,
                "giorni_sforamento": 0,
                "volume_eccedente_smc": 0.0}
    best = None
    for i in range(n_p):
        cand = lo + (hi - lo) * i / (n_p - 1)
        tot = cg255_costo_totale(prelievi_smc_g, cand, tariffa_eur_smc_g_anno,
                                penale_eur_smc, giorni_fatturazione)
        if best is None or tot["costo_totale_eur_anno"] < best["costo_totale_eur_anno"]:
            best = dict(tot)
            best["capacita_ottimale_smc_g"] = round(cand, 2)
    return best


def cg255_curva_costo(prelievi_smc_g, capacita_list, tariffa_eur_smc_g_anno,
                     penale_eur_smc, giorni_fatturazione=365.0):
    """Righe capacita' -> costi (per grafico e export): una riga per capacita' candidata."""
    if not capacita_list:
        raise ValueError("capacita_list: non puo' essere vuota")
    righe = []
    for c in capacita_list:
        tot = cg255_costo_totale(prelievi_smc_g, float(c), tariffa_eur_smc_g_anno,
                                penale_eur_smc, giorni_fatturazione)
        righe.append({"capacita_smc_g": round(float(c), 2),
                      "costo_capacita_eur_anno": tot["costo_capacita_eur_anno"],
                      "penali_eur_anno": tot["penali_eur_anno"],
                      "costo_totale_eur_anno": tot["costo_totale_eur_anno"],
                      "giorni_sforamento": tot["giorni_sforamento"]})
    return righe



