            {"nome": "CCGT extra", "capacita_mw": 150.0, "heat_rate": 1.95, "vom_eur_mwh": 3.0, "co2_eur_mwh": 15.0,
             "costo_avvio_eur_mw": 45.0, "costo_fisso_eur_mw_h": 2.0, "min_up": 4, "min_down": 3},
