            render_kpi("Ore equiv. full-load", f"{res_pf['ore_equivalenti']:,.0f}", kpf6)
            render_kpi("Migliore unita'", f"{res_pf['migliore']}", kpf7)
            render_kpi("Capacita' totale (MW)", f"{res_pf['cap_tot_mw']:,.0f}", kpf8)
